INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1d613c4-9271-47b2-aa88-bfae83cca797', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur?', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b757bae8a9c93cd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71178671-79fe-4183-befd-a37279018153', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet?', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '9735dcac8451c1a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de5a483e-4814-49ea-9302-f3c6d2fe630f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model?', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '8b77cffd91719a44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a418a3be-277a-41bd-a7a7-b6cba17fbaf6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes?', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '8041e675bc054421_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1760e6a-93b7-4c69-a8ce-37100281d331', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network?', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'e296a47a40002234_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd026c56-0cf5-41b6-9fc9-d1852ad6ea66', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device?', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'a5c5193818cb4a2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bca8bfd9-11f3-4c16-b8f3-2d2a718b4724', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed?', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6918f600c9f3177c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61660e66-2b6c-4b21-ac23-1da400d4dea8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device?', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ec4687053fca239c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3edf8e4-eaf8-4b0a-905a-6063be1947b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device?', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '083684daef023c7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cba1740-f3e2-46c1-8af8-f378598e512e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos?', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '87265c0f49b499f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c842f0fb-9d10-4ddd-b3ea-cb9440c2eb28', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI?', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4383ac45ee4293ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('550da914-cff5-48a4-801e-76186341aea0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI?', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '248ec996a716c835_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd849772-77b2-4b01-8cf1-06e40424899f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device?', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ea35ad6638d6a1e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cce3c06b-0a25-468d-a9e6-7d4eab27f54d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI?', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'bd983995fdc565cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff40eb68-67da-4030-9965-9d3e85a73c92', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device?', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3370425ac83bff37_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fa7b7e9-0608-4f67-a263-ad00690ec63f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device?', '[{"id": "A", "text": "set router-name R9", "is_correct": false}, {"id": "B", "text": "set system name R9", "is_correct": false}, {"id": "C", "text": "set system host-name R9", "is_correct": true}, {"id": "D", "text": "set hostname R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3891a51c596f0a74_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d23dfe8d-cae7-4ab7-aa6d-f12d308ce844', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos?', '[{"id": "A", "text": "set authentication user juniper password", "is_correct": false}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '494255bca8449819_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38bf4d53-787d-44d1-ad16-9b5af50a5805', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface?', '[{"id": "A", "text": "set ip address 10.221.59.1/24 interface ge-2/1/2", "is_correct": false}, {"id": "B", "text": "configure interface ge-2/1/2 ip 10.221.59.1/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/1/2 unit 0 family inet address 10.221.59.1/24", "is_correct": true}, {"id": "D", "text": "set interface ge-2/1/2 ip address 10.221.59.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '23dad62a7a1b22d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58575866-bb91-4462-9480-21396d887be2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos?', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7a0a38b41ffe3abc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbedb9f2-db5f-4f20-9c8b-c442f9716e4b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device?', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '9b4f0399c3748ddb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fc0706a-9d59-4d69-866e-3be2e2a0d501', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device?', '[{"id": "A", "text": "show interface xe-0/0/0 monitor", "is_correct": false}, {"id": "B", "text": "tail interface xe-0/0/0", "is_correct": false}, {"id": "C", "text": "watch interface xe-0/0/0", "is_correct": false}, {"id": "D", "text": "monitor interface xe-0/0/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '566a51fe83e689ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1b136fa-6e2e-4147-8860-4f3dc014661d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS?', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b27c66b56e6d4c3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea88b65f-209b-422c-bfdd-6fe45b0f3a6b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device?', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6e25ba6eb653406e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('655fbad9-0b84-40f8-8bf8-1d8fbb5ce9b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos?', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'c5d8c07e82de87da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75d4546f-7374-4bd3-ba4a-84f7f5a73b7f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos?', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2f536f7b059f8bde_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50057253-e784-4695-b563-b52f55d2173a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.52.124.0/24 via next-hop 10.69.160.1 on Junos?', '[{"id": "A", "text": "set ip route 192.182.217.0 255.137.163.0 10.69.160.1", "is_correct": false}, {"id": "B", "text": "set static route 192.52.124.0/24 gateway 10.69.160.1", "is_correct": false}, {"id": "C", "text": "set route 192.52.124.0/24 next-hop 10.69.160.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.52.124.0/24 next-hop 10.69.160.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3b0324f2832af8b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8b4cf61-d319-40d6-8a81-42afee9b029f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos?', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '1d843aca33e12053_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2671500-f7d1-4686-aaf5-e67ea0e86dc4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies?', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'fe185921d4389984_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfb6e576-209d-4c71-a540-0c16393b5fb8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos?', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'fd1ff974068c5b16_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27acfdc2-dc64-40a8-98d2-2a0c197417f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device?', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1f4f66003ff9146f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('533f4b84-fc2d-4457-a34d-62c8ad144f1a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 2).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1fa6921ef692510c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e29562c8-5be3-43a3-bfad-03feb01ff99d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 2).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'a4a0409cc02e7662_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5704807f-26e8-4125-b25e-dd0c91838c52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 2).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'c23904855b5875ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('479b5fe2-58a3-4a5d-8f74-bfd11550a7a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 2).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '8a96d03a729b2d1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02f8675d-9076-4eeb-81f4-71a64958e72e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 2).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '2ed5cba2cf2829e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fc087de-bc8e-4d35-b910-ff44d58f0986', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 2).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'e3226574a7ced5e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dae9966-4464-4281-8663-a1e7e72d5723', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 2).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5099f69d9e71121a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a321fb82-d829-4ea7-8346-8ed2c1237c95', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 2).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c876582645b6541f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8fc4552-bdca-4007-88ee-d2df78df9bab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 2).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'edec8d0b066e24e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34f91b39-c8bd-41ab-84fd-7bd6f75d5bbc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 2).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e4b7c8ea99c5874d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48e0bf07-3ac3-4bef-a1a5-7c4868ca1923', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 2).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ec370450cc2862df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a404dc0-6b49-4445-bde6-8403f4566cc0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 2).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a9d1e77d1e033f55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67ddfd2c-0888-4243-92f1-b252900c44b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 2).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '5541dafeaca103f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b816799-bfa7-4782-afaf-c2dd35bc1f05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 2).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '93cb98150670c1c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5d37304-1aa1-411f-a536-2f500919c8a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 2).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '268d35596b1bdf4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('515e8a1f-4f5d-4d7d-8990-54c134f5ef13', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 2).', '[{"id": "A", "text": "set system name R4", "is_correct": false}, {"id": "B", "text": "set system host-name R4", "is_correct": true}, {"id": "C", "text": "set hostname R4", "is_correct": false}, {"id": "D", "text": "set router-name R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'cd039cd4923daa23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdfd013f-895c-466e-9042-47000575762d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 2).', '[{"id": "A", "text": "set user monitor password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd52c0688a8666b6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('152c6b7f-959f-4c7b-8720-63cb1a8f337d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 2).', '[{"id": "A", "text": "set interface ge-1/0/2 ip address 10.122.160.5/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.122.160.5/24 interface ge-1/0/2", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/0/2 unit 0 family inet address 10.122.160.5/24", "is_correct": true}, {"id": "D", "text": "configure interface ge-1/0/2 ip 10.122.160.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '49323b4c06dad503_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c777100a-b3ce-46a3-961b-b64c3bb73605', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 2).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4d17a7031183d1f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebe1563f-9cf6-47b2-87d7-eba9acbb5f24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 2).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '70948ac9aa9198de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de7c93f0-a8dc-42ec-8c96-b1bdda4cf21b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 2).', '[{"id": "A", "text": "watch interface ge-0/1/3", "is_correct": false}, {"id": "B", "text": "tail interface ge-0/1/3", "is_correct": false}, {"id": "C", "text": "show interface ge-0/1/3 monitor", "is_correct": false}, {"id": "D", "text": "monitor interface ge-0/1/3", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b456f5f136bf40c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98374b01-5643-471b-8727-56e0101cb824', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 2).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '845f9428243a93b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2f750a5-6b83-4ac4-a0a4-e54ea7f5b35c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 2).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c68e695579fe5041_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7c5f906-cb32-4023-8279-cc4189ab34dc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 2).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'a651998bc63e968c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eacc0cab-2e85-4bab-aa52-4f28c485f98e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 2).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f0f76a395de799a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('967551d6-4472-4443-9869-f6ebd2cb510b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.26.238.0/24 via next-hop 10.104.37.254 on Junos (variant 2).', '[{"id": "A", "text": "set routing-options static route 192.26.238.0/24 next-hop 10.104.37.254", "is_correct": true}, {"id": "B", "text": "set static route 192.26.238.0/24 gateway 10.104.37.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.236.83.0 255.252.100.0 10.104.37.254", "is_correct": false}, {"id": "D", "text": "set route 192.26.238.0/24 next-hop 10.104.37.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '236919cab797ef08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fed1c43-12a2-4573-859a-3ebf8f58345a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 2).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '140ed70956ef113b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83fef60d-4d29-47c9-bce6-1043c46d4895', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 2).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '79cc4a8a1a8a2b21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dff931cc-9573-4887-8152-5894d8354730', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 2).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '3357c62686b6854c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb719689-f496-42f3-8b90-5e432511289d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 2).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '061ea22ad7c4bd7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9c703cd-2d49-433d-bda9-a735f48747ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 3).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '3f9f3647b5b820b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf73aafa-98fe-418d-ae3a-9f0d92330ee4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 3).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '402717814cbfc399_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('471d6899-1603-4b16-92b6-883f3dfdbe37', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 3).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '4beb8719b1883bc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4b413a1-eaa1-43b1-9dda-d09a875aec30', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 3).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '5889fe50883dc34c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15e59583-81c2-4062-a52e-92ad261a8f6f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 3).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'cba7398b86bbebc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97fcc6b5-5e98-4d0a-9815-06492a5e042b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 3).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'febca4ed2d715260_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a397be4d-c51c-4914-960a-ea6a38fc9705', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 3).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '253f22a78377cc03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54369047-b5f4-46c4-89aa-99375c581d8f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 3).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fd725ea004e8faa1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('397d2616-98da-40d2-ba44-150ce36e140c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 3).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e117292d72134cc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b074c71-8f15-487b-b59d-5a72a443e8c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 3).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '88700605f43a6b0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69d96eb2-88ca-4d14-bdbe-5833f7154f69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 3).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '359131bda27b6e93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8912c1ad-854e-4aa9-8996-70e5680a1410', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 3).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '336610aa242a43cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77d56a98-3e6c-4c66-b576-39115cc94533', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 3).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ec5b9cc564afcf2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('338aff0d-9047-4cb2-8a69-bd819040135b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 3).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '9f0fe7045c2a98f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8051fba-a371-4fad-b5eb-0f255364fcad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 3).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '32e049b12a9e700c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00a481fa-a010-4856-970b-dd1ea7f09d06', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 3).', '[{"id": "A", "text": "set hostname R4", "is_correct": false}, {"id": "B", "text": "set system name R4", "is_correct": false}, {"id": "C", "text": "set router-name R4", "is_correct": false}, {"id": "D", "text": "set system host-name R4", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '509d923e0db67971_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abec36c5-a7f0-42a4-8bb4-21a642f3b9e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 3).', '[{"id": "A", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '66ea1ca59d5ac770_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8f437b2-9c0b-4249-a7f6-a44b78670060', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 3).', '[{"id": "A", "text": "set ip address 10.236.8.5/24 interface ge-2/0/1", "is_correct": false}, {"id": "B", "text": "configure interface ge-2/0/1 ip 10.236.8.5/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/0/1 unit 0 family inet address 10.236.8.5/24", "is_correct": true}, {"id": "D", "text": "set interface ge-2/0/1 ip address 10.236.8.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'b3f1149823e28370_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('170516dd-27cd-4d71-aab9-d97b7e3e88f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 3).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '91f4a05af6ee0e75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70ed7ff5-1861-485f-9a2b-cb5a16c85531', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 3).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7430783d022795f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdc8dd52-b617-4494-a638-022cbba17560', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 3).', '[{"id": "A", "text": "watch interface xe-1/0/1", "is_correct": false}, {"id": "B", "text": "tail interface xe-1/0/1", "is_correct": false}, {"id": "C", "text": "show interface xe-1/0/1 monitor", "is_correct": false}, {"id": "D", "text": "monitor interface xe-1/0/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7af31a76d5a83281_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb57f466-0ef0-4901-96d6-65da5bcea50b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 3).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f1a80a0157840fe9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33cf56ba-43e3-4561-aee6-10af6a892b2b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 3).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '18cbd5530fb21ad6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b98c73b6-bb90-43a6-8c0b-eaa9ebfd39b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 3).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '4dea8b449d24564c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef9c16d9-2a49-4a70-b8a4-58b2ef4e7b24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 3).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2a996cf7bbdcb811_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd8a8f86-55a4-486a-b2ff-73033192591a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.143.115.0/24 via next-hop 10.130.78.1 on Junos (variant 3).', '[{"id": "A", "text": "set route 192.143.115.0/24 next-hop 10.130.78.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.199.66.0 255.49.41.0 10.130.78.1", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.143.115.0/24 next-hop 10.130.78.1", "is_correct": true}, {"id": "D", "text": "set static route 192.143.115.0/24 gateway 10.130.78.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e1b1fb49c5ada3fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc4ac98b-2423-4294-b390-1b6c69b1fb18', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 3).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '867d4611f8ff92ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('077eaf85-586b-4f1f-9f45-7c338dc2b465', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 3).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '5012f39697276668_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15218429-967f-4d9d-abea-da66ae93bfea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 3).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b3553e9bb7f3a96e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e763b8fb-fd90-451b-af65-a8ecd5b5d10f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 3).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f7a1e5b841e3934b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4dad2ad-ca0a-42f2-944d-08f52655f049', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 4).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'cd1d25c55c76ff45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5a205fb-f2bb-4548-ba5f-f8874113bcc9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 4).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'f441cebb419c8b1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ff2e2a1-b179-4590-a530-49a3b559f1be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 4).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'ab677b0f6d70ba31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('375a0de7-bb33-49b4-82f9-71513625f523', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 4).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '3bff5f1bd16a8830_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c94bb316-647a-4ee7-9a30-9200e74df069', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 4).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '966df94076b3e40c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('197a3198-d6d1-4542-9c72-b218d3c13d61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 4).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '87e83fa94318636c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a853bdd6-d438-4c78-a853-0af807d77c12', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 4).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0f15b1bab38ac633_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6056db16-bae5-4439-bb2e-62cf2e82bc6f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 4).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd6585b78c892b408_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('593bf607-2aaa-48d4-9e31-c2f1806970c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 4).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8cb616d4f6284adf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42244e12-eed2-45a5-b39e-971f83728a1a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 4).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '325f222f3e8ef552_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4195dcea-2cc6-4d4c-b290-a873259a1c84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 4).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f7c52eb2b04b65a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3eb36807-a914-46f3-ae31-39f5406907d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 4).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8052915a6ed9afa2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('791a5829-5daf-41dc-8511-b2ddc36fe2c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 4).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'fd3cb21bdc862fce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54f26e8a-f025-4ac3-bc9c-1e83aa7be939', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 4).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a1ad008b9cbf0bdc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('883b8185-d107-4bdc-b53f-42fedb92b559', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 4).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '241e8b109c463da8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04c12172-a811-449b-af67-b4501e671d82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 4).', '[{"id": "A", "text": "set router-name R6", "is_correct": false}, {"id": "B", "text": "set system host-name R6", "is_correct": true}, {"id": "C", "text": "set system name R6", "is_correct": false}, {"id": "D", "text": "set hostname R6", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9ab75767de8fcde9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d063aec9-5266-4a1f-b070-3f5cf6cd69b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 4).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd9cd3fcc03770364_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e86a585-84e5-4dae-b762-9b4743d83a20', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 4).', '[{"id": "A", "text": "set interfaces ge-1/0/3 unit 0 family inet address 10.51.67.1/24", "is_correct": true}, {"id": "B", "text": "set ip address 10.51.67.1/24 interface ge-1/0/3", "is_correct": false}, {"id": "C", "text": "set interface ge-1/0/3 ip address 10.51.67.1/24", "is_correct": false}, {"id": "D", "text": "configure interface ge-1/0/3 ip 10.51.67.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '7c835cfd0d637900_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fcff3b1-8d1f-4244-9003-acc403840a2b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 4).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3303571384a2461f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8b80801-6bfa-4ca7-831b-40f82c3ab1a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 4).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '395b0148ddca6b4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52db556d-4c2d-4f80-aa89-8f31671c7c0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 4).', '[{"id": "A", "text": "tail interface xe-0/1/0", "is_correct": false}, {"id": "B", "text": "show interface xe-0/1/0 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface xe-0/1/0", "is_correct": true}, {"id": "D", "text": "watch interface xe-0/1/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ae287f308abf76bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('002c6648-f830-46f9-936a-dc7c13071b85', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 4).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c6556013299711a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b2616f6-2c96-4dc5-8318-0921ff5db791', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 4).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3e480bd5a021d00a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3875c4a-018b-4e12-941b-aab534be49c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 4).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '28086f573e0cdd1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96cc4415-0ff9-45c9-bfb5-477c7164e103', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 4).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e2a1f773df5ed110_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f9ae806-0784-4705-a206-e1b92f6f720e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.2.20.0/24 via next-hop 10.56.252.5 on Junos (variant 4).', '[{"id": "A", "text": "set ip route 192.68.58.0 255.42.44.0 10.56.252.5", "is_correct": false}, {"id": "B", "text": "set static route 192.2.20.0/24 gateway 10.56.252.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.2.20.0/24 next-hop 10.56.252.5", "is_correct": true}, {"id": "D", "text": "set route 192.2.20.0/24 next-hop 10.56.252.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'cbd1abf7815d7f61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31931d52-8807-42d2-8234-7b1933ead077', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 4).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'ffdee47edf811409_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fad65340-7952-439e-ac2e-52762ca41da4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 4).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '5eba56171b7284b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a944dde-e2a9-426e-9b57-77590106947e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 4).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c5a7db283d8d0106_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a43e99e-4912-41b8-b89e-e5f68e411086', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 4).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '3d328626a2efe3af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea0c9925-081e-4cb7-82b5-15aa65911695', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 5).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b30a49bd1307392e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8ba6476-40bc-482d-8de6-31bd9faea3b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 5).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '6406bbca44fc8057_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37027bc2-c9db-4d5e-9ef6-3f35e5c7be9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 5).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'b0c40e69ea21ca99_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04c2323e-e1cc-4e95-a2cc-50c08568e2d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 5).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'a5fad9fd931d0535_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1805625-959d-42b6-a9d9-7b8dc7f87850', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 5).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '2577474771ea3881_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed87bb47-bd7a-4ed6-b18d-233fded500b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 5).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'a99578f3ee9a0241_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40e58cc4-0497-4e80-93a0-847417930002', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 5).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fc6c35a4f7552771_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba8eb29a-605c-43cf-93cd-4cc7b6df8301', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 5).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '754c3788d14e6f6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('862e19b6-8926-4405-aa84-31f8c60d83c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 5).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a8fb1867d12c5d9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ae881e2-1013-4f35-83db-50c73f2d20ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 5).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'ddc1fed4012ee701_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a138d2d7-1b76-4c72-8404-693f9ded03c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 5).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '38f4de618c57e724_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa81df60-1326-4f3d-a652-917c47e40c32', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 5).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1ac0f28ae586eed8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('288000eb-f0a7-43a8-b1a3-bd862f26bde7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 5).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '91bd73057bd9f319_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d56ea3c2-4e41-47a9-aa97-793cb7549048', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 5).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '42534e2433fa545d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18d2893a-2df5-4322-961c-3bc300e8d4cf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 5).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'd596ab11a759e7c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('100a46b8-171a-4831-9dad-8119955cef0d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 5).', '[{"id": "A", "text": "set system host-name R1", "is_correct": true}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set router-name R1", "is_correct": false}, {"id": "D", "text": "set system name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'cbe0880daffd91b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2218a664-9c78-48ae-86a8-8035fd1d992a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 5).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user root password", "is_correct": false}, {"id": "D", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'cc98c998fbefeba1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d698f3d-2a59-4ed2-9d55-5e9d96f90821', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 5).', '[{"id": "A", "text": "set interfaces xe-2/0/3 unit 0 family inet address 10.47.33.5/24", "is_correct": true}, {"id": "B", "text": "configure interface xe-2/0/3 ip 10.47.33.5/24", "is_correct": false}, {"id": "C", "text": "set interface xe-2/0/3 ip address 10.47.33.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.47.33.5/24 interface xe-2/0/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'dc9ed580c7609bc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8dd3a6ea-d595-4132-95b3-de23f32d6a80', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 5).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4b09581d95cf0211_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e7adcc4-e729-4c6b-8ff5-0eb73034690c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 5).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'fbc9a0fe9d8099fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f12e194e-692c-43e4-a30e-fcfe17bf40c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 5).', '[{"id": "A", "text": "tail interface ge-3/1/2", "is_correct": false}, {"id": "B", "text": "show interface ge-3/1/2 monitor", "is_correct": false}, {"id": "C", "text": "watch interface ge-3/1/2", "is_correct": false}, {"id": "D", "text": "monitor interface ge-3/1/2", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2c83ec24d8e443b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4045425-e379-4915-847a-7cf241150342', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 5).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'db4d5cce83ac3d50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e46b8c1a-a18b-4d0e-bae8-935f4dc66661', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 5).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2e403fd58457821a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bac2c21-f47c-409d-91ef-c7ec05a33b77', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 5).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '758812db07e0f15a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f12ab06-8a1f-4fbf-9234-b0256fbde8c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 5).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5e1855f45f62a00c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd17b326-9dc7-4052-b2b3-7e17bff34e29', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.149.244.0/24 via next-hop 10.116.165.254 on Junos (variant 5).', '[{"id": "A", "text": "set route 192.149.244.0/24 next-hop 10.116.165.254", "is_correct": false}, {"id": "B", "text": "set ip route 192.171.245.0 255.175.180.0 10.116.165.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.149.244.0/24 next-hop 10.116.165.254", "is_correct": true}, {"id": "D", "text": "set static route 192.149.244.0/24 gateway 10.116.165.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '59f68f0619da4e15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa509bcf-a5dc-4b38-92e8-5126ebf4576e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 5).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'bdeb40cf1472d480_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f57eef23-92bd-4003-97ba-f4c5763e70c9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 5).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '6703e3e1f6be8e11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d10ffc67-7fb9-4b78-9b9f-6dbff337ae52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 5).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7bd10387e215fbbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70970924-c3b6-489c-87d5-f6e99776ad15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 5).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd94806a15a31ea0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e2bf86f-c0df-4c9c-b40d-482cd08c63fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 6).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '48b9f373d99f388f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a69942ec-59b3-4765-85cb-53260839d597', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 6).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'd6d68ab0d7baca75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0257a03c-513b-408e-9c15-e3a1c4773823', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 6).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '422285da0efa9980_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dec3f97-630a-4285-bc33-5a5c63328a8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 6).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'ba72272da6bddbf5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4806d4d9-3746-4871-8860-33c24dfd0235', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 6).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'b9b0f2484b2821b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11db146c-7dbc-4e92-88b3-2dd0037c7532', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 6).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '5ce42ba9113d00b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff4d2f6f-f9dd-46a3-8aba-6461f6c63cad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 6).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3ec29fc935213a58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82afdad2-329e-45cf-91f1-074fd79abd48', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 6).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f5a9e471891d6e6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8168b65e-a8bf-4a67-a95e-1bc9b2c00ddd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 6).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5bccc5e59eb10886_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c514bedb-676b-41be-bc11-8c3c81690ad4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 6).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'a1e139637ff42d0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83afae1e-c9b5-44ee-87d2-84e320dea943', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 6).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '5a430a65ec63d59f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('701d9a5c-a534-4580-a6dd-0ddd36210c78', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 6).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1f3b666498af249b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a49034e4-1b68-4b51-a6fe-e67b208a348a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 6).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a2d36e7db1b1ce24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('548eb11f-7aa0-4227-90cd-728c1357c698', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 6).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '5521c46dc252b91c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3de54bab-998e-4724-a71a-d275cf6f9366', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 6).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '559f57d77be00a6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7eeb990-6251-4317-a8da-913d2a974ecc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 6).', '[{"id": "A", "text": "set system name R7", "is_correct": false}, {"id": "B", "text": "set system host-name R7", "is_correct": true}, {"id": "C", "text": "set router-name R7", "is_correct": false}, {"id": "D", "text": "set hostname R7", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '604aa891d816404b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9107ff80-eabe-41a9-82b7-2d0251511670', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 6).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9ce4a6be6f2e4f21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14e4a285-0881-4bd8-ac77-740f10317c96', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 6).', '[{"id": "A", "text": "set interfaces ge-1/1/1 unit 0 family inet address 10.188.249.1/24", "is_correct": true}, {"id": "B", "text": "configure interface ge-1/1/1 ip 10.188.249.1/24", "is_correct": false}, {"id": "C", "text": "set interface ge-1/1/1 ip address 10.188.249.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.188.249.1/24 interface ge-1/1/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '967c639969e059e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a3c949d-b857-47fc-a1e2-4b6949bc94c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 6).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'c15ec04d86de119c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ba66e61-6664-45c4-a99b-3b652bd37fec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 6).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '21b91ed2866b4a0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7fc9083-f7a0-425e-bdf7-d50b21558bda', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 6).', '[{"id": "A", "text": "tail interface et-0/1/1", "is_correct": false}, {"id": "B", "text": "watch interface et-0/1/1", "is_correct": false}, {"id": "C", "text": "show interface et-0/1/1 monitor", "is_correct": false}, {"id": "D", "text": "monitor interface et-0/1/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7f8bbb215ef65d29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4176f81-1ed7-436a-8558-bd12542600da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 6).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '162e48478fcc30b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0278700e-0b21-41f4-8c67-86b57c486b93', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 6).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'bf3bd4779a7fa3d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac400247-1338-4bec-af53-2b56acd3e2dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 6).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '7fe7140066ca062f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a7fed04-b59b-448d-8f1f-47c11e31c496', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 6).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c8f4181cdcdb110a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eaa99076-d608-47be-a565-dce6aab0b88d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.9.225.0/24 via next-hop 10.249.59.5 on Junos (variant 6).', '[{"id": "A", "text": "set routing-options static route 192.9.225.0/24 next-hop 10.249.59.5", "is_correct": true}, {"id": "B", "text": "set route 192.9.225.0/24 next-hop 10.249.59.5", "is_correct": false}, {"id": "C", "text": "set ip route 192.16.204.0 255.83.113.0 10.249.59.5", "is_correct": false}, {"id": "D", "text": "set static route 192.9.225.0/24 gateway 10.249.59.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '43db14840fb697cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49c8e65e-e336-4495-90c5-0428ff259c29', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 6).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c490069d0955997f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99711fd3-1c82-463a-a8e8-3d7793e8f1ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 6).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '918f3c0b61d5e58f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('547c513a-03bc-49ae-a009-d8bd816e7cb3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 6).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f85ef6887a68a7fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9cc5075-fdb4-420a-a95f-2a92bd0174f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 6).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '36c7817a48f6f8c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb0fa7f7-5c84-4f66-a585-64237c98b38b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 7).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '37737d25975d8bf8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8836acc-8730-4618-9d7f-f9bcba99f10f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 7).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'eb9b5f7a4dc59ae0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b0cbf96-dbbf-4189-98cb-957215001e2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 7).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '0b21c48770a5f02f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8af111a-40ba-4fb9-b034-65d16488098d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 7).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'a4ba7bbf70866426_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68b762d7-0a5c-4b8a-8c48-49b82bdbc418', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 7).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'a4017e8399eb4620_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73e9ba7d-4a36-4ee8-bc82-fbfa9494f2f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 7).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '3296775eea07aae6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33ea6771-a758-4e93-8b61-cafdf66837b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 7).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f359ea4e2e7df0fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c82523c7-fd05-4a5b-aee5-e8baa0137660', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 7).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b7fcc39f575ffdbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c264f8e-0114-472f-8c38-7d7d5eeb29be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 7).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '79d9aeec8d916149_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77f2e317-975d-4aee-8ec5-9f96a9958c29', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 7).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'b81ce8a0616d527e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b893e1ab-40d0-4649-aabf-8b7588f80f4e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 7).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'aa6b65b717cb7ad9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6901d9ff-2371-423b-af22-6347241c0fda', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 7).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'bc38f1506dbbfd61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26a45790-1194-468f-9b40-8b2de450fbe9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 7).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'df224c3ed40cdab1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62f749c3-25fa-49f8-9245-0ff051e5fd7d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 7).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '524e5d4206329ceb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33e13567-4b4c-463c-ba77-321648227312', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 7).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8923efed75c03722_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8efa7271-c84b-4a25-9f5a-20aaa6deacea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 7).', '[{"id": "A", "text": "set router-name R5", "is_correct": false}, {"id": "B", "text": "set system name R5", "is_correct": false}, {"id": "C", "text": "set system host-name R5", "is_correct": true}, {"id": "D", "text": "set hostname R5", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'bc76aed2890e0644_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca583c71-18f1-416a-8f21-60e54b9454c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 7).', '[{"id": "A", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'cd931aa617472bab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('136c8d6a-3a21-46a1-99cc-af550c9d4367', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 7).', '[{"id": "A", "text": "configure interface et-0/1/3 ip 10.103.191.5/24", "is_correct": false}, {"id": "B", "text": "set interface et-0/1/3 ip address 10.103.191.5/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.103.191.5/24 interface et-0/1/3", "is_correct": false}, {"id": "D", "text": "set interfaces et-0/1/3 unit 0 family inet address 10.103.191.5/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '47a2519758cd192c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('088dec44-08c3-4142-a6ef-053802acf8b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 7).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '38949f48fd943101_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8854b0b-2f14-4213-b8f8-ea5fd1f02ebe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 7).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '64cd3afe7b68d8fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f52913b-7f6a-45a8-ba70-e29ecc147a08', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 7).', '[{"id": "A", "text": "monitor interface xe-3/1/2", "is_correct": true}, {"id": "B", "text": "show interface xe-3/1/2 monitor", "is_correct": false}, {"id": "C", "text": "tail interface xe-3/1/2", "is_correct": false}, {"id": "D", "text": "watch interface xe-3/1/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '772b854f8cd38bdd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95ed7247-4b1a-477d-b76e-a7574f82daa8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 7).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b60daf423f23db82_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f638e48b-d3c1-44e4-869b-2d6309ddab2b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 7).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3538b462378ec8d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a936634-905f-43c3-b1c2-e8b7c8f8f9d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 7).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'cdfa20ef25324ac9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9901b606-5697-4727-9550-9d128fcab9b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 7).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '4675244513450704_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('909c732b-442d-4428-a2d6-fb3ade8dc23f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.22.103.0/24 via next-hop 10.181.249.1 on Junos (variant 7).', '[{"id": "A", "text": "set ip route 192.3.2.0 255.214.102.0 10.181.249.1", "is_correct": false}, {"id": "B", "text": "set route 192.22.103.0/24 next-hop 10.181.249.1", "is_correct": false}, {"id": "C", "text": "set static route 192.22.103.0/24 gateway 10.181.249.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.22.103.0/24 next-hop 10.181.249.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '44606875104dbc93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('210d18c9-501f-4d2f-a02b-2729d19e0ad2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 7).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '8f0a3243ade0614c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('385acf46-ecdd-448c-9b4e-bcbbcd1c45af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 7).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f240c8b0b89a9575_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b09922a2-946a-405c-b411-81726ea83a05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 7).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0116691a096ad425_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e92f80e1-1ac2-4163-9c53-ee2796e7c337', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 7).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '04d2681d9b92aca7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50731be6-2955-4bac-9c47-ce883cbf6809', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 8).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'ec78b348afbb6f0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('522eb25c-64ee-476e-a278-d60f49486462', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 8).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'd59d21cfe354d747_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02592537-8d55-4947-a185-5763f4ec1420', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 8).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'e71e1fd689477811_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7058da27-aa0e-4205-95b2-e21db41a1738', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 8).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '3123f9276fcd22c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4133733-4790-43b2-81d8-be271e5d5dca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 8).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '091257a20130c6bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03aae76a-5856-45bd-a927-7328f72387df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 8).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '596380f492b70749_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7026a36c-3a47-449f-8a05-e5e1725f7913', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 8).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f44a52cffa79309b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb38bccc-2658-47ee-bd84-220e8d9d6d3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 8).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ca6aad5d8cf8ab60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ea9c320-2f6d-40d1-91ee-ebdbd27e56df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 8).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e8e157f0e593f1db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c596f34-ad32-4004-8acc-853a3d60375e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 8).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'f97110d233681c8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4cfabe2-bdb9-41c4-b508-4a800cc973b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 8).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '190eb080e7295577_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1e822e9-e07d-421d-b35e-6c4b17f0689d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 8).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a7647f5ab1508465_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('444440d8-bc37-42e8-a438-d67a500121fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 8).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b57be4eaeec69b0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0261c0b7-f08b-4abc-8ec9-8512130fc01a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 8).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '37adbdc1d6fffd71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10d42db4-baa6-477d-9226-c9e3cc7e88d7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 8).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6eacaf2e11626940_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebda93ba-386a-4fc6-bdd9-df5dfb6fdc83', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 8).', '[{"id": "A", "text": "set router-name R1", "is_correct": false}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set system host-name R1", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f19f3fd8257e376d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('389e3980-600b-422e-ac6e-bf17b447e4c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 8).', '[{"id": "A", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b96dd774c4c9dc38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26fbd701-6ddf-446f-980e-3b89d06def4c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 8).', '[{"id": "A", "text": "set interfaces xe-2/0/2 unit 0 family inet address 10.229.50.1/24", "is_correct": true}, {"id": "B", "text": "configure interface xe-2/0/2 ip 10.229.50.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.229.50.1/24 interface xe-2/0/2", "is_correct": false}, {"id": "D", "text": "set interface xe-2/0/2 ip address 10.229.50.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '1d2f1f7b832566d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f6f4af1-a92d-4d39-8d04-5100007eed61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 8).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '94126f83b162165a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('000b9b40-c7bd-4243-8981-e435e00e5d13', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 8).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'deff4095a19dc33d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebb7b74b-8630-479b-8315-a30bdea0b018', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 8).', '[{"id": "A", "text": "tail interface ge-0/0/0", "is_correct": false}, {"id": "B", "text": "monitor interface ge-0/0/0", "is_correct": true}, {"id": "C", "text": "watch interface ge-0/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-0/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '616b9816f9c3fd3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f687069a-39f5-4bae-aea4-9c24a8aeac27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 8).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c6a89f7a827acd75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6c9164a-0597-4f7d-9f40-1e5b8c005cbd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 8).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c4512008e81978da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2486f9ba-4ff8-4f2a-836a-e74a37d92eb0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 8).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '513f408b2b8edc11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09e23c88-6e16-44e4-9a49-0d59ebdbf8bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 8).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '950c4618f77703bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8193d3cf-74e1-48c5-b435-acc25e0bd7a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.133.168.0/24 via next-hop 10.154.48.1 on Junos (variant 8).', '[{"id": "A", "text": "set route 192.133.168.0/24 next-hop 10.154.48.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.130.90.0 255.219.99.0 10.154.48.1", "is_correct": false}, {"id": "C", "text": "set static route 192.133.168.0/24 gateway 10.154.48.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.133.168.0/24 next-hop 10.154.48.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '4ccd0da825e1e43e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53935f5e-3891-4c20-bc66-c0655e6673e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 8).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '6c42ec7755995643_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8828520f-3e22-49c4-8b1d-e381ee788be8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 8).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'e61aa357e500944d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6815d905-a274-4a14-b40e-c535c0cbef2c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 8).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '48ec6caac9c351b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f9b5249-f1ef-4d5a-9ebf-e74b2a522d6c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 8).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '923e1504fd4222f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35ac4d05-7a41-4ec7-b7b2-b4887ed69922', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 9).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '8e40d6348bcc829e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f12d664-4c24-4d9e-a8b7-7926dd29a9f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 9).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '3d3cd50e7d2c727a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43390bd0-9bf7-4aeb-9347-68a4f1422efa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 9).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'e75ccd07ad5928a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b51e4479-17bd-4e53-9471-43a56b8506f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 9).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '7b886a473310654e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7eaed8e8-03b4-4485-b66e-5af3ce747c94', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 9).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'd4a38a79f87eb9de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('082d830b-dd24-410d-b360-1d4861fd7c98', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 9).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b1dc582c5930b7ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7549f63e-5565-461f-bfd3-fe0dbd1ed895', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 9).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '96dbad256ad10a37_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b65955a-30a3-424a-9629-122614844254', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 9).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6ba8cd5e70bb23b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a511f622-9875-4aa4-ad27-2283c7bd4264', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 9).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f2c178593944eb92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64611dd0-3d5e-4798-905c-ca724ea5d4d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 9).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e9dd407a65d9cb03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8c92d8a-a932-4886-b23a-0a30f9b47e81', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 9).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '57a16349aa9f92cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc288dce-24de-4253-bdc9-9e41ce2f69d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 9).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '55ec5f29588038c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3591906-786b-421e-825b-1f03e9445e9c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 9).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7f54cf92a9ca967b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c4c1943-0286-4a61-a62c-d64c371ecaec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 9).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '95af15375a994de7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be3ea7b9-2b61-4784-a7ef-b4f955e81be9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 9).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6fd8a52aae6ad0aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a168c6fe-a4e8-4d2d-9f88-caef526eec5f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 9).', '[{"id": "A", "text": "set hostname R7", "is_correct": false}, {"id": "B", "text": "set system name R7", "is_correct": false}, {"id": "C", "text": "set system host-name R7", "is_correct": true}, {"id": "D", "text": "set router-name R7", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0d66f4e1f8bf7b72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a947e87c-bd74-4b21-9f64-4f4b096e31c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 9).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ef991f6dcec010c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8872db6-5765-4253-badf-2f1ba9e09ad0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 9).', '[{"id": "A", "text": "set interface ge-1/0/1 ip address 10.26.110.254/24", "is_correct": false}, {"id": "B", "text": "configure interface ge-1/0/1 ip 10.26.110.254/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/0/1 unit 0 family inet address 10.26.110.254/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.26.110.254/24 interface ge-1/0/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'c9ddb60c1e71747a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82615178-cada-42ea-b2f8-f64126497d14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 9).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3fd79900edc88868_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('070b56af-ded4-495a-8169-32608e157e57', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 9).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f53eac5a4da8e4fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02f5ffb2-be00-45f1-bcf1-c770238ed42a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 9).', '[{"id": "A", "text": "monitor interface xe-0/1/3", "is_correct": true}, {"id": "B", "text": "watch interface xe-0/1/3", "is_correct": false}, {"id": "C", "text": "show interface xe-0/1/3 monitor", "is_correct": false}, {"id": "D", "text": "tail interface xe-0/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '533c642557f5979c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('412d5961-c241-4182-a455-7cd6b67802c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 9).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '214e446055a15e5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0685fbdb-67d0-4bad-bb46-852caf0d6ae9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 9).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f044e3f5393c6fdd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e43fe16e-e744-4ef5-8bf3-639bd2c612df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 9).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '247632f39b8dd6c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a7137ee-6076-4cad-b904-07929987ff31', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 9).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '610b1eab81dba292_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('435b67de-eca9-41ce-995c-94438894cd36', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.105.56.0/24 via next-hop 10.69.139.1 on Junos (variant 9).', '[{"id": "A", "text": "set ip route 192.165.127.0 255.148.123.0 10.69.139.1", "is_correct": false}, {"id": "B", "text": "set route 192.105.56.0/24 next-hop 10.69.139.1", "is_correct": false}, {"id": "C", "text": "set static route 192.105.56.0/24 gateway 10.69.139.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.105.56.0/24 next-hop 10.69.139.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'fc7f3740849f6553_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4747494a-e9f9-4d01-a2f5-4a9dcb8261bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 9).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'a68ab5e1bec96068_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2353e41e-8379-418a-8d5c-7bfe03c2e487', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 9).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '1f337f020248ced4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef6f77f7-f208-4fd7-a18c-240d1f9ef05d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 9).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'dfd0dc82dbae45ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6286c31-eee9-4fa9-a1f3-072c00e44878', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 9).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '6d6ed59c18370913_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0a1e44e-cfd4-44c7-9896-3e9051c331e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 10).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '04170f3179d9cea8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22ee30ef-df5b-4e33-a435-4a3a290efaa9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 10).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '959c02fae753a7b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b3af470-7802-44e7-bcef-4b7951fe2ddb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 10).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'ad3d0c5d509ad0b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fe0c94e-ac93-433f-b5f1-70dcf49ef7be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 10).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'c16c250b7a0b7c72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ade36753-3a00-48da-aa0f-d6b9ad5bbef9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 10).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '15dd695d2f5b3b9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('644e81c8-e041-4c17-b5ae-2a8b027a2726', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 10).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '11be5c514a7b1376_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34637568-e3c5-4e15-8c6d-6d856eeaee04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 10).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b6083680cf015f25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09519313-4be6-4ead-a9d8-3f1911479d43', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 10).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd2c24e9755dbeda3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46ba95d6-d6e8-48ab-96aa-3af77cead3f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 10).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a361d5b57597c337_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fa8158f-53fc-49ee-b103-f9056a0ddab6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 10).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '367e9180343c4e29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60320736-52b1-4e2e-95ba-8de37a60053d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 10).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6d7299f4ccf91c0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3addadba-ebae-414c-aa34-12800ee07cd4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 10).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2b2198ba05029154_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fd54758-a63a-462f-86ee-8578928edb86', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 10).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f14ad967de447045_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd66e765-4186-43dd-96ae-5656582a33f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 10).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e68ab5a0bb937054_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57513539-4279-4486-83d6-9e96a55419cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 10).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e23c1dfefe18d09c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('493e8a75-877b-41b6-9f6b-7924c7c85fd3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 10).', '[{"id": "A", "text": "set system host-name R3", "is_correct": true}, {"id": "B", "text": "set hostname R3", "is_correct": false}, {"id": "C", "text": "set router-name R3", "is_correct": false}, {"id": "D", "text": "set system name R3", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9ac2ed13188185af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f43c9c6c-b068-4ff1-9790-b9ff62832a4a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 10).', '[{"id": "A", "text": "set user monitor password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user support plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ca103e0916059765_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dea1e7be-747d-4432-b182-cdaa562bdaa4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 10).', '[{"id": "A", "text": "set ip address 10.105.217.254/24 interface et-0/0/0", "is_correct": false}, {"id": "B", "text": "set interfaces et-0/0/0 unit 0 family inet address 10.105.217.254/24", "is_correct": true}, {"id": "C", "text": "configure interface et-0/0/0 ip 10.105.217.254/24", "is_correct": false}, {"id": "D", "text": "set interface et-0/0/0 ip address 10.105.217.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '89fd2558427ef751_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('118e5f1e-d7f1-4fd9-9413-f246bdd14aa1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 10).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '26346eb108c37bf5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10b43562-15ca-4148-ac08-bc30407fd7a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 10).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '906cb238bb604ca5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cc6768d-1a81-4ad0-81d7-98e363299b30', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 10).', '[{"id": "A", "text": "tail interface ge-2/1/2", "is_correct": false}, {"id": "B", "text": "monitor interface ge-2/1/2", "is_correct": true}, {"id": "C", "text": "show interface ge-2/1/2 monitor", "is_correct": false}, {"id": "D", "text": "watch interface ge-2/1/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2decd610f2ad294d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a821362-384f-4c99-8ea0-a37f6fd2583b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 10).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '0008b40df08cc9d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d2971ed-9126-4930-a225-26639bb82f9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 10).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '20e0dddc09dcd737_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29caaeaf-e570-4111-b3e5-25dbc879da67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 10).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'd30373a2b53bc4b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('097cc0c7-3d91-4805-8d5c-e98d1b1b693a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 10).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '0e86436ad7a98f5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff791d8d-ccc2-4f2e-beda-6e9973ee4fb3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.30.150.0/24 via next-hop 10.203.152.1 on Junos (variant 10).', '[{"id": "A", "text": "set ip route 192.81.144.0 255.172.227.0 10.203.152.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.30.150.0/24 next-hop 10.203.152.1", "is_correct": true}, {"id": "C", "text": "set static route 192.30.150.0/24 gateway 10.203.152.1", "is_correct": false}, {"id": "D", "text": "set route 192.30.150.0/24 next-hop 10.203.152.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '58d66ede0efd9ebd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b7f0cb7-16cf-482a-8a33-deec33c24155', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 10).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c3b3cbf0b87658c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe17c74e-a179-4237-9283-d104aa5b64db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 10).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'da19bdb89ce4aa1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40e30db1-bcdb-484e-8a96-881c69ecb563', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 10).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '58de885c7f3e40e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d283e621-6924-45b0-9321-41b48063efaf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 10).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '941ccdb83c5d4d39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8a910df-bec7-4bcd-9be3-1c4ad7d8969d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 11).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6061ab52cfef8a14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c4ae78f-a398-4990-8e1d-75fccd087c8d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 11).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '9780bcef1c0405ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a2f2f1e-d35c-453a-8707-50e1247c3781', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 11).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '34ebb8c38d86690d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3735344a-746d-4c8d-ac54-aea0d71da866', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 11).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'ffb8a34022a3262d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1157d61e-c7cb-4227-a99b-104241c14d5c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 11).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'cb3f0c995e276185_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eebf31cd-f9fd-4f47-a8c2-3a0fbfaa93af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 11).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '1bdf91a32e654143_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0489c26-c839-4b23-8513-ab798342eb57', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 11).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e58cf02ebcf75183_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('580e692c-3186-4bcd-97fb-6218e375e034', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 11).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9fee4b165e6b701b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ed5029f-279d-462f-a4f6-ad03cd9e4990', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 11).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '19e6c72281ebf1a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3f9fb68-7764-4783-af3b-04451775919a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 11).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '2d17c8252c275d43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f29b16d5-e719-4fc5-881c-eaf2f326fd12', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 11).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ad330ddde858c021_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26b15ddf-5d72-48cb-8df8-c925d38eb080', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 11).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c363a17950e14b35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e51e202e-62ec-496b-80de-2397664221f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 11).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1d4961fd1c056fe7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb5ce25d-4c8a-4eff-886d-fdcef771e0f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 11).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '31bea975922c2225_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9c1b626-30dd-4c85-9086-d0eb7be7962c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 11).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8c72e76a2b7f8229_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5492be27-7e56-4042-be9f-6bc51bb26343', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 11).', '[{"id": "A", "text": "set router-name R3", "is_correct": false}, {"id": "B", "text": "set system name R3", "is_correct": false}, {"id": "C", "text": "set hostname R3", "is_correct": false}, {"id": "D", "text": "set system host-name R3", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '497cc65e8c34d2c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd8227d3-f26c-48b0-bfac-6028d92dacd1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 11).', '[{"id": "A", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user root password", "is_correct": false}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '86cc7024660aa264_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4d15f11-542e-40db-93b6-637b4b6f8eae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 11).', '[{"id": "A", "text": "set ip address 10.60.69.5/24 interface ge-1/1/0", "is_correct": false}, {"id": "B", "text": "set interface ge-1/1/0 ip address 10.60.69.5/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/1/0 unit 0 family inet address 10.60.69.5/24", "is_correct": true}, {"id": "D", "text": "configure interface ge-1/1/0 ip 10.60.69.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '0a0439f2824abc53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41dcf682-86db-409e-983d-303b8dc277b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 11).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '24c4032764f9f358_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd3f2307-df36-4025-aaa3-5d31d2c0442b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 11).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '42b1435ba8c312be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0e2d543-8ebe-4c24-bf43-1adde734241e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 11).', '[{"id": "A", "text": "monitor interface et-1/1/3", "is_correct": true}, {"id": "B", "text": "watch interface et-1/1/3", "is_correct": false}, {"id": "C", "text": "show interface et-1/1/3 monitor", "is_correct": false}, {"id": "D", "text": "tail interface et-1/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ce2443d86c53ecbe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbba2776-7213-44bc-82a5-81b0baf68147', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 11).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7c855d2ad0d1e8dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4c4f80d-3f47-4602-bf0d-2fe047b6f3bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 11).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '03c3c33dcabac3be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a86be474-5ffa-4eca-a28e-1f941d6b17cd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 11).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '50e3ed3459886726_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('207027de-7efb-4d35-b70d-33eeb3027847', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 11).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'aa1198df8c04edae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52227b9a-fb5a-4115-a290-5a38a7fd0e3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.99.166.0/24 via next-hop 10.6.227.5 on Junos (variant 11).', '[{"id": "A", "text": "set ip route 192.134.195.0 255.67.140.0 10.6.227.5", "is_correct": false}, {"id": "B", "text": "set static route 192.99.166.0/24 gateway 10.6.227.5", "is_correct": false}, {"id": "C", "text": "set route 192.99.166.0/24 next-hop 10.6.227.5", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.99.166.0/24 next-hop 10.6.227.5", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6d3569595d45473b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a94e6d25-810c-4308-95a5-dadfb47ea15f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 11).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c7b7b955c59fda0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c87396c-08c1-4cd4-ad07-d7e0743cf52a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 11).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '1ecca8914e0995d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5443bdd-61bb-4ec5-b959-d4a7ddde46bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 11).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '3cccbbb7e0b66922_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3c34cc9-643e-4d8d-a5b7-ee1814e0bacb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 11).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '13730165acafb484_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e14593d-ed52-4d57-b081-b0bd477a3e77', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 12).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b8574606d34f7a65_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d344fac-e8c6-44b8-8133-e7b0924217fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 12).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'f9903de7c83cff54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5690ae7f-0d7d-429f-b5dd-b61956013781', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 12).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'bf6b6d0bf494ee53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f44e027a-0842-450d-bde4-9d73ee502e97', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 12).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'd557c541117b9838_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('114665ab-ef08-4c4a-bc80-7c0679d094db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 12).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '74a67be4d14ba844_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78db5b33-abc6-41ad-8b97-7ce76fc617f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 12).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'ed2a016243b6a877_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('433498ee-44b7-478e-b8e6-73508eb658e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 12).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'be4912863a89a3d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34be0546-6530-41e0-97a6-0d2567c02ec9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 12).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '489414d435365c0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85b10173-a41e-44d5-be3f-6c15795d74cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 12).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4aff42186e55def0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33a1e0a8-b229-4af8-bb5b-cd85f342a059', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 12).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '7f367efcacd99bc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2b09e49-c66d-4190-85b0-7eab00c0be41', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 12).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '977c96dab006db78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0605100-1614-4631-92a6-6bfb6e97f8f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 12).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'df1b86c3294d8998_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcb31fae-33c1-4808-9a4d-5a66126dedd9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 12).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4e9078bcc2c1f9a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36f4d6cb-f514-4054-9e7a-ecb2f751eb5a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 12).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '5cce2cb3fd740321_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('905c6494-ffed-420f-a79b-a9805efbfd9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 12).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '218e3bc940b9679c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd53d3a0-8236-4873-9b54-d4ff5ac7fb70', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 12).', '[{"id": "A", "text": "set system name R11", "is_correct": false}, {"id": "B", "text": "set hostname R11", "is_correct": false}, {"id": "C", "text": "set system host-name R11", "is_correct": true}, {"id": "D", "text": "set router-name R11", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'aef8565173c29767_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72e4f6e1-c894-417b-86d6-06b80899f377', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 12).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '0598087c6fd9f9e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a71d17fa-1784-40c5-80e4-8a236eabab9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 12).', '[{"id": "A", "text": "configure interface ge-2/0/2 ip 10.67.177.254/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/0/2 unit 0 family inet address 10.67.177.254/24", "is_correct": true}, {"id": "C", "text": "set interface ge-2/0/2 ip address 10.67.177.254/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.67.177.254/24 interface ge-2/0/2", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '4ac0c57893ba2226_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bdcbb06-2936-4fe0-b3d8-9c40941f7a92', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 12).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6f4418c96cf0a712_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b32751a3-69e2-4cac-aaaf-21d95e2798f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 12).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'aefcd8948437d966_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('535805f3-1465-4875-b46e-95c0bf1f448a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 12).', '[{"id": "A", "text": "show interface ge-3/1/0 monitor", "is_correct": false}, {"id": "B", "text": "watch interface ge-3/1/0", "is_correct": false}, {"id": "C", "text": "tail interface ge-3/1/0", "is_correct": false}, {"id": "D", "text": "monitor interface ge-3/1/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a49628f9681ff008_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a6f2b44-0a5e-49b2-b08e-b992e079ee3f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 12).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '39b048570202558c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fe2ba33-eae2-4581-bb65-9ad3751aef57', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 12).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd4068881ec41e0e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b848150-5e5c-40c1-8c36-b29254be3302', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 12).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '70cc54245e8479b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17854b5d-0eff-4b93-8ca7-6a0eaf7779bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 12).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ee379dcb5b90590c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ccc3cfd-a40a-4e72-8f7b-3b5f60f43f37', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.18.35.0/24 via next-hop 10.17.48.5 on Junos (variant 12).', '[{"id": "A", "text": "set ip route 192.117.56.0 255.46.236.0 10.17.48.5", "is_correct": false}, {"id": "B", "text": "set static route 192.18.35.0/24 gateway 10.17.48.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.18.35.0/24 next-hop 10.17.48.5", "is_correct": true}, {"id": "D", "text": "set route 192.18.35.0/24 next-hop 10.17.48.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2829f11fd263f792_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d77173e8-770a-4cb3-b430-2017c8f55a3b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 12).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'b749c7eaf9319a58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86e08169-5c04-4c51-a561-b2bcdb2abc34', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 12).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f90034e32f948a57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a33ce4e9-7607-4cdb-bcfb-17159ac322dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 12).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '116213d1c20e8ad1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c3a6983-9cb4-420f-961f-41f098c06d58', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 12).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a72f45a9167a6401_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4461e8e-7fb5-4fef-9c24-e30859d61069', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 13).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd533debc90c1db04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('311a46f3-5912-4d1b-bd2c-f825b287788a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 13).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'ca777cae9e64478a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7f42a1c-04e1-4349-957f-5bca3001dc95', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 13).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '2cd3f79fd1c81561_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51782a10-499b-4eb0-8aaf-3506871ea92d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 13).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '962222e60d43afe5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39076283-c02a-4d24-b202-bbe5ea1dc8d7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 13).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '030f071dd79d7ff0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48c813ec-f36d-4285-8ed0-44335659b4c7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 13).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'd192ec0d13449a90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd697c6d-e0fa-4d4c-b77f-4aef971a1546', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 13).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '05b536b71b6f666d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aeb52a54-9f07-4642-90dc-a518678be319', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 13).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '03a85ff05697c2e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d150b78-14d4-4a4e-9700-11e277554696', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 13).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fda7126141bede9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11a42d84-f748-436b-afad-0553f8b106b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 13).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '88b5be82672f7a3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b1dc3f5-0035-4f95-b288-fb859f74f77e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 13).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'eb494525219c1538_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f214d7f9-860b-4bb0-9539-d26841c7b855', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 13).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c401a11d798043d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4530d844-7686-4545-9388-f55f0c9e7022', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 13).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '70929ed536d6186a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7722088-d2ea-4c5f-ade3-64844feae97d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 13).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'd0a6ad9855e09280_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b59b9c39-4d1c-4c7f-90f3-ae68d5d98a5c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 13).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a8678d48b58ba1b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ed30743-70ee-4821-a783-549d5617c2ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 13).', '[{"id": "A", "text": "set router-name R2", "is_correct": false}, {"id": "B", "text": "set system name R2", "is_correct": false}, {"id": "C", "text": "set system host-name R2", "is_correct": true}, {"id": "D", "text": "set hostname R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '1a7ce4d85371c2ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27488b5e-aacc-431f-95b2-e625cf4a5bb9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 13).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user monitor class super-user support plain-text-password", "is_correct": true}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3eee8e65655e39c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5f4cecf-6ad0-4214-a136-f5e8e7f23790', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 13).', '[{"id": "A", "text": "set ip address 10.17.43.1/24 interface ge-2/1/0", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/0 unit 0 family inet address 10.17.43.1/24", "is_correct": true}, {"id": "C", "text": "configure interface ge-2/1/0 ip 10.17.43.1/24", "is_correct": false}, {"id": "D", "text": "set interface ge-2/1/0 ip address 10.17.43.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '77e137ff57f74207_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29496f2b-630b-4280-a178-6b89e399b35e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 13).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6a230823d7362d3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3ee3f90-9648-4b22-a1fc-dfe0cf800460', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 13).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3de534da1cfd1b64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61e8c168-9f15-49cb-aa48-21b8fb10398f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 13).', '[{"id": "A", "text": "show interface ge-2/1/1 monitor", "is_correct": false}, {"id": "B", "text": "monitor interface ge-2/1/1", "is_correct": true}, {"id": "C", "text": "watch interface ge-2/1/1", "is_correct": false}, {"id": "D", "text": "tail interface ge-2/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a4c5666e7a9886fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d19b28f-8ba8-4f72-9606-d252c283493c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 13).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '87c2f172ba588ca7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60cfa8be-b6b0-463e-826f-4e87bb4b61b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 13).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '48ea9013a8c4dd86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06d81544-1bbc-412f-9ca7-43d6b4a7534d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 13).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '74fe52005e21975c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3316e4e3-f232-4f1e-832c-c516cd1cf342', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 13).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '88a4249970b899d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4eb7abba-65dc-47dd-b45b-30117ecc9707', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.175.152.0/24 via next-hop 10.237.142.254 on Junos (variant 13).', '[{"id": "A", "text": "set static route 192.175.152.0/24 gateway 10.237.142.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.175.152.0/24 next-hop 10.237.142.254", "is_correct": true}, {"id": "C", "text": "set ip route 192.214.10.0 255.138.134.0 10.237.142.254", "is_correct": false}, {"id": "D", "text": "set route 192.175.152.0/24 next-hop 10.237.142.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3b3651b130dea857_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bf87e6d-1e7a-4dfb-81e3-deb6ffcb91cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 13).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '02f45156eb90505a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9912154-9aa5-4322-8914-a97c3ff62c46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 13).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '6664636cb112f572_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1613b7a4-2261-4042-bfbb-88c2238ffa5d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 13).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7e7554667a79937e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2c6a607-a98f-449a-8818-a4323ee78ce5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 13).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '315a9452430e43e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab22f558-7f71-4499-bb19-6025f39e1623', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 14).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '35d4e95318798305_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d9c0f0d-f7f9-4788-b0ff-3a21cfbf0cec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 14).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '1ed8f94ad859d27d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4738aea8-ca0b-4296-bf74-21144fdfbbab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 14).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'b0695a12a67c519f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68802d5b-b4cd-46c4-ba53-c84993e6bdb4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 14).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'd932d9ca628db8e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0cf0442b-fa76-4a41-aece-3c917e66df36', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 14).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '8b3f46e3016b6b5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8402128e-dc67-4033-97cb-852053d24e00', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 14).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '09c723838e5716d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f870767e-2956-4af1-8865-d07af024e942', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 14).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '063027b465fe1337_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36564721-9e42-42eb-a0fc-d420afdb14c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 14).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ad2a4013c199c412_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9ed3139-6490-4a78-aa1a-c90b898c9c1f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 14).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9a10f6cedbdf807a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1322639e-09fc-452a-b9e2-c1cfcf203a59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 14).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '288debc80293631b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c508738-5a96-41b4-a889-afc171fc85f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 14).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '51ddfa71cb555080_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65e39375-f7d5-4d9c-8e88-a583de4eea0f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 14).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'adf9efa250b469d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04a2b169-4367-447a-b19b-31453bfc76b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 14).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '878ad259a7a1e8f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7a82d6a-0745-4ceb-b404-ac56d22e9309', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 14).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1dad5ba70574950e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af1d2998-b01d-4b2d-9731-49f8a7584b68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 14).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9255fffcb056729c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56efe357-fe7c-426b-b776-e0f60cd3b05e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 14).', '[{"id": "A", "text": "set system host-name R2", "is_correct": true}, {"id": "B", "text": "set system name R2", "is_correct": false}, {"id": "C", "text": "set router-name R2", "is_correct": false}, {"id": "D", "text": "set hostname R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7e07c5f3bf9003aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c51a49b7-9f6e-4c32-9c3e-d254cfdbf89c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 14).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9827891fb3db59e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('163f3a53-206c-4c61-af98-1225ece975d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 14).', '[{"id": "A", "text": "set ip address 10.180.204.1/24 interface et-1/1/3", "is_correct": false}, {"id": "B", "text": "set interfaces et-1/1/3 unit 0 family inet address 10.180.204.1/24", "is_correct": true}, {"id": "C", "text": "set interface et-1/1/3 ip address 10.180.204.1/24", "is_correct": false}, {"id": "D", "text": "configure interface et-1/1/3 ip 10.180.204.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'ccc064fb97431f4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('621f5b3f-f8ab-4f16-a513-8c2707a3bfee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 14).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6fd274a5113df2eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed0e1f13-680b-4165-9e4a-8e3a768244ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 14).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd5225bee83d22991_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7b73c0e-e714-4d1d-888f-a338816ac769', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 14).', '[{"id": "A", "text": "monitor interface ge-0/1/1", "is_correct": true}, {"id": "B", "text": "watch interface ge-0/1/1", "is_correct": false}, {"id": "C", "text": "show interface ge-0/1/1 monitor", "is_correct": false}, {"id": "D", "text": "tail interface ge-0/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd29a9efa255c1b12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7db683b4-b322-4eb3-b91f-fa43941e8216', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 14).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '31c668521433f25d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1dd7506d-cd69-4041-b80f-a979970eae1b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 14).', '[{"id": "A", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '28315ed00db6d394_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('895dc9c7-852e-4660-ab66-6a9b5a2db655', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 14).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'fc29fc7fd2579027_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cba0d1c-8763-4d63-a42f-484a15649afb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 14).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2d1d7f27f6625445_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('885c0b1f-7729-470f-84a0-7e335280817d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.21.226.0/24 via next-hop 10.61.1.5 on Junos (variant 14).', '[{"id": "A", "text": "set static route 192.21.226.0/24 gateway 10.61.1.5", "is_correct": false}, {"id": "B", "text": "set route 192.21.226.0/24 next-hop 10.61.1.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.21.226.0/24 next-hop 10.61.1.5", "is_correct": true}, {"id": "D", "text": "set ip route 192.38.35.0 255.35.85.0 10.61.1.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '07c894e5888c2668_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('391e4f1a-102b-43f7-961b-d1d332f24cb3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 14).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'ad9e69318d7fb5d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b24f908-c97e-4f69-ae24-87476005f4dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 14).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a5e76d5eb4048300_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f5af07b-3ba5-4990-bef2-7f9976be4b5a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 14).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c145d65b628ccaab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('831640ac-de9e-4cf1-ae2e-7fa63cdb064b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 14).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f09eea4c0427adcd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5222ab95-0c0f-40c9-a2a5-dced082e4789', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 15).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd75e9143eb1f2567_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd9f82f2-1297-49ff-9574-3e153a88ded7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 15).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '46ac180dcd1a0f65_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8709d389-33c8-43f5-a9ff-86284146237e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 15).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '422da67df0eb6956_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('665e1a87-a5b1-4b16-a579-17075e5202a8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 15).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '6b3a7411fd49343a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('013cda53-21f1-46c3-86ac-94c89fbfd427', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 15).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'c6c1453fadc8d6da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ae5d104-cab4-4d95-8f93-a02d5f342272', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 15).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '9c5422eee1100468_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31731698-2a6e-40ef-8623-210ede80b30f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 15).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b5fd437fb84c6e51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95b06c72-734c-4424-9e89-0bb7a9afe4e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 15).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f08776e6cf3b3260_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07bca0f6-8b1c-4761-bd4c-15e3349e59a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 15).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9a9d389a39e77235_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80e4b5e5-db85-4e81-b7c2-37fb5d2d74f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 15).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '5c897f679f44fdce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2780de31-eb93-4a6a-a8a4-170dfe65325b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 15).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2ab23c1cfb57de26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b76bb90-630c-4704-9bb8-2eda4f45c0ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 15).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3a79c873110cf810_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d3d36c7-c9c9-47a0-97de-919ee67ab3aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 15).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '9770efd965ad8763_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e2638f1-8c29-4873-b7d8-0f588025e500', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 15).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'def9c663a159b265_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24b96cc8-eb26-42a6-93cb-a5e85301807c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 15).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3febafad079287fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('195dd849-8072-41ff-bcb4-668bbb44f7bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 15).', '[{"id": "A", "text": "set router-name R3", "is_correct": false}, {"id": "B", "text": "set system name R3", "is_correct": false}, {"id": "C", "text": "set hostname R3", "is_correct": false}, {"id": "D", "text": "set system host-name R3", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'd75d2e762dfac541_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af5c9c6d-f88a-4237-8763-60c2c509b3b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 15).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}, {"id": "C", "text": "set user root password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '74d8566745fd85e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ac27160-b641-4bb3-9c7b-87139eab02c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 15).', '[{"id": "A", "text": "set interface ge-2/0/0 ip address 10.117.223.1/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/0/0 unit 0 family inet address 10.117.223.1/24", "is_correct": true}, {"id": "C", "text": "configure interface ge-2/0/0 ip 10.117.223.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.117.223.1/24 interface ge-2/0/0", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f7c92b84eccb9f38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65c6fdc0-c25b-4535-a938-c7b54a7a9a60', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 15).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9244f3020f15c368_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f6cbdd1-c750-4cf3-9228-018a8eb726a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 15).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd0e84b4d169ffcde_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d298779-2e10-40e7-a7e4-f3b976d761c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 15).', '[{"id": "A", "text": "show interface et-0/0/1 monitor", "is_correct": false}, {"id": "B", "text": "watch interface et-0/0/1", "is_correct": false}, {"id": "C", "text": "tail interface et-0/0/1", "is_correct": false}, {"id": "D", "text": "monitor interface et-0/0/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '981d9abc5b18b41e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d22daef-4449-4dc4-a95c-ede8784f92b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 15).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3cbc5dc4af8e9ca0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c4e8e4a-8473-422e-91d9-431c29dda69a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 15).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '44f5dc098c52f7b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('162156cc-6e45-4c9e-8ffc-1aa0645ace06', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 15).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '04e5338ed65d61c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e3eb564-a97a-490a-a278-94590713859d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 15).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '48fa04822488db63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7062435-2e6a-4ecd-a136-587f70a21bfb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.90.184.0/24 via next-hop 10.241.220.254 on Junos (variant 15).', '[{"id": "A", "text": "set routing-options static route 192.90.184.0/24 next-hop 10.241.220.254", "is_correct": true}, {"id": "B", "text": "set static route 192.90.184.0/24 gateway 10.241.220.254", "is_correct": false}, {"id": "C", "text": "set route 192.90.184.0/24 next-hop 10.241.220.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.197.187.0 255.159.199.0 10.241.220.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3f372623481d9249_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1bafc01-d94d-4e03-9217-5bc7d1f48078', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 15).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'edd6a286a02937eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a84c0289-313d-47c2-8e19-c049ec3489cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 15).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '14193df1be4f68f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46693f88-69bb-4210-9ae8-92906bdbd924', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 15).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '6ffbb9758219d7dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31dd149d-1579-46e4-8615-02d1f65e9dae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 15).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'edff8767be549192_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbbec144-052f-4583-ac1d-9e271b7dbc5f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 16).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6fb0833f4a3f5cfe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b61219b9-6ebe-43e7-be45-9a2e9b7b3189', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 16).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'd3ed4ad35047f3bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('291bfdb6-2435-47d9-bf94-1a96ce4e3951', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 16).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'c5f6f865c378f462_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38b95d25-c1da-4b84-aba3-888a6bdd3dd5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 16).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'd2c1f5fad9f3c428_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a99c171-32bd-4221-b8af-787a84b9eff3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 16).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'cdae82ee56b8e941_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91d30cc2-1054-4fbe-a8f7-5b50b393a3bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 16).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '4773d28add2de1f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('721247c8-024a-44ed-8c99-61b74a8429f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 16).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '98e56bae3010d879_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a079af75-880e-4577-b24e-e7694c89d056', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 16).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'cd4dc61e650a4189_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c834be4-c2f1-4150-a33a-aa017910bfa6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 16).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '41c38fd1f4026c7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcb60d0a-3831-4a34-8614-db2f54c939cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 16).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '124f813ace9b6421_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdefebf2-da77-44d5-abfe-3fd016d28e35', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 16).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '84a353a457f9c3c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acc7d0a0-4ecb-4271-af89-af4e830dbe22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 16).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '4ee7c10b55e6cc0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f1c4303-0f7d-466b-b67b-363043aedbe3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 16).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'adda44e139d52d2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3fc2aa2-3d75-407d-bb06-c237221977dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 16).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fe59f42d8a8e2265_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03b3079b-4266-4c09-909a-9b5e8237b21f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 16).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '330872c0a2107600_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89d2e6b8-2080-49d6-b06d-9f6a4a3213d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 16).', '[{"id": "A", "text": "set system name R6", "is_correct": false}, {"id": "B", "text": "set hostname R6", "is_correct": false}, {"id": "C", "text": "set system host-name R6", "is_correct": true}, {"id": "D", "text": "set router-name R6", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '40bbabd3d57d2c49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8eb3ea3f-57e3-444e-8f29-1adae352f174', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 16).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '96a0e6a7ab368aca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30db4de9-44e6-484f-bc17-50353809266f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 16).', '[{"id": "A", "text": "set ip address 10.10.231.5/24 interface xe-3/1/2", "is_correct": false}, {"id": "B", "text": "set interface xe-3/1/2 ip address 10.10.231.5/24", "is_correct": false}, {"id": "C", "text": "configure interface xe-3/1/2 ip 10.10.231.5/24", "is_correct": false}, {"id": "D", "text": "set interfaces xe-3/1/2 unit 0 family inet address 10.10.231.5/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '93cea1e3394666dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('576c61f4-a2e8-40e8-89c5-0d7da7ec6c9c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 16).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4fa6075fe6e52fe7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cfd190a-f733-4287-8d95-55ad8ee50fcc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 16).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c889482502405c94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe63c195-d589-40da-91cf-952c7d55b192', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 16).', '[{"id": "A", "text": "monitor interface ge-3/0/3", "is_correct": true}, {"id": "B", "text": "tail interface ge-3/0/3", "is_correct": false}, {"id": "C", "text": "show interface ge-3/0/3 monitor", "is_correct": false}, {"id": "D", "text": "watch interface ge-3/0/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '98924a2e3e9db6cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eb777a9-3e81-4a0d-b7df-231b8bc92b79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 16).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f231538e7456bd80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('989688f2-ab48-478f-8bc7-9e92742c19d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 16).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e591adac4e16e811_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fa763d0-b0de-4614-913c-112d6f8c19fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 16).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '3db9a9c3d9d4def4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cdcb42f-7fc0-42a8-b688-ab480a7ce074', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 16).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8be480180d487881_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1da9609a-f71b-4154-b6fb-c780f9102ed4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.123.116.0/24 via next-hop 10.196.145.1 on Junos (variant 16).', '[{"id": "A", "text": "set ip route 192.24.47.0 255.107.75.0 10.196.145.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.123.116.0/24 next-hop 10.196.145.1", "is_correct": true}, {"id": "C", "text": "set route 192.123.116.0/24 next-hop 10.196.145.1", "is_correct": false}, {"id": "D", "text": "set static route 192.123.116.0/24 gateway 10.196.145.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a13b626664478e43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4bbc8ba5-6e7f-4817-8b11-250a8fa4dd48', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 16).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '2e4dd288fbdabf7a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2af7eeb5-2bff-4cc5-8362-99347a503b9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 16).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a234a1607b951064_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b2786e2-fbfa-431e-86f5-8cfcca38048e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 16).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f02d91368275ac80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46d942d6-60da-4908-81b1-5f7e64c79405', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 16).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '73ffa758d3540dfe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('531e9bf0-52be-4236-a25d-f948985365f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 17).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b478bdd62ef06aab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5936362b-4cfc-4cdf-865d-4c8261abc7c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 17).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'c2cf6e80b1eb347b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c766ab7-539e-4a93-8d3f-1a5a45ce15db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 17).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'a4be10333abd5729_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('711b3788-f5f9-446c-9c5c-734968d0b1bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 17).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4d8b682104d6ca86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2632da9e-b56f-4e2d-8c97-b3e211fb63e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 17).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'c832b0d9ce8b8a6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c763c33-7535-4c43-988d-9013bd92ee74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 17).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '31a43c8626d3c42d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2170ee7f-e2e9-48f6-9235-6036a3670d82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 17).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '52654f120694faa7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee32a28d-1dfe-4db1-99c8-feabe68b215f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 17).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c1bdff117ab5e66f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fd1344d-2779-4b55-9578-eae2d1f0d0bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 17).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8b7b93e4eea08a18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d300cfc-53c8-4723-8938-700a21755a63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 17).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'fa9c93f4f70e3b81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a06d79f-7913-4901-968c-8a119fdab2a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 17).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '285aeee078ac9bfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42539ad9-7d81-44fb-86a7-d5957e06b272', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 17).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '742e628521f2cd1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61902b09-c45c-4d17-a412-5157554041af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 17).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd2ea12a78879c408_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1518aba-c72d-4a7e-9861-44470728ff10', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 17).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f759b38e8058d640_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd3e4763-1d91-4abd-9540-d08b331ffa62', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 17).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f7c421a612db0341_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42b3acb7-e7c3-45a1-838d-de85883d40d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 17).', '[{"id": "A", "text": "set hostname R5", "is_correct": false}, {"id": "B", "text": "set router-name R5", "is_correct": false}, {"id": "C", "text": "set system name R5", "is_correct": false}, {"id": "D", "text": "set system host-name R5", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'aef0629f8f5f7460_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e5facff-82db-49ba-9384-a0c8fda1dd84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 17).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "set user root password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '133209e4416bd1d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2318e409-dc71-4b7c-bd38-08a7faab61ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 17).', '[{"id": "A", "text": "set interfaces ge-2/0/0 unit 0 family inet address 10.8.131.5/24", "is_correct": true}, {"id": "B", "text": "set ip address 10.8.131.5/24 interface ge-2/0/0", "is_correct": false}, {"id": "C", "text": "configure interface ge-2/0/0 ip 10.8.131.5/24", "is_correct": false}, {"id": "D", "text": "set interface ge-2/0/0 ip address 10.8.131.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '2e064c0f4a066587_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a33dc49-99a5-4aff-8c3f-4acde30fa01f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 17).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a6d30c64b9f192f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a3ccab4-d320-47ed-ac31-d28d8b2d7c52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 17).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '238dfaed06bc8d9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e6904ba-0e23-4043-893e-2875aeb8a4bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 17).', '[{"id": "A", "text": "monitor interface ge-0/0/2", "is_correct": true}, {"id": "B", "text": "show interface ge-0/0/2 monitor", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/0/2", "is_correct": false}, {"id": "D", "text": "watch interface ge-0/0/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '333d5a8ab0dac9cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('393e6f10-86b8-46d8-8e69-3d4ddaab87ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 17).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'dc02c9d49b6f414c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2786d59d-bdf3-4420-ab2c-495240450ee9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 17).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6e0af297cd489582_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b40fef91-83af-4d4d-8ac2-45e8cd73f1ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 17).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '9b4db7da07b7a7d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa031f4a-f88d-449a-81a7-04528cb685e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 17).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6fd3cf5f2953ca25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab62c489-ebe8-494e-87c2-342d38c23640', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.255.120.0/24 via next-hop 10.27.113.254 on Junos (variant 17).', '[{"id": "A", "text": "set static route 192.255.120.0/24 gateway 10.27.113.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.255.120.0/24 next-hop 10.27.113.254", "is_correct": true}, {"id": "C", "text": "set route 192.255.120.0/24 next-hop 10.27.113.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.185.113.0 255.178.63.0 10.27.113.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5ad69af444179e42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('940faf2c-dbc1-41b0-99e8-fe0e32e570a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 17).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '595457fa240f0be7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9fe8dff-5847-49f2-a920-92218b18ce53', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 17).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '48a38c1fa7d40aaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('753ba916-9b97-435c-9bd7-1c656241c71f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 17).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'db43081e1c0b26c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b724f58f-ebf0-4dd2-bb48-12726433f47f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 17).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd219cb0020746aed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a8de133-d2d8-42ea-92c6-df314cfd1957', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 18).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '5fe225019348b7b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23c9d088-82a5-4a85-bd1d-be0faef80738', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 18).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'ae20c6c46ffd3adb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6de0322-7b8f-4ab0-b2e8-d7f6e149714b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 18).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '3fa558fb18ee8f5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1dc22b8-18db-41be-8b76-f22424b8848d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 18).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'a109370de4784b29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5142c86-73f7-4c24-83e6-0d3363b1a059', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 18).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '912c48ae75a5b84d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f6f8813-6bf4-43b2-934c-e5ba2c28c9c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 18).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'f443383fe07b43c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eea4f697-9fec-4c7d-ad23-61dbf6f7b16b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 18).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '40b22c20cf978bc7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c94e124-d41a-4705-9785-1494859b2d86', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 18).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7d1a4ea6880e7ce4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dc30d26-515c-4d63-86fe-d8754b975fb3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 18).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3040be9153adfb3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('345a96dd-6efb-43e5-b885-af82fb24ba85', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 18).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '2d17c236396c77b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6602d240-e229-4496-93eb-2d882dee88fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 18).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '328e5e09bb4630d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93d95c52-e7b4-4806-9b1e-bf2ed46f97ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 18).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '582a5070bd1a4936_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31f46b43-b216-4b67-b751-f5231aaeca08', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 18).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0fcbc6d10fe39359_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('233556be-86de-41c1-beb6-1e12f16e0ade', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 18).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ee7292e68b51b8b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2a69311-a892-438b-88de-bb5daea6ff9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 18).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7649ec28d5f74ead_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8a2a221-a39b-4fa5-bc90-ebcd589f42df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 18).', '[{"id": "A", "text": "set system name R1", "is_correct": false}, {"id": "B", "text": "set system host-name R1", "is_correct": true}, {"id": "C", "text": "set router-name R1", "is_correct": false}, {"id": "D", "text": "set hostname R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '418a2734abf1d866_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5cd6295-b99f-4123-a229-6926afc7704b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 18).', '[{"id": "A", "text": "set authentication user monitor password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user monitor password", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3ee2edae920fcef5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab562043-075c-43a4-a231-cc57b743bc1a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 18).', '[{"id": "A", "text": "set interface ge-3/0/3 ip address 10.147.71.254/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-3/0/3 unit 0 family inet address 10.147.71.254/24", "is_correct": true}, {"id": "C", "text": "set ip address 10.147.71.254/24 interface ge-3/0/3", "is_correct": false}, {"id": "D", "text": "configure interface ge-3/0/3 ip 10.147.71.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '3c59cd68feea0bc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a55a09d2-ff8a-4dae-94f8-518782d8bdda', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 18).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a98fa83d253264d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c51c8fbc-bc83-40dc-9b69-ab23eed2f157', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 18).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1f2cf27c533a2c18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27288a11-327b-401b-92c3-edbcb1716a84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 18).', '[{"id": "A", "text": "show interface ge-1/1/1 monitor", "is_correct": false}, {"id": "B", "text": "watch interface ge-1/1/1", "is_correct": false}, {"id": "C", "text": "tail interface ge-1/1/1", "is_correct": false}, {"id": "D", "text": "monitor interface ge-1/1/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'e229b4b65d2f949b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88b79081-4cb7-40a1-8e4b-87b70afcc82f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 18).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7d523447d8c93b9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b60e5f31-4cf1-4ce2-8533-5a1b4826a5c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 18).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c9b91ea6a3f84cf6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('385ea271-28b6-4abd-b555-0d498b48fd1b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 18).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'e96b98fa1bb06858_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a0f0153-8e82-4623-b722-255cf3319801', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 18).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd2fef8aed65987af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ea50120-2569-4651-b39d-8817ea739864', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.49.83.0/24 via next-hop 10.107.45.5 on Junos (variant 18).', '[{"id": "A", "text": "set static route 192.49.83.0/24 gateway 10.107.45.5", "is_correct": false}, {"id": "B", "text": "set ip route 192.179.95.0 255.108.217.0 10.107.45.5", "is_correct": false}, {"id": "C", "text": "set route 192.49.83.0/24 next-hop 10.107.45.5", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.49.83.0/24 next-hop 10.107.45.5", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '97bd1d252e7dff45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b08a744b-8be4-4457-ae72-fd0e97cca141', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 18).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'f5fc5182db45cb91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7927c447-e4f7-4c5c-80e4-e73e7a52cd3f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 18).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'eb95f49588fafd0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a73e3689-c7af-4307-84f8-3f1faf807698', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 18).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4ec7a39b65771ee7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19776182-2a98-43e9-8127-9d1a88c73777', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 18).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '32d6ebd7fe5222da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a31cc669-6521-4c61-9eb7-ea4f67208192', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 19).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '94ce886fa7cb40af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f2b061f-e0cf-4b47-ab50-5df365219378', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 19).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'a3085be8a5cf4241_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63bae349-02ee-4b99-b9d5-7520a099afb8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 19).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'f589ba7a8d10b44d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2c509f8-06b1-4daf-ba3d-86c086682029', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 19).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'cf0240e03d329f62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fe98b6a-14c8-40c8-9b0a-810c81ba177b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 19).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '5bf529a75c4ba9c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f09394dc-7e0a-4cc5-b474-5265ce969e17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 19).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '70cf1681cd8e8e35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4906f6c-a34f-437d-a3c5-c1e12d2caad7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 19).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'be6e7cc06a695a28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54d941b5-1525-45d8-9df6-89647744428a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 19).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '20c638cad1eebd1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28bef8e1-b325-4900-816c-a58a751a301c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 19).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f56f4ac201a355f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a7d463e-28fe-47d7-9615-8e20fe975b14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 19).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '5c454f674e2a2716_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fe3981c-c797-403a-ae1f-f6aa3d92729b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 19).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'cc04eb5af5ee101f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af54b988-5020-43b5-a4fa-35eaba57a645', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 19).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '913762cb2f6ba228_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09e29faa-331e-48fb-9b24-06c804a28a81', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 19).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0e780498e2d6dd19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72dbaf64-6baa-4f11-87f9-f7d12c06145f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 19).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '517fa7f788dd1886_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b66ce066-b82b-47f4-adcd-56ed1bdb4bd6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 19).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ce29199854561dd0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('143f5b11-7957-4643-96ec-35264aee0d9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 19).', '[{"id": "A", "text": "set hostname R11", "is_correct": false}, {"id": "B", "text": "set router-name R11", "is_correct": false}, {"id": "C", "text": "set system host-name R11", "is_correct": true}, {"id": "D", "text": "set system name R11", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '578729df27a765bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0b50a6b-cfe8-4ffd-8eb6-b07f309f9948', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 19).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9ed72dae87918c43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db69cedb-10f0-4aa2-b487-d451096f1482', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 19).', '[{"id": "A", "text": "set interface xe-1/0/0 ip address 10.2.88.1/24", "is_correct": false}, {"id": "B", "text": "configure interface xe-1/0/0 ip 10.2.88.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.2.88.1/24 interface xe-1/0/0", "is_correct": false}, {"id": "D", "text": "set interfaces xe-1/0/0 unit 0 family inet address 10.2.88.1/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f6af7799eacf3be8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee60736e-21a7-40ec-8880-a9f48a23231a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 19).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd78bee210c7d946d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19658154-9b8d-46ed-80c7-77ea650d0717', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 19).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2530db139fa9b8ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b84bf43c-0cb6-4e38-9615-19792ce91d37', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 19).', '[{"id": "A", "text": "show interface xe-3/0/1 monitor", "is_correct": false}, {"id": "B", "text": "tail interface xe-3/0/1", "is_correct": false}, {"id": "C", "text": "monitor interface xe-3/0/1", "is_correct": true}, {"id": "D", "text": "watch interface xe-3/0/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '459dd0c97f414b75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89fec563-8e83-4ab2-a492-baf5e76e725f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 19).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1593b9c10042f68b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('094c033a-637d-4025-afa8-86029c994fe3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 19).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8b3988744d913b44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5a1d23a-be60-4005-a5f3-9426fe2932ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 19).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '12c2625873d6343c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9aa881c-5ce5-43d5-b318-13bc49eac4f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 19).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '4d490365b91111a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d77951a-e33b-4678-8803-18a801d918b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.177.242.0/24 via next-hop 10.206.81.254 on Junos (variant 19).', '[{"id": "A", "text": "set static route 192.177.242.0/24 gateway 10.206.81.254", "is_correct": false}, {"id": "B", "text": "set route 192.177.242.0/24 next-hop 10.206.81.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.251.84.0 255.238.29.0 10.206.81.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.177.242.0/24 next-hop 10.206.81.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a5b01a8562577d5a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a31b6d5-7915-4050-b5e9-8644e313aa1c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 19).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e6ed7580f6efe3dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c1dcb6d-ab65-4836-b5a2-091d8d73a174', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 19).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '602fc47255afa3b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1f64ed8-fb79-4b92-9698-6338c1cdfa17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 19).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '84b62d673bf2d8d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc6d866d-864b-4bca-b5ac-bc574803b545', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 19).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e724357677f9464a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('648d48b8-2dc9-4ac0-8b4b-200757084a03', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 20).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '958eb7fd945adab0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50624dee-4061-44b4-91c4-e1d6749e67a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 20).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '95e900e22afb55b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2f18c05-e25f-4c32-96ca-f3f18009f5e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 20).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'a8c2a02e06910efd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b9c55a0-5d13-4b4a-bb04-70a9b965816e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 20).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '67ce818f2884e6b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('781bc32e-b896-47f5-b90f-e98091206ca5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 20).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '2684f3e2d0c33225_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('105e9512-e89d-49d0-ad58-fb7626967e09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 20).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b6d04ba251a2d8f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9164b5ac-213e-41c2-90a9-430ba6f1c4de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 20).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ba58d69c804f0dc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36ef024f-61d5-42f6-9155-598c8b6c56fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 20).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '72cc3fc6451b56a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5e8d059-ef59-41c1-8f93-13c5436cb33e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 20).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd6950aa1ed63dd6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('687596b2-db81-4566-a20c-8d9168c6020f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 20).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '9f63d5a47e9bc495_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dc9f234-8db2-40c8-aa9a-12ffcc22dfa5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 20).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a845c7a19e7adfa3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d63cbe58-d215-456d-88b9-03e86b58b3fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 20).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a5fe84c68805fc95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('330dcc20-5d67-4f3e-bb7d-e977d86a1488', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 20).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '930f98eab477aa66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b4a40a2-99c2-43d3-9d47-b3c376e759d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 20).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8ef85239ac004b8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('671ffa7d-4725-4b48-9025-151d66696e76', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 20).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '38984658f3f9c41b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3076823b-a2d0-490b-a28f-63e9383f1ef0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 20).', '[{"id": "A", "text": "set system host-name R9", "is_correct": true}, {"id": "B", "text": "set system name R9", "is_correct": false}, {"id": "C", "text": "set hostname R9", "is_correct": false}, {"id": "D", "text": "set router-name R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '77c6736035247101_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4abc15f2-c581-4c68-b013-cd3fc8e5bcf4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 20).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '2243ea69276f627f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3cd6b66-68d2-498d-972b-702624e0a979', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 20).', '[{"id": "A", "text": "set interface ge-2/1/3 ip address 10.4.160.5/24", "is_correct": false}, {"id": "B", "text": "configure interface ge-2/1/3 ip 10.4.160.5/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.4.160.5/24 interface ge-2/1/3", "is_correct": false}, {"id": "D", "text": "set interfaces ge-2/1/3 unit 0 family inet address 10.4.160.5/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '938b587cfe21160a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e62c0934-356a-4fd4-a873-966c6c79d4d7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 20).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5d26bac47fc6f268_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2b35d6b-5a7a-4515-8427-ae6a2dc9b3de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 20).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd3466e9b4cad2e33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41c6ee00-a487-4937-9a41-99a89a7ff1b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 20).', '[{"id": "A", "text": "watch interface ge-1/0/0", "is_correct": false}, {"id": "B", "text": "monitor interface ge-1/0/0", "is_correct": true}, {"id": "C", "text": "tail interface ge-1/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-1/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '871610993a7501e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4773990e-e362-457c-b532-30f7f19f81a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 20).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6919cfba0ac33dc8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41b935f3-0c9e-46cd-b993-bf4c783ccb52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 20).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '22d5c0ab3d64ae40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c96b351-1f03-4421-8dfb-da374c658bed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 20).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '9fc55c4105f085ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08595d15-8ec3-4b98-8076-5a7bc090b388', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 20).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd6b57438abfc1e8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e02dbcca-467a-4d67-a46d-d230f6d7b4fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.177.165.0/24 via next-hop 10.205.68.1 on Junos (variant 20).', '[{"id": "A", "text": "set routing-options static route 192.177.165.0/24 next-hop 10.205.68.1", "is_correct": true}, {"id": "B", "text": "set route 192.177.165.0/24 next-hop 10.205.68.1", "is_correct": false}, {"id": "C", "text": "set ip route 192.198.142.0 255.138.79.0 10.205.68.1", "is_correct": false}, {"id": "D", "text": "set static route 192.177.165.0/24 gateway 10.205.68.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'df78adca19e6c351_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e77bc4b-a2f1-4d42-92a8-93681866803c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 20).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'a5c1cd12af661a9a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('045c668e-27f6-4f09-b138-0ec717823f98', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 20).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f710eb06905b68e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('478041b8-4dba-4bfa-8cd7-babd98210e76', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 20).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a085876094ab59ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99a3f55a-c255-4335-b748-751957ffb9b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 20).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b79059d18f7076f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb711b52-e49b-452d-8b44-b1e96c5c288c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 21).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'af8030ea241fe816_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09fb6a3c-692d-4b4c-bde8-73cc0ab82a8c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 21).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '540ec9eddd851260_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91ecd77d-079e-4de6-8f50-1bcfb534bc6f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 21).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '604024a0d02ba15b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d158c3a-785d-47e9-bb90-8593617b196f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 21).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '8136d318a78f7975_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('781bba5a-102f-4c2a-93be-d57bce1cfd27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 21).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '1520ad45a9cd616d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06c60299-806a-46bd-9fd4-b07c727affbf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 21).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'e3efbe2e85086342_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebd9b095-40c6-43af-a1c7-a1e938a0c458', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 21).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f01f8eeaa9b60de9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d698500-87b9-4df7-97f2-ff0112d7c279', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 21).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fa33ea0d994a7912_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2efab50-d794-49df-b863-f876c1e0438a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 21).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1f623ff2372e2165_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3c9751c-ff3b-4614-9d71-3406578998fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 21).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '3e25af960ea09b35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd95e7cd-f0d5-4199-bed6-404277cb835b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 21).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f445a85fbf3ce47e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e7bd103-3f8e-4211-86d3-9dc20ad1890c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 21).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a0180cfc32a44770_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd214df3-991f-40c0-a193-f64847dfbcc8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 21).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '00c92a5aaa6f9f41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecdeac46-150c-4edc-ba4c-36a69ef34787', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 21).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a17388c108824a78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e774e26d-2784-4f8c-99b0-bf6e2859d4ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 21).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'cbf321149a5a4a5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee57cf05-d58b-4da0-84de-9f04ad2ab485', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 21).', '[{"id": "A", "text": "set hostname R3", "is_correct": false}, {"id": "B", "text": "set system host-name R3", "is_correct": true}, {"id": "C", "text": "set router-name R3", "is_correct": false}, {"id": "D", "text": "set system name R3", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '1f447aadcdb31466_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed18a6c1-ee3e-42b5-ba98-90874afe4bc5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 21).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user root password", "is_correct": false}, {"id": "D", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4b027c7f34f5a17e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e52d0aa3-0a26-46ba-8af9-d83ec3ec40bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 21).', '[{"id": "A", "text": "configure interface et-3/1/1 ip 10.174.127.1/24", "is_correct": false}, {"id": "B", "text": "set interfaces et-3/1/1 unit 0 family inet address 10.174.127.1/24", "is_correct": true}, {"id": "C", "text": "set ip address 10.174.127.1/24 interface et-3/1/1", "is_correct": false}, {"id": "D", "text": "set interface et-3/1/1 ip address 10.174.127.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '61302ec1a69c8d9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0e92e6d-428b-4d71-8e44-006cc3b38d01', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 21).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'df5778bbfe03b891_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b22b1f4-5adb-4c1b-b3a1-480c478312d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 21).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'fcd2e574d0666560_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c7b76de-981f-4736-b3a8-2fbe251cd14d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 21).', '[{"id": "A", "text": "show interface xe-0/1/1 monitor", "is_correct": false}, {"id": "B", "text": "watch interface xe-0/1/1", "is_correct": false}, {"id": "C", "text": "tail interface xe-0/1/1", "is_correct": false}, {"id": "D", "text": "monitor interface xe-0/1/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '287ef970089827ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c144d15a-c4f2-44c7-8e70-380ea188c86c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 21).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8cbfa157c98c34d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33faf875-17b3-4115-931d-2ac46377cd49', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 21).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2ac18a9b49206197_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a1cc455-0fa0-4542-ba75-fe1a9a30fa3a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 21).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '3c9a3fc3de4e11a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd4a8c51-86dc-4af2-a874-6c0b3aef78fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 21).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'dff020e9d800cc90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa9553d3-56ac-4ed3-b6b3-547f28eb501c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.139.162.0/24 via next-hop 10.33.87.5 on Junos (variant 21).', '[{"id": "A", "text": "set route 192.139.162.0/24 next-hop 10.33.87.5", "is_correct": false}, {"id": "B", "text": "set static route 192.139.162.0/24 gateway 10.33.87.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.139.162.0/24 next-hop 10.33.87.5", "is_correct": true}, {"id": "D", "text": "set ip route 192.222.219.0 255.196.32.0 10.33.87.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5b2f1c4860deed6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44cd6944-de85-484d-880b-a4d4cf1a2021', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 21).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '4991a4f5f112765b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c410df56-d478-4f60-adf6-276f69d777f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 21).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'c9bd4401e957ec50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99cf5924-407d-4cfb-b9fd-78643c9ac8d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 21).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5a3a263ed9d65737_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8efaf4e-2df0-4e0a-a916-e15affbf6b7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 21).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0484d30d6e3fe266_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdf37e8f-1601-4c22-9fbc-5d4118e59db6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 22).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '0c93a38958c33b1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5deb022c-3703-489e-b502-694419bd2f9c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 22).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'a79555a4878370ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d7e51d4-67e9-4f7d-ac80-50c2f45d1d31', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 22).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'e04bb24faeccd71f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae05a974-8c06-4780-b53c-cea7f8097565', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 22).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'a15cfd779925bf15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b64d4e2-3779-4b07-9703-dc8e5559037d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 22).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'c84b90d3d3ea40fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f636baac-f9f7-48a7-a91b-dae0ca19c363', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 22).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '232c0e358742be64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('175a018f-244b-42a3-96c9-cbde21c9101f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 22).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'cccd3d05efb88706_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3bbe124-fc66-460d-9953-64b91a99bd03', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 22).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '41af7b186e9fa7ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2ceb1ed-44e8-4cb1-89fb-8a99073af280', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 22).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9d7e157c76d9d8ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b52a2fdc-f0fc-4267-96af-974585574fd7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 22).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '81432bd719787219_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8be03ac9-3d44-4f2f-8439-bfe979a69a2b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 22).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '5142ffde6568aa71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d2f5077-fbba-4167-bc3f-f78d94525230', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 22).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'b934397a5598be85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e9e6849-8cd8-418e-b280-8de9e8b653c7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 22).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'dd4885ae9b69cd23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('252c7114-7c0e-487a-ac0a-2efd17689f46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 22).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '544e580c94281db3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('615c2c34-61b2-4b7e-a567-d769d018a6e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 22).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '63863745ece36cb0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34973b01-a4b8-4d93-84d2-a99de5fe6670', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 22).', '[{"id": "A", "text": "set hostname R10", "is_correct": false}, {"id": "B", "text": "set system name R10", "is_correct": false}, {"id": "C", "text": "set system host-name R10", "is_correct": true}, {"id": "D", "text": "set router-name R10", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2fffe07dd7d553d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9567baed-370d-4e80-b5b0-e0d7e5cf9d68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 22).', '[{"id": "A", "text": "set user monitor password", "is_correct": false}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a5c3b6d0a6ca168d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddbb4d44-334e-498e-b9e7-b0ed04f948a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 22).', '[{"id": "A", "text": "configure interface ge-1/1/0 ip 10.214.64.1/24", "is_correct": false}, {"id": "B", "text": "set interface ge-1/1/0 ip address 10.214.64.1/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/1/0 unit 0 family inet address 10.214.64.1/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.214.64.1/24 interface ge-1/1/0", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '7ea5a7f309be0c60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46fe4cac-c0cc-4844-8073-4d675100bee8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 22).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1664a1ea471f1ef5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fe9a748-ca4d-4587-bc45-424c531e4111', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 22).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b69f9c8c8278c13c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c4f68bf-aa6e-467a-8d16-0851128bf356', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 22).', '[{"id": "A", "text": "tail interface xe-2/0/3", "is_correct": false}, {"id": "B", "text": "show interface xe-2/0/3 monitor", "is_correct": false}, {"id": "C", "text": "watch interface xe-2/0/3", "is_correct": false}, {"id": "D", "text": "monitor interface xe-2/0/3", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2c11590b9c3c3397_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79c69fc5-94f3-42ac-8ea2-79796bc3af74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 22).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '39fa084f57f9b6de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e50f494-9f49-46ab-b187-39b0d1448834', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 22).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c4bb78d172a05b34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89dab795-9428-4bea-b2f1-e72dcbc989d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 22).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '47657fcf6dde55a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45e85f04-1d8c-4a28-8b43-aae1c24ee1f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 22).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5dcd0a899ff50a5a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fd33652-10a9-41f3-8004-7cf1a441114e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.54.96.0/24 via next-hop 10.242.183.1 on Junos (variant 22).', '[{"id": "A", "text": "set static route 192.54.96.0/24 gateway 10.242.183.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.234.40.0 255.164.21.0 10.242.183.1", "is_correct": false}, {"id": "C", "text": "set route 192.54.96.0/24 next-hop 10.242.183.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.54.96.0/24 next-hop 10.242.183.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'be0caa4e367f827e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f4cd71d-98f3-48cf-9df3-05a08a05836e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 22).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'da135ecdd858a9ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20b75df0-0b1e-451b-86bd-09971d98d2ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 22).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '6598faf9d3f73e85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21d320f3-d8f4-4ffc-9493-c0233758fa83', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 22).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '44d550790e6890cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee8c23a2-9b5b-42be-bed4-cb6beedac9c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 22).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0409c7894513a3c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6caba9a-08b5-46ca-a167-099cdf74a025', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 23).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '13d13f720d17f778_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8919eec2-d429-402c-95dd-4da11d0a1d4e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 23).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '6f0c20159d487154_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('101370f1-a34c-4a8a-96f4-6bd9a8d7cb7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 23).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'fc0c78ba046f75ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d48fec0-911d-4515-a6d0-d1153442034d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 23).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '24fdebd364b4109d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0813cc4-7d33-460d-a674-1f36d0c6c4a9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 23).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '332472822da0da9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9ad53a6-0986-4f16-8a5e-e1d974430634', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 23).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '158e41378fc2807b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5c14106-3a36-4aa2-ae1e-6a9d9856f3ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 23).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5c2e77943ddaec11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a46a8f67-f3ad-45af-a821-522f73ac31f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 23).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5ea11af0116aa649_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ea25dd5-6e11-4462-987d-d7a0e66d8870', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 23).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5d2b1b4e65639522_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('187e9be4-50e0-4daa-ae35-19d1dd57aff1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 23).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e232a8b4142ad6c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('354550ac-8aae-4748-ac21-ec30dc04a0b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 23).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ef3a1c093dda985b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b4a549d-6a80-4c02-85b3-e96c22bb9c5f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 23).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c7d3060b95a10f2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8c82baa-b07b-4b34-8d0c-6d81e2e7596f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 23).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7d029aff7dcfa11f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b64ffc16-a0dd-4513-96ad-0f0fdd1529c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 23).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a815c114db3a794c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d280dd0c-d381-4c3f-8144-05baa37c18ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 23).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '83fd63ddf2640c40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b3690bc-321b-4323-aa14-128377a3ea9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 23).', '[{"id": "A", "text": "set hostname R12", "is_correct": false}, {"id": "B", "text": "set system name R12", "is_correct": false}, {"id": "C", "text": "set router-name R12", "is_correct": false}, {"id": "D", "text": "set system host-name R12", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4a4dde80df877c92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a0ca92e-87c5-4e03-bc1e-2dab8696fa05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 23).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd18046160e2727ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e70ffc60-a05b-4f63-a4d7-04d3ad76369b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 23).', '[{"id": "A", "text": "configure interface ge-0/1/1 ip 10.248.227.254/24", "is_correct": false}, {"id": "B", "text": "set interface ge-0/1/1 ip address 10.248.227.254/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.248.227.254/24 interface ge-0/1/1", "is_correct": false}, {"id": "D", "text": "set interfaces ge-0/1/1 unit 0 family inet address 10.248.227.254/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '058cbbc235bd6e1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df6c7574-d751-4783-aeda-b6a4cde4ab78', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 23).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'da014a659ff05276_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4d47db6-0182-47d0-be6b-4c6fd44c1db4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 23).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6754923ea4823ec3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5b68952-5c24-48f5-aae3-a598fe6c6c59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 23).', '[{"id": "A", "text": "show interface xe-0/1/1 monitor", "is_correct": false}, {"id": "B", "text": "monitor interface xe-0/1/1", "is_correct": true}, {"id": "C", "text": "watch interface xe-0/1/1", "is_correct": false}, {"id": "D", "text": "tail interface xe-0/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c5e3c640242a80d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e1b3a62-9a6e-4c27-82b7-2864a5a2f2aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 23).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e1f687aecc0d2833_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac949400-3399-49c9-b02f-141b8f7d7abe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 23).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e458580eed798e6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7efdda96-d068-43df-920d-294e8997338c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 23).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f72c619e2139f52c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15405a81-6a5d-4fa8-b783-97650830ecf6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 23).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'cdd2bfece0731825_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('051fd877-d24c-4cdc-93de-30514f204159', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.1.230.0/24 via next-hop 10.22.217.5 on Junos (variant 23).', '[{"id": "A", "text": "set ip route 192.79.110.0 255.171.16.0 10.22.217.5", "is_correct": false}, {"id": "B", "text": "set static route 192.1.230.0/24 gateway 10.22.217.5", "is_correct": false}, {"id": "C", "text": "set route 192.1.230.0/24 next-hop 10.22.217.5", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.1.230.0/24 next-hop 10.22.217.5", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '433dc4c248041b87_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('271e230e-1003-4630-959b-b83a12fc628a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 23).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '641326a2dca1209e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fbc1751-7dbf-4103-a39e-41db65f3525a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 23).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'd8004e1902e8d669_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a163269-697f-433c-9379-49a51e9344c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 23).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'fc51d667fd829c3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e59e646-9a80-40ca-8db0-f64da4927b07', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 23).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2236c3b45b0872d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d72b4b9-a6d2-4091-96d9-45386c2cb8e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 24).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b39d1595daa19b2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58157878-2cf1-4a75-84a7-b379076f3c06', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 24).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'df3d607bc04d7b76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb5e9083-012a-4d68-b49b-f857db40731c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 24).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'd76a6bde242178ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffbe0cdd-ae14-4c1d-9ef0-2706cbbb2637', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 24).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'df3db42ff6d63bd8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3dd1ec69-3326-4ddf-9790-8e1d4a3215c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 24).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '693c67a9495f1429_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed788518-05c6-4277-b9d7-b79071accbcd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 24).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'f65af3be700671a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3a35301-781f-4c03-be79-85cbb04434f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 24).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '67358ae1c36ed843_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c485f578-6c27-4fba-be7d-8a78b51cd166', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 24).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9dd66a24ae1ab319_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4f7ef8f-87e4-4a93-ac13-0b823719624f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 24).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'bff7c5fa8a6e6bf3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cd75f01-2ceb-46d3-b244-7bcb5285978c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 24).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e14885f0bbad48d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e3b9a29-4bfc-40f9-b88d-4a10ef2b1c82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 24).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7d7422b40546b17a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0510cb38-fbaa-41f1-bc73-276e11441a33', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 24).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '701ae674b5c6f8f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d8c0266-b029-43fd-8758-1ad8c8c41295', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 24).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '73c32e81732e4c62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccfd44a4-2f9a-4787-b59f-c89aef32bb00', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 24).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f4699c76e14bfbc8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f9b4ec3-af6c-4def-8aca-5cf377adf133', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 24).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '254aabae7b1faa68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e5b1177-67af-4183-aba0-fb1e7c160666', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 24).', '[{"id": "A", "text": "set router-name R4", "is_correct": false}, {"id": "B", "text": "set system host-name R4", "is_correct": true}, {"id": "C", "text": "set system name R4", "is_correct": false}, {"id": "D", "text": "set hostname R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2499644a9e088bc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14e58556-66ca-464d-961a-2b3c6a3f12a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 24).', '[{"id": "A", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '08ac60142c69bc07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c96349f6-6377-41fa-832f-c606367a575b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 24).', '[{"id": "A", "text": "configure interface ge-3/1/3 ip 10.219.18.1/24", "is_correct": false}, {"id": "B", "text": "set interface ge-3/1/3 ip address 10.219.18.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.219.18.1/24 interface ge-3/1/3", "is_correct": false}, {"id": "D", "text": "set interfaces ge-3/1/3 unit 0 family inet address 10.219.18.1/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '03ee051ac64a1bdd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d18e10b-c8d1-414c-8135-bae74384b717', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 24).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '0671b44ce21efd94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('776fa4ae-9e1e-4b8b-951a-79f6c6861e75', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 24).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'cd758cdcdc4d2ec0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b103953-fd66-47d9-84f8-6df8e3213bdc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 24).', '[{"id": "A", "text": "show interface ge-3/1/0 monitor", "is_correct": false}, {"id": "B", "text": "monitor interface ge-3/1/0", "is_correct": true}, {"id": "C", "text": "tail interface ge-3/1/0", "is_correct": false}, {"id": "D", "text": "watch interface ge-3/1/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '4ad2efe9ef477796_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cfdcc6f-892f-4f4f-b140-145b776781ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 24).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c4bf36bafe85192f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89f84206-f1e3-4d44-aa4a-4eb0e0f06465', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 24).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2e48adddc3e7ef04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('404d75a4-7325-4dd7-8af9-353d48cc1bb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 24).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '82d8aa42b75d2f2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dee5215-272e-4db7-a7f8-ba984d8e22bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 24).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a900758682e5b79c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4eb5ded-5ca5-4ab4-9f15-b3990715b930', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.187.69.0/24 via next-hop 10.25.67.254 on Junos (variant 24).', '[{"id": "A", "text": "set ip route 192.120.91.0 255.20.252.0 10.25.67.254", "is_correct": false}, {"id": "B", "text": "set route 192.187.69.0/24 next-hop 10.25.67.254", "is_correct": false}, {"id": "C", "text": "set static route 192.187.69.0/24 gateway 10.25.67.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.187.69.0/24 next-hop 10.25.67.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7d44eccfdef20307_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ac60b06-032b-447c-b2c4-dfc3d2e071c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 24).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '0b50baa38aad58ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fef86223-72e6-45e7-9e70-82d04361dd97', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 24).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'd17d22333307ef11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b1f033d-d83d-4e3f-82a5-52dac0eaee48', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 24).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0d7f9cc82876c834_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6455c62-a1e9-42e9-b201-0c6ef34d9659', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 24).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4b46adae7cba627e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5518aa57-5b7b-46f0-b74c-f212a96ebebf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 25).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'f27e23b6b1a79ec7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('100f51d2-6a49-4be2-9f55-cf733278abea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 25).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'd4093d585d8564b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6156ea6d-0854-4135-8e1a-493c71440076', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 25).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '2b444e36802d0e40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40f7d777-6b80-42f3-af06-8c168724ff14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 25).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4a0ec3fb35ce17d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0a3f00a-0745-4d97-af45-313e6d356d52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 25).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'd841e274fb6af836_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52a9ea0f-3075-4b30-974a-22cdf4879308', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 25).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'f927031207239ee8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('509a40ac-5b02-4544-96ad-40d8d92294dc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 25).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a90aa143e125fa62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3910a523-33e4-4ab1-bcc2-444710e282bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 25).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2c5b688028104f14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('928739e3-bc8e-49a2-bef3-02da6e73814e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 25).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '48894db026c0ff2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9b5c300-5214-4418-98b0-fd440f1a17eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 25).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '414d0d68f6746fcb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('218113dd-020d-4e43-ac2c-efcfac628c09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 25).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6751da5fdeb9dce8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1e8c9b7-c5d5-4e73-abb7-9cc4afe499f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 25).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c37878333ff8f23c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f46d9fd-e96e-4627-8c97-9495d44e1823', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 25).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'c49710c24884cec5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b1332c4-2006-4e0a-8154-61ae0575c6df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 25).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '9d7aa965d166421b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db3f7b0d-f598-43cf-a8d6-f1568dc2ede5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 25).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c547dbd244a73249_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('487fea19-97a5-4873-81a7-017f43f1ded6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 25).', '[{"id": "A", "text": "set system host-name R3", "is_correct": true}, {"id": "B", "text": "set router-name R3", "is_correct": false}, {"id": "C", "text": "set system name R3", "is_correct": false}, {"id": "D", "text": "set hostname R3", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4183b90e735fed34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74150bb3-5222-4d81-9b82-0038421230ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 25).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b0d6e93c022f4d84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e9ba324-fb87-4966-a2bb-a0b61fe99352', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 25).', '[{"id": "A", "text": "configure interface ge-2/1/2 ip 10.40.163.5/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.40.163.5/24 interface ge-2/1/2", "is_correct": false}, {"id": "C", "text": "set interface ge-2/1/2 ip address 10.40.163.5/24", "is_correct": false}, {"id": "D", "text": "set interfaces ge-2/1/2 unit 0 family inet address 10.40.163.5/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f87c271aef4f1568_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5171baa3-3cef-4b4d-8015-dc165d97a692', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 25).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a233f662c22966e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7406f4a0-1b81-4fcb-a422-31931766ac31', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 25).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd469fb89d8cd3ea1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6cbb8ab-dc71-4e78-a53e-15727eb4d9b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 25).', '[{"id": "A", "text": "watch interface xe-2/1/1", "is_correct": false}, {"id": "B", "text": "show interface xe-2/1/1 monitor", "is_correct": false}, {"id": "C", "text": "tail interface xe-2/1/1", "is_correct": false}, {"id": "D", "text": "monitor interface xe-2/1/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'add22793114e96c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6f8eef1-e903-4826-be2b-33f207ab39a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 25).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8358882cb5a23048_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67381b0a-dbd1-4455-b991-d97ea201e2b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 25).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f28a8ed45d7777aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0430b48b-1990-4c27-ae5b-c432b9b9f720', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 25).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '46f0efa4c247a4a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f1015ba-3fe8-463c-a90d-14bce080e387', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 25).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '59586431fd7fd4af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa9e16a2-60a4-44db-83c1-5ea891afc10b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.234.75.0/24 via next-hop 10.179.13.254 on Junos (variant 25).', '[{"id": "A", "text": "set routing-options static route 192.234.75.0/24 next-hop 10.179.13.254", "is_correct": true}, {"id": "B", "text": "set route 192.234.75.0/24 next-hop 10.179.13.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.86.119.0 255.31.105.0 10.179.13.254", "is_correct": false}, {"id": "D", "text": "set static route 192.234.75.0/24 gateway 10.179.13.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'deeb0234da5e7622_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7f5a805-4f0b-4174-8bea-78981a3108bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 25).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '64e351ac281c01f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bea9fc6e-c2a5-4ff3-9918-20ce0a133db1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 25).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b14e243663e7709e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df38f56e-f52b-48b8-8fb6-70c8384cfdec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 25).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '125e4acc3728cfbe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7de5de12-4af8-42c6-a985-375cc6f3f2c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 25).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e61ec97e10bd1810_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('382ee56a-811b-4260-9922-58528e8c8b90', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 26).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '217443f465c7a14b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6b3972c-fe38-4868-9ad6-e97b680f790b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 26).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '714a2f83c346ae06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0d91824-e2d7-472d-bab0-1ee2cecd6c52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 26).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '98448f12d3e3b5f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ceb5d16d-0f4c-4552-8748-5e042373af69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 26).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'c6b6ad4b8296a27d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf6b5573-30c1-4ffa-81a4-22360939cf19', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 26).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'c15475d5ba6538fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a340cf93-b8c5-47c8-a944-a6014d5377e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 26).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '80ef2cef9adc95ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('721fe847-cdfa-4a31-9049-a0c7c2c69861', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 26).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '67eea50855f375d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39a06979-dc98-484d-9d68-970d0bc20b53', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 26).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8305c5d8042ec7ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75ddf861-b3bc-4b79-8277-b05a15a631c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 26).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6310363a28fd49c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e37db0ac-00d0-4edb-bcc2-1e20697f0763', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 26).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'ad0f1bd62537a7b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64776add-4928-4232-96e7-e9741055eeb8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 26).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '8a0fa6ff1895de83_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('058e6a8d-c434-42b9-a0cb-3b666d6ef5a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 26).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'be4ad724e0910bff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fca0b2b-d352-4c10-8f97-8d22b1c7451a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 26).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f46264ce3e19fd6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d86c2d9-20ea-4fa5-81dc-20238ab103df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 26).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'b0db290ad7dd55e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34861228-18db-4b30-b5e5-4beaaa293e62', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 26).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'cd87f49ffdb41aab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1906cb1-0217-4be0-8c5f-35137a015066', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 26).', '[{"id": "A", "text": "set system host-name R10", "is_correct": true}, {"id": "B", "text": "set router-name R10", "is_correct": false}, {"id": "C", "text": "set hostname R10", "is_correct": false}, {"id": "D", "text": "set system name R10", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'fa4e225c0b08a888_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39b9506a-72d9-41c7-add3-60ac04f53fb1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 26).', '[{"id": "A", "text": "set authentication user monitor password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user monitor password", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user support plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'dd91681c1f04fdba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('063ec326-89c2-4b4f-a4e9-e62aea3f7b34', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 26).', '[{"id": "A", "text": "set interface ge-3/0/1 ip address 10.86.236.254/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.86.236.254/24 interface ge-3/0/1", "is_correct": false}, {"id": "C", "text": "set interfaces ge-3/0/1 unit 0 family inet address 10.86.236.254/24", "is_correct": true}, {"id": "D", "text": "configure interface ge-3/0/1 ip 10.86.236.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '2c2a2c3c4177dcb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41b95cad-82d6-4cc7-a6db-2d26c5439888', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 26).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '2fec94b99eb9ea79_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f905a00-0f9f-4c22-977d-87eebd94ebcc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 26).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '65f789535779ecec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6535f019-841c-4836-a0d7-5944543659c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 26).', '[{"id": "A", "text": "watch interface ge-1/1/2", "is_correct": false}, {"id": "B", "text": "show interface ge-1/1/2 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface ge-1/1/2", "is_correct": true}, {"id": "D", "text": "tail interface ge-1/1/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2bbc5e45a03a96af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebb9696c-fae6-4907-9e12-425cbfac51dc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 26).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6177f3aa63f5d1a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52bc82ff-cb8b-4eb9-8ce0-8ffc85c8790e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 26).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '771956e669d92a70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48f236bb-d66e-4d0a-9dda-c57e18d97a72', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 26).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '83adf9694243decb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d466dfa4-c2ce-445a-9ae4-9271eaa6a24b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 26).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3a45f5f4d9480ac0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2ce78f6-c2b9-4c05-9111-46e8d12ae5a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.223.78.0/24 via next-hop 10.224.29.254 on Junos (variant 26).', '[{"id": "A", "text": "set static route 192.223.78.0/24 gateway 10.224.29.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.223.78.0/24 next-hop 10.224.29.254", "is_correct": true}, {"id": "C", "text": "set route 192.223.78.0/24 next-hop 10.224.29.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.12.250.0 255.91.48.0 10.224.29.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '56c6ef1c2a4038d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9362c46f-3fa9-46cd-8c9b-0ace8d238ebd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 26).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd1550713ffc7a388_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4372b8d5-b41d-466a-a405-d279fcc46708', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 26).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '3f63167bf16b94d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('635317e4-1223-42ea-94f4-e89f2d8596a8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 26).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f9a3c3ab5b6d312e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57815db6-de1f-4a0f-a1d4-9ca05e928a5d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 26).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '63d3393b4687b74d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d7bfb02-570f-4c6e-95f7-6a924588a2da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 27).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '3d2827998eb3e05c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22c52046-8e74-4b35-9363-da94c2f143c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 27).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'ed5903a8881c7793_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eab1187d-f8fe-49ef-9344-046e6f94e7af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 27).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '158a6af0b490c7f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b9cf574-ecbf-4a2c-ba47-9ecd5113f7c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 27).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '48cd810efea15435_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1b02652-1d7f-49d0-ae2f-637e8603c920', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 27).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '138f2e5f84d92fee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2345959-338a-4f9b-8f47-037060aae912', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 27).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '669b57c9afe8313c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39239fc0-c3e8-46b4-bc39-fe9782d7a718', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 27).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ec0f05c649019d60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f565a246-555b-4323-9009-2409feba621e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 27).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e7c6636e8cfc9a19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b1732d9-0bb0-4f89-b04e-d543639042b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 27).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6c5d9e71071d182b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e66b414-09c1-4fb3-a36d-e5220ece1eb5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 27).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '83eae72663b2e4a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('852cf7fc-7113-47ae-97d2-280e62b12fd1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 27).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '74b2b246b23d86cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d919269d-87e6-4289-9e75-4df1f493abb1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 27).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '015749863946a725_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3857a27c-564c-4ab5-85a8-559c9e46cdc2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 27).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '30b13dc4af17690d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cde24205-4650-44b7-bd0e-77851f7cee07', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 27).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '67ec40c030d46979_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8acbd946-cc7b-4bdf-b696-6bef311a687d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 27).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '21a03a20c5b652de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9a4795d-fe68-4465-b102-ec7f84a21ade', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 27).', '[{"id": "A", "text": "set router-name R8", "is_correct": false}, {"id": "B", "text": "set hostname R8", "is_correct": false}, {"id": "C", "text": "set system host-name R8", "is_correct": true}, {"id": "D", "text": "set system name R8", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3bcf0cab6c4772aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10150aa2-3c75-47c7-9706-0a43e055f716', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 27).', '[{"id": "A", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '422ab59a2c40e14a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59bba4a1-13f8-4e40-bc91-9047a462161e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 27).', '[{"id": "A", "text": "set ip address 10.214.31.254/24 interface et-0/0/1", "is_correct": false}, {"id": "B", "text": "set interface et-0/0/1 ip address 10.214.31.254/24", "is_correct": false}, {"id": "C", "text": "set interfaces et-0/0/1 unit 0 family inet address 10.214.31.254/24", "is_correct": true}, {"id": "D", "text": "configure interface et-0/0/1 ip 10.214.31.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '866a83a2f9e41904_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7d58179-3452-4e3a-ba5a-bcac591b2cfc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 27).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ce6ca403f4a1065a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('535dc995-39bb-45dd-8d75-cd510152922f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 27).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'bddeff61199507dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab54a88f-634d-4c7e-aa66-2e6ff3801e21', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 27).', '[{"id": "A", "text": "watch interface xe-2/0/0", "is_correct": false}, {"id": "B", "text": "monitor interface xe-2/0/0", "is_correct": true}, {"id": "C", "text": "show interface xe-2/0/0 monitor", "is_correct": false}, {"id": "D", "text": "tail interface xe-2/0/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'e6b790f6bd7af73c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83ad4744-1d81-460b-8f28-3698200bc3f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 27).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '86fe4507147ea136_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ace48ec-640e-4b84-b633-f437bb0b2ce4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 27).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b7bf9a1c112d7d6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b021a00f-28b5-4517-bad8-9267279623b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 27).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '81686accb554c4e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a40b1647-6cc9-4904-83f1-aa663096ee6e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 27).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '53047c0fb83ee924_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c3d61d4-260f-4e91-bc21-f2d7b11b06ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.95.113.0/24 via next-hop 10.4.76.5 on Junos (variant 27).', '[{"id": "A", "text": "set ip route 192.18.71.0 255.127.1.0 10.4.76.5", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.95.113.0/24 next-hop 10.4.76.5", "is_correct": true}, {"id": "C", "text": "set route 192.95.113.0/24 next-hop 10.4.76.5", "is_correct": false}, {"id": "D", "text": "set static route 192.95.113.0/24 gateway 10.4.76.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '715eaa5ac8f20b11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('392bd3f6-8efc-4a62-b1c3-d64a64266d96', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 27).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c57cefe2af2fbb9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d452a52-bd23-45f5-8fda-0ac3fa8eb60e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 27).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '3806ae5e26c75729_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aac9c6a8-2dd9-4ef6-be74-462f5f02209d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 27).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '81f6dd3d9510d20b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbcc6829-eeee-45e7-95c2-f67b151a300b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 27).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '36ab819c9fbff736_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9d84785-b5e2-4934-b003-b4756a1d1daa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 28).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '5ca7121b40c62493_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b38ba6e4-112a-49de-9330-e5ac091aad88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 28).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'fefb938f7fb44c28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2b49cba-381f-4808-ace4-958a20edc3e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 28).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'b95e3eb36a443bb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94a14f54-4cf8-420e-b210-d788a3008f1b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 28).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '88302fd6cea25c0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d8dc9ca-3b7c-4cd9-8c75-338682cc92bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 28).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '5bc3f39cffdd3601_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0cde1d0-86f3-4344-a20b-832136b1b7c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 28).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'c7c2cd4cfc078cf0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa995a9a-6730-4e61-8933-37afe1ff55d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 28).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c64c936f9d519890_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25c62419-08b5-4e66-a0f3-a957e94aeadd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 28).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '93ac75272e379c07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a42b841b-d631-44c6-ba9c-3efa727e3623', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 28).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8d6fa67d0fb5610f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4db73031-09fa-4f10-8ebf-415fee97be8c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 28).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '839c8af38c7d80df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df24c5d1-72d1-4224-af26-5e1f373f6c78', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 28).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a1f7988739eaf861_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27ad4ada-3738-421b-bce7-d0402e40d4fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 28).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fd790595c9ec3f40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ff81103-86ab-4309-be18-27f8c659d640', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 28).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '06fc7713c930a8d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dad67c12-de8a-445a-a17c-15c00b80e67f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 28).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2cdea044837271f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48d36e7a-34f6-4e98-9f09-4a7a139cba2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 28).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '802d1c0c6ea22524_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edf7531a-b232-493c-a71a-c3be984593fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 28).', '[{"id": "A", "text": "set router-name R8", "is_correct": false}, {"id": "B", "text": "set hostname R8", "is_correct": false}, {"id": "C", "text": "set system name R8", "is_correct": false}, {"id": "D", "text": "set system host-name R8", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0dd2dd2d947eb9d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('152136cc-9e0f-444c-9daa-bf0b83b8aa54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 28).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'e2bf1e8443b539ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d694a9b-341d-4de5-b62f-38d6e7d98c75', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 28).', '[{"id": "A", "text": "configure interface xe-1/0/3 ip 10.178.83.1/24", "is_correct": false}, {"id": "B", "text": "set interface xe-1/0/3 ip address 10.178.83.1/24", "is_correct": false}, {"id": "C", "text": "set interfaces xe-1/0/3 unit 0 family inet address 10.178.83.1/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.178.83.1/24 interface xe-1/0/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '904309b77e1c6ba2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90a245e3-45a4-4393-b5f6-aea9ffa0a42e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 28).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5575a30b4d88aa84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebbe89b5-ca10-4ef5-905d-7f9630de856a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 28).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '93578574342c1e15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7db98b00-fd89-4785-a16a-ff6c21663bfb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 28).', '[{"id": "A", "text": "watch interface xe-1/1/0", "is_correct": false}, {"id": "B", "text": "monitor interface xe-1/1/0", "is_correct": true}, {"id": "C", "text": "show interface xe-1/1/0 monitor", "is_correct": false}, {"id": "D", "text": "tail interface xe-1/1/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3f841402d7d5257d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d664927-30ac-43cc-a12e-bc74df4daaea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 28).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'fcd6373f49741b81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb4e6d9f-0dbd-40d3-941d-55ddbc011a66', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 28).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a0c45176c5bc79ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3ccfe3a-754f-4316-9c3d-347b252311b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 28).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '61c5814fd1fa517d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0041164f-ab62-4029-9a4d-fcc53694c39d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 28).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd42819d5e5bb64d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3710623c-d2f7-4fc6-ad7d-5f939ebb984e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.84.106.0/24 via next-hop 10.106.73.1 on Junos (variant 28).', '[{"id": "A", "text": "set route 192.84.106.0/24 next-hop 10.106.73.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.22.211.0 255.255.56.0 10.106.73.1", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.84.106.0/24 next-hop 10.106.73.1", "is_correct": true}, {"id": "D", "text": "set static route 192.84.106.0/24 gateway 10.106.73.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '683ca4934193f0bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eeb08e0c-a482-4428-9206-e83c507625e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 28).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5afa465941e3d3dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f83f7d3-99f3-4bef-b597-bc9180cc9c5a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 28).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a35e51864184ed84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74f11e3f-50d1-4978-b275-84825e2308f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 28).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e663c90851f4d565_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ab972da-a4e1-4973-9c95-b18fac805c2c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 28).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9329c09abad56d54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a07f29a-1156-4e92-a37f-ec42d4b08740', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 29).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '2354f68c964ca868_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88fda1b6-ed87-4c95-9659-6f46c7455bdb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 29).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'a03643dc5c91a8b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6898590-8800-4b3f-ace1-f2f583e9dc3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 29).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '58af97b717a47b9a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4582759-369a-4d1e-a8b3-538717219a8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 29).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '70362951c6d161a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a99060e-d6ab-4c41-aaa2-d55dd87bbbbc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 29).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '4d51fbe4e88afa52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a3a682d-8abd-4389-ad43-2d59c0b32b1a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 29).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '6fcb0f1e9b2be93d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f52d56ff-a3b4-408f-8b36-51c731c889d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 29).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '640298fec44c5116_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c86ad3cc-2389-4866-b4b1-bdbe4b301b00', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 29).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b94598b7b5603233_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('900dc7f0-f447-4d68-bcf9-0f0727c0e8ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 29).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'cf837c33b25175f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('379ac446-fd04-44e2-9362-cebbc39b6d46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 29).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'cfdb451e92ff6514_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ae91c7a-7a04-4453-9fb1-9fe12f003a93', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 29).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '954c59a7c1d28ba3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60bd4a1e-333a-4f7b-ab92-1446293e7590', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 29).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2df6f493a985d8c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24686cba-74b1-4e14-a33c-66abbc86a4af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 29).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0a18229be4f7b8c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e723c23-6117-47d4-b8d8-31fc3c804163', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 29).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a5e5aa92055c4ca3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b1c9b52-c6d3-4ad1-b3d6-48cd0062ad79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 29).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3130c0dfc39b1a28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bd7e5bd-f6b8-4688-9ce9-a0dc0889f6e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 29).', '[{"id": "A", "text": "set system host-name R11", "is_correct": true}, {"id": "B", "text": "set router-name R11", "is_correct": false}, {"id": "C", "text": "set system name R11", "is_correct": false}, {"id": "D", "text": "set hostname R11", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '68bc3cebbfe3d8e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d0365c5-0a8c-4272-afd6-2a766f92ce78', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 29).', '[{"id": "A", "text": "set user monitor password", "is_correct": false}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '0be52c3be5bb2cb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d40031e5-86fe-4234-8e78-80e9b138f39f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 29).', '[{"id": "A", "text": "set ip address 10.113.18.1/24 interface xe-2/1/1", "is_correct": false}, {"id": "B", "text": "configure interface xe-2/1/1 ip 10.113.18.1/24", "is_correct": false}, {"id": "C", "text": "set interface xe-2/1/1 ip address 10.113.18.1/24", "is_correct": false}, {"id": "D", "text": "set interfaces xe-2/1/1 unit 0 family inet address 10.113.18.1/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f35d1aebed068cd6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b53749b6-f9f7-49a3-82b3-f1cc334958a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 29).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4a05716bb5e21818_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d944f9f2-6ec8-4a75-ab87-0aee9e2b1f0e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 29).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2b1ade25fcfa3d32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79e35ad7-680c-4b8b-b51e-9696fe793ef2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 29).', '[{"id": "A", "text": "show interface et-3/1/3 monitor", "is_correct": false}, {"id": "B", "text": "watch interface et-3/1/3", "is_correct": false}, {"id": "C", "text": "monitor interface et-3/1/3", "is_correct": true}, {"id": "D", "text": "tail interface et-3/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8b60c12fcdb34088_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4321fb74-68b1-4aa6-835e-35cebfa28f43', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 29).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '10f670e0554129b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecafdad6-92db-4ab3-8085-a12c0b761b73', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 29).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '89ba872cee5530fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a825112-d389-4ca4-8302-0b788c925531', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 29).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '3f59a77abf963eb3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44109275-f84e-4d96-b55d-45cd8baac5db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 29).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '805f7d077e3232e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('faf84ccd-9fe1-4383-b1e6-9fa9ebf14f99', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.183.150.0/24 via next-hop 10.118.91.254 on Junos (variant 29).', '[{"id": "A", "text": "set ip route 192.51.116.0 255.242.101.0 10.118.91.254", "is_correct": false}, {"id": "B", "text": "set route 192.183.150.0/24 next-hop 10.118.91.254", "is_correct": false}, {"id": "C", "text": "set static route 192.183.150.0/24 gateway 10.118.91.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.183.150.0/24 next-hop 10.118.91.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '804c38ce711ae404_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52df50b1-2151-4970-9441-02f14d1c0085', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 29).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '399ee39c5fffd068_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11025cb4-59be-4aad-b826-305838d03756', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 29).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'd12b07f4b37ba45b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1554c5d3-4cd0-4546-b13c-eae0e7d22648', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 29).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0ea964074e516599_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfac3b0f-2683-431e-b284-213806ea554b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 29).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '24bca668d3537105_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18c077e2-9c4c-4e38-a130-04d2ef91f197', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 30).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'fc60134dfe95550b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dd668ee-e416-4bda-b2f5-6f065d0f7938', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 30).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'ab7288178abc8147_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d7d03ae-7c53-4acb-b0d8-954734428a59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 30).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '7cf2565b0876af68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd143462-7482-4e3a-9280-71acf8cc546c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 30).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '261924c70260934e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b451d9d8-3b5f-4ac1-b3dd-fcebb0fec73b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 30).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'e692f542f1093d9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7eda9e34-4edb-44ec-9d7f-4352bbe2076b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 30).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '3efcee009a7c02a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cb7dab6-10c8-41e9-9fcd-7af72a807349', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 30).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b03b9f835ccc6b9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a311673-d9ec-4ccc-8ddb-9ee07125a801', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 30).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f5ad31d03d02f423_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c41d41b0-85d6-41b9-8229-11b6d47fae07', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 30).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7357f90ce373ada7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05926d36-1b3a-4cd9-bfa2-5dd766fad610', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 30).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'fc026aa444a6374a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f157617d-1091-41c0-8806-4f07c978eb68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 30).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '98be4ec33d4736b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0d5e763-f36d-4b91-9e3e-997af9e9daed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 30).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2a62894834631542_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c067ef2-0897-496f-9173-db774f4bfc3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 30).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0748b5ddcc673d7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66b866de-f13d-4253-8674-5d40346f2a6e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 30).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3a05fa77c810d99c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea46b6c3-43bf-42b5-9d1a-390752889509', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 30).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '496bdaa87270baca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75b0caad-5609-4a86-8121-0fe753800c6a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 30).', '[{"id": "A", "text": "set system name R2", "is_correct": false}, {"id": "B", "text": "set system host-name R2", "is_correct": true}, {"id": "C", "text": "set router-name R2", "is_correct": false}, {"id": "D", "text": "set hostname R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '17b1d45448cad955_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8a7d1fd-c4b1-4d2d-a007-333db2af0359', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 30).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'cc127ba76e62c2db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('427a5a4c-c2bd-42a3-8775-011030e1c04b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 30).', '[{"id": "A", "text": "configure interface ge-1/0/3 ip 10.128.17.254/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.128.17.254/24 interface ge-1/0/3", "is_correct": false}, {"id": "C", "text": "set interface ge-1/0/3 ip address 10.128.17.254/24", "is_correct": false}, {"id": "D", "text": "set interfaces ge-1/0/3 unit 0 family inet address 10.128.17.254/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'e4f0fac30f0f966e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4966225-91db-4cce-8521-c3d5196c82ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 30).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '416433361c7d6b3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a37a815-dfaf-479e-9829-2147a87b05de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 30).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '87371444b4137485_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17e81c78-15db-4a8e-aede-e6c7619426cd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 30).', '[{"id": "A", "text": "show interface xe-2/1/1 monitor", "is_correct": false}, {"id": "B", "text": "tail interface xe-2/1/1", "is_correct": false}, {"id": "C", "text": "watch interface xe-2/1/1", "is_correct": false}, {"id": "D", "text": "monitor interface xe-2/1/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b5bc3e4dbdcae03f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39fc1a46-e82c-4da3-b611-672c7691889a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 30).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7d332cf7851d98ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ab1c9be-0719-4548-a68c-f45583f3f31b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 30).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2314fe32755ab182_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec27d039-7ba6-4a08-8795-b34915e31491', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 30).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '7183c5d69a5770b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04b31c02-6dea-43c8-9210-75691eb77521', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 30).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '00868b6458dec7ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71bac406-54dc-46f4-b232-50268dd49cdf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.90.0.0/24 via next-hop 10.194.6.5 on Junos (variant 30).', '[{"id": "A", "text": "set routing-options static route 192.90.0.0/24 next-hop 10.194.6.5", "is_correct": true}, {"id": "B", "text": "set static route 192.90.0.0/24 gateway 10.194.6.5", "is_correct": false}, {"id": "C", "text": "set route 192.90.0.0/24 next-hop 10.194.6.5", "is_correct": false}, {"id": "D", "text": "set ip route 192.193.195.0 255.153.227.0 10.194.6.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1b9b12b24ad30ad0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c5745b5-cd67-4e29-989b-0c4c7c64c37f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 30).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'a95eea6655439cc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07a08027-b604-4b9d-8dea-1726647f8735', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 30).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'c8081e29e66ded77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8990f15e-4149-4174-91ef-d861ec329a33', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 30).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '369da84dfe92c59f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43c24122-fdc4-4787-88bf-4a67b0d6dc55', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 30).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '99bfe08303b0a296_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ab5fd40-728e-4f51-af60-d3d6a57a39c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 31).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1535e7a15525757d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91716730-6134-458c-aad4-77651f3ee391', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 31).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '294300cf3a726b5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d9c19bc-236f-46f6-bd9c-f11eefda2b75', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 31).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'd8d510b21f61bc14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fd70020-8f62-4fb2-aa4b-689a10bc3363', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 31).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4de9fcaf8601e620_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef7127fe-4f8b-49f8-95e5-856949e8d44c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 31).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '3e0cd8715f75d03a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2022f4f-ace1-46f4-9e78-1fa66b5698fa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 31).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '06f5e7eec53f5737_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eb99120-8cd2-4fab-9c7a-181304c7e740', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 31).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd504b411025140b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('526a6c6d-c1aa-4862-9d68-cb122174a382', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 31).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '39a549eb31a0616f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a5f5146-0bba-400b-bfe1-cd9bc638114c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 31).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '783cb3b41d8d2c53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8d55744-743d-4388-8baf-d346035fb3a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 31).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e1457971f4cebeda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('291c2afe-d2b1-41e3-a4b7-5870a884d80c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 31).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'bbd5bf21bb15744e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7023c40f-c5f9-4fd0-baed-b87851713d46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 31).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'cf74d82f5dcbebc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('841af9e1-f05e-47ce-bb60-8ce2de2346ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 31).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '3e622541711b9a67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c66ab34-a8b7-4d70-bc8c-b788c37db81f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 31).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ca7eec3cc65d05d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92942073-466c-44a2-8d77-70368f622e0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 31).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3f2589f694ef0356_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f83e4f1-dd3b-467d-b200-8b59207a4f3f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 31).', '[{"id": "A", "text": "set system name R12", "is_correct": false}, {"id": "B", "text": "set system host-name R12", "is_correct": true}, {"id": "C", "text": "set router-name R12", "is_correct": false}, {"id": "D", "text": "set hostname R12", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '508100aedd567c29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c398be0-aaec-460e-9fb2-1b6ae060eb5d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 31).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd9ab62f9c3c2c6de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecdd68e9-003d-4f90-a416-7b1a82af413e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 31).', '[{"id": "A", "text": "set ip address 10.172.114.5/24 interface ge-2/0/1", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/0/1 unit 0 family inet address 10.172.114.5/24", "is_correct": true}, {"id": "C", "text": "set interface ge-2/0/1 ip address 10.172.114.5/24", "is_correct": false}, {"id": "D", "text": "configure interface ge-2/0/1 ip 10.172.114.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '12a16facee0c9e15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5778712-5629-4645-9138-4a2c5105d58d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 31).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '69af4f68fa479762_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('529cc991-c30a-4a00-b99e-78d03bf23241', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 31).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'bb7ec28de1609724_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0d457c6-af6a-4041-9d23-75a5dde55775', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 31).', '[{"id": "A", "text": "watch interface ge-2/0/0", "is_correct": false}, {"id": "B", "text": "monitor interface ge-2/0/0", "is_correct": true}, {"id": "C", "text": "show interface ge-2/0/0 monitor", "is_correct": false}, {"id": "D", "text": "tail interface ge-2/0/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '40f59bad7fcb5d91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('321306e9-eb7c-4eea-95bf-5b8ff8f7c24e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 31).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '44651c065abd7eb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a25e217-f268-445f-b28c-3692dfd8b4eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 31).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f0c0a386dff3bbce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5123161e-2ddf-4997-9c30-68cb70db6033', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 31).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'fa8ce2683033e19e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b422c99d-16a0-4c97-a588-88528c40c5e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 31).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '48b7429e10d54cc1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48e71d8e-14eb-4441-b594-374d76279b07', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.220.172.0/24 via next-hop 10.244.106.1 on Junos (variant 31).', '[{"id": "A", "text": "set route 192.220.172.0/24 next-hop 10.244.106.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.220.172.0/24 next-hop 10.244.106.1", "is_correct": true}, {"id": "C", "text": "set ip route 192.94.150.0 255.151.204.0 10.244.106.1", "is_correct": false}, {"id": "D", "text": "set static route 192.220.172.0/24 gateway 10.244.106.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1cbb0e93e6fb642a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b36aa99-57cb-49e6-95a6-e9b59ad4c067', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 31).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'f864bf772e2cb514_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efbbffce-f8b5-443d-b7eb-8372eb06a808', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 31).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f6f82618b5484047_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1214f1bf-b7e4-4426-bb33-1a6b6c8153e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 31).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '40954b69fb59be53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('027697b9-b3a1-4d88-8e4f-90d83385a1b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 31).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2afaf80f76b32d41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cdfe445-d676-444d-a253-3b2344beb2ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 32).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6a8cb6c0219ec466_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0bb6c00-4d1c-42fc-b824-ef52c7c2933d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 32).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '9895e7232d2e88bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbd6ace7-b1a9-4d4d-b395-b2f0f09dbd52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 32).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '29b62f7264338f41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('832311e5-9108-4dfc-b0e6-a29c55dec7a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 32).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '1e5e9f3774ad6993_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a13c2d9-99f0-4cb5-a016-78d77fb3dc6b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 32).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '73ad4f65972bcb6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cb39d05-bb1f-4f20-b1d8-1d1db685bbbc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 32).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '863d39f884b81110_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9887327-0a71-4f56-bce5-c3b354e03043', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 32).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '387ad9749de61193_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eae354cd-5ac8-4a19-86a1-bee0a96c26eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 32).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '749e641febcec93c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce625309-5888-4621-b283-2be1f19d5b76', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 32).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '98d205b122cba6e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcbf5f4c-e15e-42bd-99fe-b793c623f43b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 32).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '8d0b9901c878cbd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5aafd1d-04f0-42fc-a322-a503c82f134f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 32).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '90646ae1d15d72b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44b4f896-0d59-470c-9802-bbf5ec7f5704', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 32).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '5077571ab96e8b78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fc130a7-5421-467d-865c-b08f039df792', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 32).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '08926e859d3c5a2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('668b515f-9831-4f88-926e-155066c2fa46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 32).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '23cba49879ff8a08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b4b48b7-4de0-4dc6-9706-4af7bedcdd69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 32).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3fd3beedc8043061_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65540416-75fe-498f-aa65-5a57e2588f22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 32).', '[{"id": "A", "text": "set router-name R7", "is_correct": false}, {"id": "B", "text": "set hostname R7", "is_correct": false}, {"id": "C", "text": "set system name R7", "is_correct": false}, {"id": "D", "text": "set system host-name R7", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '32343b9f8bc4985d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8a1f2d9-0f71-45e1-9483-1b56dd742dc1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 32).', '[{"id": "A", "text": "set authentication user monitor password", "is_correct": false}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '321cbb2332503dd7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f92c125-f9c7-4bb9-9260-0ac8ca2f06e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 32).', '[{"id": "A", "text": "set interfaces xe-0/0/3 unit 0 family inet address 10.90.223.1/24", "is_correct": true}, {"id": "B", "text": "set ip address 10.90.223.1/24 interface xe-0/0/3", "is_correct": false}, {"id": "C", "text": "set interface xe-0/0/3 ip address 10.90.223.1/24", "is_correct": false}, {"id": "D", "text": "configure interface xe-0/0/3 ip 10.90.223.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '23dc57fa0296a2a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a3336de-9d95-40da-a3c1-d6e7bf335bdc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 32).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a30edc79648a8530_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('894834b2-9fa9-4bdb-86f1-0fca9f7e383b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 32).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ab0e9c0e600ef1c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae55319c-279d-4ec8-9e40-35893d4cfc8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 32).', '[{"id": "A", "text": "watch interface ge-2/1/3", "is_correct": false}, {"id": "B", "text": "show interface ge-2/1/3 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface ge-2/1/3", "is_correct": true}, {"id": "D", "text": "tail interface ge-2/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7f501bfe14b1520e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5dee9ed-549e-408e-9949-000066a5490b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 32).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'cab335aba5b87cfd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51b3e2cd-2c16-4163-abf4-8e73e9ba34de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 32).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '72672208d8dcc5fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('436be807-95b3-4e05-a6fe-565060e89f59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 32).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '20740becc719a074_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b45ed923-eb89-4edf-bd28-04248c2fa654', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 32).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a15a93310c081048_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e153e871-de42-4b26-a6b9-e76eb2fa39de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.161.146.0/24 via next-hop 10.91.121.5 on Junos (variant 32).', '[{"id": "A", "text": "set ip route 192.95.6.0 255.170.176.0 10.91.121.5", "is_correct": false}, {"id": "B", "text": "set route 192.161.146.0/24 next-hop 10.91.121.5", "is_correct": false}, {"id": "C", "text": "set static route 192.161.146.0/24 gateway 10.91.121.5", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.161.146.0/24 next-hop 10.91.121.5", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'dbc506cdefcee9ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e4f991e-8851-4d02-97f0-dd7f0be6c331', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 32).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'b4f35ae3c2aedd7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb501142-b1ac-4375-8618-f3ac01872d80', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 32).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a74587b4b4593f2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e61a3f3e-7693-4f47-8fed-cb0ad0e8bb4e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 32).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b47765bcafa9af31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a0ce8ca-05bc-4a46-b00b-0dd86e7d1cc9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 32).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '44c763c8fb113903_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adde214e-ce58-4b05-a43f-ec66559f6c26', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 33).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'ff1474ee7f437d3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a834411-e6a6-4e30-b9c0-faf242b10a45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 33).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '3edc702a29c4c755_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb31c1ae-7df1-4758-8bc9-7f2f31f3d9ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 33).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '729f0e1f1172b69e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62baafc0-4516-475b-8028-bb17b895a0bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 33).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '9ffc1e19f2eb9150_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6168e411-41c3-4114-9769-2d87500ff927', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 33).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '5b8598daafedb4c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13cdf5dc-9338-425d-9a27-80ec2fe4953a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 33).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b3f435a5e4d0fb01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1ebfdd0-f0f7-45bc-8cf8-a3173bc19235', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 33).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'cb21cc38147e3f2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4542362-c4f7-44dd-8c48-1208cde14620', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 33).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'af6e2758393bba3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81804ecc-afa8-4cd5-bee2-e49a726e2b68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 33).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e7e59ef30a8ad45f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffecddf5-0efb-4c23-adff-4e67fe7ed2bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 33).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '71d5bd0cb7e68eec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e65d5529-4fd7-406a-b15e-d545548d5028', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 33).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1d128684539a2f64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38284998-6a6e-488a-9531-1ab5410b4fef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 33).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ccc7c6b7c998760d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eff1f177-ff5f-475d-b594-764e54a07e59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 33).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f68e6cf75bf9822f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dc04bd8-7f0f-44b3-960e-9ca1a167c221', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 33).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fd152cfa848ea9c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68012a65-b725-49d6-a972-975ffdd65f34', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 33).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6a9b3f95ae6ff309_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd8d5434-e947-4b43-a574-a4d2e8c0098a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 33).', '[{"id": "A", "text": "set system name R2", "is_correct": false}, {"id": "B", "text": "set router-name R2", "is_correct": false}, {"id": "C", "text": "set system host-name R2", "is_correct": true}, {"id": "D", "text": "set hostname R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ae871d1335de9433_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ab17666-b50c-4a70-9eb8-4c9cf34c2d3e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 33).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '102fbb460f5e347b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34cd8c98-4729-49bb-ae6a-3ad3cf8066e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 33).', '[{"id": "A", "text": "set interfaces xe-1/1/2 unit 0 family inet address 10.219.63.1/24", "is_correct": true}, {"id": "B", "text": "set interface xe-1/1/2 ip address 10.219.63.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.219.63.1/24 interface xe-1/1/2", "is_correct": false}, {"id": "D", "text": "configure interface xe-1/1/2 ip 10.219.63.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '64af6b136249994e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0be5c927-b114-419b-beed-383f54f959eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 33).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '515e35b99ef22d09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('080103be-2c3c-4a23-b602-eabb05e8aac1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 33).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'eab63df9d169d115_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('048ab52f-8603-4959-a489-0fc2a3029d9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 33).', '[{"id": "A", "text": "tail interface ge-2/1/2", "is_correct": false}, {"id": "B", "text": "watch interface ge-2/1/2", "is_correct": false}, {"id": "C", "text": "monitor interface ge-2/1/2", "is_correct": true}, {"id": "D", "text": "show interface ge-2/1/2 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '996c576fa9c52e29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e82cb3ec-220f-4c4f-ad0e-76fe60198e89', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 33).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b9cbaf1efdd39594_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('772692b9-103f-449a-8756-decf91e041e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 33).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd8c74e6ca2d66c27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ea1b898-a409-4428-9fd0-38a571505d40', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 33).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'befa6b3d3c801005_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('511ace30-1e44-4c2e-8f6d-fda50dd42e74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 33).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'fcfacd4a50b1be70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf69cde2-afa9-4ec4-944e-552fe978fa21', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.76.93.0/24 via next-hop 10.39.204.5 on Junos (variant 33).', '[{"id": "A", "text": "set route 192.76.93.0/24 next-hop 10.39.204.5", "is_correct": false}, {"id": "B", "text": "set ip route 192.25.6.0 255.252.203.0 10.39.204.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.76.93.0/24 next-hop 10.39.204.5", "is_correct": true}, {"id": "D", "text": "set static route 192.76.93.0/24 gateway 10.39.204.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '287af1bfab87a54e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0209ab18-74a7-4dd4-8e33-fdadc585ccd3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 33).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5614da9faec31a29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9040dcee-8d33-4665-924f-521d9bd57d1f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 33).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '0420a1b38d1fe311_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d87206e7-a10f-446e-ace0-965e93d84f8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 33).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4aaee16882ba15f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52a3f53b-a654-4827-94b7-362ebb6656b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 33).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '08060b7811af7ca7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2fc1453-40c9-4e89-a0b0-320136d09a9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 34).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '564fe0ff76e3d602_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('945c41f0-520d-4942-9eb1-57013a4fbadc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 34).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'be285d862c3f63ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d115cadb-3b96-4558-a8e6-23a3d0acc11e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 34).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '4e38d281fb2ebe41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('835aab46-160a-464b-a7e6-bc81f8b2a70b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 34).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '18ab0163a7bc666e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7817c28-51bf-4509-ac24-a45750507a7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 34).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '7dd11fb53e67cf52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3b7a50f-e296-40ef-a432-3bd8dc1dc029', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 34).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'aebda6367b806471_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47c11b62-6742-426b-be30-50849bb49cab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 34).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f31619aa614abad5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('239676f9-aea6-43d7-a867-10e430aa65b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 34).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '07fe46d234fd02e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6dead62-c264-4b04-a961-8a1aad53baa7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 34).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'dd4fdf4192d3bd20_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87c25223-49e1-4558-87c2-24f6aa2362bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 34).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '407ca22c1eb9c9bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('108be1d5-7061-49d4-b8ff-56c258e433be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 34).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '64f4f0546d29e599_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7683fb48-6434-4d12-ac69-cba6b3d1b547', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 34).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2c37321674577d2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df64cdd6-4cea-4420-b8c6-a7be72d0ee5e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 34).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b9b0a9f772b27007_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a9de0ea-9bd4-48be-acc4-e36a6eb62d31', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 34).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '70d59b4f336211e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b30dc0d4-681c-4a48-bd08-6e8a36b5e30a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 34).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '20bb7644d675c3c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f14dc1c5-b440-4a84-8f48-b72f83f22073', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 34).', '[{"id": "A", "text": "set system host-name R6", "is_correct": true}, {"id": "B", "text": "set hostname R6", "is_correct": false}, {"id": "C", "text": "set router-name R6", "is_correct": false}, {"id": "D", "text": "set system name R6", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a79ae9c2762b5c0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00015203-f307-4a70-9ebb-58d995c21a00', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 34).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '534390411855801f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26c07818-bf2e-4d67-ac6e-b1e192f84b79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 34).', '[{"id": "A", "text": "set interfaces et-1/1/0 unit 0 family inet address 10.19.196.254/24", "is_correct": true}, {"id": "B", "text": "set interface et-1/1/0 ip address 10.19.196.254/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.19.196.254/24 interface et-1/1/0", "is_correct": false}, {"id": "D", "text": "configure interface et-1/1/0 ip 10.19.196.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '921f3f8264482645_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22952b7d-cc61-4d63-aadf-f087445eea72', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 34).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd76bd9f283079b58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('707421cf-ab94-4ef0-91d7-3ec4e8464285', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 34).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f0f7a6fccf707dc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d490e225-e36a-49af-aa5f-809cac0b0a4e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 34).', '[{"id": "A", "text": "watch interface et-1/1/2", "is_correct": false}, {"id": "B", "text": "tail interface et-1/1/2", "is_correct": false}, {"id": "C", "text": "monitor interface et-1/1/2", "is_correct": true}, {"id": "D", "text": "show interface et-1/1/2 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '85a2b5c705e2745b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b52d3a5c-0b88-4e5d-b986-a1e5ffb76e36', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 34).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '57a388b85d1b6993_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0b70bd9-829f-4aa7-ace2-7cf9708f7a7e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 34).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '159c5e68a20a4f4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6645553c-ed31-4ef2-a2e1-24e080503d5a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 34).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '38fd701e0bcd81e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('556a2606-0204-41fb-96a0-d31790764d88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 34).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'af5be16d4d14eb9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78adfe1d-79cc-4c3c-9adf-1b73a3bab130', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.224.148.0/24 via next-hop 10.133.236.254 on Junos (variant 34).', '[{"id": "A", "text": "set static route 192.224.148.0/24 gateway 10.133.236.254", "is_correct": false}, {"id": "B", "text": "set ip route 192.195.194.0 255.48.65.0 10.133.236.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.224.148.0/24 next-hop 10.133.236.254", "is_correct": true}, {"id": "D", "text": "set route 192.224.148.0/24 next-hop 10.133.236.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7b38185e8e396499_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b25c1df1-9287-4ae8-8360-9c0d48bb398f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 34).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '9f2e20da40494d58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cce6941-fee5-47ef-8c36-e3d2c0bb74ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 34).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a3aeb7f2150a2f22_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b659a4d-bbab-4207-afbd-63230727e9ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 34).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b4f10cc898031689_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6dea36c-fb37-4c29-84bb-18e3cb70c44f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 34).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2ecfda554cb415b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bab96997-aaa2-4eee-98d0-cb69abe34560', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 35).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'f0fa3ce2027f3b8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a39543a8-62ee-4422-bfa7-5ce6f1d2ff31', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 35).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '58656857d07f2339_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07fa9199-4ad1-4662-81af-3f6ce6e6a9d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 35).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '08a03b2c75c0b110_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a01b4967-3f86-4204-a2ff-a892184bab17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 35).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '9c707cccc5286d36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eeebdc65-d457-4dd3-9e51-e8bf9d6397bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 35).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '47f5ee6c733bdf36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b884e102-de3c-4293-a7b5-ba515bcb0830', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 35).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'f8aaa581169609e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('585bae39-5501-4577-aef1-5b031a1be003', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 35).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7b968b263fdc500c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79fd202c-eb99-4f01-96bf-77b72b7fc094', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 35).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8c893d120957d31c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6a239f5-6c1f-4f39-b3b3-e78186446f3e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 35).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e988f58b6f25fbbb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d42e6ee1-72d7-492e-b67b-05a0f9854d8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 35).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '7588c0d360aa26c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa44d193-1443-413a-84d7-555f1aa82d89', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 35).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2f64883a89d52449_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f639a60-f731-487e-bae2-a40505a3357a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 35).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '6b584925040f531b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36ae92ec-ecdb-4219-80ac-9dbbad9d3a73', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 35).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1081fe516f791c29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c8fc91b-23e1-43ac-89ed-5cd6b1cf7f23', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 35).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'bd408b226b0f6c36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93dbf58f-23e1-42ea-8925-dcfedcb5674a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 35).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'eb2bf2feb130f573_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca97a83f-cf16-419c-ad9a-3b3ebd8eb072', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 35).', '[{"id": "A", "text": "set hostname R4", "is_correct": false}, {"id": "B", "text": "set system host-name R4", "is_correct": true}, {"id": "C", "text": "set system name R4", "is_correct": false}, {"id": "D", "text": "set router-name R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '1441152a933af566_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1c6523d-4c3c-4887-8675-f45ec7b25f3f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 35).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user root password", "is_correct": false}, {"id": "D", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '467cb3d312b854e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2eed4bb1-5e85-4ccc-89fa-53221154b072', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 35).', '[{"id": "A", "text": "set interfaces et-2/0/1 unit 0 family inet address 10.153.218.254/24", "is_correct": true}, {"id": "B", "text": "set ip address 10.153.218.254/24 interface et-2/0/1", "is_correct": false}, {"id": "C", "text": "set interface et-2/0/1 ip address 10.153.218.254/24", "is_correct": false}, {"id": "D", "text": "configure interface et-2/0/1 ip 10.153.218.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f5947872736eae76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8349637e-6969-48d5-9573-6fab917f0eab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 35).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7d7d8f5eefcadc10_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e90a591e-9f10-4865-ad07-4bdc7b31683c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 35).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6577bf7da6c2f583_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9884cf24-5565-4f5d-9ce8-992b18b9700c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 35).', '[{"id": "A", "text": "show interface et-2/0/3 monitor", "is_correct": false}, {"id": "B", "text": "watch interface et-2/0/3", "is_correct": false}, {"id": "C", "text": "tail interface et-2/0/3", "is_correct": false}, {"id": "D", "text": "monitor interface et-2/0/3", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '007eebed71b20d0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7458825-6b99-4ba3-86ff-0d88baff072f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 35).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '92b2284d6ffaf909_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87b814f8-9f7c-42d2-90ae-a73eed8c813e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 35).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5be83123ae4ad9d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2443c59-4070-48ab-9782-acbfb5b1c781', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 35).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'faa9f9d28bdd9420_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1efbf8c0-3a5f-41a7-af21-49282e87ba4c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 35).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '001f38f35e317116_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c73cf6b-dda4-4dad-bb36-08e99ab8eb1b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.25.186.0/24 via next-hop 10.24.34.5 on Junos (variant 35).', '[{"id": "A", "text": "set static route 192.25.186.0/24 gateway 10.24.34.5", "is_correct": false}, {"id": "B", "text": "set route 192.25.186.0/24 next-hop 10.24.34.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.25.186.0/24 next-hop 10.24.34.5", "is_correct": true}, {"id": "D", "text": "set ip route 192.25.65.0 255.95.208.0 10.24.34.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'db6377bdda1c663a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f834aeb0-c88d-4d94-bcdd-e20dd86f3e23', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 35).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'ee7fcbc4e3bd8b88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f77812c-e759-4ae5-941c-274e1e06794f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 35).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '207d4a0cbf424a69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9553b871-74bf-47eb-aca1-81840e49655b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 35).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8030bda2b11e3a0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82db6ba1-9543-4235-8200-96455d81f23f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 35).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '32a7f10fa0e1d246_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('876623ce-94d3-417f-9498-ae13efaa81c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 36).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'daaf44fb3155175e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b7d9e7f-1237-4526-9613-404dd7174112', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 36).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'b30437989b32d77e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('703d99c3-00e4-4a82-9c8a-1da0899a96ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 36).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'eee17eb3802e030d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67f5bdaa-ffd7-45d6-84e6-21ec9274f5f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 36).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '1396673ca03a45c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57066ade-b175-425a-ad90-cdda9d9e5718', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 36).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '40cefa61fc525573_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a1484d6-f5d9-4649-a05f-b88c63a00daa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 36).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '2dc6207fc9959a41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1b1f220-dd22-41c2-8e53-80edd246b658', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 36).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '66ead7dd74009041_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f26cf29-bdf6-47ae-be22-ac6700a5368d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 36).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b6411dd0410d199e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99d17230-4295-45ff-8180-416123955a04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 36).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ba70be45fcadbb8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('255eb6c7-1397-4270-ac3d-f971727a8f25', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 36).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'c2a0d88b8cc0c0f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19df49ba-648e-4eae-99c6-c8cf451546f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 36).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b36bc107887221d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84ccdb22-26cb-4ed5-94e3-8ae4263863a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 36).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '15de4e57fb6ef643_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e5baee3-b3dd-4c85-b9a4-77f993b0c5f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 36).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'dd2b2d153c49e82d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('090df21b-be44-4e67-acc2-39389addab3a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 36).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1438b5584f1de85a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0125fc5-f443-4dcf-8baa-fc162d8755e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 36).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4a06ed4fe6510199_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e702ac1e-ee95-4044-b0ab-28bc0d8bc98f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 36).', '[{"id": "A", "text": "set system host-name R12", "is_correct": true}, {"id": "B", "text": "set router-name R12", "is_correct": false}, {"id": "C", "text": "set hostname R12", "is_correct": false}, {"id": "D", "text": "set system name R12", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '52c157c809893b90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5810c1df-3a76-41c9-b7af-dc94d1bf2602', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 36).', '[{"id": "A", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6e00c98964af6889_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca676cfc-4d5e-4d26-8d44-028d15fdc877', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 36).', '[{"id": "A", "text": "set ip address 10.148.13.254/24 interface ge-2/1/3", "is_correct": false}, {"id": "B", "text": "set interface ge-2/1/3 ip address 10.148.13.254/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/1/3 unit 0 family inet address 10.148.13.254/24", "is_correct": true}, {"id": "D", "text": "configure interface ge-2/1/3 ip 10.148.13.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '6a4c90b7594ed2e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('396da6bc-8980-4045-aa0a-64d1dda0deed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 36).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd3061cf1b4bb1f91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec2ac3ab-fc29-4d53-8cc6-cb817c5a4c33', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 36).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '51bdaf780f4e30da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8a4f3dc-1d79-46ad-8b9c-cc34aaadc5e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 36).', '[{"id": "A", "text": "monitor interface xe-2/0/0", "is_correct": true}, {"id": "B", "text": "tail interface xe-2/0/0", "is_correct": false}, {"id": "C", "text": "watch interface xe-2/0/0", "is_correct": false}, {"id": "D", "text": "show interface xe-2/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c36641536142317c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee788e88-127a-4ef0-98d2-d0bbea617a2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 36).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2294bf994feee263_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61a71b24-820d-4cf2-8883-46c0b735d2f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 36).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '74916cf230f3b894_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70be3e38-e978-4214-9034-0f5eae263450', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 36).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'e6eaf8c8b48a8ee9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b144ca3-8a02-4889-9c5d-f9fd94e0a1bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 36).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7c8caf96e6e16296_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3a71b5d-b01b-4b49-8f2e-f6a745826a68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.160.187.0/24 via next-hop 10.195.104.254 on Junos (variant 36).', '[{"id": "A", "text": "set static route 192.160.187.0/24 gateway 10.195.104.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.160.187.0/24 next-hop 10.195.104.254", "is_correct": true}, {"id": "C", "text": "set ip route 192.229.178.0 255.198.224.0 10.195.104.254", "is_correct": false}, {"id": "D", "text": "set route 192.160.187.0/24 next-hop 10.195.104.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e785d9b2775c5c77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a55cd326-5d63-4de9-a30d-25bb868bf772', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 36).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '6c328bb0651609d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13621a89-8509-4d53-9399-9ca3e882ad96', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 36).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f492bcca3c143917_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d6e8603-6cf2-4b88-b79b-43c387bbb866', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 36).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ed7a900a27e8b313_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('965b2745-b3ed-4cad-853a-67460166208c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 36).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'aa1629018db1c969_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34a71210-418b-41d2-ad5b-7a7d151551f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 37).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1bb51b5dd7a8beb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09c3a44f-1ba1-495d-9533-61f1d195a75b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 37).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '051825ac1054cb6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2639ada3-9d88-4b2c-8a25-f74102317007', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 37).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '6260aafd9ea2cc8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('711ad2cf-ac6e-49f0-bf84-e57795e24642', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 37).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'b00740ae390c840b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df829286-0b38-45d7-95d3-a0d3cd0dfee3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 37).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '50be4f6fe7a97580_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f102568c-ccf9-41ee-8fe4-98df92ff7cd5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 37).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '607ed4cd00e3a05a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b377b88d-7bb0-4274-8021-0bd655719389', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 37).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8cdd3bd16bfb5ceb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9d4c77d-ae74-44b5-b1e8-a0f80c507e41', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 37).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '68112a676c7bc251_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81e9c150-275a-46c1-9b4d-5a0b95ac31f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 37).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f6c9900cfdedf11a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30f020e9-05c3-4ed2-be85-7770a22f18c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 37).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '8b8428dfe4daa457_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('561cf311-028b-4eed-9df4-148d83338335', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 37).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a4b3d3efe2bf305c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5f57fbd-62a9-40aa-b937-7359fa1d804e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 37).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7b827f0449b6d691_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e01f7f8d-ffae-4f75-9964-ec214902cb2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 37).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a9b353dd3b7e3d89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('502244b5-dc5f-421a-aace-f5c046e983a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 37).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'cf6805dd094c776f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('703da4bf-bf97-49f9-b05f-1a9ac5cd0d52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 37).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '22dd93ba7527aca0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b58a03a-09c4-4fa1-a914-34f883111f8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 37).', '[{"id": "A", "text": "set system host-name R11", "is_correct": true}, {"id": "B", "text": "set hostname R11", "is_correct": false}, {"id": "C", "text": "set router-name R11", "is_correct": false}, {"id": "D", "text": "set system name R11", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5a3c674e1ee11094_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56c31a78-b874-4a93-a2ae-5bad8bae8944', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 37).', '[{"id": "A", "text": "set user monitor password", "is_correct": false}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '322d6300210c707e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db21f612-b65c-48d6-b675-578986dbc93c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 37).', '[{"id": "A", "text": "configure interface ge-0/1/1 ip 10.156.222.254/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-0/1/1 unit 0 family inet address 10.156.222.254/24", "is_correct": true}, {"id": "C", "text": "set ip address 10.156.222.254/24 interface ge-0/1/1", "is_correct": false}, {"id": "D", "text": "set interface ge-0/1/1 ip address 10.156.222.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '8bdf34d055f45b57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26c6e6d5-971a-422f-8b38-9a6fb8b75eeb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 37).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1a6370b2038b3a0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a56efba-3f57-4654-8e37-f5c6a77565e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 37).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5280a891dfb13649_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80f2dcf1-eb62-4ffc-8369-3abfeaf37d5c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 37).', '[{"id": "A", "text": "watch interface et-2/1/1", "is_correct": false}, {"id": "B", "text": "show interface et-2/1/1 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface et-2/1/1", "is_correct": true}, {"id": "D", "text": "tail interface et-2/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd3af8656a0182f72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4fe3deb2-9f76-4e01-9ca6-a2cf57b5afc6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 37).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ecf08d018e33a342_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95ccf4a4-8dd5-4ae9-92b3-b0a206b49f0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 37).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a16f6f41da0c5db1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52b7bae9-e0f1-4daa-b85f-3849e1fdbb23', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 37).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '8b53fa8cf28d31f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c79cf9ae-7120-402f-b2c7-2b0f14bc537d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 37).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'fbf6b9319987694c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('faa1c315-2186-4cc6-b050-028796156555', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.7.137.0/24 via next-hop 10.32.96.254 on Junos (variant 37).', '[{"id": "A", "text": "set route 192.7.137.0/24 next-hop 10.32.96.254", "is_correct": false}, {"id": "B", "text": "set static route 192.7.137.0/24 gateway 10.32.96.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.11.127.0 255.232.165.0 10.32.96.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.7.137.0/24 next-hop 10.32.96.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ed18c4bfdbf0ff36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af86d743-1787-491f-b0ba-082a90498922', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 37).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c25d5c5fb6525c0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be2d0732-dbf7-403e-aa15-b33161e08886', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 37).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '9cb82954699d25b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d2439fd-d884-4011-8fa6-fb2e3a2b72ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 37).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '60f45cfe63ad86a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0b78488-5745-4dff-8d30-32746931274a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 37).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2c9c3144ef29bff4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f7c8dd6-0639-4010-8c98-7384a60fbf8c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 38).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'ad1fdb74db6b04d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ab8fc6b-4fb1-47a1-a9da-ae07157c7a75', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 38).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'de2015168105fe31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c8f55ea-96e2-4b7f-82f0-eecb47a416b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 38).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '77533efadfc4bb3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f19ec44-2283-4e51-b83a-57fa90c05984', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 38).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'd0bbbc1412195a2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16f7757a-28fb-4394-a33b-1a76f2fcd47b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 38).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '5a823f10c58bf619_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bebf225-80d4-4c91-9c02-5f2cd14e17b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 38).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'ed65a80c125501cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f7dcab0-471d-4dd8-aa68-5b303b456834', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 38).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd8dfb5fe231246f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a694fa3-bce5-45af-9239-ed320be544ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 38).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '34e8fbb0569c1587_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fc531fb-ba8d-4453-bcc0-f8fc43d2a420', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 38).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'eab66ca1465b1939_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bde9b2f6-df8f-4b77-a4c7-21df505d94f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 38).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'a73ce5bf2f8bbade_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46a26e6d-39d8-4db9-b4b4-802e9b85a9ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 38).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'dd898290f848d97d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10abc800-c1e9-4cd4-88c1-fde2d611f68d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 38).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'dc0dafc73b4dde4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7160159a-b8b5-484f-8214-585bdd6e8a33', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 38).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'affa9a8acd678e2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd0dfbd2-d6fb-4209-b62a-b8923a0ff8c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 38).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e618d750f29f2212_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb4644c5-94cf-4040-b7bb-5932f7480bad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 38).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f2ad38a9e3dac1f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef28ef5d-c75e-4a67-b678-2ae04ef7f7d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 38).', '[{"id": "A", "text": "set router-name R4", "is_correct": false}, {"id": "B", "text": "set system name R4", "is_correct": false}, {"id": "C", "text": "set system host-name R4", "is_correct": true}, {"id": "D", "text": "set hostname R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '17b20c87f936c7c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b40e2eb-f1c4-4639-92cf-95f977bf8f6f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 38).', '[{"id": "A", "text": "set authentication user juniper password", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b0ccfb1e643ff8fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30c56322-5533-47c3-acdf-9abab0a11592', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 38).', '[{"id": "A", "text": "set interface ge-1/1/3 ip address 10.109.156.1/24", "is_correct": false}, {"id": "B", "text": "configure interface ge-1/1/3 ip 10.109.156.1/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/1/3 unit 0 family inet address 10.109.156.1/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.109.156.1/24 interface ge-1/1/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'bc0b4914224ee117_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d95f3a4d-7281-4267-91f4-4fbb80865384', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 38).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '28326929eae5ed1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db7d1151-7c3e-4d9a-8d7d-8e3b07414e9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 38).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'bdd0c0e7264a0110_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55d1fe71-2f56-45a9-ae6f-462371393940', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 38).', '[{"id": "A", "text": "watch interface xe-2/1/2", "is_correct": false}, {"id": "B", "text": "show interface xe-2/1/2 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface xe-2/1/2", "is_correct": true}, {"id": "D", "text": "tail interface xe-2/1/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a4dc24f2a3748150_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55ff7b05-f368-448c-bc6a-5b3cbac40559', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 38).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5d9897ad674eb27f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c92e8d40-dad2-4c05-b053-709163bf196d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 38).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '4c508ffe8e426e17_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11fdff91-082c-4dd8-931c-b99e7d4da2ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 38).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f0b7b038cad129e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91f8cb15-a1e3-4288-a2c7-c021809dabb4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 38).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2c28d9eaeef16d8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eda60b8-274d-4def-aad2-639b0aa3493e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.250.173.0/24 via next-hop 10.21.95.254 on Junos (variant 38).', '[{"id": "A", "text": "set static route 192.250.173.0/24 gateway 10.21.95.254", "is_correct": false}, {"id": "B", "text": "set ip route 192.96.170.0 255.26.198.0 10.21.95.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.250.173.0/24 next-hop 10.21.95.254", "is_correct": true}, {"id": "D", "text": "set route 192.250.173.0/24 next-hop 10.21.95.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd92002b0fb4c53d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09e55577-8505-4830-8f66-1e75156fcd21', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 38).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '3b985d2315f0766f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f390bcb9-3dff-4df1-9bbf-3339f78dea0e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 38).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '0bf60ec9784d5985_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a434a775-7906-48a7-bf72-a788dfd152ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 38).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7de09488f1313aa6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47fabebd-137f-411e-9860-d6344cd68974', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 38).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '239c5c089251723e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7368485f-6eae-49e9-8b24-c42d855794ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 39).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'f43e35618b219b76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dffdfed-3c5e-4115-a2fb-c997473ea0d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 39).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'a113e02eaad904c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d5bf6cb-c451-488d-8f88-f347927c1392', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 39).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'e1259211cf0a87c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73872ab6-232e-46ff-989c-07700f74fefa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 39).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '60777cb0020fc2de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07330e68-08be-4305-b1b4-8c705ce82b72', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 39).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '2d8d26d9dce245db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52ae8b09-45f9-4a13-82b0-ebd9ea5b6b27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 39).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '997e72fce7553261_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9722ef7d-fbfd-4b38-8d61-f21ed6adfa6a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 39).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '045627b406ab063d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fab7db80-c6ce-4b9e-b648-68ece17493ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 39).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4deb11e67d5eae7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c6615e4-41ea-4e47-81e5-b006c713fb11', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 39).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7cbd78c48506de43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e00d5a3b-7713-4811-8350-75b4c5b16c88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 39).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '3004cdd30c7434ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c546fcec-f779-4925-a65a-584293634f1e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 39).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'da64dc6aae93b91d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('166e08b5-f947-41a7-acc0-f02ffa06978f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 39).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '0e54e44ffbfae9ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40565c1d-738d-4280-ab4d-db47cb11729d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 39).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2b4ddacab07c74eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02ad83ad-3c40-4fcd-8044-8c72035fd6e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 39).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'adc59d05af30189a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a5786a5-aa95-4cb2-aaaa-a8c97783a095', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 39).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5ad95c90b466aeda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5cd47ce-4c3f-403b-bcdd-8bbd7c156708', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 39).', '[{"id": "A", "text": "set router-name R7", "is_correct": false}, {"id": "B", "text": "set hostname R7", "is_correct": false}, {"id": "C", "text": "set system name R7", "is_correct": false}, {"id": "D", "text": "set system host-name R7", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'baf3b3280125c4a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe3774f2-e60e-4209-bfe6-2f7e1f057c0b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 39).', '[{"id": "A", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b0e38448fc9087fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42fbf142-05f4-4d74-937b-fa271de0bd45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 39).', '[{"id": "A", "text": "configure interface et-1/1/0 ip 10.12.11.1/24", "is_correct": false}, {"id": "B", "text": "set interfaces et-1/1/0 unit 0 family inet address 10.12.11.1/24", "is_correct": true}, {"id": "C", "text": "set interface et-1/1/0 ip address 10.12.11.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.12.11.1/24 interface et-1/1/0", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '9680762027b50423_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('760125e8-3ea4-4a55-82a8-126540ff5d3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 39).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b30793b6a39a2f0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d31a6ea9-4753-4651-8e44-c267b2b4c863', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 39).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '344092ce475c9895_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cc0c8ae-46b8-49b1-80e6-a614950f6ee8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 39).', '[{"id": "A", "text": "watch interface ge-3/1/2", "is_correct": false}, {"id": "B", "text": "show interface ge-3/1/2 monitor", "is_correct": false}, {"id": "C", "text": "tail interface ge-3/1/2", "is_correct": false}, {"id": "D", "text": "monitor interface ge-3/1/2", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f517cd0b499b8d70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d7fccee-aed6-429f-8969-d073e4dcc310', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 39).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5abe88b2a75d8e01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5903a07-aa21-45f8-b251-3576d6ac4d68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 39).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'dc1cf97828dd5da9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0e52469-49a8-47a4-8645-a5d72efa9209', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 39).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '84467fb9bf05a639_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a397e81-9a0d-4e2d-a0f4-f01b08c883f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 39).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '33cb2f41ed726e72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28433653-f4ed-4012-9bab-4d66b40860ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.41.118.0/24 via next-hop 10.10.254.1 on Junos (variant 39).', '[{"id": "A", "text": "set ip route 192.6.6.0 255.158.76.0 10.10.254.1", "is_correct": false}, {"id": "B", "text": "set route 192.41.118.0/24 next-hop 10.10.254.1", "is_correct": false}, {"id": "C", "text": "set static route 192.41.118.0/24 gateway 10.10.254.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.41.118.0/24 next-hop 10.10.254.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd6f87259f5dfcf0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e00aceb2-1098-420d-89fd-4ea750e1efe9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 39).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'a28099b2a2a6e8d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3032423a-c8f0-4e59-b2ec-67fef390cb2c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 39).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '7c96f9e3e8e933e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69d2cf48-cca6-46fe-93ef-e41eed9c9296', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 39).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f1762f4e657e653b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44c6fd7b-2924-4243-a477-0aacc44d1ea6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 39).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8a323d70f8e2a83e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('708a1c79-a449-4adf-a210-ae0af18f842c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 40).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'c67695e769433041_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eef647b-0aa2-4775-8c59-0d7c2843a9c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 40).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '9f1e559e7eee1ab6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca79b9de-5fcd-4048-afce-83ffcfb30316', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 40).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '7ace83e4701d3db5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbcbcfe1-26d8-42bb-bcea-b14f901cd60b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 40).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'b322dd87967dfc13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4896cbf-125c-4d24-90ae-7d1d58cdb7e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 40).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '110f0dd524297fd8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05c060a2-91b2-4b1d-96b0-db7e65e39471', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 40).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '5948fcd48c14bc49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a99439fa-5526-4230-9165-74ea98cb6d6e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 40).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1623497d369491c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('072be987-418a-4090-ba76-dfe115840711', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 40).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '10443c257dea3749_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97de7567-622a-4320-99ae-46fd38f0636f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 40).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4dd5b130d02295ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac03f307-69cc-4da8-8f4c-d5a89d665090', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 40).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e68724940846026d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80f32003-59b0-403b-9b02-5da1212429d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 40).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '704896b4ff6cc4ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00e496e3-fabc-4ba7-8b23-99b7373a2553', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 40).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8ca005e23feb646e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('125faf95-c360-4998-a50e-a21371aa697a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 40).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f410097ced2b0915_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0280254d-966a-480a-a195-7a451ec10c83', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 40).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '54c7529617a7cc2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('075fc555-b9df-47fe-9190-d861fc43a892', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 40).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'bce561aba65fc1a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8eae9d1-c89a-46d1-a8bc-a93258f72033', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 40).', '[{"id": "A", "text": "set system host-name R2", "is_correct": true}, {"id": "B", "text": "set hostname R2", "is_correct": false}, {"id": "C", "text": "set system name R2", "is_correct": false}, {"id": "D", "text": "set router-name R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8d523dc447c1d805_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f91117c-0488-4bae-8a1b-06cc57b35b45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 40).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user root password", "is_correct": false}, {"id": "D", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ed176c77e6e52b21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf54defa-f7a6-4347-9351-be475c2ac18b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 40).', '[{"id": "A", "text": "set interfaces ge-0/1/0 unit 0 family inet address 10.164.68.1/24", "is_correct": true}, {"id": "B", "text": "set interface ge-0/1/0 ip address 10.164.68.1/24", "is_correct": false}, {"id": "C", "text": "configure interface ge-0/1/0 ip 10.164.68.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.164.68.1/24 interface ge-0/1/0", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '1cc497c215c99504_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95d11b70-1a71-4e8d-b817-5351c4392a14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 40).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '30b55deefef93e86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d6f4333-f2b2-46fb-9ea4-ac42ed33ab21', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 40).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1ef88f13e1fb1011_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2aec35d9-0a63-4171-af9d-caa4d1f112bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 40).', '[{"id": "A", "text": "tail interface xe-2/1/1", "is_correct": false}, {"id": "B", "text": "show interface xe-2/1/1 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface xe-2/1/1", "is_correct": true}, {"id": "D", "text": "watch interface xe-2/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'e829a11669294103_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6243730-a515-4138-b2ae-d1a10419d015', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 40).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '20ccaa603e8310d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aed5297a-2677-429a-b862-25d8f930861f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 40).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'da39f4d3c2f59882_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57c8df06-92cd-4ce3-8a79-63bafc3b3366', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 40).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '64530b7463107975_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21a86016-c5f4-4733-a10a-95b7ddcf6f52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 40).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '37975d669a4bd950_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28b4e031-1ea4-4eb6-ac22-539b2f97ba52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.231.57.0/24 via next-hop 10.27.255.254 on Junos (variant 40).', '[{"id": "A", "text": "set ip route 192.209.172.0 255.130.111.0 10.27.255.254", "is_correct": false}, {"id": "B", "text": "set static route 192.231.57.0/24 gateway 10.27.255.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.231.57.0/24 next-hop 10.27.255.254", "is_correct": true}, {"id": "D", "text": "set route 192.231.57.0/24 next-hop 10.27.255.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3954f7e8de57af28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1f63804-665f-4962-957c-352856548c12', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 40).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd3597b4a3eeda5b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b9746d5-73e9-4d7e-aacb-c605bc9ac7a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 40).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '6201a7f33f0bdf51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6b9bfdd-3c7a-409d-b20b-c351b9dd69e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 40).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e6097baf54ad8458_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c07ef2d7-0b7c-4463-b8dd-4b3ec0e5e9ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 40).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e2df41d6c55d6d81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4409081d-a97a-41a0-b437-d4bc22820439', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 41).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'aebd68137927eed2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49d277d8-089c-43f7-8a7a-66922755859f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 41).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'b4d973aa1b585294_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('929b13b4-4aaa-4133-90b1-6d62f022a0f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 41).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'cb60fbf26c563964_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd166bb8-826e-45e8-a94a-fd739f117daf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 41).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '6ecd8eacfeb0bc75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9c10cd0-ccbe-4d8b-97af-d5e8499d137b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 41).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '6b2423ff55e8c90c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc46b3c9-f0af-40fa-97c5-0c1b0d14112a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 41).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '34aa67d036a0555c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12848850-7b5b-4a1d-88c2-1af319ca2b69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 41).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8250d96e60091323_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0239bfd-6cb2-4c98-9423-5fd8fa8d7ca7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 41).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b2cfd9f942fa4011_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0274735-9ba3-4f9c-b5e5-b35d729ad7ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 41).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '96671a638571b1c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f87c916a-726e-466b-85d9-9132db939683', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 41).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '8ffc2ed80063a3a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('242cebdb-3847-43d5-95c8-74139d67a8d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 41).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'be9927412217fc52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9718f2ba-4579-4fcc-8c69-27d07a196a0c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 41).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8e9ced2631d63e51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('917a5022-ba36-4d91-b61b-63ff93e989b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 41).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd517e983aae983bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('150bf395-b68c-4d09-96a7-a37711f7ef0c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 41).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'bbd6ed80aac1daf7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4050fd0-2e85-42d8-be3d-55d4a13f62d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 41).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7419d2b6340e3661_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9a56e66-010c-4239-9ba6-b992fd730741', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 41).', '[{"id": "A", "text": "set hostname R12", "is_correct": false}, {"id": "B", "text": "set system name R12", "is_correct": false}, {"id": "C", "text": "set system host-name R12", "is_correct": true}, {"id": "D", "text": "set router-name R12", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2390b2f926be3ece_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('001cee85-bc37-4be7-98b3-8eb781a676dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 41).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b601c882c8e8cb1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6ee8637-98f7-4e44-a086-3c4e209747bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 41).', '[{"id": "A", "text": "set interfaces ge-3/1/1 unit 0 family inet address 10.133.161.5/24", "is_correct": true}, {"id": "B", "text": "configure interface ge-3/1/1 ip 10.133.161.5/24", "is_correct": false}, {"id": "C", "text": "set interface ge-3/1/1 ip address 10.133.161.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.133.161.5/24 interface ge-3/1/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'be7ee7f9073de416_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6a8a352-8555-41cd-9634-dc0504040e38', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 41).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '350087234d4cf3fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0302c9c9-7071-40dc-a184-b0d97bc56902', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 41).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '55822f325328b8f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47a7be78-11b1-47cf-868a-0025103c40a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 41).', '[{"id": "A", "text": "monitor interface ge-2/0/2", "is_correct": true}, {"id": "B", "text": "tail interface ge-2/0/2", "is_correct": false}, {"id": "C", "text": "watch interface ge-2/0/2", "is_correct": false}, {"id": "D", "text": "show interface ge-2/0/2 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'cc8c86c188c1ecd1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7607ed41-a298-48eb-8828-d3be13d65f47', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 41).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6c934ba6595e4d7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0c4e000-462c-4ebb-ac8a-6022860161fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 41).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'abced0798b45bb3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76cbb1a0-9650-45c2-b7cf-4d9bee67949e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 41).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '71d6c8ff51ccd2e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7273cd69-cc18-434c-9d33-c947f7d8de3f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 41).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6b6832d315ba24a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('815abba5-3435-425f-81a1-a8c3b7323655', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.99.224.0/24 via next-hop 10.139.150.254 on Junos (variant 41).', '[{"id": "A", "text": "set route 192.99.224.0/24 next-hop 10.139.150.254", "is_correct": false}, {"id": "B", "text": "set static route 192.99.224.0/24 gateway 10.139.150.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.99.224.0/24 next-hop 10.139.150.254", "is_correct": true}, {"id": "D", "text": "set ip route 192.117.74.0 255.245.118.0 10.139.150.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f67b62e51ff1698c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('141c8a44-6f35-4964-bbb7-5b527b5390e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 41).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '0c4b8cfd9f5b0e62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee8d94e2-aa7c-4335-a212-241c99b87418', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 41).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '88879aec03812863_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04856dc4-8462-4dc6-8e65-64f035e86894', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 41).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'fe32a057b295c61a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90bd09cc-d5d8-4aaa-9527-6e850709cb4c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 41).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f6389a3619c17665_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae754806-bb0c-4a35-a3bd-4a530532efcc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 42).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '2826bfdbc7bcd222_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e876186-9ee0-464e-b277-081fec70745a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 42).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '57c45f386dbce644_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8670e7b2-63eb-40c0-b17e-6da42ce22bec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 42).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '3972323e747a5de0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1354591-9161-478d-a509-f512abc75ef1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 42).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '055d56f2b3bd1a3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eb43026-5397-4221-bdf4-0cba06ab9094', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 42).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '6fc706ac58568f6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49d8ca38-09df-45ef-8649-cd65820721d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 42).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '843261f3c1792923_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f4b4b9a-5dba-493c-bc84-d0c6abb2c94f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 42).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1419bd2527557d03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcb5e382-b3da-4abc-a5ea-f766cd2ce75d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 42).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'bd32d7241db202fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b81a8e6-c021-488f-a355-72949f0ab6cf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 42).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '74f06ae2eca3bd07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d88301d-1e19-4bec-ab41-d793e4af2972', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 42).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '730cfbca75a4f9fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52c0679b-a39d-4cb8-9d64-e080182f088b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 42).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '669354e2668b5d41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc80eada-b00d-4f3a-9103-fc4ed114716a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 42).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f9fe23b9072b343d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f84c7b32-c7f3-486d-8ffe-86adf1c03e47', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 42).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e392866268acf149_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00a1cc9e-f8e4-4c1d-b5c7-6560ad89a7ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 42).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7482be5700a69614_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a28b4a1-46cd-4ac8-8e49-bac395e88f19', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 42).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f9735eeac2c0ba53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f77ad79-bd34-4f3f-a9b3-375cb8605fef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 42).', '[{"id": "A", "text": "set system host-name R8", "is_correct": true}, {"id": "B", "text": "set router-name R8", "is_correct": false}, {"id": "C", "text": "set system name R8", "is_correct": false}, {"id": "D", "text": "set hostname R8", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8926f5f38dc0929d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3add6146-17e9-4f59-8512-2c23d73ea727', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 42).', '[{"id": "A", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5670bfd35887c4bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78edff98-69f6-409f-a7d9-837e63128d88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 42).', '[{"id": "A", "text": "set interfaces ge-3/0/0 unit 0 family inet address 10.104.138.254/24", "is_correct": true}, {"id": "B", "text": "set interface ge-3/0/0 ip address 10.104.138.254/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.104.138.254/24 interface ge-3/0/0", "is_correct": false}, {"id": "D", "text": "configure interface ge-3/0/0 ip 10.104.138.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '8cdb2875dd47863a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34520381-7e2a-4243-a1ac-cb13fa5d7abf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 42).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6ac322d296231148_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99b4e35d-76bf-477f-ac85-45fa6c05a0dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 42).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '556fd4f31b6c5ca1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d207af9-b0b6-479b-8572-ed9965f0de2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 42).', '[{"id": "A", "text": "monitor interface ge-3/0/2", "is_correct": true}, {"id": "B", "text": "watch interface ge-3/0/2", "is_correct": false}, {"id": "C", "text": "show interface ge-3/0/2 monitor", "is_correct": false}, {"id": "D", "text": "tail interface ge-3/0/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '606daab09e15e05e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1259b836-4c5a-48ee-9e52-f3c02666ec79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 42).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '9ebd55837d9a2bc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb278a96-3711-47ea-b114-0c10c1ce1d9c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 42).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '27a6bfc08ff116d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2711ad8c-979f-4c9e-bd4b-7a6a545cfe61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 42).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '75d533ad0796e238_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('843c591a-b8f9-4054-977d-7e01be2f0a9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 42).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8c63bb13ed23d4ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60488fbf-e95c-4f02-afb0-c9e563ef3483', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.63.234.0/24 via next-hop 10.106.161.1 on Junos (variant 42).', '[{"id": "A", "text": "set route 192.63.234.0/24 next-hop 10.106.161.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.90.7.0 255.169.227.0 10.106.161.1", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.63.234.0/24 next-hop 10.106.161.1", "is_correct": true}, {"id": "D", "text": "set static route 192.63.234.0/24 gateway 10.106.161.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'aed395f9a7a3a256_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0e0ec36-ed51-46e7-90fb-a61ec5872fde', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 42).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'f891736c44195132_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c91f2749-d0b9-4cc6-910f-4c9b7fafee64', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 42).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '6ed8a142a22d32e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3a91448-d04d-4f4d-8b69-d0018cc74edb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 42).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd2b4e44fb2e1f560_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e4a77b5-9d3c-4ab7-bfda-757517ffdad3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 42).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '509f4792a5a0ece9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6d34ea3-34c4-496d-a0c3-09c24317f172', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 43).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'e80c207fdf1136c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('707821f4-d717-4ed1-a810-b4618c8a021f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 43).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '78c7e2b40223115e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94022cd9-2bf3-491c-98db-2cb0b4dc1e4a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 43).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '8f5adb79d4c25a4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2246f668-1291-41f6-b576-02d8d74c9e96', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 43).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4dad89e80aa6f56f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80991552-61e5-4388-b268-a0a02f76fd6c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 43).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'e390d3e7c29009a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69527342-3746-481a-9e0f-5a17b524729e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 43).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '99b98c2388d31147_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3335232-6d92-4b8a-9fd9-249dc86981a9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 43).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '09bdd4a57699f02b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('728afcd4-4e61-4c7f-a5cd-bf3694842c74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 43).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ad91fd69d4e6a6f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('159860e3-81c3-41ce-8bdf-78c92b9dd42e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 43).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2fd795081c52da99_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7be8a49-18b4-4a6f-a323-02f9c648a820', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 43).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '8593b0bd9314d4bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71b65b65-c7eb-4a33-839c-79c4b0857bb9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 43).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1583fb204ee0ff2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0e31b9a-794f-4f88-a256-4a74784a4538', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 43).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '16b231bd6b03e5d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55a04c83-6475-4f59-8960-15db5e747ef8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 43).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '757ca1ee51ce3bbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf3de5cc-82ae-4a47-89f8-f45a09fa3e21', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 43).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8858d7a1846bd46e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c30f814-420f-4d38-a281-ad747f0a4793', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 43).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5f4b97ab0a1e473c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('389158e4-9b8d-416f-b93e-54ff12d2909b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 43).', '[{"id": "A", "text": "set router-name R6", "is_correct": false}, {"id": "B", "text": "set hostname R6", "is_correct": false}, {"id": "C", "text": "set system name R6", "is_correct": false}, {"id": "D", "text": "set system host-name R6", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0c64a7ab327c8544_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fb7d6f5-b799-4f11-8397-dac2ac3889b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 43).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4cf37adec7ae83f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('842dbdd9-9f41-4a57-8456-0b6a05c98d3d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 43).', '[{"id": "A", "text": "configure interface ge-3/1/2 ip 10.41.187.5/24", "is_correct": false}, {"id": "B", "text": "set interface ge-3/1/2 ip address 10.41.187.5/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.41.187.5/24 interface ge-3/1/2", "is_correct": false}, {"id": "D", "text": "set interfaces ge-3/1/2 unit 0 family inet address 10.41.187.5/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'e154d4cb91d14875_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34a7c23a-7bdb-4b8e-8a8c-387ce6b162cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 43).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '502c40319dde2ca6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a4f4c89-f000-48c6-a8bc-5974f7211b9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 43).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2a41870b12900601_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9240e32-4a61-4029-bd43-7f98e808b735', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 43).', '[{"id": "A", "text": "monitor interface et-0/1/2", "is_correct": true}, {"id": "B", "text": "tail interface et-0/1/2", "is_correct": false}, {"id": "C", "text": "watch interface et-0/1/2", "is_correct": false}, {"id": "D", "text": "show interface et-0/1/2 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '32196056a4ae3b4a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9f20258-7f2b-4e01-9613-36894d762395', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 43).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c816e2dfb03c42d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3c27a7f-b6fd-4821-acb6-da2c36461b45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 43).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2d020e1b18cfda36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f61eba3-e74d-4014-adb2-fee5c5c17d56', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 43).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '8ce8d68505013ae7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cb53651-b8ab-4a81-a758-e18f72ef3e54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 43).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '51b30deaf4b9011c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbf0d373-1aac-42e7-98dd-c1b0977eabe1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.13.65.0/24 via next-hop 10.165.30.5 on Junos (variant 43).', '[{"id": "A", "text": "set static route 192.13.65.0/24 gateway 10.165.30.5", "is_correct": false}, {"id": "B", "text": "set route 192.13.65.0/24 next-hop 10.165.30.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.13.65.0/24 next-hop 10.165.30.5", "is_correct": true}, {"id": "D", "text": "set ip route 192.225.202.0 255.96.9.0 10.165.30.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '18eda53d959da50a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63eef18d-f4e7-4422-bcbd-2faef951523d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 43).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '775bb822c81a1164_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c482d7c-584c-4689-beff-b7f2faeec381', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 43).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '4e07025a39e97478_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89be6320-4751-4cd3-886c-d696be3a60e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 43).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '6fa22b8914e4841f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d6de620-a452-41b8-845a-6096800aba19', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 43).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5df02dc87a254cb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d9ab99f-db76-4b7a-8b74-638ed14a8841', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 44).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b8072222fa30fab1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7a8c973-2b20-49fb-9c8d-3ef4c19c20ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 44).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '9adcd118049dec91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb279fa0-d43b-4b67-8f49-239572978c36', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 44).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '87e2102bb58aa216_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4beadf15-ef88-4ab8-86e6-710061b18e45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 44).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '8c60e265f8ef5b42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73aabba9-fbe8-410e-989f-31c974e828f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 44).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '9c2857010168bcdc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d19e6df2-ac0e-4805-bcf9-f6cd63d859c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 44).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '42a6f517105e6b95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1cdd985-cfc8-47c6-adec-d1d6856a87b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 44).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '58799e4862e40cdd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44ec3093-946e-4daa-830d-cde9a241e1dc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 44).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ae5bdf69ec63c919_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('825d7cf9-1695-4e11-b433-34e98a60b6f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 44).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd8fe7a1fc445f88e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e47f0c6e-6409-4e57-b0b0-5d11920bdf42', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 44).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '53743739cbd404c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17529eee-2f06-4f4c-abf3-25a382bc45a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 44).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2a0d78e0c4931fbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22629634-4bdf-4bbf-b9fe-83627adfcab3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 44).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '31473b0f546c2656_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96bb1059-6b64-4235-8666-ef27869a04d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 44).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '73ef5b5d96fa3ad6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e279075c-58e3-4d86-bafd-25ccf59f36de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 44).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '780444381d636568_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bb995c6-b50e-434a-a4c2-efb3177e1652', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 44).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9eaa7793a2221972_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2560e9e8-fdeb-4983-a5b8-6009163b3f30', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 44).', '[{"id": "A", "text": "set router-name R9", "is_correct": false}, {"id": "B", "text": "set system host-name R9", "is_correct": true}, {"id": "C", "text": "set system name R9", "is_correct": false}, {"id": "D", "text": "set hostname R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '60c3c397ed12a6b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e7fa172-696e-4bce-b50b-563fa018277c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 44).', '[{"id": "A", "text": "set authentication user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '49432ff79ccb1687_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b5ca0ee-4983-4116-a812-64a658121b58', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 44).', '[{"id": "A", "text": "set interfaces et-0/1/1 unit 0 family inet address 10.111.144.1/24", "is_correct": true}, {"id": "B", "text": "configure interface et-0/1/1 ip 10.111.144.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.111.144.1/24 interface et-0/1/1", "is_correct": false}, {"id": "D", "text": "set interface et-0/1/1 ip address 10.111.144.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'aa4cfe75fc0d85c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38ce234b-a2f8-4bd3-b614-cd8347f596a8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 44).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '21590eb4f81d8079_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f41540e6-9aeb-4f6e-bccd-bb3f8a20cfb0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 44).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6675633d9f18036b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abebecdd-5be7-498d-bae1-e58ef9f00ee8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 44).', '[{"id": "A", "text": "monitor interface et-3/0/3", "is_correct": true}, {"id": "B", "text": "watch interface et-3/0/3", "is_correct": false}, {"id": "C", "text": "show interface et-3/0/3 monitor", "is_correct": false}, {"id": "D", "text": "tail interface et-3/0/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b2a5243525681e9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23f6790b-eea3-4382-b225-c0e3ca7b71d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 44).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '62e202330666b725_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e27d8609-a84e-4524-bc24-501d823d93b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 44).', '[{"id": "A", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'dc162e1387148cbb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5dcbd37-d3d0-4f50-a5ce-99a26965c491', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 44).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '59a7e5ddcfaa2710_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b77deaf-bfba-4e8a-bd2f-3e76739cf20e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 44).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'cd1f76cf1594f1c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('414bdceb-2f89-4166-8f2d-89efd9f745dc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.251.169.0/24 via next-hop 10.32.252.1 on Junos (variant 44).', '[{"id": "A", "text": "set ip route 192.105.10.0 255.89.194.0 10.32.252.1", "is_correct": false}, {"id": "B", "text": "set static route 192.251.169.0/24 gateway 10.32.252.1", "is_correct": false}, {"id": "C", "text": "set route 192.251.169.0/24 next-hop 10.32.252.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.251.169.0/24 next-hop 10.32.252.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '641f773ece75e21d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f68cfae6-1530-4b0d-9a9c-240c60587fcd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 44).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '511ec671eae7778f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70f19cca-2d60-4d42-84d5-1981561777d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 44).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '61eadf30d4ad2911_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a3a049d-757d-4cf3-83d7-bf3396b0930a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 44).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f6a964d406e81577_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21194c1e-2042-4c1f-b83c-2bd4ea4671c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 44).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ef3e7cca6c1b6e8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8ae2efa-2b71-4576-8feb-10013d6951aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 45).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '44f1c3e0f03d645c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25bdf7e2-ba94-42bc-819f-23233740666b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 45).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'd4594fac049bce26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fb03fae-6926-4c5f-8f63-78447ce45b4b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 45).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '19d8076e880e16bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6853e3b-6239-4522-9b1d-58c5b9a54022', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 45).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'beaac2189f7505a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10433646-feb6-4741-bb75-b3c0570f917f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 45).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '515048d9758e906f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('698348dc-fd04-4fdc-9c53-401832ac27a8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 45).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '472cb45ab035f432_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b628fb62-4f24-4068-b6f1-a43c4811291f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 45).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4f73db379962b175_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a3fb48b-5d60-4756-9b58-d275fe249a33', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 45).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b0e1c9b481d4848e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fd3b2db-d85f-46ed-856f-ec62ae8a81f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 45).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4570a13f47eee6d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6b9a9c2-51a4-4d96-8285-600a8362272a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 45).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '656add1834e09075_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2831c45f-a5ee-4143-88c8-ea6fec42714a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 45).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '70a6476c3c2d23ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a57b8214-cb1f-4f1c-bfca-272a5195e002', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 45).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '231928b714037319_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3454c6af-bb87-4131-b3bf-c9874a860f59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 45).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e38b729b3d2be819_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73269b62-4deb-4677-8735-3e91f691d236', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 45).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '0022508636d6b2b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('274ac626-8e0e-42ff-a6c5-df24e9eeca58', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 45).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9b6d962b1b9b4697_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2a836cb-2ee2-4593-b632-9c5cb86d2b16', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 45).', '[{"id": "A", "text": "set system name R1", "is_correct": false}, {"id": "B", "text": "set hostname R1", "is_correct": false}, {"id": "C", "text": "set system host-name R1", "is_correct": true}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f0f77a12067b24bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15dd9f96-4200-4431-b516-92fef23f9d01', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 45).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}, {"id": "C", "text": "set authentication user root password", "is_correct": false}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '57c3cd59a919438f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0ab8b65-705d-4c2b-87f4-4c7c683bb88b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 45).', '[{"id": "A", "text": "set ip address 10.105.49.1/24 interface ge-0/0/0", "is_correct": false}, {"id": "B", "text": "set interface ge-0/0/0 ip address 10.105.49.1/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-0/0/0 unit 0 family inet address 10.105.49.1/24", "is_correct": true}, {"id": "D", "text": "configure interface ge-0/0/0 ip 10.105.49.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'a1b985016267af94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3eec37e5-efbf-48bf-ad4a-024054b7f2b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 45).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '83837b4817494452_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de349f15-6f97-4c0e-8b4b-f8501eb86b51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 45).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2e8f869c54bc99c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfbd1b3f-7326-44b6-83b3-534b4b0fd9bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 45).', '[{"id": "A", "text": "tail interface ge-2/1/1", "is_correct": false}, {"id": "B", "text": "watch interface ge-2/1/1", "is_correct": false}, {"id": "C", "text": "monitor interface ge-2/1/1", "is_correct": true}, {"id": "D", "text": "show interface ge-2/1/1 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5a5474f8d4666465_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d49c067c-062c-4e1e-833a-22c7bf7669b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 45).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '96dfb1343df68729_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4b48a82-07a7-49a9-bc46-2901dd5136b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 45).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'bb2f618798b74c0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c5cc3cc-dd5c-4e82-a7c0-7d3d1978b41a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 45).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'cf4073ac95f0187a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('008f64f1-0caf-4bc4-85a9-ebf99a57f545', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 45).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '9a2ef8fe68bf01b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acc8f367-f92d-4637-8465-d6d91af83d5e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.60.169.0/24 via next-hop 10.115.67.1 on Junos (variant 45).', '[{"id": "A", "text": "set static route 192.60.169.0/24 gateway 10.115.67.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.200.173.0 255.163.93.0 10.115.67.1", "is_correct": false}, {"id": "C", "text": "set route 192.60.169.0/24 next-hop 10.115.67.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.60.169.0/24 next-hop 10.115.67.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8dd7c639cb1a1e9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('172e0e37-25a0-41a9-a586-06a85c1cdc74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 45).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd10fbe47081e18b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4dd8cfb-17a7-49d1-b32a-8aa9e04e594c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 45).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '45f325b212bf3596_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('940468cc-29e6-4279-bb42-b365fef5da07', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 45).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7fda4a7a7c42d4fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8dd4fa91-45a4-4c7a-a49a-876527f82a2b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 45).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5e2e2674dfb50da8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('572e55cb-0693-4dad-86d8-750a90654f83', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 46).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '16c6d847ede6b034_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fbd3ae4-2f53-4e4e-b18f-ef16b0e71b1c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 46).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '522e4246c05262ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('442c8da5-310a-47ee-b681-85fb00ba7212', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 46).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'ae8b585d14658d8d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c84aa97-e5cb-4488-88bb-66538f551cd4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 46).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '0afc42a44ae886dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65551721-c379-436a-a992-f91160de03eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 46).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '380db82c2448c7d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdec8a47-073e-40a4-81b6-74419afc0f42', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 46).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '969442802cdd129b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c776c16-b094-46ae-88ba-92cf43da10f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 46).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3b45ec243820d2b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('673463d7-e844-433d-8a87-3d0850e1cbf8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 46).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ac0496731c8c8054_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e5e4d74-f861-4637-9823-547583e051c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 46).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c25fcd8c5ba2c3f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09ef7c69-4aff-4755-a03d-cd7271ef4163', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 46).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'dcc0fec77655face_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49ba62b2-5abc-4fdb-9861-345d31f2677a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 46).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f27771910da00635_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39cc8808-5228-43bf-94ee-3560b9a66b40', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 46).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f498176c875ac388_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b08729e-9785-4d28-951b-6899810c5c13', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 46).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e8fcf2c15a178ccd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d892e8c6-4c0a-4e31-bbaa-7d26903eaa67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 46).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '69ac9a68ec24cf17_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f10d977b-e5e7-4789-8eb0-07867726f04d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 46).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '807a084252a6afc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f20b99fb-b56a-4f6a-b9be-ab3b58f3c4c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 46).', '[{"id": "A", "text": "set system name R3", "is_correct": false}, {"id": "B", "text": "set system host-name R3", "is_correct": true}, {"id": "C", "text": "set hostname R3", "is_correct": false}, {"id": "D", "text": "set router-name R3", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8a338d914da10199_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6381dbb4-7434-4eed-9569-92304d9f8b3b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 46).', '[{"id": "A", "text": "set authentication user monitor password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ceb223adc84e42ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85ca5433-7214-4dc1-83b9-fb7371995626', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 46).', '[{"id": "A", "text": "set ip address 10.79.144.5/24 interface xe-1/0/0", "is_correct": false}, {"id": "B", "text": "set interface xe-1/0/0 ip address 10.79.144.5/24", "is_correct": false}, {"id": "C", "text": "set interfaces xe-1/0/0 unit 0 family inet address 10.79.144.5/24", "is_correct": true}, {"id": "D", "text": "configure interface xe-1/0/0 ip 10.79.144.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '13946cbe54d56022_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d0dd082-44cc-4c08-a0b7-f8d2e0a0c83b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 46).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '536c601819afde3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('296ae400-37ad-4cd6-86f6-4ee349d3744b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 46).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd6e182735a7ea858_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aed259a6-900a-4e2b-b55d-2e70981d28ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 46).', '[{"id": "A", "text": "tail interface ge-3/1/3", "is_correct": false}, {"id": "B", "text": "monitor interface ge-3/1/3", "is_correct": true}, {"id": "C", "text": "show interface ge-3/1/3 monitor", "is_correct": false}, {"id": "D", "text": "watch interface ge-3/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'bb75e0f65e949e99_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a6535e5-c77d-46b7-b8f8-faaa936606f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 46).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '343812b5c5432296_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a71707ae-848e-47e9-81ce-0ab08d114703', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 46).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1619bd7346049085_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f782a657-4adc-400d-93a2-65bd2a0a171a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 46).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '33929b97eb9b3c97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed601ba7-af61-4629-91be-bf5186f4bed1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 46).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c1674ef11d889cfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9fa30da-a862-407a-af98-6d47ad01ed3d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.219.115.0/24 via next-hop 10.216.246.254 on Junos (variant 46).', '[{"id": "A", "text": "set static route 192.219.115.0/24 gateway 10.216.246.254", "is_correct": false}, {"id": "B", "text": "set route 192.219.115.0/24 next-hop 10.216.246.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.25.21.0 255.28.155.0 10.216.246.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.219.115.0/24 next-hop 10.216.246.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd2cc3adff8df5692_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d84f499e-c76e-4c72-86cc-833471db6019', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 46).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'b808678fcd57fef8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc16a89e-3593-45e9-8c3f-617a766f0738', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 46).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '0dd438fe6cec807b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4f82270-9cac-4bbb-a306-5475652dd210', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 46).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '022e1eff7d8e3c3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ca39aed-3d2e-4eee-948b-3c8504ecf66a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 46).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9e1497fae1ea7eb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62123449-7266-4a18-b8d4-bb0e636ede30', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 47).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '2d4c9cdcee2859bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e919c29-6ddf-4b08-beeb-5c32ab584d78', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 47).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '02868800f9fe8c33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac1bc1ea-53b3-4ccb-b185-0a999f0fd792', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 47).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '7362757678cb0e5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('864827d5-68df-4218-b00c-49da91aa6e93', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 47).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'e944e7168c8ef261_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e12f9f4d-57f8-441e-8ada-7eb3040bc75d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 47).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'dfb7b7b559fffeaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e23dc07-1740-4907-b04f-9541db4436ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 47).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'c6c22d6aa03bbeb0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a41ab95a-8541-4fa0-ba1e-6077cb085f91', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 47).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2c9255b45a79a617_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2849d97c-2876-4090-8edd-1ffab8e3c8fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 47).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '65329453e5e5da23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54f655d9-52ac-4bce-823a-4b97872db5e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 47).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4c805b7a985c3372_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddc482b0-45b2-4fe5-a827-2dcddb343d9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 47).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'e1de42fd24c5dd14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8bf44bc-4b8f-4ce5-b4ae-84b6a03cb3ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 47).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '115f62e3aa894b51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b97baddc-bfca-4c52-ba4c-9222a4c6efde', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 47).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a720b8d9c4d33e14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e18b48fa-2521-4dec-8ee1-c3069cb2e035', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 47).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '9cc599154d0a5a41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1056098-c1e8-4273-ab81-8919e1baac8f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 47).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f7e155242adda584_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35c6afc3-6b29-433f-9939-f671649b3d68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 47).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '58bf11c536bcea88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f35cf299-9c67-4577-a08e-60395190590d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 47).', '[{"id": "A", "text": "set router-name R9", "is_correct": false}, {"id": "B", "text": "set system name R9", "is_correct": false}, {"id": "C", "text": "set system host-name R9", "is_correct": true}, {"id": "D", "text": "set hostname R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '497583c7018e2bb3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62120148-7071-4e2f-b739-fb0b72896240', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 47).', '[{"id": "A", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user root password", "is_correct": false}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '133a8263219718f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fe94f91-0ef0-4634-8258-0005cc0aeada', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 47).', '[{"id": "A", "text": "configure interface ge-3/0/0 ip 10.54.23.5/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-3/0/0 unit 0 family inet address 10.54.23.5/24", "is_correct": true}, {"id": "C", "text": "set interface ge-3/0/0 ip address 10.54.23.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.54.23.5/24 interface ge-3/0/0", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '289ba17afc20c2e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c57fd733-daac-45ce-ae8f-fc651863d70f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 47).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7f48e70d52dae27b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0afbb658-01b0-4aff-a0f0-1c69deb8fe17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 47).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c463b595ce81929f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06f3af10-27f8-46f6-962d-fcc7fab7e2ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 47).', '[{"id": "A", "text": "show interface et-0/0/2 monitor", "is_correct": false}, {"id": "B", "text": "tail interface et-0/0/2", "is_correct": false}, {"id": "C", "text": "watch interface et-0/0/2", "is_correct": false}, {"id": "D", "text": "monitor interface et-0/0/2", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5bf95a26a21f23a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73629346-3316-4370-a651-bf8554d55632', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 47).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8d51c044c13a8eb3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bcd3ec0-63f1-4320-9dce-de80b0f1337f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 47).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '316a0065ffa952ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17ad9ca6-81d2-47f2-bc37-b48e0092535c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 47).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'a3c32763d6e723e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b6479e9-ce31-410f-93f6-2094fbf9fb71', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 47).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e82553dbb7adb597_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca821b95-63e1-4cc5-9b5a-24692dd9833d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.3.114.0/24 via next-hop 10.95.248.1 on Junos (variant 47).', '[{"id": "A", "text": "set ip route 192.127.139.0 255.92.160.0 10.95.248.1", "is_correct": false}, {"id": "B", "text": "set static route 192.3.114.0/24 gateway 10.95.248.1", "is_correct": false}, {"id": "C", "text": "set route 192.3.114.0/24 next-hop 10.95.248.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.3.114.0/24 next-hop 10.95.248.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd42c76edfd0c3e48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77973f44-c6b4-4b2b-8b84-749b7592f889', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 47).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '4214c57457cd772b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('668116aa-31ab-47bf-b21d-f57f08e6f078', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 47).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'cdb161d1ab2f4cdf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5111c9a7-9b97-43ed-a1e5-fb66429b8202', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 47).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '79f0743d8ba4bac6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0e9a777-524b-4d4b-b644-a10e0bbc138a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 47).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9f6bbbe4dc37c4d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('238e9626-fd78-4b12-9944-5cd0c52b73b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 48).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd6c9958448155770_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('739982f2-672b-4dcd-b796-25ecb3560e4c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 48).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '87c769d80a67273b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b4f7da2-6c13-468f-9795-5984ba38e33a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 48).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '00b945511a8cee07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e54f790-fed4-4d55-8cc2-dededd44f80e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 48).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '0e51cfb4014ef643_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98f76554-9237-4190-a1d2-129188c3bbc3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 48).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '702e0df0d97676ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74bb5f54-5e7c-4aaa-8451-0ad8260a53f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 48).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '2db9b26a155d8f37_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c55972f-b841-4c3a-af10-0ce5eaae70e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 48).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2a6e3133c81349f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4a0994b-dc37-4f6c-a620-9d83d7ec0878', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 48).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f6868318c993d0f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0faa78b3-6041-4d21-a4c9-0c559eac0ae0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 48).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a252556fdd41a4f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8f2a846-cdbc-43eb-8136-800b9054dbb4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 48).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '4ede5528caa1a031_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a85e5bd-d9a1-4191-98db-4f292667ce09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 48).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6e24ee5604434d00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae96bdfe-2920-403e-b362-987fe0443bf8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 48).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'd754787184d27eb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7529a92b-076a-4fa7-9949-052c28cdfabe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 48).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'cb163dd084396e48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62d98336-7da8-4234-9e4b-1b89b693ad45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 48).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'b00ba8290e78eeba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43b2d0d3-4128-4161-90ba-7748dcf47f8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 48).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '524a9e2670871cf5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9e5f9eb-86a8-4031-bf44-e9150cd0a46a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 48).', '[{"id": "A", "text": "set system name R5", "is_correct": false}, {"id": "B", "text": "set system host-name R5", "is_correct": true}, {"id": "C", "text": "set router-name R5", "is_correct": false}, {"id": "D", "text": "set hostname R5", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a349b0147ee1d322_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4c164f9-6121-4c92-8254-cd3c57ef7abb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 48).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '05a9110cf3f6127f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79ba5514-ee7e-4d52-9fd6-e4a9588deee4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 48).', '[{"id": "A", "text": "set ip address 10.108.167.254/24 interface ge-2/1/3", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/3 unit 0 family inet address 10.108.167.254/24", "is_correct": true}, {"id": "C", "text": "configure interface ge-2/1/3 ip 10.108.167.254/24", "is_correct": false}, {"id": "D", "text": "set interface ge-2/1/3 ip address 10.108.167.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f751caf50425b425_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5345f3b7-ef00-47ee-89ab-2430e5ff0ffc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 48).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b8b7a696de68db6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb6175b3-779e-49b6-ab3c-90c83ba92194', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 48).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1fbcbb8e3709eeb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8656346e-8742-4c3f-b6b2-2fe170591d60', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 48).', '[{"id": "A", "text": "watch interface xe-3/0/1", "is_correct": false}, {"id": "B", "text": "show interface xe-3/0/1 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface xe-3/0/1", "is_correct": true}, {"id": "D", "text": "tail interface xe-3/0/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd7e33e52f1a0ab14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0abca4e5-1dc6-4c52-973b-368af7bcf30d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 48).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '24b1ac6fd0ef0a1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a925a7dd-019c-4df6-b41e-41e038f1a101', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 48).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '713c11800ae3b3e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4046df0e-ce0a-40fd-98bc-44369acc2675', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 48).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '4d8ad1f50df64f05_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f84ee2d-3283-4760-a3b6-c6cc7ce1105e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 48).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7777eb3d25d3a38c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb51ea2e-67a4-4eb8-924e-576d626b9de7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.246.221.0/24 via next-hop 10.22.209.5 on Junos (variant 48).', '[{"id": "A", "text": "set route 192.246.221.0/24 next-hop 10.22.209.5", "is_correct": false}, {"id": "B", "text": "set ip route 192.77.45.0 255.116.20.0 10.22.209.5", "is_correct": false}, {"id": "C", "text": "set static route 192.246.221.0/24 gateway 10.22.209.5", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.246.221.0/24 next-hop 10.22.209.5", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd88ec2ee3d9a9e15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8376ddc-caf6-4842-85db-1fbde8e38256', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 48).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5221c5ccf624f545_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39e95600-a069-40ec-beb5-64d214d9b800', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 48).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'a147157fde5dd3ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87448acd-740e-47a6-a9c4-3189ade1f393', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 48).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9e2d2f6354313034_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('736d684c-5ee1-48ec-93c0-1469d711a072', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 48).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '488096cf7e0529d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49082432-64db-4c7c-8002-587d0e33b78f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 49).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '960dcb2d7fe92b6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06b0b87a-5ea8-477b-9059-59a2046ebba5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 49).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '87f151f2f24ab163_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7468e11e-26ae-427a-b859-9e1a52841ae5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 49).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'bc8b7b9b9ff3552b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3afa49dd-ce7a-43aa-b4f5-9533f2e40863', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 49).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'f8f8e0c12ec4e3dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ee0ba39-4274-4d18-a085-7a8a99ecb665', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 49).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'cc44128d7404aec3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('381e70a5-f1bd-428b-85e6-572fef07a2c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 49).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '9fb8a74f23c40a7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e945c15-ca71-401f-8985-e47aa60641fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 49).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '54225d53d37c60d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4153a89-b41b-4cb3-849b-ca0f80490074', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 49).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7667a5599ede9f36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a9005bc-f9df-479b-918b-c51cfb97807b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 49).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e0851f7ffaf46793_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7e83137-cdcf-4e12-9f68-3fb847a4aaf2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 49).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '23344a7f624d9a09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee969cc5-f8f8-4565-b95f-a5910db78d22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 49).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0981e4248d858dc7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e22c09c-eed5-4321-a293-12f7c06a487d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 49).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '16bcb165e2505322_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d13b6ed-6e72-46ac-9e04-5180112e7ff2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 49).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0da274aec2b3adb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57cf3e28-ab9d-4926-987e-584b1412efcb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 49).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ca97bd6cf88354ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d178028f-b352-4c6d-af9f-c04c7f301f9c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 49).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a38357f0e9656206_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33b396d9-9106-4eed-922c-2fbca7935ecb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 49).', '[{"id": "A", "text": "set hostname R1", "is_correct": false}, {"id": "B", "text": "set system name R1", "is_correct": false}, {"id": "C", "text": "set router-name R1", "is_correct": false}, {"id": "D", "text": "set system host-name R1", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '17db3af3b4033c18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21448017-eb52-4bb2-a3b6-b12e3a125d1e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 49).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9a57f6437fb53896_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63b64818-5bae-430e-95aa-611b642bd2a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 49).', '[{"id": "A", "text": "set ip address 10.52.105.5/24 interface ge-1/0/0", "is_correct": false}, {"id": "B", "text": "configure interface ge-1/0/0 ip 10.52.105.5/24", "is_correct": false}, {"id": "C", "text": "set interface ge-1/0/0 ip address 10.52.105.5/24", "is_correct": false}, {"id": "D", "text": "set interfaces ge-1/0/0 unit 0 family inet address 10.52.105.5/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'd8aa0a7625680bcd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec46cb5d-590f-42f1-9518-bd2b5e478275', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 49).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b5b0360bdb7880fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8229475-7247-42d7-99a5-bcebfcb6e54f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 49).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'dd10ca1263adf3cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('650182b8-ca86-4eed-9e8a-5ba60219f84d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 49).', '[{"id": "A", "text": "show interface et-2/1/1 monitor", "is_correct": false}, {"id": "B", "text": "tail interface et-2/1/1", "is_correct": false}, {"id": "C", "text": "watch interface et-2/1/1", "is_correct": false}, {"id": "D", "text": "monitor interface et-2/1/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '957d0035a4959801_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09920ca0-330e-4ce5-9f6b-63ce8d83b7de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 49).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '92a8f402cde9ecde_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d05098e-2f62-48aa-8fda-4789063f6381', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 49).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e9a4dcdd1b7604a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c0e04c6-7b80-4dfb-9a88-eadc01a63d90', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 49).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'e4c98974416ca25d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('325ffcac-a544-43a2-b64a-50de5c4bf655', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 49).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '0f8e4c1e7bd2d2b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d6de9b0-9bba-46a5-aa59-19696806f79c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.115.121.0/24 via next-hop 10.39.36.1 on Junos (variant 49).', '[{"id": "A", "text": "set routing-options static route 192.115.121.0/24 next-hop 10.39.36.1", "is_correct": true}, {"id": "B", "text": "set ip route 192.9.153.0 255.247.30.0 10.39.36.1", "is_correct": false}, {"id": "C", "text": "set static route 192.115.121.0/24 gateway 10.39.36.1", "is_correct": false}, {"id": "D", "text": "set route 192.115.121.0/24 next-hop 10.39.36.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7b8ad35dacd6c196_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a6b8b65-6af2-4cf2-80f2-037a1c2aa771', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 49).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'f38cb30806f9e1b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a06357a-903b-4fc4-903d-eb8d58843929', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 49).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '949c61df87cd3f06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a322e0a4-d9ca-429a-b7c8-552a4b8ec81e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 49).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '85e168a47284aef5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06fdd322-a791-4331-a197-705d8bbaafec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 49).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4a733437c972d0e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('081710e8-2bfd-4c8e-984e-4c7322a6f785', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 50).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '5cb9ce7e16e58bac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b91a78f-82de-444b-b391-e49a0bc5366f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 50).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'cbe5a9d153f54caa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('489ca23a-5d9a-438f-a859-34658c1cde64', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 50).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '02bed67229d0fb87_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5764cfd6-4ae5-4fbd-89c2-fd3c2a016c6d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 50).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '38fe5b679999e5ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fb1a655-9a3f-4ac2-8ba9-629719a382b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 50).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '940e30d6f390130f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dca91a91-0c7a-4a80-86a6-02e8ef2ba873', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 50).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b24aa80e7133183b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('251451e5-10f3-467e-bd64-b52f370c0d35', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 50).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6b02b2988444b933_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79d89b40-0c53-4ef5-bff9-f111425dcb82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 50).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '521a0cabaee9bf35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('907003d3-1990-4c31-b743-132728c96a40', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 50).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '151bf40b29420896_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c380061-d343-4122-bdcc-427b3c4e58ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 50).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '7977fbe54d27a37f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dbed3cb-2e28-4473-86cd-23725d713343', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 50).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6cf6dc0ee14a6788_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c1f4655-2f8c-47c7-94a3-31bb7f15a48c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 50).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '60358c8fe121f5b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab3e09d6-554a-4d74-be9c-c7251794b258', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 50).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ca74a08d256ac528_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5005a1e-0d08-458f-aa9a-796f473eaab9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 50).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e8458f8d45af9eab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd6d3c49-593b-4b65-9886-6985c6b81af6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 50).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '948cb0b82a75d464_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('325c57d3-6154-41c3-b29e-0d321f2096c9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 50).', '[{"id": "A", "text": "set router-name R2", "is_correct": false}, {"id": "B", "text": "set system name R2", "is_correct": false}, {"id": "C", "text": "set system host-name R2", "is_correct": true}, {"id": "D", "text": "set hostname R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4dc8a6a0ebda73fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85aaf5f6-a753-4531-9eae-ab38a7897a7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 50).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'effcdd668e9e6185_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ed6eb1e-dbb7-4920-9dee-ba18421a25b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 50).', '[{"id": "A", "text": "configure interface ge-2/1/3 ip 10.174.139.5/24", "is_correct": false}, {"id": "B", "text": "set interface ge-2/1/3 ip address 10.174.139.5/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/1/3 unit 0 family inet address 10.174.139.5/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.174.139.5/24 interface ge-2/1/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'fbb2957730f8e321_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38922aef-2de9-4129-9e61-80ca5c977495', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 50).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '261a3fe5d6c2f7e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de7b42c8-ac54-42d1-b5b6-dbd1b27fb854', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 50).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8a902c1ac4d2a3a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e29f516-d933-4d7c-aebc-83175194956c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 50).', '[{"id": "A", "text": "show interface et-2/1/0 monitor", "is_correct": false}, {"id": "B", "text": "tail interface et-2/1/0", "is_correct": false}, {"id": "C", "text": "watch interface et-2/1/0", "is_correct": false}, {"id": "D", "text": "monitor interface et-2/1/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '00edc48d54e1d188_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('935beae8-e5fc-4057-8286-ac5f8fe1371a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 50).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6dc8c676ba3e2692_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a26a431a-7c37-4c65-ae0a-cff1d86286c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 50).', '[{"id": "A", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '37e9fbcb7b0a741c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c87556d9-49a1-4901-8f51-58256ea0f431', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 50).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '68d4c435543d8242_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b62e9da6-58bd-449f-9c2f-70520ccaa4a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 50).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e84592d33fbda333_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c69dd22-92e2-4982-9e28-9f79e43cebbe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.101.68.0/24 via next-hop 10.60.237.5 on Junos (variant 50).', '[{"id": "A", "text": "set routing-options static route 192.101.68.0/24 next-hop 10.60.237.5", "is_correct": true}, {"id": "B", "text": "set ip route 192.251.116.0 255.252.179.0 10.60.237.5", "is_correct": false}, {"id": "C", "text": "set static route 192.101.68.0/24 gateway 10.60.237.5", "is_correct": false}, {"id": "D", "text": "set route 192.101.68.0/24 next-hop 10.60.237.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'bad9c14dc4be598e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bf1a4c4-0e14-403f-93e0-1640205558c9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 50).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '4f3b78af872a3767_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4a614bc-b0f9-4e4f-897b-b7320956ac66', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 50).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '408376c0e3560c82_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4449ec47-b7eb-4c5c-87a8-eabf341f138d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 50).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'fba54a086c0f0a32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c50b1300-08e0-4920-beb2-3f15dc2d2f09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 50).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '369d00d48d63cfb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a255cc75-8ca9-477d-932a-f75482c037ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 51).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'f137779ca826d9d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('415d6302-3c3a-4892-91ef-736a84229df0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 51).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '780b5e56e514ee5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab384b39-6a1b-4227-846f-072e9de6e6f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 51).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '512398e668dba1e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed6f1333-255c-4292-83b2-9995ecd9c9b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 51).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '02b36bc68120327f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ce21536-e34c-481a-80fd-43042fe21119', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 51).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '766c09173ac6f597_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70674cdc-4df6-4d30-b088-4a2bca5e97eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 51).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'aa9044209454358e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bcb735c-617e-4317-bc86-677322973024', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 51).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3e67a362ab9c57bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c742a79f-5141-406b-b197-754bf2cc9be1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 51).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7dabea334638c338_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f4fa98c-572f-483d-9268-09ab94f9d009', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 51).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '76b49a319751f47b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('828063c9-1bb5-4f67-a967-6188d49c7c0a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 51).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '952e705208c8dfbc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('492f49fb-852a-45ef-afde-3997a9fd1605', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 51).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '43de7a2a5f70cde6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f7e7d59-d840-4208-bdc5-72e44475bda2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 51).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8b1afa7874040332_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27d01169-4037-4320-8395-473a1dafabfb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 51).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '40a031b3a9340e78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4eb499d8-6113-4a0c-84e6-50e50d88127f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 51).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '07b5405761fcbe04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcd982a2-0735-4d6e-b40e-7d89a9fee38c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 51).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'fe85d5a1a5dad84d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b4fdb27-0d72-4887-8b2f-59dd1eab060e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 51).', '[{"id": "A", "text": "set system host-name R4", "is_correct": true}, {"id": "B", "text": "set router-name R4", "is_correct": false}, {"id": "C", "text": "set hostname R4", "is_correct": false}, {"id": "D", "text": "set system name R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5c716fa07bee799d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e8b220c-0a05-43c2-9348-8ebab4c0ae01', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 51).', '[{"id": "A", "text": "set system login user monitor class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1466b54d0a599d30_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a68433ca-8d51-4f1b-a817-560e41798602', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 51).', '[{"id": "A", "text": "set ip address 10.75.231.5/24 interface et-2/1/3", "is_correct": false}, {"id": "B", "text": "set interfaces et-2/1/3 unit 0 family inet address 10.75.231.5/24", "is_correct": true}, {"id": "C", "text": "configure interface et-2/1/3 ip 10.75.231.5/24", "is_correct": false}, {"id": "D", "text": "set interface et-2/1/3 ip address 10.75.231.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '8353321f8a01900e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42c381ed-e13a-40f7-8017-9a6bf5235bde', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 51).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f4227e922d3d8311_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a227e12-bd15-48b4-b28e-8e5bcdb6eab5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 51).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7dc3ad807800c65f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1b683ac-334f-420e-b316-1d20c70eacb5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 51).', '[{"id": "A", "text": "tail interface ge-1/0/2", "is_correct": false}, {"id": "B", "text": "watch interface ge-1/0/2", "is_correct": false}, {"id": "C", "text": "show interface ge-1/0/2 monitor", "is_correct": false}, {"id": "D", "text": "monitor interface ge-1/0/2", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1ae48c943451ef2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8783c67d-3277-4d88-9f10-3a88e4ff2f28', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 51).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ee311755a7034389_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('413aa852-5465-49f2-a8ab-7133e0452efb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 51).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c518a42b9ba43f5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6847b5d4-ed7e-4942-a420-44b0c15c479f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 51).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'fdb1b247c64737c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('238fece1-ae4f-4e36-8ee4-418708deb943', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 51).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ee27da184b4d9f55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f79d189-181f-4f06-bdd0-92f394769065', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.87.198.0/24 via next-hop 10.98.33.254 on Junos (variant 51).', '[{"id": "A", "text": "set static route 192.87.198.0/24 gateway 10.98.33.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.87.198.0/24 next-hop 10.98.33.254", "is_correct": true}, {"id": "C", "text": "set route 192.87.198.0/24 next-hop 10.98.33.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.104.19.0 255.130.59.0 10.98.33.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '20b5a009daa4b4e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc6eea04-18a5-40c1-8f11-ed5b04cdf9c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 51).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c31710f9663e85fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3653375e-9076-4b58-9fc3-78c807045aae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 51).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'eea2122f4f1f466f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0331826-5c58-4a64-8c4b-1dedd9782d8c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 51).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '10188bb37c1f1916_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7761a161-4c0c-416a-a627-d20d3491bed5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 51).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8bece52db91bd6ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70a6ef87-4c15-4bbb-aacf-2aa2daed735f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 52).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b48b2332ccc672f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab5168f0-cc6e-4576-a8b7-e3907fce3418', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 52).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '586c4966a4b8585d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b14e1784-9cd0-4811-a60f-e0627d2ae014', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 52).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'de7aa7b209e58e3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('431f4bee-7444-478f-ae3c-55452b0d0ca1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 52).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '1c59ea91b002f158_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0c356d7-22c1-497d-84c4-f20d3accd6b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 52).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '6cb013cea4a5e931_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80a6f391-9528-4939-bb5b-04bf10fc21df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 52).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '1a5ea0334df65d9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94c6e105-7332-419e-9a8a-47bf772ce855', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 52).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8003fc4e02a42037_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f661ebc-454d-44ab-a42e-671be9eacd88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 52).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9483d6cf2dda74e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9dfe65a5-b4ef-4ac6-bbe7-7752f60999e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 52).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f1d8a5d26b7bcc0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe3ca915-ff76-4884-ba38-3863665cfa3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 52).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '6053c709e4785af3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be6353e4-e07a-41a0-8840-814c1f06ad29', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 52).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2d798984c46eb016_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('166581c9-d61e-461a-adb6-344ad6f32708', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 52).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '62b4b971a3bdf9b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('412a497e-3fb9-4255-bb46-87b8e70b5280', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 52).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7cfa6b510c5ae74f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55c79dc6-1697-499e-afb1-d18901310e14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 52).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '6f46f6126378d006_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75b74ceb-1b73-48d4-8648-edf2bba9f4ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 52).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b450216116b3ffb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('572da294-5094-495f-ab18-03cdcb87024c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 52).', '[{"id": "A", "text": "set router-name R7", "is_correct": false}, {"id": "B", "text": "set system name R7", "is_correct": false}, {"id": "C", "text": "set hostname R7", "is_correct": false}, {"id": "D", "text": "set system host-name R7", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'cf4796ef729394f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('faaa60cb-dda5-4445-9dcb-6076a5cdd7ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 52).', '[{"id": "A", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd79fa895b4b4117a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('483650f2-8a83-4c06-a497-b9ff001f2f2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 52).', '[{"id": "A", "text": "set ip address 10.110.125.254/24 interface xe-3/0/1", "is_correct": false}, {"id": "B", "text": "set interface xe-3/0/1 ip address 10.110.125.254/24", "is_correct": false}, {"id": "C", "text": "set interfaces xe-3/0/1 unit 0 family inet address 10.110.125.254/24", "is_correct": true}, {"id": "D", "text": "configure interface xe-3/0/1 ip 10.110.125.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '6201acf93358b03b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73efcb33-7e29-4016-a476-253037fc89fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 52).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b8bea4c20625da24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('976205ce-7408-4d56-afc0-7d50c334a5f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 52).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'fa5e213c6df4d745_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45cfd3de-8a98-4dca-8ae8-f765e23aee14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 52).', '[{"id": "A", "text": "monitor interface et-1/1/1", "is_correct": true}, {"id": "B", "text": "tail interface et-1/1/1", "is_correct": false}, {"id": "C", "text": "show interface et-1/1/1 monitor", "is_correct": false}, {"id": "D", "text": "watch interface et-1/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '342a0da1ad548ad8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('827f84d1-0c19-490e-afbe-c1b641d3d54b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 52).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'fa365bdcb13a8b25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d4a7f25-61fc-4846-baef-e2a8eaca9d40', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 52).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '69afef905e3e5771_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc0ace0b-39a3-4477-a33b-560e581f8c86', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 52).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '24754788dfecc66d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec7edb94-18b8-4013-af56-2ad24f8a8b69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 52).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '9878dd6b97a97d19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbae1446-276c-4a70-8325-e9e222950960', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.8.167.0/24 via next-hop 10.181.59.1 on Junos (variant 52).', '[{"id": "A", "text": "set ip route 192.190.99.0 255.246.4.0 10.181.59.1", "is_correct": false}, {"id": "B", "text": "set route 192.8.167.0/24 next-hop 10.181.59.1", "is_correct": false}, {"id": "C", "text": "set static route 192.8.167.0/24 gateway 10.181.59.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.8.167.0/24 next-hop 10.181.59.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e55afe6660dac5bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1d42f92-a835-4583-be81-baf484bd3b84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 52).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '32c3b1a702c8531b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e92507ac-3280-4234-8ba5-98b4d73fc307', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 52).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'e54bfa7f4ca6b1b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87895f03-0edb-4d7c-bab9-cd14e247bd7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 52).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9dc2dba15179ca89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6f686f3-9f02-48dd-b518-85bab8589c13', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 52).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ad15ec589dcc414c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa27252d-1ec3-43f6-a70b-010f7785ab79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 53).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '465857c5d8c86556_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01c626f8-9ae1-4923-9dfb-541b28682d20', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 53).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '504281be9c9683fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8865071-a2e0-4f92-b8c9-95953b810a24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 53).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '9b6f0ac7602651d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05c25385-13c8-4a44-a07d-70341440fead', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 53).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'c16b51af7398e763_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76a4f0e4-1e1d-41f2-9ca6-d9bd16f65068', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 53).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '91f87071a0532d88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16a37287-cc81-4db3-83cb-e4dc00023e7d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 53).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '44568e0427eaecf4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a41a65a-169a-457c-8f09-d8df281e5322', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 53).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '208a077edbd338f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e7ece08-a902-4c17-aeff-b33aba5d3028', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 53).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '653ecf84abd762e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8eee127e-78ce-43eb-b2c9-8f8db317e403', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 53).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f7030b7035ab2343_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de480dff-4bcc-48f3-ba27-51564151c8a8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 53).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'c5b56ff37e470c2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1cf8ba0-58f5-4d5f-832c-a2e8016940dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 53).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'dc3a4c8ac5bf0221_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1451985e-2416-4877-8d16-ffe878d0c5fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 53).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'dacb6eff5313183a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b99740a-fe8f-484c-ba60-9bcade76b0f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 53).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '88ccc126dc273ed2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c116992-efef-475a-8227-f744323bc6ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 53).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fb2fbb1711419b10_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('675a67b7-de89-4c52-ba27-e823608e035c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 53).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '788e4b312f7566a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01c05eb1-4788-4e7f-affa-3b1bce23de20', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 53).', '[{"id": "A", "text": "set hostname R5", "is_correct": false}, {"id": "B", "text": "set system name R5", "is_correct": false}, {"id": "C", "text": "set system host-name R5", "is_correct": true}, {"id": "D", "text": "set router-name R5", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a24c3ee33eeeb97e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9c285fe-5104-4b92-be78-1cf400346708', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 53).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6bf014206569dac7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('997ea9c5-3a17-471a-85e9-ebbf70a4155b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 53).', '[{"id": "A", "text": "set interface xe-2/1/2 ip address 10.122.105.5/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.122.105.5/24 interface xe-2/1/2", "is_correct": false}, {"id": "C", "text": "set interfaces xe-2/1/2 unit 0 family inet address 10.122.105.5/24", "is_correct": true}, {"id": "D", "text": "configure interface xe-2/1/2 ip 10.122.105.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '1681b71db46ee144_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cc0b344-cd38-49be-8fa9-ee6bd38c2f91', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 53).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9603f629f8d9cd86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7ed0d73-44a3-45a6-9226-d33059e64f10', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 53).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '650b51ff03cf4df6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bc91e87-c494-43a3-954f-a0889d1ebe94', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 53).', '[{"id": "A", "text": "tail interface xe-3/1/3", "is_correct": false}, {"id": "B", "text": "monitor interface xe-3/1/3", "is_correct": true}, {"id": "C", "text": "watch interface xe-3/1/3", "is_correct": false}, {"id": "D", "text": "show interface xe-3/1/3 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '567fee456e39a3bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33a96b18-2759-4f68-98c7-a21b3cbdc92e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 53).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c9e20beeb26ef891_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e5b5920-0914-47ae-ae6a-0e60a517f6b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 53).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e684bb206aeea48d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3698bb83-5daa-4940-97be-8919c8fbc6f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 53).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '93210b1ab7cf1445_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbf098ac-7c6f-42e8-be13-5c9351c2b41d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 53).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5c7b921ac2db9c04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7388a44b-d71d-496e-9049-a019dbb25e95', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.140.130.0/24 via next-hop 10.80.112.5 on Junos (variant 53).', '[{"id": "A", "text": "set route 192.140.130.0/24 next-hop 10.80.112.5", "is_correct": false}, {"id": "B", "text": "set ip route 192.138.137.0 255.36.100.0 10.80.112.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.140.130.0/24 next-hop 10.80.112.5", "is_correct": true}, {"id": "D", "text": "set static route 192.140.130.0/24 gateway 10.80.112.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '61209c21c0b72870_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c58bae97-cd5d-41c7-9f3c-24c0d4b83a97', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 53).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e9d2df517e668965_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33310bbd-2bc1-4708-8e48-96e9312f7a2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 53).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'cfb385e35e8a955f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ade6b016-9bb3-47e1-a3b2-9e404710023f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 53).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4d9426f08e96f55f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48339728-95b3-4e3c-856a-3824bdc6589b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 53).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '34d7e419acc94efd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1dae9f9f-0c52-4c95-85af-6de4a7a356bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 54).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'eb0f99b2ad2e80e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a3b4d08-6804-4783-b0d5-6ce2c7ba0cf8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 54).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '95f6bf9fcfa0e755_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adef655c-170f-4276-9f85-d70bcdaca971', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 54).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '6fc490290601cd15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('335526c2-e788-44b1-ab97-ea3797502fb5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 54).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4b7831a3f25ea8c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('998fcb82-26f5-4897-b8eb-610a04210286', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 54).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '1b26ee36a563241a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a061b7ea-3507-42ce-8805-22144140b180', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 54).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'ff2cf68ec797e4a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30b6e23a-3a0d-444f-ac84-f1b67cfad7bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 54).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '02b24d5b8d1e590d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83abb4e6-2d34-4516-9446-351d1e0a12b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 54).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1f72374c7406b5d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c484eb7b-74c2-426e-b419-33e6a7e37884', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 54).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5a95f6568db1583f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1340981-6b67-4e57-ab9e-9a74f71779cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 54).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '472809528e6b88e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00090732-f7b6-4255-a96b-4eb0929c13f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 54).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ded707963ff23e9a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de740370-0bb4-4a47-b9d7-901076f61c25', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 54).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'eaf6e47749c9d8e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc86e3b7-3b4f-49ed-b729-27b449e2a4f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 54).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '8fe69d01a00f9ef3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2429a3b8-7b58-414b-8bde-f9236fc80cc7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 54).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '6da0ec9d9e7dd518_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d7eaa1b-8c41-4344-82f6-6a4225685352', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 54).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4010383d835fb3d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c798a730-0716-4196-af32-30a0ab294925', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 54).', '[{"id": "A", "text": "set hostname R3", "is_correct": false}, {"id": "B", "text": "set router-name R3", "is_correct": false}, {"id": "C", "text": "set system name R3", "is_correct": false}, {"id": "D", "text": "set system host-name R3", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a8e404e66af755ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37314009-2c2c-4baa-a102-e7ee63c226d7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 54).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f41a0c9232e4e592_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5dd27e7-7793-412b-9d43-06b4fa3ad332', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 54).', '[{"id": "A", "text": "set interfaces ge-2/1/1 unit 0 family inet address 10.186.224.1/24", "is_correct": true}, {"id": "B", "text": "configure interface ge-2/1/1 ip 10.186.224.1/24", "is_correct": false}, {"id": "C", "text": "set interface ge-2/1/1 ip address 10.186.224.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.186.224.1/24 interface ge-2/1/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '90deede92dea1d4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92e66d82-9fca-4ee7-ad43-bbf53abd7974', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 54).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '90afada29910360a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37edb649-7ec4-4d6e-b462-6ca879ff6c3e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 54).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8c6d0a3da306457b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f3f064e-3fa6-48f0-b090-fddc1b62c569', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 54).', '[{"id": "A", "text": "watch interface et-3/0/0", "is_correct": false}, {"id": "B", "text": "monitor interface et-3/0/0", "is_correct": true}, {"id": "C", "text": "tail interface et-3/0/0", "is_correct": false}, {"id": "D", "text": "show interface et-3/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ac788e46c74afffb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('244663ea-7f50-43b3-bebf-7f8cbe11363e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 54).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '74afd4c504adf51f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48c1d6f4-8c65-4aad-afea-16cf61c96369', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 54).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b1ef2c6d9a3ec27c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efc198ba-171a-4ee2-890b-14702291bb8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 54).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'ee29ea4b3ec3d55d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a55adc4-3c36-4214-992e-f30feae91751', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 54).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '365f50463de485db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b52aeed6-47a1-4456-9669-2cf196008206', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.141.94.0/24 via next-hop 10.30.233.1 on Junos (variant 54).', '[{"id": "A", "text": "set static route 192.141.94.0/24 gateway 10.30.233.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.141.94.0/24 next-hop 10.30.233.1", "is_correct": true}, {"id": "C", "text": "set route 192.141.94.0/24 next-hop 10.30.233.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.35.14.0 255.103.252.0 10.30.233.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd6052b8cb00e9a89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e180f2b8-34f0-470b-9e8a-047605a8e22e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 54).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5b0492d808c5af04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2b6a345-05ae-4270-aab5-42a46bee29b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 54).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '8dc57116750c8c65_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d129cff8-2aad-4280-aba5-c16b7d51a16b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 54).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b5dbd8996cfa1291_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b09e92c-2c90-499c-a9f5-d4df55d7aaad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 54).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '038411c05bb5d3a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8b5c453-68ae-4386-8fcc-456f8fedd3c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 55).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b5ec99f894f3e138_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('591ac4d6-d0cb-4a9e-96b5-77782a50ccc4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 55).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'e28d15a46f15267d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bb08f5d-cb7a-489b-8779-81b3aab21545', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 55).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '73d9a706aeae85de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9144a156-259e-4d11-b466-bab50f8ca2ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 55).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '1b641acb8e8ba76a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34d6ed02-d90f-4934-b397-55157b4b04bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 55).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '8f0da22abb1b9144_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03a0f278-1364-47ca-8e0a-af444549369b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 55).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '53cc95208eceb536_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72dff2ff-395f-40c0-b8ff-b833b93a154a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 55).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9a8ab1b91e8cc5ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('025e55c4-04f5-434f-a033-29368d24e0c7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 55).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '771a9ce3c8998e84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b15e4f1-f085-4c4d-9e2e-479cb8202ad9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 55).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9f537b05f09022a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b30a00f-ab43-41c1-a838-206827622d27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 55).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'f1d4a05d1794b794_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('844a462d-2a8c-492f-8916-7336e355c539', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 55).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'db6ffeef34777a90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e9c34a6-b70d-4911-81e6-4a936f34ad00', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 55).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f0aab7af327f4f91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5858c11c-5cbb-4013-a05d-73d353070ac9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 55).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '8b1c46bc7021129d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a8d6fe6-3cf1-4cf4-830e-d92239d88b4e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 55).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7a02ba1c60ec69ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48a182b9-e1b9-48f2-bc00-57abf8e237c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 55).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'fbea241370b5d99f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('425a3918-30fe-473d-a34e-72371ac6887f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 55).', '[{"id": "A", "text": "set system name R6", "is_correct": false}, {"id": "B", "text": "set system host-name R6", "is_correct": true}, {"id": "C", "text": "set router-name R6", "is_correct": false}, {"id": "D", "text": "set hostname R6", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a41de81026dcb0d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ddccf67-ece0-43ed-89b5-bc2b4ef34894', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 55).', '[{"id": "A", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set user root password", "is_correct": false}, {"id": "C", "text": "set authentication user root password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'acbb5207c8cce013_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09671c9f-40c8-4380-9cd4-92d598289ed6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 55).', '[{"id": "A", "text": "set interface xe-3/0/2 ip address 10.177.235.5/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.177.235.5/24 interface xe-3/0/2", "is_correct": false}, {"id": "C", "text": "set interfaces xe-3/0/2 unit 0 family inet address 10.177.235.5/24", "is_correct": true}, {"id": "D", "text": "configure interface xe-3/0/2 ip 10.177.235.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'fd76457b30fd7c14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04fc4399-9176-4d63-ae0f-52c36abab096', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 55).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '63d56bd2241f83f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d451b55-979a-4d56-92d8-c7e06e50c7b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 55).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '0adc1d67afcb42b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('070ec649-e5b5-4d08-960c-60eefc3bffa6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 55).', '[{"id": "A", "text": "tail interface ge-3/0/0", "is_correct": false}, {"id": "B", "text": "show interface ge-3/0/0 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface ge-3/0/0", "is_correct": true}, {"id": "D", "text": "watch interface ge-3/0/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'def1645d20dd5fdf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65f5f5d9-5ab2-42f5-b0c1-b3a668d19dad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 55).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e0f99239ca73fa9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('904cf107-bd22-4b6c-8964-8748d00f1e0f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 55).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '321d9d13eae12b6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30f486a0-584e-4885-af8a-952aaffc48c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 55).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '69752ea3f45f3af2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bef6049-7f12-4c48-aee7-6d93f64a236a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 55).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '9fea9048f7786ec1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb143c7c-6569-4f58-a6bf-7f170ac10703', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.248.56.0/24 via next-hop 10.55.225.1 on Junos (variant 55).', '[{"id": "A", "text": "set ip route 192.163.160.0 255.245.126.0 10.55.225.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.248.56.0/24 next-hop 10.55.225.1", "is_correct": true}, {"id": "C", "text": "set static route 192.248.56.0/24 gateway 10.55.225.1", "is_correct": false}, {"id": "D", "text": "set route 192.248.56.0/24 next-hop 10.55.225.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '800672628b5b81f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('420432e9-5329-4798-83b9-51b95fa2020c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 55).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '71e3564680d7e121_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44f738aa-1414-432b-a9b8-8644849260ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 55).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '9a8a546658df2d7a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80cff177-6037-434e-8b8a-8395b0fc3ba4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 55).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd23c664b7954799d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c327656-a183-4324-bafa-96ebccc8ad24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 55).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0a7174c3d2233053_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1a48f9e-95e6-4b15-b822-d160228a9683', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 56).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '8309a634142077d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8206fa5-027e-4656-bf90-b46c3991dbb0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 56).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '4ae1fc4b8ffc2864_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('713076b6-b7ed-4e3e-998e-4680a8150270', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 56).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '5aa9e34dc219e869_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7914df5e-02f9-4263-9ed3-58d0128424d2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 56).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4ed941a3dd2d7f0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8da39c67-eb27-4dbe-afee-52d04092e8e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 56).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'b537ddc338277324_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6185e4f-527f-48b3-b172-fb64188efe67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 56).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '6d55e199b7b38caf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('424466f4-8a11-43c8-9584-32523a399e5c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 56).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3b58bc87de21e440_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6af3d887-1af7-47ea-b0ea-be7a80c5fb67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 56).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1a3f3d5ab9ac7afa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85a41eee-a600-4b57-b880-7705ea1b57ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 56).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7ddc8eaa261eabb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eacb8162-454a-46dd-9c3d-08709610d47a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 56).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '0dd5d2492709b080_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f07133a-142b-4a35-ac83-c51b46fb4304', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 56).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '373fdbbcb0a64858_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('960543a0-4901-490f-b27a-91289ed58069', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 56).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ff25e41a26ffeaab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d93149be-2f3c-4b52-a008-aa42f121bb2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 56).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '37f382d99741e1ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db04b776-21ea-412b-97e0-b3ef400c006a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 56).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c674f758a33afc90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3422cbac-5678-45ed-8c82-35de1d10294c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 56).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f00a514139e82e3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64481dc1-7860-42cc-b7ba-f66eeb7c1d82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 56).', '[{"id": "A", "text": "set hostname R9", "is_correct": false}, {"id": "B", "text": "set system host-name R9", "is_correct": true}, {"id": "C", "text": "set system name R9", "is_correct": false}, {"id": "D", "text": "set router-name R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '38c6067d0d52c386_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3368915-f7de-4e09-987a-fa1679e5341f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 56).', '[{"id": "A", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "set user root password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd80d37a548dd8cc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('039a1fc4-e30b-4caf-bc14-00f8c75859c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 56).', '[{"id": "A", "text": "configure interface et-1/0/2 ip 10.27.35.5/24", "is_correct": false}, {"id": "B", "text": "set interfaces et-1/0/2 unit 0 family inet address 10.27.35.5/24", "is_correct": true}, {"id": "C", "text": "set interface et-1/0/2 ip address 10.27.35.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.27.35.5/24 interface et-1/0/2", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '04f4f12dab2b224b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78ff7787-1f8d-4f1f-9f06-eb0b0bf172a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 56).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a2237bff6296fa32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef8c9691-9c63-4666-8441-ef7f6f106e20', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 56).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '312924ecba2f65a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0afabc2f-c566-4dc2-9984-83fd2daf0fac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 56).', '[{"id": "A", "text": "show interface ge-0/1/1 monitor", "is_correct": false}, {"id": "B", "text": "tail interface ge-0/1/1", "is_correct": false}, {"id": "C", "text": "watch interface ge-0/1/1", "is_correct": false}, {"id": "D", "text": "monitor interface ge-0/1/1", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7d2ee3d56c9ad35d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1173d6f8-6535-4b55-adcc-15ecf49d0f8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 56).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b597d26bebac54dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc74277b-db00-4ad9-821f-ed03d415a131', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 56).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '649f8166e7c216f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27bc174f-ef07-48d1-8c13-3f78d7586ad8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 56).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'b8efa3663907a650_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5088fa3-82bf-4c36-80c1-8f2b3ab99b0a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 56).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'da24736a0a963c70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c53eec0-e0dd-4b7b-932c-c0a6ce70c295', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.63.113.0/24 via next-hop 10.115.3.254 on Junos (variant 56).', '[{"id": "A", "text": "set routing-options static route 192.63.113.0/24 next-hop 10.115.3.254", "is_correct": true}, {"id": "B", "text": "set route 192.63.113.0/24 next-hop 10.115.3.254", "is_correct": false}, {"id": "C", "text": "set static route 192.63.113.0/24 gateway 10.115.3.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.217.151.0 255.46.241.0 10.115.3.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3b015eac3f193698_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7c59031-2bf9-4a9f-ac29-6d81d8b13b74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 56).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd8a597416b901ef3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea1cef4b-3696-40c5-9dbc-d8acbfa9eebf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 56).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '295006abf550cdce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b728300-d03a-4159-a12b-5d05bf31d41f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 56).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '349ebba719ee7f9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e880920d-e0b1-48c1-b74e-d697e9498d72', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 56).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '05357bbd96a5be99_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('850c3281-09cb-4d51-88cd-8587dbde4d13', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 57).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '59fffb19c28c1125_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70cabf81-82e2-4491-bcda-add74c0c83ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 57).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'bfca893c6010bf95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd02eadc-2caf-4b0e-8fbc-4f2971180035', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 57).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '110108498c0d07d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11c4d511-b175-4f27-9f9a-3169fce2264d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 57).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '784bb804a9288270_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2d58a40-454d-4013-be8a-273bc4876417', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 57).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'c4a2a8f5123b1a72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('baf26705-b4ec-41d9-a250-17f7924e85e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 57).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'a43f47dd5978297c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e53d7538-7b58-4436-acad-360d25ec3338', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 57).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5ff7af0474e59d92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99f6f014-bc69-4aa9-98eb-1485b15bf821', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 57).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '869c180c3b84b4a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17c821e3-48d0-4f7e-a8ec-0eecce18f442', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 57).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'bde9f08cceab91d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9017dd4b-69bf-4e6d-813b-8af64f7eb981', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 57).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'a4e690f9914ae041_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db9ddae8-8c77-470e-8f1f-136e1217f020', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 57).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2300cdb448ec1196_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44caae77-a03d-4277-a400-7c0b0c79b47c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 57).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '454414a9a900f4dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d49879f-853f-48ab-bb0b-a6b73a2813fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 57).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'cd13a476ec5c527e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66810b57-87e4-4372-a18a-d84f30fe9cc0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 57).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'd4f9f53fe38e4bb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cc90d22-f073-4b4a-873d-bbba37ab271d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 57).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9d692db0a2a784e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b956cb7-b940-4730-9b4d-9548fcfbaf38', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 57).', '[{"id": "A", "text": "set system host-name R6", "is_correct": true}, {"id": "B", "text": "set router-name R6", "is_correct": false}, {"id": "C", "text": "set hostname R6", "is_correct": false}, {"id": "D", "text": "set system name R6", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9365600429c56eac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4e7479c-6922-4b5a-b9f3-30d42eed8dfd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 57).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'df262bf4c412bb99_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3aaf2ce2-97de-4435-87ba-46466fd84c63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 57).', '[{"id": "A", "text": "set ip address 10.41.110.1/24 interface ge-3/0/1", "is_correct": false}, {"id": "B", "text": "set interfaces ge-3/0/1 unit 0 family inet address 10.41.110.1/24", "is_correct": true}, {"id": "C", "text": "configure interface ge-3/0/1 ip 10.41.110.1/24", "is_correct": false}, {"id": "D", "text": "set interface ge-3/0/1 ip address 10.41.110.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '10b4fb31f859b9c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3c81da9-3b3f-48a5-aa5d-f273708b8db5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 57).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'fddcfbf70abaefc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2c97946-5af1-43ec-b4d6-5f96114d8bdb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 57).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd332fbc70c697744_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bcaec10-b941-466c-b390-972b74eecbdc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 57).', '[{"id": "A", "text": "monitor interface xe-1/1/3", "is_correct": true}, {"id": "B", "text": "show interface xe-1/1/3 monitor", "is_correct": false}, {"id": "C", "text": "tail interface xe-1/1/3", "is_correct": false}, {"id": "D", "text": "watch interface xe-1/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f551a7d43c52f0c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('277308b1-4e48-44fe-8496-765df39bc88b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 57).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b21c69994f46e77a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4fc338a7-371a-4b84-a202-fcde3dd13996', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 57).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '22bdcdfbfe0409a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48e36388-8424-4419-8e3a-eb5f3a3949a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 57).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '6996464880f658a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('023957ff-a504-4e50-b400-6d8e9fb970a8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 57).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '742d50ba357c3ee7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2d76759-9271-4d24-a0d8-3a77c296b449', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.175.79.0/24 via next-hop 10.164.248.254 on Junos (variant 57).', '[{"id": "A", "text": "set ip route 192.165.11.0 255.74.128.0 10.164.248.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.175.79.0/24 next-hop 10.164.248.254", "is_correct": true}, {"id": "C", "text": "set route 192.175.79.0/24 next-hop 10.164.248.254", "is_correct": false}, {"id": "D", "text": "set static route 192.175.79.0/24 gateway 10.164.248.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6baa17f709d489eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29cba43f-f94d-4961-9b89-42c5d0f27d76', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 57).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '27fb80f3fa64c370_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('415e94de-8191-4e23-81c2-0b78de401231', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 57).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '768cbd8f59719419_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf50e648-58f5-48aa-982f-e1ab6234e8b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 57).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '296450775c9327a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('110f66cb-4948-4f6c-a04e-7274b21cb06c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 57).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9802cd8fb36d771d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98821dbf-5b4b-4744-b26c-07a10332f4c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 58).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1bd0d7d00320d33e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80c6be67-2983-4d8b-9f34-542e10b55ced', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 58).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'fe114650ce04ebe5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('586558ef-57cf-42c3-bbb3-4598964b65b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 58).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '30644ac86f9916db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('196ee36b-2956-4f11-a78f-b2beab5b65cf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 58).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '5e49884c3cbb2924_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13de7740-eeb0-4d57-920e-2bf3cd0ba0fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 58).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '86cc1119bd3005e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91a42b41-49ca-47e7-a35a-72b142db3b27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 58).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '50cc41b6a7ad77ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3128cceb-8be3-4bd4-802e-6f77e1f6ba10', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 58).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e6f968350bc91ed7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('231f0f0d-4613-45b1-a045-ca40ce3580ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 58).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '63f7b061fae656e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e5cf028-f7c5-4445-bb50-ff99953ae50d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 58).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '28f337359763db1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea082bde-26ee-40ed-80b6-8738cdee32e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 58).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '2bf242d8ddb87835_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f77b1bc3-e053-4ba5-8007-a75114b913b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 58).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '9cd413e6c3e21d40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b20e6b0-2cb2-4a0a-8a7a-e681f928cb79', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 58).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a2f3429db5bd199e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cac271a6-0079-4be0-80dd-bdeba2c01174', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 58).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '77dbeada22ab8977_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('553a4757-729b-4f6d-a490-21d1a47b289d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 58).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'aa1e3c1d6cfc0a91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d925f7b-afac-4a15-9050-5d2e1ce1587c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 58).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4df5afe6c830be4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3c3740f-d971-4cf1-a47b-a4df460cc345', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 58).', '[{"id": "A", "text": "set router-name R11", "is_correct": false}, {"id": "B", "text": "set system host-name R11", "is_correct": true}, {"id": "C", "text": "set system name R11", "is_correct": false}, {"id": "D", "text": "set hostname R11", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '75cd49c53b552c4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecc004ca-3662-4cf7-a9a4-9aa6761d9a4d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 58).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '45ad7629d0cd37c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ea610b7-8d2d-4d85-a339-19fcb2180d8c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 58).', '[{"id": "A", "text": "set ip address 10.162.123.254/24 interface ge-1/1/0", "is_correct": false}, {"id": "B", "text": "set interfaces ge-1/1/0 unit 0 family inet address 10.162.123.254/24", "is_correct": true}, {"id": "C", "text": "set interface ge-1/1/0 ip address 10.162.123.254/24", "is_correct": false}, {"id": "D", "text": "configure interface ge-1/1/0 ip 10.162.123.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '9770afb5773a3e44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b421ad7b-3324-48a2-a874-59b26dfcc643', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 58).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'cfd6c53caf5bba20_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68f48045-30b1-4097-aff0-45f1d9f1fef7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 58).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '489dd92849c00c1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fbab186-ef16-4188-b341-09b18315a987', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 58).', '[{"id": "A", "text": "watch interface xe-1/0/0", "is_correct": false}, {"id": "B", "text": "show interface xe-1/0/0 monitor", "is_correct": false}, {"id": "C", "text": "tail interface xe-1/0/0", "is_correct": false}, {"id": "D", "text": "monitor interface xe-1/0/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8e8b1facb934ccd0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2320e1d5-de4a-46c1-9256-a819fb480608', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 58).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8cde564899f889a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc0244fb-9a86-47ad-84f2-561b59ceb89c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 58).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1c6a13041bc868da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('769a4d04-8370-463e-b2c3-7a64aabfddfe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 58).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'bbf5019cbd99f8fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af8abb46-792e-4a61-bd0b-87faf953a1ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 58).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7d3679a0881f12ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7348e32-ba8f-4ac4-8f71-43d3a853d96f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.57.128.0/24 via next-hop 10.86.37.254 on Junos (variant 58).', '[{"id": "A", "text": "set static route 192.57.128.0/24 gateway 10.86.37.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.57.128.0/24 next-hop 10.86.37.254", "is_correct": true}, {"id": "C", "text": "set ip route 192.187.192.0 255.40.79.0 10.86.37.254", "is_correct": false}, {"id": "D", "text": "set route 192.57.128.0/24 next-hop 10.86.37.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '70fe7c77a1f886f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ff2dc13-f731-49a5-8390-5dd9f3014645', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 58).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7a7e27b3236a8e72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c98ee056-e488-4910-9adb-9089a0c001d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 58).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '574fb24a0c95abe9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f85a30e0-e610-40f9-bbfe-24c3a6a57a88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 58).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '35a1119ed98a5b7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e7a43d0-23ea-49f8-8f2f-a0f3f4e5dd92', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 58).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c2577d4344ba32e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d85c2635-8dcd-4a99-97da-a044a7e6817f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 59).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '7c9f5156a19ad5a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('202a5718-9b3a-4870-85bd-852fdddbb0c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 59).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '50678b9d22fc3171_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be16ec58-09c1-4d1f-abc8-f4fa2aad779e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 59).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'b639e8f0b9260086_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('074100c2-a203-4993-a127-e2dc2d19d4c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 59).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'e33e09dac3bf19fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e027da6-b193-4ecc-a973-cb5695fe2c4e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 59).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '42520189973921b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd2b42ca-f3cb-43de-bb6e-240817face2e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 59).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b330e2b16586e073_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b81c16b8-490d-43ee-96a9-202bd97b3c1d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 59).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '44164ef67f053ee6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e08c7bde-dfc6-4ef9-beaa-9e7ee95bbb32', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 59).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8a24415668c79a1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('490cf590-17cd-4d7e-ac08-1a862af0a941', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 59).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'eefe6fd507ebb306_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b88bfe6-44f5-488f-912d-7ac57fd3cccb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 59).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '957528447c701a11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bba8a739-612a-4a0f-a86e-6dfc27266d82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 59).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '09732794f601d67f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf8c0d76-cd1b-47c4-81fd-b612c73912ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 59).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'af643c79058aa665_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44c9a305-7a3a-492a-a6fe-1a7c27d61c69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 59).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '03c002e02d308168_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b82ee434-6fa6-450d-ab7a-0bf404395c4c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 59).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7df4f32d2c7b7e25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8eb6f45-8377-4b41-9b03-a2c7ecf011f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 59).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ee594147709537af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('426349c7-19a7-490c-a5bc-fabe473deb98', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 59).', '[{"id": "A", "text": "set hostname R7", "is_correct": false}, {"id": "B", "text": "set system host-name R7", "is_correct": true}, {"id": "C", "text": "set system name R7", "is_correct": false}, {"id": "D", "text": "set router-name R7", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b7e0a2634bccc85b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('878bccc3-e1d9-4118-9935-6b7623952481', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 59).', '[{"id": "A", "text": "set user monitor password", "is_correct": false}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1652625628ae4453_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55405284-bb10-49a7-b177-0868eadfdb3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 59).', '[{"id": "A", "text": "set interfaces et-1/1/1 unit 0 family inet address 10.115.249.5/24", "is_correct": true}, {"id": "B", "text": "set interface et-1/1/1 ip address 10.115.249.5/24", "is_correct": false}, {"id": "C", "text": "configure interface et-1/1/1 ip 10.115.249.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.115.249.5/24 interface et-1/1/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'a851ffdc223c215f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8bb7fbc7-b75d-4e5e-bb23-e32d72590167', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 59).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '013ca71c1e768c9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b261e458-1b7f-4185-ac19-7c3cf0660f40', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 59).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5122959b2a1b95c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d54d1963-5ad0-43f1-84dd-cc457ab7cd58', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 59).', '[{"id": "A", "text": "watch interface ge-2/0/0", "is_correct": false}, {"id": "B", "text": "show interface ge-2/0/0 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface ge-2/0/0", "is_correct": true}, {"id": "D", "text": "tail interface ge-2/0/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '9c030ad72937b325_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('088d7b79-87c8-45b3-bd6c-66b871470ee0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 59).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a2fa09b21d26a492_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b290b61d-ab52-40b7-a577-88961a39e442', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 59).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1da3e844312464bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2da344c5-cf29-4a0b-bc79-e4b4796f6b69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 59).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '80e9c8056241924c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffeb8ee2-6d08-4130-aa2a-4abbd54b9239', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 59).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e2d11ecd626b0c67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1439b04-1744-4a82-af2c-eba2bb3e9edb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.172.70.0/24 via next-hop 10.129.75.5 on Junos (variant 59).', '[{"id": "A", "text": "set route 192.172.70.0/24 next-hop 10.129.75.5", "is_correct": false}, {"id": "B", "text": "set static route 192.172.70.0/24 gateway 10.129.75.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.172.70.0/24 next-hop 10.129.75.5", "is_correct": true}, {"id": "D", "text": "set ip route 192.200.155.0 255.236.215.0 10.129.75.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '177a360e28208f0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b26e430-979f-4ea2-9ca3-e4bfd8c5ae82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 59).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7bcc854a4deb7f7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bd5dae2-c9a2-428e-ab69-32eee1020493', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 59).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b83f848eb039e2e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e27a4aa1-dd09-4f7a-abff-734c56b6011a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 59).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b84303c9967f37a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c751998d-9d6a-46fe-a07d-03a764610e85', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 59).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1143689699d98ab5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18113ed1-7e55-4895-90f1-a8c3a9154e4c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 60).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1031b9a084ac6db0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79578157-4d06-4a65-992f-1741990c986b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 60).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '2ebcb2701aef40e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7fed284-896f-4781-9544-d2b6f2fc4be3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 60).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '7e418454b586e238_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe60c95e-59c8-4acb-bf8a-2cbbd2ecfeb1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 60).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '093fe960c38b7efd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbef5842-2486-4344-b10f-85151f96051a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 60).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'ed3f07e0807a92fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18da1864-daef-4766-81eb-db0df6c39624', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 60).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '96636b29f4b0a871_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01885fab-5986-4bbb-8e85-f0d7fd92363f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 60).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f7f5939e38b2fc5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b1c991a-6018-4da5-8128-ee02213581e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 60).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7e6bb27f95e45964_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f72aae89-0527-4777-9a91-234fcf2ab337', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 60).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c8358f7065d4b0e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8dad43e-52d2-402d-a6a0-3295cab9f3ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 60).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'f73c0e30046c8e14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50c14ebc-37ba-45f1-9ea5-c7601735bda3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 60).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b8b10e93dd0f9090_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cce1994d-9e68-4d0c-ae14-cadc31566985', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 60).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fff16dd56d44c4ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0eb142bf-9609-41a9-9f00-ab5b1e808e81', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 60).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '28783951c3f0eac6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f152925-9fe3-405a-9b21-7651e450bfc6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 60).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'cbe3ebc97ce21919_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76d283e2-69f1-497d-8a1e-248d280a5581', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 60).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '652664bd478a7c96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e65058e6-096f-4c52-8ce2-54d55e53fe6f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 60).', '[{"id": "A", "text": "set hostname R8", "is_correct": false}, {"id": "B", "text": "set system name R8", "is_correct": false}, {"id": "C", "text": "set router-name R8", "is_correct": false}, {"id": "D", "text": "set system host-name R8", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7bfba884a2f1f9e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ac3cbd6-3e88-4989-93e8-781454852a0d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 60).', '[{"id": "A", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'efb938cc9744b5a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d537609a-20bd-4b5d-a9c5-505234082bb7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 60).', '[{"id": "A", "text": "set interface et-0/0/1 ip address 10.196.82.254/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.196.82.254/24 interface et-0/0/1", "is_correct": false}, {"id": "C", "text": "set interfaces et-0/0/1 unit 0 family inet address 10.196.82.254/24", "is_correct": true}, {"id": "D", "text": "configure interface et-0/0/1 ip 10.196.82.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'cc6a4b9f8552c930_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1271bb30-0803-4091-8710-0e4144c7ee7e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 60).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'bf5a744461f320cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b225932e-a2ee-4e77-873e-f0fe98353740', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 60).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'e00b8b3c18682d92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4226c77-2199-4190-a9db-92e98323121d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 60).', '[{"id": "A", "text": "show interface ge-2/0/1 monitor", "is_correct": false}, {"id": "B", "text": "monitor interface ge-2/0/1", "is_correct": true}, {"id": "C", "text": "watch interface ge-2/0/1", "is_correct": false}, {"id": "D", "text": "tail interface ge-2/0/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '4c4e3522108e7339_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a76c241-0b2b-4621-8504-475c4993fbac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 60).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5a1e06b3107858ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ad20444-decb-4c1d-b8f4-e2625f374134', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 60).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7366b7429b6649af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea181cb6-1642-4bd3-88fe-3a6a4963490a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 60).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '0267335b488f16be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90cfaf8c-4e2b-48ec-a955-5a70ce3d2a5b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 60).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '20c07b3593a61ff5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba97b4ed-3efb-428b-bcda-fd9374908933', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.122.124.0/24 via next-hop 10.223.171.5 on Junos (variant 60).', '[{"id": "A", "text": "set route 192.122.124.0/24 next-hop 10.223.171.5", "is_correct": false}, {"id": "B", "text": "set ip route 192.240.255.0 255.212.88.0 10.223.171.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.122.124.0/24 next-hop 10.223.171.5", "is_correct": true}, {"id": "D", "text": "set static route 192.122.124.0/24 gateway 10.223.171.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a9d1f0adeb0e806d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c746f1f7-5b63-4536-8c9e-f6e6987fc23a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 60).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '8d0184f978c51902_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e43277b8-edc0-439b-bea1-750484915b90', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 60).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b67fe0c676858aca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2c2f986-6041-44cf-a4fd-486f6cac7130', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 60).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e7d540a90e96f6c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6971486c-c448-40da-be4b-fe2c6de00335', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 60).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1acd914b2e6a8e98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7828cc36-b5b4-4a15-8e28-c17fdb5c2bfd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 61).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'c4c48eba22154815_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fb26bb9-451f-41b2-98b1-804ee0bdb0d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 61).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'ebca3a6341267727_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20dd8076-574c-4e6f-a9f1-2616075ff960', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 61).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'af7ba7e77520a301_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc27f30e-7778-484c-bb7a-7e6d8aa08480', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 61).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '12e6b70c3148aabd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef1433b1-5312-47f5-8d9d-40ad1f52c17e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 61).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '4578cea18f9c53c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb7fcae1-e6c1-4800-a9cf-9e8b97cfb7d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 61).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'd85701b80ac1e6a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c8733fd-b812-4ef6-9452-74b1a474f450', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 61).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e22bc5e402a30545_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06a67743-e1cb-47a1-a741-eeeaa86b3d11', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 61).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f31564c9c574be7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8b7e2fa-0c6d-4f0c-a2e9-b4f5f10bf70f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 61).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ec0781a51cc5cae9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('096bc248-93b9-444f-b1ae-5e2c8b9e9603', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 61).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '8cc6633160ab5468_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('511e2395-b798-4f8d-868a-056b2e81b1da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 61).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a67fd43cdda2c80d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a59f3c49-88a4-4060-84c3-fa0cf7dcc9c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 61).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'eb6c1db541f89ad1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4684d9e5-c3bc-4a97-b02f-e5429955218b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 61).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'aad3544edcadcddf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cf0e270-c720-45bd-96d8-0d04cfad8c78', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 61).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e0301725685374d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('059e9b51-75c0-4da4-b7cd-edec1fb27eb9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 61).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'd6a1cbcbaf192580_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0702da8-8d3c-45f9-9b37-d1b1a08f5c19', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 61).', '[{"id": "A", "text": "set hostname R5", "is_correct": false}, {"id": "B", "text": "set router-name R5", "is_correct": false}, {"id": "C", "text": "set system host-name R5", "is_correct": true}, {"id": "D", "text": "set system name R5", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '6c3aa936ff77cc95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6cfca6f-03d4-49b1-9bcb-7d18582905c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 61).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '230a279ab6d05700_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7da2b19-8d8f-4d43-a999-f266a601cc9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 61).', '[{"id": "A", "text": "set ip address 10.192.150.254/24 interface et-3/1/2", "is_correct": false}, {"id": "B", "text": "set interface et-3/1/2 ip address 10.192.150.254/24", "is_correct": false}, {"id": "C", "text": "configure interface et-3/1/2 ip 10.192.150.254/24", "is_correct": false}, {"id": "D", "text": "set interfaces et-3/1/2 unit 0 family inet address 10.192.150.254/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'ff8c685d75a08795_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14b78ff8-7cd5-48f3-a619-9723298d4281', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 61).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'de0865e41ebecfdf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f93bc4de-2fd1-4775-8656-493d0b90effc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 61).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '011b7518f5d8dfd9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e16585a4-25af-4d2c-b889-bf7d58b06c6c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 61).', '[{"id": "A", "text": "show interface et-1/1/1 monitor", "is_correct": false}, {"id": "B", "text": "tail interface et-1/1/1", "is_correct": false}, {"id": "C", "text": "monitor interface et-1/1/1", "is_correct": true}, {"id": "D", "text": "watch interface et-1/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd8530159d3ff5506_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6670f9a9-4da9-408b-853d-6de8ebf0f3ae', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 61).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8399c6ea0a797833_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eab05652-c6a1-42c4-99f7-4bfca84bf6d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 61).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c672dc73603b9f63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4def3db0-dc92-4f23-b81e-fff5caa0adba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 61).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '4e8915ea04f31bfe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b33efdd-0d60-4e84-beda-7a7c53406bb4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 61).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2a1ed1dda7fe2e25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bdb8ffa-f9b2-46f4-b54a-891f1d1a478e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.6.72.0/24 via next-hop 10.84.91.254 on Junos (variant 61).', '[{"id": "A", "text": "set static route 192.6.72.0/24 gateway 10.84.91.254", "is_correct": false}, {"id": "B", "text": "set route 192.6.72.0/24 next-hop 10.84.91.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.6.72.0/24 next-hop 10.84.91.254", "is_correct": true}, {"id": "D", "text": "set ip route 192.125.119.0 255.182.28.0 10.84.91.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3021026fe87c5123_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3f93ff3-4955-47c4-a30e-e36439a2e392', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 61).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7546b15726bc698e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dc8a620-a5f8-4300-8a4a-7e978e02164f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 61).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '8487bf6b5f9a5ae6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37a8df9e-1327-4276-9c23-71f73a463118', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 61).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f0a2aa69f5cf09c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c17e8779-bc26-49e0-9981-eabce8774919', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 61).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8b6bedd92777f1ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a7e793e-f6fc-44fc-99fb-4a47311edda5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 62).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '26ee8285899e42c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e54463e7-2fda-487e-82bd-9e17c762bfaa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 62).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '36263943298f21be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46e09afc-d572-42ab-a859-8a1bde66c424', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 62).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '002577bb4008606e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b201426-23e7-4ad8-8f96-4997891b2656', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 62).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'b1e00ab060696b83_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3997ee41-4ce8-4ca7-9715-c71989f693d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 62).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'eaf08adff8835d00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31aec971-265a-409a-9f2c-c666d50ecf9c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 62).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '574f021769b52caa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1632e62-7278-446a-9745-94acb30740ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 62).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '927c96e1a2436989_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac5ccf9d-f801-4dbd-ac8a-c36b423cbf49', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 62).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'bca0048a0be11b07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42ffff5d-6449-4eed-8d4e-6d5bada35b98', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 62).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '50bdb48196d19d07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6db6610e-fd87-4879-b7d6-4124d65bdc63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 62).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '8a34e3d95787bd3b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f1efc76-4ce2-449c-934e-f207333ad845', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 62).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '16c25e8c4b252ece_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f1f45ec-ff0e-43a4-9c40-ac456d115483', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 62).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'cf4a01884d28e2a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffe685d3-3061-4adb-b308-44e5aa036c4c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 62).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'c3e2dd9eba595f09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('662f07e7-893b-41bb-83ea-121022170b71', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 62).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '15804a673615df32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('428883c7-1129-4686-819c-35489104b775', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 62).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ecff5ef7219496d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41fb1af6-bd49-4c8c-80c7-7bdeb4185576', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 62).', '[{"id": "A", "text": "set system name R5", "is_correct": false}, {"id": "B", "text": "set system host-name R5", "is_correct": true}, {"id": "C", "text": "set router-name R5", "is_correct": false}, {"id": "D", "text": "set hostname R5", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e7d773d4a1f45f7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cc6e402-5925-4f15-a893-4aadfdc27044', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 62).', '[{"id": "A", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user root password", "is_correct": false}, {"id": "D", "text": "set authentication user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ce0759f89e23f016_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a206ca8-24ab-49e2-aa16-9d1a37f6dfed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 62).', '[{"id": "A", "text": "set interface ge-1/0/2 ip address 10.224.106.5/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.224.106.5/24 interface ge-1/0/2", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/0/2 unit 0 family inet address 10.224.106.5/24", "is_correct": true}, {"id": "D", "text": "configure interface ge-1/0/2 ip 10.224.106.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'c7269f0dd81e795c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6f321a0-4870-4ad0-8cb8-1462abbb2efd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 62).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ef1aeeb46259d162_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04e4312c-1478-4a3d-be01-2183f4eb476d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 62).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5a92cc6a8375c5de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4c6daef-f387-469e-b149-b1e03400386a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 62).', '[{"id": "A", "text": "tail interface ge-1/0/0", "is_correct": false}, {"id": "B", "text": "monitor interface ge-1/0/0", "is_correct": true}, {"id": "C", "text": "watch interface ge-1/0/0", "is_correct": false}, {"id": "D", "text": "show interface ge-1/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '4902051f1e719890_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a294a5e-7274-42ab-98dc-fc4bdddc1723', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 62).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '450a1157282c96f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('127bb5a9-1b39-4a96-8567-a811919da955', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 62).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8e404325e9956549_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8f14bc7-dc18-48eb-a0a7-2cebd11b43bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 62).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'c674c29d5c278c9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc5d5c3a-b0f5-4c60-95cd-309f8aae765c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 62).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '33e84654f120f83a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c29abf2c-4837-4afe-ad2b-52bccc5299ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.134.10.0/24 via next-hop 10.129.192.1 on Junos (variant 62).', '[{"id": "A", "text": "set routing-options static route 192.134.10.0/24 next-hop 10.129.192.1", "is_correct": true}, {"id": "B", "text": "set static route 192.134.10.0/24 gateway 10.129.192.1", "is_correct": false}, {"id": "C", "text": "set ip route 192.146.134.0 255.77.108.0 10.129.192.1", "is_correct": false}, {"id": "D", "text": "set route 192.134.10.0/24 next-hop 10.129.192.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5bf382d5bd874ae3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2507e89-9d13-480c-b1df-06f52749f86f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 62).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '9aa94611e463f685_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfc65ed7-b3f2-46df-a5c8-697b3bbba4ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 62).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '29515b31c1048678_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f249612-cf33-4ac9-a159-2712bfd559a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 62).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '94ead76dd1afd49e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75305cf4-d353-4063-9e8f-9114d05ca6e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 62).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '6c6b596f7baf86f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1d373de-8706-4c36-b063-0ea8a7d95397', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 63).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '8ae48e28f9b1965d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42876d46-4a46-4f57-874b-ede910cecfa3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 63).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '7f1e0130c8c4e2c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92473fc6-a161-4a0d-9d18-71264648f652', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 63).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '516d1bed3b5156b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2f89088-973d-4d5d-a743-6d13717ee44e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 63).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'dd1f509ddee328c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('319cb0f5-7b40-44a4-8509-3e4d4bbe9468', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 63).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '5476a362a482940b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e958e4d-77e7-48da-b36c-98dd50bfed5e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 63).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '26371ca0fceae6d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9e328a7-840b-420a-92fa-ba21fd23e390', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 63).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c3a4c60503362b96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('555491d4-0618-4884-ba63-1a621eef09e3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 63).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '780cab67fc84e7f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a37a5baf-ac08-44f0-9e19-66d48a0a052a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 63).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a3c3131a90547eac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51a7be6b-343c-4583-8b26-f45b5a4c00e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 63).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '28ea61843800320b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('460f790d-7d6d-4b99-86da-323e8fce8e77', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 63).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b4e4704b2f286bb0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4db0005-0344-4cc4-8fe2-2d19d665094f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 63).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a5730a35c4d770fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('349b4877-9d40-4aec-b6d3-5f73cae30b64', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 63).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a6f35100833cd5f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb492ea3-2c43-4a47-afb5-577baa1e15c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 63).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3e2c7133707cda20_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0deed4b3-a38e-460a-9391-4cf50e917e64', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 63).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'a966e8fa01780655_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8111c8b9-e238-4079-a699-c2f769aa7e09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 63).', '[{"id": "A", "text": "set system host-name R10", "is_correct": true}, {"id": "B", "text": "set system name R10", "is_correct": false}, {"id": "C", "text": "set hostname R10", "is_correct": false}, {"id": "D", "text": "set router-name R10", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5fbf97c6e5f53c54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b557eb2-a86a-4178-953c-23503461b559', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 63).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '453ef630254a467e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('579a5500-df5c-49f6-b67d-fc60272cc853', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 63).', '[{"id": "A", "text": "set ip address 10.143.73.5/24 interface ge-1/0/0", "is_correct": false}, {"id": "B", "text": "configure interface ge-1/0/0 ip 10.143.73.5/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/0/0 unit 0 family inet address 10.143.73.5/24", "is_correct": true}, {"id": "D", "text": "set interface ge-1/0/0 ip address 10.143.73.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '895c14dec7857a4d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('634a63c9-6ab7-4a94-b986-62765358ec42', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 63).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a1f32a07359fecea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2fe5e83-8aea-4a90-bd61-139462ccd953', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 63).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7bdcc9837fa151ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b976ed61-9f10-4c38-9d62-b63159b9a436', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 63).', '[{"id": "A", "text": "monitor interface et-2/1/1", "is_correct": true}, {"id": "B", "text": "show interface et-2/1/1 monitor", "is_correct": false}, {"id": "C", "text": "watch interface et-2/1/1", "is_correct": false}, {"id": "D", "text": "tail interface et-2/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'cdc7ffc5535aa600_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f580027a-e778-44ae-ac3f-7f761ccd273b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 63).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2495ddbd35208c47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('408bf496-3161-48cf-933c-5f1ea89315a8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 63).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ebd55b224fc34a66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f097ba6-48ce-4508-ba46-fe3fcec2854d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 63).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '0bd3d687d8051548_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('610f21f4-1194-48da-85ee-bd3e5bd90c52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 63).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6eea648cf435ecb2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3839620d-6df3-4fbe-97f7-4178be0b2f08', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.190.244.0/24 via next-hop 10.74.139.5 on Junos (variant 63).', '[{"id": "A", "text": "set static route 192.190.244.0/24 gateway 10.74.139.5", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.190.244.0/24 next-hop 10.74.139.5", "is_correct": true}, {"id": "C", "text": "set ip route 192.182.210.0 255.7.205.0 10.74.139.5", "is_correct": false}, {"id": "D", "text": "set route 192.190.244.0/24 next-hop 10.74.139.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1e59fcb2d9fceff6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11d6cb0f-5c93-484e-9a81-4e6209a0273c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 63).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '53b725c9584551b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('089091a3-d48b-4c94-a54b-2ef9ae22241c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 63).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '0a01b19ae3e148a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dfe21f2-6d3b-4798-8f73-28966a7ed509', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 63).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1f5053cfd8865491_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a06a4eed-e0c3-48d3-99bb-b45f6a39edf1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 63).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '093a5056af945210_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cea82529-21b9-49a7-9a51-693f8ade191b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 64).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '89556f90cda506a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af0e2541-45f2-48b6-a0be-bb8d397dd02a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 64).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '5757a952e8737a40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('083c8f54-0610-4456-a62c-8cc4d0727a1f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 64).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'a2ba9cf94fc37c93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66fecc76-1b5b-4481-83ff-6fe7eaeae750', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 64).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '5cb5b5eab0d2321d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2a9d3d2-11c1-47b3-b1b6-88b127b53376', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 64).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'd9dc98e6b3775a87_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69a575e3-0825-4fcf-9c43-b84110f63d5a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 64).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '3515f3796348f752_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa23b72a-61e2-4b0f-845f-35be2e3ef475', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 64).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '41ca9b51089aa2e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3630244-4138-4c01-ae02-af9927a0621b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 64).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '18723c0b861f5cd9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e050ea66-d41b-439a-9e80-a5107a8fe9de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 64).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '44b18003c2c68ccc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('781b163a-0722-40a3-a39f-3a8b60810e17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 64).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '50c34184a096d6a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d808b00-7962-4f15-98ad-50a309d8d731', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 64).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0b093ce22effdc55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc0cdf72-889d-478a-b174-1cb9421be35e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 64).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '7621a8d680c3df55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9f17b50-622b-4baa-9f79-e50af3a7fb7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 64).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '998a8458f3398e36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a06f1e6-8a56-4f80-9db4-4941b13a53e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 64).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1f61042e92e48305_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e190c87-aeb8-4e89-91c4-235c3851c08d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 64).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'bea78df2b8198b48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43d6de27-9f0c-4e86-8085-e05e7412f031', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 64).', '[{"id": "A", "text": "set system name R6", "is_correct": false}, {"id": "B", "text": "set hostname R6", "is_correct": false}, {"id": "C", "text": "set router-name R6", "is_correct": false}, {"id": "D", "text": "set system host-name R6", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0f7dd46fff21867a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75aa4d60-9e65-4ef3-b729-d550e9f15c65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 64).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "set user root password", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '570db709d00e4dae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83dcafbf-f72d-43f6-9712-128e35775b8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 64).', '[{"id": "A", "text": "configure interface et-2/1/2 ip 10.1.4.254/24", "is_correct": false}, {"id": "B", "text": "set interfaces et-2/1/2 unit 0 family inet address 10.1.4.254/24", "is_correct": true}, {"id": "C", "text": "set ip address 10.1.4.254/24 interface et-2/1/2", "is_correct": false}, {"id": "D", "text": "set interface et-2/1/2 ip address 10.1.4.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '762c599e01983e00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90d1a120-bd86-4bae-8c41-30c46dfb9d41', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 64).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6589ac1e2afd54b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e9035c8-1236-4959-85bd-eeec0e054029', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 64).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a80e1746fb440b90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16d50e3b-4bd5-4b2b-9fbb-865c5e862af0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 64).', '[{"id": "A", "text": "monitor interface xe-2/1/1", "is_correct": true}, {"id": "B", "text": "tail interface xe-2/1/1", "is_correct": false}, {"id": "C", "text": "show interface xe-2/1/1 monitor", "is_correct": false}, {"id": "D", "text": "watch interface xe-2/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '612d5ed973654f35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e1f6af7-6608-4cc0-b6e1-7d5632b4f14f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 64).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3dc3075776ca12d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('470aade1-8f21-4f0f-b3b8-43b8b8a4dced', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 64).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'be3c860b592fedaf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('914ca280-c28d-4550-9d47-8027dc53c5c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 64).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'dd62765d4c6432c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('504297bf-2f80-4833-97db-14d72b406718', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 64).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'dc0d638f2c289169_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8767732c-96b7-41eb-a76c-e3468ebdb0d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.222.126.0/24 via next-hop 10.189.237.254 on Junos (variant 64).', '[{"id": "A", "text": "set static route 192.222.126.0/24 gateway 10.189.237.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.222.126.0/24 next-hop 10.189.237.254", "is_correct": true}, {"id": "C", "text": "set ip route 192.114.97.0 255.8.22.0 10.189.237.254", "is_correct": false}, {"id": "D", "text": "set route 192.222.126.0/24 next-hop 10.189.237.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '0533fa307c20d6a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8df26bf-ffda-4168-aca8-6573f184e2f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 64).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '8b37287d1786235a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a166714-6a1c-4bb9-ac9b-fc6010f5c9eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 64).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '8ef4c625a57b7399_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77da921c-2bda-458c-82e1-cb960f2591a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 64).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c3d56f50d8712485_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e611a13e-5313-4dbe-8c62-b53d0c481937', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 64).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0940392085f48008_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f7608a5-78ef-4833-8d2b-4eb30c90215a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 65).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '4d4a839123a725ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3afe402-bf5b-4632-99f0-6a9b9d8bc31a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 65).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'c2074e407e0dd2e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('907183bc-79d4-484b-96c1-20ec970a2047', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 65).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'd9900f777078b4a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0ae6967-c82e-44d3-95ba-741208227108', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 65).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'ded9f73b6ed2b532_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68d02aff-a461-43a9-bea9-36c5d900cc78', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 65).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '19da512d417d0999_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1335a61-9a74-4613-af9b-d479de2741d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 65).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'bf3f3411b1a5546d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4ad3fbc-fb6a-42a4-8468-f594b9790fde', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 65).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e4cce41b4ad75b4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07b1e117-6535-4610-9b55-c184a2231a66', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 65).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1abe2bb3d4f193ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b3e97aa-0659-4d76-99ee-5ffd21f6d5d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 65).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1d813bdf0785596c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65fcfadc-e271-4021-a056-183a9b04f61b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 65).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '005e0e8b008b0bb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88d7218a-736e-4fa9-84e4-8b3fd778f42f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 65).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '846228c166b1793b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e6653f4-3cbb-4a55-94f3-c36da03d3800', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 65).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'd57c6a8debe8be3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('724d0914-147d-4a3d-8bd5-8c4c6bdf63ca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 65).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '20dff6ee824b24fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('247b5741-755d-4d95-a4ce-5037951be30e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 65).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '44b118dc2771e77b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c717edd-7e42-45ce-bd37-e7f512788d67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 65).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b5c750882d0e1472_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5069c76f-9781-4569-8e9a-50e1d8df272f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 65).', '[{"id": "A", "text": "set router-name R4", "is_correct": false}, {"id": "B", "text": "set system host-name R4", "is_correct": true}, {"id": "C", "text": "set hostname R4", "is_correct": false}, {"id": "D", "text": "set system name R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '794d77dd601ffd78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47db3dd1-0965-4e72-83a0-1260e81b7d1f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 65).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b27154d2a7cf66c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9556ff6-ee45-460a-bb75-ccb1b7c9236b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 65).', '[{"id": "A", "text": "set interfaces ge-0/1/3 unit 0 family inet address 10.147.10.1/24", "is_correct": true}, {"id": "B", "text": "configure interface ge-0/1/3 ip 10.147.10.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.147.10.1/24 interface ge-0/1/3", "is_correct": false}, {"id": "D", "text": "set interface ge-0/1/3 ip address 10.147.10.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'ad845d9c4e594a73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40c18676-a857-46f9-8871-bbc72a09a35f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 65).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a6159cdcded0bd92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ce4186a-0aae-48db-8bcb-91e74e173b60', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 65).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3034361d8524a4d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4baa2863-7ee8-4f64-9ec3-60e649f1c0fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 65).', '[{"id": "A", "text": "tail interface et-2/1/2", "is_correct": false}, {"id": "B", "text": "monitor interface et-2/1/2", "is_correct": true}, {"id": "C", "text": "show interface et-2/1/2 monitor", "is_correct": false}, {"id": "D", "text": "watch interface et-2/1/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6d62229373b51ca1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04f36a16-d5c5-4180-b178-93cc4f5cfeb1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 65).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '032bb4625a6fa36f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63c6723f-11e9-4fa1-812c-a448600eb4d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 65).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '52e5e05d684cd4aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a083108-6147-4ae9-b21c-18e779ef997d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 65).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f8874024989b1c47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cec2906-9643-4949-b75c-65a0bee3a8af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 65).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8848107651dd943e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73126c31-fa80-49b2-82a7-5057a8c8a8c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.115.85.0/24 via next-hop 10.163.31.254 on Junos (variant 65).', '[{"id": "A", "text": "set routing-options static route 192.115.85.0/24 next-hop 10.163.31.254", "is_correct": true}, {"id": "B", "text": "set static route 192.115.85.0/24 gateway 10.163.31.254", "is_correct": false}, {"id": "C", "text": "set route 192.115.85.0/24 next-hop 10.163.31.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.75.127.0 255.200.50.0 10.163.31.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '98705cb03f95866c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e368b28-ac5d-4101-96c5-92c2806d6a46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 65).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '4139b19df58002e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6ad861a-9f2d-46ac-a864-6c6e27d8697a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 65).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '7dceb81840cd1ff7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3bb1880-246b-4dfb-8092-e9d9c6ead37a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 65).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd0f08e2d235afc28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8eeb01c0-e12a-41b4-b79b-5423b404c057', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 65).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '96f5f21dab39b918_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7471a3e7-9ca4-49f4-8c22-1612c290ab8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 66).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '5a0beebacd7b8877_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d9ac401-25be-4036-b70c-96b6f052c353', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 66).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'bc69dec75dca9c4a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c272852b-89b0-4eb7-aaed-35bd52c65868', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 66).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'e5b375fdd0f6ea5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a653dc40-f3f4-48fc-81d6-410cee5bbea6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 66).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'd3c97db1483a4121_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b03b86cf-1148-484b-9c60-3f65bd5906e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 66).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '7f2efa8b75daf727_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e3160f3-8afa-449b-bf06-a7525410402f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 66).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '09fbce4f096a9ee5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d094281e-7f3c-41f1-8e44-adb690014f70', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 66).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8849cd60b71c49ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebd3a33e-03dd-4bcc-8b97-df9ec0dd9d15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 66).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '47c90c705295575e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8f64257-de94-49ef-b6cd-7a4444e52143', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 66).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1ac1802114c1b6bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fcded95-32f6-4e0d-beff-7d11efb21313', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 66).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '3806548c8c75953f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f684d4e0-6fee-4954-bedc-c994c6ba28d3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 66).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'cb69c2b766fe6735_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7111e30d-14ee-43c8-91b1-b25c381139e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 66).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '02681c5838be9302_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('352c0a65-4c63-4646-8a90-84721323c4a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 66).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e804af16fa934070_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11cb288c-7eec-4480-a18a-114ff262cf5b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 66).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '67884c2853580c6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f2f402d-f44d-48a5-b736-ce9e66875907', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 66).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '439fbae56cb19252_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c7ea348-964c-46a5-a01d-ec95bfca6ec6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 66).', '[{"id": "A", "text": "set router-name R9", "is_correct": false}, {"id": "B", "text": "set system name R9", "is_correct": false}, {"id": "C", "text": "set hostname R9", "is_correct": false}, {"id": "D", "text": "set system host-name R9", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '06f5a56fac538f0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d4a2920-9d54-4532-b191-77e03a88677b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 66).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'cc095db95c46de94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61bd6bfe-6723-4d53-84fc-e43a8b049505', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 66).', '[{"id": "A", "text": "configure interface ge-0/1/3 ip 10.196.67.254/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-0/1/3 unit 0 family inet address 10.196.67.254/24", "is_correct": true}, {"id": "C", "text": "set interface ge-0/1/3 ip address 10.196.67.254/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.196.67.254/24 interface ge-0/1/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f2535508b324dc60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46927e9e-4408-4ef9-aa5a-34fc231511e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 66).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'cf5caa41177091a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a54dea7e-ac0c-4732-aedb-cd3f8bd94acd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 66).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '352d0682a7179460_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fe26867-b61c-4a83-9682-3a71989b7fca', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 66).', '[{"id": "A", "text": "monitor interface et-3/0/1", "is_correct": true}, {"id": "B", "text": "tail interface et-3/0/1", "is_correct": false}, {"id": "C", "text": "watch interface et-3/0/1", "is_correct": false}, {"id": "D", "text": "show interface et-3/0/1 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '019ea8666da51686_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f13ad89-5259-4333-99f2-95aede3336a4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 66).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1489e75d730b76d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('509b1fe6-9d0a-42a6-b0de-0e6d5eed4201', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 66).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'c89f135dc785b0f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26c10d65-658e-41ac-b20c-ec1d71d38045', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 66).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '774ae10711c07e52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14e87edb-d453-4bb8-98fd-c3d583386aa7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 66).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f77d05d2331590bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f77ba5a-62cc-4325-a89d-0da0174172c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.108.201.0/24 via next-hop 10.118.0.254 on Junos (variant 66).', '[{"id": "A", "text": "set static route 192.108.201.0/24 gateway 10.118.0.254", "is_correct": false}, {"id": "B", "text": "set ip route 192.243.65.0 255.106.182.0 10.118.0.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.108.201.0/24 next-hop 10.118.0.254", "is_correct": true}, {"id": "D", "text": "set route 192.108.201.0/24 next-hop 10.118.0.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd9ca985812732bb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd9dcc4d-6928-4964-8d59-79b9dc761719', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 66).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e846a6964710c016_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e109148c-8202-49a6-9ded-6640cb828351', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 66).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '926a3e07e370e624_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2464417-37b3-4246-bf1d-c8b2677745ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 66).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8d16bd5930878bb5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38310a30-c368-41dc-bd50-0f0d3db1ead6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 66).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'df4c089532a4dfcd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb38d22d-afdc-4b81-a290-b197ffbb5a13', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 67).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '33b7b81ead39f29b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7a49ace-906e-4e99-a6b4-732482f3456d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 67).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '280d21e8f7b61d55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2872704d-65f5-47a8-be21-f9a474421677', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 67).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '92eebc3885fc4416_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5cc59de-3ec6-4670-888f-95952a71af93', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 67).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '2a01b9367ebe8ce7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('510c1497-552d-4419-a7b3-44b180bf629b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 67).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'fc1f7a0555033ded_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('197470ac-8439-481f-aa78-ea33b63fdd3a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 67).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'd8b2a04f5fb3291d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('241681cf-ae08-4930-9c98-ee3361a2d577', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 67).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '22164e412d9cc040_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d3f3f24-75ad-4110-88a1-1dc037e3a12c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 67).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '97aa9458c2245686_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6c37832-9bdf-4ec2-9a96-845bc70ef376', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 67).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '65f68073835c77fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('634808f2-0304-400b-a78c-b350bcd0e65e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 67).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '08e8ac67259443d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a74ba285-e6de-4c26-8f16-56c315279e81', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 67).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '717e3868f0f52f2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7990e0ab-228a-434c-a4e0-2a13b4f1f12c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 67).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3f193d049ed82a43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53240aad-1048-4e80-b225-e3c509f7e952', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 67).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e30ecfc20b6ceeb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cd20e06-0890-4e5f-abce-1a3843cff549', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 67).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e33d9acee59d005f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1da73dc4-2c7d-494a-ac34-88aed4652e6c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 67).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '64facc3b50caac0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f48ae542-20d2-4e2f-8717-670ced7ae5c9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 67).', '[{"id": "A", "text": "set router-name R5", "is_correct": false}, {"id": "B", "text": "set hostname R5", "is_correct": false}, {"id": "C", "text": "set system name R5", "is_correct": false}, {"id": "D", "text": "set system host-name R5", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b21b7a9ac78278e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('533e953e-a42c-4864-852c-1deee5ea3de3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 67).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'fb4f2f9a6ff2e8a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b622152-f71e-4668-bb2d-63421954934f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 67).', '[{"id": "A", "text": "set interfaces ge-3/1/2 unit 0 family inet address 10.82.128.5/24", "is_correct": true}, {"id": "B", "text": "set ip address 10.82.128.5/24 interface ge-3/1/2", "is_correct": false}, {"id": "C", "text": "set interface ge-3/1/2 ip address 10.82.128.5/24", "is_correct": false}, {"id": "D", "text": "configure interface ge-3/1/2 ip 10.82.128.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '07dd9d4c1e6fe1a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f43d8e10-1796-457e-88ed-c4bc85d13c94', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 67).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd122feca18600e60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be6e3f98-b4f2-46cc-b682-d78d09ac2f85', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 67).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '80311b1407aa9623_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db68e57f-bcd2-4607-bfae-0c935f3fea5b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 67).', '[{"id": "A", "text": "tail interface et-3/0/0", "is_correct": false}, {"id": "B", "text": "show interface et-3/0/0 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface et-3/0/0", "is_correct": true}, {"id": "D", "text": "watch interface et-3/0/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '025235f90d9d00cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33379234-0b99-4c6e-b022-5e1ee110e99f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 67).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a30f01da2f94ca4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c32582e1-de8a-4633-afa2-0baebefe8405', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 67).', '[{"id": "A", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '773c5e42394de64b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a27a5e34-d772-466c-a6d6-004317907c9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 67).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '4446310265ef06f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('073d9557-8123-4de4-9ff1-263fe2903f4f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 67).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c4bb9d4031397cc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac07978c-4b75-4b84-91eb-d36f396cadbc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.9.113.0/24 via next-hop 10.247.148.1 on Junos (variant 67).', '[{"id": "A", "text": "set static route 192.9.113.0/24 gateway 10.247.148.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.30.89.0 255.77.97.0 10.247.148.1", "is_correct": false}, {"id": "C", "text": "set route 192.9.113.0/24 next-hop 10.247.148.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.9.113.0/24 next-hop 10.247.148.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd4090befc5f19bee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a326498a-8149-4790-abbd-d398e73a0146', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 67).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7dfc0ea94b6dac04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35738217-5045-4d1a-a486-9d0c60b5fb74', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 67).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'e5bc6ada8ea3d73a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ce69d6d-ca35-4abb-8602-72717cd7d53a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 67).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'abbfae55d0ae8de8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10dd15af-9e60-4b78-b2c3-5438d1e3d665', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 67).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c1bf905210dde3fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cea89687-c3d6-46b7-b3b9-10251807fb6c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 68).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'befea1d5729958dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fc7b349-d5fc-4f6d-9320-00b200c241c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 68).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '776492ffbec2ba43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d05f0210-14ce-4f18-beb5-cbcf311df31a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 68).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '17e7112353b7038a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb1f8136-8330-456b-8c88-11501e9ef086', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 68).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'e3e9fdece97c5694_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('189383ae-6ca1-453f-8e69-5444a4e5f069', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 68).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '695efef478c9eafb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1755323-bb32-4d32-b629-be6233c6f7a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 68).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '255bb78727456e78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21f543dd-5438-47a1-b137-44efedb19540', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 68).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '43ab86bd9fdeaee9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2d87564-0d2f-477f-a6d7-fa7bd978a217', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 68).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4f13c0e2aeba3d76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0611346-e134-4d33-b63f-75381f265dd6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 68).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '817e5ed0db213649_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a80c51d-4de3-463a-b844-81a32a8c4647', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 68).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'c8a94a83754e4612_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('084e9405-d4af-48e6-a4a8-e159b86e6ca8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 68).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd6c333d5ac4127f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a9f5e38-95f1-42d1-83cf-5a2c47a58bcb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 68).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '4f1c82fa27bf2500_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edf0a5dd-3c31-4cfa-97bf-93fe130b40b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 68).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd5c8367f2abdbd02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19500bcd-e753-43bf-9e95-0934e8290120', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 68).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '32ad64792553617b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7501558-67b5-4eeb-9835-cff314d6c82e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 68).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '81bf3265e5f1da0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e520d0e2-2a3f-482b-88c8-70eee24fd312', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 68).', '[{"id": "A", "text": "set system host-name R8", "is_correct": true}, {"id": "B", "text": "set router-name R8", "is_correct": false}, {"id": "C", "text": "set system name R8", "is_correct": false}, {"id": "D", "text": "set hostname R8", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4f7bc0e3840e066b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4653bc87-5db7-4351-a601-45a9308f9a2f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 68).', '[{"id": "A", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '1109b7b826321698_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2e1e2dc-a567-4b58-ab8f-21ef361014c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 68).', '[{"id": "A", "text": "set ip address 10.59.196.254/24 interface et-0/1/3", "is_correct": false}, {"id": "B", "text": "set interface et-0/1/3 ip address 10.59.196.254/24", "is_correct": false}, {"id": "C", "text": "configure interface et-0/1/3 ip 10.59.196.254/24", "is_correct": false}, {"id": "D", "text": "set interfaces et-0/1/3 unit 0 family inet address 10.59.196.254/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '6146cb4f7658e97b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3218f778-2741-491d-a411-1d2c84b548d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 68).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '895985d876a86036_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bd7ca4d-bb51-4704-b40b-a1430872754b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 68).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6d0b46c6279aeb4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5bc4d41-6cee-4bd0-8220-579f0d6b6101', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 68).', '[{"id": "A", "text": "show interface ge-0/1/0 monitor", "is_correct": false}, {"id": "B", "text": "monitor interface ge-0/1/0", "is_correct": true}, {"id": "C", "text": "tail interface ge-0/1/0", "is_correct": false}, {"id": "D", "text": "watch interface ge-0/1/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6019846db5963f8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1ba3748-7583-4094-903f-4fdbda316a2f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 68).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'bd315de2bd3daee5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46b018fd-2f75-43e7-84ae-72ce7c471108', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 68).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '59ece1724764f103_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b64a8d9e-67db-4bd1-8b78-c310a1256e12', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 68).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '8f602b31b3fb666e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05bd480a-7429-4be2-87f4-ec700a5bf201', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 68).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '30ab1661e2f83d05_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('739fefd8-0652-4571-8a26-7b0b99050f1f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.29.63.0/24 via next-hop 10.78.32.254 on Junos (variant 68).', '[{"id": "A", "text": "set ip route 192.94.91.0 255.238.135.0 10.78.32.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.29.63.0/24 next-hop 10.78.32.254", "is_correct": true}, {"id": "C", "text": "set route 192.29.63.0/24 next-hop 10.78.32.254", "is_correct": false}, {"id": "D", "text": "set static route 192.29.63.0/24 gateway 10.78.32.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'cb86d7e31c2d1dad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17ce84f0-4ced-4db3-ae8b-7f29a91fe6f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 68).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5592bbccd6d620c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2564c818-7987-461e-9290-238daf2f2d55', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 68).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'da2ed11484a5671c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fba6649-1ba9-459a-b3fc-dc896254968d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 68).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'febe5969ac128f08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eeedca10-3910-4ef7-b68b-123c9e897676', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 68).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '738d850e091d49b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b11b473-306a-4457-a424-cfee9d725d0d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 69).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'a78dd507ea3c1302_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3ef11a3-5f20-4720-86ec-dab47f6e21e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 69).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '0bfa6c17a18e19be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('245f15ad-80b4-4557-ae4e-bfc4892623f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 69).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '5c3ee130c5a5f269_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('397e8f04-a0b9-4480-9dd5-b1281f6e0576', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 69).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'e553c04700f1d316_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0c772a4-f018-4004-ae12-82bd58c85127', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 69).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'c2fd18066be96bff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71c820fb-8ee1-48c4-99aa-6216e866ddd8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 69).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '745f790ed3f88518_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2608b9b0-1b30-4f3f-a58e-f4fc93f8f725', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 69).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '34b577283ba33dc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a65c7a88-35c5-45a2-8506-33272f3812d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 69).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0626a2ad89617353_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c728130f-bbd7-42d6-bb5c-4dae612338db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 69).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1731950f8f4393e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01af4426-b3e3-4dab-a1b4-1416bcfe0092', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 69).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '0d7725e72eb7aea4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f210d93-f279-4a51-85ce-19301ffc6898', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 69).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4c037a168f9e3293_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed095f2a-2c46-4640-ad1e-e7b66b93b8e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 69).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '26286e5dac29e5aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1280cedf-f8ee-4bca-af92-62b4e1ffe01b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 69).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b1cc8732dc4543a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1ee7095-5639-4fa6-ba3c-073913680283', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 69).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '82f509daa29becad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('154d899d-f729-4492-82ef-80de9fde03b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 69).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2b56ab6c7e1f4269_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61bf094a-a0b2-45c8-b14a-1de025c31bf8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 69).', '[{"id": "A", "text": "set system host-name R6", "is_correct": true}, {"id": "B", "text": "set system name R6", "is_correct": false}, {"id": "C", "text": "set hostname R6", "is_correct": false}, {"id": "D", "text": "set router-name R6", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '1443fb99cd372030_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43a20ea7-096c-4268-a97a-10cea16728d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 69).', '[{"id": "A", "text": "set authentication user monitor password", "is_correct": false}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'c6e923ef3dceee71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4e94693-4f31-4d72-b0a8-3609c7cd7deb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 69).', '[{"id": "A", "text": "set interface et-1/1/0 ip address 10.141.134.254/24", "is_correct": false}, {"id": "B", "text": "configure interface et-1/1/0 ip 10.141.134.254/24", "is_correct": false}, {"id": "C", "text": "set interfaces et-1/1/0 unit 0 family inet address 10.141.134.254/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.141.134.254/24 interface et-1/1/0", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '53d3441f404c61a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0909634-db14-4919-942f-50cfbba3163f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 69).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'db7854dd43d11f3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8dcdba3-cae5-4c75-984a-24fc04d49aee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 69).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '097812630906fcaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59a94fde-ef83-40b5-b80e-f91c1c89ed0a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 69).', '[{"id": "A", "text": "monitor interface et-1/1/3", "is_correct": true}, {"id": "B", "text": "watch interface et-1/1/3", "is_correct": false}, {"id": "C", "text": "show interface et-1/1/3 monitor", "is_correct": false}, {"id": "D", "text": "tail interface et-1/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1d347f9408f9cabe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81704ff1-a3d2-4550-b1cc-0f623fbb12f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 69).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '6965a1c0e68ffce7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86d0df3c-9a3f-4771-b2a5-bbba7f99de9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 69).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8d3a2cd3446cd3bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13a26fef-31c8-4f1c-87ce-2431d64571cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 69).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '6aa31914b132dfe0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94fba69a-2c3d-4804-b508-978d4b1c3ee7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 69).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'fb0623d85f623449_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e60a5634-b487-4a4c-b8e4-2af511fb9ca5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.205.230.0/24 via next-hop 10.26.13.254 on Junos (variant 69).', '[{"id": "A", "text": "set ip route 192.113.97.0 255.235.188.0 10.26.13.254", "is_correct": false}, {"id": "B", "text": "set static route 192.205.230.0/24 gateway 10.26.13.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.205.230.0/24 next-hop 10.26.13.254", "is_correct": true}, {"id": "D", "text": "set route 192.205.230.0/24 next-hop 10.26.13.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ccde1f3061474ac6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f86d2f9f-2fb3-4549-ae97-4943f924942a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 69).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7a22719e0aa42e8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c9495df-c9de-4184-a6ba-60130deb0597', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 69).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '2e9cbab54ad9f05f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('639ef102-4979-4389-9a4f-acc14494dba1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 69).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0199ff293f0d7d8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdaae773-dbe0-4c42-b1a6-f8ea8df94525', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 69).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'f0f37bc5bb61b3e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9da07f4a-4c9f-405e-82f4-6e6659d00a4b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 70).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'c3d228b855a71cbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca2e6878-6148-4559-812e-05a528b6632f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 70).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'f94b86833811b1c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9817a87-fcf7-4bc5-8cb9-2ae114c1a348', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 70).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'd3eaf92e1bcd29d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b92d9a38-252b-46fc-ad43-bd1cbe39c4da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 70).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '832be3170907f85e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c560c3fb-094f-473f-9d10-004911c61625', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 70).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '0eabda2778872a04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('320fd95a-90cb-45c3-985a-8a6b54d81bf5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 70).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '3dd68fbeae985b39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fee8698-6f30-4ea5-ac58-cdc8cfd614ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 70).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c30b26dbf82e1339_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57c0e163-ac5d-48dc-af19-ab20695c6b05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 70).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'baa6a38df09d30e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6324f706-d61a-4620-ab89-160285597587', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 70).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0c2633109d1b8eca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('464389e0-b9dd-4815-a87b-48c8b725ca5f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 70).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'f7171a52f59918ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a1ab584-11ac-49a2-8c02-b7e1ceef17b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 70).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '5705d2e73bf15171_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04696457-1d8c-4a3a-8152-4dcd8560206e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 70).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'b3142a57be6ca287_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cc93754-add9-4848-a0fc-2320d28834b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 70).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '86e493b08a9adf69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8ee46b1-d69d-4c5b-9cb6-e8cff56dc2bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 70).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ef0efeb0c3b2871f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('492bbcc1-5e8f-4418-b716-1c9fca770d32', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 70).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e605ac9f0d94349a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2e66805-564f-44f4-bdde-dfe5017a5374', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 70).', '[{"id": "A", "text": "set hostname R9", "is_correct": false}, {"id": "B", "text": "set system name R9", "is_correct": false}, {"id": "C", "text": "set router-name R9", "is_correct": false}, {"id": "D", "text": "set system host-name R9", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ad21d200bca8dc32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da897094-d34c-449d-83cc-b0c86479c8e7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 70).', '[{"id": "A", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "set user root password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7114658566d7f8d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7505a1b2-e4c9-443a-b1b6-21052cf2c0f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 70).', '[{"id": "A", "text": "set ip address 10.232.190.1/24 interface xe-3/1/2", "is_correct": false}, {"id": "B", "text": "set interface xe-3/1/2 ip address 10.232.190.1/24", "is_correct": false}, {"id": "C", "text": "configure interface xe-3/1/2 ip 10.232.190.1/24", "is_correct": false}, {"id": "D", "text": "set interfaces xe-3/1/2 unit 0 family inet address 10.232.190.1/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '858e86ef12decc19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c655bc7b-3225-40d8-bbdb-102bb940103a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 70).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '8070e0497b9689c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1c2ab54-2c1f-44b6-be95-393bfba6afce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 70).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8e1fa2a9b40f1fd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79da5e60-36a5-40d9-8eca-63c788dd370e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 70).', '[{"id": "A", "text": "watch interface xe-3/0/2", "is_correct": false}, {"id": "B", "text": "tail interface xe-3/0/2", "is_correct": false}, {"id": "C", "text": "monitor interface xe-3/0/2", "is_correct": true}, {"id": "D", "text": "show interface xe-3/0/2 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '33aff8140028b315_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f494559-2657-4ebb-b618-3cb96e4e2157', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 70).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '9e1b96a19c76424e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('808e991a-050a-48de-a56f-206046af88a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 70).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '443e6321db7c9598_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb013443-99af-4280-a9b1-39d73a062ff8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 70).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '2c3c2159a593c044_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6830253-72f7-444b-8f56-876c2791ac89', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 70).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'cb677063ca3c62db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73125ec8-d59c-47ea-bc63-71b5619aa20c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.178.10.0/24 via next-hop 10.164.255.254 on Junos (variant 70).', '[{"id": "A", "text": "set routing-options static route 192.178.10.0/24 next-hop 10.164.255.254", "is_correct": true}, {"id": "B", "text": "set route 192.178.10.0/24 next-hop 10.164.255.254", "is_correct": false}, {"id": "C", "text": "set static route 192.178.10.0/24 gateway 10.164.255.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.134.102.0 255.43.192.0 10.164.255.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f9ddc011694d9e54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22476e4f-e464-4ebb-976a-525950aefc75', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 70).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd05eef3d350d6b52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb2fca2a-4ad1-4e40-9b92-e13af933c931', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 70).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'da9b58938981b23d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a84e9ddb-48b4-42ce-83e9-76006be15f6d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 70).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4946208fa423255f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cb81342-9974-45c6-9abd-2d3aef87feb7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 70).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '69ae872c9d1c9f9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa793e77-a263-4abf-9a4c-634d4827a47b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 71).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'ee0aa6a3e9220005_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50b93560-5ede-4494-84ec-96239ae734f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 71).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '4e67a35ee796db60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('102d00f5-11d0-48d4-ae3c-8cea27abff69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 71).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '6b2ac6415336a788_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31d43277-29bc-4bd6-b186-20a897ddb4ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 71).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'ad8e494f5d3f92bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18616a80-a580-4f1f-833b-4171316f2b7d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 71).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '93b29a3df48c86c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb3d140f-1a5a-4041-8935-07751e8047a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 71).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '6723a28106e91089_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('167bf348-4624-4e55-8054-f8a923e5b396', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 71).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7907dcacbe72029d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b99e79c-4198-491b-adeb-b0661374bf12', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 71).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd41dd3f29db0d920_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dd5276b-289e-4a25-94b0-0e3dacac915b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 71).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '706f6c993adaca0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52c8023d-e525-4a74-8d37-69d0c3640057', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 71).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'd1c28e1126848c45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a022dfd8-9601-43ad-9fa9-694aebe7d6c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 71).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '57ac5f26a8bb50b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a96fb9ad-8ff4-40e4-87d8-f0bb7b9d03b7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 71).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'cbed78ff6db6bd67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('499532b8-ece3-4c5a-8c23-f31179587518', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 71).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b8d722142b0479ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f235c9e1-bb5c-4cb6-95d7-088d1653fb61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 71).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '94cb74fe305f15a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a368ec40-5519-49f3-b6fa-a8abe5008a49', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 71).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8050cac36638b0a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db48cc71-454b-40c5-a808-691d25844d57', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 71).', '[{"id": "A", "text": "set system host-name R4", "is_correct": true}, {"id": "B", "text": "set system name R4", "is_correct": false}, {"id": "C", "text": "set hostname R4", "is_correct": false}, {"id": "D", "text": "set router-name R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3a32d03df4a26b39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23cf043b-8077-4b00-8ad9-ab6d1702bd2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 71).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'aaf6a2f28fa7a32f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da0787b7-b946-45e5-a106-936b3b683375', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 71).', '[{"id": "A", "text": "set interface ge-2/1/1 ip address 10.211.110.1/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/1 unit 0 family inet address 10.211.110.1/24", "is_correct": true}, {"id": "C", "text": "set ip address 10.211.110.1/24 interface ge-2/1/1", "is_correct": false}, {"id": "D", "text": "configure interface ge-2/1/1 ip 10.211.110.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '8947a93faad08323_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('658f6947-f75f-4cda-b0c3-adb4dfdfd59d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 71).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4b4f859319b0ebef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a24720c5-68b6-4d02-b4a0-757b095e7453', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 71).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7354005931979016_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1300f97-76be-4198-af59-87cd92a32f17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 71).', '[{"id": "A", "text": "monitor interface et-3/0/0", "is_correct": true}, {"id": "B", "text": "tail interface et-3/0/0", "is_correct": false}, {"id": "C", "text": "show interface et-3/0/0 monitor", "is_correct": false}, {"id": "D", "text": "watch interface et-3/0/0", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'cc42c777e4812d92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49874c9c-44eb-4f3c-af0e-d78f06a15f80', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 71).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "SCP to /var/home, run install junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '0dfcfd9ad3725a94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1d583f8-777a-4f5f-b2a3-9223c670e32d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 71).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2601ac9858d414e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d3da508-c8d4-4417-82dd-0dfbc00ef11f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 71).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '77b94cd3ae237910_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dd779be-0dfc-4152-b1c9-2c769184bb44', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 71).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'dfc6c388a397cd52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d83dc3d-3e0a-46f9-ae44-e2adc5a08d72', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.144.119.0/24 via next-hop 10.178.174.1 on Junos (variant 71).', '[{"id": "A", "text": "set ip route 192.29.155.0 255.128.41.0 10.178.174.1", "is_correct": false}, {"id": "B", "text": "set static route 192.144.119.0/24 gateway 10.178.174.1", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.144.119.0/24 next-hop 10.178.174.1", "is_correct": true}, {"id": "D", "text": "set route 192.144.119.0/24 next-hop 10.178.174.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'fcb4880bce1084cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4726039-bbf5-43ed-ab50-d6bfaf21d4dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 71).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '55518294f40fa9f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5bdccd6-8627-4611-af23-6b7b5aebe9ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 71).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'e872ede4983892b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be256c83-238e-485e-9b7d-443356b5cd96', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 71).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd56efa594f77d951_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21044acc-b76c-4fe2-8507-c50274078806', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 71).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '95b2740f5f67687a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7044d9ca-e4e6-42c1-9aa1-334538d95f1f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 72).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd22ef605b6993db4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95950f99-20d3-494d-82a5-f72d09150a2f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 72).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '6c88598746d3af8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e520aaf2-ddcb-429b-b592-9c5917a336ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 72).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '9363bec32ab5d089_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8490ea51-195c-49e5-92fa-2bd788d8dc80', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 72).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'a4ef6be8591da260_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b642b7cf-4860-410b-97e6-5ae3a8f5573e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 72).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'e4f3dffb122bb738_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e643b2e0-e57b-4acf-afe8-159eead76192', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 72).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '6051d1db28428e00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdb45b31-531d-4990-aed7-90295cea24f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 72).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd2d0b4c60341a72c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e103768-5a4c-4c99-b52d-5ac7a15c79bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 72).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9336b822a242c88b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81d97018-86bd-43d7-a4ad-4b3e50d4be04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 72).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b64f897072ca8403_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a591cf5b-7a26-41b9-bd55-5627698451ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 72).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'be2b7d5fcab32a66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbf34d07-9398-4b18-bc78-e3efec63676c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 72).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'c0fd480a30bdc4c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8eb98314-1d78-4063-b822-0a3fdca87615', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 72).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8357264e9844df09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8ebb8c3-34bb-4dfa-8e08-5625def8387e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 72).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '438c701f0ca22dba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92e4606e-ce61-4d9a-b4f2-557cbb4ef8d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 72).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '4d5fb56d07a70394_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('252a24a8-5cb8-45cf-81dd-adee29ec37b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 72).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ddf8a16e6125279b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddaee117-d1e6-492c-9e47-08eb513108cd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 72).', '[{"id": "A", "text": "set system name R12", "is_correct": false}, {"id": "B", "text": "set system host-name R12", "is_correct": true}, {"id": "C", "text": "set hostname R12", "is_correct": false}, {"id": "D", "text": "set router-name R12", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4a1bc4870e819afb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8063e5d-2568-4e19-819b-00fbc25053f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 72).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5ac2e0b49802be76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94ea5027-a18b-4d82-a427-ed9f62510ba9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 72).', '[{"id": "A", "text": "set interfaces ge-3/0/3 unit 0 family inet address 10.34.1.1/24", "is_correct": true}, {"id": "B", "text": "configure interface ge-3/0/3 ip 10.34.1.1/24", "is_correct": false}, {"id": "C", "text": "set interface ge-3/0/3 ip address 10.34.1.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.34.1.1/24 interface ge-3/0/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '6b6b212380bd288c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44dcf3b1-bf1d-4bdd-a32d-3d665fec9e9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 72).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5fceb7001775249b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7622a48f-fea2-4ff7-a72d-93d4093cda84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 72).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '544f568405bcac75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee712598-ab63-4d7c-8213-ecad6c5f1e6b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 72).', '[{"id": "A", "text": "tail interface ge-2/1/3", "is_correct": false}, {"id": "B", "text": "watch interface ge-2/1/3", "is_correct": false}, {"id": "C", "text": "monitor interface ge-2/1/3", "is_correct": true}, {"id": "D", "text": "show interface ge-2/1/3 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5646fbded259e68e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b57ace39-c663-4b80-94f2-d82ed846876e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 72).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1a0371599eaba6c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a099dbc2-c058-492b-9474-f126dcc19fde', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 72).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8a17c2e2ff1b3cf3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34615dc0-5a66-4b8b-b2e1-6c5494862fc4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 72).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '31c7d7e6691336e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f65c8082-2cca-419e-a061-395470803ec5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 72).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '668e9ab85c397f8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac9f3a16-af24-4077-800d-396428f65d9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.87.86.0/24 via next-hop 10.19.249.254 on Junos (variant 72).', '[{"id": "A", "text": "set route 192.87.86.0/24 next-hop 10.19.249.254", "is_correct": false}, {"id": "B", "text": "set static route 192.87.86.0/24 gateway 10.19.249.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.87.86.0/24 next-hop 10.19.249.254", "is_correct": true}, {"id": "D", "text": "set ip route 192.126.134.0 255.175.32.0 10.19.249.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '46fc3c41a4845680_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('046de336-f952-4cc6-ad36-3aeeef1bfc32', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 72).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '213440e434f27871_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2f65894-81dc-438e-8632-d8dae4589c18', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 72).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b7934f90ace2f756_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84abe7a5-819e-44e3-b8dc-689857571be1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 72).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2dffc0a886aec9f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f85351ab-6fbe-419b-a5fa-593b64b6776b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 72).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '01c644cde2d11bc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('610b03e7-942f-4f72-93ed-46424cac1634', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 73).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '150820182acdaa0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22fdc92e-1196-4a5b-bd96-55ac08a62a77', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 73).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '9e6d97fc4487043a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7726ec4-18c7-41ef-b1dd-e4c72762683d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 73).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '22ad8ceae0375ccc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a64450a-c25e-4dd1-8072-d20f244a1cf9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 73).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'e9f05a8c2e9dd27d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d746c314-7b68-423d-853e-55294a154c1d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 73).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'c2e92490078c3d76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c9f3860-1e46-42c8-bee7-fae328fd028d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 73).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '1946db3d76c98682_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6befa057-282b-4903-8202-d70abc3cb1c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 73).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f297fde042894508_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79b60cb8-43dd-4f42-a045-83821f4bb8bd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 73).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '50139121ffb66149_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('508c95e0-7966-49a4-a20d-6823ac9a6b8f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 73).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '21bdbb6dc639c5c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55235057-241a-485b-b424-53976b0c1d26', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 73).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'dda02d8d4d3107fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f30a16f-99fd-46c6-87e2-7c70726d56ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 73).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '29cd71fe054e826d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15ff2c2c-5c5f-44d6-aaab-0edcf095f36d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 73).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f25a852cceca5fbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('921ba070-a7a0-4256-af99-e1d30a2659c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 73).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a038957018acdf47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d3c04ef-b274-4e79-84ce-d01cdbf1433a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 73).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '19b1bfb5826c8f49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b7a73e4-289c-4278-8c2d-b306e18e4628', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 73).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7d5f80f6cd33a27a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c5fca40-fff4-455d-8ca7-d216017014d7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 73).', '[{"id": "A", "text": "set system host-name R12", "is_correct": true}, {"id": "B", "text": "set system name R12", "is_correct": false}, {"id": "C", "text": "set hostname R12", "is_correct": false}, {"id": "D", "text": "set router-name R12", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '0d7de04e9e7b4dfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a68e016d-54a2-4b7a-8528-53de437b07f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 73).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5b8b2bc5cb550101_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b285a5f8-f13a-4443-9751-5db1f7e9cbf9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 73).', '[{"id": "A", "text": "set ip address 10.58.171.5/24 interface xe-0/1/2", "is_correct": false}, {"id": "B", "text": "set interfaces xe-0/1/2 unit 0 family inet address 10.58.171.5/24", "is_correct": true}, {"id": "C", "text": "configure interface xe-0/1/2 ip 10.58.171.5/24", "is_correct": false}, {"id": "D", "text": "set interface xe-0/1/2 ip address 10.58.171.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'fc012fc245680401_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f282f82-f9fc-4241-bb49-3d7781f7937d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 73).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd05c5f6bd1d5d6a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f001a458-2f23-49b3-bd98-bfa2699cc47f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 73).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8bc511aeae962b86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92f30533-2c7f-4d88-a43a-338b305de73a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 73).', '[{"id": "A", "text": "watch interface ge-1/1/3", "is_correct": false}, {"id": "B", "text": "show interface ge-1/1/3 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface ge-1/1/3", "is_correct": true}, {"id": "D", "text": "tail interface ge-1/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '94eda543f4315bb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7810aa1-6054-4f5b-94fe-feae7cc6ce72', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 73).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2c6cd088fd688391_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5f38af3-68ff-497b-9222-b10261eb0e91', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 73).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'fd6c8e0689ed5feb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a03a027-c7a3-4129-9f09-c0efeacc74b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 73).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'ebd6b0611977e39c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a6d648d-9d0c-43f4-900e-be871df5250d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 73).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c54348e79783670b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab2681b0-ed7b-4051-a6bb-650c69d29b9a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.182.36.0/24 via next-hop 10.140.140.254 on Junos (variant 73).', '[{"id": "A", "text": "set route 192.182.36.0/24 next-hop 10.140.140.254", "is_correct": false}, {"id": "B", "text": "set ip route 192.241.236.0 255.71.125.0 10.140.140.254", "is_correct": false}, {"id": "C", "text": "set static route 192.182.36.0/24 gateway 10.140.140.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.182.36.0/24 next-hop 10.140.140.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '34b517e72d43e1af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9283ce71-9d4c-464f-a8e1-7affc415ccdb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 73).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '762bb5926a7febe5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2250a255-df80-4cef-9a45-22c5b65646c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 73).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'aa54e86697341abe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2b79747-438a-4631-ab2f-2f494dc22d4f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 73).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7e5c65101daa9ff9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b526556-8242-4d94-ae27-e314be9c86af', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 73).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd326110b62760358_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f36cc29-e62e-409a-9687-10c9edabeba4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 74).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'a5e36cab8a384c2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c42482d6-8b08-4f1b-85ef-938a477c0d99', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 74).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '46db8fdfa59a38cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e7b5ae4-0cf6-4e14-b907-15326deefb68', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 74).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'f1bc7b4b2d4c20b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87014d6d-dabc-44e6-a45d-48d886e9565f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 74).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '54b4368098bf8e3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d0f6c97-c591-4a89-9635-c2112f88087b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 74).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '3bc8116b8f1872b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15c5b5b3-e1aa-46bd-893d-8f0296f81b75', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 74).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '169dc468759823fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3374c92b-961f-4052-92ca-216884e74c51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 74).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f50390c0e0b71250_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88d8941f-4ea2-401b-adc2-9de557ea2a23', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 74).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '02fa7450feedac3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09bc7482-82fc-4f57-821a-e8744ea694be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 74).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '73057f306071bb2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27441650-93d5-4221-be56-9f4e71b5c57e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 74).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'c0991c5302714023_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d84f7cc-2fb6-4a15-a25c-9d3d164ec6e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 74).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '269f8ebfe18f535c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('716e3f48-40af-44f1-bbbb-44b65bc84a9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 74).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '5efec52384ba0675_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6ffd159-8abb-49c7-86ab-e0e92c39963f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 74).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'fb8f42814522313f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d458cb57-07b0-4fc0-b885-0eb0345c8025', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 74).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f7f9842c62129961_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('330275ba-c8f4-4ab5-926a-4155c36f41cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 74).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'be820de66158a0a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12e4faa5-5fbe-42c0-b387-7599296f526b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 74).', '[{"id": "A", "text": "set router-name R5", "is_correct": false}, {"id": "B", "text": "set system host-name R5", "is_correct": true}, {"id": "C", "text": "set system name R5", "is_correct": false}, {"id": "D", "text": "set hostname R5", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '75e2778e451deeee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('246792c4-d0d7-4a83-a389-2d8a1c25b7db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 74).', '[{"id": "A", "text": "set authentication user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ed6790a52ceef180_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fcfdf21-29c3-4e91-a67e-8ec66d4707b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 74).', '[{"id": "A", "text": "configure interface ge-2/0/1 ip 10.245.251.5/24", "is_correct": false}, {"id": "B", "text": "set interface ge-2/0/1 ip address 10.245.251.5/24", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/0/1 unit 0 family inet address 10.245.251.5/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.245.251.5/24 interface ge-2/0/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '672524c830bb7077_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e611c52f-60ca-4d0b-a641-6f37320ff1ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 74).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '80383348816fc08c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42b8c5db-73a6-4b56-ad08-0f9012e3f17d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 74).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'd1474673a2801c9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('143f6808-f558-4087-bb1e-270e864e2c69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 74).', '[{"id": "A", "text": "show interface ge-2/0/3 monitor", "is_correct": false}, {"id": "B", "text": "tail interface ge-2/0/3", "is_correct": false}, {"id": "C", "text": "watch interface ge-2/0/3", "is_correct": false}, {"id": "D", "text": "monitor interface ge-2/0/3", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6270c5e0e1520142_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2353f1ef-e01e-443d-b641-ba1d9c793e36', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 74).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '1a3ab4973e9b10fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fe0dcec-cb4d-43c6-8f53-65563083dc8a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 74).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '731e7b65483bbf0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43f5184b-9c39-4174-816b-953f1ef3b006', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 74).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'e7b3cb6e6cc6e37c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b862dcac-b8cf-4c4b-8252-5b43c37c82dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 74).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '5acc11e168b067e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b5aad15-dfd3-42d3-aa9c-efb7ab97d8d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.190.255.0/24 via next-hop 10.89.104.1 on Junos (variant 74).', '[{"id": "A", "text": "set route 192.190.255.0/24 next-hop 10.89.104.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.190.255.0/24 next-hop 10.89.104.1", "is_correct": true}, {"id": "C", "text": "set ip route 192.234.158.0 255.145.22.0 10.89.104.1", "is_correct": false}, {"id": "D", "text": "set static route 192.190.255.0/24 gateway 10.89.104.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f3d497157dccdbc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e14230e-9de4-4591-8b0b-e3d502011d17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 74).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'ee566d6d3cb474d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6fa20b4-63cf-417a-8b78-71f5cbb81fe3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 74).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'b26c868117948bbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4631261a-b930-4017-a8a3-501a4229c8ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 74).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '991130987e3b28b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d724e60-f8a1-4e25-b9e3-c57c0ad3b057', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 74).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '882a49dab38667af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('784bf7db-6db2-41f9-a89e-f8a4f725c389', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 75).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'f80f9888ee55f953_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6ef74db-b087-4887-a521-3fe2a306aef3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 75).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'c67f81285985779c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2922af87-5bc7-4e5f-ab1a-7947d0fc2d66', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 75).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '23c404961d889fee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de800122-b12e-4f10-b4df-cc77a4151250', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 75).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4aa8a0de1a099626_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80d41342-5be9-4488-8ee6-cee096bb43a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 75).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '12d2d7116b0d66b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b367fd1-f4da-466c-b46b-728c4cf42e7a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 75).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '88b67cc25e586519_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6b61fb3-8263-4d7c-835f-d635545757ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 75).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e92f2c741843af00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09e4cecc-d586-4344-acc3-9a6dfb79ccb2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 75).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '833c268a6bbd66ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('947e41e9-1f70-4d39-bfa8-1253fbfee3b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 75).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ad998879e3b235ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d966b77a-5648-4c7f-a0dd-88af4ab645b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 75).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'b59011895b118e7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5201e683-6b31-41ea-9005-577fb5581f76', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 75).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '9195019341769ae3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c33b0b5a-a9ff-409e-bcdf-dc41a146def9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 75).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f21a17d7f12fa6e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0217e6f1-647d-4de8-8290-2125cb6bbcaa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 75).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '99f99a4bd0f97359_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ad30c1b-18d4-41d7-829d-1d54d717d263', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 75).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '548e4bf05692cfd7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0589dd0-c1bc-4b35-89f0-05e3dea5ed5c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 75).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '242ff96b2a5dcb4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('694e1aa0-6444-4455-a83c-14232dccad67', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 75).', '[{"id": "A", "text": "set system host-name R12", "is_correct": true}, {"id": "B", "text": "set hostname R12", "is_correct": false}, {"id": "C", "text": "set system name R12", "is_correct": false}, {"id": "D", "text": "set router-name R12", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c8dfd9ce58761e98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ebbd237-9ec7-44b2-9b22-7a41ab4dc54e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 75).', '[{"id": "A", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user monitor password", "is_correct": false}, {"id": "D", "text": "set authentication user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '71855c09b282523b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79762108-2603-4f71-8439-56b476afb4da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 75).', '[{"id": "A", "text": "configure interface xe-1/1/1 ip 10.227.23.1/24", "is_correct": false}, {"id": "B", "text": "set interfaces xe-1/1/1 unit 0 family inet address 10.227.23.1/24", "is_correct": true}, {"id": "C", "text": "set interface xe-1/1/1 ip address 10.227.23.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.227.23.1/24 interface xe-1/1/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '654b19a4e60f68c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('108a891a-f56f-4384-aa5c-45c35e5544d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 75).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3b2d5aa62ea74e24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4419e1f1-3290-479a-be2c-2900a31b7287', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 75).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6c0973ad32e21e2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ce3cc50-1ec0-4f58-a897-b924e295074a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 75).', '[{"id": "A", "text": "monitor interface ge-0/1/2", "is_correct": true}, {"id": "B", "text": "show interface ge-0/1/2 monitor", "is_correct": false}, {"id": "C", "text": "watch interface ge-0/1/2", "is_correct": false}, {"id": "D", "text": "tail interface ge-0/1/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '4a3601f0e9aa95f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76689f47-abfb-43b5-a048-7f7eb9c1f6d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 75).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '629253ca8de88ad8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8716ff4d-b4df-442f-a033-7c96c939cdfe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 75).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '4ea556acd60912bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df9f7cf3-cfb8-4044-bb88-3b13bb28633e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 75).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f6f8f9377341be38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e8a84cc-e747-4758-8887-511e6f225339', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 75).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd19b3b0b0e507ee3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36053883-c89e-47cd-a791-1e2b74273c82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.160.150.0/24 via next-hop 10.2.183.5 on Junos (variant 75).', '[{"id": "A", "text": "set ip route 192.200.46.0 255.135.184.0 10.2.183.5", "is_correct": false}, {"id": "B", "text": "set static route 192.160.150.0/24 gateway 10.2.183.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.160.150.0/24 next-hop 10.2.183.5", "is_correct": true}, {"id": "D", "text": "set route 192.160.150.0/24 next-hop 10.2.183.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '30dde127d884b038_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2de1b4bc-4862-47c5-8364-5992f4716215', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 75).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c4daff4a781eb85a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a25cb255-35b7-4cea-8f71-d3779e5aa8d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 75).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'bdf579c784d9046f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('942c45b2-d2e0-4f2d-8456-b8c5884d34ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 75).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4fbb31caa707afea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2b1b8a1-dd32-4523-add8-f2adf01b1df4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 75).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '07322e1e59882a82_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a99712a0-c394-401c-bcda-af42f43e7db0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 76).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6425e1667e8cdfe4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc6c1542-cb54-47a0-96f2-7b52582eee31', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 76).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '4b19bb271f2db99d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d3212f1-5ded-43c6-8f02-ba05ea55cc82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 76).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '4e225ea045e4e43b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42a28b24-2392-4acc-98e7-afd41555eaf9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 76).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'a304b3a3f88b66fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e3b0d3c-6492-4f19-843b-3f878f06194a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 76).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '58ad39b6141bf1a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39917a8b-7726-4706-9e03-f2e62e130aa3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 76).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '2f20c241d9c963ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcc2f50e-9a58-4fa1-ba86-d59525b45fe4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 76).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '72cf45a2a69b0939_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81986bba-cfee-4e4c-bf08-f8b329f612d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 76).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b0270d9b8af40352_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd4a430a-a401-4a0c-99ab-f0fe792d64ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 76).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7b423930a6ebfc9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('891588c6-5d68-4ef0-9f44-f431352743a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 76).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '845334c4e1148d84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a37c4582-f151-4247-9ff1-d36e0cec3c42', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 76).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'ea1b3847fe2cb05a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44fd5644-11f3-4b5a-b5e8-088ac79821fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 76).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fffbab02275dab56_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8b813cc-5488-4186-b1f3-7292cf934f82', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 76).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'bc41c9f21f2aa5df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6029cb69-2c1f-47f3-a9f2-0a420a90c082', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 76).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '92e61ee3a09613e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e09db64-ca44-40bf-a771-58a078bb3eab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 76).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '758c7dbb18b5fc50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d214a4fe-9a75-4288-b35d-f3db23b81b66', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 76).', '[{"id": "A", "text": "set router-name R2", "is_correct": false}, {"id": "B", "text": "set system name R2", "is_correct": false}, {"id": "C", "text": "set system host-name R2", "is_correct": true}, {"id": "D", "text": "set hostname R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3c8e2c67baec8281_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4bd85e99-4bc3-482d-b4aa-adec37e82194', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 76).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'dd47a0485d4b234d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58156270-3ffe-410a-87f9-0ff1ecc4a232', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 76).', '[{"id": "A", "text": "set ip address 10.105.60.254/24 interface ge-2/0/3", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/0/3 unit 0 family inet address 10.105.60.254/24", "is_correct": true}, {"id": "C", "text": "configure interface ge-2/0/3 ip 10.105.60.254/24", "is_correct": false}, {"id": "D", "text": "set interface ge-2/0/3 ip address 10.105.60.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'bade1ce14f9d40da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40508d28-f84c-4d17-9555-fe696fcbf33c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 76).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9cb6f9ff303cfb2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fc61b8e-986b-495f-9a90-cd29f5d54149', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 76).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a00f0a122539f8e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9937dfc9-7b93-4613-8ae8-f3e761eda518', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 76).', '[{"id": "A", "text": "monitor interface xe-2/1/1", "is_correct": true}, {"id": "B", "text": "show interface xe-2/1/1 monitor", "is_correct": false}, {"id": "C", "text": "tail interface xe-2/1/1", "is_correct": false}, {"id": "D", "text": "watch interface xe-2/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8fbd2f9008bc5e3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3ba4a91-fc2d-4d6d-924f-f12a489122cd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 76).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '94c1decd107deb0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f41358cd-d958-4489-826d-e66bdd1eda73', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 76).', '[{"id": "A", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '63aae69dab6c0598_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('611edea2-7f84-47e2-8883-e574372b6d39', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 76).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '6b0bbd7cc46ed986_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('290ad9b0-70fe-42ff-a28b-7af94f56aa36', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 76).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e950d73f168b93a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4993df11-57d7-48d5-bc89-f19c6b02daee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.3.75.0/24 via next-hop 10.157.243.1 on Junos (variant 76).', '[{"id": "A", "text": "set static route 192.3.75.0/24 gateway 10.157.243.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.3.75.0/24 next-hop 10.157.243.1", "is_correct": true}, {"id": "C", "text": "set ip route 192.22.23.0 255.34.69.0 10.157.243.1", "is_correct": false}, {"id": "D", "text": "set route 192.3.75.0/24 next-hop 10.157.243.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'dad93780905e1f97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7aa79fc-d21f-43af-916c-6f49df246d52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 76).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd7c3c385e6dde9fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5a42f03-698c-4214-931b-f9ad4a6f993c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 76).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'd213e76520377e27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb28383b-3c41-4b38-bfc8-5db6c381e564', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 76).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1e025689e8c27b08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c77309a1-fb2e-49a6-bc48-aae2bc2981d7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 76).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '87c8d5c8d61005e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bf6b94a-7870-4aed-b3e4-d4ca14cce94c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 77).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '8115af948aeaa5f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3732697-0cb6-4e9e-9b38-82c67555bc84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 77).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'd23156cc3193f626_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b03942f-3887-4bf3-99a4-fd307819c990', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 77).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '093fe6aa6ab550bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b06482b1-9707-412a-b412-b4ca5f3e9b5b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 77).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '0b087c118ba30f2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b72d6a2c-82fa-4141-b6ec-4ebdbfe60657', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 77).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'd1077350729d623c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfabc1bd-8de8-42ff-9698-05e37036318e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 77).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'a9f4aa0f60a0d01b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f192f87f-6551-4cf0-8e96-12e4f140297e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 77).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '38c1b1d77a67be43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bfd0e2a-1005-48c4-b0b2-c77f4d736071', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 77).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '70937ab08ac0eee9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a2bba6b-554b-4b93-b9e4-b28d3622caf9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 77).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0588212919885901_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e22d10d-ab6a-4fec-8337-d23b9fb0bf8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 77).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'cac93b6cbeb21d18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dcc14b5-58e5-4bbd-859f-1f94bcb81da7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 77).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'e30dbfcb6e58a0aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14fa97da-fe9a-499f-864b-ae7b0fd70e88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 77).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '14b9b797ad70ea24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d57c179-914e-447a-bcb6-0af259fd4fe3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 77).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'c015465ae8260214_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94440072-9dc9-44f5-a254-b414b28420c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 77).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c584d2f2fb05ca19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e75a36ba-964a-4bd3-9129-42e002c07b60', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 77).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '224936839c8aeaed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4c37ad5-3d43-41e1-91f8-b72cd805f70d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 77).', '[{"id": "A", "text": "set system host-name R4", "is_correct": true}, {"id": "B", "text": "set router-name R4", "is_correct": false}, {"id": "C", "text": "set system name R4", "is_correct": false}, {"id": "D", "text": "set hostname R4", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ac82ecd724b07b04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e87b5d7-d674-4fb7-8c68-d55277dc5930', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 77).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '29ca768721221358_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aad3c15b-11fc-4156-94d7-2f0c18072fb7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 77).', '[{"id": "A", "text": "configure interface ge-3/0/1 ip 10.252.26.254/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-3/0/1 unit 0 family inet address 10.252.26.254/24", "is_correct": true}, {"id": "C", "text": "set ip address 10.252.26.254/24 interface ge-3/0/1", "is_correct": false}, {"id": "D", "text": "set interface ge-3/0/1 ip address 10.252.26.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '1822163ec62d6c59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c84047de-5633-41c6-9fa5-9ce0df3dabfe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 77).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'da458c5bbd12456d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a46c468-13ce-4d5c-ae92-3bc660d4cb47', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 77).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '13d210a45e5e209c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02753d59-259a-431b-9377-4c5e869b491e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 77).', '[{"id": "A", "text": "monitor interface ge-2/0/2", "is_correct": true}, {"id": "B", "text": "show interface ge-2/0/2 monitor", "is_correct": false}, {"id": "C", "text": "watch interface ge-2/0/2", "is_correct": false}, {"id": "D", "text": "tail interface ge-2/0/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '9b14404f1718e0d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e1a686a-024e-42a9-b094-638f9ff141f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 77).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '48937108847a435b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf9a92c7-b4c8-4d4a-bcef-d6fd08c3c622', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 77).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '3283ef0e6f0aad88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('783d4696-6beb-4b65-b6ef-c2a3f1f784e3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 77).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '3ffe28d17cf8cd9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('159e111a-117b-4968-bc13-4a1c69794194', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 77).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c3b0ff47a0303ed4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40eca4b9-3722-48a0-9f9c-460fcfe0e26c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.18.184.0/24 via next-hop 10.158.185.254 on Junos (variant 77).', '[{"id": "A", "text": "set static route 192.18.184.0/24 gateway 10.158.185.254", "is_correct": false}, {"id": "B", "text": "set route 192.18.184.0/24 next-hop 10.158.185.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.78.49.0 255.106.141.0 10.158.185.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.18.184.0/24 next-hop 10.158.185.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7f766efc0d4a094b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81c1d150-fac6-434f-9d3a-54f214b4d021', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 77).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7c584a69786bfb93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9110f1c2-549f-43ef-9225-25024a14322a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 77).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '44f9c3ffa1dc3a39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a80c4c5e-8f82-4ea1-a01b-c206b7cb9e9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 77).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b5e92d27719e7974_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff4d79b1-306b-4f4f-b727-21143031f539', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 77).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '327badbaa263f400_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67e9da9d-4acd-44f5-aafa-8d86193435b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 78).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6363b8005003f89a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b8c1f83-78a7-40e3-89a4-d4e07fde0339', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 78).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '6453c5b1dd745c8d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea50c7ec-5587-4af9-a71d-951fd1930423', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 78).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '1734fea19eb74c12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b2d9812-da5f-426b-99cf-bc58ab2b4a1b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 78).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '1f06f6b208cbf805_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a11b931-23d1-4975-aa2b-91297e3d2274', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 78).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '452a0bbc9a81ae30_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d75b2836-bd86-4985-b595-29d91e78d06a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 78).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '8deab30b26563936_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf934a8d-82d6-4484-b514-be5295c7df7c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 78).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '633b83d882d0fb12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6493bf2-f17b-4e4f-bee6-a4e6dfcc0a6f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 78).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'aeaa693c40e7c602_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ee32820-5b8e-49f0-8fac-c52ed1781344', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 78).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '4531ef7080dc8bd8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('347396e3-580c-486d-aa75-b6c8a302914a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 78).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '483b3d0ce37301db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee768ef7-a07f-4f59-9682-4dee38285e61', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 78).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '24a580c51329eb01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9be58d1d-7ea4-44f4-ab0b-e457af45d8f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 78).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2dc85dd3f71bc662_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c20f58ea-4a7c-4e8e-a870-6a88be27f286', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 78).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1f59ff60d8e9fb1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6234eed-de10-4db0-a82b-ff06f8980e4b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 78).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '79440767f7aa556c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0068c08c-e8c8-44c1-a900-b48b3d3dbc96', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 78).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '19041172a344557d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08538900-e6d4-47cc-942d-78650166c825', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 78).', '[{"id": "A", "text": "set system host-name R10", "is_correct": true}, {"id": "B", "text": "set system name R10", "is_correct": false}, {"id": "C", "text": "set router-name R10", "is_correct": false}, {"id": "D", "text": "set hostname R10", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4776ee57a7e3be24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb5703fd-7c0a-4b76-a49c-36304085db1e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 78).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'ab1323bc6802a10d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b253db22-a27c-4261-93ba-16ad9d329dff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 78).', '[{"id": "A", "text": "set interface ge-1/1/3 ip address 10.118.209.5/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-1/1/3 unit 0 family inet address 10.118.209.5/24", "is_correct": true}, {"id": "C", "text": "configure interface ge-1/1/3 ip 10.118.209.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.118.209.5/24 interface ge-1/1/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '94a08278a9f374ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('488ea565-8816-40f8-89dd-855f95866dbe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 78).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9e80279d411528a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e736f6b-a466-4b02-b0e8-1c09e4d4b019', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 78).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'af9dc3330f85c8b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5f4c9bf-3af6-4ff0-bd62-cfab880bc842', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 78).', '[{"id": "A", "text": "monitor interface ge-0/1/3", "is_correct": true}, {"id": "B", "text": "show interface ge-0/1/3 monitor", "is_correct": false}, {"id": "C", "text": "watch interface ge-0/1/3", "is_correct": false}, {"id": "D", "text": "tail interface ge-0/1/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '03b9817c38194120_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f12a0d16-315e-4782-8b44-556490933b8f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 78).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5c036f58c1955aa7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d28f7b40-0df4-4e95-946e-e75c73877ddd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 78).', '[{"id": "A", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '64d1a9050960fe4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c57a9752-f778-4c93-bc3c-c3098beb9589', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 78).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '3e43e2235427c34a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c23a4cb-3724-4371-ab25-6adf79960bec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 78).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '856673e999554395_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fb9412f-7e1b-48b5-b771-5b2a9eae0a59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.122.196.0/24 via next-hop 10.178.155.254 on Junos (variant 78).', '[{"id": "A", "text": "set route 192.122.196.0/24 next-hop 10.178.155.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.122.196.0/24 next-hop 10.178.155.254", "is_correct": true}, {"id": "C", "text": "set static route 192.122.196.0/24 gateway 10.178.155.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.118.161.0 255.156.8.0 10.178.155.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1d249bbaa7498aa3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3a31369-7f49-4b88-b5ea-54f5cbf8231c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 78).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'd16a24275648064d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16e1cbf7-8976-4d7b-ab70-6f0e8a5a687e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 78).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'e780761004e778a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18e28578-2f0c-48b9-99f7-ed1ccc352b3b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 78).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0587c08b86427356_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49aca9d6-caa4-4a5c-a0b4-7dfb3b25394f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 78).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '47475dd42aa1714b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c99f8db-768c-4221-a054-8d3960f753ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 79).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'a4345040dff84674_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32c20be7-5797-4511-9e90-b0ca32677243', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 79).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '7026e8778a197f67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4d6916d-bac4-4c4b-a740-f34e148cae70', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 79).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '65c6731cf81f4cb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25c67a91-4126-4969-93cf-b9ecff512e20', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 79).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '65c4b5fb5588d0ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b714af1-08ba-4340-929f-e64f3e3bb3cf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 79).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '1f54b8b2198598cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b75891c6-837c-4498-835b-9637e8660a4e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 79).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '7efe57a131f144fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc0eeb10-ea77-4953-9efa-c37ccc32ef51', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 79).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b529292bf8039992_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af95a671-54c0-408e-a3a1-09d0d5c7fb59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 79).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a74e08c3a819e702_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5558ef59-d151-4efb-81f6-1479ae1a9fce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 79).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2167a9ade0b65a91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('840fc2cf-5525-41a8-81c9-698ea73e17c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 79).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '7a21d56e69e7b671_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5f8a00a-fa25-45d4-95c8-cc142e5a8e59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 79).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'aba56ee10bec000a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('948a31f3-ee4a-4e9e-aeed-2bc99ab589c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 79).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '4085ea64517d02c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4133db9d-38e8-4354-ae1a-5423e303a4a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 79).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'de093b91a675a16a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d09dc9da-6052-4890-af39-89c38274ea72', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 79).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '65f5dddbe9d8aed8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ae3fec2-ed0e-4ae1-b88a-62f3139f3767', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 79).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '820f9bc84f75bd1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8163b5aa-5430-429c-9cb9-cd52f55319c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 79).', '[{"id": "A", "text": "set system host-name R9", "is_correct": true}, {"id": "B", "text": "set hostname R9", "is_correct": false}, {"id": "C", "text": "set system name R9", "is_correct": false}, {"id": "D", "text": "set router-name R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'bdd00310a1d0a478_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60f2415e-3710-437d-a61c-2bd91e845684', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 79).', '[{"id": "A", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6d49db6f8e1af57a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e983162c-518a-46d3-b14d-65fb63889eb6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 79).', '[{"id": "A", "text": "set interface et-3/0/1 ip address 10.233.251.254/24", "is_correct": false}, {"id": "B", "text": "configure interface et-3/0/1 ip 10.233.251.254/24", "is_correct": false}, {"id": "C", "text": "set interfaces et-3/0/1 unit 0 family inet address 10.233.251.254/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.233.251.254/24 interface et-3/0/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '6715756f4930a38c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('734b1ea6-30f1-4af1-91e0-df5243d2cbfa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 79).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f487fc35f9c75b3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d811bf22-8b41-4e99-9370-db38d27b5611', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 79).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8e34ac0e6001d97a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd9c6dfa-4322-4eeb-96b5-99fc16daa63f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 79).', '[{"id": "A", "text": "show interface et-2/0/0 monitor", "is_correct": false}, {"id": "B", "text": "tail interface et-2/0/0", "is_correct": false}, {"id": "C", "text": "watch interface et-2/0/0", "is_correct": false}, {"id": "D", "text": "monitor interface et-2/0/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '4c6cc058e1388af3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9fe487b-c743-4942-b825-e1e9c4e96238', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 79).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '8b761128c0e5659e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46b174ea-1587-4ea2-bbc2-5103c2b21d95', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 79).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ae348ce973caeb8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86917fa1-aa28-4080-bd3a-f7d2af06d9d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 79).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'fa0d2dc3434af94d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('657a3e32-4c23-4a1f-9203-e5f9d88f76aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 79).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '93738dcbba3fa5dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89993c2c-d9fa-4795-959d-ba3922e39ec2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.96.172.0/24 via next-hop 10.162.86.1 on Junos (variant 79).', '[{"id": "A", "text": "set static route 192.96.172.0/24 gateway 10.162.86.1", "is_correct": false}, {"id": "B", "text": "set route 192.96.172.0/24 next-hop 10.162.86.1", "is_correct": false}, {"id": "C", "text": "set ip route 192.45.247.0 255.73.114.0 10.162.86.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.96.172.0/24 next-hop 10.162.86.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8c2b40720eb489c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3277accd-b865-4957-a40c-d1572acd4748', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 79).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '65f0c490d972cee3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80926a7b-acaf-41f6-81bc-67fd3a3de237', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 79).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '4b11d1c218377930_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6366f1f9-36e1-4e6c-8ed3-2ca7c5d588b2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 79).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '8a7c1afa75f8c5ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8687087-a092-473f-b40d-2e319e303818', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 79).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '142c9aa5da29d36a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fe5166d-dd32-4dc4-9838-aedca1b68e57', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 80).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '5bb1096b7a2ad7c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('882fb0cb-8ee8-4894-9afc-ab041550e6d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 80).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'e4b5977009ec9a5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dd1bbb2-85b1-4e67-868c-9e3f8a5b2319', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 80).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'ead8921fd1ba6580_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3da33bc2-f8f7-493a-97aa-cbce58145af6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 80).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'ee6d026ba17baab4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78c7e57d-bbaf-4f9d-a4c0-663622fa3d10', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 80).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '6515e202def329b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('219290dd-c709-4a38-b0e2-cc61f7eb4d25', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 80).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '713146317ca94049_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3e357ab-fa39-4038-9e81-275e32ae4e43', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 80).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1783e9505210acd9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe71374f-7228-4230-8e1f-c2cf50ef7db0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 80).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2cc436128b9dd90e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df0795c4-6df4-4d15-bb7e-e648d33418c1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 80).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '401c776e14e3c536_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78d033de-c14c-416b-a4db-cfdefa7c8eaa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 80).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'd2043a7e170f0df1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a5f08d2-624f-4aff-8fa4-1a3214a458d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 80).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '080aec5f8a7b5ab0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('825575df-63ad-4d67-b0e1-24dcbca849fc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 80).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '26edff1b27fc6ea3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16aac1f7-07dc-48da-98ee-3c1d7da2d0b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 80).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '06ebe847c1b84186_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bc72de3-4fa4-4c02-b2a6-f18ead052797', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 80).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '3c09087d523cb477_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e82c9947-e4f6-414c-ac1b-b2ee1c644659', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 80).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9b63ff0e856cd274_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74105548-046f-4380-9e18-8ddc064f6205', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 80).', '[{"id": "A", "text": "set router-name R10", "is_correct": false}, {"id": "B", "text": "set hostname R10", "is_correct": false}, {"id": "C", "text": "set system host-name R10", "is_correct": true}, {"id": "D", "text": "set system name R10", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b3a81369a419843d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ccbb300-e8b4-43b6-b959-2964bcb10d9c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 80).', '[{"id": "A", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '83219e055ad6d879_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfa46b2a-3f60-4ac7-b7e1-7abdd5b753f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 80).', '[{"id": "A", "text": "configure interface ge-2/1/3 ip 10.116.121.254/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/3 unit 0 family inet address 10.116.121.254/24", "is_correct": true}, {"id": "C", "text": "set interface ge-2/1/3 ip address 10.116.121.254/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.116.121.254/24 interface ge-2/1/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '8923f3db747f2fbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6164628f-3ccf-4f03-a8f2-68cf98181efb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 80).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'e480b2a1a070e4a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fa9ef98-114a-40ff-9883-e9cc4ce105e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 80).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8b484bff3913cb54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9f3a58d-1a0b-4d6f-8bc7-f4028d63c120', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 80).', '[{"id": "A", "text": "monitor interface ge-3/0/1", "is_correct": true}, {"id": "B", "text": "tail interface ge-3/0/1", "is_correct": false}, {"id": "C", "text": "watch interface ge-3/0/1", "is_correct": false}, {"id": "D", "text": "show interface ge-3/0/1 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '488707d8338a10ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ceb7d2d-6c93-4603-afd6-d9e3ff25c228', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 80).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '384ad957186a56cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01f155bb-9c9c-4fd1-811a-9a93969ff8fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 80).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '39ba058b02bbdf6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84d5c738-c2a1-45e7-8043-c03edeba9fa5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 80).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '71809eceee82e35d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bc82a49-6070-4216-ac3e-dcbff3acf13e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 80).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3fbb3d9f9ed49cda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f8e66f9-84d5-4f28-8d9a-806a821275f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.113.251.0/24 via next-hop 10.253.225.254 on Junos (variant 80).', '[{"id": "A", "text": "set ip route 192.34.97.0 255.137.100.0 10.253.225.254", "is_correct": false}, {"id": "B", "text": "set static route 192.113.251.0/24 gateway 10.253.225.254", "is_correct": false}, {"id": "C", "text": "set route 192.113.251.0/24 next-hop 10.253.225.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.113.251.0/24 next-hop 10.253.225.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '148f53800845ac2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f430c439-06df-4ca7-a8f1-47f59e6b0b71', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 80).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'ba58c90e87aa40b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f15f2fe9-c5a6-4515-b958-d65c26e893f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 80).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '4ab52e6ed00aca00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd5bb9bf-3b06-490c-8877-3c616d271435', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 80).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9f7772a1883da243_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('161f1494-9108-4cd0-abcf-c31ce8511b14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 80).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b62fd19cc3a8feab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed043afc-a601-429a-9a79-643b1a2039c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 81).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '1c9bc694a1172c7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce669d62-f199-4a2a-b26b-f2cace864873', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 81).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'c666803dafe72d46_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7a796a0-fc99-4d6d-99cd-c0e4d65cca7d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 81).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'f07ccb22b8664553_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce3b3a1e-ee2f-4e81-8374-a4639fa3b6d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 81).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'd9a2bd313910177c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0aa72dba-f187-45e7-a2b0-1bc6d2bc2d24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 81).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '512a869c8e1be3c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ae6f294-47ce-4162-94b7-b45dcaf07352', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 81).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'f35ad07bdca11864_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a3b66bf-93b7-4f77-8b42-26419b481d0e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 81).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '53a873f8d6a36e62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84574e51-4013-4df4-8571-a10f97f2e144', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 81).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'dea507f6d4038ae3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('793fb565-1ff3-4529-b82a-a7f819aaec3d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 81).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'c4035c587f7079ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a117e6f-638a-4ee9-a4d5-9f545e4041df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 81).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'd557df7a5b34219b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1196d8d-8e0a-4511-b5f7-57b74c0887d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 81).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4321a4992312ddc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53465be0-c192-4d8c-9118-e69eb6c98e9d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 81).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '8364d12ed384cade_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ffb8b92-e522-47b3-a367-cc1f05723121', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 81).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6e41d85820ed6277_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d8b32db-7e74-44af-a10b-19eb5127c991', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 81).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '08c65558c1f580b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60fefd14-1ecf-4e37-982c-c59856ed0b22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 81).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '03d8430984a26da7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a54d7e73-63c7-481d-9f6a-1f5e4c5967d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 81).', '[{"id": "A", "text": "set router-name R8", "is_correct": false}, {"id": "B", "text": "set system name R8", "is_correct": false}, {"id": "C", "text": "set system host-name R8", "is_correct": true}, {"id": "D", "text": "set hostname R8", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9f96fc82b12960b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7cb1734-6e30-4851-91a1-5e63616d68d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 81).', '[{"id": "A", "text": "set authentication user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '70810d7adbd922f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('984bdff5-2138-450b-be8a-65386582aace', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 81).', '[{"id": "A", "text": "set interfaces ge-2/1/0 unit 0 family inet address 10.14.122.254/24", "is_correct": true}, {"id": "B", "text": "set ip address 10.14.122.254/24 interface ge-2/1/0", "is_correct": false}, {"id": "C", "text": "configure interface ge-2/1/0 ip 10.14.122.254/24", "is_correct": false}, {"id": "D", "text": "set interface ge-2/1/0 ip address 10.14.122.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'd8677d3f4b4f96b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9290f929-8d84-4c67-be4d-4bc5261304cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 81).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'daaf6b2245806dbc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3565fd4-36db-499e-9322-5dd689020284', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 81).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'efa3c8dff00567ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e636bc0-cdf0-4dce-8a31-ebceab71aa3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 81).', '[{"id": "A", "text": "tail interface et-0/1/2", "is_correct": false}, {"id": "B", "text": "show interface et-0/1/2 monitor", "is_correct": false}, {"id": "C", "text": "watch interface et-0/1/2", "is_correct": false}, {"id": "D", "text": "monitor interface et-0/1/2", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'edf6621687212fc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edb483bc-5110-4c87-802a-80ae11a42dce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 81).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ffc8fe404e1360eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b064f636-37ce-48fb-adcf-a77a07404500', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 81).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'cbc99c510690b4e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f4823f3-62ac-49b7-9ced-d5ac24b9c60b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 81).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'ac724d4d9802b24c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('752f1427-73e3-4383-8c33-18bc4be9e337', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 81).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '4d50835e876cdd98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7e14917-9d81-4130-9889-ead86d9598ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.118.254.0/24 via next-hop 10.7.132.1 on Junos (variant 81).', '[{"id": "A", "text": "set static route 192.118.254.0/24 gateway 10.7.132.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.103.220.0 255.138.253.0 10.7.132.1", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.118.254.0/24 next-hop 10.7.132.1", "is_correct": true}, {"id": "D", "text": "set route 192.118.254.0/24 next-hop 10.7.132.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '64ebd40eff5af360_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44db3348-7a35-4ea4-bb8d-5cf5ebd3aa8f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 81).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '5d82783ca5dfe242_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53665e5c-362b-449f-a812-edc53af06f0c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 81).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'c4622e7c3ccad3eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2971653b-9e87-494c-a7da-fabda0dd85ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 81).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd1d01f5ba412a6a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c14ebd5-4d37-4314-a688-d2713ef3dcfd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 81).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '89fb76ac6204997c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5446b566-a4da-4a77-a1c3-24909964473b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 82).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6d65132c23627c58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a050e4a0-a5df-46af-b9bb-05fb64fa60ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 82).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '3ec79c90f571446c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e63b4859-cf2f-4f92-b168-e9a51ffb09f8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 82).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '6439206b6ad654e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f3c3ddf-ed70-406d-929d-61462a0d89f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 82).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '330da861396e9888_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52031c1b-34d0-465b-aeb5-f831e4360343', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 82).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '2b609aff68315165_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('880b6d5f-e15b-4481-a249-c5a8d3881cfa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 82).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '0a2ba7e014a64ff5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7101128-7960-4b16-a0e9-de6988931c18', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 82).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5fc26c47d47848b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7688cc2d-f1d4-4d83-9898-b37337fa0675', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 82).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0bc8a2e2fb736d2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a9190ce-605d-4da1-b83c-9fd10e29594c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 82).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'feab16cfe5d79e6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b44054d-e8a9-4b13-ae3e-d1f44793f295', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 82).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '763370e29ebc26eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('676c7d81-1fde-43d8-8a2a-a2717444899c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 82).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '140aa0d0e629a7a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51bd0358-7951-4301-a1bb-7375b76a1e6e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 82).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '34f4448b99710f75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b30e7246-e103-498c-b508-26555b6420b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 82).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "show configuration", "is_correct": true}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '68540c563269060f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42159301-c4f5-49a5-a5dc-29522e86660d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 82).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'c1ee76fa4554b934_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('027d1fb9-40bb-4626-a6df-817bbd9f2219', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 82).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f285fa6be1acd5ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b1880b4-6c38-43d1-8c77-d73e665e6b9c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 82).', '[{"id": "A", "text": "set router-name R3", "is_correct": false}, {"id": "B", "text": "set system host-name R3", "is_correct": true}, {"id": "C", "text": "set hostname R3", "is_correct": false}, {"id": "D", "text": "set system name R3", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '31e9febe7900574c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bedd076d-627b-4797-ac14-78f11043d702', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 82).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '3dea1b518866f463_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ba1b28b-2e22-4aaa-ab6c-dcb232eb2140', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 82).', '[{"id": "A", "text": "set ip address 10.133.80.1/24 interface et-3/1/3", "is_correct": false}, {"id": "B", "text": "set interface et-3/1/3 ip address 10.133.80.1/24", "is_correct": false}, {"id": "C", "text": "set interfaces et-3/1/3 unit 0 family inet address 10.133.80.1/24", "is_correct": true}, {"id": "D", "text": "configure interface et-3/1/3 ip 10.133.80.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '4d587346434b3301_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b50843be-30cc-4a84-9fa6-279e0c747543', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 82).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'fa4f335b9af4cdc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fee7dc35-2c5d-477b-97e3-91401f46262a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 82).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '22fa3960a9146bf8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9be8c4ab-7f33-4338-b657-0aa39b42bfd2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 82).', '[{"id": "A", "text": "watch interface et-2/0/1", "is_correct": false}, {"id": "B", "text": "show interface et-2/0/1 monitor", "is_correct": false}, {"id": "C", "text": "monitor interface et-2/0/1", "is_correct": true}, {"id": "D", "text": "tail interface et-2/0/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c247a0d83647af15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f48ad76-3c6f-4951-864a-4cd03504e3e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 82).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '0eb5e9edabcc324e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7cb8940-74c1-4aa5-8b01-443a04e03cb1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 82).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '933fd646c6051acb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed23ce7a-aa0f-49a8-b296-9f3a8d7c18a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 82).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'b7e4f6de7b051eb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2010e6f-c0e3-4972-9d96-e66a9e3dc28e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 82).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '1c82763e2eccecab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffc248fc-ba4e-4145-8046-876f219ea1c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.206.180.0/24 via next-hop 10.251.94.1 on Junos (variant 82).', '[{"id": "A", "text": "set route 192.206.180.0/24 next-hop 10.251.94.1", "is_correct": false}, {"id": "B", "text": "set ip route 192.6.68.0 255.85.191.0 10.251.94.1", "is_correct": false}, {"id": "C", "text": "set static route 192.206.180.0/24 gateway 10.251.94.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.206.180.0/24 next-hop 10.251.94.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '57d13259afb46bcf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa310dcd-7f04-42a2-81c3-e5b6aa88a95e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 82).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '581f989015523fe0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4297d42-f582-44b2-b337-e3938b190075', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 82).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '8b4446c302bf58fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0374eb52-1ec9-4654-93a2-29b4e840ac5a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 82).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5635bcf64f28400c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2bbe5d6-830f-441c-ad76-1184325d7c17', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 82).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '5fb1ac594424fa8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f4902fd-c539-4ae6-b3e4-c10d92c86441', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 83).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '0e29218c827192a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04c5d5f1-a556-4d7a-acf6-45ce4a81d206', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 83).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'a7495090928bb12e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdf2d327-b1e0-4318-931c-f052226d81e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 83).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'b9bfb245fc9ba486_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79f84bf0-12c5-4f4e-bcb5-a48d0b99e891', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 83).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'f660a33bc057bd7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e14ad2d6-7adf-4ebc-bc34-907ac71e8572', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 83).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '901c5c12a464a13c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b56dd7e4-4efc-4cc7-a0e6-31a33e5c87ce', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 83).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '7fc6d8292b19b5cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d37d1b8c-999e-47da-af20-a6b13f7fabc6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 83).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5169b910c6fbaef9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8060acd9-55f4-456e-8769-9a1c2ce3598b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 83).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '65f47a4769984ef0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('178312ac-722a-4b4a-b545-56d5ea5fd0b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 83).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'abd702f61c0b28bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2cb5d67-0cda-4061-9b45-8f23cd2530d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 83).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '57ef25c57988cc5e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68344b70-ae27-4e55-b674-affa997d68f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 83).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '3ac1759926bb5cc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c7d374c-c5f2-47d5-807b-68e722b19b8b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 83).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1ff004b458cdc0d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7eb99c67-fe72-47ff-9016-4b438bcb74b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 83).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '023aed17b200d346_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56a9251f-401d-4b6b-b0c8-87043aa86982', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 83).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '56cacac9a03a155f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66b88007-9120-4647-b788-af7b3e33e908', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 83).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4a2ae00d6f01fe54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61397473-6307-4ac1-b13e-e9e436b851b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 83).', '[{"id": "A", "text": "set hostname R5", "is_correct": false}, {"id": "B", "text": "set router-name R5", "is_correct": false}, {"id": "C", "text": "set system name R5", "is_correct": false}, {"id": "D", "text": "set system host-name R5", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '20315533b86ee396_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4828d5b-1b96-4edc-b3bc-a64f1a60ddb1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 83).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "set authentication user juniper password", "is_correct": false}, {"id": "C", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '95b6f8ab58750c43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08d1aec5-f015-4736-9166-13b0a4a87986', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 83).', '[{"id": "A", "text": "set interfaces et-3/0/2 unit 0 family inet address 10.252.223.1/24", "is_correct": true}, {"id": "B", "text": "configure interface et-3/0/2 ip 10.252.223.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.252.223.1/24 interface et-3/0/2", "is_correct": false}, {"id": "D", "text": "set interface et-3/0/2 ip address 10.252.223.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'ec9fed1b15611c5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c185966-0879-46aa-88c6-6588db48dd19', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 83).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '101cd532abaf0dbb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc7cf140-978d-4b84-8245-038b24016027', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 83).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '60086c2aa13e3f39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('444352fc-75a5-4edd-82c2-5827fed52037', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 83).', '[{"id": "A", "text": "watch interface ge-0/1/0", "is_correct": false}, {"id": "B", "text": "show interface ge-0/1/0 monitor", "is_correct": false}, {"id": "C", "text": "tail interface ge-0/1/0", "is_correct": false}, {"id": "D", "text": "monitor interface ge-0/1/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '6f542c145a00824f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f0b8ad3-3277-4307-be59-67e29f5540d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 83).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '14f6484e9f1f9057_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7de9d62c-0b94-4f33-aaba-f0f13bb87696', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 83).', '[{"id": "A", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a3883cd83a6b9c57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57e6dc26-b1be-4543-b289-1c04bbae3698', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 83).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '5716d8c02fd244d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('059f7f71-f8a5-42eb-941a-f5c9b04cff38', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 83).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7f1be8273605ee74_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c6adf97-6502-4bfc-b930-1160bcab91d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.249.234.0/24 via next-hop 10.174.44.1 on Junos (variant 83).', '[{"id": "A", "text": "set ip route 192.143.223.0 255.168.114.0 10.174.44.1", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.249.234.0/24 next-hop 10.174.44.1", "is_correct": true}, {"id": "C", "text": "set static route 192.249.234.0/24 gateway 10.174.44.1", "is_correct": false}, {"id": "D", "text": "set route 192.249.234.0/24 next-hop 10.174.44.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'ca210f55b829fe73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7a2325b-2224-4ec1-95e5-b0348914666c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 83).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e8b7e1570a087c86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9acfbc4-230f-4a9c-a3eb-709edff8d323', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 83).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'c60125578c5cfedd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a26ffb9e-4d44-49a9-80c6-f647eeb75aa4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 83).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'd271b76668a32554_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3937257f-1093-4b6e-b390-7745e7d72e9c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 83).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '573b48179c6c9718_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdfcf4cd-6793-4aa7-bc40-228622dcbd85', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 84).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '44c46d525928c5f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7eb9849-31fd-43ce-a9ac-00a456928543', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 84).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '2a1621a354c5f1c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea065030-22dc-4893-8b3f-b0d504312a9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 84).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '9a58349188c3739a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('608e8214-85fa-4276-9a24-2e0d40643908', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 84).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'a86f7addee445611_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed498a1c-5c06-4edf-b71e-127e843e96e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 84).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'b4c47c47c8179b14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cacf515-99a6-4641-b60c-2e2d0f702e4f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 84).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '2b6a92350eae3499_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d0b0deb-d7ad-4b1b-a01e-6bafb4a86a7d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 84).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b0b38bff4fdc7c95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05c352d2-7e08-444b-bf29-9418193fb919', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 84).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6d61114771d36d9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06634f5c-64f6-4945-a91a-3e1aaf3e2dc7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 84).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7b4de4259f321d38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c41e8775-c71f-46a5-a0dd-f650afb48bc0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 84).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '3207cf7c137c373d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63a0050c-881e-4c1f-b572-1dff2d8c8690', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 84).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '6e4188d9e0463bf7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecb5f885-29c1-4ccf-80cb-2cb7dbd62bcc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 84).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '222a0dcfd3e028cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98253dfb-fa3f-4d6c-97ec-c6570d6ce657', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 84).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7800134ae6e65a34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d1a61f4-027f-45cf-8425-68d04e07daea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 84).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '551ae4a46be010e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55fc39eb-d870-4371-a934-b1a021d11c3c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 84).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '9843f0f3e34c5aac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('494e5561-b3be-4b79-8a56-462e784e5f1b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 84).', '[{"id": "A", "text": "set hostname R2", "is_correct": false}, {"id": "B", "text": "set system host-name R2", "is_correct": true}, {"id": "C", "text": "set system name R2", "is_correct": false}, {"id": "D", "text": "set router-name R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e5f32bba7b58bdfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c0ca6dc-e570-4bb4-8567-e7cf15c13805', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 84).', '[{"id": "A", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a1299a5c7929ef02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7688ef3a-aaa9-4f58-ace9-375ae53c036d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 84).', '[{"id": "A", "text": "set interface ge-2/1/2 ip address 10.179.178.1/24", "is_correct": false}, {"id": "B", "text": "configure interface ge-2/1/2 ip 10.179.178.1/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.179.178.1/24 interface ge-2/1/2", "is_correct": false}, {"id": "D", "text": "set interfaces ge-2/1/2 unit 0 family inet address 10.179.178.1/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '1f4608a2ce4ccd55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ee1b7ac-6f47-4584-addc-16a8ae9c9786', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 84).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4278c7e22396ddbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1220dfe7-aed0-402d-9283-5288ec459ce1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 84).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '66d4341d0ae4bfd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e828613a-d4cf-4ed1-88be-1a79440f6d7c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 84).', '[{"id": "A", "text": "watch interface ge-2/0/0", "is_correct": false}, {"id": "B", "text": "tail interface ge-2/0/0", "is_correct": false}, {"id": "C", "text": "monitor interface ge-2/0/0", "is_correct": true}, {"id": "D", "text": "show interface ge-2/0/0 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '600f425874bfaff7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65fffd5b-89d7-40df-83b6-7a8800be5907', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 84).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b8d7e92e1e1e1fe6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('503aad9b-fe45-48b8-b1f5-07cdbdea3157', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 84).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '2bbce8ccfb1d32b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2d6cd12-1452-4325-82f5-dd45a11be41a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 84).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'bd83e019a1c70abc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc9f9ee2-cc34-4ab1-8f9e-e7b522c43398', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 84).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6185a5a2e25d1044_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a85c7ee-54ab-4949-9423-542129211285', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.85.254.0/24 via next-hop 10.10.217.254 on Junos (variant 84).', '[{"id": "A", "text": "set routing-options static route 192.85.254.0/24 next-hop 10.10.217.254", "is_correct": true}, {"id": "B", "text": "set static route 192.85.254.0/24 gateway 10.10.217.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.144.10.0 255.188.6.0 10.10.217.254", "is_correct": false}, {"id": "D", "text": "set route 192.85.254.0/24 next-hop 10.10.217.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '154e11fb64a7ac6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8027ea97-9a5a-409d-9a08-620e3bc8d7d8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 84).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7cf1c2daeb50cb5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fa992c7-8610-4e53-9a4d-2e369468568d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 84).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'ec8cc46840e27ac3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04eccf05-a275-4e69-9839-7651422a2fa0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 84).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '655d8433fbc5ff73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31bf1656-d488-4383-a85d-7d157ea0d37c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 84).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '6a60236b45014769_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e431d2b7-bba0-46af-a9ed-56fbd288ad65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 85).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '6c3379fa1b0a77f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('641ed805-06e3-4595-91fc-e848d06cf242', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 85).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '7f18cf2060156081_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db223f91-545c-4916-99d0-77e21eb68bdd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 85).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '63de150a99ab82ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('458c8b0f-087d-46c0-ae35-59b3e96f2b58', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 85).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "2 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'deca460bd6f6ba4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3da34d19-20f0-46f4-96e8-572ca556a5b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 85).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '285b33efd9d16672_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f63c5142-9755-4ee6-b8a1-53b05a46b82e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 85).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '8f19c34ebbf0ef6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1126594d-b10d-4a27-b9fe-0aee725238b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 85).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'acca4d02b355f61c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52cafb02-53dd-4fd5-b04b-c28f8d744f8d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 85).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '287ce986b118f321_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59cc00bf-f9a7-4e74-8570-492836c7b728', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 85).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8bc8091a5cfd792c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92fd7fc7-ca72-451b-8f60-f6c200b64243', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 85).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '3c858fe973d1db32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64569a42-b9d1-470d-8a18-416f28e458e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 85).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'a1cc9aeedcf7295b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5899945-0e84-42c4-ab84-a00663da68f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 85).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'e22bc84555981854_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e79517b8-476f-466e-9db4-bee8fbd85829', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 85).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '7d2708d8c7036a45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d629f2d-6dfa-4dd7-ac1b-f3a1d01687f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 85).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fa7c78a8a0fa894c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9dd128f-031f-44ff-bb79-ac3e3e2bf874', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 85).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ed4d9433d70b7c25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('092b3e30-3d6c-4715-8e78-4784bd5bcf2c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 85).', '[{"id": "A", "text": "set system name R2", "is_correct": false}, {"id": "B", "text": "set router-name R2", "is_correct": false}, {"id": "C", "text": "set system host-name R2", "is_correct": true}, {"id": "D", "text": "set hostname R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ecb72ca6f8b78856_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4379890d-3888-432d-b2ba-caa10c90445b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 85).', '[{"id": "A", "text": "set authentication user juniper password", "is_correct": false}, {"id": "B", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd28750931645930a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c424751d-c5c9-4f99-80db-2dfcb1c5b317', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 85).', '[{"id": "A", "text": "set interfaces ge-0/0/1 unit 0 family inet address 10.160.210.5/24", "is_correct": true}, {"id": "B", "text": "configure interface ge-0/0/1 ip 10.160.210.5/24", "is_correct": false}, {"id": "C", "text": "set interface ge-0/0/1 ip address 10.160.210.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.160.210.5/24 interface ge-0/0/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '682acc1d90721c45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30d540d8-f7c6-4b77-b495-e4f56f7d1c65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 85).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b7535d5a3029227b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e5076bc-21b1-4239-a82c-bcf4cfd1e30a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 85).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'c64a00f6aa7e938a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57751de9-7544-4e37-b589-a9e48ac015bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 85).', '[{"id": "A", "text": "show interface et-3/1/3 monitor", "is_correct": false}, {"id": "B", "text": "tail interface et-3/1/3", "is_correct": false}, {"id": "C", "text": "watch interface et-3/1/3", "is_correct": false}, {"id": "D", "text": "monitor interface et-3/1/3", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'e0ce905d5283b0df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b96fc642-da5b-4463-bbaf-52ba600fb80b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 85).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '38ec7617775ca0c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b23f41a-f57b-496b-bbec-c9c5378311aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 85).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '34148637bfef9c27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9255c206-200c-40ac-b030-f9f7854b60f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 85).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'de3c4be46649402d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3907443d-d508-4fc4-ae1f-b760c40b990c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 85).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '11923cdc26bf0e83_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4440e50-0dab-46f9-b069-20b1a0ea5326', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.189.231.0/24 via next-hop 10.32.122.5 on Junos (variant 85).', '[{"id": "A", "text": "set ip route 192.119.169.0 255.57.220.0 10.32.122.5", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.189.231.0/24 next-hop 10.32.122.5", "is_correct": true}, {"id": "C", "text": "set static route 192.189.231.0/24 gateway 10.32.122.5", "is_correct": false}, {"id": "D", "text": "set route 192.189.231.0/24 next-hop 10.32.122.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '96feb5dc9a81c7c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7df39a3b-2903-442f-be90-bdf08c954692', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 85).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '748b9d16cf80816e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53432254-0a26-48b5-82c0-e2776944282a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 85).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '65ec19e9e7377dfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f13dab28-45ee-42df-b006-8a4db14757d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 85).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '2462cc73c42f18bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52f57b74-ed01-487b-9471-56ecbee38205', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 85).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '1fd17b18a23a4b84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b095bd8d-417f-4f14-8161-eb61a7090bda', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 86).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '5dcbccaf8ea89ac8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5d7eb12-42bd-4b38-9497-cfac7cd770c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 86).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'ad9771f7cda6edc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8edbc4d4-332b-47fd-8bff-ef17a554cb24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 86).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Firewall", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '4369e0360c3507a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abf53d40-35c0-4052-85c1-b98f65ff0d8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 86).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '4229793054e1e042_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30bea564-bd0e-49ea-8f56-7f31efdef789', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 86).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '619aa7d38718531e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f55af998-c995-4765-98ff-136fae08959c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 86).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '5dc78d1c4bb751f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac028c04-2c15-487c-8259-0150e27d84cf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 86).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'a8530ada7c401ae6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e321d3fb-a446-4be6-b25f-b2da60c97388', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 86).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e315e5dbeee8e565_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70a6dbc9-30d1-4c9f-a335-34a37a475a58', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 86).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'cd628db240cf6ce2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b5a5454-7cb0-410e-ae70-9e4faa205d66', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 86).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'a1cc136e2eb00eb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b8ae693-7e01-4ab3-90fb-8cbae4c27820', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 86).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '48518798feb65a22_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fd057d4-453a-43aa-a5c9-e63dc2beef71', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 86).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '02050df11bca97ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc12a5c3-5d89-4345-9b91-022179385976', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 86).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f17ff77b0c665bc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aca3ccb8-2bd7-4ccd-89f1-a7993c0765c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 86).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'd419922307a3342e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de56cfc3-0aa6-44b9-b201-5b5c05ce0ee5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 86).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c348ff95f8f106b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a652d55-badc-4268-8ca6-8a420855607b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 86).', '[{"id": "A", "text": "set router-name R3", "is_correct": false}, {"id": "B", "text": "set system host-name R3", "is_correct": true}, {"id": "C", "text": "set system name R3", "is_correct": false}, {"id": "D", "text": "set hostname R3", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'be7e04ed007f9883_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('681073bc-930a-48da-ab0d-d6d58e31ddea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 86).', '[{"id": "A", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "set user monitor password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '84005c0a96a0266a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('935987ed-1fae-4660-85d1-41b8cf75e0d9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 86).', '[{"id": "A", "text": "configure interface xe-2/1/1 ip 10.135.142.5/24", "is_correct": false}, {"id": "B", "text": "set interfaces xe-2/1/1 unit 0 family inet address 10.135.142.5/24", "is_correct": true}, {"id": "C", "text": "set ip address 10.135.142.5/24 interface xe-2/1/1", "is_correct": false}, {"id": "D", "text": "set interface xe-2/1/1 ip address 10.135.142.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'c699871133508bd4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69bb3aa9-827a-4caa-95da-1b6c5b2e3ece', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 86).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f331fef9b1a49ade_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b95474cd-6810-4593-a5e1-57cd486045f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 86).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'fa090c2bd7647b7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d48ca73-0ebf-42a9-b3f5-2553fead761a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 86).', '[{"id": "A", "text": "show interface et-1/1/0 monitor", "is_correct": false}, {"id": "B", "text": "watch interface et-1/1/0", "is_correct": false}, {"id": "C", "text": "tail interface et-1/1/0", "is_correct": false}, {"id": "D", "text": "monitor interface et-1/1/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '265f998429d7b6ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bc6a1e1-6c62-457c-ad76-09065199d384', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 86).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'b0b5997bdb2b125d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('212de840-1b9d-4a97-8b7c-b5280d95d486', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 86).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd8eafcd5693ee65f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1e6461d-b5c7-4cd2-b8de-605da95100ef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 86).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f607b48f733871a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94544972-2b59-428b-a290-4162eafbd4a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 86).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '03772f0964e627a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be048cff-a545-4616-978d-3eee03594213', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.148.51.0/24 via next-hop 10.59.236.1 on Junos (variant 86).', '[{"id": "A", "text": "set ip route 192.250.202.0 255.236.110.0 10.59.236.1", "is_correct": false}, {"id": "B", "text": "set static route 192.148.51.0/24 gateway 10.59.236.1", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.148.51.0/24 next-hop 10.59.236.1", "is_correct": true}, {"id": "D", "text": "set route 192.148.51.0/24 next-hop 10.59.236.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '19aff3fb2d1e9420_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a77c96c-0ebf-48ca-a65d-a9dde1460db0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 86).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '2ed471d676a86317_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('903faeec-7a5e-445d-8e78-eb1cfdb40028', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 86).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '298bc3d48fe57ca2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('393aa02f-7e2b-491d-866e-228024438102', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 86).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '165c33e2c5246b53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed3af6fd-3858-42d2-b6e0-c662b9ed0436', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 86).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '709e6e6fe17b2608_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b42789f-289a-4d23-89f8-ef927366ce84', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 87).', '[{"id": "A", "text": "Layer 4", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'd90965a39047657c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c3df94a-2708-4e7e-9150-7cbba52726b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 87).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '9d87797daf33b6a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e40e7e78-dc94-46f2-9a84-942e5a280feb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 87).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'c6a0c02b25c0583c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b207145-5296-4ba1-8f25-c08149254a9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 87).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "6 bytes", "is_correct": true}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'f8b3fb648ac8accd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1efd8d3c-be42-4f9f-b9a4-d8fcb45db375', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 87).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '27ab5e4e83906628_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e64ae8da-b7e2-4b1f-8831-5c8b389ce123', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 87).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '2370e575df08281c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a495927-5063-42b2-83eb-e6d99c6908f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 87).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '95b4625dc3905436_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ec22e78-cdc2-4408-bc19-f4cb48c9b00a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 87).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'd36d6e01a0116e70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('774de392-4078-496c-80a2-54939f94579a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 87).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '780fa357ef0bb373_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc534748-0925-4c72-8af1-6028b70c2d65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 87).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '6692706593aa39cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f929d79-9673-4a1e-b0f9-fb798f847f1f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 87).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2f237355ac1b7920_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c023461-fed5-47c7-b7d2-679c7bd1b482', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 87).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '62b0b94c55a1c964_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a8fff0d-881a-4c68-a1b4-c13db0e24e20', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 87).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd238cb80b140c55a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ba34899-5279-4b06-ac84-e91e1f8ed174', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 87).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '571f4adb76098f64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('756b7e88-988a-4a1b-8ec8-07114ca24342', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 87).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load factory-default", "is_correct": true}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ca33e8c33b10f19e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c53df85-5f7d-4251-8666-2faea7dc3135', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 87).', '[{"id": "A", "text": "set router-name R1", "is_correct": false}, {"id": "B", "text": "set system name R1", "is_correct": false}, {"id": "C", "text": "set system host-name R1", "is_correct": true}, {"id": "D", "text": "set hostname R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '921c41221fe9f2a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fa6549c-99ec-4a0b-9813-5f7e3c4a36d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 87).', '[{"id": "A", "text": "set system login user monitor class super-user support plain-text-password", "is_correct": true}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4b5d57df4c5f0ed1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ddd88bd-3983-4ba4-bc8d-e79f6e0be9fe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 87).', '[{"id": "A", "text": "set interface ge-2/1/2 ip address 10.161.166.5/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/2 unit 0 family inet address 10.161.166.5/24", "is_correct": true}, {"id": "C", "text": "configure interface ge-2/1/2 ip 10.161.166.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.161.166.5/24 interface ge-2/1/2", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '8a985dbe26112416_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acdd8141-4f1d-470b-a7e7-f1f94e87953d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 87).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7a7dd2891a2c3827_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59716f86-3247-414e-8487-d0eece7359ec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 87).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '21b6d4cebfe7b09d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffe15e6c-2644-40d1-925f-b3182152e051', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 87).', '[{"id": "A", "text": "tail interface xe-2/0/2", "is_correct": false}, {"id": "B", "text": "watch interface xe-2/0/2", "is_correct": false}, {"id": "C", "text": "show interface xe-2/0/2 monitor", "is_correct": false}, {"id": "D", "text": "monitor interface xe-2/0/2", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '627e953d2869bf3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8aac7bb-fc5f-4ebe-9eff-9a2b3376cc95', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 87).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'bfc2518f80a09872_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c697b676-d5cf-4cbf-9ded-69fb4df53bef', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 87).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'f29c6f60380ff886_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e312d3b8-87a7-49a1-9a7e-e115bffcebb3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 87).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '603819fffe211371_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('046b0f81-4e65-4ed9-b70a-261832e356b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 87).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'd32f4fc033c3299f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcbc3238-f442-434e-b9b2-adc5d4f308eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.88.64.0/24 via next-hop 10.2.80.254 on Junos (variant 87).', '[{"id": "A", "text": "set static route 192.88.64.0/24 gateway 10.2.80.254", "is_correct": false}, {"id": "B", "text": "set ip route 192.219.250.0 255.28.135.0 10.2.80.254", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.88.64.0/24 next-hop 10.2.80.254", "is_correct": true}, {"id": "D", "text": "set route 192.88.64.0/24 next-hop 10.2.80.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3f9fac6e9f41dd34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa3bdf37-4ce9-4aad-ba80-e61979249928', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 87).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '54fb95129b8aa0df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dd8c1f4-2134-42ca-8877-f62ef93614ff', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 87).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '9995c513a84fc6b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f51403c-a072-4a6d-9709-5280d737697d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 87).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'df040d433366362c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c935a089-308d-4159-86da-718e78a4e58d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 87).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '3f7bd5ff6adefbaf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08666309-9628-4cc8-9776-5c05cb5581df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 88).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 3", "is_correct": true}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '436854961d59189d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6462160-a85b-4702-a13c-b2df2ebd028f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 88).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '766a5a62ac6a90c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('621e79b3-27fc-4462-abf0-8ec85ebcea20', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 88).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '169bc57a51191ad2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('763525b0-b982-48f2-a1a9-bdb3dab7bc54', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 88).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '6d4cca7c8003d3a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcc25dac-1f39-489d-aab6-1f7f6d16a79f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 88).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '284e39b542b983bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6cc5075-9c62-427c-b4e0-727b877c1a48', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 88).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'ec5124cdff72f611_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cbb5fd3-0ca1-4285-add4-c4566188210d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 88).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '42ed1a14a9bfb120_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bca6adec-c8a7-4cc0-beb9-85b12834e070', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 88).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1c35d67e38bd7488_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd8123b0-73c8-4ede-a2a2-bf2997be1ba2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 88).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '28533bf3be51a51b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24cd0888-816a-45b7-9e12-5c00ffc22a46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 88).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '77013fe141b0673d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b46d1fe-8848-4691-b32d-0e74d9ecdea2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 88).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1fa3b09070213e3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4185f5f-4d89-4704-b0d2-4a40a9cdc3e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 88).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '63cb17ba275c0f43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b5dbf9a-7b49-4d85-b1fd-d34880bd5cc2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 88).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "show config", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '62d67a6868c25a23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5b9acb6-c391-4686-9434-80f62ced2c3e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 88).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fc00ff50d3ca2088_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbbe485b-cf29-4f8e-9fc3-a1005accd264', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 88).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '27818b93660fba62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd626379-c93d-480b-88c2-e0e3e1234ad4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 88).', '[{"id": "A", "text": "set system name R9", "is_correct": false}, {"id": "B", "text": "set router-name R9", "is_correct": false}, {"id": "C", "text": "set system host-name R9", "is_correct": true}, {"id": "D", "text": "set hostname R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '7530f8de77de8671_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14a48d25-5d59-4c7c-a491-8875eddaf825', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 88).', '[{"id": "A", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'e27354888e2e08d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a883540e-9b10-466f-b464-af8a0e6802bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 88).', '[{"id": "A", "text": "configure interface xe-2/1/2 ip 10.39.179.5/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.39.179.5/24 interface xe-2/1/2", "is_correct": false}, {"id": "C", "text": "set interface xe-2/1/2 ip address 10.39.179.5/24", "is_correct": false}, {"id": "D", "text": "set interfaces xe-2/1/2 unit 0 family inet address 10.39.179.5/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'fe4e932d99295371_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3f66d24-a002-4872-a367-467a466dfd9a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 88).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '872fa1b5921fcad7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61ba8151-2c26-47aa-a95e-164f97856d04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 88).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b233f0a42d7b1638_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d18832e6-c821-4c0a-90d2-1a6b8b5f5cac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 88).', '[{"id": "A", "text": "tail interface et-3/0/1", "is_correct": false}, {"id": "B", "text": "monitor interface et-3/0/1", "is_correct": true}, {"id": "C", "text": "show interface et-3/0/1 monitor", "is_correct": false}, {"id": "D", "text": "watch interface et-3/0/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '056cb130f40635bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('466a8aa3-4fae-448e-96f4-f31ea912fd59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 88).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'e4857f1719d12a04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f1c8241-89af-4c01-9be5-0d3fed33487d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 88).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '276f3f33de4849d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bcf3b48-2145-43cc-a1eb-e0421427617d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 88).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "They are identical in Junos", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'c782279473b90e15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f189db76-8c26-45d8-9aef-68a00eda1908', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 88).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a7613118e8705ae5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c1ea4cb-4db9-4e31-992a-1d71e1f97be2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.128.172.0/24 via next-hop 10.217.97.5 on Junos (variant 88).', '[{"id": "A", "text": "set ip route 192.180.60.0 255.65.57.0 10.217.97.5", "is_correct": false}, {"id": "B", "text": "set route 192.128.172.0/24 next-hop 10.217.97.5", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.128.172.0/24 next-hop 10.217.97.5", "is_correct": true}, {"id": "D", "text": "set static route 192.128.172.0/24 gateway 10.217.97.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e7f37df711db3efd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cd30e21-6e6c-444c-b6c7-616144b7d5bc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 88).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '858369ad63b15d4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('265cf62b-d38a-4959-9311-a62c121ae34b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 88).', '[{"id": "A", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "They are functionally identical", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '8671566bc4e54164_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02742dc8-fd2c-437f-b4b4-69d3c4d02727', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 88).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '850291bcf98a4ba5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f202fbe-1a49-41ad-8d66-23f5e2dc57cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 88).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9d8482cd5521b747_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f2d27d2-88e3-480b-9535-fa66a92f85f3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 89).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 7", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '3a86a11f35ef1890_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d902cc4a-88a3-430d-9484-4baea3c1cb2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 89).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '5437bbb40a1d524d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f96754ec-b15d-42f7-96f8-626f966693c4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 89).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '24a082b1fad8ba44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9144219c-9ccc-4780-8faa-f37e14771106', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 89).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '48ce280ba78c101f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c319ae1b-93ee-45f5-b958-0d65b4d11faa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 89).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '1922e16aca121d37_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f58ff986-8fd3-454b-9584-009a0e55cd96', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 89).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '088d669c935d839d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53d438aa-ea1a-43d2-b217-4a19a9f0e6dd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 89).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '59e343b82c84c384_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d5460a5-b4fc-49e5-a0ae-b6c4a4d64c2d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 89).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'f1f6e38e53fb33e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a8792df-0ef8-4835-af41-fd1e1d756e19', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 89).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2a817548f4a81fc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64f87181-eeee-485a-8e8e-3ddd0826f03d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 89).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'b11d8aba40217087_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acd034f9-caba-47bb-90ae-978e72f1202b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 89).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'fda6668678cd0cc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5af7b2e3-0886-4d5b-a234-52ff57164ade', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 89).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '05299805ddf83ccf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d7cfe24-3a86-448a-970f-d0ad7f596c45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 89).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '3aca426c13195737_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e013a18-1d10-4a70-a7fc-50b690077c8f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 89).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ec5fe3268dbd809a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2a68ada-1318-4f3a-b22d-d3ff84e033b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 89).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'fd7c244beca0be4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc50e09f-401f-4f86-ab51-ce8272ead62f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 89).', '[{"id": "A", "text": "set system host-name R11", "is_correct": true}, {"id": "B", "text": "set hostname R11", "is_correct": false}, {"id": "C", "text": "set system name R11", "is_correct": false}, {"id": "D", "text": "set router-name R11", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e74dce2dadb5c16f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ae5e742-cfae-4808-9224-26b3abc1e62c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 89).', '[{"id": "A", "text": "set authentication user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a74d8165d282682b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56b90a0c-2c5c-4628-847c-c526910494f0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 89).', '[{"id": "A", "text": "configure interface et-1/0/3 ip 10.98.28.254/24", "is_correct": false}, {"id": "B", "text": "set interface et-1/0/3 ip address 10.98.28.254/24", "is_correct": false}, {"id": "C", "text": "set interfaces et-1/0/3 unit 0 family inet address 10.98.28.254/24", "is_correct": true}, {"id": "D", "text": "set ip address 10.98.28.254/24 interface et-1/0/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'da5c95a5959a58f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12b28f85-cbb7-4529-ac16-105d387c76e5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 89).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '57a192be97ec931a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fccb10d-dad6-4380-8fc6-ccedac28e1be', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 89).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '29af81f4527b9aa0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93ca5831-b3d7-4e27-b2fa-f9d1c4524e95', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 89).', '[{"id": "A", "text": "show interface ge-0/1/0 monitor", "is_correct": false}, {"id": "B", "text": "tail interface ge-0/1/0", "is_correct": false}, {"id": "C", "text": "watch interface ge-0/1/0", "is_correct": false}, {"id": "D", "text": "monitor interface ge-0/1/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '469ba7c5519b3e68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72c292f1-fa89-47b2-b3b1-001d537c97d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 89).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '0c116f942dfeaf5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25fe6f7f-6a30-43d3-b318-eb045529df7c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 89).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '37f76b69116db531_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1b9144f-07ae-4489-a9f1-2c76f438b758', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 89).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '99f3a583e0ce4343_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91770e63-381c-4ff5-97b0-0412562a22d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 89).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2ca462ebd8c285c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16c70a13-d6ec-4e4d-bd35-17fc30c052a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.169.154.0/24 via next-hop 10.73.130.1 on Junos (variant 89).', '[{"id": "A", "text": "set ip route 192.91.111.0 255.187.50.0 10.73.130.1", "is_correct": false}, {"id": "B", "text": "set static route 192.169.154.0/24 gateway 10.73.130.1", "is_correct": false}, {"id": "C", "text": "set route 192.169.154.0/24 next-hop 10.73.130.1", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.169.154.0/24 next-hop 10.73.130.1", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '0a972c2fa6a931f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b09e37d-97fc-4cd9-8b9e-d1c988eeef69', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 89).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7aac91cf813a9a20_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37b2ac4f-5b09-447a-903f-484a4281fea1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 89).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '325d0b0bccc51bd0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de0a8f77-79e1-486a-816b-4bc932ab4f3b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 89).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '560c425a1c8c968c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d47e9cfa-cbbd-4091-8968-e8ca81fcbf05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 89).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '3b7bb3f19abdbd48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c935a115-bf22-4acf-99ec-75a8f68b56d6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 90).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'ffec31b7e1ee47e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52dbd4fb-afe9-4b2c-8621-e9d31c66c9d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 90).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '35ff79d9a7886e35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5145bb88-af0d-428b-802e-993968bca8f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 90).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '6002a49c137d9b6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36a4b92d-d4b6-4d26-b8c2-90585ca455cc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 90).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '7ad633f7e4f8b74f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25e0b237-5f9f-424d-9cb7-fbeec411c4e2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 90).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '2e9ad4fb11bb5408_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a926bdc-739a-47bd-a485-2de20f639877', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 90).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'e8895010ced1a9e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f3831a4-e42c-4680-9800-8bf3f9dac6c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 90).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '99febe6fe21dce73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4f32840-3740-48ae-9abc-40187987cde8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 90).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '45bff9a65558312d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba6453f8-7244-4b36-8fe8-e4a4bc00fef2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 90).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '8bb32fb74c058871_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2afbec1d-5fc0-4815-9a88-9b3112f4b964', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 90).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '80d4b8de61079bb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1934779f-01a7-4561-9031-2caef9f3ed4a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 90).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '3f2433221c893987_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('962a20ee-403d-4f78-abf1-97007ba9c1f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 90).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "config", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '921941d6af0b5d0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e131408-2cf2-46bd-bf48-abf6b0cdb5f1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 90).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f8dfd2023bc6c41e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc529d52-0240-4e70-ab88-25a624e6256a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 90).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'ca4d8404c3c68b34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c0df6da-c53c-4189-9872-422012772693', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 90).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '32ecba85c608e25e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05969385-b36b-42f7-95fe-614d4654a11b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 90).', '[{"id": "A", "text": "set router-name R1", "is_correct": false}, {"id": "B", "text": "set system name R1", "is_correct": false}, {"id": "C", "text": "set hostname R1", "is_correct": false}, {"id": "D", "text": "set system host-name R1", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '2d339e6625664ca7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c5f5274-50aa-45b4-b551-403a36e740ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 90).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set authentication user root password", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user support plain-text-password", "is_correct": true}, {"id": "D", "text": "set user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'baf77e8857ccd4f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fba55f1-9508-4e4f-968e-e7b65d1d4747', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 90).', '[{"id": "A", "text": "set interfaces ge-2/1/3 unit 0 family inet address 10.29.45.254/24", "is_correct": true}, {"id": "B", "text": "set interface ge-2/1/3 ip address 10.29.45.254/24", "is_correct": false}, {"id": "C", "text": "configure interface ge-2/1/3 ip 10.29.45.254/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.29.45.254/24 interface ge-2/1/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'fbee00a48e949f0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33701b71-68db-4fe1-9b0c-f64bc2a44162', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 90).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '528be86bf6d8fe90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97a8467b-6618-457a-9287-a819fc2d593f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 90).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '449c1555f4e12072_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cff7a3f1-e1c8-4f27-8fb0-6f8064fbf2fb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 90).', '[{"id": "A", "text": "watch interface et-0/1/1", "is_correct": false}, {"id": "B", "text": "tail interface et-0/1/1", "is_correct": false}, {"id": "C", "text": "monitor interface et-0/1/1", "is_correct": true}, {"id": "D", "text": "show interface et-0/1/1 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '9efb985df459c359_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71de98b6-6594-4e28-ab61-37883cc6889b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 90).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "D", "text": "Download to /config, run upgrade junos", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd1fbf331089decba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ada6e1d7-8659-4023-92d6-9850579ebb65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 90).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'aab61a811d7bb130_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c080fb1a-46ef-4d13-9301-6bc75032c761', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 90).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '97b903b082cfe582_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c3f4c8b-4286-473b-b069-48054e2cad04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 90).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '65a022141f4dd822_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfce041b-f32d-4243-bac7-b267a3086d18', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.228.53.0/24 via next-hop 10.254.170.254 on Junos (variant 90).', '[{"id": "A", "text": "set static route 192.228.53.0/24 gateway 10.254.170.254", "is_correct": false}, {"id": "B", "text": "set route 192.228.53.0/24 next-hop 10.254.170.254", "is_correct": false}, {"id": "C", "text": "set ip route 192.101.118.0 255.54.250.0 10.254.170.254", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.228.53.0/24 next-hop 10.254.170.254", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '2fcad01a9c7ed162_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a1672ca-aa2c-4daa-b2ee-113c6001131d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 90).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c23eee74afc34adc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5d32e1d-75e4-4d33-b186-6101e409fded', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 90).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '13436e660db9588c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fe4ebc8-7a3c-437a-941c-6457887b7442', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 90).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a45347c429769894_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f812d31-1336-4cb3-95ed-a0c9c7ebbc7c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 90).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '0bcb15375543298a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f34b581-fbe1-45f4-bcf4-2a6dca583d10', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 91).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'c6398e658e46f314_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18ba9254-cc63-4a57-b37c-07b6e717d47a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 91).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "256", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '446c09777594745e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f52ab67-a2da-4297-b153-084c9af65199', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 91).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '9f12e48891c7a2aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9b62302-b983-4483-b207-7f9d53897634', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 91).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '7e70cd4ee7d09600_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7048d966-81d0-4344-a691-02f91a3cba1e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 91).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "IP address to MAC address", "is_correct": true}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'd785212761918db2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbf98b51-c9f9-4a77-9c92-acad1fafe6ad', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 91).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'ada92c4f36226e3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd4d831a-fb1c-4169-a77e-98e098c576b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 91).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9257166b2aaf3f6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b32c7c04-6533-4ef4-825f-9e13070f837b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 91).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'ffb84efeabdc30ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a951343e-ba5b-4088-beab-3c64f29b0188', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 91).', '[{"id": "A", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1c9f0fb6fa0690ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a781b1a-53ef-4e9d-9f8b-1baa6fb45ed4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 91).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'fe7f389726ed7daa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47f268e3-832b-4e0b-9c81-808dbc70de57', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 91).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '4044384516b0748e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16ca25fd-88c6-442a-854f-a81eb954035c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 91).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "setup", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '32e409c22ea50422_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2c32e90-2665-4b34-84e5-169056ea1a04', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 91).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '8be285a65802829c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b2eaa25-0989-4991-b945-a48d963650ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 91).', '[{"id": "A", "text": "Compares two configurations", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '328269b3dea489bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95bb008c-3330-4121-954c-140947948e10', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 91).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "set factory-default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5a887bec8ed8c44d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ac18e76-b334-4f68-8777-c4255ba8e36c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 91).', '[{"id": "A", "text": "set system host-name R10", "is_correct": true}, {"id": "B", "text": "set router-name R10", "is_correct": false}, {"id": "C", "text": "set hostname R10", "is_correct": false}, {"id": "D", "text": "set system name R10", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5775b79b4e5ae3d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0868786b-72e9-4838-b2ea-112284a46838', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 91).', '[{"id": "A", "text": "set user monitor password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user monitor password", "is_correct": false}, {"id": "D", "text": "set system login user monitor class super-user tech plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'd09b84b7203c45d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3217b5e-fbbf-4203-a0de-521a8695b411', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 91).', '[{"id": "A", "text": "set interfaces et-1/1/0 unit 0 family inet address 10.20.82.254/24", "is_correct": true}, {"id": "B", "text": "set interface et-1/1/0 ip address 10.20.82.254/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.20.82.254/24 interface et-1/1/0", "is_correct": false}, {"id": "D", "text": "configure interface et-1/1/0 ip 10.20.82.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '0af0e6454e8b44e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73d64536-f8fd-441f-84ed-3d217acca0a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 91).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '94e42128bd56e32a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('356369df-b025-436a-a74d-8a4b9ddd134a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 91).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '046a2721a572591d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c3c58a7-2e0f-47ca-825b-402a6a720361', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 91).', '[{"id": "A", "text": "show interface ge-0/0/2 monitor", "is_correct": false}, {"id": "B", "text": "tail interface ge-0/0/2", "is_correct": false}, {"id": "C", "text": "watch interface ge-0/0/2", "is_correct": false}, {"id": "D", "text": "monitor interface ge-0/0/2", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'ff81ab8a369fc8a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7405ade7-33b2-493c-b2fb-93e57e8db92b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 91).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'd786794ac9bb6ece_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c3286d3-9f9d-45f5-9d4f-2aede79e4363', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 91).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '026ec57ec1817793_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1e2f7f3-4b85-47aa-96d0-9051ebe0300c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 91).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'd3bfeda1ed421d28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9841b35-4d97-41ae-8b7f-e6307b28e811', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 91).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '97993cb89c1d2650_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12e8a707-38dd-4bfa-8b7f-91d50e135449', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.62.78.0/24 via next-hop 10.62.231.5 on Junos (variant 91).', '[{"id": "A", "text": "set static route 192.62.78.0/24 gateway 10.62.231.5", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.62.78.0/24 next-hop 10.62.231.5", "is_correct": true}, {"id": "C", "text": "set route 192.62.78.0/24 next-hop 10.62.231.5", "is_correct": false}, {"id": "D", "text": "set ip route 192.209.11.0 255.21.214.0 10.62.231.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f6bbc3d9308444cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c1dc862-0ca2-4be2-9e6d-84e592c086db', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 91).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c34f34968cd0e720_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e7cd833-3d7b-48c7-ae3f-ee73b04de5f5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 91).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "D", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '5ad53dd187da8105_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('643a518a-dadd-469c-ba15-fcf8d955ec1d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 91).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '78f2b8814b4ac8e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f91c8aa4-b25e-46d8-b7bf-8bed7cdad816', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 91).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a1d8eae5a7dafee5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88a27b08-b0fc-400a-91f9-78eef2e66b22', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 92).', '[{"id": "A", "text": "Layer 2", "is_correct": false}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'fb0b3935e20bc406_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47e37313-d6b1-4751-b2f4-a437b00544cb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 92).', '[{"id": "A", "text": "252", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'f50a36d47e71b15c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('196a431d-42a6-460a-a80e-aa65e5fbf3f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 92).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '7c1e517dabdd2c88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cba60fe5-0a80-42ff-b28d-88ecffb6a9b8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 92).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'e9113f73204bacd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33aed98b-d200-4a47-bb9b-1233ea2c1986', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 92).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '90d18f9b160d1cd5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f6f9343-73f8-469c-bcbf-1e39a8e183de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 92).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '5536e9bfc031d3f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2aa94bb5-145c-4ef6-a4b1-2c6eadf45530', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 92).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Board", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fa5ee281c2fb96c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01473786-a549-4cc7-b367-1e5bf80e6125', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 92).', '[{"id": "A", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'eca67182a9cc433f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba44dce8-cc02-4238-92b5-7ce8f5c451b5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 92).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Broadcast Ethernet frames", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '631d7055c91c0376_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5379a545-1a19-42a0-bae4-54a59d23b203', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 92).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'aebbc443fe93b48b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d473b1d6-53e9-4254-a155-bf45505302ab', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 92).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '9e2be0e403e3ba36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d321603-2ac5-4cdf-9c07-c4eda7a6c70c', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 92).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '014a59b8e2be972b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71c799a0-56c9-446a-b5cd-97b162896c43', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 92).', '[{"id": "A", "text": "display configuration", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'afdda08e7494b6bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34253886-f280-4fc1-8fc8-ea3a0f58f13b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 92).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'baf41d50465667a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cf706e5-df3e-4a3e-a7b7-56946a1ac985', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 92).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ad489c0449e821df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a07ff9b-dc7a-4b4d-afdd-70639035cf73', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 92).', '[{"id": "A", "text": "set hostname R1", "is_correct": false}, {"id": "B", "text": "set system name R1", "is_correct": false}, {"id": "C", "text": "set router-name R1", "is_correct": false}, {"id": "D", "text": "set system host-name R1", "is_correct": true}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3e6bcf908b6095b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13ad4c98-e887-417e-b1d2-114f17e9b2d7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 92).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4b335b427acac15d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('859776f2-e9ea-4a24-bfce-b82edb11079a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 92).', '[{"id": "A", "text": "configure interface et-1/1/3 ip 10.139.127.254/24", "is_correct": false}, {"id": "B", "text": "set ip address 10.139.127.254/24 interface et-1/1/3", "is_correct": false}, {"id": "C", "text": "set interface et-1/1/3 ip address 10.139.127.254/24", "is_correct": false}, {"id": "D", "text": "set interfaces et-1/1/3 unit 0 family inet address 10.139.127.254/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'd95bca777694f285_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6632dcb5-cd45-47a2-bf81-cca058fb0323', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 92).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'f23f734f59c5e15a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f582612-5a7f-4f47-addf-78f6302272b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 92).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '28eb258f0110a290_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25a836d5-10e6-4118-b726-fd24751311e0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 92).', '[{"id": "A", "text": "show interface xe-2/0/0 monitor", "is_correct": false}, {"id": "B", "text": "tail interface xe-2/0/0", "is_correct": false}, {"id": "C", "text": "watch interface xe-2/0/0", "is_correct": false}, {"id": "D", "text": "monitor interface xe-2/0/0", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '81eae6a9661c7f88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa8779a6-807e-460c-a4b7-2075218962a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 92).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7c54749f6e1f6660_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7dc20756-b4f6-4814-90e5-dcc9413b3448', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 92).', '[{"id": "A", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "B", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "D", "text": "Contact JTAC to generate a recovery key", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '779777f0ae9fcd32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e8695b1-9410-4f92-9845-47f30026fd8f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 92).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'd16f8ccf2fb64cd6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf242c30-8f54-4c3a-a8a3-d74954acd923', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 92).', '[{"id": "A", "text": "A routing metric like hop count", "is_correct": false}, {"id": "B", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "C", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c9af86704c6fe37e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1593e850-44dd-4cb1-b7d9-ee6c6ece0870', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.208.148.0/24 via next-hop 10.138.5.5 on Junos (variant 92).', '[{"id": "A", "text": "set routing-options static route 192.208.148.0/24 next-hop 10.138.5.5", "is_correct": true}, {"id": "B", "text": "set route 192.208.148.0/24 next-hop 10.138.5.5", "is_correct": false}, {"id": "C", "text": "set ip route 192.86.170.0 255.210.91.0 10.138.5.5", "is_correct": false}, {"id": "D", "text": "set static route 192.208.148.0/24 gateway 10.138.5.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '93b9d2c458ec268a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('335c3700-1f95-45e0-9eb9-6737997e2708', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 92).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'e4e90fa01f2eb207_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04d400df-aa39-48fc-b6ee-39e093c9ca24', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 92).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'f0445be8afbeea6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('726c7e15-66f0-48af-b1db-bba669627cf9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 92).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'ba688e9b3681406b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1adaca8-ceef-4d88-8e7a-a093931ef468', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 92).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '7878bb6872ade870_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48089f6d-727c-4420-9d35-3db96d1e9032', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 93).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'e3ed9c2ea8dfe20d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f8c76ec-435d-4eb6-b5db-977e4cd4b9f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 93).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '988294264e5e5f4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36ea6f97-892b-44f6-9394-1a0d5fa41777', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 93).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '912bc9d0ed71fa56_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dea3486e-94ca-4862-98cb-77a505f14bc3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 93).', '[{"id": "A", "text": "4 bytes", "is_correct": false}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'd1cc9a245ca5b9cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5f55092-a40f-4348-ae25-0e62f760e2eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 93).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '6bdfe2b95e4c7357_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89bf74d9-2c12-4b94-88d2-69cbd1d9617d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 93).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "CPU and Memory", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '08c0ebc4e2d18f03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb771b76-aea6-44af-9756-b459c1941e5b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 93).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '2ce671da7bd4dfec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db1b4b2f-b66f-43aa-9d72-49a1adf216d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 93).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'cc08e8ac978de336_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a2f066b-0371-4a48-b35a-3c8a177caa06', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 93).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '51b53735cb24b190_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5c8c151-a2fd-4aa6-83fb-5cee30cace7e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 93).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'b95b2fa83a238e92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ea4f1a1-0833-4ddc-84d7-599f051de7a2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 93).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Read mode and Write mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '144fb56f2ed6ce4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78ecf874-503c-45ab-9d8a-e020e90a76d4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 93).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1dd9f02188cc3628_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('072a5623-3502-4c6a-9a62-574daa45e5a1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 93).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'be6b2207a7d7d4b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c0e7015-0bd6-4054-8564-654e985806a9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 93).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '4abcf9eb7768b3fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2a83d77-92fb-44ea-9ed5-35a272e25fc1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 93).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '71e31c7411a1d5f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84b887b1-cf6b-46d0-8ae2-d311d16eed4e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 93).', '[{"id": "A", "text": "set hostname R1", "is_correct": false}, {"id": "B", "text": "set system host-name R1", "is_correct": true}, {"id": "C", "text": "set system name R1", "is_correct": false}, {"id": "D", "text": "set router-name R1", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3fca469645f1bf3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8c42748-4592-4309-ad23-626704c2bfe8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 93).', '[{"id": "A", "text": "set authentication user root password", "is_correct": false}, {"id": "B", "text": "set user root password", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user tech plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9bc78cfab5fd6d63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c429498-dbf1-4309-b103-92f8a6affeb5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 93).', '[{"id": "A", "text": "set interfaces ge-2/1/1 unit 0 family inet address 10.65.104.5/24", "is_correct": true}, {"id": "B", "text": "set interface ge-2/1/1 ip address 10.65.104.5/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.65.104.5/24 interface ge-2/1/1", "is_correct": false}, {"id": "D", "text": "configure interface ge-2/1/1 ip 10.65.104.5/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'f58c07a44a1db30d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f4eeda6-76eb-439b-ab63-4e5c353cbc4a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 93).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'c01bd5c5a1be25c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57a2ecf5-26a0-473c-925d-77c44c2bf00a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 93).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '8d310f6b2649392a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03f57cfb-495f-4e4f-bff8-cb571480823f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 93).', '[{"id": "A", "text": "show interface xe-2/1/2 monitor", "is_correct": false}, {"id": "B", "text": "watch interface xe-2/1/2", "is_correct": false}, {"id": "C", "text": "monitor interface xe-2/1/2", "is_correct": true}, {"id": "D", "text": "tail interface xe-2/1/2", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a6c06e3493bdf1c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dab9d6fc-16f3-4c3e-acea-07bd4a22f7df', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 93).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ef4c93fdf62dad97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1de24335-1158-42d3-a5a6-4d6507eaecf1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 93).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '344934c46a5553b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cf08ab3-7dee-44f3-ad51-30ed1fc7091e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 93).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'b8a9a3a55cb28f00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e47abe28-50a8-43ed-967c-bd8dc1e638e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 93).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'c983b53f2224060f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d87a99ed-e3eb-4e8e-8526-74936d168db6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.106.186.0/24 via next-hop 10.4.109.5 on Junos (variant 93).', '[{"id": "A", "text": "set static route 192.106.186.0/24 gateway 10.4.109.5", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.106.186.0/24 next-hop 10.4.109.5", "is_correct": true}, {"id": "C", "text": "set route 192.106.186.0/24 next-hop 10.4.109.5", "is_correct": false}, {"id": "D", "text": "set ip route 192.141.222.0 255.44.55.0 10.4.109.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'bf7eb53447603dcd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea4b6769-8ab8-4905-b186-a81f3b206630', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 93).', '[{"id": "A", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '2104b67aaedb6d69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4c0f6f0-7675-4546-a1b4-e6c188602adf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 93).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '2515df49a4773048_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c0ffa06-ff4b-4e9f-bfe3-e75c6813bf8b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 93).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'b66b296a0a0b9927_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('189599ad-4513-4bff-964f-be93f882b8a6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 93).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'fbdc7687bdfd0727_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f826836-c766-4c24-9ca8-2eccbc70088e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 94).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '38c1946e3527d945_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d4c4588-5b77-4feb-ae70-cebd4a0141a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 94).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'd4e3f49222a60fb0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60c74fee-39be-490a-9eb8-d25e39b62c34', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 94).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Router", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '81d81199cb6912e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b402b1a-8db1-41d3-9be6-accc3f9a6686', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 94).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "4 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '535b6cca66c6d21f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4487d533-262c-4567-b7bc-11c4fe7b502f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 94).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'e7466d9b805ae823_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cf7a9c7-9715-46a2-b624-dfb581305e8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 94).', '[{"id": "A", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'ea586280ffddc7d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be09074a-8781-49f8-b673-f265bb46f75b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 94).', '[{"id": "A", "text": "Control Board", "is_correct": false}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Management Ethernet interface", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'fb0d931685d62575_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ff23e1a-7ac0-43b4-b393-bd8ba69ae187', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 94).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "Transit traffic bypasses the device entirely", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1b5ef22929ca9b02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b705118-6f6d-4444-bc28-978fc0c2cacf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 94).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "All transit traffic", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '688f0d996d7a89b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40de2f9b-846d-448f-870d-7c3297d76f5a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 94).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Packet forwarding stops if the RE fails", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '52019c3632c9fbfe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfa9a9d4-604a-423b-8e28-ef4b25fc57ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 94).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '57597038a3d9c12d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1482695c-54b6-47e0-9151-5695875fcbed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 94).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f106a675d186fc71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e9619a2-b44d-4f29-a775-efe2a5a033e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 94).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'fa49cc2f21fd3a4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7088628-b195-4f43-ac9e-29f6b38a0701', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 94).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'a8f88b5097b49fb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8f775c6-c848-4071-b219-4f9767aff02a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 94).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '065bba74085fc2d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d77f9355-49d3-465f-961a-21eacc987a3b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 94).', '[{"id": "A", "text": "set router-name R9", "is_correct": false}, {"id": "B", "text": "set system host-name R9", "is_correct": true}, {"id": "C", "text": "set hostname R9", "is_correct": false}, {"id": "D", "text": "set system name R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'ccceda22905cca1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edd16073-175a-422f-a2ac-0f79440b1e59', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 94).', '[{"id": "A", "text": "set authentication user monitor password", "is_correct": false}, {"id": "B", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4204d7bbc33b00fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd652acf-ece2-48e7-8c46-3e47625afafd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 94).', '[{"id": "A", "text": "configure interface xe-0/1/1 ip 10.158.109.254/24", "is_correct": false}, {"id": "B", "text": "set interface xe-0/1/1 ip address 10.158.109.254/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.158.109.254/24 interface xe-0/1/1", "is_correct": false}, {"id": "D", "text": "set interfaces xe-0/1/1 unit 0 family inet address 10.158.109.254/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'b3b5e63abbfced4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa0863b1-ecbb-4b54-86cf-366eccd6e879', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 94).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "C", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '4a3bb54c429a3475_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4546c6f-9dfc-4cb3-a80a-b47928831d38', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 94).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "display interfaces", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '1c9f0474052e67c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35387c7f-a67b-47c4-afc0-46be6d7dac66', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 94).', '[{"id": "A", "text": "tail interface ge-3/1/1", "is_correct": false}, {"id": "B", "text": "watch interface ge-3/1/1", "is_correct": false}, {"id": "C", "text": "monitor interface ge-3/1/1", "is_correct": true}, {"id": "D", "text": "show interface ge-3/1/1 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'a1af367982931904_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2629564e-d8ac-41e4-b431-719a5624b8a5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 94).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'ef1158da3a24cb43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88f1c77f-f403-4916-b039-e2cc4b6fea56', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 94).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'bfe33da680e593ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('591f18b0-7dc2-410d-a3a7-202eb40dc5b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 94).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '7db7b6f3925469e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76eb28f5-eab0-4fbd-a190-336f3e67a686', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 94).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A routing metric like hop count", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3477b3c7f090123c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16529232-8eb7-4ad2-b183-b5412e424d2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.167.180.0/24 via next-hop 10.112.182.5 on Junos (variant 94).', '[{"id": "A", "text": "set static route 192.167.180.0/24 gateway 10.112.182.5", "is_correct": false}, {"id": "B", "text": "set ip route 192.121.102.0 255.119.22.0 10.112.182.5", "is_correct": false}, {"id": "C", "text": "set route 192.167.180.0/24 next-hop 10.112.182.5", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.167.180.0/24 next-hop 10.112.182.5", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '3ee1426b26eba416_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33373553-7a45-4c59-8723-4f2ffc56fb1b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 94).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '7b88d089ac056ef4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4789a167-f0d6-42cd-a2ab-0155450d4221', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 94).', '[{"id": "A", "text": "They are functionally identical", "is_correct": false}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'ba079da0a22feaaf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8dd3597-06ab-4767-9d96-b5a7b1644103', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 94).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Name, protocol, and action", "is_correct": false}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'cbabca152c0547df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b2b8a7e-1357-4316-8af0-687820274bc0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 94).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Verifies the checksum of the IP header", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '88e231dab750dac9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('129edaf7-a77e-4a24-8b23-7164cd61b909', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 95).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 2", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '7d9808e65344760a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56c870bb-136e-46cc-ba1f-4daac49616ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 95).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "254", "is_correct": true}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '19ea30f3bdcf7bd7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4360003d-d307-4eaa-b120-a7d3c09d25b3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 95).', '[{"id": "A", "text": "Firewall", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Load balancer", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '58a5bf7b1ec672c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f549914-77df-4dbb-b81e-10eb23d6cd62', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 95).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '2baf693e30cc1f62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78529652-0af8-4c44-94b4-2c9ee70b4db2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 95).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'b0c0f2d56abffc19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d7e3909-84a7-4a02-93df-4aa28fc359b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 95).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '29a9cac31e054317_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9271cf79-92c1-423a-b4bc-7e987335bfb7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 95).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'b48fc9546ce65ddc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c21637c5-4135-4222-8d63-0f033e7709f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 95).', '[{"id": "A", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '5871470ccf12b220_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dffbd49f-3b79-4e54-9d3d-4291cc8483a9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 95).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7dde0d8d0d1c4015_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('973faee1-336e-4f99-acb1-034fd8b5f952', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 95).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '838ef6653c4d517c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ea2832f-cf3b-4493-9fc4-dd816419b4e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 95).', '[{"id": "A", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "Operational mode and Configuration mode", "is_correct": true}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '70eafe6c1e369949_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e96f1a5a-b5bd-44fc-b9fe-9e89c5e5b258', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 95).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1eea606bfbbfeefe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b5e953a-f579-49f6-8e88-a15db79d3cbe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 95).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "display configuration", "is_correct": false}, {"id": "C", "text": "show config", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '0a5087d511777b4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56f9963f-e671-4ebd-a5fb-abbbb8099acd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 95).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'fc3ad55ff703b278_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdb84e05-c1aa-4620-920b-4866290dc044', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 95).', '[{"id": "A", "text": "restore factory", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8b1757c73db50972_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70905f41-ee70-453c-bdd7-d3403545c5ed', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 95).', '[{"id": "A", "text": "set hostname R2", "is_correct": false}, {"id": "B", "text": "set system name R2", "is_correct": false}, {"id": "C", "text": "set system host-name R2", "is_correct": true}, {"id": "D", "text": "set router-name R2", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8eb5041656de4ae1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dc1fc95-2138-4c90-bcac-93885e5c9323', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 95).', '[{"id": "A", "text": "set authentication user monitor password", "is_correct": false}, {"id": "B", "text": "set user monitor password", "is_correct": false}, {"id": "C", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "create account bob class super-user", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '5f00936c1ba8631a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7e587fd-be19-45a3-b2e8-89f2b2e0dfd5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 95).', '[{"id": "A", "text": "set interfaces ge-2/1/3 unit 0 family inet address 10.26.43.254/24", "is_correct": true}, {"id": "B", "text": "set interface ge-2/1/3 ip address 10.26.43.254/24", "is_correct": false}, {"id": "C", "text": "set ip address 10.26.43.254/24 interface ge-2/1/3", "is_correct": false}, {"id": "D", "text": "configure interface ge-2/1/3 ip 10.26.43.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '6a7ec63ae9acc1de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ca74afd-a84b-4a62-be9c-85cf2cd453aa', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 95).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "C", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '80da7e00a794cc9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65099d66-70f8-4c77-aef1-ec864db0091d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 95).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interface status", "is_correct": false}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interfaces terse", "is_correct": true}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'f1ab79552f271a97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8630afbf-e6c5-4f3c-8e53-94d52d59572a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 95).', '[{"id": "A", "text": "monitor interface ge-1/1/1", "is_correct": true}, {"id": "B", "text": "tail interface ge-1/1/1", "is_correct": false}, {"id": "C", "text": "watch interface ge-1/1/1", "is_correct": false}, {"id": "D", "text": "show interface ge-1/1/1 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b0dfeb3d1e44111d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('058c35d5-1386-4bdf-aabf-676e8471e983', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 95).', '[{"id": "A", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '24fef2329fcabd77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9ebdf6e-876f-4002-9b20-37e0761591a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 95).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '7d705c3a8dc682ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97a625ad-e379-41fe-9dd6-426f879444c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 95).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'f1a578a49dae8756_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83a4bbe8-491a-4df3-a89a-994198c8f807', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 95).', '[{"id": "A", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e804f5708d7faf8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d4cc4f4-bcf3-4e95-a2f3-9b6f22da1bea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.21.47.0/24 via next-hop 10.240.208.1 on Junos (variant 95).', '[{"id": "A", "text": "set routing-options static route 192.21.47.0/24 next-hop 10.240.208.1", "is_correct": true}, {"id": "B", "text": "set static route 192.21.47.0/24 gateway 10.240.208.1", "is_correct": false}, {"id": "C", "text": "set route 192.21.47.0/24 next-hop 10.240.208.1", "is_correct": false}, {"id": "D", "text": "set ip route 192.204.245.0 255.230.124.0 10.240.208.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '30484127f797156a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fca968f3-f668-445d-9453-21c41bae9c28', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 95).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '0d92ada507b880fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c225a04-654c-4df7-9298-3dc06887d0c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 95).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '0eaaf3caaca46ada_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec5ded64-2ef5-4d63-af70-5b1fb0d59c75', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 95).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "Source, destination, and port", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'c008ef006277d5c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c10e9f8-85ec-43c1-a4fa-8901834e2d78', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 95).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '76cbe6ab98e071aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37bb109c-696f-4431-9aa1-638bfa6048d1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 96).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 4", "is_correct": false}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'a9d2e3945d7bd569_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('385e4c93-d480-409f-a9e8-411f8283b5e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 96).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "252", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '445225da4f40b017_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33b26f34-4c54-444d-a344-2764c8fc4ae9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 96).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Switch", "is_correct": true}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '0b8b4f1fdbcc0333_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6a47f20-6e2f-4d6b-9916-4aa38610b64e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 96).', '[{"id": "A", "text": "2 bytes", "is_correct": false}, {"id": "B", "text": "8 bytes", "is_correct": false}, {"id": "C", "text": "6 bytes", "is_correct": true}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '5a487b2d6ee93e9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac10f03d-3f49-4448-ad53-806b50423fdc', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 96).', '[{"id": "A", "text": "IP address to port number", "is_correct": false}, {"id": "B", "text": "Hostname to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "MAC address to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'b896189aed66108c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3cd253c-3c8a-466e-a91d-6f13a8ef0a87', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 96).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '1031d7e9de70b466_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff647758-884c-41dd-9001-6cd270c14fb9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 96).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'db25a5782f983ce6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63f0ef16-b8ed-4dd5-b3d1-63060ed917ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 96).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '55044dcade02d12a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c8f8267-8704-40c3-9122-15a9b40e8448', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 96).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '831037eac0b43600_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d58c1667-55b0-4b38-8fdd-6071919dad8f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 96).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "The RE must process every packet", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'df8ad4167f031e03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd0a25fe-c832-466f-9a3b-33960a224bbf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 96).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'f9e2ce688856fbaf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82103c5d-cc61-4619-8e0b-34030629136f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 96).', '[{"id": "A", "text": "configure", "is_correct": true}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "edit", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '5c7c574b4e7280e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35f7209b-044d-40a0-8792-c04918e916fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 96).', '[{"id": "A", "text": "show configuration", "is_correct": true}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b1e6e6c8e03cf4b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('740da866-597c-4cba-a491-eada6a1970fd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 96).', '[{"id": "A", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '98de1a0bbfc20132_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('375dacd2-f105-474d-babe-dc5a75d4da88', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 96).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "restore factory", "is_correct": false}, {"id": "D", "text": "load factory-default", "is_correct": true}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e9d24fcb1a987f3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcf0e6ba-3a31-47cc-9699-172cb0d243ba', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 96).', '[{"id": "A", "text": "set router-name R9", "is_correct": false}, {"id": "B", "text": "set system host-name R9", "is_correct": true}, {"id": "C", "text": "set system name R9", "is_correct": false}, {"id": "D", "text": "set hostname R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '3fcc4a67ef93229c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('376ff17c-d0c2-4024-ab12-575e8a9fc60d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 96).', '[{"id": "A", "text": "set user juniper password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set authentication user juniper password", "is_correct": false}, {"id": "D", "text": "set system login user juniper class super-user support plain-text-password", "is_correct": true}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'b8b061694e042756_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('773aa225-85dc-4b58-90e5-25fc9e218c4f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 96).', '[{"id": "A", "text": "set ip address 10.248.35.1/24 interface ge-0/0/1", "is_correct": false}, {"id": "B", "text": "configure interface ge-0/0/1 ip 10.248.35.1/24", "is_correct": false}, {"id": "C", "text": "set interface ge-0/0/1 ip address 10.248.35.1/24", "is_correct": false}, {"id": "D", "text": "set interfaces ge-0/0/1 unit 0 family inet address 10.248.35.1/24", "is_correct": true}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'aa961d863c2705c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85fc23a7-1727-41cf-ad62-f6fa8579c582', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 96).', '[{"id": "A", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '66eb5dca147b43f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02a58874-d3f0-4ec2-b53c-05e01895a411', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 96).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '776aaad880e6656e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('715c860b-c5bf-4c26-93c4-8fe2d5225d01', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 96).', '[{"id": "A", "text": "monitor interface ge-2/0/1", "is_correct": true}, {"id": "B", "text": "tail interface ge-2/0/1", "is_correct": false}, {"id": "C", "text": "watch interface ge-2/0/1", "is_correct": false}, {"id": "D", "text": "show interface ge-2/0/1 monitor", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '099c92df2af158e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34147de8-b750-4149-b76c-993a421f1777', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 96).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '90566d4d6cecd83f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8d799f6-e705-48e7-b6e3-d98338d9b57d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 96).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "D", "text": "Use the recovery CD provided by Juniper", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'a560fd2a7a16211c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db974e4e-57d4-4798-bec3-9e86306e04bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 96).', '[{"id": "A", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'd2b5120f3c271370_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fba663f-74fa-4035-a461-1bc4bd193080', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 96).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '8eaedb18b83be66c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6231d17-0d9d-4608-9753-5088bf7e069f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.13.213.0/24 via next-hop 10.195.143.254 on Junos (variant 96).', '[{"id": "A", "text": "set ip route 192.232.83.0 255.62.39.0 10.195.143.254", "is_correct": false}, {"id": "B", "text": "set routing-options static route 192.13.213.0/24 next-hop 10.195.143.254", "is_correct": true}, {"id": "C", "text": "set static route 192.13.213.0/24 gateway 10.195.143.254", "is_correct": false}, {"id": "D", "text": "set route 192.13.213.0/24 next-hop 10.195.143.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '6195c699bc03e7fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbe986ed-4783-4b83-97e0-f5bc25a63978', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 96).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A BGP peer group", "is_correct": false}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A collection of static routes", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'c6945916124bad02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f0e7b8a-aca5-4064-802a-6842f506234b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 96).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "C", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '53d8f53f84d391c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05961177-0f53-45ec-938a-8d8eb68fe1e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 96).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Input, output, and forward", "is_correct": false}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '79e24120be1072e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0299e896-3d34-48c3-af09-139a431eb78f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 96).', '[{"id": "A", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'a0c38f21c42bc46f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c4433ba-c8bb-43b4-b55c-a0223e0b3d6f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 97).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 7", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'b2b63b5e4f3b7333_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50e08fbf-6fee-4165-b3cd-98dad698b795', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 97).', '[{"id": "A", "text": "254", "is_correct": true}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'ea8c7a1cfd4d61ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fadd535-1a00-4237-b7d7-62c33e77ac9e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 97).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Load balancer", "is_correct": false}, {"id": "C", "text": "Switch", "is_correct": true}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '791375aed0a7c473_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9040941-3059-4041-aa12-daf668a2d6c2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 97).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "2 bytes", "is_correct": false}, {"id": "C", "text": "8 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '246d932f26e3a4da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b5c478b-f622-4264-b1b2-c0845c4625d0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 97).', '[{"id": "A", "text": "IP address to MAC address", "is_correct": true}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "MAC address to IP address", "is_correct": false}, {"id": "D", "text": "Hostname to IP address", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'a13f2054db81e225_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('350d0ec8-5ba5-4dcd-9d26-9cc1c78bb69a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 97).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "CPU and Memory", "is_correct": false}, {"id": "D", "text": "Control Processor and Line Card", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'a059ce7d7a88d7d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da2527a1-249a-4f49-955e-52727cd23852', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 97).', '[{"id": "A", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '6698f37fcd1632f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f10f2b44-7e7a-4f6c-b138-1f07913fd2f6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 97).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '9f45a2efd9c1a981_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57a56a9e-3d53-4382-a97d-a80dd879852d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 97).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "C", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "D", "text": "All transit traffic", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7b2a71e21738dc18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46a42f74-cbe6-40ac-b456-b92e913405c8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 97).', '[{"id": "A", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "B", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "C", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '1903dc93269de604_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6af4a765-0928-4be6-aa55-e11924f02d7b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 97).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "C", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '1811c68657edf88d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14b03981-5a09-4bbf-b469-0813c03bbbee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 97).', '[{"id": "A", "text": "setup", "is_correct": false}, {"id": "B", "text": "config", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f4fa4cb81eb8d257_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5b77414-a774-4677-ad33-8b8e0f697281', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 97).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "view configuration", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '71d136f4d4948940_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ab1b739-e7b9-4439-aea4-c8b41a4363ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 97).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Matches two files for differences", "is_correct": false}, {"id": "C", "text": "Compares two configurations", "is_correct": false}, {"id": "D", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '98f5d1c157053d94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90f67476-7464-40f8-8b1a-d60628b3ee44', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 97).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '4fdd694858a6da03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a64789de-4d4f-447a-93e6-45f0a06aecf0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 97).', '[{"id": "A", "text": "set system host-name R12", "is_correct": true}, {"id": "B", "text": "set router-name R12", "is_correct": false}, {"id": "C", "text": "set system name R12", "is_correct": false}, {"id": "D", "text": "set hostname R12", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'f10f1477c9397f39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86ceae90-7b80-4e59-9de4-88eeb4800f38', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 97).', '[{"id": "A", "text": "set user root password", "is_correct": false}, {"id": "B", "text": "create account bob class super-user", "is_correct": false}, {"id": "C", "text": "set system login user root class super-user config plain-text-password", "is_correct": true}, {"id": "D", "text": "set authentication user root password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'df396b0acdd865ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9776943-d055-4f26-af5c-5a9d74056977', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 97).', '[{"id": "A", "text": "configure interface ge-2/0/3 ip 10.235.148.1/24", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/0/3 unit 0 family inet address 10.235.148.1/24", "is_correct": true}, {"id": "C", "text": "set interface ge-2/0/3 ip address 10.235.148.1/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.235.148.1/24 interface ge-2/0/3", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, '43d1e30aaae8a362_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb53a132-2855-472a-bf62-d8945417ac63', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 97).', '[{"id": "A", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A collection of routing protocols", "is_correct": false}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '31385485fe3f75fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ceb52df0-a66c-40c0-9b81-88743b3d510f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 97).', '[{"id": "A", "text": "show interfaces terse", "is_correct": true}, {"id": "B", "text": "display interfaces", "is_correct": false}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "show interfaces detail", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, 'b36626b583b9806f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83cbdddd-920e-4535-ba2d-fd206914e27a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 97).', '[{"id": "A", "text": "tail interface et-0/1/3", "is_correct": false}, {"id": "B", "text": "show interface et-0/1/3 monitor", "is_correct": false}, {"id": "C", "text": "watch interface et-0/1/3", "is_correct": false}, {"id": "D", "text": "monitor interface et-0/1/3", "is_correct": true}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '476594410d5219f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15b6aa28-ea2d-40e9-baf8-05b069d463d5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 97).', '[{"id": "A", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "B", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "C", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '9480d53bed37b0d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b274cd2-2a14-49a9-bdba-719063c91267', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 97).', '[{"id": "A", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "B", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "C", "text": "Boot into single-user netadmin by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user netadmin to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '55de62597756a2b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('092c05ed-2523-4533-ae46-050b5da71652', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 97).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'c5169088f625ef15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95ffc3e0-4938-4c56-8bde-8e96e134075b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 97).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'a25f96009a72da6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('130a8dea-7c03-4324-bbfc-61d81c882ae4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.225.228.0/24 via next-hop 10.50.211.254 on Junos (variant 97).', '[{"id": "A", "text": "set routing-options static route 192.225.228.0/24 next-hop 10.50.211.254", "is_correct": true}, {"id": "B", "text": "set static route 192.225.228.0/24 gateway 10.50.211.254", "is_correct": false}, {"id": "C", "text": "set route 192.225.228.0/24 next-hop 10.50.211.254", "is_correct": false}, {"id": "D", "text": "set ip route 192.64.62.0 255.179.189.0 10.50.211.254", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '94532ac50cb0f795_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('099ef0d8-4c38-41fb-9c30-f9daaba32c02', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 97).', '[{"id": "A", "text": "A BGP peer group", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A collection of static routes", "is_correct": false}, {"id": "D", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '242fe90e5aa19897_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44dddd19-db4e-4fd7-9255-c4855be6a9e6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 97).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, 'bca1c0fba32efcf0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a45444d6-d10f-4982-bd92-2a5047f3d794', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 97).', '[{"id": "A", "text": "Input, output, and forward", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'bde510ca0c59d661_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9b00690-fe8c-4108-bd1f-fd7fb937d77a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 97).', '[{"id": "A", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "B", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "C", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'e7c176eb9b1aed7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87d72039-9f84-44e1-a486-55f6ea3f470a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 98).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 3", "is_correct": true}, {"id": "D", "text": "Layer 2", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, '12ed703a3be8cf2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c94adb3-6815-4338-9a0d-19572352895d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 98).', '[{"id": "A", "text": "256", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, '5de1d85db8f68f74_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49cb43fc-f848-47d0-bd97-8bb9c4fb9c9b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 98).', '[{"id": "A", "text": "Switch", "is_correct": true}, {"id": "B", "text": "Router", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Firewall", "is_correct": false}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'b5848807c0328728_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a63a0f8-de23-4a06-8905-1016d4c37fda', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 98).', '[{"id": "A", "text": "6 bytes", "is_correct": true}, {"id": "B", "text": "4 bytes", "is_correct": false}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "8 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '20c9c41adcd8aed2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed82b55e-7eca-4f45-8893-bfd1fe674b43', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 98).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to MAC address", "is_correct": true}, {"id": "D", "text": "IP address to port number", "is_correct": false}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '86e4bc43a2d6a383_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81e57c4b-9143-47e4-b41a-d61b8e5c1c3a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 98).', '[{"id": "A", "text": "CPU and Memory", "is_correct": false}, {"id": "B", "text": "Supervisor and Fabric", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, '06197d78970dfb52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bf35764-88d3-4cd7-ac06-31821919f5ac', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 98).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Management Ethernet interface", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '92383fc74473f3ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35f1ec0e-6db8-477c-84c6-dbd5b2f43949', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 98).', '[{"id": "A", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "B", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "C", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "D", "text": "In → PFE → RE → PFE → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, 'e6502836e442695d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4477ea75-3055-484e-97f0-8d041eaa18c7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 98).', '[{"id": "A", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '7c2bfc0af964aff8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cc89d87-e946-43d7-9894-697de2baec14', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 98).', '[{"id": "A", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "The RE must process every packet", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '710b5cfc9bcf989b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('257974e7-3f30-43d9-a58c-87dea476b33e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 98).', '[{"id": "A", "text": "Read mode and Write mode", "is_correct": false}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "D", "text": "Exec mode and Global mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '2e9e5f97b7bca88a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f45e698-a762-484e-b633-f008fafc6bd6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 98).', '[{"id": "A", "text": "edit", "is_correct": false}, {"id": "B", "text": "configure", "is_correct": true}, {"id": "C", "text": "config", "is_correct": false}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '1f697fc52e851905_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aae21e38-714b-446f-b13b-6ee105ee284d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 98).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "view configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '02c2542e0bb9c652_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2964ea30-e75d-4986-9725-292c027fc6f4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 98).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Matches two files for differences", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '41ff0e0b989fbb1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0758ae5-7138-4823-bd91-60722915518b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 98).', '[{"id": "A", "text": "load default", "is_correct": false}, {"id": "B", "text": "set factory-default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'c5ad28d20db30731_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e455d319-e64e-49d0-806d-c0f5f554a348', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 98).', '[{"id": "A", "text": "set system host-name R9", "is_correct": true}, {"id": "B", "text": "set hostname R9", "is_correct": false}, {"id": "C", "text": "set router-name R9", "is_correct": false}, {"id": "D", "text": "set system name R9", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'e019b5c9e8d4da91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21b4f043-b68f-472c-9f2b-1c26d164d622', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user support with an authentication method on Junos (variant 98).', '[{"id": "A", "text": "create account bob class super-user", "is_correct": false}, {"id": "B", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "C", "text": "set user monitor password", "is_correct": false}, {"id": "D", "text": "set authentication user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'a56b21af135141e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa045e4b-75fd-4a3d-a360-9ecd49fe1570', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 98).', '[{"id": "A", "text": "set ip address 10.198.176.1/24 interface ge-2/1/0", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/0 unit 0 family inet address 10.198.176.1/24", "is_correct": true}, {"id": "C", "text": "set interface ge-2/1/0 ip address 10.198.176.1/24", "is_correct": false}, {"id": "D", "text": "configure interface ge-2/1/0 ip 10.198.176.1/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'ebf8d1e96146e4ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7be43339-e0ca-4e32-a700-57b150087ebe', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 98).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A collection of routing protocols", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, 'c6b56152cd0b53ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08567184-73b5-45ff-af92-bf84b8afd936', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 98).', '[{"id": "A", "text": "show interfaces detail", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interface status", "is_correct": false}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '5ae58895a5e223e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb9cfa76-d7e9-4c2a-945e-f13b3466cf2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 98).', '[{"id": "A", "text": "monitor interface xe-2/0/1", "is_correct": true}, {"id": "B", "text": "watch interface xe-2/0/1", "is_correct": false}, {"id": "C", "text": "show interface xe-2/0/1 monitor", "is_correct": false}, {"id": "D", "text": "tail interface xe-2/0/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '2ed39215aa879f50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ea1fc7f-81a9-4211-8566-534c4f63d9ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 98).', '[{"id": "A", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "B", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "C", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '9a27b77c10c151af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c44fd6f6-3932-403c-ab33-fa5ad7c147a7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 98).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Press the reset button on the front panel", "is_correct": false}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '13b1138b7aef2f1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccfdde2a-e462-48fa-b24b-e1db0198a1a0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 98).', '[{"id": "A", "text": "They are identical in Junos", "is_correct": false}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "D", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '008df4fc6d055f75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f42e2ee4-5fe9-451e-9c03-17a917855121', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 98).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "The BGP LOCAL_PREF value", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'b89e4cfabed024a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6d55635-a9d6-4027-8267-2a1cba5a0fd6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.21.24.0/24 via next-hop 10.191.214.5 on Junos (variant 98).', '[{"id": "A", "text": "set static route 192.21.24.0/24 gateway 10.191.214.5", "is_correct": false}, {"id": "B", "text": "set route 192.21.24.0/24 next-hop 10.191.214.5", "is_correct": false}, {"id": "C", "text": "set ip route 192.15.62.0 255.209.245.0 10.191.214.5", "is_correct": false}, {"id": "D", "text": "set routing-options static route 192.21.24.0/24 next-hop 10.191.214.5", "is_correct": true}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '85fdbac4b6bd5822_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('100221c4-ad3e-43b3-9ba6-2f3ef65df3bb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 98).', '[{"id": "A", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "B", "text": "A collection of static routes", "is_correct": false}, {"id": "C", "text": "A BGP peer group", "is_correct": false}, {"id": "D", "text": "A single routing protocol configuration", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '4e274a734042def1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('688effc7-00b3-4b14-8d1c-01049228f320', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 98).', '[{"id": "A", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "B", "text": "They are functionally identical", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '05e052468da22b9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('740a8cac-04d8-4e14-b801-c8411d4de78a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 98).', '[{"id": "A", "text": "Name, protocol, and action", "is_correct": false}, {"id": "B", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "C", "text": "Source, destination, and port", "is_correct": false}, {"id": "D", "text": "Input, output, and forward", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '9371ff05958638b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c56a9a45-6eab-4cf9-812a-6387469f3306', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 98).', '[{"id": "A", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Checks the destination IP against the forwarding table", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '598767734e45c2f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbd90e34-992c-49a2-84fc-d11dd3b80fd6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 99).', '[{"id": "A", "text": "Layer 3", "is_correct": true}, {"id": "B", "text": "Layer 4", "is_correct": false}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 7", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'e11cbaf34e3ad6ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5ded227-2fbe-4706-b812-6542183a8a44', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 99).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "252", "is_correct": false}, {"id": "C", "text": "254", "is_correct": true}, {"id": "D", "text": "256", "is_correct": false}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'c3de8df67513da44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55d59d19-26d5-4423-aea2-a46fac324626', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 99).', '[{"id": "A", "text": "Load balancer", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Router", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, 'da0ba406e42d1dde_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3c82222-d59e-45a8-a74e-5f225f12afdd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 99).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, 'c3f8a30cfdd5b6ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('187703ae-e96b-4e79-b058-bd03cc387dd4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 99).', '[{"id": "A", "text": "MAC address to IP address", "is_correct": false}, {"id": "B", "text": "IP address to port number", "is_correct": false}, {"id": "C", "text": "Hostname to IP address", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, 'd7fa3d26e6a28404_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fc39790-649c-458d-acd4-f81baeaa4e94', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 99).', '[{"id": "A", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'eed825b4aed45ae2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bd2a8cb-4bfe-4a58-af31-dd5fa016f3bf', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 99).', '[{"id": "A", "text": "Management Ethernet interface", "is_correct": false}, {"id": "B", "text": "Control Board", "is_correct": false}, {"id": "C", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "D", "text": "Routing Engine (RE)", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '20be12eddf296369_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffe6c70c-8b4e-4ebb-803c-acc31bc88157', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 99).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}, {"id": "D", "text": "In → RE processes → PFE forwards → out", "is_correct": false}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '1c99e2e3579935b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27b1dfc6-599d-43c4-94db-0cf3d3a35c65', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 99).', '[{"id": "A", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "B", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}, {"id": "C", "text": "All transit traffic", "is_correct": false}, {"id": "D", "text": "Traffic between two hosts on the same subnet", "is_correct": false}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '11219b4c6c7a3d30_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2812b5fe-fb62-48c6-b615-4b05e09cf7e9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 99).', '[{"id": "A", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "B", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}, {"id": "C", "text": "The RE must process every packet", "is_correct": false}, {"id": "D", "text": "Only one routing protocol can run at a time", "is_correct": false}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, '64af65cedd1b0dc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a286906-b137-4dc4-bf5a-f08140152a09', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 99).', '[{"id": "A", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "B", "text": "User mode and Privileged mode", "is_correct": false}, {"id": "C", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "D", "text": "Read mode and Write mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '3f96003b4327f985_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d30dbd4-a1bd-4a47-94a0-288a3913d3a3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 99).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "setup", "is_correct": false}, {"id": "C", "text": "edit", "is_correct": false}, {"id": "D", "text": "configure", "is_correct": true}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, 'f24a6a53bf31bf15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c2f8b63-c768-4f0f-8a86-eea4e329cead', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 99).', '[{"id": "A", "text": "view configuration", "is_correct": false}, {"id": "B", "text": "show config", "is_correct": false}, {"id": "C", "text": "display configuration", "is_correct": false}, {"id": "D", "text": "show configuration", "is_correct": true}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'd3f53181959f8696_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8cd6958-9c9b-478e-b2f1-8536bcfff884', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 99).', '[{"id": "A", "text": "Matches two files for differences", "is_correct": false}, {"id": "B", "text": "Compares two configurations", "is_correct": false}, {"id": "C", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "D", "text": "Joins multiple command outputs", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '2a5b00e1bf60ca00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6a8bab3-780c-4b96-bf7f-74ef1d479cb7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 99).', '[{"id": "A", "text": "load factory-default", "is_correct": true}, {"id": "B", "text": "restore factory", "is_correct": false}, {"id": "C", "text": "load default", "is_correct": false}, {"id": "D", "text": "set factory-default", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '5495395a06190b47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('681ee300-4149-4243-8354-326bba635101', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 99).', '[{"id": "A", "text": "set router-name R10", "is_correct": false}, {"id": "B", "text": "set system name R10", "is_correct": false}, {"id": "C", "text": "set system host-name R10", "is_correct": true}, {"id": "D", "text": "set hostname R10", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, '8fe4a44c1723a3b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0a4e866-8012-4b80-9cd2-fe75c123da41', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user monitor with an authentication method on Junos (variant 99).', '[{"id": "A", "text": "set system login user juniper class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set user juniper password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set authentication user juniper password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '11c3dc706943c651_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c521a97-783a-4c08-918b-fb51407dd40a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 99).', '[{"id": "A", "text": "set interfaces xe-3/0/1 unit 0 family inet address 10.107.186.5/24", "is_correct": true}, {"id": "B", "text": "configure interface xe-3/0/1 ip 10.107.186.5/24", "is_correct": false}, {"id": "C", "text": "set interface xe-3/0/1 ip address 10.107.186.5/24", "is_correct": false}, {"id": "D", "text": "set ip address 10.107.186.5/24 interface xe-3/0/1", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'a9eed9353e253b8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92bb2d3e-9828-4431-b7bd-10c681061d3a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 99).', '[{"id": "A", "text": "A group of users with shared permissions", "is_correct": false}, {"id": "B", "text": "A collection of routing protocols", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '9a6b67fc18f6d88e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('599ae69f-ea4a-4cc2-b911-1cffab037a48', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 99).', '[{"id": "A", "text": "display interfaces", "is_correct": false}, {"id": "B", "text": "show interfaces terse", "is_correct": true}, {"id": "C", "text": "show interfaces detail", "is_correct": false}, {"id": "D", "text": "show interface status", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '7040964ff609ce48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94af5c2c-c94d-44b6-aa7f-b6ee6470a0da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 99).', '[{"id": "A", "text": "show interface et-0/1/1 monitor", "is_correct": false}, {"id": "B", "text": "tail interface et-0/1/1", "is_correct": false}, {"id": "C", "text": "monitor interface et-0/1/1", "is_correct": true}, {"id": "D", "text": "watch interface et-0/1/1", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '543c5f878df227a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7d7d4c2-b190-4398-9a20-6016346b4f0e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 99).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy to /boot, run system upgrade", "is_correct": false}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, 'db574b91238f3366_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de49c79e-5588-423a-997a-71fc9cd0430d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 99).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Boot into single-user engineer by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "C", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user engineer to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '811120046a6d6e2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37d65b85-b980-4ed3-82ad-9e15e28281e1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 99).', '[{"id": "A", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}, {"id": "B", "text": "They are identical in Junos", "is_correct": false}, {"id": "C", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "D", "text": "Forwarding table has more routes than routing table", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, 'd8700935ee0ff114_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('746db2ab-3bd7-44d1-a9c8-cae96d165880', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 99).', '[{"id": "A", "text": "An administrative field for route tagging", "is_correct": false}, {"id": "B", "text": "A routing metric like hop count", "is_correct": false}, {"id": "C", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "D", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'e496bd23e766cb6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1a57ef0-4d68-4cdf-bd4c-23abc6c9afb5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.164.208.0/24 via next-hop 10.7.146.1 on Junos (variant 99).', '[{"id": "A", "text": "set ip route 192.176.20.0 255.141.72.0 10.7.146.1", "is_correct": false}, {"id": "B", "text": "set route 192.164.208.0/24 next-hop 10.7.146.1", "is_correct": false}, {"id": "C", "text": "set routing-options static route 192.164.208.0/24 next-hop 10.7.146.1", "is_correct": true}, {"id": "D", "text": "set static route 192.164.208.0/24 gateway 10.7.146.1", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, '7564a09c5a88fafe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('793579c7-8dcb-4777-8769-a3990ec7df45', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 99).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "C", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, 'af253df6333a82f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d113e0ef-c921-4572-abba-904cfa0a7338', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 99).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '54483d130e98cb4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d62c6d4d-c02f-4c02-8d38-e0d61c825879', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 99).', '[{"id": "A", "text": "Source, destination, and port", "is_correct": false}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "D", "text": "Name, protocol, and action", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, 'aab6d158e40b9d68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b73cc90c-1c06-4ed7-88ad-628fb809b32f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 99).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}, {"id": "D", "text": "Validates the TTL value of incoming packets", "is_correct": false}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '475b1eea9a850ea1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca846725-edc0-4019-956c-4c52a917fa3d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'At which OSI model layer does IP routing occur (variant 100).', '[{"id": "A", "text": "Layer 7", "is_correct": false}, {"id": "B", "text": "Layer 3", "is_correct": true}, {"id": "C", "text": "Layer 2", "is_correct": false}, {"id": "D", "text": "Layer 4", "is_correct": false}]', 'IP routing occurs at Layer 3 (Network layer) of the OSI model. Routers make forwarding decisions based on IP destination addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Networking Fundamentals', 14.0, 'f34bdff4f55aa221_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44731289-140b-4246-9288-e048afef8638', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'How many host addresses are available in a /24 IPv4 subnet (variant 100).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "256", "is_correct": false}, {"id": "C", "text": "252", "is_correct": false}, {"id": "D", "text": "254", "is_correct": true}]', 'A /24 subnet has 256 total addresses minus 2 (network and broadcast) = 254 usable host addresses.', '{}', 'Networking Fundamentals', 14.0, 'dec4b954e587a318_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d837588-c3e9-4f45-b070-c4d8ff1eaa15', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which device operates primarily at Layer 2 of the OSI model (variant 100).', '[{"id": "A", "text": "Router", "is_correct": false}, {"id": "B", "text": "Firewall", "is_correct": false}, {"id": "C", "text": "Load balancer", "is_correct": false}, {"id": "D", "text": "Switch", "is_correct": true}]', 'Switches forward frames based on MAC addresses at Layer 2. Routers operate at Layer 3, forwarding packets based on IP addresses.', '{}', 'Networking Fundamentals', 14.0, '4c6aed73c2f50580_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59208aee-c1a3-48e4-842d-7ed7247c869f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What is the length of an Ethernet MAC address in bytes (variant 100).', '[{"id": "A", "text": "8 bytes", "is_correct": false}, {"id": "B", "text": "6 bytes", "is_correct": true}, {"id": "C", "text": "2 bytes", "is_correct": false}, {"id": "D", "text": "4 bytes", "is_correct": false}]', 'A MAC address is 48 bits (6 bytes) long, typically represented as 12 hexadecimal characters grouped in pairs.', '{}', 'Networking Fundamentals', 12.0, '68f621f95310c32c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b8a6e9a-9751-4e96-b757-1fa45f682e07', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does ARP resolve in an IPv4 network (variant 100).', '[{"id": "A", "text": "Hostname to IP address", "is_correct": false}, {"id": "B", "text": "MAC address to IP address", "is_correct": false}, {"id": "C", "text": "IP address to port number", "is_correct": false}, {"id": "D", "text": "IP address to MAC address", "is_correct": true}]', 'ARP (Address Resolution Protocol) resolves an IPv4 address to its corresponding MAC address on a local network segment.', '{}', 'Networking Fundamentals', 14.0, '3d0c43351ee7ca71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f276da8f-809c-41e9-87da-377e2287a714', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the two main architectural components of a Junos OS device (variant 100).', '[{"id": "A", "text": "Routing Engine (RE) and Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "CPU and Memory", "is_correct": false}, {"id": "C", "text": "Control Processor and Line Card", "is_correct": false}, {"id": "D", "text": "Supervisor and Fabric", "is_correct": false}]', 'Junos separates the control plane (Routing Engine) from the forwarding plane (Packet Forwarding Engine), providing high availability and stability.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 16.0, 'b97431d4e856e573_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a09b20a-8f21-4977-b786-bcb8af39a286', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which component of a Junos device is responsible for forwarding packets at high speed (variant 100).', '[{"id": "A", "text": "Packet Forwarding Engine (PFE)", "is_correct": true}, {"id": "B", "text": "Routing Engine (RE)", "is_correct": false}, {"id": "C", "text": "Control Board", "is_correct": false}, {"id": "D", "text": "Management Ethernet interface", "is_correct": false}]', 'The PFE handles all packet forwarding operations in hardware or high-speed ASICs. The RE handles routing protocols and control plane functions.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '0df2c1565c506bba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d6df96e-858f-4556-a2b2-95c529995457', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'How does transit traffic flow through a Junos device (variant 100).', '[{"id": "A", "text": "Transit traffic bypasses the device entirely", "is_correct": false}, {"id": "B", "text": "In → PFE → RE → PFE → out", "is_correct": false}, {"id": "C", "text": "In → RE processes → PFE forwards → out", "is_correct": false}, {"id": "D", "text": "In through an interface → PFE forwards → out through another interface", "is_correct": true}]', 'Transit traffic enters an interface, is processed by the PFE for forwarding decisions using the hardware forwarding table, and exits the appropriate egress interface without involving the RE.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '3a851a0e61eaddc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('838d3aaf-3e63-4f0d-99b0-f935fc2d022d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which type of traffic requires processing by the Routing Engine on a Junos device (variant 100).', '[{"id": "A", "text": "All transit traffic", "is_correct": false}, {"id": "B", "text": "Broadcast Ethernet frames", "is_correct": false}, {"id": "C", "text": "Traffic between two hosts on the same subnet", "is_correct": false}, {"id": "D", "text": "Exception traffic such as TTL expiry and ICMP messages", "is_correct": true}]', 'Exception traffic (e.g., packets with TTL=1, packets destined to the router''s own IP, ICMP messages) is punted from the PFE to the RE for processing.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 14.0, '95685371c94b501d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0e954e1-af19-4a38-94b8-b6753e453ce4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a key benefit of the separation of control and forwarding planes in Junos (variant 100).', '[{"id": "A", "text": "The RE must process every packet", "is_correct": false}, {"id": "B", "text": "Only one routing protocol can run at a time", "is_correct": false}, {"id": "C", "text": "Packet forwarding stops if the RE fails", "is_correct": false}, {"id": "D", "text": "A Routing Engine failure does not affect packet forwarding", "is_correct": true}]', 'Because the PFE maintains an independent forwarding table, even if the RE fails or restarts, the PFE continues forwarding packets using the existing forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/junos-overview/"}', 'Junos OS Fundamentals', 12.0, 'a1b1df88ab6ea0cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f86789b-3354-4622-a36a-bf8e80aa8097', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What are the two main modes of the Junos CLI (variant 100).', '[{"id": "A", "text": "Exec mode and Global mode", "is_correct": false}, {"id": "B", "text": "Operational mode and Configuration mode", "is_correct": true}, {"id": "C", "text": "Read mode and Write mode", "is_correct": false}, {"id": "D", "text": "User mode and Privileged mode", "is_correct": false}]', 'Junos CLI has two modes: operational mode (>) for monitoring and troubleshooting, and configuration mode (#) for making configuration changes.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, 'b062610fe003d556_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50cf79a8-eab3-4cba-936f-9d57a615bee5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command enters configuration mode in the Junos CLI (variant 100).', '[{"id": "A", "text": "config", "is_correct": false}, {"id": "B", "text": "edit", "is_correct": false}, {"id": "C", "text": "configure", "is_correct": true}, {"id": "D", "text": "setup", "is_correct": false}]', '''configure'' (or ''config'') enters configuration mode. The prompt changes from ''>'' to ''#'' indicating you are in configuration mode.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '013c800757c15f19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e3497aa-a0d3-41f0-8ea4-e616c00daee7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the current active configuration on a Junos device (variant 100).', '[{"id": "A", "text": "show config", "is_correct": false}, {"id": "B", "text": "show configuration", "is_correct": true}, {"id": "C", "text": "view configuration", "is_correct": false}, {"id": "D", "text": "display configuration", "is_correct": false}]', '''show configuration'' (or ''show config'') in operational mode displays the currently active configuration. In configuration mode, use ''show'' to see the candidate configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 14.0, '77f5897ecc070ff0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14a96d55-9566-446a-adc8-c97fead5076d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'What does the ''| match'' pipe command do in the Junos CLI (variant 100).', '[{"id": "A", "text": "Joins multiple command outputs", "is_correct": false}, {"id": "B", "text": "Filters command output to show only lines containing a specific string", "is_correct": true}, {"id": "C", "text": "Matches two files for differences", "is_correct": false}, {"id": "D", "text": "Compares two configurations", "is_correct": false}]', '''| match <pattern>'' filters the display output to show only lines containing the specified pattern, similar to ''grep'' in Unix.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'User Interfaces', 12.0, '5790c8f4bd1574e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13e2304a-3519-4983-8765-14f7d973e594', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command loads the factory default configuration on a Junos device (variant 100).', '[{"id": "A", "text": "set factory-default", "is_correct": false}, {"id": "B", "text": "load default", "is_correct": false}, {"id": "C", "text": "load factory-default", "is_correct": true}, {"id": "D", "text": "restore factory", "is_correct": false}]', '''load factory-default'' loads the factory configuration into candidate configuration. It must then be committed with ''commit'' to activate it.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'bcaae8358704856a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('580601d3-df8d-4039-9655-4a3cb048d412', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which configuration statement sets the hostname on a Junos device (variant 100).', '[{"id": "A", "text": "set system name R6", "is_correct": false}, {"id": "B", "text": "set system host-name R6", "is_correct": true}, {"id": "C", "text": "set router-name R6", "is_correct": false}, {"id": "D", "text": "set hostname R6", "is_correct": false}]', '''set system host-name <name>'' configures the device hostname. The hostname is displayed in the CLI prompt.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Basics', 14.0, 'b600cc9a0912edfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba4c3f18-7ecc-498c-b950-b86674310177', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which statement adds a user config with an authentication method on Junos (variant 100).', '[{"id": "A", "text": "set system login user monitor class super-user config plain-text-password", "is_correct": true}, {"id": "B", "text": "set authentication user monitor password", "is_correct": false}, {"id": "C", "text": "create account bob class super-user", "is_correct": false}, {"id": "D", "text": "set user monitor password", "is_correct": false}]', 'User accounts are configured under ''system login user <name>'' with a login class and authentication method (plain-text-password, ssh-rsa, etc.).', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '6f7a3c6838468a3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('962e8dcd-cc57-4e75-93dc-91f8c813b1da', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you assign an IP address to a Junos interface (variant 100).', '[{"id": "A", "text": "set interfaces et-0/1/1 unit 0 family inet address 10.121.28.254/24", "is_correct": true}, {"id": "B", "text": "set ip address 10.121.28.254/24 interface et-0/1/1", "is_correct": false}, {"id": "C", "text": "configure interface et-0/1/1 ip 10.121.28.254/24", "is_correct": false}, {"id": "D", "text": "set interface et-0/1/1 ip address 10.121.28.254/24", "is_correct": false}]', 'Junos configures IP addresses under the interface unit level using ''family inet address''. The syntax is: set interfaces <name> unit <n> family inet address <ip/prefix>.', '{"https://www.juniper.net/documentation/us/en/software/junos/interfaces/"}', 'Configuration Basics', 14.0, 'a063fc1a2d791469_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e20925c9-1700-4ef7-8054-bfe38c324ca6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a configuration group in Junos (variant 100).', '[{"id": "A", "text": "A collection of routing protocols", "is_correct": false}, {"id": "B", "text": "A set of interfaces bundled into a single logical interface", "is_correct": false}, {"id": "C", "text": "A set of configuration statements that can be applied to multiple interfaces or protocols", "is_correct": true}, {"id": "D", "text": "A group of users with shared permissions", "is_correct": false}]', 'Configuration groups (under ''groups'') define reusable configuration templates. They are applied using ''apply-groups'' and help reduce configuration repetition.', '{"https://www.juniper.net/documentation/us/en/software/junos/configuration/"}', 'Configuration Basics', 14.0, '7601c5559516fc4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0b62012-a20b-477e-a299-f8b9f1cceb70', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command displays the status and statistics of all interfaces on a Junos device (variant 100).', '[{"id": "A", "text": "show interface status", "is_correct": false}, {"id": "B", "text": "show interfaces detail", "is_correct": false}, {"id": "C", "text": "show interfaces terse", "is_correct": true}, {"id": "D", "text": "display interfaces", "is_correct": false}]', '''show interfaces terse'' provides a concise summary of all interfaces with their status (up/down) and IP addresses. ''show interfaces detail'' provides extensive statistics.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '3cdc070c327dd2a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b401b34-28c4-4906-8482-4f562108c3b1', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you monitor real-time interface traffic on a Junos device (variant 100).', '[{"id": "A", "text": "monitor interface xe-2/0/3", "is_correct": true}, {"id": "B", "text": "show interface xe-2/0/3 monitor", "is_correct": false}, {"id": "C", "text": "tail interface xe-2/0/3", "is_correct": false}, {"id": "D", "text": "watch interface xe-2/0/3", "is_correct": false}]', '''monitor interface <name>'' displays real-time interface traffic statistics, refreshing automatically every second until interrupted.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Operational Monitoring', 14.0, '58a5de81f9871e51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2edcc66d-9de5-4ff0-ab16-3ecbacfa8a5e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct procedure to upgrade Junos OS (variant 100).', '[{"id": "A", "text": "SCP to /var/home, run install junos", "is_correct": false}, {"id": "B", "text": "Copy the new image to /var/tmp, request system software add <image>, reboot", "is_correct": true}, {"id": "C", "text": "Download to /config, run upgrade junos", "is_correct": false}, {"id": "D", "text": "Copy to /boot, run system upgrade", "is_correct": false}]', 'The Junos upgrade process: copy the .tgz image to /var/tmp, run ''request system software add <image>'', then reboot. The system boots from the new image or falls back to the previous one.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '5caaa895c92ac545_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('780bcbae-afb1-42f9-bf7d-d5d9ba4887b6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How is the root password recovered on a Junos device (variant 100).', '[{"id": "A", "text": "Use the recovery CD provided by Juniper", "is_correct": false}, {"id": "B", "text": "Contact JTAC to generate a recovery key", "is_correct": false}, {"id": "C", "text": "Boot into single-user operator by interrupting the boot process and selecting the recovery option", "is_correct": true}, {"id": "D", "text": "Press the reset button on the front panel", "is_correct": false}]', 'Root password recovery: power cycle the device, interrupt the boot process with a spacebar press, select the recovery option (option 4 in the boot menu), and enter single-user operator to reset the password.', '{"https://www.juniper.net/documentation/us/en/software/junos/software-management/"}', 'Operational Monitoring', 14.0, '964943a7d4b920b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce57b454-e8a2-4825-b74d-bff4f4cca788', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between the routing table and the forwarding table in Junos (variant 100).', '[{"id": "A", "text": "Routing table contains all learned routes; forwarding table contains only active best routes", "is_correct": true}, {"id": "B", "text": "Forwarding table has more routes than routing table", "is_correct": false}, {"id": "C", "text": "They are identical in Junos", "is_correct": false}, {"id": "D", "text": "Routing table is in the PFE; forwarding table is in the RE", "is_correct": false}]', 'The routing table (inet.0) stores all routes learned from all sources. The forwarding table contains only the active best routes selected by the RE and is downloaded to the PFE for actual packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 16.0, '6461ab3fb448d94e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9f2f649-f2a3-44ed-b488-06e62ff3d049', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is route preference in Junos (variant 100).', '[{"id": "A", "text": "The BGP LOCAL_PREF value", "is_correct": false}, {"id": "B", "text": "A value used to select the best route among routes from different protocols to the same destination", "is_correct": true}, {"id": "C", "text": "A routing metric like hop count", "is_correct": false}, {"id": "D", "text": "An administrative field for route tagging", "is_correct": false}]', 'Route preference (administrative distance) determines which route is preferred when multiple routing protocols provide routes to the same destination. Lower preference values are preferred.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f71b4e1f5c732dbc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('164b7d8d-a0d4-4ce7-8713-211a4d509a94', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command configures a static route to 192.166.18.0/24 via next-hop 10.23.103.5 on Junos (variant 100).', '[{"id": "A", "text": "set routing-options static route 192.166.18.0/24 next-hop 10.23.103.5", "is_correct": true}, {"id": "B", "text": "set route 192.166.18.0/24 next-hop 10.23.103.5", "is_correct": false}, {"id": "C", "text": "set static route 192.166.18.0/24 gateway 10.23.103.5", "is_correct": false}, {"id": "D", "text": "set ip route 192.3.12.0 255.131.202.0 10.23.103.5", "is_correct": false}]', 'Static routes in Junos are configured under ''routing-options static route <prefix> next-hop <ip>''. A qualifying metric can also be specified.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 14.0, 'f7060691bf48ef66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('977f1c54-0798-4857-999f-79d56f5a1933', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is a routing instance in Junos (variant 100).', '[{"id": "A", "text": "A collection of static routes", "is_correct": false}, {"id": "B", "text": "A single routing protocol configuration", "is_correct": false}, {"id": "C", "text": "A virtual routing table with its own set of interfaces and routing protocols", "is_correct": true}, {"id": "D", "text": "A BGP peer group", "is_correct": false}]', 'A routing instance is an independent virtual router with its own routing table, interfaces, and routing protocols. Common types include virtual-router, vrf, forwarding, and l2vpn.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-instances/"}', 'Routing Fundamentals', 14.0, '1acd3832c28d9acd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1aab5fb9-8d29-4047-b5f8-c42f80096175', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'In Junos routing policy, what is the difference between import and export policies (variant 100).', '[{"id": "A", "text": "Import policies affect routes entering the routing table; export policies affect routes leaving the routing table", "is_correct": true}, {"id": "B", "text": "Import policies affect outbound traffic; export policies affect inbound traffic", "is_correct": false}, {"id": "C", "text": "Export policies are only for BGP; import policies are for OSPF", "is_correct": false}, {"id": "D", "text": "They are functionally identical", "is_correct": false}]', 'Import policies filter routes as they enter the routing table from a protocol or interface. Export policies filter routes as they are advertised to a protocol neighbor or interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '4c87f96f6a6d77cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94f9fa23-b71e-441a-8c78-a3dae2b044c6', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What are the three main components of a firewall filter term in Junos (variant 100).', '[{"id": "A", "text": "From (match conditions), then (actions), and optionally a count", "is_correct": true}, {"id": "B", "text": "Input, output, and forward", "is_correct": false}, {"id": "C", "text": "Name, protocol, and action", "is_correct": false}, {"id": "D", "text": "Source, destination, and port", "is_correct": false}]', 'A firewall filter term consists of ''from'' (match conditions like source/destination IP, protocol, port), ''then'' (actions like accept, discard, reject), and optionally logging or counting.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '865797e1b1fbe4f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1b215e1-49fd-4cf5-9259-9d49d0fb15f9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What does Unicast Reverse-Path-Forwarding (RPF) check on a Junos device (variant 100).', '[{"id": "A", "text": "Checks the destination IP against the forwarding table", "is_correct": false}, {"id": "B", "text": "Verifies the checksum of the IP header", "is_correct": false}, {"id": "C", "text": "Validates the TTL value of incoming packets", "is_correct": false}, {"id": "D", "text": "Verifies that the source IP of an incoming packet is reachable via the receiving interface''s routing table", "is_correct": true}]', 'Unicast RPF checks if the source address of an incoming packet is reachable through the interface on which the packet arrived. If not, the packet is dropped, helping prevent IP spoofing.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filters', 14.0, '4640d1defbcc3700_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3499ab9b-58ea-4986-9409-86cf6b42838a', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos?', '[{"id": "A", "text": "0 through 15", "is_correct": false}, {"id": "B", "text": "1 through 1000", "is_correct": false}, {"id": "C", "text": "16 through 1023", "is_correct": true}, {"id": "D", "text": "1024 through 64520", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, '90fc81ed06f61ca2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aadbb6ee-225b-4e82-941a-f3ba8218af83', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos?', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show rsvp lsp", "is_correct": false}, {"id": "C", "text": "show mpls path", "is_correct": false}, {"id": "D", "text": "show ldp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '6c93b7ee3fc9e54f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7afbb562-5826-48e6-877b-6aa40a7b29b7', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0)?', '[{"id": "A", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "B", "text": "It is used for OAM operations", "is_correct": false}, {"id": "C", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "D", "text": "The penultimate hop pops the label", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, 'b61849ce62111999_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b55cb9c-2934-451d-871f-3eac96e043c4', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP?', '[{"id": "A", "text": "ResvTear", "is_correct": false}, {"id": "B", "text": "PathTear", "is_correct": true}, {"id": "C", "text": "PathErr", "is_correct": false}, {"id": "D", "text": "ResvErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress.', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, '61118f65cb07c9a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc7201f4-53c0-48c0-9307-4b65c0a06e39', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP?', '[{"id": "A", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "B", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "C", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}, {"id": "D", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, '83f23f138bf7441d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d77e4060-a9eb-4ab5-b433-f03a7337cc49', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 2).', '[{"id": "A", "text": "0 through 15", "is_correct": false}, {"id": "B", "text": "1 through 1000", "is_correct": false}, {"id": "C", "text": "16 through 1023", "is_correct": true}, {"id": "D", "text": "1024 through 64513", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, 'f9e965bc63f7b74c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb98d63b-8a5a-4451-a844-bc1958e319fe', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 2).', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show ldp lsp", "is_correct": false}, {"id": "C", "text": "show mpls path", "is_correct": false}, {"id": "D", "text": "show rsvp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, 'f274ab30697164c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6d4ac15-29d5-4c29-9668-c1bb8fdd4de7', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0) (variant 2).', '[{"id": "A", "text": "It is used for OAM operations", "is_correct": false}, {"id": "B", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "C", "text": "The penultimate hop pops the label", "is_correct": false}, {"id": "D", "text": "It indicates an IPv6 payload", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, '380b8b25584903e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f7d8a1b-62e9-4ad4-9fa1-cf86b23031b6', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP (variant 2).', '[{"id": "A", "text": "ResvErr", "is_correct": false}, {"id": "B", "text": "PathErr", "is_correct": false}, {"id": "C", "text": "PathTear", "is_correct": true}, {"id": "D", "text": "ResvTear", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress.', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, '24461f87ac7cf73a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfda996d-d32d-48d0-9911-eb5ea0e3c476', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP (variant 2).', '[{"id": "A", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "B", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}, {"id": "C", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "D", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, '14f28d0c07214ed6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33aebbf7-d0bc-4ba8-b258-541f0d489126', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 3).', '[{"id": "A", "text": "0 through 15", "is_correct": false}, {"id": "B", "text": "1024 through 64800", "is_correct": false}, {"id": "C", "text": "16 through 1023", "is_correct": true}, {"id": "D", "text": "1 through 1000", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, 'a7bb8dadec005aba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('366d9edb-2125-490e-9028-c9830f2d90e1', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 3).', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show mpls path", "is_correct": false}, {"id": "C", "text": "show ldp lsp", "is_correct": false}, {"id": "D", "text": "show rsvp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, 'a0356258d879c6e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b406489e-437c-4526-a76f-a5714f247d2a', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0) (variant 3).', '[{"id": "A", "text": "It is used for OAM operations", "is_correct": false}, {"id": "B", "text": "The penultimate hop pops the label", "is_correct": false}, {"id": "C", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "D", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, '7ee32388713e8133_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdfe8388-02f1-42eb-b524-eb113149b75f', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP (variant 3).', '[{"id": "A", "text": "PathTear", "is_correct": true}, {"id": "B", "text": "ResvTear", "is_correct": false}, {"id": "C", "text": "ResvErr", "is_correct": false}, {"id": "D", "text": "PathErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress.', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, '03d3f395023a7150_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc6b62de-2d55-4bfe-a950-b94fb004b203', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP (variant 3).', '[{"id": "A", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "B", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "C", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}, {"id": "D", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, 'c84bff1a7ab5527c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbf966b8-95db-41e2-80fe-4c671079254f', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 4).', '[{"id": "A", "text": "1024 through 64800", "is_correct": false}, {"id": "B", "text": "1 through 1000", "is_correct": false}, {"id": "C", "text": "16 through 1023", "is_correct": true}, {"id": "D", "text": "0 through 15", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, '9d3a9bc74774d0e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('592ec0b3-cabc-4293-a14d-2a1e4ddb02da', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 4).', '[{"id": "A", "text": "show mpls path", "is_correct": false}, {"id": "B", "text": "show rsvp lsp", "is_correct": false}, {"id": "C", "text": "show ldp lsp", "is_correct": false}, {"id": "D", "text": "show mpls lsp", "is_correct": true}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '7e457705e5cbae63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2c95eb5-ee7f-4843-8352-a8a3f821552b', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0) (variant 4).', '[{"id": "A", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "B", "text": "It is used for OAM operations", "is_correct": false}, {"id": "C", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "D", "text": "The penultimate hop pops the label", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, 'e2040f5f824d0566_gen_v4', true) ON CONFLICT (id) DO NOTHING;
