INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('321b43ab-efd4-4913-bf82-30b7b30583e5', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP (variant 20).', '[{"id": "A", "text": "ResvErr", "is_correct": false}, {"id": "B", "text": "ResvTear", "is_correct": false}, {"id": "C", "text": "PathTear", "is_correct": true}, {"id": "D", "text": "PathErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress.', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, '95fba271f76bec9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a753cda-50a5-462d-8a81-d6ecedbd70a4', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP (variant 20).', '[{"id": "A", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "B", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "C", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}, {"id": "D", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, 'c5e6350717959b95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4caa4879-8afe-43ce-831e-2e710ce6b555', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 21).', '[{"id": "A", "text": "1024 through 64600", "is_correct": false}, {"id": "B", "text": "0 through 15", "is_correct": false}, {"id": "C", "text": "1 through 1000", "is_correct": false}, {"id": "D", "text": "16 through 1023", "is_correct": true}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, '78423e509fa1a0c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('145d158c-59c3-4292-ae5b-b7afcc5f436c', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 21).', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show rsvp lsp", "is_correct": false}, {"id": "C", "text": "show mpls path", "is_correct": false}, {"id": "D", "text": "show ldp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '0eeaddb062f799ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
