INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fafdc2db-c224-4dc2-8e1c-587544a3330e', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 50).', '[{"id": "A", "text": "1 through 1000", "is_correct": false}, {"id": "B", "text": "1024 through 65500", "is_correct": false}, {"id": "C", "text": "0 through 15", "is_correct": false}, {"id": "D", "text": "16 through 1023", "is_correct": true}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, 'f89e39b4173225ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cccd269a-43d9-4668-854e-fd4594cc3df2', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 50).', '[{"id": "A", "text": "show mpls path", "is_correct": false}, {"id": "B", "text": "show mpls lsp", "is_correct": true}, {"id": "C", "text": "show rsvp lsp", "is_correct": false}, {"id": "D", "text": "show ldp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '6539d1f5afe914bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2eee97bd-729e-4f91-9fe3-d5184addd001', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0) (variant 50).', '[{"id": "A", "text": "The penultimate hop pops the label", "is_correct": false}, {"id": "B", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "C", "text": "It is used for OAM operations", "is_correct": false}, {"id": "D", "text": "It indicates an IPv6 payload", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, '5b9e49828dfd522f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
