INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a372b87-5168-42e8-a431-43c21869dd2b', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX (variant 12).', '[{"id": "A", "text": "A VLAN segment for guest networks", "is_correct": false}, {"id": "B", "text": "A routing instance for security traffic", "is_correct": false}, {"id": "C", "text": "A physical security domain on the device", "is_correct": false}, {"id": "D", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, '89c850da90f3b9f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1bd848c-031b-4eb5-bfab-17703f4b17f2', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 12).', '[{"id": "A", "text": "set services nat pool POOL1 address 192.39.229.227", "is_correct": false}, {"id": "B", "text": "set nat source pool POOL1 range 192.39.229.227", "is_correct": false}, {"id": "C", "text": "set security nat source pool POOL1 address 192.68.225.35/32", "is_correct": true}, {"id": "D", "text": "set security source-nat pool POOL1 192.39.229.227", "is_correct": false}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, '2105bbddb8c903fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
