INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bb5497f-fddb-4506-bd17-63e900ec7dee', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which IPsec mode encrypts the entire IP packet, including the original header (variant 21).', '[{"id": "A", "text": "AH mode", "is_correct": false}, {"id": "B", "text": "Transport mode", "is_correct": false}, {"id": "C", "text": "Tunnel mode", "is_correct": true}, {"id": "D", "text": "ESP mode", "is_correct": false}]', 'Tunnel mode encrypts the entire original IP packet and adds a new IP header. Transport mode only encrypts the payload.', '{"https://www.juniper.net/documentation/us/en/software/junos/ipsec/"}', 'IPsec VPN', 14.0, 'db2d941b5cb97702_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13ae282f-45fb-4b18-b934-a479d70af80b', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX (variant 21).', '[{"id": "A", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}, {"id": "B", "text": "A routing instance for security traffic", "is_correct": false}, {"id": "C", "text": "A VLAN segment for guest networks", "is_correct": false}, {"id": "D", "text": "A physical security domain on the device", "is_correct": false}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, '5d1c39cf66d597c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da1e85fb-74af-4288-adb5-802f1c58e272', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 21).', '[{"id": "A", "text": "set security source-nat pool POOL1 192.67.58.77", "is_correct": false}, {"id": "B", "text": "set services nat pool POOL1 address 192.67.58.77", "is_correct": false}, {"id": "C", "text": "set nat source pool POOL1 range 192.67.58.77", "is_correct": false}, {"id": "D", "text": "set security nat source pool POOL1 address 192.212.174.154/32", "is_correct": true}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, '7220da272351de6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
