INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d184c8cd-9ae0-4140-b53e-b77ea3e24a9d', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 25).', '[{"id": "A", "text": "set services nat pool POOL1 address 192.222.6.82", "is_correct": false}, {"id": "B", "text": "set nat source pool POOL1 range 192.222.6.82", "is_correct": false}, {"id": "C", "text": "set security source-nat pool POOL1 192.222.6.82", "is_correct": false}, {"id": "D", "text": "set security nat source pool POOL1 address 192.137.131.10/32", "is_correct": true}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, '937156b8750afe05_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17041e35-4dd1-412a-bc32-4a084e67f830', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies (variant 26).', '[{"id": "A", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "B", "text": "Simple packet filter", "is_correct": false}, {"id": "C", "text": "Application Firewall (AppFW)", "is_correct": true}, {"id": "D", "text": "MAC-based filtering", "is_correct": false}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, '955bfada1ea7a94d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8288503b-808f-4618-9853-643a5e1432a3', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is the default action for a Junos security policy if no match is found (variant 26).', '[{"id": "A", "text": "Permit (all traffic is allowed)", "is_correct": false}, {"id": "B", "text": "Deny (all traffic not matching a policy is dropped)", "is_correct": true}, {"id": "C", "text": "Log and permit", "is_correct": false}, {"id": "D", "text": "Reject with ICMP unreachable", "is_correct": false}]', 'Junos uses an implicit deny-all policy. Traffic not matching any security policy is silently dropped. A ''default-permit'' policy can be explicitly configured.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policies', 14.0, '8a9d413864228159_gen_v4', true) ON CONFLICT (id) DO NOTHING;
