INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c06c5b9b-f0b4-46f9-b353-7946feaebacf', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 47).', '[{"id": "A", "text": "set nat source pool POOL1 range 192.168.213.80", "is_correct": false}, {"id": "B", "text": "set security nat source pool POOL1 address 192.121.192.191/32", "is_correct": true}, {"id": "C", "text": "set security source-nat pool POOL1 192.168.213.80", "is_correct": false}, {"id": "D", "text": "set services nat pool POOL1 address 192.168.213.80", "is_correct": false}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, 'bcfc5c2f268976a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43648107-73cc-4d55-b9c5-af53b65e6096', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies (variant 48).', '[{"id": "A", "text": "Application Firewall (AppFW)", "is_correct": true}, {"id": "B", "text": "Simple packet filter", "is_correct": false}, {"id": "C", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "D", "text": "MAC-based filtering", "is_correct": false}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, 'f1e4a5d6a59a1fe0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e3305a3-ecb1-4e96-af88-5146d2809446', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is the default action for a Junos security policy if no match is found (variant 48).', '[{"id": "A", "text": "Reject with ICMP unreachable", "is_correct": false}, {"id": "B", "text": "Log and permit", "is_correct": false}, {"id": "C", "text": "Permit (all traffic is allowed)", "is_correct": false}, {"id": "D", "text": "Deny (all traffic not matching a policy is dropped)", "is_correct": true}]', 'Junos uses an implicit deny-all policy. Traffic not matching any security policy is silently dropped. A ''default-permit'' policy can be explicitly configured.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policies', 14.0, '2d9ea7b7181edf86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
