INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad8e0394-8de4-44e9-a2d0-9bb9c29cfae6', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX (variant 56).', '[{"id": "A", "text": "A VLAN segment for guest networks", "is_correct": false}, {"id": "B", "text": "A routing instance for security traffic", "is_correct": false}, {"id": "C", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}, {"id": "D", "text": "A physical security domain on the device", "is_correct": false}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, 'eed2386c5eac3b81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9299e59-4842-4ffb-99cf-b504f1e587f8', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 56).', '[{"id": "A", "text": "set nat source pool POOL1 range 192.134.208.29", "is_correct": false}, {"id": "B", "text": "set services nat pool POOL1 address 192.134.208.29", "is_correct": false}, {"id": "C", "text": "set security source-nat pool POOL1 192.134.208.29", "is_correct": false}, {"id": "D", "text": "set security nat source pool POOL1 address 192.207.201.207/32", "is_correct": true}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, '4238054dce588cb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfe1cee5-51ef-4888-b324-8f498a97aab2', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies (variant 57).', '[{"id": "A", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "B", "text": "MAC-based filtering", "is_correct": false}, {"id": "C", "text": "Simple packet filter", "is_correct": false}, {"id": "D", "text": "Application Firewall (AppFW)", "is_correct": true}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, '074c0ce50283681a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
