INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e65fdb85-73a4-4277-a73e-69fc53190503', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 69).', '[{"id": "A", "text": "set nat source pool POOL1 range 192.161.234.221", "is_correct": false}, {"id": "B", "text": "set security source-nat pool POOL1 192.161.234.221", "is_correct": false}, {"id": "C", "text": "set security nat source pool POOL1 address 192.188.56.44/32", "is_correct": true}, {"id": "D", "text": "set services nat pool POOL1 address 192.161.234.221", "is_correct": false}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, '5dfd2592a204013a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6054c0d0-2f6e-4286-a131-e7b24f7b71b4', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies (variant 70).', '[{"id": "A", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "B", "text": "MAC-based filtering", "is_correct": false}, {"id": "C", "text": "Application Firewall (AppFW)", "is_correct": true}, {"id": "D", "text": "Simple packet filter", "is_correct": false}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, 'c2b69d78f45b47cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f3a4030-d60f-430a-ba9e-6ad8c1a37f93', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is the default action for a Junos security policy if no match is found (variant 70).', '[{"id": "A", "text": "Permit (all traffic is allowed)", "is_correct": false}, {"id": "B", "text": "Deny (all traffic not matching a policy is dropped)", "is_correct": true}, {"id": "C", "text": "Log and permit", "is_correct": false}, {"id": "D", "text": "Reject with ICMP unreachable", "is_correct": false}]', 'Junos uses an implicit deny-all policy. Traffic not matching any security policy is silently dropped. A ''default-permit'' policy can be explicitly configured.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policies', 14.0, '1fea1f543679f4cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
