INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70e93b9d-6743-4dbf-a00a-a7690f31ae8c', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is the default action for a Junos security policy if no match is found (variant 74).', '[{"id": "A", "text": "Log and permit", "is_correct": false}, {"id": "B", "text": "Deny (all traffic not matching a policy is dropped)", "is_correct": true}, {"id": "C", "text": "Permit (all traffic is allowed)", "is_correct": false}, {"id": "D", "text": "Reject with ICMP unreachable", "is_correct": false}]', 'Junos uses an implicit deny-all policy. Traffic not matching any security policy is silently dropped. A ''default-permit'' policy can be explicitly configured.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policies', 14.0, '4ed5c9f7624767ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d889d414-3227-4f82-b2ca-58352c771d58', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which IPsec mode encrypts the entire IP packet, including the original header (variant 74).', '[{"id": "A", "text": "Tunnel mode", "is_correct": true}, {"id": "B", "text": "ESP mode", "is_correct": false}, {"id": "C", "text": "Transport mode", "is_correct": false}, {"id": "D", "text": "AH mode", "is_correct": false}]', 'Tunnel mode encrypts the entire original IP packet and adds a new IP header. Transport mode only encrypts the payload.', '{"https://www.juniper.net/documentation/us/en/software/junos/ipsec/"}', 'IPsec VPN', 14.0, '40244701ba662c79_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('710b9865-50fd-4086-8501-2ffefd86e7e3', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX (variant 74).', '[{"id": "A", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}, {"id": "B", "text": "A physical security domain on the device", "is_correct": false}, {"id": "C", "text": "A routing instance for security traffic", "is_correct": false}, {"id": "D", "text": "A VLAN segment for guest networks", "is_correct": false}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, 'bd8186427ac35c71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
