INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8e04cb1-9827-41dd-a597-363da2793674', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX (variant 78).', '[{"id": "A", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}, {"id": "B", "text": "A physical security domain on the device", "is_correct": false}, {"id": "C", "text": "A VLAN segment for guest networks", "is_correct": false}, {"id": "D", "text": "A routing instance for security traffic", "is_correct": false}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, 'a425177c836f34e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c00b72d-ac9e-46d0-a0b8-9124faec82fa', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 78).', '[{"id": "A", "text": "set services nat pool POOL1 address 192.7.55.30", "is_correct": false}, {"id": "B", "text": "set nat source pool POOL1 range 192.7.55.30", "is_correct": false}, {"id": "C", "text": "set security nat source pool POOL1 address 192.17.143.215/32", "is_correct": true}, {"id": "D", "text": "set security source-nat pool POOL1 192.7.55.30", "is_correct": false}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, 'f4c09ca3f92d4bd8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7700b714-ae3b-4124-9344-6b391bffab9d', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies (variant 79).', '[{"id": "A", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "B", "text": "Application Firewall (AppFW)", "is_correct": true}, {"id": "C", "text": "Simple packet filter", "is_correct": false}, {"id": "D", "text": "MAC-based filtering", "is_correct": false}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, '76f44cb0b6d814df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
