INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ce7a44b-500e-4388-b899-94a8962f59ac', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 80).', '[{"id": "A", "text": "set security source-nat pool POOL1 192.45.172.93", "is_correct": false}, {"id": "B", "text": "set services nat pool POOL1 address 192.45.172.93", "is_correct": false}, {"id": "C", "text": "set security nat source pool POOL1 address 192.122.210.212/32", "is_correct": true}, {"id": "D", "text": "set nat source pool POOL1 range 192.45.172.93", "is_correct": false}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses.', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, 'ebfbe1ad15f1f269_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1eefceb1-c34e-45cc-a434-bb5ab289d880', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'Which encapsulation technology is commonly used for overlay networks in data center fabrics?', '[{"id": "A", "text": "GRE", "is_correct": false}, {"id": "B", "text": "MPLS", "is_correct": false}, {"id": "C", "text": "VXLAN", "is_correct": true}, {"id": "D", "text": "IP-IP", "is_correct": false}]', 'VXLAN (Virtual Extensible LAN) is the most common overlay encapsulation in modern DC fabrics. It uses UDP encapsulation (port 4789) and supports up to 16M segments.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'Data Center Overlays', 14.0, '39e8e702187bdca7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7832772f-635b-49ff-ae92-ad7f9e65d6aa', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'In Juniper EVPN-VXLAN, what is the role of the VTEP?', '[{"id": "A", "text": "VXLAN Tunnel End Point - encapsulates/decapsulates VXLAN traffic", "is_correct": true}, {"id": "B", "text": "VXLAN Traffic Engineering Path", "is_correct": false}, {"id": "C", "text": "Virtual Tenant End Point - manages tenant routing", "is_correct": false}, {"id": "D", "text": "Virtual Topology Entry Point", "is_correct": false}]', 'VTEP is the device that performs VXLAN encapsulation (adding UDP+VXLAN header) and decapsulation. Leaf switches typically act as VTEPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN', 14.0, 'b137ff086f5bbb56_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60fd31a7-9bcd-4b4e-8bbc-65a24ebf4002', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'What is a QFX6 Virtual Chassis Fabric (VCF)?', '[{"id": "A", "text": "A virtual router instance", "is_correct": false}, {"id": "B", "text": "An MX series virtual router", "is_correct": false}, {"id": "C", "text": "Multiple QFX switches operating as a single logical switch", "is_correct": true}, {"id": "D", "text": "A physical chassis with multiple line cards", "is_correct": false}]', 'VCF allows multiple QFX switches to be interconnected via VCP (Virtual Chassis Ports) to form a single logical switch with unified management.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis', 14.0, '92b253b9d3bcf1b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3631436-4999-4c93-b8ac-4a076dd29b66', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 1, 'remember', 'What is the spine-leaf topology commonly used in modern data centers?', '[{"id": "A", "text": "A three-tier topology with core, aggregation, and access layers", "is_correct": false}, {"id": "B", "text": "A two-tier topology where leaf switches connect to all spine switches in a full mesh", "is_correct": true}, {"id": "C", "text": "A ring topology connecting all switches", "is_correct": false}, {"id": "D", "text": "A bus topology with a single backbone", "is_correct": false}]', 'Spine-leaf (clos) topology provides predictable latency by ensuring every leaf connects to every spine with equal hop count.', '{"https://www.juniper.net/documentation/us/en/software/junos/data-center/"}', 'Data Center Architecture', 12.0, '31591841981ac568_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f8db803-972d-44a2-b500-d183db65459d', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'Which encapsulation technology is commonly used for overlay networks in data center fabrics (variant 2).', '[{"id": "A", "text": "GRE", "is_correct": false}, {"id": "B", "text": "MPLS", "is_correct": false}, {"id": "C", "text": "VXLAN", "is_correct": true}, {"id": "D", "text": "IP-IP", "is_correct": false}]', 'VXLAN (Virtual Extensible LAN) is the most common overlay encapsulation in modern DC fabrics. It uses UDP encapsulation (port 4789) and supports up to 16M segments.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'Data Center Overlays', 14.0, '05b290b6a329be7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9fa59da-6b39-4a50-b973-45c1ce555afa', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'In Juniper EVPN-VXLAN, what is the role of the VTEP (variant 2).', '[{"id": "A", "text": "VXLAN Tunnel End Point - encapsulates/decapsulates VXLAN traffic", "is_correct": true}, {"id": "B", "text": "Virtual Topology Entry Point", "is_correct": false}, {"id": "C", "text": "Virtual Tenant End Point - manages tenant routing", "is_correct": false}, {"id": "D", "text": "VXLAN Traffic Engineering Path", "is_correct": false}]', 'VTEP is the device that performs VXLAN encapsulation (adding UDP+VXLAN header) and decapsulation. Leaf switches typically act as VTEPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN', 14.0, '8c28fe779438895b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87451300-9109-4650-83c1-10400ce04108', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'What is a QFX5 Virtual Chassis Fabric (VCF) (variant 2).', '[{"id": "A", "text": "An MX series virtual router", "is_correct": false}, {"id": "B", "text": "Multiple QFX switches operating as a single logical switch", "is_correct": true}, {"id": "C", "text": "A physical chassis with multiple line cards", "is_correct": false}, {"id": "D", "text": "A virtual router instance", "is_correct": false}]', 'VCF allows multiple QFX switches to be interconnected via VCP (Virtual Chassis Ports) to form a single logical switch with unified management.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis', 14.0, 'd5f2d03ff4cd7884_gen_v4', true) ON CONFLICT (id) DO NOTHING;
