INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ee97de4-ddad-44b3-b940-c048a707ce91', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'Which encapsulation technology is commonly used for overlay networks in data center fabrics (variant 3).', '[{"id": "A", "text": "GRE", "is_correct": false}, {"id": "B", "text": "IP-IP", "is_correct": false}, {"id": "C", "text": "VXLAN", "is_correct": true}, {"id": "D", "text": "MPLS", "is_correct": false}]', 'VXLAN (Virtual Extensible LAN) is the most common overlay encapsulation in modern DC fabrics. It uses UDP encapsulation (port 4789) and supports up to 16M segments.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'Data Center Overlays', 14.0, '3423a9fe57eccd96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
