INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83be32cf-605e-425d-90ce-6f55e8d42732', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'What is a QFX1 Virtual Chassis Fabric (VCF) (variant 45).', '[{"id": "A", "text": "A virtual router instance", "is_correct": false}, {"id": "B", "text": "Multiple QFX switches operating as a single logical switch", "is_correct": true}, {"id": "C", "text": "An MX series virtual router", "is_correct": false}, {"id": "D", "text": "A physical chassis with multiple line cards", "is_correct": false}]', 'VCF allows multiple QFX switches to be interconnected via VCP (Virtual Chassis Ports) to form a single logical switch with unified management.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis', 14.0, '0595a131a7dbd543_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('074048d5-58e6-466e-b243-44827df84a7c', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 1, 'remember', 'What is the spine-leaf topology commonly used in modern data centers (variant 45).', '[{"id": "A", "text": "A three-tier topology with core, aggregation, and access layers", "is_correct": false}, {"id": "B", "text": "A bus topology with a single backbone", "is_correct": false}, {"id": "C", "text": "A two-tier topology where leaf switches connect to all spine switches in a full mesh", "is_correct": true}, {"id": "D", "text": "A ring topology connecting all switches", "is_correct": false}]', 'Spine-leaf (clos) topology provides predictable latency by ensuring every leaf connects to every spine with equal hop count.', '{"https://www.juniper.net/documentation/us/en/software/junos/data-center/"}', 'Data Center Architecture', 12.0, '9e38f024e34986f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
