INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('546f1213-7eae-4023-84b3-742ea6adc954', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'remember', 'Which Python library is commonly used to interact with Junos devices via NETCONF?', '[{"id": "A", "text": "Paramiko", "is_correct": false}, {"id": "B", "text": "NAPALM", "is_correct": false}, {"id": "C", "text": "PyEZ", "is_correct": true}, {"id": "D", "text": "Netmiko", "is_correct": false}]', 'PyEZ (junos-pyez) is Juniper''s official Python library for automating Junos devices via NETCONF. It provides Device class, configuration management, and RPC calls.', '{"https://www.juniper.net/documentation/us/en/software/junos/pyez/"}', 'Junos Automation', 16.0, '1b4557c16549deaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('764508cf-bcc9-4859-89ca-03defad29a9e', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 1, 'remember', 'What is the default NETCONF port for Junos devices?', '[{"id": "A", "text": "830", "is_correct": true}, {"id": "B", "text": "443", "is_correct": false}, {"id": "C", "text": "22", "is_correct": false}, {"id": "D", "text": "8080", "is_correct": false}]', 'NETCONF uses TCP port 830 by default on Junos devices. It must be enabled with ''set system services netconf ssh''.', '{"https://www.juniper.net/documentation/us/en/software/junos/netconf/"}', 'NETCONF', 14.0, '12774bb90fa5fdd8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e81529cc-4572-45a2-80d5-dc212477145f', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'In Junos automation, what is an SLAX script?', '[{"id": "A", "text": "A shell script for Junos", "is_correct": false}, {"id": "B", "text": "A YAML configuration file", "is_correct": false}, {"id": "C", "text": "A script written in SLAX, an XML-based language for Junos op/commit scripts", "is_correct": true}, {"id": "D", "text": "A Python automation script", "is_correct": false}]', 'SLAX is a scripting language based on XSLT, used for Junos op scripts, commit scripts, and event scripts. It processes XML data from Junos.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation-scripts/"}', 'Junos Automation Scripts', 14.0, '74024a9956d0945e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80a647bf-d89d-4baa-9ab2-1db0710fe12f', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 1, 'apply', 'Which Junos command applies a configuration from a file using the CLI?', '[{"id": "A", "text": "apply-config /var/tmp/config.conf", "is_correct": false}, {"id": "B", "text": "load merge /var/tmp/config.conf", "is_correct": true}, {"id": "C", "text": "import config /var/tmp/config.conf", "is_correct": false}, {"id": "D", "text": "set config-file /var/tmp/config.conf", "is_correct": false}]', '''load merge'' reads a configuration file and merges it with the current candidate config. Other load options include ''override'', ''replace'', and ''patch''.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Junos Configuration', 14.0, '39dade8f22dd13d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
