INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('193fd19d-0c41-45bc-83a2-ce4f218c75e0', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 1, 'apply', 'Which Junos command applies a configuration from a file using the CLI (variant 100).', '[{"id": "A", "text": "import config /var/tmp/config.conf", "is_correct": false}, {"id": "B", "text": "load merge /var/tmp/config.conf", "is_correct": true}, {"id": "C", "text": "set config-file /var/tmp/config.conf", "is_correct": false}, {"id": "D", "text": "apply-config /var/tmp/config.conf", "is_correct": false}]', '''load merge'' reads a configuration file and merges it with the current candidate config. Other load options include ''override'', ''replace'', and ''patch''.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Junos Configuration', 14.0, 'ecdb14e3cd0966fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7509232-4601-42eb-b0ba-0dcd794cb8c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery?', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '86db3368c1c4b7d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fe8d0e1-b540-45af-b4a4-8ea6621af961', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix?', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '5a4ff94ff200a4f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7757cd1b-affe-4817-913a-048f19f3949a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network?', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '97cdc1a17e761eb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d6b15aa-20cf-4877-8cfb-f6aaa85398b1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD?', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'add24842394cc9ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b42853ff-6f65-4d57-99b1-33ee1ef4a63b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch?', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2fbd24ff8195e13a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('469beeae-7cab-4d0c-890f-8de3074d5adf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk?', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd9a9ad6c1c285f09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99f5dcaa-8076-41bf-b8b0-25627d9a923e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning?', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4e3cae8d9884e513_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f867945-1b94-46ae-8505-ba109ea8c90f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive''?', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cb3f7e1f129f78a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9dc9c89-aafc-439c-a563-88c47e5f7ffe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network?', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '28f5547c0f1ba9fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('359594eb-4866-43b1-9cc9-2e65327e27aa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route?', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '812bba07b059babc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c390c042-cedc-4eb7-a290-7b8c00e582e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses?', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '7bfc8f293355b5e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b740fea-4c14-4f8f-b0b3-b25b9f5ac76e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol?', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'b14282c3bc2bdbe8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26a7f766-fd9d-4040-b3ab-1108a555d6cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent?', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fa288d19d944d50f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64a4862a-8fda-4102-8d58-1ec2546a5ef1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address?', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c2e074314cc463cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('306ad102-2020-42e1-b619-e35b60795b53', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server?', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'b06a8dacb7fdf49c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55c21bc5-f34d-43de-80fd-d0db541efd0c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.222.180.0/24 network?', '[{"id": "A", "text": "ip access-list standard 10.246.122.0 0.163.115.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.246.122.0 255.198.121.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.246.122.0 0.163.115.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.246.122.0 0.163.115.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.163.115.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a1a5b220b16155c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6f28b12-3a1f-422a-af28-d2c3e88d1c96', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device?', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'b76e360b030e1c4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32bc9b4d-ea43-439e-b3e0-fe7840ff37d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch?', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'efdd764af82990a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17b7f437-2a5c-4800-add7-edffc424c736', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management?', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '17dce49968f3e29b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('650582c2-ba80-4d29-a2ad-afefc41dea23', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation?', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'f5d5f63b57e60096_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51f11439-eec1-4a3a-a964-bfba982e2460', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 2).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e8c716e4fba68b1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82f73837-543e-4696-9539-669404823e3e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 2).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '629d821fe76fc2ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20f07ae7-3951-4542-a122-f1efa2bebdb5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 2).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '363008ee24717219_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa26b4b7-593f-470c-b6d6-f5c1c085d339', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 2).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '9a5dbbce9b27f353_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bf10e85-d088-4eae-80c0-1752f3d99ac9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 2).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fabf0895ceb253e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5740fe92-2bc5-45a8-a224-f79c058d1e56', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 2).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cf684d214dc1d79e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a78bff36-7cef-4b79-ab5f-b16b8555c45f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 2).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e44d3daed7b432ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90436612-466c-4498-8606-cae513ed7b8f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 2).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f56e47cd978a16bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b57fb636-382a-4954-98de-a990ae011bbd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 2).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '78d2dfb208c3d661_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae7d9512-e5b2-45db-ada1-105967db07e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 2).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '6094c10421f309dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d086d4ae-3ede-4adb-88a8-1fc0bbe58b5a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 2).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '06747016ba470884_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbc88ec4-62ae-4ecf-bf29-39d88361f593', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 2).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '2d8b5072dcdd29d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f90f04e7-11b5-4504-b200-0a681ce2599a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 2).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7ff933b8a325ce4d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4e4659d-5527-4af8-ae2e-36cd521b031b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 2).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8eb13bfaa1352da2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aff197ea-d52f-4f72-bab0-7ed356e7b30a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 2).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'd93eaaee9a51d9fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92e8c906-b366-46ca-a667-865900dca3f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.121.96.0/24 network (variant 2).', '[{"id": "A", "text": "access-list 1 permit 10.103.107.0 255.56.1.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.103.107.0 0.162.217.255", "is_correct": true}, {"id": "C", "text": "access-list 100 permit ip 10.103.107.0 0.162.217.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.103.107.0 0.162.217.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.162.217.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ebfc7e17a948b883_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3963a16-b56d-4e16-9b51-8e196ac84c0d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 2).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '0c241ce8b5a12d11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b68f777-9c48-4f6d-a058-d8c25c7028ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 2).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '30e30fe4b81d5317_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35a2aa67-ddda-4cf7-b967-3487f37c334c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 2).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'b2f8f6aa6065fe70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a52a7e31-feaf-402d-8d0a-b9bf33077dce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 2).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '5cec65de11fb48cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('935a1e4c-f507-405b-a8e8-04a78eacf24a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 3).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '74a04f3d4557172b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48baf0e8-0f0c-46b1-a37b-1926371cfdd2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 3).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '58dec74f877d70b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e05d258-af5c-4f5d-bdd8-3f7e666e31f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 3).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a133a461611e44dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8693a851-90bb-428a-9b8f-ffb10d32c4c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 3).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '8b06b935981953be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9397d69-1a1e-460d-809c-c6859bcd4e96', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 3).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5f65efffeb35dd97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34c3d6e7-0549-404d-9bc4-d72ede485054', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 3).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2a5fa5c3d8374949_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd6416b0-a15e-476f-a5f8-b59a24444203', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 3).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9bb6d6a1ca1457f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ce68488-2d6f-425b-9800-ce80a50b0a55', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 3).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a5224f25cfc26519_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4c6789a-c06b-4800-a1a2-721e04e685ef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 3).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'fc0edf6a28ae2ffa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0006340-a8c4-4202-8b46-1d39f74c0bf3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 3).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'f92fae9d5af07be3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1a21f36-0f2c-4249-bd25-bbad5cbb958f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 3).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '906c4536cd8ced9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59196bcc-08ab-4dea-acf8-104750284201', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 3).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'c84f371cf1f97176_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c36d248c-91b6-4053-a7f8-73a6ca4a0878', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 3).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c631e2fc3982ff4a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('599f4e3e-0dd6-467a-9ff7-36171199c798', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 3).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2cc31ae35338f2b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e543345-0196-4652-bf6d-6682ed09a097', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 3).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '9a439d8f82155d94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42fb475a-d064-425e-bd0e-6d1a3d175198', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.117.103.0/24 network (variant 3).', '[{"id": "A", "text": "access-list 100 permit ip 10.236.16.0 0.95.227.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.236.16.0 255.155.40.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.236.16.0 0.95.227.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.236.16.0 0.95.227.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.95.227.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ecf931d857d43935_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dcc9a89-0059-4bd9-abae-55ddc9dd30cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 3).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '756b55fa429820c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('146c6d89-0ae2-41fa-9f13-8ea9863cd902', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 3).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '693d95a675296764_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16110355-b28c-480f-9f40-2711681d837e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 3).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '940abbd2a87954ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfacbda0-7aae-4f58-b679-39bef0dd9796', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 3).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'dc8c56ddedc9c60e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccac74c4-9578-4182-a99f-deac177cde4d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 4).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3ff7eca3d9117186_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d36ac9d4-b3c0-4519-b561-4dc65e1b0613', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 4).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c1145d8e3e23c95c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05b0dfdf-5eb8-47e6-adb5-37e937372f7e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 4).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '6529ac46fccabd76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0650caec-927d-4acc-8edf-59b597a3de9e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 4).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '7dbf211f192f5b6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74745475-150a-41b2-98fd-573c409791a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 4).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8df5e88bcac5dc60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee4b44be-f7d1-4511-8ecc-c3ee22b6c9f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 4).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '80f6f6d5c8dcba43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7746340-7556-4b6c-8417-2f2d8609706d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 4).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0e8214030063dbaf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23fa579d-ad16-422c-9533-012d5f34d3b5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 4).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '83c293fddc7a17ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da26fdf7-d3cc-43ce-b89a-a9557d4db6c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 4).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a25286d68d6703e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f4b8850-d992-46a9-bca8-959035069d18', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 4).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '264cab0aa8e567bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c519c4e-db18-41d0-8755-3b0c69726813', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 4).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '64b7f8b950697f6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ded5d28-c321-4e6b-9d74-2ceda46b2602', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 4).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'a1c667426b074eb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9787a53d-f24d-4fb3-92e0-9a7195ceb6d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 4).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '550085b4bab7e97d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c81b0512-f986-4edb-8fc0-87a80a56585e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 4).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5fbbfa35a0374748_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8074a3e-e9e7-4eeb-9207-68d1fcb898f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 4).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c9ce11142d56bb43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b401af47-5b89-472f-a5b4-990fcf75f2d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.165.46.0/24 network (variant 4).', '[{"id": "A", "text": "ip access-list standard 10.132.0.0 0.226.195.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.132.0.0 0.226.195.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.132.0.0 255.222.79.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.132.0.0 0.226.195.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.226.195.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '736b708dcab846b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d979ee84-0192-424b-8f44-782a0d55ecf3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 4).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '366182aa3da74e3b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ed49cb4-73f6-4527-bfa6-108307601784', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 4).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '44f932bd4a5adfc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b3aa014-7fe0-46eb-bd7f-ea103c911812', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 4).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'd511eb7a83fc9d87_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f76a730-ae1a-455f-a308-3a074923fb54', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 4).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '667393c3aab6dc17_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe0fe4d9-639c-48db-a3d4-d0e9d623978b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 5).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2f7f35f2a3d787ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e3d6d30-8ec5-454e-ab16-54a42577853b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 5).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1f593c2a84e707f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33814e9b-2386-40aa-83cc-a7cf751084f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 5).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a17215ea0ab47208_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca4527bd-a30d-4767-a1ba-4cd21632887e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 5).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'acb2d59bc1c3db7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f950c4c-287d-44c8-a33c-ebc759f1e32e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 5).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9cf6f0f9dfa0c019_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ab3171f-7186-4351-a195-5571af2d2450', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 5).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b87bea4938a87245_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('061ad5ae-986a-429d-9741-656517e354e6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 5).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '90e579a8b7fed8e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c76969c-6847-4d4d-84d5-93275ef7ccef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 5).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0d27c3b69289cbec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5689b5b-44e3-4016-b248-bfbe132956a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 5).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '7f8cc35606695eea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af9b9b47-1e8b-460a-bf04-26a9d62ec3f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 5).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '02d1e931c8bf33c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('187d1ae5-d276-491f-aedd-686f3cfa86b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 5).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '6b2ba0211a33a453_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('469c33a7-3df0-4356-b3db-2a4354da9202', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 5).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '7ca5e2b55094f852_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d805c55e-1b6f-4040-8bd0-6541f0e9d828', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 5).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'baf3e5241531cf5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85fd0d32-fdc2-41ff-9a5c-4f161a6d9e61', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 5).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e7c37b48b1a97cce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38b9a4ab-9b83-4b74-8670-7eb2899a506f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 5).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '4f345c7cca19f8d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be374271-42fc-479d-93bb-52b9d2fb2bd1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.15.161.0/24 network (variant 5).', '[{"id": "A", "text": "access-list 1 permit 10.152.12.0 0.180.52.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.152.12.0 0.180.52.255 any", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.152.12.0 0.180.52.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.152.12.0 255.157.190.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.180.52.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '507af3b3580e8806_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('645b2708-d3a0-4d23-bf2f-bc3cb0f31fc2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 5).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '1478fb0a4e893091_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('301a225e-48b8-43bb-be6a-1f0da3383214', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 5).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c70eb97599831504_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13f70e08-c421-42b0-8b71-bdc85b9223f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 5).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'd7f448887f9bd55a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c174b100-49e3-43fb-ab6c-a375ab481ebb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 5).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '5da9c7e8b3bc8fba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63478352-8184-43ff-a1f0-d77dd74c8140', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 6).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8545e8f120bc48db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51b600bb-8259-438b-9987-f5db9bca85eb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 6).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '24b632b1252d937e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a56abf11-e889-4838-9ac5-11fc2175d95e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 6).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'dee500e832b80188_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3cd12b7-152a-41b1-9978-edd427942567', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 6).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'e88452cd8bfbcdfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d568a006-195c-4268-80b3-255f8af39e25', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 6).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '20d4f4b52649c6eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('579a823d-0fb5-45fc-b4c7-617f96b392a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 6).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c696dc027926b1b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4b22d25-a13d-456a-a046-1da7827fe2cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 6).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e739b4144b48dcbe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1493ad6-c8f6-4789-9ff0-b0176e721536', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 6).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '818172d2e63ab751_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c0b3d46-130b-4d10-9634-9101efe8b733', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 6).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'c59a3651ab417d82_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3efd6735-d9e4-4896-b54b-02680b996fe0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 6).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '4d2e6c836e5de849_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c3b3131-2d83-4517-8db6-49789cc10200', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 6).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '772caa5e21d21c00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57f29142-4989-400d-b7ea-bc3d47386ada', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 6).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '470cb1736bda0aa6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41c2ce38-2500-4026-a1d9-bc91772ea053', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 6).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3dcda3acaabe5f9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12fafe71-efeb-4ed8-93d7-86d8e9bb3c11', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 6).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '12482354f61993ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18cc35da-cff5-4f2d-b987-f4f7d0dddae3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 6).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '8c609b64a7fe839e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe5f9ac9-abde-41c7-996d-394347577407', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.197.112.0/24 network (variant 6).', '[{"id": "A", "text": "access-list 1 permit 10.253.220.0 255.123.93.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.253.220.0 0.170.138.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.253.220.0 0.170.138.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.253.220.0 0.170.138.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.170.138.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0a8aa778803f599f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07299389-c1de-41f1-9317-30165e61f762', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 6).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'e7c1fe00a3d09c87_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01d8a319-798e-4d7a-9383-80b0177aaf52', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 6).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b082300b5a39da3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9842b930-360e-4be5-bcb4-f88d5befae49', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 6).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c0be9887cb66d47b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('520b76c8-d1b5-4609-b201-97683144a370', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 6).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '8aca859b5b688302_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f2ad8f3-78e3-4b44-bf1c-94078b8df208', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 7).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e6d525428817755e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74f849ca-d0e6-4be0-ad06-01b5f451023d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 7).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0270541517c69fce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11d0456f-6fe6-4f0a-ba51-d896687b7d60', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 7).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'ea2d2131e7aa8607_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48276f04-0a85-41f2-b542-7d24076c5504', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 7).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'b599f28a0c9035fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd1945a6-bf07-4013-8c2e-3e819f1f34d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 7).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '68e69c4b3042fb1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8fe0de8-ba11-4efa-ae08-63f6b8c5c930', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 7).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b565221173e7a336_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5d88659-8321-49bc-adcb-d24ba9c460d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 7).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '496752c7ccd7f6fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5076b8ad-ea31-42c9-85c7-463c75a76834', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 7).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '12e4ec0bdbab341a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('666d9fc3-bc3a-4d69-a3ac-ffcad78f46a6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 7).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '0ebade6f7ff4dd85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('360aa99c-c3c0-4431-8d6f-73fcce71e9ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 7).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '5db00984d3db4afa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5611a856-fd51-44f6-8b24-d35b6a985560', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 7).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'ed8729fb6f77da01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('468706db-8cba-414f-9257-ca8a004fef9b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 7).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '3180984a436caeff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('460c1089-7d8d-486c-b9dd-adfd76828514', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 7).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e4c1ef99062c286d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a21b9125-4eeb-43e0-8378-d631457e2964', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 7).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5184f9ed1ec80189_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5dddcbc-81ad-4793-8779-09c4885ae022', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 7).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '773f82b029eb7546_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57049365-40f5-42ab-89fd-2fe623cbedc0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.136.218.0/24 network (variant 7).', '[{"id": "A", "text": "ip access-list standard 10.52.230.0 0.196.123.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.52.230.0 255.99.108.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.52.230.0 0.196.123.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.52.230.0 0.196.123.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.196.123.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2762c6cbd90aafff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a7f1ff4-3678-4005-bd22-54b046b4efec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 7).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '60e6d8a953a79407_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e14512d-ee78-47e4-a523-e0a6b78425c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 7).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a2cd8e81e82dbf73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6976761-d9c4-467d-b86e-66340bffb910', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 7).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '0948e76348cc1d1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0236c19e-63f0-45cc-a987-883e76434a8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 7).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '35b646ca4813c8a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14ba6ce5-34ac-4978-85f4-b77d711da7be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 8).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1671551bfa26d186_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca3121aa-be8f-426c-8775-8d38c4c43e70', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 8).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'bf305e9340d921c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a12f20cd-c827-49b9-a131-38389971bd5a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 8).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '27941eea9207124a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76d359f7-5118-4850-9c4a-e3b614f48e3b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 8).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'c9bb7eb571ca2e08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f57ed6b8-aab7-4ce4-9420-6da5dc1d0a06', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 8).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cc09a854efbf056f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abf6be20-4ecd-4377-84ac-f5fa0ec7ca70', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 8).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f73a1777fd0cc32a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ce64e0d-aaa0-498f-b9ce-7ab476a8af6f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 8).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9e8996d36b951184_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16aab6a7-d78a-43b6-8f8e-e269d6213242', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 8).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ed014fe5da48e2f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f9aaf24-6cbe-421a-9fd7-f52f6ca4f273', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 8).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '8029a83e41670552_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50d84aba-85bf-4929-baff-a7e10dbfc801', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 8).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '12525984dc46cf63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3beb0c76-2479-47cd-a63f-650b5d06ce36', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 8).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '98736c9d4a0a849b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71f6badb-458f-43e5-b63d-c0c8bf852580', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 8).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '2fc673a2be8d6879_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c0eab9a-f1de-4f4e-b35e-5ac94df8a462', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 8).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd417e675384bbb05_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d32ec18d-17c2-4242-9535-1112749d6ab8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 8).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c96686eb8c377f63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('954c26b1-2574-4786-8276-36b4c7b28196', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 8).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'dc816667632a9d9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58f61ede-fc76-4efe-9f46-1604705bb4af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.14.80.0/24 network (variant 8).', '[{"id": "A", "text": "ip access-list standard 10.194.192.0 0.217.117.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.194.192.0 0.217.117.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.194.192.0 255.94.188.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.194.192.0 0.217.117.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.217.117.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '6bae8465fa41608e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49ac094a-7535-4da1-bda1-604885dd8645', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 8).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '303318a99e0683d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97e3ef54-7284-476f-a15c-c804e0566110', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 8).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'be4d815a31c67947_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6c6d17f-625f-4a7d-a20f-3f115d36adc8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 8).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '6a9771d977cef91e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0adda304-146e-4cfe-80af-d9d6e4e28be6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 8).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '5090fa0e69321562_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64cb4510-f329-43e0-a9cd-cbc2408af880', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 9).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '29bb1f065e25a2e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fd43877-604e-42df-8ffb-687536fe79dd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 9).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f7e477f4db663a95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88e4b08b-ef2f-43d3-bca4-164fee9079dd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 9).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '9fb7f85d96a5986e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4577ab21-1f19-4b0c-906c-5429988e73e5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 9).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'faf005213cb45595_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7103018a-58fb-409b-9a1d-91a139e33477', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 9).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c9bcb06cc35888bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2104a7fd-4a42-4f13-b4e1-42133bbd465d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 9).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c25988858dcbe600_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5990844-1654-4d02-a261-e29cacd2d85e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 9).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd5db760140de9ddc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77453510-c350-44d8-aa32-8a454a9ae96d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 9).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0e8854f318ec36cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a7f78a9-f7a9-43f4-b966-53c4040de89c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 9).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a6c4cf7084d4d973_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fef156d6-8850-458c-9aa2-6e1fb2dd6b28', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 9).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '0c84df15f1190a12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa9afcbc-8ce1-4c34-aeb6-2a16ef703298', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 9).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '65b5d4ef71423ebe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d56857ae-db2d-4782-a890-8fa86516b1a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 9).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '765eca8ea4e11f0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2507ef6c-19d1-4fce-b1c4-787a93784f7a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 9).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f3089a85b0a414f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aef534e6-c10b-4419-a54f-30d019d11b31', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 9).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '42841cba85ac2a89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa989a9e-2e93-4e0c-b773-f9d22311f7e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 9).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '17afe6b26f039ead_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1af3065-9602-4abd-a317-238edba75e97', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.203.34.0/24 network (variant 9).', '[{"id": "A", "text": "access-list 100 permit ip 10.79.127.0 0.48.21.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.79.127.0 255.47.171.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.79.127.0 0.48.21.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.79.127.0 0.48.21.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.48.21.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e0676bebb2997f86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38559504-bf39-4af8-9138-5862d0664465', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 9).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '23dd529af48566dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fab1ea95-84c8-4a32-9ae6-1dda9300fb73', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 9).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b71759a218bf983f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4beb29b1-b8d6-4372-8c94-64651edb1191', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 9).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'a62d394ffffbad1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5a87ddc-6020-4505-9044-0bef7d6cd521', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 9).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'd4ce4baf45513373_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f19131d-8f3b-459f-a389-88e65acfec27', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 10).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '51455d47ededefe8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3f1ad43-d4df-4cd2-a530-2e17ccb75a66', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 10).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a07ed01f5fd26399_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1e29a28-fe3e-45d8-b565-bc3c430c1b52', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 10).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '6e6f2590545914bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eeca36e0-b67a-41f6-927f-10f877cdbe0b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 10).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '4caa8c28dd70ed16_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('951d9cfb-a91e-465f-8211-01202f8fce6c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 10).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9767ec2fc02fc662_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b9535f1-0f88-4488-b8bf-1ab7aede517a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 10).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '06dab3c8abeeadcb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c08c0bd6-b0df-4e03-a409-2d1dae267971', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 10).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '877b2dc4c3a8d421_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('251b6b80-bea9-4509-a517-ad537609c101', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 10).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c406fb0acd9e001d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de59c3b1-bbea-4c03-bf3a-cb96f0c9e479', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 10).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '180dbc9d1134a6ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76d92e97-bc59-430f-82f6-517c6b9348ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 10).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '0bfd3114bd2c21d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ca6cd0c-97b1-47d7-8ef8-e8e71c0ec2b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 10).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '5a324b74d1b478d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e7b9a6d-fb37-400c-b616-c74afa77147e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 10).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '87cb171ab34a9a14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a47f734-b14d-4ec2-87de-dfb771ff94d2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 10).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '78a942f91d18d7e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4e987d6-48ec-4151-93d6-58204455fda9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 10).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6ee5b6ecda8bcff9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e5519df-0e3b-42b9-8dfe-a9481b631688', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 10).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '7dfdaf6492623482_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f071ef71-22e6-4469-9414-3e9ce533a068', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.76.220.0/24 network (variant 10).', '[{"id": "A", "text": "access-list 1 permit 10.192.174.0 0.173.133.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.192.174.0 0.173.133.255 any", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.192.174.0 0.173.133.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.192.174.0 255.253.38.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.173.133.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a5d7a2bfdb50ef7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3fdbd77-67e8-4f7c-b32a-e821e75ae931', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 10).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'fe823e86ca16b3f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed4aee55-4385-4478-be51-86b4070886a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 10).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '94259e9341c3b191_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbabf01e-bbf5-46fa-9f59-d3cead7c808c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 10).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'a3e25d28aa55dfc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33bc6668-5a41-4498-a2e6-6871ec16890d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 10).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '6670f55561a18a26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3fe1913-1e75-440a-9c50-42c983ef48e4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 11).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e78b4cb90b9aac00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('490077f6-efbc-45d1-abe6-eb55acca0e93', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 11).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3669aa8c5b00951f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a25f8d9b-84a4-40a1-aae7-5fad5e727755', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 11).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c7fc1cd17e6c643c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9af5b54-ec03-42b1-8ae2-33b3aebbf3b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 11).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'd42db3b31aca3403_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75c1b612-5e3e-4488-a56e-ca29f94d9b19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 11).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '46d18e1f77e62f8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95d2f5e8-e53d-40dc-a165-fbe3dc96acd9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 11).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8ddae79780402d43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8302109-1bc0-47d4-9b69-413a3dbe20f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 11).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e8095b2e5fd1eb7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b539dd30-8209-4f86-b3e8-0c251b5662ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 11).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a3636d5556194fce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30cf8f19-e0ce-4949-a779-fd1c87488241', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 11).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'f316c486342c4c00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d6300a0-63a7-49a7-ab63-4c965a54405b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 11).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'ded82258286e42aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02d2609a-7a31-4892-8746-17d2c04bad39', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 11).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '7a0d3bed4071c05a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62503232-cdf9-4815-a124-39fceeffef10', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 11).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'f74ddc4c407eb7f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6db61370-f62f-49fa-8b8e-4050ab093310', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 11).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '752ecf993dd600ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcb1830e-5155-4cf8-ad9a-97683522100d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 11).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '207b9400acf8768a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53661ca3-f25c-4de3-b89b-c86c98fd6920', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 11).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e2bcb7ea831042d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('219ae24e-cbb8-4cd4-9351-088827530803', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.82.248.0/24 network (variant 11).', '[{"id": "A", "text": "ip access-list standard 10.164.15.0 0.160.130.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.164.15.0 255.102.184.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.164.15.0 0.160.130.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.164.15.0 0.160.130.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.160.130.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f528ccad77378b93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1dfccda-daff-402d-8760-44d1685b5891', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 11).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'b3fae847bc995964_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a567b3bf-609d-4763-aaf5-6bba20b71cf2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 11).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5bd2a4fd5cfc5db3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4d0d281-b09e-43de-ab90-26fffc922705', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 11).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '4ba7c24871fd0b86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('713cbc1c-ecf4-492c-a776-f0ad1e2ff365', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 11).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '493d29393fb46aa8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('078b86f4-abd2-495c-9c1b-7f34e4cc494d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 12).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0e82e36632d393f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b140fd8-63bc-46ec-9fb8-243cee61db76', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 12).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ed659b05c4aa545d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe756808-9ad4-491a-a3ca-f4646ece6d8c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 12).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '64c0f90711a607bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff537ec8-344d-4808-9bd1-560b3efe22e6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 12).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '617708bacd90cf3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7c03ca7-26c2-4580-9102-43f2106986ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 12).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ac5973e480c68002_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b3a0feb-a565-4549-b5f9-a33a3064b9c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 12).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '05133a607aefd0ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d1628ac-8123-4ac6-8491-ea52ff236944', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 12).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b37e23bb96129676_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70ab29eb-2cf8-452d-8c2d-fbcaa2ccad05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 12).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3271e68e13092b3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9aa150fd-b58c-4b28-9505-8f33201e56b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 12).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1962e7975c11a7f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('446445a3-5496-4da3-9580-fd6e898d6f29', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 12).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'a3d707346a15cd4d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56647401-acae-44e9-ab1d-b011f58de5b5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 12).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f220ab02341dad2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7afb615-2bc1-45c1-9b73-e4077ae70251', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 12).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '4d402ec770ae96f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cb7e3e4-c712-4475-b47e-591ff81513f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 12).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '451000776c90b308_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f70a0712-2d88-4d14-b41a-219f155b42ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 12).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '45807b3e81e321bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32e6f905-35b2-4974-9973-e85730514113', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 12).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '014b239d2852f34f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c772b44-77ae-487f-8dbb-1be90f0bb21a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.199.69.0/24 network (variant 12).', '[{"id": "A", "text": "access-list 1 permit 10.42.80.0 255.251.135.0", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.42.80.0 0.20.162.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.42.80.0 0.20.162.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.42.80.0 0.20.162.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.20.162.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8adc387463e1539c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f8eaa5d-df21-4992-abb4-83d358ba3bba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 12).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '5234e7afc692a66b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d539087-8e6b-4b63-ad5b-9718fa7fd01e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 12).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '01f3b4cab4f97215_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8263c6c6-6a84-42bd-a284-70af21129986', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 12).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ccdfa603e82967ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4631ff57-fb3d-47e8-96ff-9dd9a2137821', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 12).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '392610a86d559a56_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b3f5200-334a-49fb-92d9-e3de28db898c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 13).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b5dcae4040c4610f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('347ead03-2dd4-4073-83c2-22578c70b0b8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 13).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1b08866089641357_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c26d41e-1033-4996-93f8-71e09fc8fdaf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 13).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '05dc781054d6be58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08e5d7b9-2879-4505-b2c4-ac484b682e50', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 13).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '5a697841bdf8f8df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75547fd1-fb2d-416d-98c2-0034fd2c27fb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 13).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd4b4cb1ddbe1c18e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('590b325e-9c23-4956-9df7-b15f4f8d0583', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 13).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3eee679c70141bd5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4094afe0-ee43-4622-8d34-83340e936f5b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 13).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '320f79440d866eca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f78b762b-5470-42e3-8d39-503aa61da23e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 13).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '90cf7d0a2cba13a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffe8637c-8ade-46f5-bf1f-525192d3caea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 13).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '29c78334d0c10442_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57852c4e-0172-469e-9276-0bb560cf0d41', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 13).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '8b1ebba30d90e24a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfdac702-0327-418c-811d-34562e5494a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 13).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'b52b64aec7a86a57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6be61a7f-5a50-4e5f-bd52-fec18797338f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 13).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '988fdeb56438f9c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78f0d34e-ff00-4008-8df7-9f9bf0a74a45', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 13).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '30da983acea727a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5795edba-5e52-4796-aba7-d748af0d74ff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 13).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '0d46d11933b6baf7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7de80a62-c497-415e-92b5-3bc459a157ef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 13).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '4c73b771ee2166be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d1b365c-76fe-445b-a49d-ea1bbe1e8915', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.62.66.0/24 network (variant 13).', '[{"id": "A", "text": "ip access-list standard 10.247.102.0 0.39.114.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.247.102.0 255.9.150.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.247.102.0 0.39.114.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.247.102.0 0.39.114.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.39.114.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e7a28fe111ea3e9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a612ca9f-d6d5-4609-a8cd-75f39541e7b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 13).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '67ed162be18d5268_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a820525e-c15a-4e12-8036-2055fce83e75', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 13).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3d69697af8ff886f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc6c887b-3df6-41f2-b12b-fdbe6e423d71', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 13).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '27ba794939c25081_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c3026ba-0ba4-4ae0-bdc0-466871c8505d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 13).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '8c1ab50ef73d0b68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5f26f4d-0cd8-403b-93cf-011a65ab5a2f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 14).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ee7499b09ec4b742_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e417f587-faa0-4a64-9ff7-51f898037809', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 14).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'cd26f34919e01cfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('465f5420-384b-45aa-9a84-75b6ade3249f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 14).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'bc69d37fc43b3485_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24f722b3-5c6e-4e33-b605-7af372a39026', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 14).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ed870bb1b563d326_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb21b3dd-376e-4bf9-ac98-c25746a25dd6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 14).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'af3e1d19e278a395_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37ca4d2c-27c2-4cbc-aa12-ac7a204d043c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 14).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '502490da4f617ef9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75466002-a9d4-4ee6-9724-ccd23f250bfe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 14).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e2e2400ed8dcb353_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc8c3b33-7ad7-4b93-a12e-abe3e44aed5d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 14).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '476f3754a6f291b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cc44e53-e95d-4e5a-a7c7-f4f3b7ff6b37', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 14).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '2239f37d27ab5b44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('126bc3f6-7617-4ed8-b242-596b2fe16418', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 14).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '2a0e80082b0df26f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4feca7cd-5f0e-4922-81b6-9c45170ad255', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 14).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'c0745b1a17dd9e57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b01250e-038f-4715-89ca-0d400cbcf7bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 14).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'd5a8365c1f0980a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e7b23d7-a014-4842-a9ce-9a05d6a4a6d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 14).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e2fac7a9baeb0ab3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e93a104-2b64-4bf8-b83a-d3dd538a8115', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 14).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5fb4088b4c390371_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4316c3c6-e2e4-436b-aa9b-23e8552b1ab6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 14).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '64da37ec7454cbdf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04d07df8-e3fb-46c2-8136-797f42ff20da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.41.145.0/24 network (variant 14).', '[{"id": "A", "text": "access-list 1 permit 10.47.99.0 0.197.39.255", "is_correct": true}, {"id": "B", "text": "access-list 1 permit 10.47.99.0 255.183.189.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.47.99.0 0.197.39.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.47.99.0 0.197.39.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.197.39.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c337cd8cba5e1f76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cef3ceb8-1aa0-4eb3-8a33-ece0ed35a8c1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 14).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'd8e6892cddc0f7ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78bfdf25-7be5-422f-9520-15291c35710a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 14).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd4a6ed28bd821352_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1803ec5b-95a7-42bc-9d7d-55be7f972dee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 14).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '80fcd19bef3f914f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a86be0a-9263-4f7c-9bbd-1f62713de2a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 14).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'e2468d4549abaee2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9a5d588-c899-442b-9e6c-577495943329', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 15).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b89a0f081f80d7d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('467b312e-9231-480b-8970-ed7627bd23c1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 15).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '78246781b592a182_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a72df79e-bd5b-47ec-bbfd-6a1b1e7da5f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 15).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '96f6b9541189c9aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ba58925-74e4-496b-9501-bacd6a3c5bc1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 15).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ba033282d5bfc062_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b428cff8-feb2-4945-bdc5-6d5481a15833', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 15).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '99779efc83f9035a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a9b4a0b-db63-42f6-94cb-1bb3f23cd7ba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 15).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd15a74b6f557e682_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c247036-c770-42b7-b039-8bd63ced1b44', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 15).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ebe05d83cdf377bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cff35ca7-3477-404d-ac9d-4a3701a2acaf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 15).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8f36229ea0430c11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91a92f4d-6ab4-4f95-83bc-f5e93be47cbc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 15).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '42f522d302196aa9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('855637c7-4817-47d7-b3de-1868d572d50b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 15).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'eee1064093f962bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c2464e1-1d09-4ee5-90e3-b51a13b5ea15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 15).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '471fe391ca468f09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0056a642-5b27-41f5-a569-65e468ba2412', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 15).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '6589db7fd594a9e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc661ae3-9ee9-49da-9ab8-203a5180a9d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 15).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2295dd0b1dfea77a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79e67acb-96d8-4e28-b5d2-01113215a42f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 15).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ed2dc85cce4d53e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6aca147d-0a27-482e-b094-4ae5b839da98', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 15).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '4919dbff5e4816ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a64ee58d-7c1d-4bfa-8934-17414899166e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.90.224.0/24 network (variant 15).', '[{"id": "A", "text": "ip access-list standard 10.78.53.0 0.17.9.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.78.53.0 255.30.197.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.78.53.0 0.17.9.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.78.53.0 0.17.9.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.17.9.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9def6223bab649cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce788888-cffe-45f0-9179-f66fdf1e558b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 15).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'c9fbfd3dc610830d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccd4be02-06c1-4269-813d-9549ddc92356', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 15).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b8f763ecf67a0d0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97398b85-555e-4c26-adad-a29c4a44031c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 15).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '6b1c8d41e04ccaaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('442bd878-6982-4204-a417-5d7ce0cfa789', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 15).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'c619db01f5edd5f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28a48d2c-4acf-4200-8ae1-a7c816636c08', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 16).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ecf4594e14d20c78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73eb92fa-7444-4473-a1f7-e4e63e88de55', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 16).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c613784a1e5ec555_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de5a0fce-f283-4706-95d5-392553f1abf8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 16).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '93e7131117f99c48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f7c850d-0867-4d77-b1ce-8bf18a1cf24d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 16).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'f68e107f5eba9c3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('458ec340-2030-448c-8d65-8ae633ff4b35', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 16).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c3fdeea069f14cc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55ef296b-91cc-4d08-900e-bc5a6fa12c6a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 16).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1afb869011a4e804_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d6968ff-9125-43ad-a76d-315a3ac294a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 16).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '99529fdc0f7ac83e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eda8af23-103b-4bfe-b3ff-fdae200aae6f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 16).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '06c3509423a8ea1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1df75dfd-7b3d-453b-a8a7-93fd97547c55', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 16).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '18a3a9927fc92eff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49320bb8-7690-4f17-990e-3efe00f9038f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 16).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'b5621708a265bc4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fd5a067-046a-4bec-96cc-d57409bf3018', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 16).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '8069b9c5decb25c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('381b8e2f-e58f-4ce3-ab9b-c14454941a03', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 16).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'a1cc8186bf9808f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfcb6b54-655b-4755-8a78-e467f56a4ed1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 16).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8064838109dcc1be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be8af5c7-58ad-4560-a55f-e72b4615ce27', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 16).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1233c37d856df541_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46bb8a5d-c407-421a-8574-7511252008ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 16).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '409d95b2879f0f35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('533c273e-6b51-4780-86cf-0c027431880b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.190.33.0/24 network (variant 16).', '[{"id": "A", "text": "access-list 1 permit 10.153.163.0 255.222.46.0", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.153.163.0 0.171.149.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.153.163.0 0.171.149.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.153.163.0 0.171.149.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.171.149.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd66ecafb1d6a5cbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06f84c23-0e99-43f8-9d68-de905b9148b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 16).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '883617705e5427ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('638ab47d-9943-4f7c-8c80-c1b9384ad947', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 16).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '612be945a20ee43b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c47e6498-337e-40e1-8452-a4f400ffe43d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 16).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '70896290272a574b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b5b4f57-5d06-4728-b705-5d7f02d92dae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 16).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'cadac874792277bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff7bb21e-64cd-42ce-a245-3d15577991ef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 17).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2137b6e0062d3c15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3b51fb9-20bd-4cb1-a4f3-d534d9270289', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 17).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c3051e004246c719_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7efee97-109e-4ee9-8709-a0af6e775348', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 17).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'd39574ad425a2b00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af17f716-b96f-42b6-8870-6ba523bd5529', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 17).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '2fab2114c9f96430_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a65bc23-557a-41b8-a143-70bcff1853e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 17).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e14a2f04711fc46d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b979aa51-40c5-420f-a13e-dec4d6a933f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 17).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ec8c72e54afa8aa5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e74c709e-96ed-43b6-9b9a-29165c256194', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 17).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4bfcb96468f77490_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('768f338e-3c73-4587-b4b4-ae369d37a583', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 17).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '160084a7b865ba93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98d56ce2-1ea4-448d-92a8-b6a9e1c2d091', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 17).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a675f422bf778e64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfdf0c9a-56af-4296-bd1b-075e10ae23d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 17).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '507930b104927015_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ec3f657-9a14-417e-875a-c6fc766e1f2e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 17).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '6bf54e72bd27930c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b7f409b-f12b-4c85-9043-de8c1c9b672a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 17).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'a3b03fae13e9328d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b9090cf-25f5-4291-bf73-8da8c708cf6b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 17).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ebbdca8d68890335_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44b21c6e-7887-412a-9222-cb5dbbf5aac4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 17).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '127dc84652e532b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc51a1c7-5bbe-4392-904c-057bdf879e43', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 17).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '24025dc7fb1ecc70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7ff06f8-0a32-40d3-879b-aa9e6c479858', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.155.240.0/24 network (variant 17).', '[{"id": "A", "text": "access-list 100 permit ip 10.120.99.0 0.32.155.255 any", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.120.99.0 0.32.155.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.120.99.0 255.196.19.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.120.99.0 0.32.155.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.32.155.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'cdb6dc4913de2d5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c174143-f8fe-4d66-b534-08189958d7cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 17).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '333b37f5084cd84a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fecf8fc8-b4a1-46ae-807f-789adebac760', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 17).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '79a0cb08c5a79dbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0cde2b6a-38cd-4119-896e-ed1224850664', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 17).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '2b656d60e5a4e6f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76a6d04a-b1b7-4ebb-81bd-17e1a45071ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 17).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '6c5fd654ae7cfb96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b25d629a-259b-482e-ac2b-455e62688791', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 18).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '061b04ae20604993_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd038448-fa36-499a-a799-b41e68db239e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 18).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e17b9a5e73533437_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e095200-92a2-4227-afa4-d1eb6ec7d21f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 18).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c346eb5f36b633e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a1bf6ec-ea2c-49a0-96d0-861b111e74e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 18).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '00aee6473a2e606a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8aca00aa-a3f3-4c4c-bc13-de3995c118b5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 18).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3e2b4b9c471a4a8d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3047c752-cdd3-41bd-b338-8163c9955ffd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 18).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2be21b4db60c7adf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f91931bc-3fc5-4def-8bf3-3a821150a67c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 18).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '796bf6666c01d9d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6b57568-515b-45e1-92f1-0628968aaac1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 18).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a90b6a73d12bb41a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0327ffe-486f-49de-8094-a5bf4ace1eb3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 18).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '980ae8ca75a2df0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd34f0b8-ff70-4e9f-9c5e-ca5f80cbfef4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 18).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '48c2055219526899_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35a4c048-9bb8-456e-9a06-5d004eba2385', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 18).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '69551a98b9b8d639_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('498c1f3e-7456-4551-b966-8c10e0ff6254', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 18).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '07189ac9e9dcea75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2411610d-ad05-4a1e-9271-fad6b5bdc242', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 18).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '83e1e77febb061be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54ef9c15-c377-4cb6-b19b-bdaee43f4f5f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 18).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '66742d81e2747032_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64806119-5f45-47f2-9d4b-4e63dc6c3069', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 18).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '52e00b014ab082c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a4760d3-f106-4d14-8041-9d03bcb01a25', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.23.189.0/24 network (variant 18).', '[{"id": "A", "text": "access-list 1 permit 10.169.219.0 255.49.128.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.169.219.0 0.113.5.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.169.219.0 0.113.5.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.169.219.0 0.113.5.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.113.5.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f54fcead7b87bf1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d07f35e0-a7c4-4308-a9e0-4519728830b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 18).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f8f977026d85cecb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc20b80e-09b1-4904-a3f7-017f25993ad6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 18).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4a924a97f9d575b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('873cc216-3c31-42b0-a0e2-a18feec6b263', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 18).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '00c5a305e9406fec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ad078f5-f063-48dc-81fc-949cc1909010', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 18).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'bcd0aba26ab98ce1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07ed5b35-7279-4261-ba7a-f4796f567b9c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 19).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0a332591907f8a92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0799a568-beed-4573-9f32-255e50186582', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 19).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3bb6904f31ceeeee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a3bc8da-5d30-4394-8194-b3a240dc8fb9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 19).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'f80f8ba63237372c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0a0118e-3d9b-40c8-908e-dcb4a27829b1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 19).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ea2c089718fd1d78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7abb95a-fdcc-4e8e-a04d-1c096cb16fa1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 19).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'dc8948419c994267_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86385764-ca23-4545-b859-a010e86fb2a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 19).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f6495ba2d5be230b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('948f0577-ee99-46bc-966e-59cd7e7b8ce7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 19).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e3bc1875b3537f83_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('711e6f47-5d34-4f5e-8ea5-494619a819a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 19).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '25e27f0336c70606_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fe67a19-848a-4f02-8b11-94bab7d33398', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 19).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '81e0b952a21f97c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82460601-626c-4106-9f8f-20f3bf33460a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 19).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'ef228a3521bda2ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95811c7f-8ba0-4ed5-988d-d2ad488f410e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 19).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '9e472a9445f3431c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a280923-c620-4baa-81cc-fc62fc1c6761', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 19).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'abb9ba5ffaaa3855_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40d7b4d9-36e4-4aa2-8e99-1b480836e1d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 19).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6799753083196de8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c103622d-4d1e-424d-8c82-520d1807af83', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 19).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '58d9c22b514b5c6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10a2c871-6fb7-4c2a-b318-fff4269491c0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 19).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '58be2641fcba28dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9490b013-5912-4cf7-b5ab-6712f0c4f559', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.154.158.0/24 network (variant 19).', '[{"id": "A", "text": "access-list 100 permit ip 10.16.13.0 0.213.192.255 any", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.16.13.0 0.213.192.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.16.13.0 0.213.192.255", "is_correct": true}, {"id": "D", "text": "access-list 1 permit 10.16.13.0 255.84.80.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.213.192.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f06f1e2c60fbe08b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('559990a8-b897-4a04-83aa-ead16dba4031', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 19).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '33e27fde8c7664a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('058e319a-456a-4def-85c8-95612a377144', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 19).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '95ffdce353e1c40f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c8cb468-8f0b-42cf-8551-bf21e1e369a9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 19).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e3e5f5ae528b1f8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d850c65-626c-47fe-a9ed-26335a84d138', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 19).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0e5820c8c217427e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f7c9f63-e7e3-46a5-af23-6c40649b0713', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 20).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3e6b4e5b76b4add6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e98948cb-75ce-4006-bf44-069a35bbefc9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 20).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'aca161993e1f5d3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35006263-07fa-4d38-a394-92f5ea497018', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 20).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '3d2c960ff772a4df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bd08f58-e76f-4563-8818-85245452a2c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 20).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '094e0b62efc0b227_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('997de90c-4c87-4ff4-acbd-b8d957b396fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 20).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '22a6e6b38ab25a7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cae98d31-9303-42d3-8db3-985ad4813ae8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 20).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f625c7d8f6ec85e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3ede735-6579-4f35-b409-102dc798aad2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 20).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5e6e33f806bff9dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23679fb5-ad42-4652-9eff-f6c145279448', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 20).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c8758c89491c185d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ddcea14-97eb-4f00-b75a-f9f0c8f7a212', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 20).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '8f0d0ac3370dea47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db956e47-0b6f-418e-9c5a-06a2c62838a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 20).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd17c90298a00cb94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('972c0100-e99e-4e62-b580-339b00a0b7a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 20).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f03129951b5777d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('400e822d-ba4c-45a9-9ff2-ef99c8baf7c3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 20).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'bc74c5dd19b37efd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82a916af-ce51-4f83-96dd-8b1eb988dff3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 20).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '55c7533d13ce1dad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb61d528-7047-4051-88c9-3d7b707db8f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 20).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e8c02c48efd6a02a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a84a3ad3-d19c-458a-9add-b5afad052940', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 20).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '63fdd1d7271f968a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a783759a-4ef0-44d7-93d7-d9fe9f13aa06', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.91.152.0/24 network (variant 20).', '[{"id": "A", "text": "access-list 1 permit 10.239.236.0 0.135.90.255", "is_correct": true}, {"id": "B", "text": "access-list 1 permit 10.239.236.0 255.255.109.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.239.236.0 0.135.90.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.239.236.0 0.135.90.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.135.90.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a6076606c9aaeb42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb7fc009-8811-450a-86be-e8f09eada68a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 20).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'c985adbad7de5cc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0b390b2-b9f6-4da6-91d0-5d72bf5558da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 20).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'cf59e475da95a32b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4349491e-a18c-42ba-8003-9697b3ecd61e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 20).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '9ceb783330bb0fa0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73883ea0-0c12-42e2-b618-75514639bef9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 20).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '2554e10abdfc1b2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed06ff1d-8242-4da5-bcc0-af2367c74b85', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 21).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'fd1dd5250c92f6f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f1e7730-653c-4efd-b05b-aeac70d21416', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 21).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b3a0cbdfbcf1b979_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d08aa43c-4e7d-442c-b012-590d2b135d27', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 21).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '197d0631e8acf6da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29e3c8e1-8fad-481d-9075-870ad9a59e28', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 21).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '8e57956046fec46b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c289597-30a1-4d54-9780-dfd8858f1360', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 21).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4216e0b75f539317_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c78cf13-3401-4e5f-8989-928245124fb4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 21).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e7c356f3f4a5ec44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcae1ca6-5ef2-4b43-865a-91afdc1d0eb8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 21).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8b4b69081e1a74ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a64f1877-c422-4f42-b4b1-c6c9a655f052', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 21).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '226eb58f5d4a0e5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf94681b-2f0b-45da-9227-b7f1eba98bd5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 21).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'ad45fe45a86c5a09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ff936f8-d962-46c2-aee1-5ee8558df607', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 21).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '4fffb5550dbbce3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4452eb7-b569-448a-8a43-6db9bae5be34', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 21).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '88ffec5bc0bd6805_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1444bee-dc9c-43c1-b340-3ea4975d86bf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 21).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'f8ef768947987431_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bab7c85e-a839-49dc-8304-eeaa0960ab5b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 21).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8c053c285a7e07d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d273c079-6803-479c-9f60-822f1733d334', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 21).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '001d647545c440e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c737e4c-7f01-45d4-87c2-a5355a1dc9a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 21).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '41d9ef7d73341221_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5d792d7-3269-4b62-88dd-008805020e65', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.89.159.0/24 network (variant 21).', '[{"id": "A", "text": "access-list 100 permit ip 10.200.126.0 0.173.130.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.200.126.0 0.173.130.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.200.126.0 0.173.130.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.200.126.0 255.175.151.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.173.130.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c0828143ab478cfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70ddf93f-7889-471c-872d-b89d0aed425d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 21).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '92d7e267ada42144_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcdc3100-2a76-46c4-a169-35ba28f054e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 21).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '19f519f2797e8cbb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c8f2f2f-1551-4073-aa38-23b30d8d3319', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 21).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c9c2891b0377ded5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70fcf791-ba2f-44e0-816e-5f736f8bef9f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 21).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'a866d463db4afa32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a18ecd4-5789-43a8-b8d5-09b8f0bfa2e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 22).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4d20d4ad01e8280d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33600153-5daf-4ddd-ad03-987cc6ce1d8c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 22).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '663cc3c0a9074e5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae8e9626-d3b6-4a63-8128-4de8e9279467', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 22).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '45183132fd49bc31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e86e0dc9-31d8-4b7e-a31f-6a95a991b926', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 22).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'dbaa1f9b967cede9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b30fcd13-3f8f-4648-9030-4866bfa74bbc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 22).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ac69137573065cef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22d7fb0e-5afc-4172-bb55-49c492082261', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 22).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8d952d6f70532613_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7600724f-307f-4283-8108-3c7c38790b12', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 22).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '076bb76975909eda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcf0c30a-2527-4a1d-baf0-7a813c309063', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 22).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e55b9bbd1404e0ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31d7ec92-8cba-4015-8e94-152d83b9b5bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 22).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '8e20e4a47501e4f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('545ea968-fdcd-4b80-bd7a-1c49a6f85cfa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 22).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '58cdd82c2ebeb6fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e36ee1e3-fe47-4f31-abb3-354331ea69bc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 22).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '8007f2f457fb24e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6da28df0-a2bb-4689-ae5a-7e050966fe82', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 22).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '607ee6639f9c7897_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('726019fb-b9f9-467d-88c1-23dc3ccb7f29', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 22).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '878dc1465d35998d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4f3d7a1-3a51-4108-a82a-2837472bddc4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 22).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '10101511a46ee922_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cceabd22-4fdb-4e9d-a4d0-ee31a22e65d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 22).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e5b9ee8cdc1f9470_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5166471f-fa4e-4673-8778-bd953ec168fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.247.196.0/24 network (variant 22).', '[{"id": "A", "text": "access-list 100 permit ip 10.49.250.0 0.83.245.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.49.250.0 255.165.25.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.49.250.0 0.83.245.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.49.250.0 0.83.245.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.83.245.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ec8cdcc8ed079ca8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba4f5c2a-074f-47b0-81f9-dceff98bfc30', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 22).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '585831a4c492a389_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9af85ea9-1f78-4c17-aa0d-cc766ea605bc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 22).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3ec7d4baa8a78ae2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38be3310-919b-4b62-a428-2122b376e22a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 22).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '93158c01de8f5093_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('673976c1-4e1f-4050-99f5-a7d9b67d6b30', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 22).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '6dcd8d40ac94eb28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79fa14ec-2a2f-44bd-8701-c3518b224e65', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 23).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'cb531ee99cae6807_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('303a4687-c66a-43cc-a937-af446093889d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 23).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2d5b9a166fb8e029_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82fdf720-5681-4178-94fd-de1536acd13c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 23).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c48fc2b985fe3462_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c3f95cb-d19b-4645-b6df-203d2461a7c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 23).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '5555b97011e31e1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdf2836a-b43d-42a3-ae40-c8520c25f98f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 23).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e386b73d116ec0cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b482e71-181e-4843-b452-a8b959a3276b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 23).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '19202c987b394134_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd91de20-f615-4bf6-a73a-a9a732f8e496', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 23).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1b60647ceec51963_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8b65142-a10e-4e14-af00-db957a4bbce1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 23).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b44ea84b32584055_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('368340f7-b011-41b0-b9d6-d08857b0e015', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 23).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '39be37fdfa7bc83f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('380ae185-7bcd-44f5-8377-bc5b14eacb38', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 23).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '5cb74618db7fc77b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5ce5e9d-c758-4958-81fe-c90783a86b99', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 23).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '01e0127a3bf0a27b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cf4f800-a62e-4570-9686-8f5895b7c6c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 23).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '6ed701609fa4d215_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('779ea96d-85a7-4179-86f4-6fd52d8728d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 23).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'b593f106706af755_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae67944c-1303-4db1-98e4-832d3e3d520c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 23).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '158997627f439fb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61f62210-3cbb-46b2-ab42-e577926f859e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 23).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'ad77198a188a40ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf67af5b-4b26-4416-b0a5-8ef035ae0ad8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.179.56.0/24 network (variant 23).', '[{"id": "A", "text": "access-list 100 permit ip 10.247.117.0 0.129.7.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.247.117.0 255.23.12.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.247.117.0 0.129.7.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.247.117.0 0.129.7.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.129.7.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '07c19d81b7b39d2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f74004a-66c5-462c-8a8f-7efc4655bbbc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 23).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '70cc5f1ad06b9e5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ae35cdc-07bf-4e8a-9188-30dc2b3e9f9c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 23).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '48a7d1b1356411fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b2f5300-4c85-47e0-b761-da211162f683', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 23).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '825c8c9c51759d03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('233a8d54-3a00-401f-aa72-a81a673064f4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 23).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'd1c8d328d0a766ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6ddefff-a130-42f5-a384-d0b54181ca95', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 24).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '20f0ec3b5039f1f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('514952fe-3f98-41ac-a320-28d6e346f3e5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 24).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2cf6583240e7bc39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eda17853-9721-4f6d-9fa0-63cfa16bab4e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 24).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '7db6eeb6b938e995_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea051b17-9b3a-4e31-8fcb-f98aab2108db', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 24).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '9db0581457a51753_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72bd9b4a-7032-4eb6-96b1-00f5aeb0cc1f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 24).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f0383f901bec3dfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1d2bb89-a747-4fb1-8c0f-be8868d39e8e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 24).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f00321a9b57b6486_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71b87bd3-2b94-407a-b92e-dbfa7f7ab521', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 24).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b590dcae1f1be290_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49527842-030f-4d5f-8355-e1ac9cc6218b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 24).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9e7c6593f5624b7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6240935-cde2-4087-8a51-ec781da30ef1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 24).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '3eb91a06f6df57d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27e1f58c-523b-4a6f-b3f5-474dbe71a488', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 24).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'f101284454c68419_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c908aef-6768-4729-9860-efb078cc4252', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 24).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'aedfa999f7ceef1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9970aa0f-3da8-4683-bd2a-f3123f38d4b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 24).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '70f681aea9e4c66b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3106ccb7-770f-4c9c-aab4-58ca85355859', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 24).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9c609f75e5ce663e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f3eeba3-c18e-4044-a68f-f08a37bda2a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 24).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '837928406e8387ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db7adf19-d3f6-406c-a755-49978fe7a812', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 24).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'fa98b876072afa01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('babddbdc-b737-4f32-bf94-b2d4291a7295', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.113.248.0/24 network (variant 24).', '[{"id": "A", "text": "ip access-list standard 10.102.210.0 0.112.249.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.102.210.0 0.112.249.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.102.210.0 255.60.7.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.102.210.0 0.112.249.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.112.249.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '709393d0746061a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb5fca8e-1c49-4c68-9c75-fd46418f974d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 24).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'c11618c21f69dfaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03716b87-dbbf-47f9-8ef3-4096ae3a1ce6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 24).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'de3e22db900c419b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a779951-9f83-4119-a6ab-7ceea54a4bae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 24).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ff4da11230e21f6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd90f769-b403-4552-9303-5ce8206938c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 24).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '404328d92bd8b219_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9df12337-16ef-423d-b855-245dffd951f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 25).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ab749c014352ce0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6a1da9a-1ebc-4c93-bd83-a9b121411ca8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 25).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f49e3ac8f6f6c1c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d7d10a5-42cb-43ad-a53a-3d96ff95033d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 25).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'e2d8780112884ece_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4425678-71bb-40ee-be14-7b50332699e4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 25).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'bd55b00610a7ffda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbdc7dc3-7a73-4c47-a7ac-00e73f449631', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 25).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '484970d689617930_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d34fcbe8-c857-4690-9fc8-02a55228604d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 25).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ae0743b9d4fc777b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4f2531b-e207-4805-a247-e979c2cf5e7c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 25).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e9661bc96a3a7727_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2bc504f-22ba-43f6-a31c-46588fcb0587', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 25).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b24735302f272f6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddeca37c-550b-4ff4-bc7b-4cb123a421d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 25).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'adcebff618e1ac14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73e759f4-f9dc-4606-9bfa-438ee0e67704', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 25).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '9059788c02f149ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29e67cf8-39d7-4760-9f74-0e079e6a1974', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 25).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f99f07870319656d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bf2b082-b948-4936-85a1-7b771ad67281', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 25).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'f1151ef376b26f22_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e0cf6ae-3189-4712-b0c2-89cf46565839', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 25).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '866fde103cd0258b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('763a3277-63df-40ef-8ba7-d1b239e111a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 25).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'cfe8196558c9ed88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfb9e6c1-e6d9-456e-83bb-80a7ecb16fe0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 25).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '1f65037de60f0dea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84713e7b-4fc1-4be0-826d-cc2f32f7e7d1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.82.193.0/24 network (variant 25).', '[{"id": "A", "text": "access-list 1 permit 10.76.23.0 0.71.53.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.76.23.0 0.71.53.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.76.23.0 255.14.156.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.76.23.0 0.71.53.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.71.53.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7ccd524caf78c14e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f5c01d5-45c3-407c-9c30-ee73608ba278', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 25).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '45a5d4cbb9c4dbc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e541506-87db-436b-b541-66eaf297764f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 25).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9b074a7828cc3cda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb70efa1-bb9e-4465-a5c1-e8b30419c1b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 25).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '16cdea6b74600c26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f1f2a38-d19b-4721-bd0f-30313461adeb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 25).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '349935960be2e029_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4f4cfed-83dd-4118-a6f2-1ed61cd5a089', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 26).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c731eb83055e0e4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a966649-cd81-4f3a-9624-960f119d37a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 26).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3b54c474f7e6c076_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('488956f9-41cb-4ea1-ada9-3be8888fa6f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 26).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c3bb4356dd5b9ad2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfa97778-3501-4d31-8f6d-54225dada3cc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 26).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '30d45377a921ae6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66663085-e0a0-4ade-a3eb-b53de0aaac67', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 26).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6ffbc93ad2285702_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b581d9b-13f9-40ed-95eb-e75aea422835', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 26).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '480d21b96ae4222b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('925bc2c1-007c-4c33-8955-00b2ed3f4842', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 26).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3c727bcbef65c1c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5c56cea-e9bb-4134-bccf-21b45effa6af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 26).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '32a84f34dea409d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35fc73f1-762e-4087-bafd-cff2d8e32bf5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 26).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '0dac1b490da2502c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('239b96e9-da5a-4c23-acc6-f530d41519d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 26).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '081fd4bf07a83660_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2cc888e-f609-4675-bbce-a74361fce05c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 26).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '62106b007321edd6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('291764e1-e7c9-4098-aae2-fc54f8027657', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 26).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'b96aa983e536e2c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('936ee37f-e9de-469c-ab51-6385f3d18e51', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 26).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c9c270b06a52d13c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3af23448-d804-4408-98d0-1f4157901e3c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 26).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c8bb3630f21e6396_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3635a7c-fe63-4aa9-9eb8-aac9c3399fbb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 26).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '2e60f0fa12a48f7a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cc05a84-a4ea-43c1-9d80-e38d6e49c3e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.6.40.0/24 network (variant 26).', '[{"id": "A", "text": "access-list 1 permit 10.64.49.0 0.239.101.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.64.49.0 0.239.101.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.64.49.0 0.239.101.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.64.49.0 255.86.108.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.239.101.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd719660e9cefce57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78d36b94-6e6d-4225-bd4c-b8c2c04691f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 26).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '2bbd3c237a5be465_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bd64ff8-e838-4a8b-b395-05678d87a304', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 26).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '81f7f9886ef59793_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e49faff-8372-40d4-896c-db5be2ea5542', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 26).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e4fdd0feb51e4c59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83a8545c-0331-4657-84d8-38355114cd01', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 26).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '64d7b75a5d35412f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79187523-2233-4917-b625-7f832513dc66', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 27).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8b712efc8abf8d52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef9ecdbd-0380-49ea-8ade-74312bc15da3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 27).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8ff46eaecef4e366_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e271242e-adb4-40ec-b617-2ad38abded71', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 27).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '90daabaa07720028_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77d08d61-7e0c-4b80-a4ae-5dfcf2723ff2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 27).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '0702d04b64eae3f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af955550-dd17-4787-9374-e69cb8a93811', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 27).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4158d2f457c14231_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('990a5f8e-154e-4e18-8b4e-2b483df4eeba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 27).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ed4f71f4a643f8e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('389da638-21c8-4338-ace7-6f334b80551f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 27).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c4689202e6d136d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3c5a774-a500-4327-9305-0544face2d50', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 27).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '685609eca6fd0779_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfeb587d-4193-4fab-a4e6-017e5c1641f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 27).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'e63cf8bcb2e7dc27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('423e9376-c773-434f-be78-fee76d969ce3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 27).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '8f77b27369a69393_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92e0bb89-9c68-4863-aab2-026156f2720a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 27).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '02e6aa5f983e2661_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1436619d-29dc-4b4e-80dd-bc91dc7c8360', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 27).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'a111f741ff33e441_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7be0e488-70ab-4155-8f9c-385d14d84cc4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 27).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '042047104f5bfc0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73c1d310-0144-4f70-bf5f-1ad286f59f05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 27).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '29511922b2dab800_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43aa99cd-7aab-4ad7-8207-ffc04d71cb30', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 27).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '2f7af6e292c82be3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33cf9207-affb-4e06-873b-c6a822c542ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.238.212.0/24 network (variant 27).', '[{"id": "A", "text": "ip access-list standard 10.56.12.0 0.94.189.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.56.12.0 0.94.189.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.56.12.0 0.94.189.255", "is_correct": true}, {"id": "D", "text": "access-list 1 permit 10.56.12.0 255.27.141.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.94.189.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'eb09e3562630a08d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e9721db-536f-41dd-9f40-1818257e636e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 27).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '2c4244a336691454_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a8aa215-4682-4578-9f26-5dceec595790', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 27).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '580c3177c9eea558_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('874ce848-6e48-4ea6-8082-6b627b7cdc03', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 27).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '6bbdcb4289fbe671_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2087e9a6-21a4-4e4d-8bc1-fbec63a3db6e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 27).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'b9e9d2f0e624cf5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3647c15-0ff2-41ac-9a9f-984afa5e1b21', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 28).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b65803138c737ab3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('855a804d-73ca-43c8-8e4d-2e5b034e10cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 28).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '16a31036ae9a45d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('100e0158-8b98-4817-95a9-993b7875f87d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 28).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '80fe558e7f99f6a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1b0bfa4-b638-4de0-aca9-70158f06695f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 28).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '4809b084ac2ffc92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7dc9eba-88ef-493d-8720-59ab29860c95', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 28).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2c2f51b440a3b263_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3fa55f3-8cb4-4cd5-a031-384afda524b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 28).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8aeb908173b4d96e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('933df990-a4b8-4c03-9b54-be5eedb91007', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 28).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bd5b567b72c48c4d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38cf300a-2bd9-45ae-800e-f2bf05a7806c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 28).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '831b281fd70a5741_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6379ebc8-42e9-41f9-a941-a2b363bc3fce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 28).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'b59471ffb5cfb273_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a15a040f-35ba-4a4e-b052-a4dc164bd3c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 28).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '67bc10045a8077a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('422ef732-8787-4f78-be6a-28d082e1d1c0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 28).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '096f50f867f7d201_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93d005a5-8226-46c3-8ec9-5bb8cac1ded9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 28).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '3573eb182cb1d17d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('446928f5-1871-4268-956d-85f86b4b2994', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 28).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '78b51e7bfadd7357_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57eb52ff-ff48-4b52-9192-74488026411d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 28).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '91accf3ef5e9152e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('815f1d0d-aaed-488a-af19-2d7a93d921c1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 28).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'fe08b6ff29e786f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8c0b3f4-5455-4e31-b0f1-69df1b8c7cc9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.229.156.0/24 network (variant 28).', '[{"id": "A", "text": "ip access-list standard 10.204.101.0 0.109.58.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.204.101.0 0.109.58.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.204.101.0 255.8.87.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.204.101.0 0.109.58.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.109.58.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f07c8f98bd5bacd1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50b32721-36fd-40df-9f2e-abef9a22b0ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 28).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '385674ad56c04759_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68131090-43ca-493c-9a8e-c87a269d4961', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 28).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e3ab0e6263c70bd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bad92fe4-6c79-4d9c-9a8d-e8497fe8871f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 28).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '8c217a2827563fb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae7ebc68-5610-425a-b6a9-89bf512da251', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 28).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'cd16a8d6d046b33d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9aaf43f-1141-4498-ba3e-7d70a27b3113', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 29).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e544c01f4661f877_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ade541a7-e5d0-4a19-8c21-320939c6fcc3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 29).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1c1060dc059cc0ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8615a3f-c184-4001-b9c3-39c11d45c05e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 29).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '3b0dbf60ebdd9d95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d98c45da-69e8-4a53-ae66-0936ae620bfc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 29).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '12cafad7a08ff423_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6796351-8f0a-4017-8a34-5f6faab3ccdf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 29).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '12e5881a4d4bce70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e43cf4c0-d4c7-4d21-a02b-bdd39df47bb8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 29).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd6d34095cebb8a34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08dfbb18-e02b-47ba-b0bf-c21b50cb866c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 29).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0261d4adc58aa4c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('129e4bc0-880a-41dd-84f7-87a220e974b8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 29).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '09480a51cbcd1785_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a8f1efe-46dc-4694-8b3b-4011f0e93e6c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 29).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '7294ae0ab09e9cd4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88e84780-5049-413d-b738-e1076d8e065e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 29).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '717d9ab366bff1dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02e1be0b-ab6e-4630-8839-07a27929dba9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 29).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '6f4f1216ef0a090a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('624c1297-f286-4f26-ae0c-2546d7e617c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 29).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '00fc6495f06fbacf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8322f527-3e0c-4d52-8bcc-34ae9f5a3e31', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 29).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1b143ad6be578838_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a65ad223-6526-458d-bc22-9600d15538b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 29).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8e6f8ae1f8613ae2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba4edc20-256e-4575-bb0c-5f74573233f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 29).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '47db18534ddb0ae2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc06bcd9-1b8c-4326-b7c2-14a9824b760e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.25.153.0/24 network (variant 29).', '[{"id": "A", "text": "access-list 1 permit 10.16.120.0 0.62.217.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.16.120.0 0.62.217.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.16.120.0 255.66.246.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.16.120.0 0.62.217.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.62.217.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a45ed3f5d1375c6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d54ae795-162b-44a3-bee5-d9654a69365f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 29).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '401b75f946c89c93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f834300-56c1-4d62-9c84-3ea68ff925d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 29).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2913f9b01cf18377_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('054065bd-6582-47fb-81a7-28e24cf91248', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 29).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '95ae95bb74af9a97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('756ad143-1c16-4260-9778-46a8e6c9fc37', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 29).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'e3ce047bd01bc707_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb039e54-dabe-4968-9d35-1af3ed0418b8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 30).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a001afb761087c14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c38fac8d-a2c3-4faf-9afc-d01ba9456271', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 30).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ab5eb6b6f6214043_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14b09225-2915-407d-8c65-2f89e46cba53', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 30).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '91a43dfe06afbc53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9730bb94-be06-43b7-8756-2487ee4e39a0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 30).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '8fd58616d969dbba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7829e229-b10f-45b5-9e14-ee355bb900f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 30).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e90417851a9a7324_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdf0dfdc-8e3e-489b-b083-eceba2b7456f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 30).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '56bf6414faa1154a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2401b27e-c5f1-4fd4-957a-2870cf0f97e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 30).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8139b4e1f92a5d54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff95175b-2894-48d3-9774-816f5105badc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 30).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bedb04f8c581752d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de4cfdb1-dc1d-4763-ad5d-f14d764cdb5c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 30).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'b456aa24493ae59b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af7371bf-388c-4a71-82dc-6c56d3bb5694', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 30).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'b1d40d6635a2fb7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('620cee54-d2f2-4864-8efd-d93dfd47a9a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 30).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '97a3a2b6a02d701f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25d07201-b87e-498a-9933-c18e6fee2c00', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 30).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'cc68f0c70778af4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d357bcc6-7787-4aff-ad65-ea2b01444983', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 30).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f2883aea13483d6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00e21eba-90d9-40ed-89e0-67ab209c8390', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 30).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3f419e68352edb9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3e2ae80-97d6-4ef2-aab9-2e79750bc8f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 30).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '8421452a9dad21b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('289f9423-6d71-4606-891c-e0c5fde81ec7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.58.114.0/24 network (variant 30).', '[{"id": "A", "text": "access-list 1 permit 10.236.181.0 255.50.130.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.236.181.0 0.71.184.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.236.181.0 0.71.184.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.236.181.0 0.71.184.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.71.184.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b5efe9175ae6a381_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('384d479e-5594-4eb4-996e-3a82239b89c6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 30).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f127ce64aa0260af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b310302-d764-4d82-b4df-0be1dc7483d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 30).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'faa66abe6bde8563_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb1541bf-1816-4442-b262-6bc9863d0aed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 30).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '61d927de33515165_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3692865-f759-46bb-83c4-2035ece87ba5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 30).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0be001040ea85288_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24c55d7f-a7a4-4a5f-875c-f291258fcdfd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 31).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f748a2e50075be90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('627affc3-c84f-4ecb-8938-24fa2c757bbf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 31).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '39f0277f8a2f94d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0d2974d-096a-4b91-884a-7d7f0a0b1d51', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 31).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '9776e7c3eb17ccdc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ecbca72-b9a2-4901-8a11-9ce3c7b9acc0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 31).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '0e9dbe9fa8ae544f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1c7fe8b-4093-4b1a-9fd5-0b4aaf333694', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 31).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '56b67aab3cc55430_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84d5fd50-61d2-458d-87a7-ccfef3929a37', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 31).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'aade5f24cb64c7ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42b4a59c-df03-463b-859e-8bbf69b3c9e6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 31).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fa1fc6b2d0363f8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c52beeca-9ffd-4ee4-ae57-0255e1fcab28', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 31).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5d496dbf4feb1ed6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca9721fc-612e-4108-8088-fa36371ba43f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 31).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '46cb571201787c0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8c8b9f4-c852-4726-845c-7e27160c9af0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 31).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd0043b7c4b1bf765_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73dc3679-6977-43d5-b07c-a250ada86345', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 31).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '4d4a9d0ca4c0807c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bdffcf2-14ef-47bb-a648-4d2edee1382f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 31).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'cb2af4f3158b42b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9ed3513-ed03-4cf9-8072-9ccd734d6191', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 31).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1fe848fc75be916c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d75846d-8799-496c-bf8e-5fbdcf5cbc0a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 31).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8b6459822e05139a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69c0ac52-a654-4b1f-96e0-75b6b9d21d0c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 31).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '5fa0d7f2bfe12aec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a14896a6-a4a3-426e-939d-d2847a508fe8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.74.5.0/24 network (variant 31).', '[{"id": "A", "text": "access-list 1 permit 10.227.113.0 255.57.215.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.227.113.0 0.255.244.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.227.113.0 0.255.244.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.227.113.0 0.255.244.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.255.244.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd12aa83f573df18c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b87b968-827a-40b8-ae1e-0659153f27ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 31).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '66a54eba627d59fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24ce5916-ed47-4864-8e20-06c7b5acca33', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 31).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'cf3aa1101cd427ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6931a80-ac69-44b8-b20a-39f5818a563a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 31).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '18b17a37b0a88a48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29a2101a-969a-42cb-87ce-837ad9a22d42', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 31).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0a33bb8bd27d5b0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfc7c593-7411-4753-90b3-d718c81df439', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 32).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9dfe35ede4745b6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86d48894-295a-42f9-9773-6c6272b021ad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 32).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e742a2ef3cf00343_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b21a98d0-724a-4a7d-a813-ddebaa99bd19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 32).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '8ca5c01934761c80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73b82d66-171a-4146-bdbe-62bc4caa897f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 32).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '703c116d302cdb77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e282d83-dbe6-41f8-bcb8-9df6033cc1c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 32).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b9cb51883dc383c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76e729dc-1a74-4bad-9880-9a7a4b75d348', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 32).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3c13a0cb6caf0554_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d934976b-e6b5-4676-b39c-01c74b39d050', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 32).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b90900263d4a76c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b01da501-4e99-4b57-87b9-dc51d841ec81', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 32).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '26668e4a11a0d72c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('036451b3-b0a6-4052-aac1-ba3f6f5284da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 32).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'bfe03639bdaf33d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1eb411d2-b43b-4094-8e5d-269ef500db4e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 32).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'c0a0b0f06a8f75ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0f7ba63-c8e6-479a-b6e1-61a37b0028dd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 32).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'd8c12b88df383198_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a92dc3c6-2ae5-4805-8e71-7bc456e89773', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 32).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '054a1e4e3a090665_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f6ead4f-9098-4a3a-9d75-00552a658e06', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 32).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '38f760f81a22fca7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13c130d5-bfd9-4b91-9508-ba286fc8acf0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 32).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '887f6d855fa41205_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eed21d40-d5a1-42ae-98b0-17813376c429', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 32).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '8b20a3cca95fdefa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('209bf986-6d76-4d6e-b785-981016d6a964', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.212.250.0/24 network (variant 32).', '[{"id": "A", "text": "ip access-list standard 10.16.93.0 0.215.150.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.16.93.0 0.215.150.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.16.93.0 255.156.137.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.16.93.0 0.215.150.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.215.150.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4d1ef91c71d41a28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57df891c-dbda-4f4d-a2a8-8278d4b5c958', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 32).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'db5f3f5cf0f34d5a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('527d0707-9efe-4f82-9b5e-703c9066114d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 32).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd41c0254d9d5a77a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5c72b37-9639-42e7-9918-ef7f39c4d765', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 32).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '09c258af8428dea2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9b8ba8c-0a1b-40f8-aaca-8dbb4dbfdc25', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 32).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '4e0965bd0c19464f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a954a50-4588-4ffa-a565-b3bb9795d5d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 33).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a5713d53a6635cac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3af096de-4f7e-40dc-86c7-2bc9b9b54359', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 33).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e681178d51a576cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b34d038-6aa6-40d0-aa36-397c50f6bd53', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 33).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c3cb73d8e94154cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f532900-0264-4095-80c4-4178ae1ccb0f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 33).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '5cb9cf8c4f7eba26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c532479-e6e3-4f14-90be-4592030fbf12', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 33).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4237fe6ff5a6c0e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('264ddd38-4c83-4556-b39b-59d62bb3697f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 33).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5005564f076c7557_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ba87603-fff7-4fad-a2dd-129bf3443ba9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 33).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6b3f3b1bfc8bb169_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d940bd2-d77d-439d-92aa-ae1df2d167ff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 33).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5af78e8f063bacfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('538a4f82-62e7-45ca-bd3a-4a10b2f40bd6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 33).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '9af3e6d0220b5e4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1305d621-77ad-4f13-882d-e15a85d941a6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 33).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd911c67facf189b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18802ec5-ed3a-4e68-b6e8-a3634d37c58a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 33).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '3e9fd11cb17f78f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a1c8f05-54c0-4b1b-b556-daf4f27719a0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 33).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '2b3f72e57b51ece8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cd932cf-e760-412e-9c91-07b808cba7ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 33).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4281970bd40dc8cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34f9707c-e188-45f6-a636-ccd37cab0751', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 33).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5b1c4e17161c7c0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8da8785c-02f9-4afe-bbcc-4955959841cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 33).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'b676868a0fe6e62f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15b09fdd-4d3a-4d61-a1df-66717ea78bff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.39.62.0/24 network (variant 33).', '[{"id": "A", "text": "access-list 1 permit 10.73.221.0 255.134.255.0", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.73.221.0 0.215.153.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.73.221.0 0.215.153.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.73.221.0 0.215.153.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.215.153.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7f9269694681b1ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99ebc483-6909-417d-ba82-0a268351e455', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 33).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '8e144dc2c10fa812_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('993c9a89-3023-4667-8ec5-0bff13ffe46e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 33).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd50fa3e16ff7f4d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3ca2833-b691-4a5c-a5af-20f9a512a590', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 33).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '56cdf8ffb5cc27ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fab64fb3-3c98-4cb6-96b8-a31bd309aada', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 33).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'a3e0e51ff5726d15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('660a6d2f-c031-49e5-bf8b-125007d61d15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 34).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'df7c61c4bbde6f8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50104040-c244-4ace-ac83-ecb3807579c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 34).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c8b3147098e43d06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4b9306d-4c24-408e-a95c-675502e23af2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 34).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '86138faae5d797b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b156b94-89ba-437d-b98a-647e93738531', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 34).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '8d5619f57980d775_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd4c36ed-4370-482f-a4ff-f5d53ae88f3d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 34).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '20ea9ed80912c7bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36df4b8a-1991-4e20-a5d1-7d0f9f85ecd3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 34).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8de37798f7df2065_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dc94a70-42b4-4f1b-81bb-3aacae6a181c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 34).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e3465b425489eb00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f55e1727-f2c6-4f15-a734-a5d55944a8f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 34).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0896b9e91cbeaded_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1e3284b-940b-4321-a583-0040836c0120', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 34).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a55dadc50deb20de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('582aef79-7759-4622-a097-e9ad30578b09', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 34).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'c23706257dac0d13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e2d5a1a-9d28-4c11-ae97-828298975291', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 34).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'c362e610cb1081d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bef45c99-55c6-4fba-a4b5-c87d55cf56c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 34).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '966d653382e928bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76b01d1d-c9d1-4bed-9d31-161314d3a6d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 34).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9911ab95162eabd5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da4a6a9a-8416-4eac-9f0b-303ec4394d95', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 34).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '05f6602ef1ab7659_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ed20119-ba33-4b06-bb15-4013ee04d6d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 34).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '714e6dc2eb87eb12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8ed6acd-74af-4e44-996c-ceccdad19998', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.187.140.0/24 network (variant 34).', '[{"id": "A", "text": "access-list 1 permit 10.61.16.0 0.129.27.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.61.16.0 0.129.27.255 any", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.61.16.0 0.129.27.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.61.16.0 255.27.127.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.129.27.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '49973b4a49ba8bdb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78500ed6-fa6c-4749-a46b-2d15120856c5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 34).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'fabe7579e406762e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90f66bd3-6e32-4b67-a93f-156b491328d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 34).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ca0740fa8024414a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb4a1631-c000-426e-8fd4-967654280e86', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 34).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '9f675d7d26d495b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d37ad32e-be28-48a5-93a2-c2d9fb8385ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 34).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '7db3414ca0a00e00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47a5bade-500f-495b-9b11-0312b9e411cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 35).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '7b8566418dabc2bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76cfadd5-0e40-441f-8a49-60ed3bd2611f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 35).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '97c376beeab7c003_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e80b531-a1e2-4216-ae5b-faaff2daff51', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 35).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '8066bc178ad61a2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f390101f-e319-4cbb-a17c-e5c6dd072a94', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 35).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '9976fabe1b86c2e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb25e746-8a71-4709-aa06-a26296503f84', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 35).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '01cc17c6b44e8d4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d902cf1f-140b-4795-bb90-06500bcf14bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 35).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '29ad41bd49a8f3a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c2faaf8-ac8e-4256-a304-a04615dcaf33', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 35).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f36d937d7a351968_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('512f7d61-b7b5-4ac6-a279-d57dec3d79de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 35).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0d1be2f177ecfbd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7f61065-e16d-4a21-9c76-eb978adcc43d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 35).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'e40eb50f9696638d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3c8dd9d-ba61-4d2a-b22f-f2519ab7bd20', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 35).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '8aace2142d41e1ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bbe2efe-9b37-47ba-9a20-ce67242aacbf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 35).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '1ff47bc63119bf97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ad3b14f-0568-4df1-826c-2f6199c0e8ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 35).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'd54fa9bcdc9aae42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a71e030a-7c04-4b87-a994-4976880616a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 35).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '48937edfe65f77b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f900b66f-c355-4da0-a186-69b541afa801', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 35).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2bd67ee38cd8457e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12cae7f6-6542-44f9-a5c0-8e32371921d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 35).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '54aafb8cfe858f69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e34ce4e-768c-4975-bce3-71c9590046a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.98.5.0/24 network (variant 35).', '[{"id": "A", "text": "access-list 100 permit ip 10.14.23.0 0.213.235.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.14.23.0 0.213.235.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.14.23.0 255.158.62.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.14.23.0 0.213.235.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.213.235.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '36adbebb147a0da7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e258728-5cef-4747-a2f6-b0292e09cd50', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 35).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '258b5471fb4ac647_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('818d91bd-e769-4807-be1d-bafa584eeb77', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 35).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '95fb17bc673007b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be1e7766-3021-42a0-8cdd-1a99ac2e894f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 35).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '2712cd0eee9171fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4511c2e6-b65d-4fda-b180-16905eff6acc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 35).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '3f40eb2cf943c229_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61b72e75-abe2-4208-9237-1dcf8758c34e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 36).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '31e9973cfc10a70b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('350324a5-07eb-4864-af05-fc0546cfd02f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 36).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2b95754e8aa158d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b5167ea-5165-4f01-ab5e-0d7023787fd6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 36).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'f94f70c9a8457717_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b791f67e-a361-4db2-8dcc-9f8c8b9a8d4f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 36).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ae70e33bcaae0813_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28287b25-4585-4970-b80b-f67c5d715046', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 36).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3721bf5fd8737a2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3eb4dff9-d72b-4a9b-a21f-34f7bced45b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 36).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9b5f28d70793bfb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cda707fe-1b87-4557-ac8d-222dc22e0046', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 36).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1b0648e4a9de4faa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6080927-83d9-4c15-8a94-0a2f77724bae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 36).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '105dec48407f309a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2961400b-3810-4bea-be26-284c9f3b3831', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 36).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'fedf10797f244886_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50b5a8ce-621e-4632-8f45-d5ee1304ff62', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 36).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'b41e882a24b24a1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6aabf561-5241-4e8b-80f5-0d7b8148f261', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 36).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'e726e71fe2165cc7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc7be14d-be4e-4cf1-8cfd-1bf17e65fd2b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 36).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '87b8f54de8dacfc1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d05de3c-345b-4baf-b6d5-b4d4fe03dc20', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 36).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'bfd4b05afab2e8aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5325de2e-e759-4471-8c29-ee3055ec641b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 36).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7bda527d5184c2d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a911c8ce-6e12-41da-af3c-7fa009402525', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 36).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e7623e2923a5444e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16c214fd-3193-409a-a093-d9c19a1c9eef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.43.19.0/24 network (variant 36).', '[{"id": "A", "text": "access-list 1 permit 10.124.12.0 0.120.191.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.124.12.0 0.120.191.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.124.12.0 0.120.191.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.124.12.0 255.101.172.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.120.191.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5073543175ccc344_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bd21a83-cb21-427b-88a7-155315446b19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 36).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '2c348bdbb8839a00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('338fce45-be98-4acd-9145-6e6b896e652d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 36).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2c8bfa89598999aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2092b34b-0e3d-4503-9d2b-831a754de551', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 36).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '3e2b15e29bf7f22f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f13e5cf0-b6fc-42ef-8c25-935c934cba33', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 36).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '4451b776bed87b2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fd02a33-1ab1-47f4-b78c-afb3d187f043', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 37).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '075cc15057a54254_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2e2746c-5e7e-4642-bb52-b3ea0e746b4b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 37).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd38f612a40248876_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96d2e9c0-abd5-4793-a08c-da334707e487', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 37).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a31353bb89f3ccfd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efd404a8-b031-4dfe-bd5e-be3ade2d3de7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 37).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '7ee1f9975f71ecac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0dee379-a858-4145-97a5-07542d7b8558', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 37).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3dbd44c18b905383_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('facb4190-b47d-4f40-b8ef-4630db66ab0f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 37).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '602633aa8ba2fff6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('515a484b-6488-4695-863e-6c083c75895a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 37).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '63afb8002d1cfd7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('210c87ba-e325-4e9b-936c-a0bfd027cb76', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 37).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '02ba13c163ecf1b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5579e61-3659-49ae-8e76-2cda0e87e0bf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 37).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '569a63120c73e8e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cae2728-d9ab-45a4-88c6-2090fd6bd8e0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 37).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd054947a61578150_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4523058a-79e7-4306-809b-4ecfa452d57c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 37).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '466f693f916ca485_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('703a6d7f-ffaf-45cf-ad1d-7f98201c9078', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 37).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'fbc468e7e6e0f555_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2ca8259-24d8-4c14-bd45-8af7d2d326b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 37).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5a7c91d79c2bc9fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1302369-23bd-40a6-a587-8fb5cca5fe53', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 37).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'a5e54e968aa4083b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd380049-2301-4c22-af6c-82ac6f1db4dc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 37).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '17cd57181dee4df5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39b4c663-faae-462d-a2e2-22e9b38f3406', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.251.185.0/24 network (variant 37).', '[{"id": "A", "text": "access-list 1 permit 10.149.76.0 0.109.182.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.149.76.0 0.109.182.255 any", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.149.76.0 0.109.182.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.149.76.0 255.210.97.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.109.182.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4dbd1ff4b6e84f71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc05eb01-7d63-4ea8-ba41-3db775b4b0d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 37).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'b6fd70026b93cafb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2cb0f02-a053-4f4c-ab12-7a151253b3af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 37).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c9f993c3f31f79b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('077ce980-25ac-42c0-9287-59013952706e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 37).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'db0184614422297f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5630e3b-0486-429a-a1c1-02bb739159a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 37).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '3c6b2e8353da269b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fce64c1-3e85-49e4-9908-1d9c61c5f060', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 38).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '14744b3b2aff2b5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1dfbc951-b4d3-4995-9a54-2d2adb968261', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 38).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b8f0880b63ce6fc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13576431-cced-4087-a2f0-e0ca4a625491', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 38).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '634c70a4961d5244_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('914ff841-a689-44d0-a840-cbf9af3e81e6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 38).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'b88d45cb57b8d682_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dc4df73-90f9-482a-8037-8dbf3279dc7e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 38).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4adc55eeb06b826c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21ce756b-88bc-49fd-b1e7-fe7f8a0db58a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 38).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1101f9b7f7721957_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('309a63b0-2a91-44fb-8efc-ee2d8954cc62', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 38).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2563e5eafae4134a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd9e1255-4083-4196-a21f-e90d4f7c5dae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 38).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1eee3d5fe782cc79_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0aac3418-3d10-41c3-90b9-155035a20833', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 38).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '8c24061c0b6c8a0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47a29cda-d6bb-4f9a-a4a4-948ddb28d7c1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 38).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '3a11409c8e80d94e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aae90e79-d1e4-4fca-abf9-7a912f4c87d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 38).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '11286c7c05a8f738_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c23dabe-c269-454b-aefa-7f117a0ef6d2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 38).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '732cf34c984305fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('054c728a-0f9f-4d70-9857-345416781141', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 38).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1c7f8538a3a5cd8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef53246b-b53b-4131-ba1b-0454181f1a36', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 38).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7bf4065595ba39b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('083884b3-dc38-4a62-a166-70bafd096802', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 38).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'fe0834a5081c81c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f564415c-2ea3-4af6-95e8-e0f9067953f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.115.213.0/24 network (variant 38).', '[{"id": "A", "text": "ip access-list standard 10.56.74.0 0.78.175.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.56.74.0 255.224.104.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.56.74.0 0.78.175.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.56.74.0 0.78.175.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.78.175.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0544c92c44e9557e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f7201ba-14a7-4e04-a2f5-c382fbb0a753', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 38).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '346a6637a2cb73d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98449b57-1be8-4cbf-a286-ea116bee7ffd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 38).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5c5d50c0ee770cb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dde3ac0-3044-4516-b5b0-dcd14d0bbb73', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 38).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '0379f893a649ce7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('751d6fe7-8c9a-4e71-9c22-f014542e2397', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 38).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'b2ed086707805011_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a23a47b-1b4f-48d1-b096-83c1075e77ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 39).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0d2b38e04557fc6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dd52ce2-dc4e-4d45-b3d0-856359d96aae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 39).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c62f906affcbb7da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec081472-8716-4533-8a3a-2ab2629c12ee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 39).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c985f4e929d54805_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b23a94f6-f2fe-460a-9de0-69d4bacd7896', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 39).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'f75e435ab7d6e924_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8516b742-a7d4-4e5e-a704-a519c38b4e3a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 39).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '570f9a17686c39ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('046d0d29-9faf-48c2-a3d0-ef92107637d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 39).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '820c6f0ad79d8d8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('600d43ee-cd30-4240-b7e6-df4c9b6f8d31', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 39).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e79bf2d0b2cc1d1d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b54ea69-ae88-4a61-b564-bede79a9824a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 39).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4359a2cc2d6f4788_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25220cc6-dbd8-4495-926e-ac5a4211e9ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 39).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a9058df732bcb1a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d94ed3e7-c889-432c-9e6d-5a1ed5c264f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 39).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '99f44d77fd45f974_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb7c736c-c91d-4adc-b497-460d35700589', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 39).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '4afbc9b6c0a070f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('810026ec-0b7f-4557-8840-4ab566ed40b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 39).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'ca22c1852a0b42b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64b7cac0-3940-4056-bb56-6d114f67fb3e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 39).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '17893a8c6da63c03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b16237cb-4658-462f-ab9f-a4dc62a63648', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 39).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '0a4734a8d6be78ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ec45647-e4da-4d64-8abd-5e1ad6732923', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 39).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '1d24afedaa58b7c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a544a81a-d232-4b69-9654-211562a67761', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.196.56.0/24 network (variant 39).', '[{"id": "A", "text": "ip access-list standard 10.115.52.0 0.120.147.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.115.52.0 0.120.147.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.115.52.0 255.60.101.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.115.52.0 0.120.147.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.120.147.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '481660f99001633f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc1e55f5-242f-4e2f-9da5-62db7e7dc7e0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 39).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '6576b81fd6951893_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4ff92c0-949a-4cdc-a9f9-e7d76ba9b92c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 39).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '359f8f8284747e3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfd1d1b2-236f-4044-bde6-792a26543adb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 39).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'd04de779e9d7620a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b6061cf-935c-4622-b852-8d62ad0ccb56', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 39).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '8e91dc930fa723b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('389243a4-ce0b-4c5d-bd78-7315d99445b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 40).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '429a43e4d9a813d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67bb1258-6daa-4897-9a18-75d721a24283', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 40).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1dee1e158c309beb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e052d045-6c3f-466e-8f7b-81b48f6823cc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 40).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '12b9f4533fb33a1d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43dd78a5-91da-461d-b800-9378e91939fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 40).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '85abe80c2966a4b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afdd17bc-2130-4903-b012-315ad9b06866', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 40).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bd53ebc8be7da549_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e40be9a-87fb-43e3-8132-d305d477b6f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 40).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f3ecb8739f0aa175_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7598ec74-d57c-4700-af08-e11c622a147a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 40).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9dc45d94f2505a0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cb90651-c508-457b-82c5-16538d09eb8a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 40).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd540dd6fccb6424e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d5ddafa-bf1e-44b6-8ae9-e618adda9b69', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 40).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '0a4e1b01f96a95eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27ee4276-2d43-4426-bf3e-7d3438bb5a08', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 40).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'f2a5851d8a140515_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da0ec440-11b6-4a6f-9d1a-70caf957240d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 40).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'a0b195bd229708d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9774fc9-2aac-4027-88a5-807e48559645', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 40).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '91a827958cd963d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdb230f7-9823-4feb-9732-905a2ad247ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 40).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fed798095b010488_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c99ec1a-8ab3-4005-9824-2605c92512cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 40).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8f935d59d301c303_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc9dd010-3775-4b68-a6cc-8cbb2f403116', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 40).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e9c4d50a5f371179_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b91cc81-964c-4831-bfce-6077c5103446', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.35.8.0/24 network (variant 40).', '[{"id": "A", "text": "access-list 1 permit 10.50.54.0 0.91.235.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.50.54.0 0.91.235.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.50.54.0 255.69.86.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.50.54.0 0.91.235.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.91.235.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '6f56cbbb590791cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86da63fe-948a-49ec-8822-8a7630a7c596', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 40).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'fed89d7eb6196052_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('008f972e-f8c0-46ae-9b74-fce1aa80bf4c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 40).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd04eb942c9b7502f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91e31df0-9728-42e4-973c-2161e3913fac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 40).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'af0999b22c4ebfb5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfc34854-b7e5-483c-b612-aec8faf11fb1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 40).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'b7ee1e0ac86f3caf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aba75b00-afc9-438e-be3e-0c6502c564ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 41).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3693549d32d26c35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('966e0bcd-1456-4d37-a2eb-7c2ce52b3c7d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 41).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'fe5af52ce63d0694_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b786b0c-152d-423f-914a-98b550a52bfd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 41).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c3359f3d0f4a3c72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad24d75d-f00a-4948-9209-03c986682361', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 41).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ac92221e115be76f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3d67da9-8d1d-4a9b-9f09-e3f0914f8292', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 41).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '26593b48884da934_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1d9a88c-79a5-4520-8511-8ef2f118e159', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 41).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b0e312db17b0eb29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdcab24b-16b4-44ff-8ba4-bc769b7427fb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 41).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9cd5f90324380248_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca2d81c1-349a-4f97-ad38-884dadf8193c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 41).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6afb1adaaf26be09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c719cec-71fa-428e-9ed1-c13e6267cf38', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 41).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a95ab4467ab4b0e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e173bad3-2e4d-4d08-bad6-f08b7a143687', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 41).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'da4ac2f108109aab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68a88206-c077-4e78-b356-afbc29a1140e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 41).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'eb7b2b3e2dac0e5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfa4056f-7bae-44d7-9f83-6a2201f4218c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 41).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '13233edf417f8016_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3891ba7-6e7d-4a3f-a712-0f2ae4d19f8a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 41).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c8cec8fce1a14b4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88640d7c-0ea0-4b5f-b4dd-2406bc57cb03', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 41).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '19831f77234daa0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca8daca1-ff46-47ee-a8d8-cbca7230e6f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 41).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '0399657690f7913a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('892896ca-1e0e-486b-9dd2-1614e21582f4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.152.59.0/24 network (variant 41).', '[{"id": "A", "text": "access-list 100 permit ip 10.103.225.0 0.69.229.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.103.225.0 255.201.220.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.103.225.0 0.69.229.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.103.225.0 0.69.229.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.69.229.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7a081bafc9351ab4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fa4bcfb-dc10-4a66-8754-7f1ecf6b1fcc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 41).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '088794ff24452e21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1e0dce4-8426-4aea-ad88-e84068508a91', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 41).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd86ecaca050c9a9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f5b7a21-af45-42d6-9662-f4b9da3ab238', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 41).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ab362dabd6176fe8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('652d2865-0b17-4a0d-9720-5e9757c67228', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 41).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '279929484514afa3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de073959-8ea7-44df-99fc-547862ae460d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 42).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '44e5f0027744fd49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9c748d0-aa71-4480-a87c-fee1fa3faac7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 42).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ec7516a0786a618d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c59c1529-348e-4053-b8c2-b5a4689b82fa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 42).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '5e82ea614c7ce02b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93810040-57f8-4ec2-9eab-238eaa96c92a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 42).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'c8115e47b0b21dbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a306784c-3e9e-4092-ac67-38a8e8fd9eb8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 42).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '963ab150847ef559_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6587d644-4127-41cf-89aa-2499e38c33a6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 42).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c278a48b6bbcee78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abdae9ac-3ac4-4f68-bf8a-ab3be844591b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 42).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9a8b4b3bb1bdbedb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bd816ba-9a60-4314-9ce9-0412fc6a9eae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 42).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c70f78a8fdf9ac96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d6e28fe-940d-45e6-abe7-e511d0e446b8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 42).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '4b7c36a291f96358_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9061ae7c-5089-4e20-acd6-306b01caa727', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 42).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'afca0980ae56af7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0031df38-b35a-4ead-b96f-44a0eea9ec94', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 42).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'ec8362de4c80a5c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14d94c9d-929d-404d-98a0-221523032ec0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 42).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '65c1ad053d73720a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7045cd96-4547-4a01-ad4b-f6aa7e56dca5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 42).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'a9e088436947f3e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45ff8820-4598-48de-911c-5cb1a788c983', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 42).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1e50e8c736ff53dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('384a7e1d-0590-4c22-bbd3-622a2038a92d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 42).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '09aeeb81e4b058b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8174703c-8ea1-40ec-9673-7f34aef06310', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.249.55.0/24 network (variant 42).', '[{"id": "A", "text": "access-list 1 permit 10.10.102.0 0.237.143.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.10.102.0 0.237.143.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.10.102.0 255.176.8.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.10.102.0 0.237.143.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.237.143.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '778719a84aaa458a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e12ca245-8bd5-421f-87fa-d50188d95642', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 42).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '0d65a6be6d179c34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0886a87-d1f8-4638-b94b-adf435bef555', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 42).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'af6b3ef29b8b758a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb741d9f-9f2a-4140-b728-90b6527da44c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 42).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '268c2e106973a2bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f059f49-a6f0-4716-9f41-67ad1369fc12', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 42).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '534c49baaa712c61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bb309c9-6c0a-43f5-b0ea-07ac423fc186', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 43).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4d96c5396aab289a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95934e1b-5071-4272-a884-87302106d5e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 43).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b5d27295eaba3aa4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c17463ca-236f-4008-be95-73a30a694c77', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 43).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'd312944c9416c768_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a258180a-9eef-4500-a82e-8fc7f583baa0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 43).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '514e4bcd14a5c14b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e36967a-9c99-43a8-8b75-5bd99f33f176', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 43).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd1d9604e8205cf04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('017733b4-75e7-4d24-8c42-9fe46e97e571', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 43).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '88ffd5c47a2163d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0803296d-dd4c-4a21-8422-ba0f391d479d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 43).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '45472e69d2fa2ef4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65b35d59-ea22-4b19-8154-2a799ecec2fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 43).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '478916763a836e9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6457338d-a73e-4ffe-bc1e-ff6812361ef6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 43).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '42e3f6ec59a8ecd0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edc0220a-e72d-4f11-b76a-6e3f69442856', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 43).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '95596f8ba45299eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('596e1d31-bcbf-41db-97db-84009ecec883', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 43).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '53a9e9a411f143a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee5a24cb-2b50-4368-ab97-fb23e63820ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 43).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '3f96616111a32004_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11843844-769a-4d7f-8d64-cdc3dc37f970', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 43).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2d11b547cbd81665_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('021571d7-ed82-4e4a-88cf-0170ed9287d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 43).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '0ab1f89652fbcdc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd9ab892-a141-48aa-bbe8-305987f32d95', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 43).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '11615a686026b2de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7373f9c-f096-4cf2-b4df-0a78b9d7fb3a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.190.232.0/24 network (variant 43).', '[{"id": "A", "text": "ip access-list standard 10.95.239.0 0.35.202.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.95.239.0 0.35.202.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.95.239.0 255.31.215.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.95.239.0 0.35.202.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.35.202.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1274d056b22a1d2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16484e38-eef4-4e24-82df-367e214024cc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 43).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '7167d54075143224_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f43dd34-b66e-40b8-97da-7842308c1e57', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 43).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd604c690729ae81a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4cdedf2-ae5f-46fa-8a2e-a5c84e07fe2f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 43).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '10ab082c1943edd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94133a28-4001-40e0-be30-bb96b6190877', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 43).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '32a309833cfaa953_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58ab72d1-4e8e-49a9-9ef1-2777471d8599', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 44).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '6d3ebbb5542dc8ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1175b53d-cc0b-4fcb-a6f8-441687325a5a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 44).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a7bb15a82622b952_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88eb697a-c7e3-466d-9ae0-5c9554235320', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 44).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '7923ece7a9b4823a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19e5548c-8860-4533-aec2-b5735917d0ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 44).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'd660af70a478e506_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dba17567-313b-4a48-95f2-c03e7eb05c4a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 44).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '43999e7bbd62cac5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0842b326-4422-46a4-b031-e7a9540206ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 44).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9e4eb72cf0415d73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6577e074-59f1-4f20-86d0-07f8f80b0a5d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 44).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8adf40c0b932bbd6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0681fe3-a0b8-4939-93b4-db76ba1f769f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 44).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c54d09b5b76f040f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edc1782a-ec76-4e25-a7ed-a25308cfe966', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 44).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '243da69bf82895e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a44ab488-5d72-4c69-8a44-8fb13fe4c0b5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 44).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '8e02198e8c6be68a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4b386ff-57b3-467a-b5f1-523f179e7030', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 44).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '233a7d30603b6e6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64bf8d38-c813-404c-ae89-489bfc5d1a79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 44).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '4ced926c5ad997d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44afe6b1-3330-400d-a025-620455f244aa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 44).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e530b01f828d466b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7383a71c-dce7-4af1-abd6-66d231a896b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 44).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'beb90a0c9c550065_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7b8994e-c79b-4af9-8922-78618a2f77ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 44).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '17c1ade2614130c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb01dbc3-238c-4200-a14a-3198c0572ddb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.82.182.0/24 network (variant 44).', '[{"id": "A", "text": "ip access-list standard 10.180.132.0 0.52.147.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.180.132.0 0.52.147.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.180.132.0 255.175.207.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.180.132.0 0.52.147.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.52.147.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '822e55462fb0c197_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eefe7c8-b615-4b96-9f7c-adf7cb00129b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 44).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '820c6edc07121969_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7296b43d-cc50-4ea4-bac2-aa7c9dece10e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 44).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4f7ccaa13eb63986_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4533d269-b8fc-4653-a08b-33e724f551c5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 44).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ef9b5d84a12dd687_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57db70d5-9fae-4fe4-8475-558d4b258c0a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 44).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'fddf201e6f8504f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c28b0642-088c-4576-8464-67ceb6cad28f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 45).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '12ab6a1a1bf315c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f20f5c9-b318-4fa5-95f5-fe2c4c813de3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 45).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'aad9590eae974ee7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0963a6be-4790-468b-a101-59f23a18a726', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 45).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c5072a6f15d4ebe0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aff335a7-dac4-4cc9-91ce-4ee62ee5626b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 45).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '17a3c10fc6fbca1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('723c069f-2be7-4d73-bdc1-0b755b7c46c6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 45).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '03fa15ecbc81a99f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('337424b4-d9e7-43c6-8902-cb09af408007', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 45).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f9b0fa04da117c72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b2406e6-2609-4ded-a833-270f8a9c969b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 45).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9ac9da7a48c8ac9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2a69783-de18-491a-8f3c-f612ff6c0f8a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 45).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e348dc28bda31415_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9db964f1-48cd-4bad-b248-043fbd6af87c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 45).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'ae201d84428d7759_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b676ca0-2404-42af-860a-1b1b253c4c3e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 45).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '058aab19735d107b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c1ab149-2e0a-409a-acda-5acdb686b7b1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 45).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'dca494ad2912f320_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('779beb9b-e9c4-47f8-9e3d-214e4b905db3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 45).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'adf1a5854b8f658e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f7e6d11-2f81-4276-b852-6a81db024252', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 45).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6d221f2f4ab57378_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fbecf6c-eb42-4e42-9532-7640cbc3c839', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 45).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f53d4d37d178fcd1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f9044d6-146f-4701-955a-51227a2c1400', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 45).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '289e094ca754673d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a91547e7-e4ab-4f37-8d07-bf352917627d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.30.201.0/24 network (variant 45).', '[{"id": "A", "text": "access-list 1 permit 10.189.191.0 255.60.99.0", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.189.191.0 0.71.67.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.189.191.0 0.71.67.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.189.191.0 0.71.67.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.71.67.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9a9930aca33a6093_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3be8aaed-8e47-43e7-8dfd-e3f81144c195', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 45).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'ca3c42acc98f40d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47288ad0-a0f2-4447-8ab0-9780d399e745', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 45).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c37528d17e1f121a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5fdb678-0b26-4591-9d1e-f186cd71e493', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 45).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'b6b0e608a14c90f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b40af9ce-3264-4cef-87ae-95ef56bb22e1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 45).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0c93057d1c4486c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1f3dc91-7348-4daf-b731-732b3369da5b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 46).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ec5f2ee23e09b263_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec496390-ac13-4ef2-a779-54e64c0a1be9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 46).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'bad56e5b46fb2061_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4599218-f145-4014-96a3-517664f820e0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 46).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '6443929cdeae2d73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5153e297-6ab4-452c-9111-dfb576acad4b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 46).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '83a11fa550ee23a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f362b821-eb03-46d2-a788-234bbc7b868c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 46).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5e289ac7ec090db6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('757e3e2f-05b2-4fb1-a68d-75a14019c6ce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 46).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd61f611f717d6e0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48d927b0-c8cf-4618-85b2-c0d906eb7c08', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 46).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '15292b6bc0975cea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf1f0b15-e6ef-4f10-ab4b-58a5201c9050', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 46).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0e7ecb472f480eb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3fadce3-3484-42e9-a447-9e9c72ae48fa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 46).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'c08b8d8a6de8dc5e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9c4f224-850f-429a-8e50-5cb7742e17ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 46).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '24488d357a816d8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8d729a4-f0f0-4556-83d4-a4be73d8a9cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 46).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '0a9ec7d183731faf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17a88afe-efe5-421e-a3f7-7dcc45554e78', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 46).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '90f1c8877e8602e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dbf0122-0b4f-4867-8aa9-9b780003fe06', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 46).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'df43203f5ccfb1a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bb1c226-cfeb-4673-afd0-690301e179df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 46).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e77667181ba4a0eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3145b286-98de-4bda-83bd-73817d535c40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 46).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '8bcee54a556408f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c93cd128-9ae5-4083-8504-d317d093aafe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.87.227.0/24 network (variant 46).', '[{"id": "A", "text": "access-list 1 permit 10.239.44.0 255.149.64.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.239.44.0 0.149.221.255", "is_correct": true}, {"id": "C", "text": "access-list 100 permit ip 10.239.44.0 0.149.221.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.239.44.0 0.149.221.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.149.221.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5560a178672f5cc7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2de079b0-6a50-4228-845f-69b7ad4574d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 46).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'bffa320ddbafc993_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('760b2b1e-1e10-4bf3-a6e7-e899a5413bb1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 46).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a39877703729047c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b141c003-17d7-47b0-8961-f54fd447c749', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 46).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '0e4efbfdcc9c4223_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('581fe4a6-ed6d-46fc-9115-b14605477dd5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 46).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'd18a037931dfc87d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5b666ad-a377-47fa-a6cd-631d5b088261', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 47).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2b92e2bb0f8362bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fdaa5b5-9f62-426b-a1f7-af26cc42eeeb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 47).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '96d1c948654f7bfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d191402-4829-45fb-b2bc-1d7eab73a368', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 47).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a321bf4f744f7839_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab6654cd-a52b-432b-bd00-725d9c6af4b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 47).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '9435c66b69ef4905_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94176397-89a9-4f81-a6a6-29e01a024cd2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 47).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '312afae31da11aa6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78aff43f-9707-4dd3-9854-7c407d489d48', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 47).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4824f3461aeb2e34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56c28e70-ca93-40b4-b380-c5fc746917e4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 47).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0ac1aa9e463a65a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5b92e8c-b3b1-468c-b8cc-a01b04caefbf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 47).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '91958d17d51717d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d285bcab-b70b-47cb-ad1e-acf2f33cb2ce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 47).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'e09a1e423fad7def_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('391112a6-1fec-4d20-afbb-db0bd9e10f76', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 47).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '35a46b4a161006b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae07ed04-7cd8-4458-86ba-48e2a21d4461', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 47).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '0350fb77a2cc3cd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1e00037-2274-45b4-a04a-4103befbe54a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 47).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '22bded1c6770ac75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3fda7d5-eece-4e87-970c-4e3665c284bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 47).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e00679de38a3b0c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68d1d8dd-3e24-44a1-a04e-7fea78258f07', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 47).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd40a9d4642b40001_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b50e981-4853-45ac-9819-0ed719d9681f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 47).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '4cc6e68fc4be04ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50acbc50-a8f1-447e-812e-8f8105e5e356', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.159.83.0/24 network (variant 47).', '[{"id": "A", "text": "ip access-list standard 10.33.54.0 0.132.90.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.33.54.0 255.106.20.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.33.54.0 0.132.90.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.33.54.0 0.132.90.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.132.90.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4fe020d27c6aef87_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0219500f-008c-4cf5-a620-54beb0890d48', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 47).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '0de2dadabed5329a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7958fa3-2926-4c59-bb32-ce6310c2c0ad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 47).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ee3f8e853477af16_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc9de470-414a-40af-9cf8-83ff6b72308a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 47).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '082d2a2acf65761f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48f18946-fdcc-4317-98b5-95fdf1f3a028', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 47).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '74b267a13befcba0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42b0645e-3cc1-4abd-a8b3-0c1ba7aaf1ce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 48).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a5e73855e107a0de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f064a8a7-eb8f-475c-a1dd-8bdcec1e5971', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 48).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1634d263653dc29e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b6d3fe6-307a-4103-8849-beae853f0770', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 48).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '13c085f8d28ca4f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c846e88-1eac-4708-a1be-03d9777794ba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 48).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'bf75d97028fe5c81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c071b55-9975-48c4-8dc1-8d70c65e231e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 48).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0f860c4bf6ca503a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ccb1cc1-3510-4bcf-b3fd-4e4c69861fcd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 48).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b3f50ef095d7c83b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd533f8a-d2df-45cf-b196-ca6bce1928fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 48).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '60649c977ce5f999_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c7b1e6e-66e2-4173-aaca-1b5a0e5344f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 48).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a53531e437574f7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f66d0d9-793b-4d69-9502-8c71743fcc58', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 48).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '5104affa96b635df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41d31898-6664-4a70-a345-804d1477bd75', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 48).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '64f75d8d60af535b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42d55eee-dddc-40b9-b84f-df922a72bed1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 48).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '06e493f4bfac6480_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90a27c42-ba94-44eb-88e1-b4123366e30b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 48).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '27750bc995884f21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('437fd41b-e344-4138-af54-3eb5f845d4c5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 48).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f0d99ed9e2654ec3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a7cece0-9ec1-4448-af64-8ef3a278956e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 48).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4fc95ef7aad4e3e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15ab3b6e-6385-49f2-af82-fe9e627f2460', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 48).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '9dc9f847def2ffc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2c1c1fc-7199-42f0-8542-8783f175eda7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.153.65.0/24 network (variant 48).', '[{"id": "A", "text": "access-list 1 permit 10.85.112.0 255.118.0.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.85.112.0 0.170.151.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.85.112.0 0.170.151.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.85.112.0 0.170.151.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.170.151.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b22e645025e6c5d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34b7098a-0043-493c-8708-619b01631092', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 48).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'e958815ef244f788_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b809221-6697-4932-80ca-254bc4750d05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 48).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9986dfce34494535_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e50723d-b4d6-4c04-946d-b16835b1e6a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 48).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'fc845f30234fad6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0c38bc1-77ec-4959-83b3-03c9e502384c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 48).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0c0670dfc54b881a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b44c4aa8-5c28-4641-8ef0-a53bed809ca1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 49).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '59fe5e495af5921d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc8d4679-cfd3-4290-8a9b-f7cf2a145486', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 49).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '369e402b1f9e5a2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4089265-9b09-443c-b562-d9d6f24f979b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 49).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'cf491f3217fd8848_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce651a76-7b46-461b-b2c0-2667715ab6f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 49).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '854e137e13fd2c64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ddc7117-e38f-4f77-bece-a61511ff9c07', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 49).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c15458d0e04981db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94c49712-9714-461b-bfff-799c8f361633', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 49).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fd3e51fe718d0884_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed5c686f-d49a-4840-a5de-833f625bd1c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 49).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2202a46d69356ade_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0d461e4-2343-4383-97dd-be5255ab9ceb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 49).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8c1286a073621d6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f794471-f82c-4261-8f99-f573d0b85a01', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 49).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '075ca01d27fd762c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf72218a-40f8-41de-9df6-71188caea467', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 49).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '306a6fc6f2bef32b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cea85a18-d701-4017-b4c7-02e5ebe246bf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 49).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '557ea783a37bb4b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4879e09a-ccea-43dc-a1c4-97a82377b792', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 49).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '0276e5862629c58a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f954a1d9-e91c-4732-a644-22a50112a093', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 49).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '88c5a6d83327776d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fd5bda7-449f-4351-8e08-096475add3b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 49).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd801ef344dbdcb01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd27a72f-7aa6-4c83-90a9-ec9022b8b125', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 49).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '7ff6808f6e1d2980_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d303c3a6-0388-4120-ad45-6f9d55b408e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.7.71.0/24 network (variant 49).', '[{"id": "A", "text": "access-list 100 permit ip 10.159.4.0 0.252.194.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.159.4.0 255.100.128.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.159.4.0 0.252.194.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.159.4.0 0.252.194.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.252.194.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '337341592fa7930f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9f9ae47-31ba-4cea-9d74-2c411bd4de0b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 49).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '02c5aacdd5935ff2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d9515d5-5a60-4483-8275-03af7f5f5d2d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 49).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '524cacc7d39ba7c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9d9d8cb-5f07-4a66-b178-fa693eb32716', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 49).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '7888b8cd89d8d3f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3445313d-c1af-4408-be1d-d4b288ed57ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 49).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '2f08a9fc238cf376_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a843728-e193-46c5-bc72-8d6a72c05613', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 50).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '84db290895d251b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffb376cb-394d-4ef7-a2a4-dc0bbe4c7ff4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 50).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '106dca0c5c51f46f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9509f5c5-2705-4271-903b-6f3a76facb97', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 50).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '5227f0a31ff9a1f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b18f7b39-2f0f-4315-876a-7f4586385339', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 50).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '7916ee5eb7084162_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73ae35e3-a238-4354-95d7-0344f08a4fbd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 50).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '18b928ea3278cae1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c124cce-c907-41fb-b4fd-9c6ba89a5d42', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 50).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cffeb23b27bafc50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8370daa0-f319-45b1-86da-1018c7011104', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 50).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7bf99bb585799bae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd6c8cd7-6af4-440a-8f49-66b423fcf360', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 50).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '10f8ba57312fb6ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('623759e3-2a92-462e-b4ae-a38d25b59bfd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 50).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '41ba9b1057439359_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a6f6d62-4316-47bf-b542-6771c64cd542', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 50).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'a66cd7cbcec62ce0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d45a8ff2-bc3a-40b1-8bb1-6f29b659917e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 50).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'a09b4cc2f035a6f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88353565-aef1-4790-81b4-be91eb4d4393', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 50).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'dc2f56d4b522f8c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca10df78-3e6e-46cd-afd3-3fb402c97cc1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 50).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f9f21183cbe00de6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eed631bd-87d4-4021-abab-63b2005bc738', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 50).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7f4f56fb07d8052d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08fa63e9-f8ed-4fda-a774-e5c1781ab69a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 50).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '9ba54461bd0ac85b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4723add5-68fd-4cf1-8bbb-e38dc777c584', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.52.178.0/24 network (variant 50).', '[{"id": "A", "text": "ip access-list standard 10.184.114.0 0.117.119.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.184.114.0 255.77.71.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.184.114.0 0.117.119.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.184.114.0 0.117.119.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.117.119.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a46bf036bea38098_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('398b07a3-67cc-4ca1-b45a-1b663b6cc18f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 50).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'a60b79849a7d6561_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a55c2622-15b9-4a85-8d36-8ebda3b6f3a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 50).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '298ac4e0b86de618_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76e9a8ce-82fc-4ca0-b6c7-612e1880eeee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 50).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '62caafedef84c7e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65e4bb5f-66b5-4cd4-a8e2-5c1c183165b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 50).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '33a184cadf5cf81b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a98973af-0e5e-499b-b9fc-60dfcbe1b272', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 51).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '46dc603bee299d26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abcf727c-12eb-48ec-b6a6-34ec4721f31a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 51).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b31cfb98556edb1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4286d5ee-d987-4957-a486-4fcb862b5987', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 51).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '9ea98221c573e09d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ee480e8-18b2-492a-a6e7-657145f63701', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 51).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '543390d7af78e24d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7da9c2a3-a20d-4c52-970d-95c1e9debc2e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 51).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5e913cb265c3f0ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9f10ef1-c0a6-49c0-9029-321f20c45e71', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 51).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fae869fcf0b9c402_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cc87bfe-a5f4-4018-861d-1013ea7c4a99', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 51).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4d9a295ed8bc15b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49250f85-6b54-4ded-b5bb-390c69c55595', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 51).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9061189d51c5c2ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('024a5d20-8574-4957-b50e-6b3dd99fd6dd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 51).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '415ef3977d1477c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a07dd0a-3c2a-45d3-b931-b9eaf2106cd4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 51).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd3653a56a3f217a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10198d6d-09bf-4871-9a16-17886dcc172b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 51).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '5bde52d06f455338_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b30ae6a-24f0-4202-aa4f-cfb26d0e0bda', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 51).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '99018e3dd8f75268_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d636e9e-2118-4b44-bfdb-0fbf42246f40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 51).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3d473476a5b713cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfe1d0c7-6bc5-478c-ab23-c162fb5bbd11', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 51).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1048947bc917c8b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb803eac-3594-4d67-a34c-8157413b4c0c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 51).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '2ecaeae965a4aa6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc64e815-cb9f-4000-a5ba-34f849c264f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.96.16.0/24 network (variant 51).', '[{"id": "A", "text": "access-list 1 permit 10.80.213.0 0.11.87.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.80.213.0 0.11.87.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.80.213.0 0.11.87.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.80.213.0 255.96.83.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.11.87.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '4a053d0ce13d36e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12d2a3e7-da7a-4e7d-878d-2fb3d4462676', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 51).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9bda26df62f04ba5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4641f827-61c8-4c50-b366-2cd6d2587568', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 51).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2c573bd81a17a169_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbedda6b-66a8-4501-b03e-9ff51b126589', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 51).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '010922fc5c2ba56c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c60c3f45-9765-4ce5-86a1-d1c68b235067', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 51).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '74a15a4498ee3690_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15ea11fe-dd5b-49b6-b3a0-98c607f0fdaf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 52).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1fd64c17e0606b38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31791f5f-9f59-4a0a-a87e-bed56a1fe4f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 52).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9e7b155b222edbe0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8217855-7a6a-4b11-935d-aa77e58473c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 52).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '76e3ab5ba85c11a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8b2ea38-cc00-400d-b3bf-155d9d70f125', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 52).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '3dfb425ec6660d4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('082591dc-8d58-4978-b19e-101470378f86', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 52).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5e2ef044c700ae60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f87632f-2986-4024-8937-62fada5bd031', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 52).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '16a82ddc6daf952d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7203d849-c053-4832-86dd-9d3a83baaa35', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 52).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '191d4fb3e263a5d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00b0efc7-2866-4831-b207-4b9e9dd68913', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 52).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5e1595c0be0ec355_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1543a747-c630-4cde-979e-631d8ec2ed3a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 52).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a454dc5355d73d4a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('608d5844-a2ed-42cf-b638-029d5328447e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 52).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '040d2e3b91741c71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bc230f8-3b20-4613-a58c-69a3e8b9fd27', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 52).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '73b8072e3dc77fb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc0a942c-b9ca-4772-a794-4c19a854c058', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 52).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '3f128de800d513bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edda5036-bc9d-44b0-8e76-4acf1c5ad519', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 52).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ce79cbe8e7b4a735_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a082682b-1c84-4045-8f74-943f7cc6dae2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 52).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4d8e05adaf8d9756_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31a307ef-ba4a-440c-b2be-60535861889f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 52).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '49810ffe7fcff54f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aba4f4d6-d8bd-404f-a2fb-862945f1b02e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.192.102.0/24 network (variant 52).', '[{"id": "A", "text": "ip access-list standard 10.78.177.0 0.6.123.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.78.177.0 255.209.80.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.78.177.0 0.6.123.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.78.177.0 0.6.123.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.6.123.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '653ecf059944c872_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89d63578-a910-4bfa-b252-15fc8e6576a6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 52).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'a7856a3ccf43c60e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ba4be9b-b793-498c-8317-edc0a3d342a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 52).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a5e78baf4c411ef3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48bd5518-8691-4a82-b0ef-54fe84add46a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 52).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '7fbbbc6ca9f72af8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5862eaf-7540-433b-9f5c-eba6b33ed101', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 52).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'fcad4830b9bb136a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('986eda26-7bd5-478d-8af9-e2e1429f1719', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 53).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '499df84c2b9c6fa1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48894076-6dbd-4068-925d-2e0e214c5dd8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 53).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2da0d92d2ffdedb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('595f17d1-bd0b-4016-8e0c-10b6c5a3f0a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 53).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '810f261dfc1a21cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c09ac0e6-cfd0-43ec-8f9a-8a2c22186822', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 53).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '58bb645a3f2dc2ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5cc2e98-07d0-4c1c-9bf2-3be6ea93e6e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 53).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bc06dc76c44736ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b58f25f8-c342-42ba-9b63-9d60f39beed1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 53).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2a25dfff19f420ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b6591df-2e3c-4fab-ba20-cca349761454', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 53).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ee6e08ee11bae229_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('471247df-7f2e-4848-b4e1-b4008e284f48', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 53).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '555d8a8e50af940f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7925ac8d-c1f9-43c3-87e6-522bd851c3cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 53).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '48b2ce405f428182_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85bd6659-93f0-4fc6-9a81-24544c83812f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 53).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '98cd38e769478ab4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d00bc5e2-3ff4-4b42-82d7-b9bfec76ffaf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 53).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '2e50da31a0805e19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e252ae8-bb9a-4142-9b27-9f1e0c5e4de5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 53).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '216aff8ed507b8f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('826b5b1f-7223-4703-bba6-0bd8711f9617', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 53).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '87f766953a40f7be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('239a9abc-b624-4b75-a4cb-2631c72f3297', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 53).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'a6f4b25064e172c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57e94515-331c-4dee-a4fa-56e774b2e5fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 53).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '306db457a34b3adf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfab4088-63b8-426f-96b9-fb73eb6a8cd7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.151.184.0/24 network (variant 53).', '[{"id": "A", "text": "access-list 100 permit ip 10.150.181.0 0.66.138.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.150.181.0 255.200.64.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.150.181.0 0.66.138.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.150.181.0 0.66.138.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.66.138.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd543805c79665cc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76b90f75-f745-4deb-9c30-dd54881ebdfc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 53).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '1445ab6dc79589f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1201a647-c776-473b-b798-84e8d015739a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 53).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '62c09f6918ca12db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51d381aa-e925-4524-be94-d13583044382', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 53).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '63b2d30dfba907ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30f279de-9a78-43b3-9b60-110400b8b56a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 53).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'f437277ec9b3a5b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73a8735a-e637-40f9-a37c-4750083a93f8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 54).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f45a08a136590573_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0bb32a8-21dd-4af0-8d0e-9bc7203be481', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 54).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '616c2282c2d1c991_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('922c29ff-4308-4d94-b09c-0fe20b73145e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 54).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '10f0d61bfc2c7680_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15214298-0542-4cf5-847d-f2d2913175c6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 54).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '98c899e7c742d115_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56950ac4-f752-48c2-85e1-73364495ddd3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 54).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ee897481eba9b052_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bce198d-51b1-48ff-b571-8d9a09edf26c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 54).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '500cc8266127c80d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bddd771-090f-40e9-9fa5-8fe4a4fd2144', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 54).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2d207e786f9e5a98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('324b64ed-1895-4091-a888-8a11cd388da9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 54).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c38b4afce6551344_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ec27e8f-2da1-42d3-a2ae-cca18ad3cd43', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 54).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '6323d72ccd9792d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2c426f0-7154-41f1-8280-49095750f138', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 54).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '4dffe34b0bb890b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('623d8e90-d693-4dd8-b411-d34ac7cffbb7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 54).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'ca0cc508460d6542_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c2d631b-1f0c-40ab-b902-ddab8406dfe5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 54).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '70bf3983587c6a2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca95b5e2-4def-4a6f-bc89-821a15a4adc9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 54).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'aeaa6325aeee99c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a96c33c-50a8-49bb-91e2-2ecea18d77b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 54).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1b00ad62530df556_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f58b90a7-c0cf-4912-9496-4b5d6fe7fe62', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 54).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'a8e7ae6e79b6e1e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a5ad8c5-be09-4dfe-87f6-a9155249c409', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.65.45.0/24 network (variant 54).', '[{"id": "A", "text": "access-list 100 permit ip 10.40.233.0 0.156.96.255 any", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.40.233.0 0.156.96.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.40.233.0 255.215.62.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.40.233.0 0.156.96.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.156.96.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f0c693814fd47c07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a63c0461-a58e-4e5f-bdce-7154d196a10f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 54).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '074a4f5ee5a3136f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('491965a7-5b16-436c-b887-ef4135ab222f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 54).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'cb2a12fe44a175e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e6ae56f-7133-49f2-892f-d22569b3e3f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 54).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '4480f670bcff184a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0088a215-b890-42e8-ac01-0105e335472d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 54).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'e35774c8b835ac35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad16d5e8-e6f4-45d7-80f1-1bcf44721ddc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 55).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c72a5ebff41e217a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e98eb87c-2c30-43b8-9902-d29dd800ea2c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 55).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '80c966509ab40f0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6e6e812-54d7-4674-82e1-2ebc9aed19e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 55).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'aecae4a47c9c4474_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df752524-69d1-492c-9feb-5f1a939d1f46', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 55).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'f68281d1d84cfef8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fac09b0-1db6-4f31-8f96-d2716cca195c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 55).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ac653174a0e24aea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3be9cfd-662c-473e-bfa5-d254119700a6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 55).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a399238c2ca54f98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a48c9b63-06cd-4935-a4ef-cac80ffcbf30', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 55).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ed0a29455a8ed125_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('394827e8-b13a-4449-81b0-b317bf5750d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 55).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '98cb6dac7e1c2544_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b048eee-1af5-49e2-8715-684b6b971180', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 55).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'cbb6ecad08bc73cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4288e09c-44e5-41dc-8997-2ab361c6f0a0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 55).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'fa2978685ccbd184_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dedf9cac-e2ab-45eb-b552-19d64ce06a84', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 55).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'e37d7668f3e61bbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('107707ab-20f4-4a89-b3ef-eb08d2710b07', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 55).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'a1ddc61d097bf9d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ea8672f-fc26-4cad-af8e-232089087218', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 55).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'bd7ffdc09142053b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5450b7df-fc88-4572-8b7b-b0e048666fed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 55).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '361f21f8862d5dd5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a209786-e55a-4148-b811-c23fd171157d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 55).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '524289ebc592001d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44905e35-245f-4ef6-b481-55497dc6d3d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.171.197.0/24 network (variant 55).', '[{"id": "A", "text": "access-list 1 permit 10.247.26.0 255.89.128.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.247.26.0 0.44.126.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.247.26.0 0.44.126.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.247.26.0 0.44.126.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.44.126.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '71cd1b8948bd6183_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57f60177-1d85-4bce-972e-be1144aafff9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 55).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '6c8bcef6d6efc56e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b5277a7-574a-4c60-8432-531c4e83de9c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 55).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd69309248a646745_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a13fe4d-4d48-4f31-9010-2ec8bac351ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 55).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c15e7909bd4cd2f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e76813bb-4828-4cc7-ada8-1bd6c7c1dbee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 55).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'c60c959e407be351_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('267905a9-c834-4e67-9c6e-b06c2ace7de1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 56).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '156f5a47fe977c2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('902b98b1-2428-48a1-96f0-0520e250a694', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 56).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a030b44546c87813_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27fe3524-eeca-4c49-9c3a-644d76054073', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 56).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '56da3980d4f206fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5045d619-84ef-4976-925b-7ba6e6e7d29c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 56).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'caa73503e0894eb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31bde353-dfac-4e40-8158-7f6de3e6b3d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 56).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '35fb79301d2127c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('785afbd3-3d19-4779-bca7-97b89a1a9801', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 56).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '591d66d643aceba4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53b22495-38d8-4d05-8f0b-7e23969ed9ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 56).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '79be6154c373708e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('841bbe78-c2ae-414b-b134-9881c47b2800', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 56).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e9849bfd429e43c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ba6f365-3afd-4a12-95f0-5b3f140bcf9f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 56).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '322f27d594d0d838_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a03a4b8a-58f1-440c-b43e-1b69bfead7bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 56).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '1ac3d66d9001db42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd259949-13f6-4d72-90cf-fa52c9039d97', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 56).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '16af9749b3730161_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8b49969-df55-4752-82fd-309043ecf4a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 56).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '9ea76937ca2d1bd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fde2761-45d8-4f3b-a4e2-1aabe9526121', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 56).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7cfafa015ab1ebc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e736bfe7-366a-41aa-a65c-10abab208f81', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 56).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1a27fde8ec3e58e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b2c5776-d2e2-4d2b-abb8-72ebc4d3ef27', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 56).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '6b1f9167cfe1ac19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15d2bc80-c76a-45a1-92f4-1b137e374fda', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.20.87.0/24 network (variant 56).', '[{"id": "A", "text": "access-list 100 permit ip 10.219.116.0 0.29.18.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.219.116.0 0.29.18.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.219.116.0 255.210.226.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.219.116.0 0.29.18.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.29.18.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8ea44fea59e81083_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b1d852d-30f1-4db4-a555-5688a7c76385', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 56).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'de119990c0d55163_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('769037bc-762f-4cf1-ab8c-fccb6641dd44', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 56).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '373b386a12ca26ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9da351e9-cf4f-4eb6-8721-fdb3dadccbf3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 56).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '7411228f51b9edab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15fe1e17-fe9a-417f-94a8-0f27d16b5731', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 56).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '4fbe24e088314417_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9594b69d-402b-46f9-9a8e-b886e4a3b8e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 57).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8898e5a4a3605fba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04183475-ea96-4d52-8da4-978a4e1b3a1f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 57).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '214041ccab0730de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2faa87f0-08ba-4d46-afe6-db75598eaa39', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 57).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'e3eeb213025e8a08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63497f04-5a42-469e-a2ef-45d93662b578', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 57).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '22f2de7104cb1662_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2c975d0-ed71-465a-a564-f6bc898f1528', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 57).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4565a85f7a17e2b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0683b558-f258-4d96-9e22-11cc555198c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 57).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b5fcfdee5ddf572b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66dcc0b1-9bc3-42d3-82ce-d1fa25506eef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 57).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9a003de42bcf1bc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fe4104f-cdcb-453b-a80d-11482875ec42', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 57).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '770a0887d42ada8d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5105c8b4-f4fa-455a-b7aa-9b1195188353', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 57).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '2bc85999c8fe8ab4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('065ef0fa-3f6d-44a7-9da2-e026eefcea43', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 57).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'cf95f3db541573ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5e1c0a8-da97-4703-8583-a27944cd86de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 57).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '7d3600e4cabaa302_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7876c242-70c6-4d04-a3eb-d8e27d44e312', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 57).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '7200b730e4c7e314_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9b6e90d-f96d-4437-998a-dc323fe22255', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 57).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6b5384f726a0e987_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('428eb347-45ce-4fac-86c7-933ad19e3d16', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 57).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '965de80db83a8aa2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40755cd9-497f-4e45-be03-326e308e4edb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 57).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c7423c1c0fc47d38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('001dea97-e5c3-4114-9c97-7f782a049a99', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.188.56.0/24 network (variant 57).', '[{"id": "A", "text": "access-list 1 permit 10.203.215.0 0.40.119.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.203.215.0 0.40.119.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.203.215.0 0.40.119.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.203.215.0 255.111.128.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.40.119.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'adf1acab50b55a13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('669a532f-8e15-4201-8b35-c977968c5c6a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 57).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'fe5dde43e206900b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3aef8e36-9cea-4ac9-afe5-fbb34275b3f4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 57).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b903a5252f575f06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3566c065-28ff-4ca7-9c5d-e89c2da6058d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 57).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '8b28070be36263ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4278317f-8b6b-4528-ba25-5a18b0ad2993', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 57).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '54b82a3973066210_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55261c0c-d156-4693-ba55-6f73c3110c8e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 58).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ac29465068f8df97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d479a5f-f5ee-4826-be1d-304827964884', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 58).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '652f1770b7a57c6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2b6f2cc-5792-4d19-9072-329a60c490b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 58).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'e8a88386949d5c0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b4c7040-2ee9-460c-a7af-f9de791cb84a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 58).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '50a1276edf37ff8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c07b50e-ac45-4f20-bfcf-a03c46c3278c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 58).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '701c8c1f87981002_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09a35cd4-5678-4463-b407-50d1efd63fd3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 58).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '23da1ac0852907b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('882c2154-e5a6-4632-9197-cfc7ae779fe3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 58).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4805c71eb6fd7cfd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('232bc6bd-a7b0-4be4-9aa1-f3c096b9a76b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 58).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '39ec8cd3c091d27e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ade157f1-0c56-4594-8bb4-7841adaadb1c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 58).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'aaea0b321d5f2ea2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bbdb808-9634-4d5b-969c-e0947b108262', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 58).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '2634e4ad99f666a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e950175f-f411-4077-b3f4-1b805bc74571', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 58).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'c5a4c2c7f783749f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcc1e849-e383-4e7a-8576-06ddd156a006', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 58).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'e932f2fd4d895edd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('312a5c5a-73ac-41c7-97bc-bb1032764ab6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 58).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f0d3edb7e973ac84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc66ef42-e825-40f4-b1b3-0aab68a51c65', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 58).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '97c1719d58e91ba6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17aa4bcb-61b8-4f69-af03-9deb8eec920d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 58).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'd6c91af9e868e23a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('506fba05-0bb0-4c4c-a969-d59f3952f00d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.154.74.0/24 network (variant 58).', '[{"id": "A", "text": "ip access-list standard 10.237.153.0 0.216.14.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.237.153.0 0.216.14.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.237.153.0 255.50.186.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.237.153.0 0.216.14.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.216.14.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '481f9835ae32a88f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8712ef53-762f-4210-87a6-e71db8fb4f74', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 58).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'cf10e0a3ad39d35e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2956c5a0-c022-4ce3-aaaf-f6322f1fe345', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 58).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '231606782c0424cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64eb9349-cc8a-47d8-9f25-74d61af96a61', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 58).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '2a53a3dfad7b3918_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c55ce23b-f781-475c-ba1f-f31e486be7c1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 58).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'd81e3c3e8fc1fcd9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32ddfc5d-bba2-4362-b213-22069f12c6b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 59).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2ba91a48ce79e4db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d361b54-3df8-49df-b065-036daed52a58', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 59).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1633b15fd281a761_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed428ac5-f670-4442-aed9-e8daa29379e7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 59).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a21012d0c1110b04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('506c8fc5-3956-4c48-b15b-87ab41d3e357', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 59).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'c10d0c0600045256_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('078c35c5-8846-44cf-9634-5f51888975e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 59).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '64b391b57084eae0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1685a9d0-56c2-48e5-9cdf-711e234e43e4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 59).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4f317ad48c726a4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd505531-ca09-40d9-80df-9d627a834511', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 59).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b351952dd9b7a48c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7614c26-be96-4024-8cb4-a8993d2dd061', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 59).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'cdfcc4b4fb2e0210_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37adb832-ae64-4245-9d6d-25e18fb86666', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 59).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'eb2be1cc028a378f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d95c7f09-6422-4075-9db8-ce58e185ad06', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 59).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'fb2ca7dd3fc5347d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3833d786-706f-4220-8081-7f11c0b4503a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 59).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'd0f7d4ba79f55792_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75b4da3d-21c6-46a7-a3a8-851787fc391a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 59).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '8581adee7578c953_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a8ab6a7-9c2a-4df7-9413-5b03a13f7792', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 59).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '911ddf572275f6e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ed0eb83-e0e7-49fd-a559-951526c57b8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 59).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1a61227cd48e71c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7346e0f-1a4d-447a-83d2-1589d4c8495f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 59).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '48ba9e32ca3b541a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d651b9be-9180-4f06-9290-bdefead6c112', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.195.2.0/24 network (variant 59).', '[{"id": "A", "text": "access-list 100 permit ip 10.24.65.0 0.237.126.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.24.65.0 0.237.126.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.24.65.0 255.108.250.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.24.65.0 0.237.126.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.237.126.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f780eb43df8ee33b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0894e2a-e4e3-4d0a-96d2-b7fdcb986765', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 59).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '4a491deb6e0249d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b8b1314-8093-423c-a701-3bee0f661a5f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 59).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '04df2ee6c57ca4a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57a267d2-b76a-4a52-8808-eae0afff6787', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 59).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'fc9bfe3b7838658f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f2e6304-100b-49dd-ae34-1894c5ee249d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 59).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '39aa9036e0b4f9b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92a8754c-341a-4095-a101-0405dc5379ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 60).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '996df5c467dddd39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36fd91f8-afe5-470f-b967-add08187eb9b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 60).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'cd9c7109e0efc155_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('762fbc05-3b18-4328-acb2-81264e50e650', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 60).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '4c04b41a005f6dce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de36069d-67cb-4239-9516-911ce32fc082', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 60).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'b8680de9405a7bc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('621c943d-1065-48d0-ab9d-f669f6ff68b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 60).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '59544762c0958816_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c4454a8-6742-49eb-be50-a44321930c42', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 60).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c19774cf04b484a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34cc8977-51e5-45fe-9408-bcc65baf94f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 60).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '13db2dbbbbcccf4a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a88d6af-fc24-4bc9-8d99-6d8b0feaef0e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 60).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '09277fdba3538a98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db4921d3-a53c-480a-bad5-c4af43f3764c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 60).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1fecf70501fd4893_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc793876-a1c1-43b0-b1b1-1fd19d0af2ce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 60).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'e3775af6fb39f18e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c45009aa-8628-4477-a43e-85fd9e1d45d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 60).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'a1ec7cb40dcc5aa6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b160793c-2e23-42bc-901b-ee5b5c5b2757', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 60).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'ef33029fcb86e65f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c23dfed-38a6-4d61-a15b-f0f45ab92ea3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 60).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2aa08bac5ad045cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a90e49c-01ad-438e-aded-955a412684e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 60).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'b5b438e7208cd096_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcb092e8-a5b0-4e36-9210-59e9d0212a30', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 60).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '6e76bcad5b71ccf0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb9dc9a0-2321-40fb-a815-bbc2db74d455', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.240.171.0/24 network (variant 60).', '[{"id": "A", "text": "access-list 100 permit ip 10.45.150.0 0.68.195.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.45.150.0 255.231.185.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.45.150.0 0.68.195.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.45.150.0 0.68.195.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.68.195.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8ee90d0b89debd7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03fe8342-daa3-4248-bc27-73f2b8ff3e39', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 60).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '6bdcafcbca962e43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb42c115-b445-443e-965a-2083e47b1381', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 60).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '51b910fda50cba94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('960dcfc5-1a22-40a5-add5-adf50a2d63cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 60).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c218a4f492b80f33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('622b9a9d-cdf7-42a9-9bae-4734b456ce00', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 60).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '776d5495a9cdabe1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acc19294-908e-4361-b95f-79cf7778cb6f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 61).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1e1943d5bfb5cb23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6def76a5-0844-47bb-8d34-74a40614d66c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 61).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '75d4ba043d528dc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de556cac-f4a0-4894-b0e5-39030d49866b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 61).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '426a2c13f2b13772_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b760b3c-642f-4cdc-9ba8-5553d7e35576', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 61).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'e0fe794d48394b7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96795fd9-209d-406c-9e5a-61f653046f4e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 61).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '89a00ec4801ae52e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ec48f32-0587-4a98-a715-9ea8b611a067', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 61).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a2373f3cbceb252d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47275afa-384b-4dda-80a9-df6615178128', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 61).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9f78ccdddea63e84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d457ff4a-5ba2-4d15-81a8-6a6ad10f132f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 61).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'aa0e8feffd41ac9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40d6d71b-dc66-4093-8689-98fbebf293ce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 61).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '06fc8262cb99c01b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c3df3b1-7e32-42da-a556-85dfc4b09e70', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 61).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '6aed4f7035f43824_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('794ccc69-06aa-40c4-8744-4275d1eb7166', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 61).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '0b5c489cbca1f95b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdbc0037-0da6-49e2-ba26-8f72a042a035', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 61).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '37a44ab628a2317c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a081501-ca86-44bb-9ddb-60e94a22afaf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 61).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fdded4a9294b8cf0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e323abe1-cb23-4be2-b481-564a4e232ad8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 61).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd00defd320fee641_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('648091ee-2a26-434b-a843-a3f41d73f2f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 61).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '92e86d86b2d115a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7b7036d-fbff-4d39-b275-4ec80efe0826', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.146.163.0/24 network (variant 61).', '[{"id": "A", "text": "access-list 100 permit ip 10.223.202.0 0.45.33.255 any", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.223.202.0 0.45.33.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.223.202.0 0.45.33.255", "is_correct": true}, {"id": "D", "text": "access-list 1 permit 10.223.202.0 255.93.200.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.45.33.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '324a8ec12979faa6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e0162f7-8466-47d6-86bd-c4c6e4ee3263', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 61).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '21f7399f57057fc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6e0af40-02d9-4008-9769-96f1de837ea7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 61).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'aca62f0ce65b93cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4d530d0-ce99-4bcb-9e91-b03dff7bab53', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 61).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '6d8fb7ae121fa96d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('773dc2d3-78a8-458f-ba6f-8dd52d4254e7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 61).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '470e65e279b71a66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a58fc62-5bd6-40b0-b5d1-75ba371a1123', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 62).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '94dab8f0e5ac697d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c76b5693-76be-4d6e-96b2-4aacffdd52c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 62).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '7179407aa9890229_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52dcbdd3-f7eb-4174-82a8-c0cdf9ff1af0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 62).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '0953f74c4ab822e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5f322e2-e993-44c2-8941-fb9fa96c745d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 62).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ff2184ec07b6e86d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44ce7589-c8a5-43af-a82a-d24bc75e14d1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 62).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9da457da551ea5cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60af6be1-efc6-4afb-9e7a-2c372066d1e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 62).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd849fdcebf81dfb3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c924c58-3ffc-48b0-83e4-03494e79c9cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 62).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '97b7128af1ffcfb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('432d8bde-7f10-4dba-b184-9ebdb3ae798b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 62).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '641d04fa8762799b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5ab3e6c-b49b-4591-80df-d40f83bce204', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 62).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '57e23041f771a5cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5940a239-5070-4d26-89ce-0051e77b5d18', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 62).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'c5924d510b0b9e49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88ad3705-e1ee-4d51-bc5b-91b626bf3955', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 62).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '40c55d1db0e4ebba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f30da59-506e-4359-a172-f00b3fe74004', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 62).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '20f256b25e195cbc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6623902e-d034-4963-a96c-47dbde38ecfc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 62).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7e97039548c259b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51f72899-a977-45b8-bab7-e6bfb134be33', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 62).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fae1666f5783ad23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae18a4ad-c357-4895-ad30-955de1ce05ae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 62).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c000b9efcb0e0212_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1dec398e-c2ff-4e66-b28a-8633d5489440', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.136.22.0/24 network (variant 62).', '[{"id": "A", "text": "access-list 1 permit 10.201.122.0 255.83.142.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.201.122.0 0.150.124.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.201.122.0 0.150.124.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.201.122.0 0.150.124.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.150.124.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5b5c42572eacae81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c9796da-b975-4d01-a5e4-afea7d2d0228', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 62).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '10ed172cd61cbb27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74db9246-e375-4f33-b774-3a1f9748abe8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 62).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c38d6d7fbf8c87de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e72e6e9b-5d72-4806-a36d-f11b0c38f61f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 62).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '74f7c802be355266_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0537d77-ecd6-47a1-9c10-7125f269fdb3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 62).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '9a68404e5fb33884_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbb1e9c5-161a-4eb0-b291-c2115f790336', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 63).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0f25f34eb39b1d7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36104ca3-4c2f-4815-8239-d417eb15e95a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 63).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2df40d745b3cda57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a60881c-853e-490e-bb44-4d09a9a25f19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 63).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '8a287f3393c9e8e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('895849cd-1213-46b6-998a-9018cd3b6197', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 63).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'e31bec8b92bef081_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62a8d47c-6600-4361-8b20-a19d4216a54b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 63).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b3618c8e5fe124c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f3cda20-91a9-4675-9ab9-330a5222709f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 63).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '53885c30d797a3be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('553fa573-d241-4739-a9d7-9f4def8d344f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 63).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '00273636ecf943e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73c72ef3-ce91-4210-a131-e6edfb67ebdd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 63).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c4a24990b3b678d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef6a8d08-0c50-49c7-87dc-8358bbae5f58', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 63).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '41aeebf9216bbabd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b0b6d7b-0e8a-469c-a549-e28903e6682d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 63).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '98aefbf3591903f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fabf387f-091e-4fdc-8162-2aa358f642f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 63).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '0e07647728853661_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cc40e99-8163-4654-9fce-8bd16c0f865e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 63).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'e7b91c7a9d74099d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd4ac4fe-1c46-4896-8d8e-807c1c91ff48', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 63).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9647f08b6c040147_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4d16634-e952-428b-9396-3dcfb0bd1b77', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 63).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1c01b280f42c3647_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9931b743-6e99-4b67-a8a1-940b5aaf59fb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 63).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '18749e374515f42c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e058dc40-5d76-4fa4-8971-c72a5fed69cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.207.227.0/24 network (variant 63).', '[{"id": "A", "text": "access-list 1 permit 10.224.63.0 0.19.50.255", "is_correct": true}, {"id": "B", "text": "access-list 1 permit 10.224.63.0 255.6.29.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.224.63.0 0.19.50.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.224.63.0 0.19.50.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.19.50.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1fcc872cdd3c819f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ad3aef0-2b56-42a4-aa84-62d997e2339e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 63).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '3e771b5178ee991b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ae095f0-13d4-4136-b116-8d3e03558f15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 63).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '1688bb94e38baf06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f581c9db-aa5c-4a44-ab94-1f1538c1f29e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 63).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ef7c6d35d089d03d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71450ff4-d034-43c3-9090-347b8e2585b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 63).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'd86ebd2ad2e90f28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('383e3ce0-870f-47a5-873e-974b9b0678c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 64).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '1a03e511fcd789d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c8015e9-9f71-4385-bc9b-46eb620d02fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 64).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0159220edf2e9a6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b47eb59-2ff4-4ed0-a041-044b2406e0fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 64).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '6642be9e7559579f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77d28c03-789e-43a0-8269-8c1a8e50ff40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 64).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '6b173e5a676784d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6771ed92-a5fe-41b4-a63a-c79f9d48b00b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 64).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'acecf2d94f0d57f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cacbd4bf-a209-4b58-9039-97479cdbeaad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 64).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '72b000aff57133c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc2f1e6a-6ac0-48d5-abad-717eaf5ba87c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 64).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fbf780508e56cea2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65718798-a755-43a7-98a8-1684e48124f4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 64).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4ab0f6b3f9ce67fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6aae9c2-dad8-477d-924c-d6580f3805b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 64).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '2313183ad291633c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a57df6e-ca0c-4c69-9134-564fc33f8a1a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 64).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '0f4fc848a192e892_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('524a4777-c289-46d2-8243-458c9b88248a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 64).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '3f396708869826b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41636278-4bd1-4882-bdec-7ff2bd3a1dcb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 64).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '51bfc90407dc2962_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db42e1b4-652e-465c-a170-dd36d829893a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 64).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'bd127da623a192d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18f0a254-2c27-44aa-bb6a-bc4ac30c48aa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 64).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '354d4914483e66d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df2fe4cb-73d6-404a-b832-0467c27492af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 64).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'af86010c407bdf9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('daee3f6d-88f2-49b5-b63b-1dc9acb02e70', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.191.10.0/24 network (variant 64).', '[{"id": "A", "text": "access-list 1 permit 10.166.27.0 255.129.122.0", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.166.27.0 0.197.73.255 any", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.166.27.0 0.197.73.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.166.27.0 0.197.73.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.197.73.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '04d9cfc6b799ae33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e7f38ea-691f-4996-b9a4-6724c79e6349', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 64).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '3736463d65d3345e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64fedc1e-23a7-4de0-b908-4b6d4bcf4ac5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 64).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a0c32b0b24201b9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90606998-ba07-4d09-89b7-dc075babea87', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 64).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '439afbbaa05a6972_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3fbca50-a65b-4949-a201-46d8b5b84740', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 64).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '7ae810c149ba2810_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3beb1631-3bd7-442f-9380-3a4dd007b64a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 65).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8cce203798e7f148_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78a6aee1-8bc7-4c29-a6cd-769f7de89c7c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 65).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '96635ef24c95550a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df95fe5e-b7f4-43ea-ad86-e595abe72237', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 65).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'f0ebaec9dd97e77d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f930f55-1ee7-4a20-bdad-ac78a574b7e4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 65).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '0d91873cc27abb2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c53b9b8-6e04-4223-ab8a-de7d4f233db4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 65).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8de8ec739bad4864_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a6422e7-dc69-4cfe-8ec2-dd24dd400b98', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 65).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '10700e607964502d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d69c7f1-220a-42b4-b8ad-c5ba09efc2de', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 65).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '845c275931015f8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffd2bb40-3c8a-496a-a288-3017db3153bc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 65).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9cc4b36a84e734a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0b88a73-690c-42cb-953b-e250a493fdb6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 65).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1d8b0ea6061f0ce2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53b560b9-6fbb-4b03-927f-51e4e4655843', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 65).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '45fbf4706fb60153_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16ffde17-ed4d-4d0f-a552-1c52e9de45c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 65).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '95eb08f2cd81171f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f11ed119-9836-449f-ad4f-bb0d77e65206', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 65).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '6e224ca3d4605f00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2813d759-d6da-40c9-84a3-1800135a0b79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 65).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'bae3875bbb7f0274_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acda7add-6d61-49da-8654-285e6c2d70da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 65).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6098ef74aae60253_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c74137b-d1cb-4257-8df5-db1dc3f83162', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 65).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '02ddee2ab81335de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7101ece4-1232-41c3-ae29-e3acf1da0dcc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.126.54.0/24 network (variant 65).', '[{"id": "A", "text": "ip access-list standard 10.93.179.0 0.221.237.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.93.179.0 0.221.237.255", "is_correct": true}, {"id": "C", "text": "access-list 100 permit ip 10.93.179.0 0.221.237.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.93.179.0 255.152.20.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.221.237.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '22d804baeb0cc266_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa0045c6-d61a-4321-ac1e-4cc8c35a97a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 65).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '900eae05a3d6160a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c735b970-9f3d-46d1-8db2-787d5155ebe5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 65).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8d9cfb4a2f9eb51b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('778aa8fa-1343-46e1-8297-6235fe474a60', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 65).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e1952e352422ea63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9195c36-96c8-4ea2-a242-4555f31967c3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 65).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '52d75254f4098b33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f3cfe4c-7391-44fd-8e0c-9401038dbf0c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 66).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '89bd432f27f25bbb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20f9623a-e5f0-4570-818e-1419ed3587c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 66).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3ee3be209797d275_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fc00a39-02e5-48b7-a4b8-c1e330e03893', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 66).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'f336e38cc63767eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8965572-d5f2-4784-aebb-b868dc4268f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 66).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'a89c2de55291cf62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e4cc416-6f55-40ab-aae2-400d6e6d6e91', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 66).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'efcdd288b28bb066_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5b6b45f-0a85-4b42-a751-3e3db20d04b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 66).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bdf5d15811389513_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72325332-6b32-4518-aa9a-455eaae9ecf5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 66).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2e96a046a668df19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fc51a0c-3a3e-4900-94a2-9564f4a69814', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 66).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'eddaf628ce46b01f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('122af3c6-977c-43a5-bb7e-83020af2acee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 66).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '0758e3b61c3a1a69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99173366-101e-4b50-b6b9-b846f376f859', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 66).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '118e49da06b14359_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7dd67749-e383-47a7-a08b-cb12b55504b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 66).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '4a255dece6734e4d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3663a6c-4e35-4b8c-9939-7a1b8b77715d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 66).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '7e7155e5c24032d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2662c7ec-36fd-4271-8546-14ff250aec20', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 66).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2321a632ae511328_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34a60cec-e9e9-4757-bd4e-1978ccc47f4c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 66).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '563af3d6fd349209_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8f30b44-45d3-40bb-a641-df2d857a5ed9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 66).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c3f4a63c2c6ef6b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2833a151-0151-4e13-ab44-262451d75284', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.28.177.0/24 network (variant 66).', '[{"id": "A", "text": "ip access-list standard 10.161.127.0 0.4.216.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.161.127.0 255.131.207.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.161.127.0 0.4.216.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.161.127.0 0.4.216.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.4.216.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '92b6be01e8ad24fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1d13691-ec3a-454e-83d5-f1cf1bbaff35', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 66).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'badff36df84838f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6de7fea-0ff3-46bb-92df-5fd4c8a86ad1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 66).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2be0c06b07346d9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fc50fa2-d753-4a33-9264-2297b161a8ef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 66).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e33b225c4e6fd08a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ab34225-8e2f-4129-9647-f6cc6720ab0b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 66).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'b54a3fae6bd1adfd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('492cc76f-f91a-470b-857b-35100b5563a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 67).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3f23ac66d1958431_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98f64da4-5d8c-4e4b-9e37-48028f703973', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 67).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'be2bdcf6e544161b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5bbe318-cd46-462f-8fca-3a21a2347f44', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 67).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a54e32616867f290_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d8767e9-86e1-4a2f-ad8c-e2526536ba63', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 67).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '3eeb72bbe6e83efa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ea78234-84dd-49d7-977e-fcae69cb3d49', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 67).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c093e5befcdd9cd9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47e05d85-71d2-4530-845c-e48318e753a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 67).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2580e4f8b0f5cc54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18e84d3e-4595-4110-9bca-a185ab49d6cc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 67).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f15398dfca72a283_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7daca798-a28c-40c0-ad6b-b30b4e098a13', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 67).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2b44c6c4d3181ccf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c11842b-b33a-48ed-936c-3cc1cb14498c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 67).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '27392524d11e6c96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d3ee279-b0bc-4ca8-a45d-92eee43964ee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 67).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'af8e20475021f301_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce77306b-21c6-4a78-859d-2efcbaee2ea6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 67).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '209d7548197985d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3f181e4-75c7-4617-83c1-c2e95d8b29cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 67).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '2fa82d0151dcd46d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7decb077-00bb-44a0-92ad-2b7b99dfc785', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 67).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '23ee53fd7208fa57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4753031-6c1e-4455-8f20-3870993e0fe6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 67).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '00842d5deea7610d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01e773b7-feba-4adb-b3ed-d66dc56f35f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 67).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '57f1e9f72aec9362_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d197f00a-9623-4a70-a80a-41dc13090c81', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.134.146.0/24 network (variant 67).', '[{"id": "A", "text": "ip access-list standard 10.153.106.0 0.70.162.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.153.106.0 0.70.162.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.153.106.0 255.43.185.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.153.106.0 0.70.162.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.70.162.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b432788a956301ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b786c58-0822-46e0-8338-1b6e0c84b641', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 67).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '5d381ef157b8f260_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a21a9078-1f29-4588-b521-92e3f5b138a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 67).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3f243d53db7b3162_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8482b242-7379-4324-a750-a329d0d485fb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 67).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ed431de687c350a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c533ccae-b697-4496-bbe2-1a8ed71d1613', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 67).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '628f88711cbff7a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cbc6d18-272b-4b45-a368-ef245105e6f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 68).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '52c0f5392d1f7176_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74f6ead4-52af-407d-b1f5-f8be260a1a33', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 68).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '5ea2047d4f051206_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d9ac959-f28e-49ed-b395-e69998847d3a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 68).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '1d30caadd55eeca0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ce7a921-e98e-44af-ac02-70b75ee9002f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 68).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'd9c74b3b21532a46_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('862121a6-d120-4fcb-a8b0-6e35ae10fc8a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 68).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'dd7bc6712daee8c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b71cb405-989f-451e-8476-a87df7d3d961', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 68).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f3e343f50847c8f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45465429-8e69-47c8-924e-8ac5d0ad21e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 68).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '37c5e9e82e90cb7a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52889113-46e9-43fa-a5a6-6a6bdedd72af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 68).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '22054b73c074fdaf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ff21ee6-ebd6-4ed7-8a76-2d285c3a1bee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 68).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'e5bca11a8a6f3a9a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15886bdb-cec2-4745-88e2-564199aca85f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 68).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '16cb24e186765065_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6244bd66-e761-403c-b588-087294286d63', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 68).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'fc57a44706406eac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c96fc6a5-8462-461e-808e-79ffeb1dd8ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 68).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '4be3b007a33bf35b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cccd90b-f25a-4f33-a8e2-bbda40b5f55b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 68).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '47063a5724d26bc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a87c975-a71f-4cf1-bd00-989e5874a810', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 68).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2abe012a16626579_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('932def86-0acb-4e1e-8083-44d2a379f05b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 68).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'ebaf920d07f12a7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a27ee27-e384-4fe9-b238-3a22255363ee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.224.63.0/24 network (variant 68).', '[{"id": "A", "text": "access-list 1 permit 10.139.114.0 0.133.17.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.139.114.0 0.133.17.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.139.114.0 255.37.48.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.139.114.0 0.133.17.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.133.17.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e54a4836f3b51f69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1bd3dba-b70e-4740-88c6-c3424f2a4c6f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 68).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '5cc46b9657674bd1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e9ded45-5b1f-4b83-b9af-0475896d58b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 68).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '077baeb4c44dd58b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3efb67e1-089a-41a6-8093-0e30daa8d415', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 68).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '2d9a3a9f332ee8f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d6f9069-6e1b-4c31-a821-bb92d8a503a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 68).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '5894eeaf320609dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c7c8d6c-6eda-4fa7-a426-626dbe5003e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 69).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a34719e9b7a0e895_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2d9a318-34db-4fc8-af8f-7c936b396fa4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 69).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0667080bc3bbdd81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84a7e07a-977f-47e8-a20c-29634f97dbb9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 69).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '6ec84f3c7f875b7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50b3e127-b947-44cf-8a3e-8eb2c8b8a332', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 69).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '814736ed65a0ca42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdcce07d-ed16-4425-835c-d99272dac2dc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 69).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ad88f5c0cbdaff59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2e357af-9113-492f-8d06-b5542f92db15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 69).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '431f23752fbb49a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9dd22294-249c-42c1-be7e-f1734e597da5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 69).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b7eeb4b5b49653d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9641ae5c-84aa-4846-be57-f862779d168e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 69).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f54661bd208f8d54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a514e0ec-64a3-49ed-9ea1-8ada10397f19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 69).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'ff68058c4beacd2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64a66492-770f-40cd-98e0-1e18d3e621d2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 69).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'd7adf9ada97799ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df988acb-abe7-42b3-9dc0-6e5f39695c93', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 69).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '406fe134187010dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a022837a-9482-450a-b26f-7ad47e267809', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 69).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'e271993e841e4877_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e16b9e06-3088-4a3b-9acf-1918dbd63fc3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 69).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e6fbf0406688fd5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d31a6466-a31c-4464-9362-c03aa30347b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 69).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1aeac6140a66e8af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f144b0e-5ea7-4bbe-8817-61c8f40dd286', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 69).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '5f47ee0ebc0067bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c859a2ff-6702-4d33-891c-cec3e9f0a49d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.171.178.0/24 network (variant 69).', '[{"id": "A", "text": "access-list 1 permit 10.224.191.0 0.19.195.255", "is_correct": true}, {"id": "B", "text": "access-list 1 permit 10.224.191.0 255.90.62.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.224.191.0 0.19.195.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.224.191.0 0.19.195.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.19.195.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ec3e8e1d76c8c47e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2379700a-f280-470a-8eb9-a9049207982b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 69).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9c90fb8024cad192_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b29819a4-e3b3-43f8-ac08-0b84c455d51d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 69).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd3391b67c6164f34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53c1bee3-e05b-4cee-8e47-eb87d8c6b7ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 69).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '27065f4f037f84d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16b4e624-02f7-4a1e-b990-09f6d53dbaeb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 69).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '4815821f84052b67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a48d580-0117-4ca8-bb88-796d4ffd8993', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 70).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0195605d44db9e1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26a25311-967b-43aa-b82b-97866a6de846', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 70).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ee21d823f5adf714_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('161fab0a-20cd-482c-8bc7-5710559c7d9d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 70).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '923945fbb0815313_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('857bc91e-1f29-403d-92db-98d4a96c0287', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 70).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'acc6a2b0ddb59b8d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f952f45f-a036-48e5-a199-5ec789804c81', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 70).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c044b9493ebac612_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc583d6e-338d-4fc7-b4e0-59c5faa45a24', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 70).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fcc03376bc235a46_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('636f9920-52a2-4cea-ba82-9b896cf7e8c1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 70).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ab584ba156315885_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2888505-4ac5-40dc-a326-fee3630bc1f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 70).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '950e0fee6e0d0704_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('831f13a1-ba97-4f65-8c6b-2c4c37505c76', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 70).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '23ab10d72335fbf7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fc554ed-d921-4485-b211-988480367581', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 70).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '37353f03df321e04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9178d232-3c4d-44e0-a101-3ca19814da55', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 70).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'd67416f577d135c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66dbe3dc-f23e-4e86-aa91-86b7faf983b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 70).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '4ab3ab714c344162_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8e3e235-9a7c-4b5a-9027-d17d21e08e53', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 70).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'eb2dd09ba31a5937_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8efe5d0a-160b-4b49-92c1-58997e597a13', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 70).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3f55effed43c2a40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1dc58f3-6457-487c-8da9-ea7494bf2304', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 70).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '707d16f0dac4927d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6dc4d13-a53a-4e0c-a420-e5961786618c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.76.10.0/24 network (variant 70).', '[{"id": "A", "text": "access-list 100 permit ip 10.32.141.0 0.142.88.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.32.141.0 255.163.190.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.32.141.0 0.142.88.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.32.141.0 0.142.88.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.142.88.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7c3c865984b84663_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad458910-116f-412e-a712-d53230dc86d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 70).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '160eca33afd3b947_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63949101-276e-4be9-87dd-cdd3b87f09ba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 70).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8a56abc3e0f8d1a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de3e681d-648d-4e30-8a99-dfa3678b4548', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 70).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '00a13e2e01d839d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66d21b18-4c16-4ed0-93e3-9642981d732a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 70).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '4c8842afca19c706_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23837e91-e89c-4875-9e91-8d7f4292ad7a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 71).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a83c15b1ecc663c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b8cf56c-e717-49b9-b13b-2cfef807532e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 71).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8731acf0e9dd7d01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2fd6542-f46c-4944-98d4-6e625103ff62', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 71).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'ae736c42e089edf8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('086a9fda-8e36-4883-97d2-f6ef7c486e58', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 71).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '5cda6956891dc863_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e56b43dc-59be-472f-845a-d51056f28418', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 71).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '26dacb9b49d8863c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbf4397f-213e-4512-bcfc-6ce7e2fb04f4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 71).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '173e6c8dd911f93a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c4bf176-6309-426b-96a2-c1b7389a98d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 71).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a62703b8f712747b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e941022d-217c-4fa6-8dc7-7474af66b921', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 71).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fab17ac9f1b6797a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c1bb56e-b47b-4b0d-9dad-cc8f0c063503', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 71).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '9f1ac7df8e420893_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a33bcfa-d0da-4cb3-bfff-62cd5becdee4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 71).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '072b89f6222f7380_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0f3e752-1b2c-4812-850c-2a55332d2348', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 71).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '00fd9b132e858b89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b870d9b-c724-4dd7-88dd-a9120695764e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 71).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '7bc367133015b758_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a122b7c-1767-41d2-a449-247c1dac3a98', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 71).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2c9c50af9379833b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ddab375-bd99-4543-8287-c9d9e622b03a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 71).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fd9cbe44ec6461f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3040ba3c-e6ea-47ae-9756-14eff8f9b531', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 71).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '130f9135ae6fa51f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b9a27ce-0717-42ec-ad2f-fe690d584dcc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.116.106.0/24 network (variant 71).', '[{"id": "A", "text": "access-list 1 permit 10.135.47.0 0.189.34.255", "is_correct": true}, {"id": "B", "text": "access-list 1 permit 10.135.47.0 255.104.53.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.135.47.0 0.189.34.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.135.47.0 0.189.34.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.189.34.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '994c18a74495b425_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9063df4-dc8f-4f51-8d78-c9634f9e604a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 71).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '15a8583a985033ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efde6ec1-7050-416c-b2da-5ca273f78eab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 71).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'af52dbd1c9966135_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99fd1476-1f62-4319-a454-390f4ce7dbee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 71).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '81ad640da8afbccd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('887182a6-9216-47a7-aa6d-31773065b65f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 71).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '6088f5a82c3b9368_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eec6e32-1de1-4c51-9b73-2259ebb80005', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 72).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'bf66accaca5cad8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98f802f2-f361-48af-9399-12b7dc9f0b8a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 72).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '75adc2f1babc322f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbcb8eec-2b9f-4704-b5fc-fc17e45042d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 72).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'caf99730cf60c37a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8df21780-ebc7-4fdd-b917-06dddab8da28', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 72).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ff93b2ae33858eee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('302e41ae-1230-4bc2-aba7-f78980ecad9e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 72).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '87f45d94f5e25812_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7cd168c-2040-411f-8f4f-edd9469291bb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 72).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'eeff3a2fd365c3ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4aa484d9-2961-44ce-991b-2fe7d5b92900', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 72).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fed018aceb8ede66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73818ee1-053b-45fd-8056-cb152f4d826f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 72).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7933ca9fa39c5ea4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5649d5a-5d4d-4f59-9373-8588974bfd59', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 72).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'e7b4fb4d3d653834_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0413a662-cc49-456a-8ed4-6632e0200bc9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 72).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '8217b8988e19cc91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fce195cc-7c74-4d96-8cd0-be66a5f740ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 72).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'c723ec763bb6d6bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2a3e03a-d916-404c-83ef-12226ee735ee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 72).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'd4e912528b019c55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('046fd677-6f10-47ac-953b-c7c1287f8c05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 72).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f10cb7604411e79a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65248338-b005-4a3c-8080-41e8d615ce71', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 72).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '48ed755bf30a5e52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('179a6ed2-7983-4361-a5cd-8a00595877f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 72).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '2aa9cefac59f4d2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ccca7fa-3d75-45a8-8e90-d0bb5219e6ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.219.207.0/24 network (variant 72).', '[{"id": "A", "text": "access-list 1 permit 10.1.226.0 255.163.190.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.1.226.0 0.147.149.255", "is_correct": true}, {"id": "C", "text": "access-list 100 permit ip 10.1.226.0 0.147.149.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.1.226.0 0.147.149.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.147.149.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a600c875dadb4a1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f835db7-27f6-4a57-aad5-6344fc8b5bc6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 72).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f9fbfcf914957049_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f76886a3-81e7-44b6-bb74-eb14d10f9ad2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 72).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '73deabc27a246ced_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91f9cc6e-1e3e-49f6-9c7a-d8326554fb87', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 72).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'f17f429f0b9e0ab9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9f0f2fc-0e15-4caf-91f8-3adbef1fbaec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 72).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '329f29b317a9c45e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('564cb26d-448d-4350-9cad-6b9d692f15fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 73).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e0daebc5df1a2f79_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68f79700-3ffb-4e27-b841-edc7ff3091cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 73).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '10bca9e151d643fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c89604ae-db34-4f81-9b20-ba25f604f492', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 73).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '75f84da005a485d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2db4d1e1-9ee3-4814-b99c-a12f7107d954', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 73).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'eb528dbe33669aa0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdd8479c-837d-446c-bcbe-a900b18aa2bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 73).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'da29e0fbfc1c6a33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0293796-ca24-4a35-943d-c059173148f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 73).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f688f3fa42bb0a52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8e65fb7-3ec8-4db3-8b1c-6a833eb7dc6e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 73).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b340d0c34b6bddd4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd5fe9e8-f203-4fed-9fae-2d447d20e246', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 73).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6d3bfe5d63a51f37_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf1ef471-c49f-4191-ae75-1dd87f8ad46f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 73).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'e1eac3f7c1d67ec2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ed0017b-c3b7-4ec7-a7e0-493b3bb5b6cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 73).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '50d68e27d1b9fc7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5784157-0b43-44be-896e-e031e0abbfd0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 73).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'facac0d62a93ca4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcd0b813-a77a-4391-b98f-5211679f3e0f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 73).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'f342ec5b05117b28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f3e5965-8930-48e6-a041-93fa5d4985b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 73).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5320a1f5530651ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94ac298e-2202-49cd-b2ca-73805e1a9153', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 73).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c61d74698528c100_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d635d72-54c5-49e9-89d9-df98ca5c3f0b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 73).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '9b81ea95a20c655b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c361859-4f43-4d16-a777-0545413071ed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.6.177.0/24 network (variant 73).', '[{"id": "A", "text": "access-list 1 permit 10.30.25.0 0.71.185.255", "is_correct": true}, {"id": "B", "text": "access-list 1 permit 10.30.25.0 255.63.63.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.30.25.0 0.71.185.255 any", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.30.25.0 0.71.185.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.71.185.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '14eafa750db190c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a30810f-faed-43ac-9dc1-d7af4612d218', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 73).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'a4c5a2e8060bce7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c593dcad-406c-4051-b478-055c28bcc718', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 73).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3ab10e88acb5002a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f57dd8db-332f-4b9b-ba82-19687e29fe3e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 73).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '8f8e586d1a4eb8c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a86873f4-d2aa-4548-be52-3379ac27062e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 73).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '4d5c85da9f874685_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8352afc1-a531-421e-b69c-20df207770ef', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 74).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '882caffe478e7f13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb4ee4b6-03ed-43fe-a722-94ab9c280a59', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 74).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '03f4ef4ebd755848_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6fb5300-20b9-4be5-a098-19b0b9efc685', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 74).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '753587f79a7a8e8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8da15da9-5733-4499-b1ee-fe6a6e60a2cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 74).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '49ff5d83609449e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('070320a2-d610-4800-9a4e-198d80b344a4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 74).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '182d74d8e20d18be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef2d6e27-4290-4bb7-a6c3-8c4e7e51ed7f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 74).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5d9e948f149bc690_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d08828e3-2832-496b-984d-2b24c6f47387', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 74).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f764f337918f5cb2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abd4cf72-90dd-44af-b4dd-55ecb8f46515', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 74).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4144c747c5a6b021_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c4d73ff-f271-47c4-af8a-ebfe9a8f5d72', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 74).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '4c2557442891d84b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03cb25ed-55df-415a-957e-f5e6aec278a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 74).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '87702709a571cd2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('709ae008-4bdf-44c2-844a-dedd01392427', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 74).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '6af29c8c63cc14c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6f734a2-4da9-4f2f-bd95-097d73bbc517', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 74).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'dc50a0f1cd13faaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71860ecb-c649-48da-9f90-2940ee8934d8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 74).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd76256cc00d95bd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4207f098-11e9-4be3-a2f4-f23b5d9311af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 74).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '696b3ccabbc0da77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ba757e7-3e3a-4934-8d2c-1a14490fbbd1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 74).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '739408c21fa15fc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b248cd44-f6c2-4772-9ca6-44e1d883f0f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.131.45.0/24 network (variant 74).', '[{"id": "A", "text": "ip access-list standard 10.101.186.0 0.104.179.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.101.186.0 0.104.179.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.101.186.0 255.178.85.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.101.186.0 0.104.179.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.104.179.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '403b9fde3b28b976_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('554344b5-edff-4349-8dd3-12dbb4cd445f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 74).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'ba0cad5235cec4c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8d2b468-f32b-4040-9080-8524845c7a23', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 74).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd8845f582d92e4fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('571b5ae4-31bd-4bb5-8328-58ee8eac64f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 74).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '34c32b4ce3e56b1d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c72422c5-fbbc-45b6-a2bb-f436ba47a6f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 74).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '482725cc37b0a991_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bcf08bb-467a-4e38-a5cd-783e98eb3586', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 75).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f895e1e2faf4f63f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efa84b6c-cd05-4457-afd7-4b8a90b34597', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 75).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '33466e52e5d44098_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d3ff377-58fd-4110-a86d-10d9a6668a1f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 75).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '901db31c160b2535_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38f8c3c3-ea4b-4c09-b3df-a0da0aa9ea73', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 75).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '7e391da418d1aaeb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('781e03ef-7640-495b-8a5f-e4781d23742b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 75).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3fd28da686905845_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('121a3c1f-b926-4c3d-984c-58a83d558b19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 75).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '311164d9728eacff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bbd7ace-f6f0-4ed6-9864-0c3acdfddb90', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 75).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '23d3428f531b8843_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39f868be-fb11-4376-9be1-c1ab077e7576', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 75).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fdcdb1504c5c04b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4847b3d-dac7-43cf-bc13-89c655b55120', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 75).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '938e38ba0f0e8130_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2db9d3b3-b9e4-4641-814e-5b6326faecac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 75).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'c51ea47e2c695033_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0e8ce07-7dc9-4830-b71e-9d50284d0908', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 75).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'a1ee6d7d1ebd31d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a226776-5c2c-474b-a222-e9251bc0c7cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 75).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '377735540d37d19e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55d446da-50bb-4df8-a04e-9f9fee60f656', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 75).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f9a0833e630b80d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce1fb807-b638-4e1b-b321-8b99a89e7e8f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 75).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '87777330a7124d4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bc4a5d4-41ee-4f12-976d-b3d012db9845', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 75).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '30c4dfab47866580_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8178082f-e908-42d4-bee2-3b794fe3999e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.123.116.0/24 network (variant 75).', '[{"id": "A", "text": "access-list 1 permit 10.48.20.0 0.161.168.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.48.20.0 0.161.168.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.48.20.0 255.148.74.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.48.20.0 0.161.168.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.161.168.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'dc6780a6ba26d53f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2496d248-bcb5-4707-99a6-a605409d83ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 75).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '2e152793122a96b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c5f3be0-3fc7-4aff-a8e7-d58cce660f14', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 75).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'e41fa8fe2622fc85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84184dee-8dd6-4858-a63c-d365fec7cc98', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 75).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '82bc59993335b866_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4daf8e7e-9098-4ced-a86b-518c33d3a563', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 75).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'b8cd396ef839dec8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('782edc41-ca9b-4d3c-bbb1-e38d9e6fbcc3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 76).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd1b5da3a17892391_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbdcfb18-30a7-4860-ade3-8f927bb2c0f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 76).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f24512ef42ea1a5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('003317e2-0733-418a-8efc-0e47aee8d157', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 76).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '163e0968b0917207_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95dc112c-af3b-41ac-aeeb-77e03d4a2f8c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 76).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '52487fa0a56669d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08055a6c-6f49-4f65-b6a5-2efdee312f74', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 76).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c5e0e0cbbbeebdba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57e37457-d413-420d-8669-e2015ab482b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 76).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0388219843b0a5b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2cd1812-2325-4f8b-bdde-d3cc7a998987', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 76).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '73318cee85e83d3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acd5bb2c-0572-424a-8375-a75c57fc35ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 76).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '66b3166239177b4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1208aaad-d2af-4fab-a1c7-2dfc0cce8ee3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 76).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '3d7867aad99dc53b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bda1064d-0a96-4e31-b746-722392038d3f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 76).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '927debf7a211b0bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e9a6757-5034-41cc-a0b1-27ce6efeedcf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 76).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'd5262feba9cc016f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b3b6107-308e-4169-99bd-ddc2fe904394', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 76).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '94e135df671d1d75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d158a3d9-bfc3-44a9-b5db-8e780ee278bc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 76).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '82e6aa34857ed86c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38dd1266-e89f-4eb7-a810-2ab806b8c7e5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 76).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '947224b059edd47e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f2bbcf4-ebd0-4645-be82-6eba5152367e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 76).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '095610c4de7c4e84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7582f5d0-9d6f-4314-bbbf-deccac9f0eb6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.55.45.0/24 network (variant 76).', '[{"id": "A", "text": "ip access-list standard 10.34.226.0 0.35.196.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.34.226.0 255.231.31.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.34.226.0 0.35.196.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.34.226.0 0.35.196.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.35.196.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f2a67fd4c79c16e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3d7af3f-cd4f-4daa-a830-1b6e9b4f0394', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 76).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f292325f90f58f69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4b1c715-2662-4b0f-a647-80158c81f1f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 76).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8c95075f6f2309d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c85a68b5-2ce3-4926-ac09-5cd3c5cb9466', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 76).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'd271fc5dcc5f5fdf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5e4e0a6-84e4-481b-accd-196a396d6f6d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 76).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0d010e4f594c4523_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f812060d-06a9-440e-8091-2256f44754a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 77).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2617952311392883_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9374a5b6-ece1-418e-a0df-9f40d1093f53', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 77).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'dd5506f53f4ad2ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7992088c-e71a-47cb-b1e7-f5f1f1f531dd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 77).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '93b3edf0da07611c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6eb11c1c-d6cd-44b5-bfaf-6c8c5f7b813b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 77).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '96ef6f9a9b1121ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b1b6493-ef2a-4e95-9418-91f39d315ac9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 77).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0aefcc776b252076_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4141978-132a-4272-8b26-ed3e75373dde', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 77).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '16d6930f8db33ac9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6cf1ec5-0b99-4c5f-b6cf-5b88d99045f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 77).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '373bf4aedd8a0d81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('235be797-0268-4149-a382-140d19030eb6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 77).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'eea925fa61386e57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4dc7a94-cd4b-45b1-94e1-009a610f0adc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 77).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '00bfb9ccc04e3825_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('caebd0d7-a797-4218-8a29-02004bdb6a59', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 77).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'ce9525c58c77d658_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25b5ad49-22f6-44d4-b48a-5db6f35e2ab8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 77).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '5fae237f0145030c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('926f2ac5-3794-49dc-a5d7-b120d5e68110', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 77).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '298a8bb4a83b42e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a8d9cf9-d20b-4c33-9f4d-73c5f76d52b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 77).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '90e10e354a220bc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e7fc329-7c6d-438f-9023-b01badae9446', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 77).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4c090d12bd3a561a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c6e2ee5-ff23-471c-bf37-f9789a9ede85', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 77).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c28780407cc2b0e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('728fb562-ef8a-43c0-8e1d-1d13b9b982a9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.102.28.0/24 network (variant 77).', '[{"id": "A", "text": "access-list 1 permit 10.61.12.0 0.107.77.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.61.12.0 0.107.77.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.61.12.0 255.117.159.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.61.12.0 0.107.77.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.107.77.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f7e9135bb9ad76bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29728c90-8c22-449c-a41c-dd55f734b950', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 77).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'b48df22a5ecfad56_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f417486d-7237-4572-86ab-acff5b9da1a2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 77).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0a138015f822c72f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('953fdf6a-5fab-48bf-b5f4-5b0a4f897804', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 77).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'e7bffffd10c09d9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36a66b53-e9bb-4250-b431-8aac18cd9b15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 77).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '6866a77ce2eca5fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61f525bc-28ab-44ff-ad19-a8180682e3c3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 78).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '035353ee30f3da19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4576ef9f-f511-443e-9284-ce0792eb3f5d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 78).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ee6af40e5b533184_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d3eddc6-8a42-43b3-8ab7-bd95246fa52d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 78).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'b61d3935806cdfe9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('466091d5-b037-4128-a45c-245543c2115b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 78).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'f256c7d180d33e5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('242bb982-eb7e-415a-80a7-5f2572bc12b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 78).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7f9243d80ac9347e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c6a14a2-fd89-438e-8b27-4fc5d14f2760', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 78).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c01e7b005182afe7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('871877a1-be9b-4493-987a-971d0c814a08', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 78).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '26d86e7eacd5d6fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa6b083c-2998-40af-8826-fc2d583ca0d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 78).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f3df2efd28a4b283_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2349593d-5e5b-4fa1-b876-be2a5b20d486', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 78).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '56e2ff3520a2e568_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77a494d8-e90f-4977-b24e-cf53e1672713', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 78).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'eb347ac5adf0525e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0973545-4ab5-4b27-a5ae-a3c12164d136', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 78).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f2c7598790c3f877_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31db6415-826f-4c11-a874-0944d0b0afbb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 78).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'a4928d3677e2d905_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b99f841-8a90-4886-84c6-2ad5ce3362e4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 78).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '77401d859d36541f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('304942f3-3a82-48b4-bbc5-e49c1c337448', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 78).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f77775a2f863746f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b989faf-135a-429f-8e45-2d2af2a292cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 78).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'cff8dad20428c623_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0803d163-412d-409d-a6c4-17d92bdc34c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.57.25.0/24 network (variant 78).', '[{"id": "A", "text": "access-list 1 permit 10.42.70.0 0.239.113.255", "is_correct": true}, {"id": "B", "text": "access-list 1 permit 10.42.70.0 255.177.86.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.42.70.0 0.239.113.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.42.70.0 0.239.113.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.239.113.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'aaf02c2d771b090e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87692f71-abd2-47a5-8227-e24ea7777c02', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 78).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'a594562f68e3d809_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8701ea56-1027-48c0-8812-2e6e4dbf0eb1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 78).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '461eb68d49a3442d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33f4b550-d175-45f5-92bf-f03a2664b5af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 78).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'eb9cbf24b4d0fd7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('202daf5a-062d-4281-9475-e62aec4d5732', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 78).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'd418b38b354aa43a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16cc8018-e110-4d42-b14c-49595dba510d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 79).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'dd43ec31e6de7513_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99fa4a0d-7256-4d53-94c5-a5d6594084ac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 79).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '7b2435068d75c647_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05021396-e757-4a2f-b2d4-e770e49b1a3f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 79).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '8246cad4f0d24c6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('326a3848-2fad-48b1-97b2-049f07f68742', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 79).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '3fde76566655273a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a85132ca-584d-4cad-8f40-3766c2fc9fe6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 79).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e10c996cf866dee4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b254737f-c6a7-4cb9-8cee-163f7706b272', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 79).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '088b1ebebdf073c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c9c984d-3c3d-4843-81d6-8d31595b161a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 79).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ce20bb77218bae74_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('252e9a4b-d310-4f1b-b05d-d24a5e955872', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 79).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a132b014da802154_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('473da941-4a87-42e5-a21f-07e41d3594b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 79).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '006aeaa9d274fea9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26e47df1-1cdc-46b9-a43b-b1663ebac911', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 79).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'f0b1a294693a9937_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b38a2f3e-5306-456d-8046-180815ec9f4b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 79).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '588dc9d8ef5a05fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f82f5df-77bc-4d22-ba53-5c459d251431', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 79).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '352784059351b059_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e6410b7-ebca-4dec-a751-b984dfcd7757', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 79).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '75bdc6138ccd097f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dc2c4a8-5330-4bb5-88d9-e84b817b7662', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 79).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '5f5ee52b00ec86a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2459641d-0f8f-40be-ad6e-d14900210b71', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 79).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'ee3d8e6b06aab77b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd84dc5a-e8cd-410f-8d4d-a550da284baa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.209.67.0/24 network (variant 79).', '[{"id": "A", "text": "access-list 1 permit 10.191.45.0 0.19.160.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.191.45.0 0.19.160.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.191.45.0 255.164.81.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.191.45.0 0.19.160.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.19.160.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'fac6f5359fe0d409_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('482178c7-8bfb-4e20-a5c8-560211990618', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 79).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '4dbc0e4123544113_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b95cad3-b41d-4fa6-a9af-950a925f00dd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 79).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ba13eab1af574022_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('448afffa-59ae-4885-8375-51174f9769d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 79).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'caf193a79b6c02db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b18e65bb-3d87-4613-b160-a705e6c1dfa3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 79).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'cb5016a354adc137_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cf8f084-40b9-460d-8480-efc07e59c9d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 80).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4221d4a023c0f65c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90e18d70-621c-4f3b-8ce2-db5fc2233d3f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 80).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd4e51a70f2acfa7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f7f9fea-ea69-416f-b692-193c388f8a87', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 80).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'c4f859861fe86bbb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9239f5f8-0dd8-41c3-b33f-092aa383e56f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 80).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'c828db7abb20733b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1dc812b-9513-40e2-9a82-b4f0c8e8cc79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 80).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6eaf52d730bc69aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8686f90e-c3bd-44fd-b683-e812a1bc15c1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 80).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '78f921821bf152e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23fe34b2-890b-49d5-a4e8-2888dc7bc5da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 80).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '265bc0fac7ac8665_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b3a9d26-1577-46b4-90ae-4e8e32a7c058', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 80).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '90edd73338ed824a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef34fc64-b8b5-471c-8148-7d36052606a6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 80).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '10395d3ced48ef23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7a23a32-7c1c-4e12-aa97-89c3e36a41aa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 80).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '2a658d48ec7b893b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a73bdb38-c3d4-4877-a27c-e5c8cc6b2ef1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 80).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '1a3f36c5a3b9709c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e56d495e-a41d-458d-87be-9df815aaf3d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 80).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '5eaf5ac0eb50e787_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a33188b6-fe4f-4210-9489-e4e3d9d84203', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 80).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '15e64d9eecba4d33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57ccafb0-164c-43d3-976a-4df07692a55d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 80).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '96df2330f31110d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b0b5d42-e84c-457f-970f-b1ac6d727e6f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 80).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'cd1c1b03a5dee8fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6c33af4-c432-4f8f-abc8-ca5e3207b438', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.6.247.0/24 network (variant 80).', '[{"id": "A", "text": "ip access-list standard 10.168.64.0 0.193.245.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.168.64.0 0.193.245.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.168.64.0 0.193.245.255", "is_correct": true}, {"id": "D", "text": "access-list 1 permit 10.168.64.0 255.177.255.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.193.245.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a2327fe18f2934f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38c09d58-2c50-482f-b63c-5b52fe5425f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 80).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f74e3e7b2d5aaf90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35bc3d58-4100-4db6-9c75-b46da5c65474', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 80).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5534ffe01bcd2dfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf5fa4e5-cac5-498f-b6b3-12cf1b029699', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 80).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'b7cd7a644c62121c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b2450f9-78d8-4102-b855-776520856aa0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 80).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '41b1594402e8c512_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a12add7d-61bf-4fae-be1b-1833f11e90c6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 81).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2ef1e860c27b9273_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee0bdb42-cf55-4e50-b809-2365ebcacb17', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 81).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ff557ee5c6c80392_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16219918-2f6f-4426-a1de-d1bf25292e0d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 81).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '7ad10c25c62f3b6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77625257-0eb6-4372-ad07-a95982c673c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 81).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ff17a1375e1a4fb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('502315d6-5a5f-4225-97cb-fe760752f42c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 81).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b90eb09c74f2ced3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7625ab39-db70-4fef-b3a4-e88a8af013eb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 81).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '46ef8227f624e394_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c57e376e-4f61-42c7-a0ca-d7dd7236c365', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 81).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b02f6c6dda65c218_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49cb8125-e7f4-42cb-893c-2c7986f6a02a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 81).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'dc6c5c12fdd2e1d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c652819-276a-4383-8e7a-098b0a11a321', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 81).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '83c202d04152c360_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e992a362-1d6d-481c-a944-83f460f1b6fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 81).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '1cb48d4d07a0091d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b68b82c-3a5a-47bf-b837-e20af8627376', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 81).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '9f433cca00972660_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42b4277e-694a-45e9-b538-805af138dd39', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 81).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'a2d8ef5293943999_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2de2f9ef-f584-4710-9241-91d36fa79178', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 81).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '88b7154416a2ebc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e63e3fc9-ce0b-4d37-a7f0-aa6ab35a282e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 81).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '63b637f8a15e668c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cdfa895-0da3-44fb-a9ee-6b5eb9d3850d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 81).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'f22d2ee23d013828_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b215cdf-ed86-4c7b-8dc6-9af3b3342b59', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.240.250.0/24 network (variant 81).', '[{"id": "A", "text": "ip access-list standard 10.108.59.0 0.51.232.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.108.59.0 255.34.122.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.108.59.0 0.51.232.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.108.59.0 0.51.232.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.51.232.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2ddf95ee127eaf1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1512e8bf-78a6-445c-8f79-c6d38bfc71c6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 81).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '8bf78d106f0a16d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('936009ed-268f-4dfc-8879-f16e770ec957', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 81).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '443ee0495f0ad8b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f360f52-0b99-47de-bd48-931fb3d17df5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 81).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '88d7a9a9cb542f98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5098a31f-e9f5-4920-b636-0f281ffc8c33', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 81).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'd2b8fe25d8dd44d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0708ba9a-de6d-4cd9-a013-a188ce0ebeec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 82).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'cd24e44c3f294590_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2e5fe5a-bfbd-4cca-8cac-b96050a874da', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 82).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '84845e69dfeb8b48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cd83126-ec56-43e4-8a39-f678c9ad2b41', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 82).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'e652a86cf4bf57c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('feb011f7-495d-4a5d-acd5-542a9e822ff8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 82).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'd4bd121d7a041267_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6eac620-5826-4d76-be22-b3d3f3d5c1c5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 82).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '34852b96cdd6cda3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e9f0fac-54e1-45ac-9d78-48c1de36a068', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 82).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '993b85b94d886793_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f646d33-cf5d-42f6-8c98-428d9e99ca18', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 82).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '285739c53e482b2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('280e49cb-c01b-417e-8a26-9c3c7a41cf74', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 82).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ee263c610a5a6e28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aef223a3-c233-4fae-8d4a-d5f8f662d4a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 82).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1dddfb5bbda8fbf4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0814b2d7-421a-4d57-bb0b-842215da780c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 82).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '3fd44d0209731004_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da7813a0-5ec6-4a16-bd99-34ee41674d57', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 82).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '37e9447cd605f1cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('625be02f-4f6a-424a-89e2-0753d7673c22', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 82).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'b89ea232c98be0fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d283f501-6f2f-4f77-bee8-9eb0fdaabe2a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 82).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1e058c277533d651_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('779e88e1-dd1e-4cc9-b2e2-c7a1fac88b79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 82).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd01ba4fe3e3b5865_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40a69af1-b014-4119-aa01-f72ae16eda21', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 82).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'b20fc9e489024244_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b4fe06d-14c6-42e7-8f9d-44195e5ab87b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.70.179.0/24 network (variant 82).', '[{"id": "A", "text": "ip access-list standard 10.124.173.0 0.178.20.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.124.173.0 0.178.20.255", "is_correct": true}, {"id": "C", "text": "access-list 100 permit ip 10.124.173.0 0.178.20.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.124.173.0 255.186.43.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.178.20.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c1fc111b7efb6b34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23c685ab-263d-43cb-b248-809dddcb932a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 82).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '85060a26e736868d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a3f297e-3776-4ccb-97b9-b1ff0227f244', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 82).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b2836fdcb870f301_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10ab756a-69eb-49d6-a0e1-331ddd6a3687', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 82).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c4ec848c16e147fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22b196e2-14e3-4392-b532-7bc75db8e4fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 82).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '5513e5db11be50d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('901cb9e2-23cf-412b-b9ce-8b562a33d586', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 83).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '82461ce141ea87f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a58641f-5f67-4406-b7d9-868202c8e526', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 83).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0b4f5a66406e2dee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1be7dc48-0dcb-4f34-ad39-1a066ee50dc4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 83).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '5e14e4f9f39de0dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2f19953-116f-4b79-9f21-b98614063de8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 83).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '9894b5d68a087604_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03c50c11-0b71-41b3-9bb0-b25dd2fa85fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 83).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c4fe1e75fa994edd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dbd80bc-631c-4763-ae6b-2a2b6216ceb3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 83).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ef4df483552e7a67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6dc28b9-c3e9-4d1f-973a-d342f7eb0d4e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 83).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'dc44203147ac5d1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbafe72b-a46a-44ca-aad2-411cae762166', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 83).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "desirable", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c8639a2bfe73ff0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3be27c00-36d0-425e-b6e8-a1fb6cf5ad44', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 83).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'a0bdf73e1cec4a67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7a65da7-2e20-4208-a956-f6de9a70779c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 83).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '4fa04f1144963849_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb339bae-3a0e-46da-8977-37ba1a09f189', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 83).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'a8270becf3b16083_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a961781a-6b3a-4fe1-8765-4ab779f73a39', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 83).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '6cd996cc747f0e89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8402727d-b8ea-42e5-88ef-0aeab3cb3d0b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 83).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c510fc793f2a6a7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f659364f-23c1-42a9-a90c-82405e570f37', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 83).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd6fc31d1a3563585_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3667976d-5519-490c-a12d-a6d73ddfcecd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 83).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '08e4abb452d21d29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ef87a22-293b-43dd-b457-ccec3ac7bdb0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.155.27.0/24 network (variant 83).', '[{"id": "A", "text": "access-list 100 permit ip 10.26.230.0 0.100.116.255 any", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.26.230.0 0.100.116.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.26.230.0 255.184.16.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.26.230.0 0.100.116.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.100.116.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f4a0bd16a1a06ff8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b014be19-6274-4f1c-a973-e022b8aa5fe4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 83).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '01d7cec62bf43caa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a2407b7-7ddf-4949-824c-68a21fc2d219', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 83).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c012e3f21a15ad35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5866e8f-8650-4586-9ba8-a3aaeb0e5f09', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 83).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'f42c15a5a74ef35c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d793870-99c9-41be-bf3e-d2fa7143c973', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 83).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '337ccc39dd0df13c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b20e65a2-2714-4441-8ce7-bbfbeccc19f6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 84).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '48b6895bd20df3b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6c80fa7-89b5-4788-923a-9138dc3fdcfc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 84).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '763ed946acb7255c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5770233c-d459-4ec6-94df-e03f1cd46d82', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 84).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '85b8182f532d434a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7947190-f8ed-47d2-a38f-951ec50a28b1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 84).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'd23a316ddfb83841_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f96d4e86-719a-45ad-84cc-14874cc6b72c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 84).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8f18e5b1e27e7c5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('086953bf-aa3f-40c3-8dec-ffa22bdaf489', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 84).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a467bb98f7bb96ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c41329da-c1d9-4185-ab31-17ef2ae7c32d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 84).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '15491c9ecb948d05_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7618e94e-566e-490c-8d2b-39506d819bf1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 84).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd633795a70e2b3e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('152f7004-d9c1-4b1e-999f-f75f222f5144', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 84).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '6f45efffbec2aba7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45bdc78f-2e36-4f3f-8730-e0478210ec71', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 84).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '7a161f3bfd3e2d57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65588cc7-2ce9-4f4d-becc-7c0e9c5843ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 84).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '911d0a40376c8c77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2a722d5-bc46-4efa-be23-718093078697', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 84).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'c0bde905fb0c634e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83bcd43a-7bc8-4d0b-8e11-a6fbabcbf61b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 84).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '46064d90395eb171_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5637ef27-f11c-4914-9117-9247b3a96608', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 84).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '13869c7c770c68c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3797a324-44b6-4fc1-b575-bd60e7eda645', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 84).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '610d3fc92463c1a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9305ed43-f572-40f6-8fea-4ebd8f1e7233', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.43.21.0/24 network (variant 84).', '[{"id": "A", "text": "access-list 100 permit ip 10.24.113.0 0.191.159.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.24.113.0 0.191.159.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.24.113.0 255.7.131.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.24.113.0 0.191.159.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.191.159.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c52a52b2ed6b19a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cca81ba-a38e-4dc0-a946-b78fa130044d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 84).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'd8edadcfe4cc5933_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5b66e20-2b33-4b5c-9a78-42b49d6dc0be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 84).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5a0b406ba94ab2d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28fa6561-2f6e-41cf-b7b5-879b1adafdee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 84).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c981239b177d65dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c29f1024-e82c-4931-8b12-795f1a511583', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 84).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '15eb30464030b0c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4425dd93-eb93-4298-afc9-b9ddb0f976a0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 85).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3215bdfe548c2f2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34dddb24-291c-4f2d-943d-ac39f10b9845', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 85).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9d23351755c13207_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4513f527-19c9-494c-9646-4b0a81671ff5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 85).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '2da20be19a8997b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a077493d-30ac-4c64-acf3-13b39a62a173', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 85).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Manages power over Ethernet", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'd91e252f0b8c85a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2b6619c-8a2f-4301-968e-94c70d62708a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 85).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '48fe748554e553c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8d4eafe-a94f-4bc2-847e-9416828ad511', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 85).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9e25631a14d5777d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33b258be-00b4-435d-894c-b2a2461d4d68', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 85).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fb5051c88d1aef6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6775165a-315c-4ac4-9527-cbe443171226', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 85).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3e272f7c6ccf7c9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b9ef7e2-e63e-4547-af1a-f44e997b909b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 85).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '7b741b02428b356c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2926359e-c6c9-46d7-8e84-5bac4183af97', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 85).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'b9142dc56e929a00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f122bed5-3b10-4441-bea4-c6ea1442dc07', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 85).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '036e88e46c5e5518_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67307d22-e600-4486-ac40-23a4b7716c02', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 85).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'aa3056c11a78d661_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80787d15-3ba2-4389-b237-a603ff5e8d75', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 85).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4db3c98996dfd4d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92866af2-dc15-4d2e-a5db-943dbdbbb02a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 85).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ed0950ed40843fd0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b3aca35-96fc-487f-85a7-3cbd3cfbfae8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 85).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '897b817c3b8c5f35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('983c7a59-3a59-41e4-8867-1f44a9cf37b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.35.123.0/24 network (variant 85).', '[{"id": "A", "text": "access-list 1 permit 10.129.155.0 255.237.101.0", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.129.155.0 0.62.34.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.129.155.0 0.62.34.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.129.155.0 0.62.34.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.62.34.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd71501418e7f7006_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a85858ca-d8f9-465e-b565-d50f463d9fa5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 85).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '0b2b41c761353019_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f423bc3-15e3-4efc-bae2-5cc822996a5b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 85).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '0f496b7660f67fa1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77151614-08fa-4756-a220-8f0a8d284cde', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 85).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'a45430e8bc0ba74d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed92513e-6a39-4f2c-99c2-7e283eef4e15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 85).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'c02c0bccf3bf0fb2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6e5a7c8-1278-4b31-89da-855111ce3b38', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 86).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '5bcf9cf83ac8919f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6621a63-c541-4a8e-b0cc-9f5850b32eed', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 86).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '2424974df557f400_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc5f22e8-326a-4c2b-a3d2-6911669aada2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 86).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '2e9a801c918ce9ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('532e699d-167f-4e3c-8f19-78221f282f3a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 86).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '63a17c793cadc4e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('468c2f2f-506c-43ba-a32e-393748820cc0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 86).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0bc116bc0f90f19b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a43a66f8-49b9-49bd-ab24-7d2fc682f9af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 86).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7b5c40a18ab46dec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('baafb81b-b19a-46bf-92fc-d5c2a11e8874', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 86).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '54f080a74afafdf5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62802861-f892-4fce-afbc-290b744646f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 86).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '366f3cded76df7f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30ff8025-3524-4608-8426-f3de010a5b91', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 86).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'c945115ae4d7007a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4978082-f0ae-4f4b-9cf4-1476167b03fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 86).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '25fe8efcee98645b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5730cba2-3a51-4cac-a77e-bb8fd4cc382c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 86).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '065c0dea57b1a32a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfb258eb-f000-43a5-87b7-332b17775f11', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 86).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'b39466811d7c92f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cff6f7e2-79c4-4883-9d09-ada334a6753a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 86).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8f4b0670a21747a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48dabbf0-1ac6-48c4-84de-36fc0b66b707', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 86).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6ff92ec9341c5f3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71064b14-6caf-4df7-92dc-ee80e9f9ec96', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 86).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '64d140955c5124bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ee019d2-d471-414d-a354-93e6a863e2c3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.93.217.0/24 network (variant 86).', '[{"id": "A", "text": "ip access-list standard 10.39.97.0 0.205.250.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.39.97.0 0.205.250.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.39.97.0 255.90.50.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.39.97.0 0.205.250.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.205.250.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a4a3c1d2fcbb24e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5200760a-0119-4e22-9616-5fa6e3c46598', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 86).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'cda22f29bf7637b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c0d36b6-b9ad-4a41-bb23-2c19bd88d18f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 86).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '49f5c6fa7908a529_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bf58e1c-9ce9-489c-bab6-d0c7b7dc7801', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 86).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'a9047bd821e8b904_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddbf8e58-099a-492c-84ed-f99e8746f640', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 86).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'f668e918260ca5b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('553a6167-1c96-441b-b6ee-c6efbc37891c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 87).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '89662abe80525931_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ce3a3a5-55fa-44a7-85bb-7caa08dec300', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 87).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b8c2c2114c90680d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9251419-ded7-42cc-97a9-be9ae5937e9f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 87).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '7f4df362e861d2e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0c248fe-4191-426d-a427-a40cf0a468d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 87).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'e9ccd7f6c0168666_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdf30a51-ca02-4268-8b9f-33fd2751b4f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 87).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'fdefdd52eb733a5a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36f7beaa-0437-49a1-9a6e-78f902fe55f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 87).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '540defce61a89afb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b663bf49-8572-4e73-ba3f-d84ac7fbe611', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 87).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '903fbd5c585d7d02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6fb3d62-da2f-46a0-8dfb-8493b836ac11', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 87).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '082319752dea65e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2637bd62-86cd-4ee1-b653-8f0bb48361d1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 87).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'b25c8aafb7f9f5bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('075a9b40-0dd8-4aef-bde0-cd41ec41cbac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 87).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'c20320abfbf9a83b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c35fc203-b940-4b6b-bf82-27c6bd32d1d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 87).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '2849ca9d5602d403_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('556522f5-becc-417f-91ba-dc1d9cc699a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 87).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'ad13c978b078a11b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24b248be-bc13-4858-8eac-8c0ae7a50e9e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 87).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'cce896ec99125081_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cea0cc6e-cae5-43f8-a313-87d82ebac333', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 87).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '655b22f5999e2d0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db141605-8ec4-447e-bb86-901d4a3448b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 87).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '472a7f877704d7dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('865e83e9-c4bb-4f09-bd5c-82cb028c6554', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.18.156.0/24 network (variant 87).', '[{"id": "A", "text": "ip access-list standard 10.228.244.0 0.174.29.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.228.244.0 255.86.197.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.228.244.0 0.174.29.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.228.244.0 0.174.29.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.174.29.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'cde2c51cd1fbba46_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7adf1d1d-31d4-4783-a707-66ce22a5d0f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 87).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9d9235c5bc501f66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d5eaf35-36be-42e0-8409-15d2cfb91ba0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 87).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7821405af015f0e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4c8e196-2c7e-4215-9c05-0c13b20ee11b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 87).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '6767d852efe13637_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e50b851-e32b-4157-b249-bbf886620105', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 87).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '4290c0f18961beb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c13be16-5ad6-45eb-90ec-f032b609f03f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 88).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd798f7c2c2fc16fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d23d723-5e5b-4b0e-a136-0a2369ee2912', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 88).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '742877ce0fa9001f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a41d6cf7-f30f-4a3a-b1e4-523baf680a76', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 88).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'f699dcc5b3d0becc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a5fb2e5-84c2-4647-b4d5-a9a2840e43ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 88).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '909f125963a55952_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('052e24e0-facd-428f-8e19-5c62ce2badc9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 88).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ca7f9df6df03354d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b7caed5-635b-4de8-8def-a2d952a19360', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 88).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '08c05a3462a21c3b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ea02f85-962c-4a60-93ee-7fab0e5f35cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 88).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd14749d340d8ebb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8154b8b-e765-4e2f-b21e-fcafdd4df188', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 88).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '528f43fc8532b159_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d752e3da-fa74-4df2-afaa-910f4784474b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 88).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'dc0643d8ae238df3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be139817-9742-4f51-83ce-8b409a903a24', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 88).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '97110e7b85817ad2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11a4e121-2444-430d-9d77-a6964c52a6e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 88).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '5849ad848d6faa27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcc01c31-a48d-42b4-a24a-5cb1333520be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 88).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '30a07bb3af0f6eb5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ebcf557-52ad-43e8-8709-8001de2d7897', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 88).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6ff449b71974cd3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04f5a409-4ef9-4425-b517-5260ba003199', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 88).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '8cf41057655be76f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cdc8a84-6917-4e63-a3d0-f8185361fdf1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 88).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '3b36a8fc8d0f5b42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e439b812-62ce-4f6a-bccb-37887b1ab4e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.180.185.0/24 network (variant 88).', '[{"id": "A", "text": "access-list 1 permit 10.101.98.0 255.86.65.0", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.101.98.0 0.4.32.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.101.98.0 0.4.32.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.101.98.0 0.4.32.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.4.32.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'ef4ad0fa7b6542d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87e9c76c-9564-4393-94dd-b9d8c3c3b1a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 88).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'c01d87d5c874c47c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06ab6fac-5a15-4121-b9c9-02584839e933', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 88).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'deffe42635767511_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fc3bada-00d5-4064-a40c-be222ca2ef37', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 88).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ed5f6492f985816e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e50eb1b0-403f-4717-bbef-36878baa4dbc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 88).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '764bfca70bb01711_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('402adf45-e3bf-421b-83dd-b87f1fbf9d68', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 89).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '6140faef0a1b9b81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2672d277-2055-482c-92b9-4d7a5a8fb083', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 89).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'c39bd883661a8476_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc474ef1-d98f-4aba-a4dc-e86f852422e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 89).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'b9232494125e9565_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fab92eda-652e-4a73-82f9-6f5cc6b65852', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 89).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'd527322a2056c0d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15ceb481-2c6c-4076-8ee1-a8091ae78688', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 89).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4d66578a7064b996_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('faf78b8a-ed6c-485c-9c70-18322f0a1dae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 89).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1deee54ddc24520e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c143d809-8e9e-4ec4-8caf-4db71c6dc23d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 89).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6fa6089f25d9e59b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba5fb894-ed42-4567-9507-249c5ad9d191', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 89).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5665c8963a9ebde5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a955939-b50f-4933-911f-7f9708e7e490', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 89).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '35e7823c7473bec1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db65364e-842a-448c-9eaa-921dff1948fc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 89).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'e3f16ac5f992deea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22734b45-2c6f-41f1-ae1e-10fce795f71e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 89).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '86a7d04784b07e38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d33b3fb-e72e-4628-b08f-97481d84a30d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 89).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '805971845e8bc004_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2ae80ce-167d-4bee-ad7a-3e757f4c4386', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 89).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '250ccf3160a05865_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c25e9ab5-f60f-44a3-9433-2e6927ecf49a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 89).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e57af55cafc5f3c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46c50d83-b0e9-4eb1-bb81-e64678359ec7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 89).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '1b829dce814dd964_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2661f231-a646-4f86-a6f1-e38e8d8b2710', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.136.254.0/24 network (variant 89).', '[{"id": "A", "text": "access-list 1 permit 10.236.129.0 0.93.24.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.236.129.0 0.93.24.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.236.129.0 255.230.61.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.236.129.0 0.93.24.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.93.24.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8b1243cce96a6f6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47e891ee-38bd-4644-80b1-20334191277d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 89).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '6afdf4fae26f7bc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01669d8b-8333-425c-9534-9a38de511abf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 89).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2541210e85bdb15d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ec01a1a-77da-440b-8a9f-cf141a714d9e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 89).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '1a1d09037d6a80e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41f29928-5de0-4194-a395-220dde7f2b35', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 89).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '78ade020ea9df277_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('338edff1-5b6f-49dc-9f67-448df9a4ba3e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 90).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8d0245658041e0a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2db2aabc-5a13-4666-b531-27ce1411351d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 90).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'f1b7d67c4fb624b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a82bce0b-88c1-4793-9e72-f0f54c4e6654', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 90).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '242ab22881431aeb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8310fc0f-4c06-4998-b8fb-a6e5c738cd17', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 90).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'f056085e7d1f35ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c731a04-2810-4907-a9db-e492007421a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 90).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5c5f2a689b474616_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a55785aa-0f73-4031-b1f5-d9098bb81f92', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 90).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b396a015420ee1aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c732128-9742-469c-9648-38657ee63b25', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 90).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a4689334b26ef0d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ead8c48-4897-4765-9f2e-a793d65e8e49', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 90).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9d5f3f83b086b9a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29ccad08-d063-4903-8e93-12d08280e6d2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 90).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '20ff92afed37f78f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e053118b-0454-45f7-9647-b754c8aa04fe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 90).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '96bb3204abb7eb2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbd71700-04b4-4c56-a8c7-e3a79ad44ee1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 90).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'c4805e873f9bad49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f55a801-1650-492f-893f-17b78d721f44', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 90).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '3bf55cb13b95334e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9204e5f-a151-4870-be2f-246ca22b1cc9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 90).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '463a6cea9d6b6e9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f092b8f5-cea0-4e87-96d9-a4878f3bc278', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 90).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '68846a6267e65340_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('421a5129-91ea-4e44-8d41-d1e910873bb2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 90).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '12537d9440e7a896_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('553cc85b-4390-4434-8df0-9edfb12d9595', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.12.122.0/24 network (variant 90).', '[{"id": "A", "text": "ip access-list standard 10.181.172.0 0.178.49.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.181.172.0 255.159.151.0", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.181.172.0 0.178.49.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.181.172.0 0.178.49.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.178.49.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'b495e2cb9345b087_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39fdbb95-b91f-468a-851a-82dc036a9c1f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 90).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'e0badfe51211a47c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('666725d2-4927-403d-8de8-4e91257ac064', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 90).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd6e3bf93361ac04c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a372493a-383f-4766-93fe-658b1f3a625d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 90).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '08f50bd84912efac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a9b3213-2d7d-43e6-8771-37740e0e954a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 90).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0e0a508e269df797_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('588eb123-6f40-4e76-a74f-6bb9b96a8a7c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 91).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '433e64665495669c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf2a9622-736c-440d-b876-9f49ae8f10d7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 91).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'bd81ef217cf8276b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6242260-2e90-42dd-9c66-3ef5c99c9cf5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 91).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '83e3c8762ec2336d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('727651b5-b4b2-41cd-8bcc-e054c4b50949', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 91).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '590125b9721f442b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f44f3ead-20c8-49b5-ae45-fa1b104ad5c6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 91).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0456484825205b6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29f8eca6-5e1f-4f9a-b221-9bf9657a6d74', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 91).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '17dc2f79a3ce2834_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fc1943c-1e2b-4894-a871-c08af45d6cb1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 91).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '5ed133d319267a8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f39479ca-ffbf-4919-b939-8a865e89f333', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 91).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e0bf1b65754880c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e347c0ca-dc8d-4a64-97e5-0207dc2c6efa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 91).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '86bed93d1ff6d1da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('162a0f54-4a86-44ac-a429-5a7efa339243', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 91).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'ea0748cdbab9919e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98932446-57d5-42d1-a296-b841b5e81749', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 91).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'd07729621d8519ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f7be044-7cd2-45f6-844f-0cfc48964c20', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 91).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'fd10b8a7b737edce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81c46ef3-c515-42df-b436-e960d2ea00c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 91).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd0a909df21bbc99e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85ad21de-6c8c-4a4f-88d7-697dbeef451e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 91).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '58f9b3a8c1e3c8bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be98d9b1-b137-4600-8ccf-96c7d1de6eb6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 91).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '5485b8ebe813ff47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae23ffc2-ab56-4f00-9cca-ffa083dfc834', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.232.10.0/24 network (variant 91).', '[{"id": "A", "text": "access-list 1 permit 10.120.205.0 0.25.49.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.120.205.0 0.25.49.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.120.205.0 0.25.49.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.120.205.0 255.20.72.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.25.49.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'fee2704106233012_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bd3cf69-e4e1-46ee-a6f8-14b9809c4c98', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 91).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '0220267bcacc317f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c00867dc-515d-487c-9d4b-bc5d861e8f2d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 91).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '7bac8ce449596af0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3485871c-dd47-4ad3-8f2b-2fca3d8800b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 91).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '9837971539bd6fb3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18cf8ec7-eb81-489a-9e17-38f6dd17aa14', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 91).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '9ad5c61e49be6d36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64cd1dc2-8414-400a-85ac-bea5a9f739cc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 92).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'ea9b0bd06ef8af22_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38d3367b-de60-48e0-97be-235e7a043dbe', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 92).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '214e8acf8eb0043b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a33bfd1-b39e-48e2-8bab-bd309bca0701', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 92).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '5c81a832ca1a2e75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c99806b-380e-46d8-bede-20ac005ae8d5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 92).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'faa30fc6db38cb4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c35d59b4-b9ed-417f-8c59-d569561a8b76', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 92).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c9d5c7df7af8fcd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcac5874-f831-4ae3-aef4-10178a874c8e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 92).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '8666535b50836e42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f437b86b-65da-4096-a72e-b83ef7fb1738', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 92).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a171e01117027aa8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8b99976-1be8-4f69-bee9-bbea38483231', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 92).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'eb1f66dd3a41b0cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ad3505b-4b5f-4e0d-a638-21a5e2589c8e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 92).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'cbdfa5314437d6c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('873e6063-67e2-461e-9e1d-4614e0e1495b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 92).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '5c18256355263bb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b222864b-c746-4d33-8b3c-a4ad303103c8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 92).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '6bca8885ef2d6d4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9db7d870-355a-492b-8429-5fb1fc306b07', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 92).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '1cfc1d9c084df7b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70eb0003-e5a5-4f51-8a9b-d9b428b1ed8a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 92).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1855c01e073c2b61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd49c593-a86d-440e-94da-78b2fc85419f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 92).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '299cab8d7c49407f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1efa29d2-4f74-4b65-8e10-a72154b9688d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 92).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '0db93352ef1da03a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d2b1dfb-bb18-43e3-a4b8-93fa0a9c6af6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.17.253.0/24 network (variant 92).', '[{"id": "A", "text": "access-list 100 permit ip 10.173.161.0 0.113.106.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.173.161.0 255.226.49.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.173.161.0 0.113.106.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.173.161.0 0.113.106.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.113.106.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'dcbbfaa2afa04a07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72de04b1-e783-44fd-b171-d0d5b9fccbb0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 92).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'b5992dee013ec1c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64245538-fdd0-4268-a13c-605eaeb08966', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 92).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '188a0b79aa55f465_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5e57564-0aea-463f-8c7a-4fc2f8685879', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 92).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'edc06b0a5c244ae3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e39d462e-d5a9-4f28-9b1d-cc0ba8c58d4d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 92).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '0774f8a2148655ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a6ee4e4-53b5-429d-8e83-8a0021943118', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 93).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'a5b94fff88794cb2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bebdf1c9-2447-4b9c-975a-e4b863bcf9b6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 93).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'aec0c615a5acad12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e5cad99-65cf-458f-871b-6beb49692251', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 93).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'aac455958572b708_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed1dc67c-7e50-4d74-a388-2cb01d91c4b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 93).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'f7d2659999368c31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d849d39-b57c-4427-ba16-dc54ef990f93', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 93).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2b7212a13d2d25a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('470208f7-58af-4216-993b-4c4847dd6672', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 93).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7d67f148992014a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3f997da-1208-4aee-a7d5-1d33d6b6a1c2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 93).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '31962802b99a5f4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23a01944-b4c0-4fd5-924f-61e469d7837a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 93).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '11fdc1e9059cea06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27215789-1ce5-4764-bf73-69fd5e3bb4db', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 93).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1d57694106894491_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46935ad4-1e30-410a-b8b4-3ec1c2bbc724', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 93).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '220009e61f847c6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae67f00b-291b-476f-83bf-a89baa1efc32', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 93).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'bebf84713a7119e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('540af535-954f-47a6-9bdb-e10bded7d2df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 93).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '8ede2708c870085d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d44cdd67-0f9f-4933-831d-9d9b5e318a49', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 93).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '7af39823e67b317d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('939b49c5-22c1-4583-8f9e-9e64f6f0c03b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 93).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6a43132a617ec94e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6177754-b13f-45f4-949e-420f75614dc7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 93).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '1f3cb8615f35b5ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6c32a37-1fc5-4bb9-b094-7e9269d926e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.27.190.0/24 network (variant 93).', '[{"id": "A", "text": "access-list 100 permit ip 10.122.65.0 0.41.70.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.122.65.0 0.41.70.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.122.65.0 255.252.250.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.122.65.0 0.41.70.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.41.70.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'af15fac6035b58ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50f8016b-4144-443a-8220-fe833c2bb6fa', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 93).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'c626c2ae89b89373_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f1f4e05-ea94-4c13-8e22-b6feb7a2c21e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 93).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '14a2678299771474_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ca036a3-c3da-4444-a4d3-d20f74eeb578', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 93).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '57389e7e31962659_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03065325-3413-4a62-bec3-9aff66bbda15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 93).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '25eb2acab9f7bd5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f19541f-b705-4699-b311-a545f88ffecf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 94).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4435fb995e83c560_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2012770f-322f-4bf1-8978-5f8bedf4f03f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 94).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3b6588669e352384_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e1941bd-f120-4c5f-8883-ba44a066b20c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 94).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'deacd2b9ff572e68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('115eb707-403e-4c7e-879f-d71c9d293be6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 94).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '2192f38407130f4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4bcee3f-91ee-42b5-a53f-2e24bdd30301', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 94).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '3abef9d94e158ff1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7f0659a-9a14-4f5c-8f0b-597796f4d8af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 94).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ef1f7ffe4b34af61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6153e75e-7098-44be-9c6c-521b3d58ec5c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 94).', '[{"id": "A", "text": "Disabled", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '186bd63546671d9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e6417d3-8b12-499b-b511-cbfbfb9d578f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 94).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '652e01f7ff20a104_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5a1a92c-df78-48db-af41-817b3a889f47', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 94).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'abdb67fb84c978f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a49f1f8c-12a9-4d10-88bd-05c8043fb86d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 94).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'b05d18d3e0ce6f9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9188d01-c0ae-4ce5-ac29-c20a0dcc66e8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 94).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '57c7c12b97b0500c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47d73806-258b-44d1-b7ac-2d2072a32fc0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 94).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'ba643f20b592ba59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c35f1e6-d964-415a-9825-f63369b3ce9c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 94).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9873c55ab3c3615b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed20dc94-2dd9-4009-ae35-4791ce9eb651', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 94).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'bc90cef233464e90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a042eb4-79a6-4bee-9b7f-8d1c07302297', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 94).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'f57e9c1575303d84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c513d12-65ca-4d5c-9f48-3281f1d3c4d1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.195.125.0/24 network (variant 94).', '[{"id": "A", "text": "ip access-list standard 10.161.54.0 0.84.254.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.161.54.0 0.84.254.255", "is_correct": true}, {"id": "C", "text": "access-list 100 permit ip 10.161.54.0 0.84.254.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.161.54.0 255.83.16.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.84.254.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9fe8ff54317586d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fca4e3be-0048-4d25-b72f-7e747eac9478', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 94).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '9fe199246e692c36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('360b3223-bd73-4fd5-b5c0-c7820fac80e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 94).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'afec3e60b01c0f08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51981858-eb43-41fe-8f84-456c4d631c87', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 94).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'c27e3181eeaae33d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8df185d3-f688-49ea-9f20-8328a8d4937b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 94).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '55357b97f4440663_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba0fb7ae-ad59-42d3-a844-51733220eba5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 95).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '483ae470e59cb26b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c742ef4-4fe2-4cf7-ae4b-15bceef7f28f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 95).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '483038db30caf4f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd67ee1b-c9d9-445d-81a0-b20dac7b75e1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 95).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '7459ed31fb98a763_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10ee733b-d4b5-4ff6-aeaa-9bc61b10cf88', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 95).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'c28eab1dc4b38c81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('005b551d-d6d3-47fb-ae66-3cf59ee1d8b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 95).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4c48b7e4f96494a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34a106dc-9495-4f06-837f-57527454a3c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 95).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c8dc54cf17c61749_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c95727d-dbe6-48d1-a17c-880636aeb9bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 95).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2b8eac30f6332b41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45839280-f95f-4368-8707-0f49575becb5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 95).', '[{"id": "A", "text": "auto", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6fff6e83053c2788_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae352d44-7860-404a-8621-60f67e08e325', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 95).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'b2303fcaad7f1d7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db088363-2ae2-4797-bc9f-cb512a824b27', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 95).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '73ba167d474a23b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71f45cc1-8b42-4df3-a888-c690c710bf8a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 95).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '245c11aeb23af3cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9af376a8-579f-4c6a-bbe5-6eff272603dd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 95).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '0be5fa1c20944f93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adb95e14-1353-4dc8-b6cf-f83c9bcc0287', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 95).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6a8638e7b92692d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('149a51b2-5094-470c-ab0e-21fd60f05d4c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 95).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3ab391709258a902_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da9515ca-64a2-4ee5-9a54-90b7cf0279b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 95).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '0ba6cd971ee2cdc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5c3fef6-510b-4cf2-893a-af33a1037523', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.56.158.0/24 network (variant 95).', '[{"id": "A", "text": "access-list 100 permit ip 10.84.76.0 0.104.100.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.84.76.0 255.158.74.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.84.76.0 0.104.100.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.84.76.0 0.104.100.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.104.100.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'cd09d52934ab2706_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('917588e3-3779-4090-b8f6-af107acf841b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 95).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '93d389a84a5bf925_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e63ae85d-2d38-4c24-b35d-533da1660d49', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 95).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '52c49b576ea8621c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32c99598-8c2f-4551-a299-a81929ae829e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 95).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'f978a1c9239ba366_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54fb51c5-0dc8-47cd-9cc6-8385ccd2174d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 95).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '5debd291582892ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82869e89-0232-4dbb-a2b9-05a84eea8737', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 96).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd76f458e6320425c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3bfc9ec-23bf-474f-877f-1aeb5d0795b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 96).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9744e7f887db0f15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b18a1d7-23f9-4f6e-a7ea-9c6799633f86', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 96).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '297d495227b3c7bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd2013f9-ca5d-4d08-a25b-ef5179984584', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 96).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ed12b4a22ed76433_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5015105-6865-4e69-9258-8c74bab0d498', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 96).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2090b8e768029f12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6609927-06fe-4c1e-bc2c-0e14c20b626e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 96).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9d58c8c1475916ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10a7ffee-c5dc-4951-9d51-fef8201887ff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 96).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Forwarding", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9db406fdcbd8d824_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31c9665d-9160-4493-b71b-73f2f020c5e0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 96).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'bd2340667542eaf6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75069f3d-2b35-426b-9626-106b3c135f04', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 96).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'dc2e35b06973fc54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c37f4b0a-3658-4168-aee1-a15dde74b5cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 96).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '775a33958a1cfb5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6586be34-9a64-4fd6-8cf4-257021b71ba3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 96).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '817397734c8535d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dda98627-b746-4e80-ad5e-35152e7497a6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 96).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '38c77b9322b1bc02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a484dbc-39f1-42e5-b415-de53fc898248', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 96).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9cb33ce3b91f3453_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03f010d4-d57e-449d-b2a3-2c3971aa06df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 96).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '86044c4d6249a524_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c4a1158-1e87-48db-8775-0b944d7b5707', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 96).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e755d9fcbe7d5daf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27c2ba89-067f-415b-87c8-ce769b86dd96', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.186.9.0/24 network (variant 96).', '[{"id": "A", "text": "ip access-list standard 10.166.153.0 0.162.39.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.166.153.0 0.162.39.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.166.153.0 255.210.209.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.166.153.0 0.162.39.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.162.39.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'd66df21f973b1c59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09255110-7cde-4333-92be-6c0bd80ab55a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 96).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '423bb09c4aa33850_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('408b65a9-c108-4e2c-8e6e-d68be3562ac6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 96).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '9abdf3487c2ac210_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f045091c-3e48-43f2-a20c-e3b94479c914', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 96).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '36538d2ef957816b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45482ed6-3724-43a2-956d-cc580f863f5b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 96).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '6c89b9fd0e07123f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf581b77-29f4-499a-80a5-46f7b1686ba7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 97).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9fc02cad0b9d1c39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb62d199-193c-4e77-ae68-91c786e8b3ec', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 97).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fc00::/7", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0b8e82fed1e8fec1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a090bd5f-628a-4060-94d8-98b5f4002a11', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 97).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '377c6d00e83dccb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc709c24-0992-4cf9-8f51-c083853dad0c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 97).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '11ed14fc4cf94599_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9fd8d08-c6c5-40b8-a17d-d2d01cd17c1e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 97).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports are faster than trunk ports", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e96c69cba70363aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('832c9e41-bfba-4db1-b8c1-2564d528c368', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 97).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f0307a54f864abc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bb0d9e1-d8ef-4c30-97ef-f64e427b743d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 97).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ccdccdb837683e91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c90a1fb0-5e2a-438a-b746-758b5661415d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 97).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd5b2f1a53540edd6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('386a8ae3-9d1b-432e-bd01-4235e30c608f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 97).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1de16724ececdaa0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77834022-f53b-4eb5-ada9-734e5fc6c4c4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 97).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '81712200e4475fc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30526628-53e6-44a4-ae4c-675dc0f4a0d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 97).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'b3b76055ecc4ad09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3a2d01e-fd67-4f80-97f3-bcf0d82f8168', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 97).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'ccf5cf50330acae7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a968e766-de07-4be2-b27d-4bcdcdea4a3f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 97).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '99aeac64b7aaca84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe589ea6-6928-4734-8572-87ad7200cb76', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 97).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '9431c139606c1883_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3051f732-9ec9-4f2c-bc56-bda2a7b2cb98', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 97).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'b0563b219f966a80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42aee48a-8509-4e8b-abbd-461a1db389d4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.154.1.0/24 network (variant 97).', '[{"id": "A", "text": "access-list 1 permit 10.93.213.0 0.240.229.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.93.213.0 0.240.229.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.93.213.0 255.189.125.0", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.93.213.0 0.240.229.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.240.229.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '8aa3544ef138df78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bb9cc68-ec1d-45dc-90f4-8d88df11f099', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 97).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'ddf82052f594b1a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7c7a481-5a3d-401c-a190-ec3789af7549', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 97).', '[{"id": "A", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c9ff37a3aa43e3e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8d54ad1-58b0-4e8b-b7bf-597098cc283b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 97).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ab6a5a61394833d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b6f3771-fe61-46c5-bb04-fde6c1654391', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 97).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'cf96e20a29116be6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c138ecfb-aeb9-4d37-8a1e-9c5bfd51364e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 98).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'e1d4f2f81b355672_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61632d79-852e-48ed-ba00-a038fdaeb59c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 98).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4b673913281a53a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69632c7b-c029-4702-b906-7add6f6d5c79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 98).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a0db91336b621a98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb08dc6d-f967-4461-b110-60a501fbf78d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 98).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'b44c03fca3a1f7ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('811dac9e-056b-4337-afaa-20a8dbdba341', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 98).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ef637480933979d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17c8c52a-ee61-4c78-9e61-30c5fc60ec17', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 98).', '[{"id": "A", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e3a7f2781e0e1047_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63708bfd-5c1a-4caf-b972-798d899232ce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 98).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2646e0235060389d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cca08ea-bd92-4596-8954-07ca470c5c96', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 98).', '[{"id": "A", "text": "on", "is_correct": false}, {"id": "B", "text": "active", "is_correct": true}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a11087468bb0804f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d02cee0e-5b11-482e-8c92-bf05fc4736a7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 98).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '1edd27cfe339b004_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bcbff0c-c6cc-4e74-b01d-f3332cebba46', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 98).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '0cb7f482ff0cdd8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1975a5b9-061c-4cd6-a1d9-ac7822cfc711', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 98).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f5c32eab8173ec1d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('034a3a0b-6416-4044-8adc-11a4b0f9e8b5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 98).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '1965d486f98c85d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21b409f5-4441-42e2-86c9-cd59796c9b16', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 98).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '2d1c6fe30d6d4406_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1eb92ba8-5a2a-469e-8ea2-f154c231654d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 98).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd10cf6aa3b1620ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('216b9157-fcba-4ff3-b2fc-9a19a257b17c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 98).', '[{"id": "A", "text": "Broadcast mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c54891a515f6d5ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fcd7187-d1e9-4549-99c2-3deef46c9224', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.216.222.0/24 network (variant 98).', '[{"id": "A", "text": "access-list 1 permit 10.142.110.0 0.152.188.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.142.110.0 0.152.188.255 any", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.142.110.0 0.152.188.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.142.110.0 255.29.226.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.152.188.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5c4705b1c3d3ec35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07f68ba5-5d43-4c1d-977e-990ab3036d40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 98).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '230bccdd604f251c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c50cec8-dce0-4137-937a-3288153964f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 98).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '53b0d63a14f7cbe6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e89675cb-eab8-41b7-867c-fdce8a5c8bd1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 98).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'b0b0ef641e496d68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5461d713-e303-443c-98d2-918780b6d5ad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 98).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'ed72dee2f9c0cc74_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ea3f648-2f1a-471c-8527-f292444ad619', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 99).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'd3d83b8e74c88fbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63ddc1fe-4400-4f61-9f6c-91d588bd0307', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 99).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3a5d453745b4c39e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0cc4c6c-7a2c-40b8-a61d-7ca9177d34eb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 99).', '[{"id": "A", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'baa1a34e145fb4e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95977df3-55dd-4c25-8f19-bc55a04922d9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 99).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'b5c1a8cb139dcb36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d025c0a9-d41f-4a58-a853-f7c14e800ff3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 99).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6ff0858100da0842_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bc534b3-6af9-4c5d-8307-c8e3fffd115a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 99).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'b1349d3e40a33f51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42a75254-1fbd-4dca-baab-82f2a0d97a2b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 99).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'afb00e8841fb9123_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa719e78-ad4f-4308-b6ee-4e0dbc9c3818', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 99).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "active", "is_correct": true}, {"id": "D", "text": "on", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9c1e855bfc95dcf7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01873ce2-17a0-419e-90c4-57c3dbe5b4b5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 99).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'd1cfcf97d6e3208e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b14c314-d328-451a-b7ec-933c9b74a7a0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 99).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '7669ac67ea3eecb2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('937f766c-06d3-4d9f-abbe-5bb40da7e59d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 99).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '8850fd7762840acd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9f4facd-f5ec-49e1-b82f-8b434fffede9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 99).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '5c6c145b8d8864d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1deaa4f9-f51f-4621-9108-d9dfb2be46f9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 99).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '232b4527bd7a6b95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9b5ef70-cd03-4786-8e12-36c490b6ecc8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 99).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '68a718c7a5f45953_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e10207c5-c58f-4ba7-9959-2cf69e32f89a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 99).', '[{"id": "A", "text": "Client/Server mode", "is_correct": true}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '19906d5d232edd36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e03ceb2-c53b-4edd-88d3-e61b61c5ea02', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.178.43.0/24 network (variant 99).', '[{"id": "A", "text": "ip access-list standard 10.200.74.0 0.219.223.255 permit", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.200.74.0 255.112.159.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.200.74.0 0.219.223.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.200.74.0 0.219.223.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.219.223.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '73c5a54e95edc8f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8dceb5ac-d3a8-4822-8224-e35e2edc3fdf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 99).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '661038f5ac5a57d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc8f1461-24a2-402c-9fbf-a2ff6ed51788', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 99).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '35594da4a231a58f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dab79db4-fdc0-43f7-8c81-b7097711487c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 99).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "TFTP", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '0ec921de077dc483_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('469a7c27-63f6-4a5c-8787-fe620f4fe29d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 99).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '902dfa2484fa10db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c93710f5-ae83-4efa-be3d-830336a67ebc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 100).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '6a7c26392eda77f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0aa62cd4-fa78-4141-82df-ce5f3830ca64', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 100).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "2001::/16", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '4914b42c4708f08a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('061053c7-fcc4-4b7a-950f-3c81770ed83f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 100).', '[{"id": "A", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "B", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '5188abe05375cd31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ea0ebf5-9c4a-40e6-9551-5d87fcf802b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 100).', '[{"id": "A", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to devices", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '46368c8a1d2360db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d42ba0ac-3873-4af9-a16d-ba2b602291a0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 100).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '881d445941495501_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf82e135-6656-4af4-8c52-68a5aed09ce7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 100).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a5e23c15714c6d57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c387c94-1276-42b3-a0c9-c36ae78894b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 100).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f822cdc9baa25a01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d14d9f2f-8030-4c46-84b7-fc6fb40ae04b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 100).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2b664569f35d17a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac1fdf3a-fb28-464f-95de-9d38aacb7209', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 100).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '606b4a4362476e91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e3c6b0e-2110-4bbd-80e7-4cf496655369', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 100).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'e2770895c5498cfd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0576e444-8ed1-485f-9fb9-eb81ab9f7af9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 100).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f54fe02bfe9fe16a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8358cd84-a3b9-49cb-bcac-2d142ac7a7d6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 100).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'b2bcee4fc5fb7f14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51b4d842-2ccd-4744-8d94-7782155632cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 100).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd6739a94875c80db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36a6db09-5ef1-4fd4-afca-522e83e5fc84', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 100).', '[{"id": "A", "text": "NAT overload", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'e7e1f82db9c0b498_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b70a67f-1528-4fcf-9861-c05ff4097d01', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 100).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '27ae1cbb2d1db2b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('323454ad-e610-46a7-a2c7-817a26055f31', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.173.185.0/24 network (variant 100).', '[{"id": "A", "text": "access-list 1 permit 10.48.30.0 255.86.218.0", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.48.30.0 0.121.130.255", "is_correct": true}, {"id": "C", "text": "ip access-list standard 10.48.30.0 0.121.130.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 100 permit ip 10.48.30.0 0.121.130.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.121.130.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '02d48c377da13d69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('205a449e-37e9-47a5-a4dd-6f145b238975', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 100).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f599a0a44831bfe2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf3d1663-87ec-4804-9da4-b4f163eb46b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 100).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '58d02a324d9e14cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2df4aecb-4563-4fdc-b5db-f6cbf94e05c0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 100).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '2d03a625d24fcf57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9952b0d1-ecb7-4d72-b92a-c0fa468c3532', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 100).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "PDF (Portable Document Format)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '3cc8a29f3de606b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01f404bb-a9e5-4160-9290-70a8071f22f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 101).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "TCP", "is_correct": true}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '8e5b7c80ce730329_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ed494f1-6f69-44f9-8542-08f4d60c7dd0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 101).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '57a781ee24a2a7ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af750432-ec24-465f-a214-2fe1240f3d6e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 101).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '7a1a1a94df072a44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba901a75-e1f3-4e78-addc-652400c1e049', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 101).', '[{"id": "A", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "B", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'c10004f751849a70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2642564-bab0-447b-922a-776aff5f9a1b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 101).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '65828a468804e28b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb1d3a0d-bcc0-4393-94fe-900ef3b0354d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 101).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries untagged traffic on the trunk link", "is_correct": true}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '68ee28d75f32adad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c289130e-6e98-44d5-bbb7-251c7d96d9a5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 101).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Disabled", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9e52a5eee7e6bbe3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7c83744-4746-4ebd-aeab-7aba9fd967bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 101).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'd92602ad6f296a26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c905c820-1cbf-4a47-831b-d931996b45b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 101).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '16a12ee8e49e6c60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2b2cff2-8191-42dd-8342-20471d206bb5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 101).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '326d270cb99354a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef77326d-d276-4661-ba15-268c37f085b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 101).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'f358ceba8015df41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a2f9697-3255-4bcf-92b7-ff2e675e39cf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 101).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '56d8ed43b2db9e8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02d9c320-0953-4915-aa62-8e9bcf34d2e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 101).', '[{"id": "A", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "B", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "C", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "D", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'db012b831d07e726_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4645012e-6539-409f-8421-cee26ce7746b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 101).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'fae2b5b15037970d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97e66ae5-fab6-47f9-8b1f-bcf470df853d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 101).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'ba720d21ac646dd9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c024ef6-719b-42f2-85f2-786b6ea29496', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.109.103.0/24 network (variant 101).', '[{"id": "A", "text": "access-list 1 permit 10.121.72.0 255.9.95.0", "is_correct": false}, {"id": "B", "text": "access-list 100 permit ip 10.121.72.0 0.26.47.255 any", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.121.72.0 0.26.47.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.121.72.0 0.26.47.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.26.47.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'bdd827847cc08f28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b2adc3e-3e63-4fd1-9bfb-965d0a7adfb3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 101).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '89f3b5e82ee6c24e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('031ab614-9555-482c-a35d-71111699a815', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 101).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '24461e9434354d0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46f39c8d-00d3-4508-92a6-b1038f540f5d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 101).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '3f69cd32d706f370_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67ff865c-37f7-444d-a68e-cfd927fbcf46', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 101).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '48903c6edb479bd4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcae4118-31e5-41c9-ab9e-b0afcd51c2c0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 102).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '09a90747ba9016b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83453b3e-b949-482c-a6e2-50e5bcabfd27', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 102).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'fe8d85477735b7ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92e5d1c5-a7a4-4270-b1af-1f5ea7abc5df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 102).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'f67010a89cc8835c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c672ac3b-9663-484a-a801-85544a2b2f10', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 102).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'ac90249f75ba1a6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e6f74b3-946e-496f-879b-9f9a8023134a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 102).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '03a92b1122d51c78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cc16a56-bd01-4bfd-8c5f-b747a8694450', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 102).', '[{"id": "A", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '6a3009934d90945c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dd2bd6d-4706-4132-be8a-1f812e8ca759', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 102).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Listening", "is_correct": true}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9528bce3124f3d63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('720dcb63-c148-49c5-a139-0f168741bb40', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 102).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ac3bdfc91bd866e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b675f10-a7e4-47a2-8546-c932602dbe1f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 102).', '[{"id": "A", "text": "The router that boots first", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'cc7d6836862886bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('416651dc-a3de-4eb7-bc40-601dbdf4c245', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 102).', '[{"id": "A", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '29c9d510bba07609_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19258c33-100b-4517-a0e5-a9ddb6125bd4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 102).', '[{"id": "A", "text": "ARP", "is_correct": false}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '4b67572f92394814_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0a683f9-42cf-4214-9936-72528f383140', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 102).', '[{"id": "A", "text": "IS-IS", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '9f97fcdf70ee8e25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67dfc49f-7be7-44dd-b78d-3244b263ef68', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 102).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'c19d2cb2a16930c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('060c95e8-18cb-4e7e-ba9f-9b4c9d980e09', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 102).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "D", "text": "Dynamic NAT", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f57c4ea43017b095_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00c30e91-5cb0-48ae-bb46-686bf1656283', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 102).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Symmetric active mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '4b884064a18f6308_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3254946f-bfdc-4c4f-9f05-fbfd56620394', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.65.254.0/24 network (variant 102).', '[{"id": "A", "text": "access-list 100 permit ip 10.109.139.0 0.80.40.255 any", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.109.139.0 0.80.40.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.109.139.0 255.32.1.0", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.109.139.0 0.80.40.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.80.40.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '24ef2a40ece97361_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f238781d-76d1-414a-a595-feed437c3200', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 102).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'cae2e98992ba8e3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08129fb1-0c62-4498-b742-3a963a1ce61f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 102).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '507dbfcb7886afdd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d14a578a-c455-495b-96d6-922eb190da1a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 102).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '9bcd4b2392857056_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01ba3c7c-32d2-44c7-a480-540206fc2e56', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 102).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '8cee94ad7fdd7b72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b0a0ae2-f65b-4cbf-b2c2-86085cf1c2bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 103).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "ICMP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '47400e00e76bcf3b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fd632de-8055-4584-bd79-5c6211488392', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 103).', '[{"id": "A", "text": "2001::/16", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "ff00::/8", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '5b114587eb8962ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d599df77-3488-47fe-8695-26814974bcc6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 103).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '244aca9f69042849_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87d085d7-37f3-4bc1-af7b-cc0645cfd9c1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 103).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '15768fc4ef9e51c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa72ccdc-20cf-4c27-b946-ead39b4aab17', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 103).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'f63a585793156e5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47bb8f87-a5fe-4cb7-9174-e4ab0e9dbce6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 103).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Carries voice VLAN traffic", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '2533e1c1735b6093_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1ababdc-da24-49a4-a9f1-9ff1217afa39', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 103).', '[{"id": "A", "text": "Down", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '24ce93b1d807e921_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a24eb36c-656f-4318-a465-06ca5558dcdc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 103).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "desirable", "is_correct": false}, {"id": "D", "text": "auto", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4cf64258ef303237_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a67fb15-7d4d-452e-bd65-cfbfe7172285', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 103).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "C", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "D", "text": "The router that boots first", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '50a718abf9d3fd42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6650e24-856d-4e7c-a4f8-4ea42c8ea8f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 103).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '4e0d5f3ccef78142_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56e2fa8a-ccdf-4246-ab05-a631f0dd9033', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 103).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "DHCPv6", "is_correct": false}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '9a6cb6968c336d8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0252b464-431b-4e47-9171-f98f045e8e9e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 103).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '287fd8c45f930f9a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e9f6d5e-2a6c-44cb-a2ad-dccbd61bb3a8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 103).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'ec2da56c4b0e775c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e32ea3c3-be8a-42be-9f6b-9ebde2e678d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 103).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "Static NAT", "is_correct": true}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '0a3da7d52a7fe212_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('355433b3-77e6-4697-ba7d-ad40b85ce04f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 103).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Multicast mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'de529f025ec03e32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('246ab6e7-997d-49b3-9bdf-ff3719bdb2df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.177.83.0/24 network (variant 103).', '[{"id": "A", "text": "access-list 1 permit 10.167.17.0 0.47.35.255", "is_correct": true}, {"id": "B", "text": "ip access-list standard 10.167.17.0 0.47.35.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 100 permit ip 10.167.17.0 0.47.35.255 any", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.167.17.0 255.207.21.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.47.35.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '38decc0940d7796d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee661f3c-f668-4ba8-89ac-80f72bda7948', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 103).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'af28ebad5972cd0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b66d952b-6e8e-449a-a201-1890f7a24eb7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 103).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '29d4a0b0573b989e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc19bdce-6004-4a31-be64-27ed9d5afad6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 103).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "SNMPv3", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '81bbfa6a25ab7b59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17a48885-70bf-46bb-a0f7-24c747a76909', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 103).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "D", "text": "DOCX (Microsoft Word)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '339e0fba6e56ff46_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0829552a-8c67-4248-b34e-42c7804be6a3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 104).', '[{"id": "A", "text": "UDP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "IP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '9c25fe3ef3acab7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e098a78f-4d56-4b69-8fad-72e526830db0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 104).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fc00::/7", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0632184c2c71f1ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da7cf2b5-c281-470f-aad8-4e2ca9cf61c9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 104).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Resolves hostnames to IP addresses", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a60c759b50093a9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2fe9eec-bd9b-42a5-af74-8a10bc52b93f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 104).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'a93168de293b4769_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb99ef6b-c474-45ba-be99-481022eda047', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 104).', '[{"id": "A", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1a0bb70c6afd0d2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5aa3e33d-0394-49d9-a080-2746ae18bc9f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 104).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'dfa818df1fe398c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e6764ca-2f50-48b7-a718-cbf00c0a6ecc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 104).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Disabled", "is_correct": false}, {"id": "C", "text": "Down", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '861b166f2ad71fc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0918b9dd-b983-4c1a-a241-fd34904a842b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 104).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a6d27c43ab56c6cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90a645fe-472d-4c71-93ee-98b20cc80fc6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 104).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'ea49c91fd765d728_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b367d634-0e63-49e6-a017-594e27e88fc9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 104).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route that changes dynamically", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '8ef1020670a6a115_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25008c5e-fe13-4c50-84db-c7f1b6e66288', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 104).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ICMPv6 only", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '40d63c71ecce6337_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55f8e2c6-695b-4b8d-a6ee-b95a49109dce', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 104).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "OSPF", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'f534c2d4f81d5ee6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('087a2566-1474-4bab-a6e0-9c9ce4442fa8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 104).', '[{"id": "A", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "B", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "C", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "D", "text": "Provides DHCP services when the server is offline", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '84f828ecc7e0be43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fefb0528-12bb-4b51-a223-81f5e25b32ea', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 104).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '6209a730c16bce88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bcf15da-c6e2-4efc-8c30-fdc39d4ce869', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 104).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Symmetric active mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'efce7a29dba3717c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76a04023-c41c-4e75-a50a-63df4dd9af81', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.63.188.0/24 network (variant 104).', '[{"id": "A", "text": "access-list 100 permit ip 10.115.179.0 0.193.80.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.115.179.0 0.193.80.255", "is_correct": true}, {"id": "C", "text": "access-list 1 permit 10.115.179.0 255.106.242.0", "is_correct": false}, {"id": "D", "text": "ip access-list standard 10.115.179.0 0.193.80.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.193.80.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '2d2b34471a95c17d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8213dee-0d79-48eb-92f8-cc9a0f6d30f5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 104).', '[{"id": "A", "text": "HTTP", "is_correct": false}, {"id": "B", "text": "SNMP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '062f017de4f157f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79a41f98-9376-4bed-8aa2-2653b5c62e4e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 104).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '04c529a8ca236789_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a543f6a-74c9-46d7-bf76-0bdf2bb086b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 104).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '864b30efde36316e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20be0c83-59cc-4ca1-91f5-6645d2ebf87a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 104).', '[{"id": "A", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '92bc54ca07b5ec98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd9cefd0-2e69-46e5-aade-18411b80b3cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 105).', '[{"id": "A", "text": "TCP", "is_correct": true}, {"id": "B", "text": "IP", "is_correct": false}, {"id": "C", "text": "UDP", "is_correct": false}, {"id": "D", "text": "ICMP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'b0a83c0abfe14c55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ade823c2-b512-4a07-997e-b2066a5473bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 105).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "fe80::/10", "is_correct": true}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '3a05e240b2c90fd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b8a5f93-5c91-472b-ab50-10cade1d453f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 105).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "D", "text": "Provides DHCP services to hosts", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '6bba742e3fa80ad4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efdc90e8-bb3f-4833-9b41-a5f781c6e465', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 105).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'a96aa9c7a9122a69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('685fd470-905d-4e79-9c30-ba853bb24938', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 105).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "D", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '9179a797353ad4c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fc84179-c91b-4a1b-abd3-c1df7eeb62a0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 105).', '[{"id": "A", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "B", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "C", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '1075af6b2f67296d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f60fe97e-3451-43f2-8507-0129d43f2b83', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 105).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Forwarding", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '582c17ebae73e44d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57e397ad-15be-4253-be4f-d20b02ad9ae0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 105).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '701d988ccace5120_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6a02503-8748-4fa6-9e4c-b18b26a06097', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 105).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router with the lowest priority", "is_correct": false}, {"id": "C", "text": "The router that boots first", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, 'faee38377a613717_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3473331c-e7a1-45fb-a43c-30dd40c4793f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 105).', '[{"id": "A", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "B", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "C", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "D", "text": "A route that uses a floating IP address", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'b8e4a8c45f613484_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63dbbe54-e178-481a-b26e-9e5165ef9b79', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 105).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'de9aa415eb5a2d22_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6684dd21-2ef9-4b62-9359-cf65d1a475bd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 105).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "IS-IS", "is_correct": false}, {"id": "D", "text": "RIP", "is_correct": true}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '48f6377c12b0345d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95d41696-330c-4e8d-a162-475892c70e99', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 105).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'd8edb1fb83c0fea8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a030ba66-d0c3-42af-a18f-df69cf4112e7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 105).', '[{"id": "A", "text": "PAT (Port Address Translation)", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "Dynamic NAT", "is_correct": false}, {"id": "D", "text": "NAT overload", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '36f81b88cc04c99e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1695bc39-894d-4ccb-9f87-369a2a0d0972', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 105).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Multicast mode", "is_correct": false}, {"id": "C", "text": "Broadcast mode", "is_correct": false}, {"id": "D", "text": "Client/Server mode", "is_correct": true}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'c4ae13968eafaede_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3896c878-e053-40bf-bcde-a37ca4aadf3c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.198.122.0/24 network (variant 105).', '[{"id": "A", "text": "access-list 1 permit 10.136.132.0 0.153.35.255", "is_correct": true}, {"id": "B", "text": "access-list 100 permit ip 10.136.132.0 0.153.35.255 any", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.136.132.0 0.153.35.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.136.132.0 255.169.43.0", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.153.35.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '991b6ecf5784b2a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f21a489-8d0e-4350-856f-2781537005ab', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 105).', '[{"id": "A", "text": "SSH", "is_correct": true}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SNMP", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'f090815b9d5cbe21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('428931b3-ee27-4674-a94c-3eb49d82976d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 105).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'f945911b11079795_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dff7465-ab3a-4010-b8c7-d87c73145515', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 105).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "SNMPv3", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '9c5bdac12799fad6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e06d259-bce7-4621-891b-8a9120d6a835', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 105).', '[{"id": "A", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "B", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "C", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '85fb75ed504bdc34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e639003f-4368-4b12-8a59-7e9a7007211e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 106).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '0c2fa66f2cb6f763_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('581d42b4-14ea-4cbc-b9bd-3d81da9153d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 106).', '[{"id": "A", "text": "fc00::/7", "is_correct": false}, {"id": "B", "text": "ff00::/8", "is_correct": false}, {"id": "C", "text": "2001::/16", "is_correct": false}, {"id": "D", "text": "fe80::/10", "is_correct": true}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, 'bba20717550219bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec668f68-6393-4b00-9d60-3d2eaf35872e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 106).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, 'a7c015eb945846f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4237fc6c-a4c6-49cc-9db7-2359ed1f16b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 106).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Provides encryption on the wire", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "D", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '2918934f612d45f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2dda229-689c-43e5-86a9-282b8ce210f1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 106).', '[{"id": "A", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}, {"id": "B", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "C", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "D", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '91f1549bf3f9c752_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bec79eab-4353-45bf-884d-76806cc6bdc2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 106).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "C", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'c4af425d2d602382_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('371b21d4-f4ad-44e3-a77e-45dd07c2ff95', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 106).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Listening", "is_correct": true}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Down", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a3da7c0dc8de3139_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0632518f-159f-4768-837d-0c447ddabedd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 106).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '4745d163e3f326e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9180ffa0-49eb-4071-8a4e-de7c2016c520', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 106).', '[{"id": "A", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the lowest priority", "is_correct": false}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '36e6f6db24eede00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd6090f2-8cb5-432f-bb2b-90aa7557e468', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 106).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'e893fe0e9a1476a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24c1a858-ff4b-4cac-9aa7-1bcfe702adae', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 106).', '[{"id": "A", "text": "DHCPv6", "is_correct": false}, {"id": "B", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "C", "text": "ARP", "is_correct": false}, {"id": "D", "text": "ICMPv6 only", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '93e9839da889023a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a799fd2-f35f-4919-a957-9050bf189cdc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 106).', '[{"id": "A", "text": "BGP", "is_correct": false}, {"id": "B", "text": "RIP", "is_correct": true}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'fcb2fb04975ec800_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1aad9fee-b799-4526-9042-f57a5ecdbae5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 106).', '[{"id": "A", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "B", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '3635dddc717da55d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5570392e-e354-451b-bf2a-9ecd2c053c39', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 106).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "Static NAT", "is_correct": true}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, 'f7b7974e3dfac727_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97c0d8db-3ebf-4f0a-a981-dca1074f3fa6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 106).', '[{"id": "A", "text": "Symmetric active mode", "is_correct": false}, {"id": "B", "text": "Broadcast mode", "is_correct": false}, {"id": "C", "text": "Client/Server mode", "is_correct": true}, {"id": "D", "text": "Multicast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, 'e5d02dc386f0244e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a0894bc-1b71-4a3e-996c-90694f9504b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.97.6.0/24 network (variant 106).', '[{"id": "A", "text": "access-list 100 permit ip 10.239.62.0 0.250.23.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.239.62.0 255.214.50.0", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.239.62.0 0.250.23.255", "is_correct": true}, {"id": "D", "text": "ip access-list standard 10.239.62.0 0.250.23.255 permit", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.250.23.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '5719180e142ee88e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1edeed6-dd39-483a-92d1-77c9c4668e15', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 106).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "SSH", "is_correct": true}, {"id": "C", "text": "Telnet", "is_correct": false}, {"id": "D", "text": "HTTP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, 'e4cb46bb2371c715_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('518eebe1-9b8d-48e9-bc82-ad31bccc1249', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 106).', '[{"id": "A", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "B", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "C", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "D", "text": "Prevents DHCP address exhaustion", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '503187deecdb94a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eea6059b-4693-4127-9d40-f91dc8d573d1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 106).', '[{"id": "A", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}, {"id": "B", "text": "TFTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "Telnet", "is_correct": false}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '7554841112020c59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b40ccce6-8aa5-44c3-a263-b9cd21ae2266', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 106).', '[{"id": "A", "text": "JSON (JavaScript Object Notation)", "is_correct": true}, {"id": "B", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "C", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "D", "text": "CSV (Comma Separated Values)", "is_correct": false}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '43ab9cc5919a9c6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67a1d342-a022-4fa0-9020-3b451ba6597f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 107).', '[{"id": "A", "text": "IP", "is_correct": false}, {"id": "B", "text": "TCP", "is_correct": true}, {"id": "C", "text": "ICMP", "is_correct": false}, {"id": "D", "text": "UDP", "is_correct": false}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '786c97926f703705_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3ca6016-4ceb-4e95-89e2-6d4dbadeb994', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 107).', '[{"id": "A", "text": "fe80::/10", "is_correct": true}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "ff00::/8", "is_correct": false}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '98e7a4d126b7d213_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('573bd2f4-d0c8-4a5f-be1c-eb9fb263d0b3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 107).', '[{"id": "A", "text": "Translates private IPs to public IPs", "is_correct": false}, {"id": "B", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "C", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "D", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '318e86268ea825f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b988acf3-b139-41df-8d3e-c11692d826e5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 107).', '[{"id": "A", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, 'b7e1e614e4572fa9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d0eb142-667b-4e3e-a9fa-444872aa73cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 107).', '[{"id": "A", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "B", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "C", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '149141a985b97746_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4671c74c-65f5-444a-acc3-91e134282d13', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 107).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is the default management VLAN for switches", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '7a68201c45b775c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c6fd009-2292-4f03-b8a7-f8e84b584512', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 107).', '[{"id": "A", "text": "Listening", "is_correct": true}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Forwarding", "is_correct": false}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'a64c36654b76d9d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b04bb52-013b-431d-a789-69e3b4e1b182', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 107).', '[{"id": "A", "text": "active", "is_correct": true}, {"id": "B", "text": "auto", "is_correct": false}, {"id": "C", "text": "on", "is_correct": false}, {"id": "D", "text": "desirable", "is_correct": false}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ce2d10a497ba04dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7d45934-cfee-4ad1-a93b-fe39a48d2e9f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 107).', '[{"id": "A", "text": "The router with the highest bandwidth interface", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the lowest priority", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '16f49c5b6bde8485_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27d4ba09-7a88-4fd5-99b8-3a1275e602b0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 107).', '[{"id": "A", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "B", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}, {"id": "C", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "D", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, 'c09f92d261622133_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa55af89-14ca-4d4c-9391-68bb2799485b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 107).', '[{"id": "A", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "B", "text": "ARP", "is_correct": false}, {"id": "C", "text": "ICMPv6 only", "is_correct": false}, {"id": "D", "text": "DHCPv6", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, '03b6e8a528747c9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('582cd331-e598-42ef-af89-ab359e439cda', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 107).', '[{"id": "A", "text": "OSPF", "is_correct": false}, {"id": "B", "text": "BGP", "is_correct": false}, {"id": "C", "text": "RIP", "is_correct": true}, {"id": "D", "text": "IS-IS", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, 'f4e3cb48a1042eca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7206eabc-c180-45f1-8225-568a56d462d0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 107).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Authenticates DHCP clients", "is_correct": false}, {"id": "D", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4bb08a236aa269fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba04dd1e-bc64-4a89-bd14-3d1d31587b91', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 107).', '[{"id": "A", "text": "Dynamic NAT", "is_correct": false}, {"id": "B", "text": "NAT overload", "is_correct": false}, {"id": "C", "text": "Static NAT", "is_correct": true}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '1bfa0731a8e224bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d41a335-0bb6-49d3-9b2a-dc0b65b86d8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 107).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '7f10ad8fbf3e69d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('058eba41-6995-48b2-89e0-b5a61c9f70f7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.78.127.0/24 network (variant 107).', '[{"id": "A", "text": "access-list 1 permit 10.236.95.0 255.202.69.0", "is_correct": false}, {"id": "B", "text": "ip access-list standard 10.236.95.0 0.1.70.255 permit", "is_correct": false}, {"id": "C", "text": "access-list 1 permit 10.236.95.0 0.1.70.255", "is_correct": true}, {"id": "D", "text": "access-list 100 permit ip 10.236.95.0 0.1.70.255 any", "is_correct": false}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.1.70.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'c54d2f9e271eaefe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96a21310-824d-4840-a5e1-e85ac83d467c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 107).', '[{"id": "A", "text": "SNMP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "HTTP", "is_correct": false}, {"id": "D", "text": "SSH", "is_correct": true}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '948ed2e3147a9b78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e109120-d082-479c-b9f9-cd5e8466b58f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 107).', '[{"id": "A", "text": "Assigns IP addresses to devices automatically", "is_correct": false}, {"id": "B", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "C", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "D", "text": "Logs all DHCP requests for auditing", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, 'a48d5180ca4f380f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('789d8766-05b7-4295-8b62-e39dc2345303', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 107).', '[{"id": "A", "text": "TFTP", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, 'ae65970b4a44277c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8c8c285-720f-4f87-b1a6-ece500b1ac93', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 107).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, '92398c0ed8fc6e01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('482d25b8-6c18-4936-8996-79c4bf27186d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which transport layer protocol provides connection-oriented reliable data delivery (variant 108).', '[{"id": "A", "text": "ICMP", "is_correct": false}, {"id": "B", "text": "UDP", "is_correct": false}, {"id": "C", "text": "IP", "is_correct": false}, {"id": "D", "text": "TCP", "is_correct": true}]', 'TCP (Transmission Control Protocol) provides connection-oriented, reliable delivery with sequencing, acknowledgments, and retransmission. UDP provides connectionless best-effort delivery.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '029527a9557605b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80575f4a-db09-4b14-8427-bfdf29d15b25', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the IPv6 link-local address prefix (variant 108).', '[{"id": "A", "text": "ff00::/8", "is_correct": false}, {"id": "B", "text": "fc00::/7", "is_correct": false}, {"id": "C", "text": "fe80::/10", "is_correct": true}, {"id": "D", "text": "2001::/16", "is_correct": false}]', 'IPv6 link-local addresses use the fe80::/10 prefix. They are automatically assigned on every IPv6-enabled interface and are only valid on the local link.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'Network Fundamentals', 12.0, '90f4c6c48a8fed0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cbae9c2-e28a-424b-824a-196e71730256', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'understand', 'What is the purpose of a default gateway in an IP network (variant 108).', '[{"id": "A", "text": "Forwards traffic to destinations outside the local subnet", "is_correct": true}, {"id": "B", "text": "Provides DHCP services to hosts", "is_correct": false}, {"id": "C", "text": "Resolves hostnames to IP addresses", "is_correct": false}, {"id": "D", "text": "Translates private IPs to public IPs", "is_correct": false}]', 'The default gateway is the router IP address that hosts use to send traffic to destinations outside their local subnet. It is the last resort route in the host''s routing table.', '{}', 'Network Fundamentals', 12.0, '80eab4ee9fa8370a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75aa2f1c-8116-4dd6-938d-a91475969129', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'On an Ethernet network, what is the purpose of CSMA/CD (variant 108).', '[{"id": "A", "text": "Manages power over Ethernet", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to devices", "is_correct": false}, {"id": "C", "text": "Detects and handles collisions when multiple devices transmit simultaneously", "is_correct": true}, {"id": "D", "text": "Provides encryption on the wire", "is_correct": false}]', 'CSMA/CD (Carrier Sense Multiple Access with Collision Detection) is used in half-duplex Ethernet. Devices listen before transmitting and detect collisions, then use backoff algorithm to retransmit.', '{}', 'Network Fundamentals', 12.0, '504f1258c2bc276f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc6eafa4-d7a0-4a29-985f-70031bd410dd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between an access port and a trunk port on a Cisco switch (variant 108).', '[{"id": "A", "text": "Trunk port belongs to a single VLAN; access port carries multiple VLANs", "is_correct": false}, {"id": "B", "text": "Access ports use 802.1Q; trunk ports use ISL", "is_correct": false}, {"id": "C", "text": "Access ports are faster than trunk ports", "is_correct": false}, {"id": "D", "text": "Access port belongs to a single VLAN; trunk port carries multiple VLANs using tagging", "is_correct": true}]', 'Access ports connect to end devices and belong to a single VLAN. Trunk ports carry traffic for multiple VLANs using 802.1Q tagging between switches.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'ad1a0ad582e246c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93e94f27-ee23-4249-9ac0-36f4f766266a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the native VLAN on a 802.1Q trunk (variant 108).', '[{"id": "A", "text": "Carries untagged traffic on the trunk link", "is_correct": true}, {"id": "B", "text": "Is the default management VLAN for switches", "is_correct": false}, {"id": "C", "text": "Carries voice VLAN traffic", "is_correct": false}, {"id": "D", "text": "Is used for CDP and VTP advertisements only", "is_correct": false}]', 'The native VLAN (default VLAN 1) carries untagged traffic on a trunk. Frames in the native VLAN are sent without a 802.1Q tag. Both switch ends must agree on the native VLAN.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, 'e6b35cc6bfad1085_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('915ab976-e306-4b83-8d24-6126d86ca766', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which spanning tree port state is transitional and occurs after blocking but before learning (variant 108).', '[{"id": "A", "text": "Forwarding", "is_correct": false}, {"id": "B", "text": "Down", "is_correct": false}, {"id": "C", "text": "Disabled", "is_correct": false}, {"id": "D", "text": "Listening", "is_correct": true}]', 'STP port states: Blocking → Listening (15s) → Learning (15s) → Forwarding. Listening state is where the switch listens for BPDUs to determine the network topology.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '0b6722b5090ed8b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7586265-3b00-4ae9-a490-d6bdadd399b4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'Which LACP mode configuration will form an EtherChannel with a partner set to ''passive'' (variant 108).', '[{"id": "A", "text": "desirable", "is_correct": false}, {"id": "B", "text": "on", "is_correct": false}, {"id": "C", "text": "auto", "is_correct": false}, {"id": "D", "text": "active", "is_correct": true}]', 'LACP modes: ''active'' initiates negotiations and will form a channel with ''passive''. ''passive'' waits for partner negotiation. ''on'' forces the channel without LACP negotiation.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Network Access', 12.0, '151e3cc0f60c9765_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30ce1e4a-bd98-4990-8a7b-37f10140d605', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'In OSPF, which router is elected as the Designated Router (DR) on a multi-access network (variant 108).', '[{"id": "A", "text": "The router with the lowest priority", "is_correct": false}, {"id": "B", "text": "The router that boots first", "is_correct": false}, {"id": "C", "text": "The router with the highest OSPF priority and then highest RID", "is_correct": true}, {"id": "D", "text": "The router with the highest bandwidth interface", "is_correct": false}]', 'The DR is elected based on highest OSPF interface priority (default 1). If ties, the router with the highest Router ID (RID) wins. The BDR is the second-highest.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'IP Connectivity', 14.0, '93b6f6a6e82e9ded_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0577524f-88fc-4672-8818-49fa62434a99', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is a floating static route (variant 108).', '[{"id": "A", "text": "A default route with next-hop 0.0.0.0", "is_correct": false}, {"id": "B", "text": "A static route that changes dynamically", "is_correct": false}, {"id": "C", "text": "A route that uses a floating IP address", "is_correct": false}, {"id": "D", "text": "A static route with a higher administrative distance than the primary route, used as a backup", "is_correct": true}]', 'A floating static route is configured with a higher administrative distance (e.g., 150) than the primary dynamic route. It only appears in the routing table if the primary route is unavailable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'IP Connectivity', 12.0, '2603e0dfb7a69b38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('789e1103-a6d4-4677-8608-ec485c7813eb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'Which protocol does IPv6 use to resolve MAC addresses from IPv6 addresses (variant 108).', '[{"id": "A", "text": "ICMPv6 only", "is_correct": false}, {"id": "B", "text": "DHCPv6", "is_correct": false}, {"id": "C", "text": "Neighbor Discovery Protocol (NDP)", "is_correct": true}, {"id": "D", "text": "ARP", "is_correct": false}]', 'IPv6 uses NDP (Neighbor Discovery Protocol) for address resolution (replacing ARP). NDP uses ICMPv6 messages: Neighbor Solicitation and Neighbor Advertisement.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IP Connectivity', 12.0, 'b213672624cc2f0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('194850bd-29ca-4bbe-985e-38e5d10c9da1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is classified as a distance-vector protocol (variant 108).', '[{"id": "A", "text": "RIP", "is_correct": true}, {"id": "B", "text": "IS-IS", "is_correct": false}, {"id": "C", "text": "OSPF", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'RIP (Routing Information Protocol) is a distance-vector protocol that uses hop count as its metric. OSPF and IS-IS are link-state protocols. BGP is a path-vector protocol.', '{}', 'IP Connectivity', 12.0, '77f1a743b8123827_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1c786e9-4c5f-4cf1-bbca-5b2eb7b9578d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of a DHCP relay agent (variant 108).', '[{"id": "A", "text": "Load balances DHCP requests across multiple servers", "is_correct": false}, {"id": "B", "text": "Provides DHCP services when the server is offline", "is_correct": false}, {"id": "C", "text": "Forwards DHCP broadcast messages between different subnets when the DHCP server is on a different subnet", "is_correct": true}, {"id": "D", "text": "Authenticates DHCP clients", "is_correct": false}]', 'A DHCP relay agent (ip helper-address on Cisco) forwards DHCP broadcast messages from clients as unicast to a DHCP server on a different subnet, enabling centralized DHCP management.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '4fe1708f41955679_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4308f9a0-384e-4f21-89c1-1e96de9ccc3c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which NAT type maps a single inside local address to a single inside global address (variant 108).', '[{"id": "A", "text": "Static NAT", "is_correct": true}, {"id": "B", "text": "Dynamic NAT", "is_correct": false}, {"id": "C", "text": "NAT overload", "is_correct": false}, {"id": "D", "text": "PAT (Port Address Translation)", "is_correct": false}]', 'Static NAT provides a one-to-one fixed mapping between a private IP and a public IP. Dynamic NAT uses a pool of public IPs assigned on a first-come basis.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipaddr/"}', 'IP Services', 12.0, '69c846e4b1121eee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f35881ca-295d-427f-9442-47da8c5eaad5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which NTP mode is used when a client synchronizes time from a server (variant 108).', '[{"id": "A", "text": "Multicast mode", "is_correct": false}, {"id": "B", "text": "Client/Server mode", "is_correct": true}, {"id": "C", "text": "Symmetric active mode", "is_correct": false}, {"id": "D", "text": "Broadcast mode", "is_correct": false}]', 'In client/server mode, the client sends NTP requests to the server and the server responds with its time. The client selects the best time source to synchronize to.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/bsm/"}', 'IP Services', 10.0, '32c33f6fbd2187e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4acaf0c3-bb58-4ca1-9802-3b32f960be4a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'apply', 'What is the correct syntax for a standard numbered ACL that permits traffic from the 10.54.42.0/24 network (variant 108).', '[{"id": "A", "text": "access-list 100 permit ip 10.101.7.0 0.10.159.255 any", "is_correct": false}, {"id": "B", "text": "access-list 1 permit 10.101.7.0 255.178.160.0", "is_correct": false}, {"id": "C", "text": "ip access-list standard 10.101.7.0 0.10.159.255 permit", "is_correct": false}, {"id": "D", "text": "access-list 1 permit 10.101.7.0 0.10.159.255", "is_correct": true}]', 'Standard ACLs (1-99) filter based on source IP only. The wildcard mask 0.10.159.255 matches the /24 prefix. Extended ACLs (100-199) filter on source, destination, protocol, and port.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '42e8de25f0829085_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac33a096-b1eb-4628-9aac-9af5dcdc16bf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which protocol provides encrypted remote access to a network device (variant 108).', '[{"id": "A", "text": "Telnet", "is_correct": false}, {"id": "B", "text": "HTTP", "is_correct": false}, {"id": "C", "text": "SSH", "is_correct": true}, {"id": "D", "text": "SNMP", "is_correct": false}]', 'SSH (Secure Shell) encrypts all traffic between the client and the device, including passwords and session data. Telnet sends everything in cleartext and should be avoided.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 12.0, '04c45f10b4ce3a44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b6e2af3-a5c2-408a-bd43-0d3941d15771', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the purpose of DHCP snooping on a Cisco switch (variant 108).', '[{"id": "A", "text": "Prevents rogue DHCP servers from assigning IP addresses by filtering DHCP server messages on untrusted ports", "is_correct": true}, {"id": "B", "text": "Logs all DHCP requests for auditing", "is_correct": false}, {"id": "C", "text": "Prevents DHCP address exhaustion", "is_correct": false}, {"id": "D", "text": "Assigns IP addresses to devices automatically", "is_correct": false}]', 'DHCP snooping is a security feature that filters DHCP messages on untrusted (access) ports. Only DHCP responses from trusted (uplink) ports are allowed, preventing rogue DHCP server attacks.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec/"}', 'Security Fundamentals', 14.0, '3f2b130b66d2ffc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecd3bd84-46b2-4e19-927d-979daccacfc5', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'Which protocol uses YANG models and RESTCONF for network device configuration management (variant 108).', '[{"id": "A", "text": "SNMPv3", "is_correct": false}, {"id": "B", "text": "Telnet", "is_correct": false}, {"id": "C", "text": "TFTP", "is_correct": false}, {"id": "D", "text": "RESTCONF over HTTP/HTTPS", "is_correct": true}]', 'RESTCONF uses HTTP methods (GET, POST, PUT, PATCH, DELETE) and YANG data models to manage network device configurations. It is a standard defined by IETF RFC 8040.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/prog/"}', 'Automation', 12.0, '0052a73f8fed5ecc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c19abedb-d1a5-4f25-879e-e8a622b6746b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which data format is commonly used in REST API requests and responses for network automation (variant 108).', '[{"id": "A", "text": "PDF (Portable Document Format)", "is_correct": false}, {"id": "B", "text": "CSV (Comma Separated Values)", "is_correct": false}, {"id": "C", "text": "DOCX (Microsoft Word)", "is_correct": false}, {"id": "D", "text": "JSON (JavaScript Object Notation)", "is_correct": true}]', 'JSON is the most common data format for REST APIs in network automation because it is lightweight, human-readable, and natively supported by most programming languages.', '{}', 'Automation', 10.0, 'bde168b20e02654a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f092d3e-c01b-456d-abaa-d19a738350ad', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain?', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '99c7035c1058ec22_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bee43f5b-ccc0-46c5-a0fa-c7046f910cb6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network?', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "30 seconds", "is_correct": false}, {"id": "D", "text": "120 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'e754eff188393989_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e81a2eb9-7c56-43e1-912f-842a98b2f53a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR)?', '[{"id": "A", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "B", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "D", "text": "Connects to external routing domains only", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'fba5976dd451473e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dda30633-21f7-4556-9b65-b45aa10a53d8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA?', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '8ee17eeb99a84718_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('711bb07d-82e3-412c-90a9-0bc0eb836342', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status?', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'c870251ea203917b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c2f673f-d9ed-43cb-ba74-0ef797133f8d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs?', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'fdee94468a855b5e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('591b1621-01fd-40a7-ad4f-75a48957423b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers?', '[{"id": "A", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '4fa98c70c97b295e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc78d990-fbd3-4172-9806-df5406f15801', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos?', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '550a8137fdd73063_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('584eca6e-1701-41bd-93a9-e708fdd45411', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers?', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '18e8225831537b5a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8731fbb9-33c4-4936-9808-a884cf30b482', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS?', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '1fe692c9ec339756_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afa1446a-d528-4d63-b39a-5a2402c32054', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session?', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '1a91f6e09ad6a00e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99cc154d-a34d-49a3-b6aa-032eaa9bb370', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do?', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '316f17faf2dbbf81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24a5b16e-a661-4de8-a600-516d22598397', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria?', '[{"id": "A", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '173a1d42eb84fdee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('149b32c6-4707-4e5d-bf5a-b287209125a0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes?', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "ORIGIN", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '0e82f959dd1cefac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76fcb951-27ea-4fb7-af32-302b68cd77b9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify?', '[{"id": "A", "text": "The AS of the route reflector", "is_correct": false}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '79d2c6b5ccd755c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af92f081-3577-4cb8-bbcf-ce97b561c208', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration?', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'c7d0eed3a08df71a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b31bcd6-0eda-46b1-96f7-2436444bbdea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix?', '[{"id": "A", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "B", "text": "show bgp summary", "is_correct": false}, {"id": "C", "text": "show bgp neighbors", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '5dbf7db73a538a4a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('932f805d-23b8-49e4-96bf-782f3cc4c82d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP?', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'e1ece44fa6dd1d21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fa009cd-50d2-4b8c-8fe4-f81161276cf7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR)?', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'a20a0b03bdf24d39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ceac8fa7-94bc-4ee3-bd95-1239a4cf3134', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch?', '[{"id": "A", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "B", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "C", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "D", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'd6aae837c1534751_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8504d9f-097d-4a8b-8730-f99a933aa3f8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding?', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'c89ac28d5e13d5ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eed0631-f7c8-4d21-bbdb-0b125046b1f6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network?', '[{"id": "A", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '5ef75364daabe030_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9136802-6b96-4f09-95eb-a5bbbe8de544', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port?', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Backup port", "is_correct": false}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Designated port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '13d7beda70465453_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('961678f2-c815-46b0-b232-f96b880664b8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI)?', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A physical link aggregation group", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'bdb5aab7419f9588_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7aa2be06-394e-4e5b-a3e9-1afd8ec40498', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state?', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show stp status", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '35f4795f18ba9f0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ef61dde-1055-4e22-a22b-049ffd17a098', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port?', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '2f00e165b4801576_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea8e3ef9-af7f-476f-82bc-248254a53cf0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP?', '[{"id": "A", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "D", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65000 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'f21a33a5c75e2d1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b0d1522-e4fa-4aa8-b2bc-7c7c420bf9a1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch?', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'cd1605551b61789e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62bb861e-38a5-44b2-948d-e4bf3af7a41e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN?', '[{"id": "A", "text": "set interfaces ge-2/1/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set switch-port access VLAN 444", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/1/1 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface ge-2/1/1", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '43c0bebb5bdd86c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee122bd4-edea-4c02-8763-fb8a138fd214', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging?', '[{"id": "A", "text": "65200 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '6ead988a305a86f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba90c351-0fba-4e6a-ba70-278ce14e5b19', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs?', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'd18214255d82f3fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43424a3b-c97f-45d7-8740-9882ed9aadda', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding)?', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "56 (111000)", "is_correct": false}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "46 (101110)", "is_correct": true}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '7dc285e6741be23e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29fa8fd2-b3be-47c4-a643-d205e6f1bdb9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic?', '[{"id": "A", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "B", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'dd4c747d58002ee1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee4e6a3e-7df1-4ecd-9e1c-53e39ff826c4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration?', '[{"id": "A", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "D", "text": "Determines which packets are forwarded first", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'c148b322f822b200_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d39ad542-38f0-4fd5-a89c-4df147db47e7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class?', '[{"id": "A", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "D", "text": "set cos rewrite dscp 46 interface ge-1/0/1", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'bf59a4f15e39ea0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62bb33f3-e613-46a9-a7d6-0d2e33f2c0e4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS?', '[{"id": "A", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'af0b4c990fbd145f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('101ddec7-b884-4afb-92e7-c1ade4c4fb49', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route)?', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'cddf878f873b23d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5ddd0fd-ad6e-4e62-b648-a0eac1cc4149', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number?', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "1234", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'ed9d927ce8b8ec7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be9b1edd-7340-40f9-8549-0e10c8aefb15', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs?', '[{"id": "A", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '6e086cc9c8a37060_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edb81f6c-9373-464a-b6bf-13a142e542f1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch?', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '9d9d4863116dee62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c821fb1f-5709-4317-b450-c2aed9162731', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches?', '[{"id": "A", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '5cd8a3e14cfcef42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a8d578b-43f7-4194-87bf-de2f462890c4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy?', '[{"id": "A", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "B", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "C", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '532dd764d71c9c74_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb19aeae-dcc8-4bc6-b9ea-9ec5b99fe01d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device?', '[{"id": "A", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "B", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'ae4d23d0d1f2e8ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('406c015e-d505-4232-9df3-22d9533423b1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos?', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '26b2c4af507c9722_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('201cb868-f1da-47d8-88e2-008049568831', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination?', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "ping trace <destination>", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'd5f81543ae75e301_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67ea916e-fcde-41c9-ad3a-f016d9de460c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display?', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '6ba38387b0871067_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc15026c-54a3-4673-bf83-26f0fb0da024', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol?', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "show route table inet.0 <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '802e2cf6de64eab7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('023a44b3-733f-43bc-a705-9ea773c4facd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming?', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'c079dc5401fa441f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57ab7028-4047-4326-aca2-3f3dcdfbc100', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter''?', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.59.56.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '3bc61049736a5041_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c96895d1-7db8-4877-b439-ddfb8f434f73', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos?', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "C", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'f93544ae6f63bdf2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fc21b4d-177f-43b4-8a6a-c4c8853196e5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response?', '[{"id": "A", "text": "reject", "is_correct": false}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "discard", "is_correct": true}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '4269ea79a3b8c1f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f73f193-4bbc-4d3c-b799-386b79a817bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918''?', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '304d5b5eda9c2a80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70d9fb7d-af1d-4157-9467-40431d37c6a5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches?', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "D", "text": "Single switch acting as both core and distribution", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '6b6962ea77a8674f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c9b5152-364c-4b0c-91c7-1f5a004ffb9c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network?', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '6dfb4999bb3b2826_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a33384dd-6dbe-4bb6-b51d-1bd7c51a64b3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management?', '[{"id": "A", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "B", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "C", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '8cb688e581ba7208_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9b4e24f-889f-4935-bea6-57a6ba131e0e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 2).', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '020d32d4e7f02792_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57f6d187-2d78-4900-b2a8-ef122224f89c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 2).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "30 seconds", "is_correct": false}, {"id": "D", "text": "40 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'aea6f195dfe725ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('538e6d1b-e97b-45d9-9e8f-fc926f3893c6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 2).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '2ca9beb83d96d4eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5638698-9d0a-4016-94a9-55f813ffcc41', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 2).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Advertises external IPv6 routes", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '9f94331ac107c945_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6598ee1-d38c-4063-b7b1-0ab82bf06600', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 2).', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '652028b66d2c9241_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3822c9f9-36a6-46ef-bf8f-ef42acc6c766', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 2).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '9efb7c8f779a54ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6b8a250-5388-4987-9789-9ec93871dd8a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 2).', '[{"id": "A", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '949da934886c9f7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('420b4905-319c-437c-a3a6-e33d7e9e631f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 2).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'a5990ed94d50cc82_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19e63366-1aff-4e0b-a6d6-a193ca12b36e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 2).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '2af7edc7655cc8a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d0ecb01-a03c-4502-b0ef-81896a68c869', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 2).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '7e90cc22ab1c9c34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('934ddbbe-cf87-4eb6-9a75-557563059cd5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 2).', '[{"id": "A", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "B", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'b1498105c0e74ed6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68195c4d-a627-4961-a1cd-a0aa89e8daea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 2).', '[{"id": "A", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "B", "text": "Configures the local preference value", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Sets the BGP router ID", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'f89a384fd18231ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f9c7bad-ea39-4a12-af79-af62ba7ee137', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 2).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'a10e9f7d93443903_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7fafea0-d59a-4671-bb4f-7ba011f74f1e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 2).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "ORIGIN", "is_correct": false}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'db6a42aade4ef3d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28028de3-eb08-447e-a80c-ede494607f85', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 2).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The group of route reflector clients", "is_correct": false}, {"id": "D", "text": "The IP address of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '3f209bbf4f2d87f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35430aee-a6ec-4728-8f5d-c8e032709213', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 2).', '[{"id": "A", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "D", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'd24ff8e15905f8f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efe35226-6d77-4775-9e51-c6b8f9c66528', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 2).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show route advertising-protocol bgp", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '7d80dcd9edfb14b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('745777df-0a45-4136-87de-fa169fc76ab8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 2).', '[{"id": "A", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "B", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '127b0ab8640a900c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7a21cb7-b001-44ae-af0d-60350ea674a9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 2).', '[{"id": "A", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'fb15d1512ded5f67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65815d57-8183-41f9-b831-d2c6e74a0a38', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 2).', '[{"id": "A", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '18e2424be14490c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ea86070-a054-4385-ae6c-3bc1debff33c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 2).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '7149ab46beed1d5e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c6e4a48-c2e9-49d5-ab6d-dda1db8edf51', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 2).', '[{"id": "A", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '92523da8ef027a66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d203217c-5fd4-402c-89bc-0a7e4e8e932d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 2).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '219866ba8e014f44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('521c9343-8fbe-4078-94c1-d194a2557524', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 2).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '4c2096e36cfc9cd5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4aea6b0d-7e65-45c9-a52f-d903378a6136', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 2).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'b9f105a6afdbab0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67f04ebe-a6c5-44ee-b60d-e700e7182b21', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 2).', '[{"id": "A", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'ec79e53de1ffc6ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4e68878-8c6c-4319-8140-2f461b74ecf8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 2).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64700 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'fa14ed79428499dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d74e762-c469-4136-a750-10f7f7008e6a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 2).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "C", "text": "Connects to the management network", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '4ac3c3d1bb91d5eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d94c4c2-1bf7-4b74-b9f4-7e13fc919903', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 2).', '[{"id": "A", "text": "set vlans VLAN10 interface ge-2/1/0", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set interfaces ge-2/1/0 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set switch-port access VLAN 29", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '8e89c38b3893309c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9512995-0042-4e34-81d6-830abb4e856a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 2).', '[{"id": "A", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "65500 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'cb31767530af21bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa14f17a-2ccf-438b-a9ec-bc5b06f966fa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 2).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'e42134d086b77f7a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71d94ddd-8b41-4dab-af17-ac4f717afd2d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 2).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "26 (011010)", "is_correct": false}, {"id": "C", "text": "46 (101110)", "is_correct": true}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'bfa0e4cffe45d3f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee033c1f-12a5-4a66-8aa1-f70305de1895', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 2).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '747f1dcd366a335e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62bed56b-3ab1-418a-b4b5-1e9cb5f8085c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 2).', '[{"id": "A", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "B", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Determines which packets are forwarded first", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '14e24a00d2a4a83c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3c58c7a-e1f1-4309-98a7-6a425392690b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 2).', '[{"id": "A", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "B", "text": "set cos rewrite dscp 46 interface ge-2/0/3", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '36268d19e20b1ae5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9b9e7f8-82e3-46b4-95a4-0a18d353ffaf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 2).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'ad4170f7e31f2df3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da5a31cc-389a-4702-bfbd-58ab2f217900', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 2).', '[{"id": "A", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '8abcd954f5575188_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eebcefc6-e358-4440-b100-9bc9c265b595', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 2).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "8472", "is_correct": false}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'b10b04cc57bf94c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6de54ae9-8ae6-4019-8745-5ae192e63273', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 2).', '[{"id": "A", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "D", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '278b0967418c7d18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02f4d8a0-2e9d-4b6c-85e2-981f61a52ec6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 2).', '[{"id": "A", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '31d9484788cccd65_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d10d11c-67c8-4ab6-a49b-42b3bda4b98d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 2).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'e347c99c3373c488_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30760616-cbc5-4638-affa-dbf0ad84982a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 2).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "D", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '66e1aad0fc6be6dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c93cc256-252a-42c1-bdc7-b4a22af10a61', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 2).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '0f98b57cf8a49878_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f495c975-7e64-413c-b65c-3643357e25a1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 2).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'c038f85a177e29c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d11fd088-47c0-4dd5-a416-774c4e7aae2d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 2).', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "ping trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'f23d0019a52b6986_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97149448-c06e-4526-8fdd-b938caa376cc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 2).', '[{"id": "A", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "B", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '44d2461a94113e17_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b06f55e-22e5-4db0-a8de-c282b1e8c764', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 2).', '[{"id": "A", "text": "show route <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "show route table inet.0 <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '60ad56980eabfcb3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f8ade20-ac8f-4831-8074-8d5f490ef96a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 2).', '[{"id": "A", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Replace the interface cables", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'f6d90d03d2eb543b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dc65f97-10b0-4ea2-8905-a421a392785d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 2).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "D", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.132.148.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '4800c72296f50fc1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f49923b-a05d-474e-8a4e-591ae4969ae4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 2).', '[{"id": "A", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "B", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines firewall rules for packet filtering", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'f9011ea40a4fa515_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3e30a97-cca7-4365-8fc5-0aeb786c5ce3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 2).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'b98d2f444f5463b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef669fc7-17f5-4c95-9b7f-c1b0b11ad0cb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 2).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '4cd135fbf48a9c6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f31ce3cc-0857-40af-bfa0-35390c33bf8f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 2).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "C", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "D", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '7a4c7acdd8092384_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7069bdfe-ebdc-4ddf-91ba-c0f9f073bbc6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 2).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'c7a42cd4312f02e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df09e0da-ea8a-46db-87af-acfd5f5dc1a5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 2).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'd1f863b44b3857bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53d8a36c-9ef9-4fb3-8907-99570e5a5a80', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 3).', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '7510e44893b05f62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('caeea413-a3b2-4e1d-8701-057489b6ea5c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 3).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "40 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '5e5a4e79e7186f49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fde2d347-2efe-4800-89ef-cae66c4f60af', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 3).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'b10d225bfc1c1187_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2774462-8469-4da0-afad-8a8bb7967c75', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 3).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '2b3bd2e93569256f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acb0f2c5-28d8-474a-9c36-f0ff052f4548', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 3).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show ospf interface", "is_correct": false}, {"id": "D", "text": "show ospf neighbor detail", "is_correct": true}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '0e5b5066e35b7be1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f3c8787-634e-45e3-b695-4a5abba168a4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 3).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "D", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '57e68d672393b5ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d48a92b-1506-49d7-9b79-a98af130d056', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 3).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '16c2d581882076b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5eb2198e-f7a8-4b60-a919-e2149c91fdaa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 3).', '[{"id": "A", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '9272a0d964016b32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac4cbc0c-33f3-447c-801d-1c1ec0b007c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 3).', '[{"id": "A", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '40fae63372398d54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('026711ff-c13e-479e-9f01-ba6812227b99', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 3).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '2bc6225f1b4cb869_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0a734ab-a0c9-4acb-8830-a6c7a37c5279', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 3).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'e43b9a9444b63af1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e85f75b1-972c-4828-b0a6-348c29783719', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 3).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Configures the local preference value", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'ed912567d0070679_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d59b807-8e96-4439-8339-87d6fb407ac2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 3).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '4a4d77e7ed49e6df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26d7a397-7f3f-45fa-9a4f-b9c30b89860b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 3).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "ORIGIN", "is_correct": false}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '5152bca59f65d3af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9acfbc9-b41b-44c8-8b4c-1efc5c148ec9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 3).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'c17aa8ba01dbef16_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2def6e7-9560-4c54-b665-8e9b79b97801', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 3).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '40010c68191f3dfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f935eb39-4e28-451e-82b5-729dc7fc48df', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 3).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show bgp neighbors", "is_correct": false}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'f59db65ca5ed0b91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78111f72-d230-4c2e-97ef-4f35c420ff8d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 3).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'a32d31c895a64dca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7282ad37-6f2a-440a-bd8d-863b807ab54b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 3).', '[{"id": "A", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "B", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "C", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '7dc5216350c35b65_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6dbcd75-1fa6-47eb-9629-884dc5c8135a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 3).', '[{"id": "A", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "B", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "C", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "D", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'e098910f61af9958_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9566cdb0-4da0-480c-b173-c4a94de47884', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 3).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'f5c4e2bfe489d980_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0592df0-4438-4296-8fc0-753a8dc1ffab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 3).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '4168e8077caf5e6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b13c8cfb-882b-4a71-92a0-436549da9566', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 3).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Alternate port", "is_correct": true}, {"id": "D", "text": "Designated port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'cfe5461c022e8b35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11f4e367-2445-480a-9502-784cb1a13d2c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 3).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A physical link aggregation group", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '5e7ef018658e5345_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e7b7be2-189c-4d7b-9a12-f7ae4ccd9d5c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 3).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '410b7b80c614e747_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8c5b9ca-56c8-4379-92e4-0239049cfdb0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 3).', '[{"id": "A", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'a8e48126248295b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91deb296-d558-43b3-9c58-1056dc7cc4ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 3).', '[{"id": "A", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65100 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '8fccd0cbf7d949f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f74c09f9-02ca-4403-9a49-e180527d4edc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 3).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'c785a06c096f909e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36b60518-c6c0-46fe-8550-e33f61b5baa6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 3).', '[{"id": "A", "text": "set interfaces xe-2/0/1 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set vlans VLAN10 interface xe-2/0/1", "is_correct": false}, {"id": "C", "text": "set interfaces xe-2/0/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set switch-port access VLAN 384", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'ffac03370006dd54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a92f3c1-7592-4749-b027-ebf9b635349b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 3).', '[{"id": "A", "text": "65100 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "256 (8-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'dae55299f71ac498_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('858866ce-7039-4898-b231-1b199fce9ca8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 3).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '95bce648dd2b1bcb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad1f73c0-1bec-4d01-af99-1d5becada3c9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 3).', '[{"id": "A", "text": "56 (111000)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '67556e8374b9a62b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32a9dd38-8ba1-43b6-8f1f-8ec2b9f7967a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 3).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "D", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '815223e74944fbad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70eb925f-8295-48a5-a71f-8df0cf5af268', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 3).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '41794d7d4508925e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fc599aa-ab54-4f42-a561-68e759118328', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 3).', '[{"id": "A", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "D", "text": "set cos rewrite dscp 46 interface ge-0/1/1", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'f382c8f014f08016_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('648da2fd-d0ae-4481-aac4-fcec2ce7c6ba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 3).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '2b3d736b28fee391_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c747383c-b1c9-49a6-ab71-83c1d5237729', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 3).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '8a37343579cb5c4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7dab862f-2b0f-4394-8d83-5706fbc2d77f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 3).', '[{"id": "A", "text": "8472", "is_correct": false}, {"id": "B", "text": "1234", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'b643fa3b066faf78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ba14bab-0176-4cc4-af4e-7751ac75691a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 3).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "C", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '12bb6493146ba6d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('568e2bf2-783a-4095-84fd-67c14310589f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 3).', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '6e3edf90298d947e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b5f7498-ea08-4485-b783-e2e35cbe188b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 3).', '[{"id": "A", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "B", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "C", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'd578b7b7081dd383_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6635491a-32ab-4858-9fb9-707661f6a27f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 3).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '9ac08fe7f27f612b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c099884-de73-49b6-a82e-652ba0e90a02', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 3).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '707d9bec5914ad18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2728e770-660f-4feb-b608-083951863711', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 3).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '5f2b12bb50ba69d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e7f2b39-143e-4521-9d0d-e23caafd44bb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 3).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'e02d021e9cbad186_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4291f926-b05d-4ebf-b958-329849dddfc1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 3).', '[{"id": "A", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "The OSPF link-state database", "is_correct": false}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '3db00df7cca05ab2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ec42ac3-edd7-486e-84aa-7ce1df7e5a10', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 3).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'b122570c192ab04a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5b81342-1900-43ed-a54a-9fabfedb72a2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 3).', '[{"id": "A", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Replace the interface cables", "is_correct": false}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '8b99383172561aab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cdfedaf-694e-4c9b-9811-a2447fbada47', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 3).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.147.227.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '0c9d0b05b9d9ea93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc3824aa-427d-464d-a519-1916e0deee7c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 3).', '[{"id": "A", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines user engineer permissions to the device", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'fde68a5c67fc435c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('886690c3-f9ea-42b7-a9d5-14ea18a355d8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 3).', '[{"id": "A", "text": "reject", "is_correct": false}, {"id": "B", "text": "silent-drop", "is_correct": false}, {"id": "C", "text": "deny", "is_correct": false}, {"id": "D", "text": "discard", "is_correct": true}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'd84454d3372f9f7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f4d2d96-4e75-4c30-8ee2-312920a0be96', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 3).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'd0253d72a1eb3ae2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0aa13b74-c913-4e86-b55c-921692a6c457', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 3).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '5b6d3e621b1d51b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a04e2035-d633-4321-81e4-3fe722f8e59f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 3).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "D", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'd19e12e50cfb3eb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('864572d3-c014-493f-a901-0f7af6c0e26d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 3).', '[{"id": "A", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "B", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "C", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'e31c60f429d69486_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0494fe4-b94a-4bce-b703-0b908f45a1f8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 4).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '403aa70d2045f095_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e1d6bde-378e-4abe-8abc-bb0a04e39ea0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 4).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'f261ad653e2dd79a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8079290e-b43f-422f-9243-0ff8c9304b5b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 4).', '[{"id": "A", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "B", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "D", "text": "Connects to external routing domains only", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'c5422cbfe59851a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e8daa9f-ae88-442b-bb47-97805b2aef65', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 4).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'c55febe4c78af093_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23bd193d-5a6c-4415-9b13-9b601b3338bd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 4).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'e2b27707e6f5e94c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75767f86-9aac-4eac-8a28-fd522223e3c0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 4).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '41c9ebb2aa8c138a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01c26454-6936-43ee-9419-b7ff741fc1bf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 4).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '78688d479829bdb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4f495dd-6317-4c9d-b403-65fb3afaa21f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 4).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'aaa97ba97ebc7e81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a79d6915-027c-459e-b1e8-5731208a75cc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 4).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'dbf49d4987d4526a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65b7a755-014d-402a-8960-0be3ebedbd31', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 4).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '19d2487b316c496c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40c63d6c-47ae-4d5b-a133-eb4fd58c8988', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 4).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '79ca55ab8bf0e3ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7657ef8a-6358-4e2d-a140-3ff1175b4579', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 4).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "C", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "D", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '346c6553d29ab619_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92cd2246-992f-4850-93a9-546e97312da1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 4).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '72b7b04a1fc2f242_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c241f01-d595-4063-98b2-ea9722bb0a0a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 4).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "ORIGIN", "is_correct": false}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'ec05cf110bb23b56_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15109b67-dcd9-4ebf-9da5-0ecbc90e5b65', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 4).', '[{"id": "A", "text": "The AS of the route reflector", "is_correct": false}, {"id": "B", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'a1ea1f41d1de4b13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e6818aa-3339-407f-b5c5-241ba5cd72e4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 4).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '65a511210010b076_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7caaaccb-f8ed-488f-b6ab-e14637ccd65e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 4).', '[{"id": "A", "text": "show bgp neighbors", "is_correct": false}, {"id": "B", "text": "show bgp summary", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show route advertising-protocol bgp", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'e9ec61aabf49daaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62d594a9-0d5d-4f88-81b8-007455d5146b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 4).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'd554cc611cce6aef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2855e397-f7fb-4eb1-9dab-589ec817bb09', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 4).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '31b27ef1e5bdc25b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b60b47a9-fd91-49c5-91e7-4e1836361979', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 4).', '[{"id": "A", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '11af8935e43ac82c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f1928e1-ce46-4281-b745-292f07e42b7b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 4).', '[{"id": "A", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "D", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '8860b685279748e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29fe3979-626a-431e-bb4b-03049d43080d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 4).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '76b194fcca519992_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bd35089-f8fc-4105-a76a-c460d419a6a1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 4).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Backup port", "is_correct": false}, {"id": "D", "text": "Designated port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '101322ea0ac23465_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf24bdd1-e06d-4385-8741-16bdecd021f7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 4).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '0ada466534936e33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b08aa79c-cba6-40ce-8089-796339e8cbc7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 4).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show spanning-tree interface", "is_correct": true}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '9be7f52671d5cf41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0591bbf-e72d-4377-b18d-14cf7c537a8e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 4).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '032398daa5ead1a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1f2edf2-d9ba-4626-881e-1c5bf344901a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 4).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64700 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '680042e6cb3c155c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3bdeaf2-4b47-4ee2-a357-28a2e4e16cfc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 4).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Connects to the management network", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '056720f2192f13f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f24ac80c-1fca-40da-ac98-bd95d306c868', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 4).', '[{"id": "A", "text": "set interfaces ge-3/1/0 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set interfaces ge-3/1/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set switch-port access VLAN 497", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface ge-3/1/0", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '5df1a4c8f00705f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b83e10be-0a71-4f3c-8445-0631c112c9ba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 4).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "65000 (16-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "1024 (10-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '3cc8e484e77ed420_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4df076f3-f1ea-4ea3-a372-de4406be18d0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 4).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '87d42ab63cb8d158_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a5e87d1-f8a5-460e-81a2-585905227c0e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 4).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '2035c443a8ab6e6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ec9c014-f3fd-4f2d-b210-57603bb98cd1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 4).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "D", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'c2c8e652a1d88737_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7d61aa8-4993-467e-812d-1064920fc09d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 4).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "D", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'a34bc0d9286535f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ef0da46-3524-4910-bebd-707c10cb2c21', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 4).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface et-0/1/1", "is_correct": false}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '09eabae46d1a8a16_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb7f8ba0-df6a-4d84-bbd3-d44978d72441', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 4).', '[{"id": "A", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "B", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'deb74b6144df9b3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03be0278-bf20-4b12-b563-4c4e8689e1da', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 4).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '092bb2ded56b6697_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4c16a6a-2bdc-48df-ba0d-fc083eed2f9b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 4).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "6633", "is_correct": false}, {"id": "C", "text": "8472", "is_correct": false}, {"id": "D", "text": "4789", "is_correct": true}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'bf0fb37e444c39fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c8facb9-513f-4363-9111-0549ad378cb5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 4).', '[{"id": "A", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '8409805e9d5d37b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f074c647-ba06-4ebf-ad24-3a7259d73a4a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 4).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'd8cfd02b55f41342_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('301eaf28-6ba3-4280-89f5-d3e27b3ba898', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 4).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '1adeecc54f78a8f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02c665fa-d1a9-4e3d-8092-f446d2a1fb71', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 4).', '[{"id": "A", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "B", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "C", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "D", "text": "Each host is configured with multiple default gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'e9fbc3b6d9554836_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0cbe7273-134f-4029-bf2d-fd6e93b347b0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 4).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '688d65648f40716d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3e88727-a4d2-41fb-9d82-f0f1db7b0157', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 4).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '22aab913650709e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db0d8084-0d63-4fa6-a611-ca94dbda98ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 4).', '[{"id": "A", "text": "traceroute <destination>", "is_correct": true}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "show route <destination> trace", "is_correct": false}, {"id": "D", "text": "ping trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '4ccb5cbe53538dad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d06e9415-c077-45df-bb62-267951a93230', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 4).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The multicast forwarding cache", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'bec1503ef586a095_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e542fc19-f9e3-4a69-92c2-6cfa179a2e0a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 4).', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "show route <prefix>", "is_correct": false}, {"id": "C", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "D", "text": "All of the above can be used", "is_correct": true}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'b202ef996e618103_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64498e1a-cbd3-4d24-be6d-2cb1f22259a5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 4).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '8af0f1ae1e3c6178_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1d5c5a9-ded6-4c30-be83-82051633f4b6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 4).', '[{"id": "A", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.23.185.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'ca463e011cb38414_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('184bd4b2-58a8-4bd0-906d-1a466e9490bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 4).', '[{"id": "A", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines user netadmin permissions to the device", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'c7a3e47ef771b7fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdcf1ece-bbcc-4f5f-b81d-aec8d5fe16d0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 4).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '0f640e5055ec57ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cde4618-3169-4e50-bc6f-84616f10a98c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 4).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '7b5bff71c772fdc7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6d3f00d-af72-4948-84b0-27cc17813cc3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 4).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "C", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "D", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'c9aee9d00b980ed1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81e536c0-50cd-4ae1-af4a-27e3a9104813', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 4).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "D", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'a0a0aaf82af48959_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('911f9d46-fd8a-4c7b-a46d-e263d0b0a706', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 4).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "BGP on loopback interfaces between the switches", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'dc69b29b83bca562_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8226049-f4e3-4faa-89ce-b6cf860c2483', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 5).', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "Internal Router", "is_correct": false}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '40facb053e5f120f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96a98a3f-7211-4c3d-9d4e-b298e4785b63', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 5).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'c75b7d542041461b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efb9f48c-0ff8-4652-a550-261d50611452', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 5).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '77c4a141fd1194d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5b6b2a3-6bca-470e-a64a-076d431aaaf6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 5).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'cc26ecee5d0dab72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3216a59b-7b08-4f16-b4ab-6aa699d05685', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 5).', '[{"id": "A", "text": "show ospf interface", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'fac2d669401a0ebd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c99011c1-8fa1-4059-8cd0-8bff3b167fcc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 5).', '[{"id": "A", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '35e94225099179df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37b34cc8-c65f-4db7-b5c7-37d5091c0064', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 5).', '[{"id": "A", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '54c8ea8cb2f072df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8256c949-7103-441a-aa85-5fbf56d343ac', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 5).', '[{"id": "A", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '4c04ef606d9847cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8481d7c-bb10-4903-a2e2-edc3c46b9e53', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 5).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "C", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "D", "text": "Hello PDU (IIH)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'd647ea8e4e6df59c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fac4dc90-af93-40c2-a3a2-50b507837112', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 5).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '5ac30a07869b421d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62d00c4e-c367-4149-a6f4-fa4e013ec310', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 5).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'b64b48b8b335bf96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f6a1a8d-5005-4c10-8489-669f8dce1cfe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 5).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'e00e95246abeea7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3560183d-c8df-44e4-bdad-affe0ed03e9f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 5).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'd367754b6dea36d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e330644-dd57-4753-a9b3-9e7c0658db01', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 5).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'a697dde9c568347e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('845b390f-6520-4e6b-90e4-ccf6df82e360', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 5).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'b7c59c8ad9aa5df8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a59338f-662c-4fb6-ba10-89b94f44103d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 5).', '[{"id": "A", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "B", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Permanently deactivates BGP advertisement", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'd1cd1fc83ff25b55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cb9cfaa-01fe-4c63-9304-c26fbd6e2206', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 5).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'd334e2dfe0862739_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b885e150-1daf-46e0-acb7-ce916d6b8701', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 5).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '9b348cc535b48920_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76fb8031-d688-4b09-bff0-7e63cc3d6c1f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 5).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "C", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '4f9f4f09f8266b8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4008703c-db3a-44ed-a323-365923a439a2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 5).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '53946358e9135705_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b83e4ecc-7bef-42a2-b0da-11a68a96602b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 5).', '[{"id": "A", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '7db1c94bad5b751a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5620fb48-f384-4af1-adb7-9864b358df29', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 5).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'dbcca8c1e43deb7a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f04c7e5-de84-4bdb-8f7e-9db30bf19734', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 5).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Designated port", "is_correct": false}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '021ea021c0ea45ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c53589eb-2eb1-47ef-9c97-27c75e8b68e2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 5).', '[{"id": "A", "text": "A physical link aggregation group", "is_correct": false}, {"id": "B", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "C", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '12fb82b7c15602d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f031b33a-b571-4feb-a338-d196d6976dc7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 5).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'cc65bb2485b22ab3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ba3d119-d799-456f-8248-a06d0bf0182c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 5).', '[{"id": "A", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '591595400d5ef5b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e909ee31-5e55-4813-b9b0-e6cb48c00c37', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 5).', '[{"id": "A", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64700 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'd92d43a81ec5c43b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a14299f-a3bb-445a-b029-4c00a5864256', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 5).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '987dd8262756f678_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c3d8492-47b9-4f4c-9928-83cf5b285f58', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 5).', '[{"id": "A", "text": "set switch-port access VLAN 51", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/2 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/1/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set vlans VLAN10 interface ge-2/1/2", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '3d433868080e70d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('569dd4ff-2f11-4e48-9884-4b3e8a73d53f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 5).', '[{"id": "A", "text": "65002 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "1024 (10-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '27b591f95b14482d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6422963-10f2-4795-afba-953841d8c7e8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 5).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '01311502ecf5c8cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c8f5129-3e50-487e-92c4-92c81beb7f03', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 5).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "0 (000000)", "is_correct": false}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '884f6871e23e4b1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92ca3e34-b007-4ff9-9e34-8df75a0afbb4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 5).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '644a0a3c5c817e7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b84a3559-7df0-45ef-a5b2-ab3d169fe2c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 5).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'd5e2262b3f85fdda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0caa8d5-ec15-4d58-b736-7663fdedb2bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 5).', '[{"id": "A", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "D", "text": "set cos rewrite dscp 46 interface et-2/1/2", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'eab7cca87e729291_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c33dea0b-cd5d-442a-8de9-34d49ec644fb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 5).', '[{"id": "A", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "B", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "C", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "D", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '218122d3f0ee97db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1baed44-f70d-4349-a6ef-898bc01b04b9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 5).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '4b397dc37e7993e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c09803c-7aa3-4d5e-8d4e-5ab96e48e452', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 5).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "4789", "is_correct": true}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '516cce38e69df134_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('560665ba-becd-4f4f-874a-77370a46cf72', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 5).', '[{"id": "A", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '69103a420eda294f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4764cb1a-6823-4bf7-9844-85b0aa4a36c0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 5).', '[{"id": "A", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'b9bfd392221749f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74a49af0-0342-4b77-8a7d-59cec9e26602', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 5).', '[{"id": "A", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "B", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '7b658d9681f49dab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97418ec7-c0f3-4f9c-9f31-1d03a9d9a86d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 5).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '10975e10c71f5f4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05487cc6-344c-4a42-8347-7abc7411163b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 5).', '[{"id": "A", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "B", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "C", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "D", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '29b46c62db1cd077_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92b3f30f-dc3e-4805-8ba2-a765043ff94b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 5).', '[{"id": "A", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '97e589967539d9af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2aee7abc-2392-4dd7-9423-fa5510f2b213', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 5).', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "show route <destination> trace", "is_correct": false}, {"id": "D", "text": "ping trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'caaa84265c6310c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ebba4a5-1ac3-4847-b456-90d708d07fbb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 5).', '[{"id": "A", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '7ec689dad214dee9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c790dd9-f61a-4177-886e-19b73a55cc36', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 5).', '[{"id": "A", "text": "show route <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "show route table inet.0 <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'e9817539ec4ada1d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9694b3a2-6180-4d26-a4f0-d5f815fb9b25', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 5).', '[{"id": "A", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "B", "text": "Replace the interface cables", "is_correct": false}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '8cb190bc30a42f85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9dcfaa85-3cef-4289-add9-61e2a7e6a0ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 5).', '[{"id": "A", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.213.173.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'b1fbd19ae5990dc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d5160f6-77ae-4e3f-a4ce-80b682960ec7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 5).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Defines user tech permissions to the device", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '3eed20a5d3c9571c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45839053-4034-40ce-9f05-7f1fd59f6f8a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 5).', '[{"id": "A", "text": "silent-drop", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "deny", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '4596fed9df54ad7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c24799d4-a404-4c6d-b296-cdcc8997febf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 5).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '5bc9a020978a6b9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0ddca26-2bfc-4879-a4b1-b6c02e0234a7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 5).', '[{"id": "A", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "B", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '28534f784534180b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7456ed8c-9b82-47c4-af25-c44ab15d3357', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 5).', '[{"id": "A", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "B", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '16c2aa78a1225342_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3769ee9-3e46-40ca-878e-225f567565c7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 5).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '9dc52054c7ecf6f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74b9b36d-6bbb-4ecb-861f-08ae50047b42', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 6).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "ABR", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '183ca2b85bd2b3b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebc6e255-4a85-4e04-9cbd-65425cddc1d8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 6).', '[{"id": "A", "text": "120 seconds", "is_correct": false}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '2ba5502c7b4aeecf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f69ea5db-a368-4fe9-8054-2c9a8b185796', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 6).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'afb736ad22695a21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eaa9cea8-a0c0-4407-87c4-181a0f51f461', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 6).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "C", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "D", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'ea35a92949c04fc1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8711d132-ca5d-4faf-a3da-de2ed9a7bbfa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 6).', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show ospf interface", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '43e4a770b7d11be6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f9c4f61-05cf-4571-84e0-77cda0835aac', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 6).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'bc79639be47fd6f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b3062d6-0e79-4066-afbf-95dde6ede941', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 6).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '133e2f20b4e6299a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cff4bd05-c18b-48ea-9974-e3db1ec79cb1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 6).', '[{"id": "A", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'e549ca93b14c5892_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6abd5193-5aeb-45d0-af3a-5f79e2011085', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 6).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '973b23c4b95ee8c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49b81658-c6f8-4969-8cfd-5308872349c4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 6).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'e282f5c36c890f9a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a09a228-c325-4687-886a-59007a5a3e38', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 6).', '[{"id": "A", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'ab82613e3f6d0aee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('341aee29-9835-4f2d-b67d-b9a8d415d37f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 6).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Configures the local preference value", "is_correct": false}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Sets the BGP router ID", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '705da504b5b5933e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d7d0697-aa9f-42cb-bc6f-aa479ce07a4a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 6).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '37f80e8c903697ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71aafa58-e878-43b0-802a-a8b93bcf3de7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 6).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '3a1d6a4325d9cf61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c60d79bd-1497-4e1a-8f2f-20c9b3efdf94', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 6).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The group of route reflector clients", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '2ac566b8314d7867_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69ad10dd-ae3e-4f61-bed7-d92d16567ba9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 6).', '[{"id": "A", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'a7bf6edbca7a5167_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('404c6117-d0a9-4549-9a02-bb4edaeb19f6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 6).', '[{"id": "A", "text": "show bgp neighbors", "is_correct": false}, {"id": "B", "text": "show bgp summary", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'dc52447ebb9f5b80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ea28aa4-58f5-455f-be94-261527702785', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 6).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'ffbc32fab1048b96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('192de36c-318c-4661-afd9-c3789e3a0310', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 6).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "C", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'd8ace2c8b00d25a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf3760de-16b0-4902-b16f-5f9923c18f2b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 6).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '873d8e0aa9c38f93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('084ed84a-d8be-46b0-8efd-ca53d8bab289', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 6).', '[{"id": "A", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "B", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '4042db4598570d01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a75e9f49-c54e-409f-a4b8-42bda1a5e0e5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 6).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '45cbb915bd37e527_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59295f87-a58a-4468-80dc-b44899b00531', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 6).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'f9baf367b4f20a3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cce10885-b675-485c-90a7-c6e0a5387fce', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 6).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '078e0a49c8163476_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f819a79-6cda-45b5-a362-803ba97d4177', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 6).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show spanning-tree interface", "is_correct": true}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'adfc15e503451b46_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9de54139-f01e-4c6d-8b71-c31ac63c97cb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 6).', '[{"id": "A", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "D", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '1fa2f01f2bad3857_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cf8a0dd-7426-477f-b769-54a5c8006aac', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 6).', '[{"id": "A", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "D", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64513 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '7cc72a8c9775f31c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5e0db62-63dd-46cc-a845-f7260eaf66ae', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 6).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'a1de196ae041c24c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26afd14b-7c5f-4452-86c8-b165aac8af3f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 6).', '[{"id": "A", "text": "set switch-port access VLAN 293", "is_correct": false}, {"id": "B", "text": "set interfaces et-1/0/0 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set interfaces et-1/0/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set vlans VLAN10 interface et-1/0/0", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'c454f39c0c786e72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69d29a55-fe23-45e9-aa2d-ec867aebbc5e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 6).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "64800 (16-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '64b543bdc49b761c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03445b18-0d36-4799-8cc3-84fb50758d77', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 6).', '[{"id": "A", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'e1aa6b73d5f589cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('379ef8bf-482a-476c-ae94-a3c2eaf70577', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 6).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '1b01af2672440524_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c976c65a-7e40-431f-8793-64aa28681f00', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 6).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'df6ccf78a8de4bab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a1f0c79-f138-49c5-865f-554abc0a7ccf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 6).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'c12e91583539e8e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27f91a33-abef-4cdd-ba5c-bc495cd9280c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 6).', '[{"id": "A", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "D", "text": "set cos rewrite dscp 46 interface et-3/1/1", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '7a080a2de4b62f5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01c3c1b6-24d2-48c9-a56d-05a6ea141797', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 6).', '[{"id": "A", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'f63ff31a8ba16c13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc0bbda8-3934-4a2d-a0fe-3e7492260001', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 6).', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'abf269c6ef075d2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aca83044-e660-4e04-8b53-9d8c64f554cf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 6).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "6633", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '3acb87c35c8f447e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e714d22-efc3-4179-8e82-13debfad9d67', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 6).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '47cbd787f085dd11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94e12dd2-195b-4cc4-b939-547c8165cf0c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 6).', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'e49c50f5bf0a5f57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51ca89ef-b2f8-4e39-8563-29aeb2ee86a6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 6).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "C", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'fe558717762ff7c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('792decce-ce70-4360-abf9-f20e87206798', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 6).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "C", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '0a590862c0429b15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('880ae4dc-fc54-47e4-b20b-43fe9309554c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 6).', '[{"id": "A", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'aad9d48a09147f8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1de883f-193b-4ca1-94dc-2a83acac2e3a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 6).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '21b3a23135bea915_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd4a0e8a-411c-40a4-930b-73793cdb1ae0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 6).', '[{"id": "A", "text": "show route <destination> trace", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "monitor trace <destination>", "is_correct": false}, {"id": "D", "text": "ping trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '67f0c3bf097bc407_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42a36571-5613-4119-8b0a-4d853b77d181', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 6).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'b3ac8469a39870c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a11169f-ed4c-4c64-8032-8737b177d5b3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 6).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '2e21aa3646e46ab3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97c229d1-654e-4472-b3b9-c3770af2df3c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 6).', '[{"id": "A", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "B", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'cc0863b563b1edad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('908baf08-5adf-4730-aafc-db42d2cd064a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 6).', '[{"id": "A", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "B", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.204.74.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'f9f58ffcd96026a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5225921a-d767-4711-af8f-e8d4240cb7f6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 6).', '[{"id": "A", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines user tech permissions to the device", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'dfca32219cfeef52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b37dde93-f4f6-4f3b-ab7c-e83bccb9ea82', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 6).', '[{"id": "A", "text": "silent-drop", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "deny", "is_correct": false}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'ffb4d0b3ffafba62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86abb627-6a5f-4200-a79e-3bce282fc9b3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 6).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '747586e7100b2bdb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d73eda61-e5b1-462a-bffe-6a03cb5e015b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 6).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '8a80eb223e6ad899_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91a8d805-20a5-4574-9b32-17a42940fb11', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 6).', '[{"id": "A", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "D", "text": "No BGP configuration is needed in the fabric", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '21ccd8343224901c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87fbe31c-40c4-44d4-bc56-7bcc33de25f4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 6).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '2338848429b3b2a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c32a5121-49ce-4e02-9adf-427b70040310', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 7).', '[{"id": "A", "text": "Backbone Router", "is_correct": false}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '9dff70dbe8cd9969_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9130885e-2f61-432d-af12-ca843acd4fa3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 7).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'c4b71fea0b0956db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5237b06a-be93-48ca-b840-3e40657f793c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 7).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'a025b3927968ae86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94e2100c-3a8e-42a7-86bf-f473118852b2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 7).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '8e6a8ba812c2d9d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0235f803-b226-4359-842f-ab6296a451a4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 7).', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'd02630daa4c11050_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d82d52a-a55d-4a46-bc9e-9f3d0ce7c6ed', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 7).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "D", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '6290eb223863a585_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('087dae04-a2f9-4ced-a554-85315e471ee7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 7).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'a667da2491a5e450_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f9831e4-c22d-4310-93cd-fd95a5fbcb9f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 7).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Both narrow and wide are supported by default", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '728af700a154fd47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e724c43-7269-4276-b847-8cb032b55af8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 7).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'dcafdb2dcb4fab28_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b28e0de7-606c-43ae-b7e9-636e6e1381b8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 7).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'baaea5167be068ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6812b05b-a031-4086-8aea-f952ca37cd7a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 7).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '2f13711026c85dcf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00ac8ada-f991-49eb-87b2-3b25918a0808', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 7).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Configures the local preference value", "is_correct": false}, {"id": "D", "text": "Sets the BGP router ID", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '23f85358cba26abf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5d5a8ff-72dc-4422-99ee-3a62c16297fb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 7).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'b3f2cfe8c937782c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bc79aaf-0f56-462e-96ef-e1dc0e7b3be1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 7).', '[{"id": "A", "text": "COMMUNITY", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "ORIGIN", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'daf6b5f5629689b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfa0a837-e701-457a-97b6-6725445fd429', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 7).', '[{"id": "A", "text": "The AS of the route reflector", "is_correct": false}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The IP address of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '2a0eaac925014f10_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3908086f-cb23-466b-bbcc-d4003ecb75e5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 7).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '42bbeb189c0b5a48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('991fb671-29c2-4b09-abe7-0ae2f2c2112e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 7).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show bgp summary", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'e832178ad586f2c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa6cdf5a-5230-4721-9e1a-81e1309d533e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 7).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'e622102d512767ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4aa61509-2018-4a12-a8f8-3ae139b7aea8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 7).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "C", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '95f01cda4bba7d82_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d24a6cc-2e49-449d-8d6e-c882c184a9a5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 7).', '[{"id": "A", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '73e488e998af7234_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0694779d-b2db-4964-84e8-6945f761a125', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 7).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "D", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'b76f77b97c48e025_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97b90a02-9843-4b35-be9e-0692891320ed', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 7).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '128b81edd80424d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcbecca8-da46-43ef-a782-ea70df3cd511', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 7).', '[{"id": "A", "text": "Edge port", "is_correct": false}, {"id": "B", "text": "Designated port", "is_correct": false}, {"id": "C", "text": "Alternate port", "is_correct": true}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '8b0a7dd4db0eec5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eeb2983b-583e-4549-a921-1a887d72d86a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 7).', '[{"id": "A", "text": "A physical link aggregation group", "is_correct": false}, {"id": "B", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'be1e09a0cf9dc940_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d2084f8-4050-493e-b332-ad5cceb79f6d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 7).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '2ccfe151279d5033_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ff6fbb9-0242-4e06-b1af-6f198bb12f8a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 7).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '2c828e5dc3a131fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ad2a495-d2ab-437c-96dc-99bd1df6da8b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 7).', '[{"id": "A", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64512 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '5061a4009a530b56_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('851b0206-c9ce-4268-aed3-e3f7acb101bb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 7).', '[{"id": "A", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Provides PoE power negotiation for access ports", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '03fb802f667c4089_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('339f43af-29e6-4cf9-8eb9-67b16eac8424', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 7).', '[{"id": "A", "text": "set interfaces ge-3/0/3 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set switch-port access VLAN 467", "is_correct": false}, {"id": "C", "text": "set vlans VLAN10 interface ge-3/0/3", "is_correct": false}, {"id": "D", "text": "set interfaces ge-3/0/3 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '34404d88846df7ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5005e30-8926-4454-a619-f545f4eb1acf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 7).', '[{"id": "A", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "65300 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '9b3257a0b7a8199d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24c82d8d-cafb-4c78-a621-1a55c4232c43', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 7).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '1a0927f84c059968_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e71cbb5-08b5-4ede-9770-cd123c2e097b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 7).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "0 (000000)", "is_correct": false}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'e46f98da83365c54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7ebe06a-3c7d-432d-9005-e67ba6506c1b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 7).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '3d82d9d469a72e83_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f7c950b-ce1f-493d-9d5d-d98ba7914162', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 7).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'ef886c1d33db8b65_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e39a478b-e684-4ab4-a3ec-00a44595f411', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 7).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set cos rewrite dscp 46 interface et-1/0/3", "is_correct": false}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '37d87d13d6d58e6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30e4e108-8425-4068-9947-76fe792a298c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 7).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '37ffce06a2163ef3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('610b7a50-d289-4179-a582-70c302f237e0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 7).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "D", "text": "Carries multicast group membership information", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'e9e33ea4f46a4ba1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12502a71-8096-4e99-9d3b-e3d31160442b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 7).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '3af1409245e317e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dc5f09d-fa3f-4280-a718-3f2825e8de10', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 7).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'a392d8eedf590b1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f029d039-4c3e-41b3-95b9-ca3daab95563', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 7).', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "C", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '3b21103f2e2bd46e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00d997ff-60cf-4be6-a90e-065d23b7b689', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 7).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '3fff3a45cf5eec06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('266b889e-665d-4b83-9d32-34cfd1435500', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 7).', '[{"id": "A", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "B", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "C", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "D", "text": "Each host is configured with multiple default gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '9b6a9f32f990eed8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80af0742-11cd-45c4-a5c0-1c72991f0434', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 7).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'b8f58cf6d6b8f680_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a38bb60d-dbe7-41c9-90d2-8163423608c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 7).', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '1bef5a6910902a61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fa0d6b9-fdc4-4005-ae44-301a8875b53a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 7).', '[{"id": "A", "text": "show route <destination> trace", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '7d2a79abfe747d47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7426eb5-a2d1-444e-831e-edb619b5f789', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 7).', '[{"id": "A", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'c444208c1aa59329_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('475845be-3f54-4814-8efe-0954a415527c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 7).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "All of the above can be used", "is_correct": true}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '4b9be8758c01667c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('190e3aa5-f0e5-44bf-9577-716305775ec5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 7).', '[{"id": "A", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '265a5f97b736a024_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('519a1a32-9015-450d-9888-05c438016a14', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 7).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.10.40.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '19957b3396543073_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72d7a146-83af-4b16-9494-fef05867edb6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 7).', '[{"id": "A", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "B", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "C", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'da6f0a1caf148f6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('876e2c7f-3537-4aff-b194-e6d6462abc27', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 7).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "deny", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'bb46dd87d56ecf46_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53ff671a-8a95-4f44-8a42-e2b1968dee7d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 7).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "C", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "D", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'ed9b5f9ccd30484e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e5bafcb-27a3-4077-92af-5301c0c27353', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 7).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "C", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "D", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '6c040fa1b0bd7143_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b812d6f4-e45a-4ba3-a9a4-f4fa9393a91e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 7).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "D", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'dfa5af657ef23b41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9af9054d-a481-47a0-9510-ca2c9539aaee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 7).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'c7cf2b6af5872910_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4560a381-cbb1-4a57-9069-6dd1ec25ed3c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 8).', '[{"id": "A", "text": "Backbone Router", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'b32ed4c47912f034_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c10b4f8-7eae-4683-ac88-312901c300a2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 8).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'a86531d8c745382f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70c6aea8-fcff-4086-8c69-fb321e497f5c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 8).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '02a22688dda70f6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3feffe07-3d34-4e30-acbd-cb394aa65457', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 8).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'd9c7d845e66d63d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d01afeed-ad26-4f34-abad-00881d63e46c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 8).', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '5ad331329722b653_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c9d5a36-748e-46eb-a0cd-54ab55a0d24e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 8).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "C", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "D", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '8690c6efffcfb4b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bda9e93-ec8f-4199-961f-8f5d341795bf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 8).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "C", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "D", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'bbfec263238c3eb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('929d4ce4-b81a-4913-bdf8-3a791cd42aa2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 8).', '[{"id": "A", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '1ec3bcf7bb26b21c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52013cb0-bfb0-4896-8bce-4423922554fd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 8).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '091f36810712930e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('874a8bb6-3489-48f7-a1e4-9dfd9d328b0a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 8).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'a39b7794f49fb868_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('105d11ce-3bc4-444c-8a1a-fcc3c109125c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 8).', '[{"id": "A", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'a95224916b507ca2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abf0146f-1428-4be6-b2e6-3fe592ff150b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 8).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'c0d11599358a8d95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05277d55-7a9d-43f1-9e45-a9bb80fddb06', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 8).', '[{"id": "A", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '814626402bac98c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63d5a61d-3d40-4a08-8383-6ee93ffec75f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 8).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '76de4f1377b31be8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35bf8d39-32f0-4f66-ba05-01d7e413a106', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 8).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "C", "text": "The group of route reflector clients", "is_correct": false}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '4ff1b249aec0fde9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fb18605-7293-4300-837d-64d910312e5e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 8).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '3bf14d6062c11fba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a02e051-a5ac-4b08-bd9c-05c1106e0b64', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 8).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show bgp neighbors", "is_correct": false}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '4a42c2b385bb66cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('088b5131-cc2e-461f-b5b7-c3f21f040166', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 8).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '46cacd174abea56e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('952d7e3d-7ced-4586-bfe0-93d5f6f6c23b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 8).', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '9c997398623dff4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d75f4e89-5b5e-4dd7-9e9f-1450725b8900', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 8).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '1e57e6cc1e2ad4b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0464c861-11bb-43ff-8bf1-4f4881ea8423', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 8).', '[{"id": "A", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "B", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "RPF is not used in PIM-SM", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '81481e63cecfd2e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd3278b3-a59e-4109-a17b-bd97ffd04a12', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 8).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "D", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '0f19403a491a54a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d6b05de-625f-48d7-a4cc-1e98c68f737e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 8).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Alternate port", "is_correct": true}, {"id": "D", "text": "Designated port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'c23d25bbb30cb4f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e412b6ec-413a-476c-9de0-0dde3b3fbe11', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 8).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '6c1b273956b53857_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9310992b-6acb-4700-b7ef-c374161102a6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 8).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'e25e0ede93d197c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ecb8fa2-92c6-40c4-a01b-23eef7f1bb52', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 8).', '[{"id": "A", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '9cd5827ec4300971_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('951b699f-be12-427c-bf4e-aaa207a1f79f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 8).', '[{"id": "A", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "B", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64514 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '727cb4a0562f695a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffccfe49-d6fa-4935-b930-ee873983eaeb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 8).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'dcf9cfc67b51eda6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56119dfa-7168-45a3-93de-89c778c83699', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 8).', '[{"id": "A", "text": "set vlans VLAN10 interface ge-1/0/3", "is_correct": false}, {"id": "B", "text": "set interfaces ge-1/0/3 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/0/3 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set switch-port access VLAN 41", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '44c1a045ff790f88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0485447-439c-43c4-9904-56e20c3b5006', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 8).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "64800 (16-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "1024 (10-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '6abbd2959f80394c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abde0e6a-17d2-43a3-9e51-e18cda572f4e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 8).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '2923b6a23f65b95d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff98a337-ba54-4d30-bae2-a6b14c89b37a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 8).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '01491cd55781b5b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcff3544-3d63-4046-8316-440fcb87540b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 8).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '6de64a6446b304f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41d9c2f3-c01f-4754-9086-b9908b5bf581', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 8).', '[{"id": "A", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '2caba0d6092a14bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28459764-9734-4f49-8349-84600ab69806', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 8).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface et-3/0/1", "is_correct": false}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "D", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '811c73d5f010421e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('538fa978-35b4-44a7-afb8-78135fa54e8a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 8).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '18cf2132d5f94102_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b550a1c-0d32-426d-9a9c-ca6d94b0d4cc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 8).', '[{"id": "A", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'b4b173f36f003f91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45604233-ea2b-4ae7-86c3-cb13b7065395', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 8).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'a7890690f1ba5219_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b5d2021-c25f-447f-b8fe-2991c90d2a90', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 8).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '9963af6a66ad1dda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f74f2fd-79ab-444d-a96b-7ec328d2b873', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 8).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'd87ebb01157db7ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c71f6f8d-092f-45f4-9653-606ac934f148', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 8).', '[{"id": "A", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'eb09162947139b23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b40bb96-a0aa-4991-b784-909cfb7f1b56', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 8).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "C", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '5bd5a55f24f409c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cabf0bc0-9e6a-49a8-ab9c-c6c8242e8b5a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 8).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '42385016e3ede97e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('694592a6-a027-475b-9ffe-ff7e2ff1fa1e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 8).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "C", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '652a92dc473ac74f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21c6c7b5-09bb-4fa6-9b1d-e1390d20c289', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 8).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '9c45ff36188d3ad6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1acee4b-6e0e-4393-a31c-763ad34cb1a4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 8).', '[{"id": "A", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "The OSPF link-state database", "is_correct": false}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'e9bfb844dcd31449_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6942aa35-1627-482a-83b6-94ca076e1aa8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 8).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '7042321e0109551b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edfbded9-72e5-461b-8be5-acb11584da28', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 8).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Replace the interface cables", "is_correct": false}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'd34733b85037411d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62d099fe-82f6-46e7-83e8-681d391c9f65', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 8).', '[{"id": "A", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "B", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "C", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.126.137.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'bad4d992d5417afa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2aa7693f-f8b8-4d0c-8622-af386cd84425', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 8).', '[{"id": "A", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "B", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "C", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '61c5c57edd5940f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b79d4cf-9765-4cdd-92fe-0b714a33782c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 8).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": true}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'dd00744c3075a98c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ee89b24-fc02-4720-a5d6-0f4c38be16b0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 8).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '8edacfbcb8e7d5ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ad6eae2-1cde-4f06-ae87-5227167f3f91', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 8).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Single switch acting as both core and distribution", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'e3a0fe0ad5c8e235_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2782132d-5fe2-4e40-af6f-e1b3e3517169', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 8).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'b4e3f8e8e948828d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2d8ae30-25db-4404-a1df-b34f7f992e85', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 8).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '41b66dfbdad0b723_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe63ce8d-4da1-485d-84a0-629af7f77f5d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 9).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "Backbone Router", "is_correct": false}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'eb193e8583c01fd6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9dd533ab-0ec8-473d-8eea-6a05ff8aed06', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 9).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "120 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'db7f9f1a2dbdbeb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9ec0d1d-5085-47af-a50b-3143c59ca734', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 9).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '77476331d84ef1f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6325294b-0003-41a2-99a3-a4964e2b7b34', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 9).', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'dc4448b3a8483623_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9f735c1-92dd-46d3-968e-5e72e9d28385', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 9).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'b96bb31921cbe3b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34f2664a-194b-4e56-b421-f3dfabe45967', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 9).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "D", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'b279f351af428c0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4318338c-3026-4d7f-b1e9-afd9e6e96041', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 9).', '[{"id": "A", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '3f791a7c5c8af9aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a1977c1-735e-42c5-a1ef-4c428e9ae302', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 9).', '[{"id": "A", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'd77d20132b27a449_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63985a3c-173c-4cf2-9f98-0d3fe22e64d3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 9).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'd9cf8a9acc66ff56_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('358a3ba0-a4db-4ba9-a8c5-5b2dc0172629', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 9).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '576068ce42105fd7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f72032b-e0a4-4784-8917-c22fb1d55dba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 9).', '[{"id": "A", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '221a93922ef89552_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f500285e-420a-476b-8d61-1ab3f1d8243f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 9).', '[{"id": "A", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Configures the local preference value", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '72486562df528efb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9b78777-2706-40b8-9738-a3cdd0d3f18e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 9).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '46cc8b9a6405c82d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8bdba88-1e87-45b5-819f-78bbd7b6ccac', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 9).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "ORIGIN", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '218f002902f2b6e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8028d54-c4b9-4499-aba0-0021eb870e80', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 9).', '[{"id": "A", "text": "The AS of the route reflector", "is_correct": false}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '10b9d30e9662e003_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41b13173-2e99-44e8-9589-6961ca51e6c7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 9).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'bd202a31a8236ef7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98a53e60-9c95-40bf-b784-b4b4beeabb2f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 9).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show route advertising-protocol bgp", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '49ab52f1c15371d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb3f2405-12f8-4338-8fa9-f4ab59413559', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 9).', '[{"id": "A", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'dcbc0cd67cbde07c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9460d1bc-b9ed-4067-9d56-b7549cfe7c93', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 9).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'b3f1d2858755e32c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16f1d53d-439e-4312-bb78-4ccd53cdc092', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 9).', '[{"id": "A", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '06f06f2d33a90989_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a03c4f24-9210-4256-aeb4-e40d8a375a44', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 9).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'e0b2895516e3390e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41b14ed1-1077-4d02-a8e8-9419f7aab9f2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 9).', '[{"id": "A", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '01c9bc917647b1cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4293cae0-f32a-4faf-8484-3621ca3944a5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 9).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Backup port", "is_correct": false}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Designated port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '9738ec50836e0823_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('faab3574-8746-4430-b191-7d4ecf53f809', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 9).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A physical link aggregation group", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '197972f36b99819a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45ea576f-4627-4493-b09e-44f658a0bf13', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 9).', '[{"id": "A", "text": "show spanning-tree interface", "is_correct": true}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'c75618460b6b8068_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61be7862-9841-44d8-9cd9-66299ea29706', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 9).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '17909f04a3fd79d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a4c5387-aee9-4f9c-bf43-01d09f0039d2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 9).', '[{"id": "A", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65001 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'f77c9e3c742e166a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('386db848-5a71-499a-9baa-a5b9ce5792c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 9).', '[{"id": "A", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '0ecb52db355a8879_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74f309e6-c18f-4f16-9aa5-3ae15a38a9b0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 9).', '[{"id": "A", "text": "set vlans VLAN10 interface ge-3/0/2", "is_correct": false}, {"id": "B", "text": "set interfaces ge-3/0/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set switch-port access VLAN 85", "is_correct": false}, {"id": "D", "text": "set interfaces ge-3/0/2 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'baef0f27950dc90b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8def96a9-aa9d-4c0f-b347-cf7a7c757a24', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 9).', '[{"id": "A", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "65400 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '2f9b2f183a17243e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01850612-8b57-4d43-9510-d5b632e59363', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 9).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '9b2113a06010eb4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('305a8ea7-7738-4e24-a1b7-fdb04ffa1a0b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 9).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "0 (000000)", "is_correct": false}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'c726e93cf0cce766_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc6d4f99-4e97-4edb-a859-000af83095d0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 9).', '[{"id": "A", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "B", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'a5f245b866ddfdd4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c64fdd7-e5b5-42af-8be3-37e2caf4acf1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 9).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '93ddcb4f7c2e69da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9527e301-ec9a-4ffa-98c2-eb674b5dbbe2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 9).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface et-1/1/0", "is_correct": false}, {"id": "B", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '26aaf9ed02983461_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c58a02ed-f037-4e0d-94e0-412abcdd2bb9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 9).', '[{"id": "A", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '54aeb4c55f0f0300_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1b3b3c8-cefd-4a32-aa8d-f8ebbc4a176f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 9).', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '48770c4cc17b1f45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d48e9e1-ab08-433a-a55b-67ccd2460300', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 9).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "6633", "is_correct": false}, {"id": "C", "text": "8472", "is_correct": false}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'a66d7b2203a49753_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f88e7744-b323-4658-8210-8244224a3995', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 9).', '[{"id": "A", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '3f2531bcc59599b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08d4a77c-81dc-4c1b-ae9d-67e9ba7d881d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 9).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "D", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '12b5431f4c7605c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7c87e05-c1ea-42dc-a01b-03747896d68e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 9).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '7852dc71fefcf7e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6fa28a2-00e9-48ad-8502-26662df5dcab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 9).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "C", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '0f60c9167b352495_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a3cbe74-ded6-48fc-a7a7-6faafca3ef2f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 9).', '[{"id": "A", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'de6a40dbe95cc236_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a931762c-f0b5-458d-858b-94fc60e32b7c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 9).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '245906d047760575_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d8b84b4-0826-4e00-8af3-f1db5daa90a8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 9).', '[{"id": "A", "text": "traceroute <destination>", "is_correct": true}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '18022cba8d19add6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86116182-7114-4222-a926-0f49e53496df', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 9).', '[{"id": "A", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "B", "text": "The OSPF link-state database", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '36c81412296aa8b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c9db026-eed7-4751-a8fb-ae37b67886df', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 9).', '[{"id": "A", "text": "All of the above can be used", "is_correct": true}, {"id": "B", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'c8ab27fe895921ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04012eb7-47b1-46e6-bad0-9d363d5d9e8a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 9).', '[{"id": "A", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "B", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "C", "text": "Replace the interface cables", "is_correct": false}, {"id": "D", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'a5e552e6464f05d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03d801d7-03e3-4203-86e7-402aa646997c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 9).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "D", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.217.251.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '97a5565938593b97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1ffa742-07ae-4275-a066-92c8584d243d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 9).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '3eaa2d9e4319933b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7eaaa313-e5af-4531-a2d3-9e9585525046', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 9).', '[{"id": "A", "text": "reject", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "deny", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '97db08e71aafec54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e294f889-9194-4c36-af9c-5b2016a2f159', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 9).', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "C", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "D", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '3fe7e2543528e196_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e109e46-2738-417f-814e-ce0b95cb30b3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 9).', '[{"id": "A", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'a4343c9b74dac102_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad84948e-126a-4e71-a840-2cb436d2d5cb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 9).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '81d1d7de780896fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ec4f885-753a-462f-ad0c-be1f626e01af', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 9).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'e872c9d16ca96197_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64726b92-ac1d-455a-b7e8-3763e19c2b04', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 10).', '[{"id": "A", "text": "Backbone Router", "is_correct": false}, {"id": "B", "text": "ABR", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '872e2d0f8baa93fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1eed8ae7-10bc-4738-9a6d-98fcf4792925', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 10).', '[{"id": "A", "text": "120 seconds", "is_correct": false}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "40 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '6ce7db3cdea3e2f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82b466cf-fab6-4de8-999c-4aad8ec6317a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 10).', '[{"id": "A", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '885836894f5e4973_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('148a5c5a-b8cd-40a8-9c22-586e772803a4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 10).', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '89f7e65bdb60ec34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71f54356-e260-4cf4-ab86-1b26cc2d1351', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 10).', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'ee3c0dc907fa0f15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac7b8be4-2b94-4250-99dc-ef7f6604d893', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 10).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '3e585adc51426ff8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea174989-0cab-477a-b160-9e45868f061b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 10).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "C", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "D", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '44f50ede728b3a2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9dfbf509-5505-4e9c-8501-d885ab359ec5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 10).', '[{"id": "A", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '4b6f39be5f6f9370_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2022f640-43ae-4b69-af79-976adf824d12', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 10).', '[{"id": "A", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '51f6e33698f450fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a6f27e8-cf1c-4231-9969-545a6ac6e25e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 10).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'a8ff6c564a25d9c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('931ad2c0-afcc-49e4-bcc4-ad007efd0abc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 10).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '8e5aeca7b301665c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aad69106-6f7e-4d4d-8c59-95b60a1d8b8b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 10).', '[{"id": "A", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "B", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "C", "text": "Configures the local preference value", "is_correct": false}, {"id": "D", "text": "Sets the BGP router ID", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '8a85cf759de2478f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63d8e47f-c5f5-4db9-848e-757d36134f54', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 10).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'eba3cbbffb1efe3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('628d8485-7847-4e00-ab00-9c62a722b5fc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 10).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '13e9feb45223709c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('396838b2-7874-425a-95ff-9f6d028a3eaa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 10).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "C", "text": "The AS of the route reflector", "is_correct": false}, {"id": "D", "text": "The IP address of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'f057bdb1a09ebfee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7344a066-a43e-4997-95db-9ca2e7430bee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 10).', '[{"id": "A", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "B", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Permanently deactivates BGP advertisement", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '7a4f98173b2aaed4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce870609-f496-4e36-b2e0-d4d95c4eb452', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 10).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '959bea7159836f64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42e14198-1bb3-450f-8707-ae7213179e9c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 10).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "D", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'f495068d5bb11b6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa9cde86-b9fa-41ae-8aa3-783dafd7c50a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 10).', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'c21c1585c6ef2c0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('947452a1-0923-43a8-a14f-b09aba6880aa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 10).', '[{"id": "A", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '26be6ac6d3de1cdc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c333560-0194-4adc-ab63-5995c7ede6d9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 10).', '[{"id": "A", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "B", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'cd7052773ae88e43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc0c82b9-1a89-4bcd-b4cc-1f49fec0cb5a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 10).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'a6b752c86b92018d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3f4a4f6-e004-485e-b6ac-5619535a05c0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 10).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '30e2d38e9f22a87b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef85b2b1-9615-4464-b444-b81c892f1582', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 10).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '0abae6be0e951076_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2588ff0d-8ab3-4eda-b103-91202f59fa54', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 10).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show spanning-tree interface", "is_correct": true}, {"id": "C", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "D", "text": "show stp status", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '314f8d248288a657_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5d12bcf-68bf-437e-b31a-6ad54d332f21', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 10).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "C", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'edc56a7c1b0d7d80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5241117b-d86f-4ff4-8acc-fa9bcb4f3569', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 10).', '[{"id": "A", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64512 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '4caea86ca226d261_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b2a2ea9-5d62-4da7-b818-082fd5ed9997', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 10).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '28745b7f73c02c39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f3a4fd8-1599-4a34-b97d-72ae0a535e4b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 10).', '[{"id": "A", "text": "set interfaces ge-0/1/2 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set interfaces ge-0/1/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set vlans VLAN10 interface ge-0/1/2", "is_correct": false}, {"id": "D", "text": "set switch-port access VLAN 418", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'e14845567ff173fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('343010f6-e664-4012-a629-220fc38af20b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 10).', '[{"id": "A", "text": "64800 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "256 (8-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'eb04f26a36203ca1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b940026-6b53-4eb1-8dc9-fd29e67cb492', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 10).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '068def55d91714d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6d4c189-b62a-4a23-8ed0-8fdc615ec06a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 10).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "26 (011010)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'eb4f7b1bc4cd803d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2f6634a-7d9f-49e4-a1c8-f71d61ebe0da', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 10).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'c49fc96d78064528_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ea8ac89-e42d-4416-a711-a67a1bca251c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 10).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'ba162068a41274ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e256bd5-1017-4fb9-af3c-9bc4714abe6a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 10).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set cos rewrite dscp 46 interface et-3/1/2", "is_correct": false}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'a03b786206a61bdf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0c9b01e-53d2-4553-bff5-b6293cc8f52c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 10).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '88a66071b0ce986b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d93bc528-9524-4390-9355-b4672253bedc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 10).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '85216be65f107fa4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ee28145-1da2-4058-aa6a-89bf1a2c9d40', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 10).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '0ea4c7cb9b470e07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aaaf12a6-adc0-4513-a608-52c8ed5cf90e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 10).', '[{"id": "A", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'a9c185339ab0e40f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdcca88f-7663-43eb-82a4-2c474cd2cb6f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 10).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'f3899f0e0e1f6606_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a9bf0bf-4bdc-4b17-8405-c994a6f55446', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 10).', '[{"id": "A", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '28cab661734f6dd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('accce8eb-df38-46d1-8806-2a028b8f4eae', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 10).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "Each host is configured with multiple default gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'e36fee8888a7f52a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f04da684-4b84-4d26-8387-961646ca038e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 10).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '6e139c42701e0a35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ff808fd-886a-425e-9a0c-c518205e5073', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 10).', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'a3f868d3a78cb7da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58d29c95-0283-490f-8044-d510f28512b3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 10).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "show route <destination> trace", "is_correct": false}, {"id": "D", "text": "traceroute <destination>", "is_correct": true}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'ee58e7c8bcaf1baa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea9204ba-9ee9-49a5-98e8-6da132ba1786', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 10).', '[{"id": "A", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '4dc5a80b82f9a73c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd7e447f-0522-48d5-aee1-c1928c882270', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 10).', '[{"id": "A", "text": "show route <prefix>", "is_correct": false}, {"id": "B", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "All of the above can be used", "is_correct": true}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '400f4b1090e0aea3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dd0b97d-53be-4785-87ed-854d9787aad3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 10).', '[{"id": "A", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "B", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'f1cadf8a6f9bceda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbd865b1-f58f-427b-848f-a915f815817d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 10).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.231.55.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '62b7e0c80f40f1cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f16b14a-ab17-40ea-9d28-4646011c76ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 10).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "C", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'e031c7c93fa53b37_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f7c207e-cde5-457f-a1ef-46874f895573', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 10).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'cf56a80c0c1265a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fc86ccf-a484-4ebc-b181-49ad14e01296', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 10).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '46f1e22fea963b22_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f44e853f-8753-47ef-a966-81552f0003e5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 10).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'c1006bb6438a9087_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1f4a437-2ed3-464e-b695-1e89bc7c371f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 10).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '7b0126704ee21e78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('209b922e-9ff6-452c-90e1-ed4a0becafac', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 10).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "BGP on loopback interfaces between the switches", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '58b499265dce37da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ca244f9-1399-4f00-a65f-6759624798f1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 11).', '[{"id": "A", "text": "Backbone Router", "is_correct": false}, {"id": "B", "text": "ABR", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'a98df7e289492654_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c4f720e-c588-4495-96b7-6ace070f6426', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 11).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "40 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '2ee5619c94d9d04b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4b3c772-fd7d-4c6d-8b81-56400323a2e7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 11).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '85962a86aa1c890b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e9497a3-2c77-452a-bfb4-c6a3022019c4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 11).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "C", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '8bc8146f968b03e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87f2a5b7-8476-46bb-91da-4d01920fa808', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 11).', '[{"id": "A", "text": "show ospf interface", "is_correct": false}, {"id": "B", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show ospf neighbor detail", "is_correct": true}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '1b5c4d491b764576_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5c068a2-7cb2-41f7-b401-95ac12988226', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 11).', '[{"id": "A", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '99c9b33d343fe069_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e033c76-90ed-404b-88c6-d190f510b324', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 11).', '[{"id": "A", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '489625635d27056a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('641526cd-f94b-416c-a262-cd77b17b9ea8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 11).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Both narrow and wide are supported by default", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '19b1753b348107dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ce079bb-172c-42ac-bfa7-9ad919adaf29', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 11).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '0673360f586d0b9a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cf59913-1792-4323-accb-9bcf92afdbe2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 11).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'cdf73b1191ac222e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9da491a5-d321-4c6e-a777-a23ff478721f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 11).', '[{"id": "A", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'de6e92c236c5a80f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55877ca4-59ff-494a-af27-df6c31f6e082', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 11).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '1872d0d32cc6cdec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8dc754ac-575b-46c3-9a20-751113b11b8f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 11).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '4063a55c90e1d4da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bcbece7-48de-494b-ac8a-422981ba90f2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 11).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'b46c1259b448c7a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c15baaf-e9a9-4dfe-8895-b65f7aaa6423', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 11).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '7c2f785be80a6007_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d4ddc44-973f-44bc-93f7-847d44032627', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 11).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '50700a0fff8ffe84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8198f7fc-ddf9-412f-a689-e963ef2b8eb8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 11).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '92441ce8c0b9dc64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('332607ff-d88f-492a-808d-4ff9200c3401', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 11).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'ee0c20758239151b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47fd8f69-02af-4646-964e-7efb31a7f063', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 11).', '[{"id": "A", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "D", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '1d0ee2fdd42ffa65_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd58f13f-fcd0-436b-bab6-af9c43c41f89', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 11).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '7b8a303310fa5b30_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5db412b4-11d5-4cc3-b1de-9425155f19e8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 11).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '2c772984a321efbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b5e3763-d163-4fa2-9235-c570c858ca80', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 11).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'efc07526e4d348ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('957860ee-f9cb-4047-a5bc-14e4b280e55a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 11).', '[{"id": "A", "text": "Edge port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '114354a981d3cc10_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a1b7509-0404-49d5-90f8-449c3c1efb7e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 11).', '[{"id": "A", "text": "A physical link aggregation group", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '6ecec8f41eea93f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c706cc17-1fdb-4d34-b528-50bda4c67469', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 11).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'd1ebc02073743e51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4110c82-598c-4664-bd50-d784115f109b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 11).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '2e6667b5534349e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bcd5e38-5fdd-407c-a565-13b430e1f2c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 11).', '[{"id": "A", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65002 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '870f3df8a6377a94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bfcebd6-a34f-4a80-9eb5-f86ddac4a57c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 11).', '[{"id": "A", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Connects to the management network", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '143fc20c8e5afca4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8c04386-46d6-405b-be82-0f23dbc2b4b8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 11).', '[{"id": "A", "text": "set vlans VLAN10 interface xe-3/1/0", "is_correct": false}, {"id": "B", "text": "set switch-port access VLAN 151", "is_correct": false}, {"id": "C", "text": "set interfaces xe-3/1/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set interfaces xe-3/1/0 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '87aa54597e24ec78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8f4550f-4587-40ad-b878-6482bb07f98b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 11).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "64514 (16-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'debe4c984bad298e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc8542f9-e5ac-4b37-90c5-db4f87b1cf52', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 11).', '[{"id": "A", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '73e00586a52b5b95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57d80ff0-e071-4e33-bc0f-cdec5584734f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 11).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "56 (111000)", "is_correct": false}, {"id": "C", "text": "46 (101110)", "is_correct": true}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'acca6e008cf69598_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('455d92bd-3bf8-4898-92c7-d763235fc8f9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 11).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'ac6bba2285080109_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bcfc6db-a4ce-40db-9013-ada115b2262a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 11).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'd9d0215e6cef2265_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9de8cc6c-e9c9-42ba-af04-5bb9dc7bd78d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 11).', '[{"id": "A", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set cos rewrite dscp 46 interface et-3/0/0", "is_correct": false}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'e73be674be4762c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f35b4ccb-fe1f-48d0-943d-2bc6e2e20871', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 11).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '12c09fa5d242b647_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d18867c-614e-40a8-a4a6-2ae3cf02b344', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 11).', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Carries multicast group membership information", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '9ec11366d34984d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14893a23-bcac-4fe3-89c2-a9f92e616f76', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 11).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "1234", "is_correct": false}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'd74f626a90b7432a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62afc82c-7fed-4165-8561-6515d720f00b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 11).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "C", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'fde61d6733c0451b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7872aac7-f16b-4bc1-ba9c-1af115436dbf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 11).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '29a23dfcf3f0fcc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7761e69d-7dca-4ca4-8f82-cce41ea63708', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 11).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'dc7c7266d0032064_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f471cdd-2653-48bc-9112-17d206f29ab9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 11).', '[{"id": "A", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '76b2daff6691f429_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09085bdc-d302-4434-8882-cc9643f50227', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 11).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '21f66043778a4d72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbd48c21-5221-404d-a48b-e30e6be033e9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 11).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '8a1d5fa4a42753e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('174e53ed-a90f-4f2e-b573-80b08fcf6746', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 11).', '[{"id": "A", "text": "traceroute <destination>", "is_correct": true}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'd951110a614d6c1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a832c452-32d6-447f-be33-1978db092b6d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 11).', '[{"id": "A", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'c2c786981f1f61bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a70b764-2014-413b-858f-723db5456c35', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 11).', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "All of the above can be used", "is_correct": true}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'd2ab154eab4c8a69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cf7dc27-eaba-47f1-a01f-ec630785733d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 11).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "C", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'af60190a771937ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf03e18b-8ae5-4659-ab57-e90e6635c9ab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 11).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.43.78.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '167e4a4088693304_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7704a2bf-da99-42ad-b2a7-c357e1764a78', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 11).', '[{"id": "A", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "B", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "C", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'd2451efcbad4a3d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cf2d9db-76e8-4398-9515-2cf0baef1da7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 11).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": true}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'f465964cc29063f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('535a3d80-c9fc-4e1f-a4b9-3e1247caa754', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 11).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '8d881f373158972d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eaeea64-8c6e-45b2-b316-74d01741513a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 11).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '17e3193ea161cfcb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7944cd96-8597-41ff-91a4-ecf6322d2530', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 11).', '[{"id": "A", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "B", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "C", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "D", "text": "No BGP configuration is needed in the fabric", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'a5b32e6b5cefc170_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b203c97c-6c80-4a31-a732-e450f3c68c0e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 11).', '[{"id": "A", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '58464d3b111b4b91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d01b17fb-91a6-4f42-bcf3-6c313fbfe2ac', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 12).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "Internal Router", "is_correct": false}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '6fdb6782a3e76f02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42603f1d-dc8f-4881-9075-ff0c8c9c0704', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 12).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '136c5ef44095ab09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1d6b7c4-5f4b-4314-8b57-a525984db0c0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 12).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '724f64408f950f5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c2448b6-9b9a-42c4-8eb9-f367e95adea9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 12).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "C", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '0ab6f969798e174c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce4043e0-c907-4fe0-bdae-2fcb82a57486', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 12).', '[{"id": "A", "text": "show ospf interface", "is_correct": false}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '84ca45ca0b376db3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5464808e-99a3-4f3c-a4d5-6bda215fe441', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 12).', '[{"id": "A", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "B", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "C", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '7ca314c307d73cb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('877bd2b3-c18f-4b73-8957-8a314c8f9805', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 12).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '3c0605b0afbea53e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9dc00cbb-929a-4423-93ca-e99bb57f4710', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 12).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '83c0f9a4e0079992_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('471cf9b5-85fb-45b1-9219-fd2ed511b540', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 12).', '[{"id": "A", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "D", "text": "Hello PDU (IIH)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '2d6e21c696582a8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('003454ab-9b41-44e2-a813-110631ccf180', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 12).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '18f192753a28ddc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9aef18e5-ced6-4db4-8c16-ee070ed256ae', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 12).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'bebe375a67ebfb7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42f07778-0256-4fc8-ae9f-1f6b70418e4d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 12).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '5098257a567eb64f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1f8108f-8364-4ce9-8b01-a7032598fb96', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 12).', '[{"id": "A", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '8d996fc6a7d068a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('252be237-6a4f-42eb-8a39-4d3749a603bf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 12).', '[{"id": "A", "text": "COMMUNITY", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "ORIGIN", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '9c3240dc1e0c2ae4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0e499a7-3163-4924-8164-fb74cf74a124', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 12).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'f6de0d156c37bbcf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d230710f-7289-47f7-8198-f608fcf892d6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 12).', '[{"id": "A", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "B", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '66215909f8df7ca0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5e4b015-0e6a-4ee4-826b-7fcee027b3b3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 12).', '[{"id": "A", "text": "show bgp neighbors", "is_correct": false}, {"id": "B", "text": "show bgp summary", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '5bb9735ba5ab05c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94c4c0a6-295d-4c73-8d30-34d805977fde', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 12).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'b0aba6bd2ac4beb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff204f07-b313-4241-b7de-87fc11e69948', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 12).', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '57af6ba7a22ee37b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f055034-8d0d-4272-9d4c-cd1d24f43baf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 12).', '[{"id": "A", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'a3a8906b1088780c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42575acd-90f6-47c4-8fdb-13387f438286', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 12).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "C", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'edfc9d0463ff0503_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02955e5a-fbdd-4199-8d45-9cb8791a5745', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 12).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '73821a6b553072b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a85dd9bc-3741-4f70-ab18-9dc4687ba03e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 12).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Backup port", "is_correct": false}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Designated port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'e94c6add585d468c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41b085a0-66ac-446c-83b0-a48f85c37224', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 12).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '0a748505b4c08d6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9d790a0-f786-4b79-90e4-9d7688658f8f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 12).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show spanning-tree interface", "is_correct": true}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show stp status", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '7db69daede57ebdc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b1199f7-ed07-4cc3-b493-05c78c49f39f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 12).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '349943198eff8b96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b7c3dc2-0caf-4f92-b4ea-4c6312428288', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 12).', '[{"id": "A", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65000 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'f754665ee32c56b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd70a441-7bb3-489d-a4e9-098c9830380a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 12).', '[{"id": "A", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Connects to the management network", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'f8c201a9a64b40c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eccfa25-d6e1-4338-96cb-52786b17375b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 12).', '[{"id": "A", "text": "set vlans VLAN10 interface et-0/0/2", "is_correct": false}, {"id": "B", "text": "set interfaces et-0/0/2 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set switch-port access VLAN 363", "is_correct": false}, {"id": "D", "text": "set interfaces et-0/0/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '4a406cab89abe831_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae350446-c289-45bb-8f28-9dc7f4de7c35', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 12).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "65300 (16-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '751c529ee8b473f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fb695d5-978b-43c9-b14a-2398058eed99', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 12).', '[{"id": "A", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'ce5a97dc15e38ebd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96fd0e07-6ed6-4753-bc11-2f3ad62435bd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 12).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "56 (111000)", "is_correct": false}, {"id": "C", "text": "0 (000000)", "is_correct": false}, {"id": "D", "text": "46 (101110)", "is_correct": true}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '76b54f3d336c50ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46226218-8676-400c-a9ef-fdf90d80a8d7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 12).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'e0b5fc42b5734e80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('198d1903-4bd0-4781-9509-2586dc1bc923', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 12).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'e2261f142b1670af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4adba985-a717-493d-b27c-02380350722e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 12).', '[{"id": "A", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set cos rewrite dscp 46 interface xe-2/0/0", "is_correct": false}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '754380e1975bacb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbc8a168-3e31-4eec-a111-14732f2dd159', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 12).', '[{"id": "A", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '65acef1e287cd7ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f10caae-259f-418b-a9bb-66f37431333d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 12).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '0f256b86c318acea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cb0e25e-2913-4df3-afdc-240901fb0a96', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 12).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '398ecfced14ba023_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9086eebf-6722-41be-8d1c-3743376144d7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 12).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "C", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '96c1323340195d73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9816fa6-82cf-4fe9-aa67-b37253539f98', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 12).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "C", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '98a9ccf35458a773_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('213a0253-f917-46b2-83b6-c4d60d8775ad', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 12).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '2dc245129ada83ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('958984ac-5912-42d9-9e97-82ec528ee85d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 12).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '51ae64aa75db8b0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3dff962d-0e8c-4029-be05-dd36dcea78ff', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 12).', '[{"id": "A", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "B", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '469738a741e703b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f50280b0-1296-4466-a242-b483a1db0cab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 12).', '[{"id": "A", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "B", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '81265c67fcfcd712_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5e41e2d-d5f0-4dbd-a64d-a04ca735d237', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 12).', '[{"id": "A", "text": "traceroute <destination>", "is_correct": true}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "show route <destination> trace", "is_correct": false}, {"id": "D", "text": "ping trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '8aeb6a9bd3af602f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73d73551-6cfc-42ee-819b-f2add89a6b86', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 12).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The OSPF link-state database", "is_correct": false}, {"id": "D", "text": "The multicast forwarding cache", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'fa2ba136f2dbedb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a04667c5-4b36-4a53-9d24-2a6b836d76cb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 12).', '[{"id": "A", "text": "show route <prefix>", "is_correct": false}, {"id": "B", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '30f77e8b555d9a90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15435f24-80ea-4c84-9d88-e2e404f76a0a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 12).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Replace the interface cables", "is_correct": false}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '84686e33a52d3132_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0926d23a-a4c2-478e-b824-b39f237a07f8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 12).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "C", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.175.27.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '456c736a948f4707_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0c111b5-9e16-4338-982d-494d5e297a21', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 12).', '[{"id": "A", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "B", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "C", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '3be8a85e2c4ac250_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2063682f-63b4-4fb0-bcb2-b3dbc97575e2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 12).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'ca5ef91adb38f6b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c286e19d-a3a8-4dee-a38a-cf9034cbb1bd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 12).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '04b811cf72a70aef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dacf022-8328-4035-b997-dc40cb7d914d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 12).', '[{"id": "A", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '2b2e31bd2fd70fd9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70e9f5ff-69da-406d-ae5c-c7ca66bcfa39', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 12).', '[{"id": "A", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '09fc0e28b19d30d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57fa7da6-e54e-47c4-bd9f-07cc5137463b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 12).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'ee3260ad2457113a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af1be0b9-b4ff-4754-b232-25911cb0bcf1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 13).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '692e3be4710d3036_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f695f4e9-68d6-480d-8b9d-cda468d7f279', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 13).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '58696cc2ed13316e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58809800-ee57-4a1e-9d64-381055f8b7ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 13).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "D", "text": "Connects to external routing domains only", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '8531685ea309c874_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b1a63cb-aae1-40d3-b2ff-8f4c21fdb63c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 13).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'fbc357c8cfa1abbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4f25c6c-ac0a-446b-83e2-162104060d70', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 13).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '8144ab4a7a57913e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d725a3f3-3101-480e-8c0b-54da518de78b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 13).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '1b228fb2c9adce07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38ec7eab-dd5b-4443-a4d8-af6eadfd5694', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 13).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '2b420427a391cb7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e50b1c69-8d98-4f3d-b1ee-8b75469a5dba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 13).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '829584d59b9fd95c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0d3c3dc-5d77-476c-acab-a827ec38267a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 13).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '709afd35eeaaaab3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c3fb3ed-06f1-47f7-9abf-aceb378ffb11', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 13).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'b240430d09d7e62a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5af4af6-c9a5-4383-b28f-773d03d7c051', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 13).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'c6f5205da2901a95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ac8693e-1bdf-46ac-b9d1-607ea8a30484', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 13).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Configures the local preference value", "is_correct": false}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Sets the BGP router ID", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '90c7d0500af9bc61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cfea9f5-fcfe-458e-bdf8-2fb3079ff65c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 13).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '56e257df118a2dce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9eba0b60-c4cc-4faf-966b-7629e764e95d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 13).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "COMMUNITY", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '45399d8f5927ab00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6190f81-85dc-4826-9364-d3e91cf7e54b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 13).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The IP address of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '9aafa971fb25dc35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0349b51-f6bc-40af-a8a1-927d6fe6e99e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 13).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '91cec1a2e0998ec3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a046cd77-1cf0-4b1c-8957-2bf2dbdec26a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 13).', '[{"id": "A", "text": "show bgp neighbors", "is_correct": false}, {"id": "B", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '9c8057304c68679b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a482de8c-c95d-44d2-9d5a-374c2aa876c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 13).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "D", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '4b73d9dfb79f8c0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb77f82d-949a-4ae7-8a09-729aa138454d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 13).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "C", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '523b92bb891c71cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81b027b9-7eca-48d8-a671-5750eb50bca5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 13).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'a209d2dffb7b81ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ace7579-b426-4949-8e50-448d732a4d0b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 13).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '6dc1c2b74decede2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1117f512-b706-44d8-be5b-448e0aa7e816', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 13).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '0ce94a9802ff56ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af9a37f0-3949-4920-81c1-de4c347322d9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 13).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Designated port", "is_correct": false}, {"id": "C", "text": "Alternate port", "is_correct": true}, {"id": "D", "text": "Edge port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '2996d5cc0ae75d0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70ecc159-20f9-49a8-ae63-0d4f8a4c7d8b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 13).', '[{"id": "A", "text": "A physical link aggregation group", "is_correct": false}, {"id": "B", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "C", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'ba13687d1d3738c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('361618d1-6fc4-44ad-b1f6-250d112de940', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 13).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'e2091a85d7f9b749_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('469ed90b-92f0-4fba-9d85-4fb170e799f1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 13).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "C", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '5b7bed17c20d3a77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2c02edd-30c8-4214-8f30-0c64e6ab64c8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 13).', '[{"id": "A", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65400 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '6e05d7104e119a74_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3199490c-cfa7-4f5d-a55e-93fbb35626ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 13).', '[{"id": "A", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Provides PoE power negotiation for access ports", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '42264e134e90d9af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2f04578-bd0a-4baf-8c57-7359db33be55', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 13).', '[{"id": "A", "text": "set vlans VLAN10 interface xe-1/0/2", "is_correct": false}, {"id": "B", "text": "set interfaces xe-1/0/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set interfaces xe-1/0/2 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set switch-port access VLAN 105", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'ab63463c51a4050f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82945691-676f-471e-b617-78aa4e241df3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 13).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "65200 (16-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "1024 (10-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '39bb18012c2a35a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac48178a-7c59-4bd9-bf6b-c28a4d4830cb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 13).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '3d0a0c0b3141fa2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('166fd261-babd-4734-9fea-17757cf3240c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 13).', '[{"id": "A", "text": "56 (111000)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '9a32524677ba6500_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b406cede-f8da-4fa1-b659-3f6adfc8030d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 13).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'c9cce99cee41134a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5bdaa27-a7b0-4a34-b887-3637c1845d76', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 13).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "D", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'f6b80aeb594b2e05_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aef441b7-aa62-411b-b058-3bdbf150d691', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 13).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface ge-0/0/3", "is_correct": false}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '8c405a400c1b4f2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3b58041-e4fc-4c45-a1a0-95ee0775575e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 13).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'fd4c36b0d55f424a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3eab169b-d1df-4cca-bcae-3d25f733ca71', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 13).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '68ec138fa424d61b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97c014a0-6f55-4ea4-a671-0b15194e55dc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 13).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '986ed374bf0b5c9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68f7ba90-56cb-410c-af57-21995fa4412a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 13).', '[{"id": "A", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '740da7bc1a5d1851_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44c10aa6-9402-4836-b607-ff0a78ea0a36', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 13).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '1bb37be235f58f71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de2d3fd7-0b66-40c9-97d2-8a971e689dd8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 13).', '[{"id": "A", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '849ccafc951739b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b8f9843-8507-4b1a-b32a-ccbb0ef0b146', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 13).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '646e7d834f077f80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('720ce766-45b7-4657-a43d-c106b184ad64', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 13).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '62f9c8c850e84cbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c62171b-8e83-449e-a4b3-86bd579bd74a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 13).', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '464ce6a674edad8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b7b4356-abb0-4db7-a12e-e6d9af06e511', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 13).', '[{"id": "A", "text": "traceroute <destination>", "is_correct": true}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '1cccbbd320842167_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3710930-09a1-4f9d-8ca4-6c90013ef4e0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 13).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'c436a8f819dbffa1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0c9f51d-9206-45bc-8448-e626fc5c86a8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 13).', '[{"id": "A", "text": "show route <prefix>", "is_correct": false}, {"id": "B", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '9b418449bdc24407_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87ba95f8-ab3c-4177-95ca-8a76afcf51d4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 13).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '684e208cdfb73b33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ecdaf63-c23c-49b4-b7b5-43420e5d55c7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 13).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.82.160.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '6a7653c734ac9554_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34599bef-d41b-4ede-a897-9c204e2e632a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 13).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Defines user netadmin permissions to the device", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'c5b2c8697005830b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b57930f5-fda4-41aa-a84e-0fc9e367520e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 13).', '[{"id": "A", "text": "silent-drop", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "deny", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'f8018e33190cde1e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('033d0dcf-c26c-492b-b329-b277aae28bc8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 13).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '95d58777fdd9b600_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe2b5cea-9826-4c8e-b2f0-a0adb8c22f85', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 13).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'c3a9a5a3dd0077fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06de7653-f80f-4a73-baf3-eb8b240511b6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 13).', '[{"id": "A", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "B", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'c0305f8d97d1a36f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78cdf953-e78b-4dc8-bb06-c4dd183c39f8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 13).', '[{"id": "A", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "BGP on loopback interfaces between the switches", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '0e7c480f166e0afa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('853e34cb-80e5-455f-b571-fa85ee948aae', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 14).', '[{"id": "A", "text": "Backbone Router", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '79f12f0593cc6ff9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea12b0b6-8f02-4761-b812-5f0309e7d2fa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 14).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'dcd2fcc3c9a9cbde_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2775f5e9-e980-4dd9-8738-2e4c75f908af', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 14).', '[{"id": "A", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '22663d51d19511a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cae0c26-2a68-49b2-8f9e-44ef4a305e5c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 14).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '085ca0c32ba1fcd7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43f32257-e906-49af-84cb-b33b3d66301f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 14).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'e9c473edaa97dcf2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c1a3482-80f6-47d4-9b33-0923aff8c2fb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 14).', '[{"id": "A", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "B", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "C", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '66e583a92385f21e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9de9dc6a-df40-413e-ba0a-16c0bf9fa295', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 14).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'f7c0450169ac7102_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afe5e2ea-9e48-486c-8da3-ddb04c1859ea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 14).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "C", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'd643cb9cbd060f6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('730f36eb-419b-4241-90c4-57da9f6b45ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 14).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'df58338f1e177a5e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25854591-4d37-4806-a5c4-5c5ba8bfc3e4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 14).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '0adf84a4c9b7f05f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aae47b9b-49d9-4c67-a31d-202e19ecdf3e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 14).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'cd5fce91eb7bceeb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('954d6a24-67c6-409d-8c3e-392de4c8b1f7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 14).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'bcdcd4b3be7a50f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd0bcd9f-ebbb-4d00-a909-8712da4b7712', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 14).', '[{"id": "A", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '1d4238c075e11265_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12f44cbb-ac76-491e-86da-883bab8b1fba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 14).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '13a54574a7d22bc8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd049090-69ec-4d92-8956-ffe0d12772a3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 14).', '[{"id": "A", "text": "The AS of the route reflector", "is_correct": false}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'f99660468f57cf86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c9cb138-275f-4085-9912-7007363e6cd7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 14).', '[{"id": "A", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '4310933d5ff2a139_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6a2b04c-502a-4459-847b-0632c26e5388', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 14).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show bgp neighbors", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '27414b215e8043be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23daf3e6-8fc1-40e6-99d0-5346902ddb95', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 14).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '43647923fe7dfea6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cde8a4d9-393a-4d81-b95e-d69fafcdbe14', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 14).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "C", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'd48a01a792a6d0b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce3bb80b-43da-4203-823c-dfa52e4db3e0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 14).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '496994e896aa8ff5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c555dfd4-8724-4a66-b8c8-f02b213fff90', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 14).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '580c363fbb8ae84f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad7a3ab7-9933-4c9f-bde3-15dd910a718c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 14).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '66189c6f8221def1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99b98580-ccce-433e-a1a1-3b658915c77a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 14).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Backup port", "is_correct": false}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Edge port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'f72e5815fa034911_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('857365e1-0f78-4625-85c1-8a2f774b2bfc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 14).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A physical link aggregation group", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'f6018d66c5d31dc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4fd69e97-7734-4741-b3f6-03edc84e2d55', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 14).', '[{"id": "A", "text": "show spanning-tree interface", "is_correct": true}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '21af7b93aa34f488_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('178e9b9a-0f45-4241-835f-9f33020584b8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 14).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '590d87ed2a70dde4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2334b850-a984-491b-ad94-9465b5e8067d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 14).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65200 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'e31c4741f0797f73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d38614c9-03c1-4529-83e2-04a967c3aed0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 14).', '[{"id": "A", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Connects to the management network", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '79f405e8254c23ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe995bc2-5aa0-41d5-a85d-bce610f98f29', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 14).', '[{"id": "A", "text": "set interfaces ge-2/1/1 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set vlans VLAN10 interface ge-2/1/1", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/1/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set switch-port access VLAN 288", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'd57d230990c8b363_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71d4bc9f-24cd-4235-8ffd-c15f4ca20e52', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 14).', '[{"id": "A", "text": "64512 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '06e79708b03df14a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f40b764-dff3-4e14-9c20-e136b6d7eb2f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 14).', '[{"id": "A", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "D", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'a6762d7f657932cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e42c30ea-3614-4b3f-85a3-95cff2577fba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 14).', '[{"id": "A", "text": "56 (111000)", "is_correct": false}, {"id": "B", "text": "26 (011010)", "is_correct": false}, {"id": "C", "text": "46 (101110)", "is_correct": true}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '90f217f373ca0b35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b498c0b8-e034-4f14-af69-5777d757ca11', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 14).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '05367d592dcb96b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('598d6180-2796-4153-8c95-ff23c1f3e44d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 14).', '[{"id": "A", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "B", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "C", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "D", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '3e8083724588d779_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f89330bc-7b83-40e7-a61d-89a96874cc03', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 14).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set cos rewrite dscp 46 interface ge-1/1/0", "is_correct": false}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'd3c26165481b1dbc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53246d37-9b45-4540-a816-e04518606493', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 14).', '[{"id": "A", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "B", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "C", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'a239fab3bfb6d090_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b53d5927-62ca-45f2-bd50-a3ec2afb3fa2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 14).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '38fa0577b315ca62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8b8374d-3642-426f-977a-c5fcc4f91e5a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 14).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "8472", "is_correct": false}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'a41bcc9e41d66123_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efef2ef9-027b-4d74-8444-207683ea4917', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 14).', '[{"id": "A", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '48d6a4df4be956ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a87188a-b43c-4df7-8438-88299bce3af5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 14).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '215b8f2f80fdb5f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61499e84-ca93-4ed3-a032-b113a46f7a04', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 14).', '[{"id": "A", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "B", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'ce29ee7d0ce57806_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11aaac21-5781-4adb-a4ac-1c97058b5666', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 14).', '[{"id": "A", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'b1e5e9b8ec5aa919_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0556323f-bb6d-42b4-ba18-950863e2b877', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 14).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '629f517ec8f7d6a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c11590f-e059-426e-b522-6132bfe96f50', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 14).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '1d501e4d91836257_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89e4a628-780c-4cec-90bc-40396833480f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 14).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '30a27228ab0e17ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e204c562-72c4-4be8-b668-2a23753b4232', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 14).', '[{"id": "A", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '04a9783cc3f327a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5b5daa7-21e3-430e-b6ab-e912a29e5afd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 14).', '[{"id": "A", "text": "show route <prefix>", "is_correct": false}, {"id": "B", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "C", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "D", "text": "All of the above can be used", "is_correct": true}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '01e0f2b97965772a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8b2faa1-3112-4a23-8684-e4cdfdf73964', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 14).', '[{"id": "A", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "B", "text": "Replace the interface cables", "is_correct": false}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '020c8b040314b747_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a2be4a8-e787-4447-b5f3-0c552e07ab12', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 14).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.202.59.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '3f5f7fbe77c7b076_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97889eac-a584-4f1d-9839-f1944773306f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 14).', '[{"id": "A", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "B", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines firewall rules for packet filtering", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'c8b323487d39a63d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20d9769b-7c66-49d3-8348-8d8eec3f5ce7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 14).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "discard", "is_correct": true}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '30e6645ead36dd6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25f25fe2-8d1c-4106-8fbd-b9976da4a2aa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 14).', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '8bac8a7d8012e479_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bcc815c-5037-4294-8bf5-c2e98b34716f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 14).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Single switch acting as both core and distribution", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '2981d3c95f464db4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2df834fe-4d68-4d57-a7ea-88c5c084d7e1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 14).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'f570ec9af9505720_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87ee6c37-092b-4bb0-beae-e06e108bdd90', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 14).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '55aada1c5cc1f165_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d53173d7-9859-491b-8e14-da547605be0f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 15).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "ABR", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '831abe69511c37e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef4da3e4-b50c-4672-bb91-e62ef0f54073', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 15).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "30 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'eb53412b75199715_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ef5b08f-59de-4e59-b615-7f77fd6a5c8a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 15).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'ea2edf722164d4d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20bf4d8e-5e5f-49bd-afd3-fc9aab573e6f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 15).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '1422cf25e455f667_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a793ba6-1f69-4f88-b782-c5d8e2a74a05', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 15).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '880cf561279b0af0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41e1ef83-15ff-41b7-977a-765a0e3ad080', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 15).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '070fab89b07cb4d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e72b2171-2c33-4aa2-a38a-14521549f9f3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 15).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '4fe503ee43133d16_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef1f2968-e03d-46cf-901e-c090d37201fe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 15).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "C", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '88c8199075ccc64a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b6bb340-0318-4358-add5-b4804e79b411', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 15).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'f62554fd7a5bfa41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95a6e1e5-3350-48af-b795-d46b132c7820', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 15).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "B", "text": "AS_PATH", "is_correct": false}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '9eb66ba298d435a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f074f253-8677-4bd5-adc1-a9f3979934ef', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 15).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'bf049b659e907d26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2604bbb-beb8-4a6b-a2c7-b1c49330f341', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 15).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '110e44f78b8b8c07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd088b7b-0178-4a55-85c8-29e96326e1f5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 15).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '9a526ac267d1257c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1811b41e-c740-423e-8e20-5b361daf189c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 15).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '195882e1fbc15790_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb04fc66-f5ae-4439-b3cf-49976a913a37', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 15).', '[{"id": "A", "text": "The AS of the route reflector", "is_correct": false}, {"id": "B", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "C", "text": "The group of route reflector clients", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '938957fd99a119fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a20e296e-a464-4e4b-9e95-b7fccc65d533', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 15).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'aed8f977bc38dc84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca7d3f13-15d6-418c-801f-ca54a06008af', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 15).', '[{"id": "A", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "B", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "C", "text": "show bgp summary", "is_correct": false}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '424f168283fa553c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('670fdbcc-f2a8-4d8a-9a2f-8bdeabe6fcb9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 15).', '[{"id": "A", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '36a5df6415ec9385_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5684d9ba-c1cd-4103-88c9-414980498226', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 15).', '[{"id": "A", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '2d4b6b11de358f7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38ad95dc-5670-41c7-a7b3-67cb34f3c0f3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 15).', '[{"id": "A", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'e0e73111d9a6b0a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8439c89a-9fc4-48e4-b721-0df5f025663a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 15).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "C", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'b3a6fab804533125_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75eadc67-672d-4839-b534-bfa46af1d999', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 15).', '[{"id": "A", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '5a2c1081e9a590d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('945bf019-b9b7-423c-9be8-3f9876a96fdf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 15).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Edge port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'f6fac9495ef03f10_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eec05571-46df-4f23-b003-fef75a070ebe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 15).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'b65b5bf9406cb2a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff9bbbe3-5081-4329-8f5e-23a2e05d3160', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 15).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'bce1687e3e4ed1d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92ff8cf5-1091-41c6-9d4d-3a88eaa25e4b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 15).', '[{"id": "A", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'b9c6c1b580606f72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3683256f-35ee-4168-ba4d-e5371bba3340', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 15).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64600 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '02f75bc12b7e3df7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9c54c41-39f9-400a-a372-f33dba405c7c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 15).', '[{"id": "A", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '8c5b4db0b47953d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67efbbca-acdc-4c0d-a0a6-d4d6b5ae9389', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 15).', '[{"id": "A", "text": "set vlans VLAN10 interface xe-2/0/1", "is_correct": false}, {"id": "B", "text": "set interfaces xe-2/0/1 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set switch-port access VLAN 152", "is_correct": false}, {"id": "D", "text": "set interfaces xe-2/0/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '15dd564d6699a8e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8dd9eedb-2d7b-45c8-8ce5-0ea80cd1a381', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 15).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "65500 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'e44cca8d894ea245_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('976a88a8-0abd-4a30-a4d1-c0477798f25e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 15).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'b24b8ae2c3fbdb91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33e90df2-b080-4c4f-8a49-facbde28df7b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 15).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '7dd65c8dfb4e5622_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('975d916e-432d-4de6-a4d2-8197302f7b10', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 15).', '[{"id": "A", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "B", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '192567ee99a88f81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('227d2f9d-ed52-44c8-aa87-06c14ea72463', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 15).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "D", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'e5899040d38240d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1506582e-f0f1-48b0-806f-c01a64b97879', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 15).', '[{"id": "A", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set cos rewrite dscp 46 interface ge-2/1/3", "is_correct": false}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '182dc07bd293d5d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('689ea5f8-344b-4d59-8fb9-32246ad5b293', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 15).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'dc5b91c223975f63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63ffd166-cd6d-479f-a7c0-9ac4792b128c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 15).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '33250f49cc3f10e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41d2d9ef-7858-4373-b4ba-0fe188715b07', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 15).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "8472", "is_correct": false}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'b7541270bfbb895d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('766b1615-a72d-4017-85f2-3da613318308', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 15).', '[{"id": "A", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "B", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "C", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "D", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'ed525de6d03afb31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8819c3d-2b19-4e70-a13e-e75d38bd243b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 15).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'c5f3c7b4b49d275a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ad651f2-c8f0-4c7d-8867-e73a727fd3a3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 15).', '[{"id": "A", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'afb101880feb394c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d212b98-5760-44e4-8153-51712d5fae0c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 15).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "Each host is configured with multiple default gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '7f7db4090368fac5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5ee5424-eb8d-4cbe-92df-d3b107937fbd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 15).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '9eede2eaf23504d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('797f6bea-dcce-45aa-bd08-988bf97d5765', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 15).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'd71ccaf16cc2ae6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afd6ac95-c619-4df7-a251-866bce2c40b6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 15).', '[{"id": "A", "text": "show route <destination> trace", "is_correct": false}, {"id": "B", "text": "ping trace <destination>", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '10ece5f9e2d4c1c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3e004ff-275d-4087-a32e-c73955f0c39b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 15).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The multicast forwarding cache", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '8ce5df902cfc22ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('410fc61d-b294-45e6-91f6-e7669bf6739f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 15).', '[{"id": "A", "text": "show route <prefix>", "is_correct": false}, {"id": "B", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "C", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "D", "text": "All of the above can be used", "is_correct": true}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '10beda648214783a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58f494e3-38dc-47e5-87fa-a58e6dc827ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 15).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "C", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'c743b2f56675b55c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fcd3e86-9c02-45e1-b8e4-58aaf3f66f16', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 15).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.253.43.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '040f030b27aa7270_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47edb21c-13d9-4f6c-8d74-38938a62aeeb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 15).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'ccaf1dd0b9674ea0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a2de41a-76cb-4e2a-a6b5-9cde11c794a0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 15).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "deny", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '50388e5ba730791d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72caf4b4-cd08-4de0-8077-efcc8140be14', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 15).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '6bf3e6630fabecee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abba3f6e-8bfc-4b98-b532-4ef17e4804fc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 15).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '7e5dade194a29187_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f0b5f6e-c44d-4c8d-bfdf-209f326e942f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 15).', '[{"id": "A", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'c61f7ad391ac58d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b81af22-2db5-43fe-a337-f6d606dc5be4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 15).', '[{"id": "A", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '784e8c6f45fffea6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd557592-ca60-4795-a4f2-8739a21a2980', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 16).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'e84870c79145d82b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35e93515-7de6-492e-9221-a15f54791452', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 16).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "40 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '7d876f46bb69bfd0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fac030f6-af00-4606-b7f0-506828d358d4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 16).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '3d467de243485056_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f693c1b-e59b-49cc-9c62-123dc130023e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 16).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "C", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "D", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'ef411bcc9a1e6292_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fdaacf0-9b0f-4584-90ce-5b783362d7cd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 16).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '9c764a481670f218_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ef3d0c1-c809-4e42-b32b-f5481100e87a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 16).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'c0827bb56b7df8a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('628f4127-ee5a-419f-8adc-12856a389115', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 16).', '[{"id": "A", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '87d6fcbce8eeced0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d825cb9-ed1a-4696-a9e7-8457334fac00', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 16).', '[{"id": "A", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'c491f547767e5a3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('486e7121-51b6-4980-a0e6-19a61fd05686', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 16).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "C", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '000656aaee419318_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('143e6d0a-a1a6-4325-bac9-1eec5fa861b3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 16).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '0e3373c47ec5a4b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('374e753d-a34b-496d-9b87-a9866cb3c67b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 16).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'ef239d9ac7bddaa4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5655efdd-da6f-4bd3-87cc-c1a183e4e166', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 16).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Sets the BGP router ID", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '48d768101bde5524_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebcfa754-4603-474b-91e0-82d3e10e90d4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 16).', '[{"id": "A", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '3384f31e6a522bed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('319b6d1d-3dab-46df-8616-a2b3d1c67dbd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 16).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'c1fd790bc03fd27a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31b94a5f-4dae-43cc-be16-30291fccbe4f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 16).', '[{"id": "A", "text": "The AS of the route reflector", "is_correct": false}, {"id": "B", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'cee7c938f15d7292_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a63f3811-e8ec-4f1d-971c-1d562ef4f977', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 16).', '[{"id": "A", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "B", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'c33ed2e053fcb02c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dde2699-0969-4b5f-82ca-8ffef9966d07', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 16).', '[{"id": "A", "text": "show bgp neighbors", "is_correct": false}, {"id": "B", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '72d96a38f460f835_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5487490-5803-496d-8fa2-34cf945da7bf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 16).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "D", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '4f7e12826ab2d388_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bda70cf7-361a-4abe-8722-334b6f3474d4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 16).', '[{"id": "A", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '1bbe5bd092e9dc34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5f63ce4-441d-4914-97f9-d5eb8e03478d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 16).', '[{"id": "A", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '5b1ccd0d2ac1df6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60cf43df-481c-4943-860f-c00d0d4a4d21', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 16).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '6d8451011e400b53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('692f8ef0-aff0-4d9f-bfab-c8f7895552a8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 16).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '53da0d1d8b022c0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('173a81c0-651e-4bac-84ef-4c22f9b082d0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 16).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'c582065fc87651f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99d790b0-d0fd-41e2-86f6-95b525312209', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 16).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '7e768cc66f0d2076_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3c916d8-5d86-4f40-bdc2-6666e12cf84c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 16).', '[{"id": "A", "text": "show spanning-tree interface", "is_correct": true}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show stp status", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '21ccc2d6738e892a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0ad937a-86dc-4161-8b08-f676f3c1669a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 16).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '8ed09cbfbd7786d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a61de79-a3f9-46a9-b34e-7eddb4be1843', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 16).', '[{"id": "A", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65300 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'b18c92657ecc02f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b14cacf-d6bc-4145-baa2-bec0c860fa55', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 16).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Connects to the management network", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '21ba08d43a512f35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b447a28-5177-4799-b0ce-2195615b19f8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 16).', '[{"id": "A", "text": "set interfaces ge-1/0/2 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set interfaces ge-1/0/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set vlans VLAN10 interface ge-1/0/2", "is_correct": false}, {"id": "D", "text": "set switch-port access VLAN 289", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '190a5753ad4a0c8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2eb854a8-99c0-483f-bf3b-7f290623171a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 16).', '[{"id": "A", "text": "64520 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'c33b1cd18706f245_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('761cea26-9eb6-4cf4-9a8c-1ab95078d271', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 16).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '0e984e8700bdaf7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ede4180f-da77-4c01-be1b-6ccfb9c4fda2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 16).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "26 (011010)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "46 (101110)", "is_correct": true}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'ce70f9261c102325_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d0ca68c-be5d-4d2e-9959-121c079003e0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 16).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'c43e878491bb9775_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a69a57b1-1401-472c-86a4-ae92124177de', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 16).', '[{"id": "A", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "B", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '87ca5139ef9096be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0fef681-bd8a-4733-ba02-c8a712b611e6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 16).', '[{"id": "A", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "B", "text": "set cos rewrite dscp 46 interface et-3/1/0", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'd6e8015972f4b2de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c79578d0-e433-4cb6-8146-c51a38b9c7cf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 16).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '252241f15dbcbff0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32d61505-ad61-4c4f-ae4f-d731717403ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 16).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '5f9443560890ea04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9814e0a9-6abf-46aa-a7be-0b7c9b52907d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 16).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'dca29b3041e42f7a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87e226f3-c51b-40d9-9926-4bdeca5d1ce3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 16).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "C", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "D", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '677f09cc57a08cf7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1dfa60f6-7175-4539-8562-3f79aab58197', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 16).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'bc7074ba7faf5eb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1a374a0-3daf-4ace-9f17-29a397549077', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 16).', '[{"id": "A", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '044c78b8b31c522c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f091a44-af5e-4cd5-bdbe-f4d11ff01809', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 16).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "C", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "D", "text": "Each host is configured with multiple default gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '92cb2f089523d47a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c865cbd-f31f-43a2-91a6-db46458430a9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 16).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '8f58a95fbb854315_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddebf1f6-0a8c-41f9-a0ca-ef13f3b10c31', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 16).', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'ad9b08f8888b98bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0a963d1-39b9-4487-9704-f796fd14875a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 16).', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '0c5e7628ee28f5de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48b7a51c-29f1-49c3-8179-388eb31fc9e1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 16).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '02f41de6429b3c1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc42fd99-23cd-4350-ac53-1af67479d64e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 16).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '86aa559116d46106_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edd70c1e-baad-49dd-b5f5-63476b410107', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 16).', '[{"id": "A", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '9c05a497f012a2d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('953e9474-4cd1-4074-bedf-1f8af1dd4dfc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 16).', '[{"id": "A", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "D", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.131.0.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '5aa070b1fcdbcf22_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d7be2f0-e272-4ed9-aa3f-b6983f027686', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 16).', '[{"id": "A", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Defines user tech permissions to the device", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '743ddb0a40500257_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2c89e48-f1b5-44b7-be3c-19054599cce7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 16).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '112fc4144e52d9fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd56b1ba-4579-442b-b849-1a53067e3f94', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 16).', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '01de671a048327dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7715acc9-ae15-4aa4-857c-43f76b7e9a2f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 16).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '2dafb55dad5f5d7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c981a4c7-17f7-4ffb-a399-dfd6c09c1919', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 16).', '[{"id": "A", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "D", "text": "No BGP configuration is needed in the fabric", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '22fead36baa366b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c00a4d12-d774-49d9-a17e-aa460e5816d7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 16).', '[{"id": "A", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "B", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "C", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "D", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '86ec5a61b3f81b84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8609c119-748b-42a1-ae83-abd7b26fcd61', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 17).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'e49876a7a95ac546_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28fa6f89-28f5-4590-b73b-19e029028329', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 17).', '[{"id": "A", "text": "120 seconds", "is_correct": false}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "30 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '1bc2a05781fadb5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23780767-53ca-4ed0-898a-219642504726', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 17).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Connects to external routing domains only", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'db9c7e80ad726b49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a1d6cd8-605f-4ef6-af09-76065d2cb28c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 17).', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'b826847e1b34a2b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43055861-2280-4508-a3ba-ab8d8c874f25', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 17).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show ospf neighbor detail", "is_correct": true}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '178112d7536cb967_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a99a7d83-fd54-4f06-afe4-a6b8b41d2338', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 17).', '[{"id": "A", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "D", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'b93b9b222e638e73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08f17538-8508-4b99-8fbd-1659ab711eab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 17).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'f3843556debfe469_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f68713e9-b252-45d8-abf2-8831a0677f59', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 17).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'f8cce6147c6e2888_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bb6c96e-9c0e-46cd-853b-1a935cf33a92', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 17).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'a40b2f6403c0f169_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53f0e89e-75a4-44c0-99a3-ad552de9c7ea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 17).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '92433547d164f6a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10292a5f-f9a3-4299-8c07-a8d22eb0a9e1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 17).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'f6aca4dcd6eb10d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3acaa17a-dcf4-43b4-b5e4-30ab069d840f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 17).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '38f38b683700c1a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd63e08d-f500-40ec-be86-f47a01457d4c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 17).', '[{"id": "A", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "B", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "C", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'ac9797dac7a861cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('992b4640-98f0-46a9-a4f1-096239408d6a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 17).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '39c0d9f20dfa9a97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74075b1e-c13b-44ce-b320-511f17d0bc7c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 17).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '01a85f92e571e078_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50caccb5-8887-4c03-aa33-da29da51d9bb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 17).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'f2085686e53ab02c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('729d13c7-86d3-457a-9609-14bbc8194249', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 17).', '[{"id": "A", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "B", "text": "show bgp summary", "is_correct": false}, {"id": "C", "text": "show bgp neighbors", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'dd11f36cd40e0ec6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff08250e-eee6-4bdb-9ccd-e77d1fb2b70b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 17).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "C", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "D", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '3e5655eebc57a5a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0c4aecd-cfb3-4dc3-9c84-7edac9cb5ee0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 17).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "C", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '403850a4bb6f5bba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d7e95d8-ff2e-4677-b75c-3e9344852b73', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 17).', '[{"id": "A", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '4516bc16050f6870_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c3e3ea2-1e04-432f-96b6-d829a7174cec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 17).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "D", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'ae4c3fb925f0bce4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('432f5f20-cb84-4787-bfe3-c9d9506bd2bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 17).', '[{"id": "A", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '1b6082a28d8e78f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('102c7379-b2ef-43e3-841e-4bb29903aa20', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 17).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Backup port", "is_correct": false}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Alternate port", "is_correct": true}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'fb196e10f72eab73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fe72178-6b0e-410b-a5b2-590ef240b969', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 17).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A physical link aggregation group", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '125f5bf4899dd173_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9c06561-3c9d-4a64-9d0e-71192852794d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 17).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show stp status", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'ae928eb3999d11bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9768c4e-3adf-49aa-9f80-cadcccece25a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 17).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'e088038cea708eba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4919529f-0c80-4801-804b-3ebad7941eb1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 17).', '[{"id": "A", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64515 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'f752ba9b859eb1c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cddb5ed-3690-49ad-948f-8471ce502bfb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 17).', '[{"id": "A", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Connects to the management network", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '24e0fa5079b6294f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33679d35-304c-4ca6-bde1-90d6f3565d80', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 17).', '[{"id": "A", "text": "set vlans VLAN10 interface et-2/1/0", "is_correct": false}, {"id": "B", "text": "set interfaces et-2/1/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set switch-port access VLAN 390", "is_correct": false}, {"id": "D", "text": "set interfaces et-2/1/0 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'ccfa237b816c1585_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1525a3ac-4103-4123-9810-44d0bf4d108f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 17).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "64520 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'd1826c0f3e4e4fac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d469d642-3e16-40b5-9962-c931b23b7d6c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 17).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '31d5c22bfa972b6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('640373f1-04cb-4501-aede-bbb3fe1c1afa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 17).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'b6902e0d3feb7f2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f666327c-670d-4a3f-8060-b240f5507c7d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 17).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '3b405a0f1118d16c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f4570dd-2c73-4f18-b7b2-004af85e071b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 17).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '00c0f9e4a6956078_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3647b78-6df0-48c4-b467-4861a34ff5d7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 17).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface et-0/1/3", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'd76a9c0178cd41f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('449cd944-7ad3-4ad7-8a7e-7c4acb913281', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 17).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '42a8272e6b994750_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03eac4b7-69ec-4619-a193-04d750e2a3ce', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 17).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '5765d66e15951223_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('248bacd9-a1bd-432f-b6ce-9ab85453dc74', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 17).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "4789", "is_correct": true}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '0f3f07921f79460a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31592224-4ce5-433f-8dad-92a35aef8004', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 17).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '5d622d6123f5ae61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11dfd2c9-5397-447c-a5bf-b6b63e5154a8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 17).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "D", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'aeaae379c67c7714_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d6df8e6-b9f7-4232-a543-d0447e4f732e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 17).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'b02c732a9465c3ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4242f499-5b84-49ee-937f-78f3826308ab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 17).', '[{"id": "A", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '550e73e5e80198cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('110d3892-90a2-44ed-a9ba-0cbefe32ff6a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 17).', '[{"id": "A", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "B", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "C", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '9dad09ba442512cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd4d50d5-9159-4af3-b782-8286d850b3ab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 17).', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '12070a35b6671c05_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a93da225-e14a-4a18-9c5a-eb57a93b461b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 17).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '1fbaa1454679e616_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d511c102-055b-4683-8246-8c6850c270ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 17).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The OSPF link-state database", "is_correct": false}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The multicast forwarding cache", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'dea5de717918ce8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1deeab68-c4da-4e3c-8356-93c00eae896c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 17).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '475897650c0f3b2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16882bb1-f070-4426-8dce-1ae7f7b39d94', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 17).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'c9f9f94e417b23e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cea8284a-1c8f-4342-a272-69c2b0417544', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 17).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.217.197.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '12299aba491db672_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d22df951-1f53-47d9-b687-90850e1d81a4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 17).', '[{"id": "A", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines user netadmin permissions to the device", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'ca57e28539c89b43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1dee6877-fa54-40e6-9997-1e5f650d5a9e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 17).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "deny", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '59fbc3af262a4667_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f06bd16-3ea5-4e76-9d8c-dbd1a4df62be', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 17).', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'ee85bcfa296d7834_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('662b6325-f94d-49e1-90c5-378ee0c0d02b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 17).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "D", "text": "Single switch acting as both core and distribution", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'a79495f96c300716_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31192034-ce03-4b71-93bc-e961ba8687c6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 17).', '[{"id": "A", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "B", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "C", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "D", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '6718e350a9dbc098_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('821c3d81-a919-42ce-9976-5a2c16dc39d8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 17).', '[{"id": "A", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '34e02fc782a84743_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c4b56ff-4daa-4138-8960-264ab0476756', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 18).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '6d88c486d7e8e661_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd374bb5-e683-4092-ade5-7c63e56c18aa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 18).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "10 seconds", "is_correct": true}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "40 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'e8c575811586e804_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97aac3ff-0b48-4be4-8c8e-8e87023410b3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 18).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '9c10f6791d033791_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ad1a74d-baa4-4cba-85df-08d0fd5ae52b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 18).', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '8f90d32218237f65_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df2bcfe5-c197-4082-8f9f-44d28bf6e853', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 18).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'ea9cf45e30255c16_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ea229eb-e7c3-4f8d-900c-97f6991f1c60', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 18).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "D", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '5bbcab7112a216ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d9c8e95-0f3b-4e42-96d7-91bd4fabb474', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 18).', '[{"id": "A", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '97246695716adff0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76a40902-0b9d-47f4-89a7-1f2db3034990', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 18).', '[{"id": "A", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '7ba542c8e2a60649_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b863a74e-26b3-4831-aff1-01e63d60da78', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 18).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '9bbfb7872a2625d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('442cee06-2ff3-4803-8f01-c9ff7475cf18', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 18).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "AS_PATH", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '9c5749b8de54979f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e18665c9-5a63-4478-b399-96df390f9111', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 18).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "64", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'b5362193b4918a85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('981df3e1-a71f-4247-aa1f-2affa0debb25', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 18).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Configures the local preference value", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'bcac1649c87541d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bd3cbba-b6c8-4914-a59f-652c34834c51', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 18).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '0c8bc360aac537f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4fdb609b-2192-429e-bfa6-8ca12806d220', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 18).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '774fa1ca5a6e8db7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6feb4ae6-6ef9-4ff7-b8dc-d6c57f1d664f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 18).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "C", "text": "The group of route reflector clients", "is_correct": false}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'b2747d64b8819daf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee21d3e1-5e0b-4c3f-acae-521c2f50a384', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 18).', '[{"id": "A", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'eace2abb34acbf83_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bb0c9b1-b775-40c6-ac69-3bddc46d78df', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 18).', '[{"id": "A", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show bgp summary", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'fb4e4734a2459634_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3575f453-d5d4-41d8-a068-71ed5f6d534a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 18).', '[{"id": "A", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '20a3148dbea500e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c64378e2-cd05-4e1e-be35-bf21991cd92d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 18).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'ca08e74729da9d92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38319623-dc7a-4f9e-969f-7a33a6e8f991', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 18).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "D", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '436b8ec209c7635e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('899d2581-2302-44b1-a4eb-2d1b4c42223c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 18).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "C", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '1acbdf31ad9a2d95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1db6f630-fe8e-4f9d-a853-e1476bc8c14d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 18).', '[{"id": "A", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'e535bb1fc70619d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e8889f9-59ea-4833-9fe8-072033728eef', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 18).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Designated port", "is_correct": false}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'f141eb61b8088018_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af92a690-4f57-42cd-a58b-32a251d4a286', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 18).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'e87e6aab305371fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4aba856-0028-4bb6-8410-ba94681de632', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 18).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show bridge stp", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '1e327677a4913344_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7aa5dc90-8709-40fa-9b33-455e907aca04', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 18).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'd1d8bda4292532de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0480422a-2b88-4351-a5b2-7dbaf1e8f962', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 18).', '[{"id": "A", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64513 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '2f4f4e2a71d5c294_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('919a9bd6-1d4c-482b-bb61-f624d9089969', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 18).', '[{"id": "A", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Provides PoE power negotiation for access ports", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '40f8111e6f8aa8c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a874b26f-c741-46ab-856d-b28e0efc949c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 18).', '[{"id": "A", "text": "set vlans VLAN10 interface ge-2/1/3", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/3 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set switch-port access VLAN 180", "is_correct": false}, {"id": "D", "text": "set interfaces ge-2/1/3 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'a8e833cace41c06e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8e97c47-b7ae-4682-97a4-5b21d48e2d90', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 18).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "64800 (16-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'c74e9e5ca188f422_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef8975e5-bc82-4969-aaff-330bd3cf6f34', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 18).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'd5aafd92446fb325_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a86247ba-5f44-46ad-9bad-8a42adca95f5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 18).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "46 (101110)", "is_correct": true}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '128c1b35eca269ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2b3033b-cfdc-4634-8ccc-7d3db95cd75a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 18).', '[{"id": "A", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '9e98160becfbbc5e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea9dd421-0ee5-4d63-ba4a-e6f0fa3748d9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 18).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '4618143c370c865b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4507e027-c472-4bb6-84de-ccc6cb39725e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 18).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface ge-1/1/3", "is_correct": false}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'e5a505817b53cd2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbe83243-5227-4a21-961a-24eb24c535b8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 18).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '85ac3688f35961cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fccf53b6-3663-4a7a-acff-2f4246772797', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 18).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'b97aa8dfb9a6436f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc182b78-50c5-49a3-810c-e304ad13d512', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 18).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'c14c6813bbdf8cb2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa77b596-3462-42bc-bf6d-6d119d487dea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 18).', '[{"id": "A", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '920f6aab53583759_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('512ceb67-2913-4ee3-a13c-9ae69a3e764e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 18).', '[{"id": "A", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '8b764c179c45b0fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b21b3ffd-66ae-470c-92ef-a8880042a76d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 18).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '603090731f8f0c0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f09c335-127e-428d-b557-5e08f1726b6f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 18).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "Each host is configured with multiple default gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '4fbea77addc75bfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06c48687-0eaf-4f76-8153-1797567ce1b4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 18).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'f8528666e5d9eec5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6e48c7e-9b87-4a42-b418-6bcea0b2c73b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 18).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '3381e1349d548156_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a142d56d-92d1-4a35-bdb2-05b83caa98ad', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 18).', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "ping trace <destination>", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '242dc86f1f1f2185_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b89e64cb-1241-46dc-b38c-e5e1b17671c5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 18).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'c8ee550a331ed88a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('748809b1-d43b-43d0-abb2-ac91f6048dfa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 18).', '[{"id": "A", "text": "show route <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "show route table inet.0 <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '85ccbefe40071c52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab8503c3-3edd-48c3-899e-831ae8b5ccc1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 18).', '[{"id": "A", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'fa4689918fe2bcf8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c055eac4-b2e3-4642-a3c0-38e76daad93a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 18).', '[{"id": "A", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.135.72.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'ed23e9c071f21cf7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('caf0406b-bc14-4af4-abee-5c6243d01e1f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 18).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines user netadmin permissions to the device", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'b4c02a1c552db199_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70a9565f-cd51-448d-9b58-4962de16c032', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 18).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'ea9014dc12c05f8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a73c3710-d138-4caf-a676-b3473cd1386f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 18).', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'f97c4334f2f21429_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d24e7bd6-22aa-4c4d-970e-c1244d8da241', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 18).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'b29fe2a21eb57c8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7e67df3-342f-44f0-93c2-99d630717449', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 18).', '[{"id": "A", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '75ffa59e97e00f70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a97ae082-bb22-4da1-a58a-0255b74e00a2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 18).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'fa9d466c24fc66cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('418f6571-539e-4915-b3f4-f44dbd37ebe3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 19).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '2024bfa05a2ec39d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce9b2b4b-d572-4a80-9672-ad2860432a40', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 19).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "10 seconds", "is_correct": true}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '180f5fc3fea79ac2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5549f13-d352-4545-bfb9-86a8604386fa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 19).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'dd7c5ccaec5e8885_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6aca3324-da23-4d6d-8cdc-99bad987b501', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 19).', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'e119ffac602da2e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c62f336a-d249-4686-84c9-820004b14a1a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 19).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "C", "text": "show ospf interface", "is_correct": false}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '6d21cd784d67380f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5522cfa-3091-4e89-b3fc-fd6d160c6633', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 19).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'e5763a26223b353c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('792a1959-656a-4dd5-97b5-6c355f725d4a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 19).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '3948b24ba48463ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3523c9fb-9ca0-484d-bbe1-f8c89985ca34', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 19).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '861d435524cbb57b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1354a1db-cc01-4f72-837f-53e119ce4cdc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 19).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '543147ac1f36090a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d086056-b0e2-4fc2-a4d6-c586c7d77461', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 19).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "B", "text": "AS_PATH", "is_correct": false}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'fa9fefe3949b8d6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afe7ce80-a84f-4493-a620-7d091b32d1f8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 19).', '[{"id": "A", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '11c60eda67427602_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98e21804-29c4-4ed7-8108-723500d789b1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 19).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Configures the local preference value", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '1d2283a308ef1ebf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0cf6d9d-e47d-4a54-bfeb-a1fbc574fd06', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 19).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '8c1afc81dd3148b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5da6c505-25f8-4b67-9de5-39f40178bcd5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 19).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "ORIGIN", "is_correct": false}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'bc3f36070674add4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57a3f4e6-77cc-43d9-8b64-a9d15cf2f644', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 19).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The group of route reflector clients", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'c216eec2a7495584_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d5aaa84-3177-459e-b759-f8c92f48e771', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 19).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Permanently deactivates BGP advertisement", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'a4c097a6f4c89b80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('526e025b-4399-4fb1-9a75-7a4b3174ee9c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 19).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '10081630f93475a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a064661-3f62-48a3-b3de-03b51a423546', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 19).', '[{"id": "A", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '8d3d6d74f86957c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('917ca051-e84c-4de8-9c56-a83d3ad6dc16', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 19).', '[{"id": "A", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '19e5e1fc878d5a50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebdf9d83-c393-4afe-9df9-e46820007726', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 19).', '[{"id": "A", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'd7c406c8e6d5a8f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24ad915e-961b-41b5-80fe-090aeb5b2e35', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 19).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "D", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'a354702a09b70669_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb893364-69b2-4df9-9f23-92c00aa48ad8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 19).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "D", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '6c3d1438ab2aec4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5c3d1d1-26a0-4204-be51-130d67710869', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 19).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Alternate port", "is_correct": true}, {"id": "D", "text": "Designated port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '596b97e50e7127b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7af2f08e-3460-423f-833f-a9a7b9b538d5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 19).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '4489ba9f0ae002c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e06b23e3-2182-49a4-a401-7a0c87acfc24', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 19).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '755b5fdfd771ca7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5b8702a-bf3a-423a-ad2a-f63633edd7db', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 19).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '8fe0b69abb475b5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1abc2bb6-6ad3-4329-a832-f36afe62364d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 19).', '[{"id": "A", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64520 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'c71d9e77c9f3d022_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b01016c8-02fe-439e-9d6a-01059b2fcbe6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 19).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '6cbc47c40ff3e615_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a768840e-1c7b-48b0-8569-56aac90ac8ba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 19).', '[{"id": "A", "text": "set interfaces et-2/1/3 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set switch-port access VLAN 255", "is_correct": false}, {"id": "C", "text": "set vlans VLAN10 interface et-2/1/3", "is_correct": false}, {"id": "D", "text": "set interfaces et-2/1/3 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'ab9a3b4971560beb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e0baeb1-f23b-455b-b343-885190f2d501', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 19).', '[{"id": "A", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "65200 (16-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "1024 (10-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'ac89fe21a2bd905d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45bd230f-c981-4b0a-9410-76b2fd9483d6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 19).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '6485933d1b69f387_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4e2ed24-4510-4c47-aa76-58e09d831fa0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 19).', '[{"id": "A", "text": "56 (111000)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'bdfc550379ed4cbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('334878af-11ea-4974-8081-2774a1df31dd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 19).', '[{"id": "A", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "B", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'a66b9654125952fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d8ce1dd-5774-4527-85e2-5514957b96e4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 19).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "D", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '021e0b4d1c0ab1aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc10c51b-d424-4cff-8b36-819beb25602d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 19).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface ge-1/1/1", "is_correct": false}, {"id": "B", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'de83606a5d192b0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86f1d625-ee2d-4afd-8743-2d8ef1dc75c0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 19).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'da5f0a148572d380_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc7b3e3a-e794-4926-8966-54a66582b555', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 19).', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '8e3f22dcd29c4e50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a748c942-e7de-4fc8-abe5-531699207158', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 19).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "6633", "is_correct": false}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '3a916ec3daf9bec4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b72b957d-1d71-4ca6-8f98-6e213b33d9e8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 19).', '[{"id": "A", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '4a38230acba66dcd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4726cb0-fde5-49a9-bcaf-3a28ad6bedb9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 19).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "C", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '8898dd7dfba8212e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('996b9c6c-1017-466d-b345-e56317c63325', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 19).', '[{"id": "A", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '299c0c8ed6bc9d0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94b1615f-e39a-4d22-a1d6-ae5958909010', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 19).', '[{"id": "A", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '45284eb5b5fad5ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('129c3461-7ae2-4b7a-9f8b-6296527d0eec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 19).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'f581f99fe00da5f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('caaf158b-38de-4737-b109-c6ecc55075c0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 19).', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '8d587b45476609e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e5dbe6c-eab2-4e18-be9a-7055ab0188a5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 19).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "monitor trace <destination>", "is_correct": false}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'bc0ff722e5296597_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('035cce87-81e1-4259-bb48-ea6f46fec064', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 19).', '[{"id": "A", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "B", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '38f5100cec439c79_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('805f6390-e47b-42b3-9e17-c51b2ed5f7ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 19).', '[{"id": "A", "text": "All of the above can be used", "is_correct": true}, {"id": "B", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "show route table inet.0 <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '8b27a8bd0a74a74c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84963637-ed2a-433b-b1e0-c882d09792c8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 19).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Replace the interface cables", "is_correct": false}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'f37621cdf0fe13e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bab30c02-25e0-4827-8902-64e6446a6bdc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 19).', '[{"id": "A", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.233.47.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '3cbd606c878b00b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ea9ddbc-5318-405c-954c-98ec99eac78a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 19).', '[{"id": "A", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Defines user tech permissions to the device", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '3107bd709d7e95c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9126ad6e-0449-4d1c-9fdc-24ec544c5085', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 19).', '[{"id": "A", "text": "reject", "is_correct": false}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "discard", "is_correct": true}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '60af422f06d673f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f92446f4-4f5b-4968-b9e5-3eb803f5cdc5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 19).', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "D", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'c3f1fd3ce953fa8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cca55328-9eaa-47d3-9133-c0d241f0d5c9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 19).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "D", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '4c95efc168fccacc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfbde563-7ade-463f-8f2c-6e17bbb4d263', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 19).', '[{"id": "A", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '26c4e180e4016064_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eeae1376-78d4-465e-b9f8-972c867228ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 19).', '[{"id": "A", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'b30c09e94d2a4c02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90ee10d7-0d70-400a-be1b-ca1046e829e0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 20).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '63338810aa889781_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3043255-a726-4b63-9f6c-c9ae3356815f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 20).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "40 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'be5e5dfb7a4ac240_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb7070d2-5f1d-4e40-b976-9a807827ea99', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 20).', '[{"id": "A", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '602c7f79b88d5ce9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10b38ed0-2237-463f-8c13-cc400775182e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 20).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'f264e6c26eb45f93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b04a3f05-4002-4f94-b814-ac329331dc27', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 20).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show ospf interface", "is_correct": false}, {"id": "D", "text": "show ospf neighbor detail", "is_correct": true}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'c0cf0b401656b703_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09ef9864-dbed-4e8a-a91d-81d25e4aa7c9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 20).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "D", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '9221002bac4b0520_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4ceb669-684c-4cef-8f49-7462687186ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 20).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '1a6027cc8953a2ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d0e29e3-e732-4141-9d31-6d8690376d5e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 20).', '[{"id": "A", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '27e94a9d26133b47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c454982-6874-4b46-9fc8-ff9f96214770', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 20).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '012ee5e9ab81ff3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('944ba96e-e3ab-45d7-be9a-f4f959fe85de', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 20).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'a537d93e67c212af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92aca464-3224-4eec-a5c8-4f441f16376c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 20).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "64", "is_correct": false}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '34250f9529418f3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cc03722-7cfe-400c-b744-b3fd4370091c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 20).', '[{"id": "A", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '263c90388c89b368_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2fc89a5-ee7b-427f-b10e-b3817331f377', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 20).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'cced4fe54cc07b25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d16bbed-743e-4214-afee-8f737f2be3bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 20).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "ORIGIN", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '7a63695c769a1273_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a05a785-5066-46d5-865f-5cdb6ab9684b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 20).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "C", "text": "The group of route reflector clients", "is_correct": false}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'ae562fcf0699f90f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0559e969-6dca-4bd7-8d76-a93514a8ed84', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 20).', '[{"id": "A", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "D", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'a66652a001022a98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1e7bd1e-3ff9-41e5-ba6b-39f663195c03', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 20).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '4202422caefbad4a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4929fcd0-bcf1-449f-abda-a6ecb1939c12', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 20).', '[{"id": "A", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '40538cde8411830c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a1b149a-b0d7-41d4-a080-c67041d10b5c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 20).', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '7d7b8d9b3619d22c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d36eedf4-8304-4f49-aab5-c78d6977a441', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 20).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'd688d647b6c0d81f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e491e1eb-d97c-4e62-8eb4-3898de0f4e13', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 20).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "C", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "D", "text": "RPF is not used in PIM-SM", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'c132015836047817_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('253aa96c-ffec-4e8a-99fe-ed94b1678476', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 20).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '6afb850fe3a9e03f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c084faf-27f6-45bd-b557-fdf651b9d0c3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 20).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Designated port", "is_correct": false}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '012383a14fbae042_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3628cfd5-7fe7-4f70-a1df-5baeac837f03', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 20).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'c9c50a27fd14e202_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9d39660-f2aa-4367-bb6e-eaf144dc9322', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 20).', '[{"id": "A", "text": "show spanning-tree interface", "is_correct": true}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '345a2be701feb59e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7809ace-0add-4b5f-b16a-116cbc1c6996', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 20).', '[{"id": "A", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "D", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '79120bd4d9e47264_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cf6e0d8-5c58-488e-b0f3-5a941f407709', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 20).', '[{"id": "A", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65500 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '03d4b2ea50af9721_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edb91601-c63c-4dd2-ac29-f5b9a18e7677', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 20).', '[{"id": "A", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Provides PoE power negotiation for access ports", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '4205b689ad7a05e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a3cf935-e76d-46a5-a908-0574bda12b72', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 20).', '[{"id": "A", "text": "set interfaces xe-2/1/2 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set vlans VLAN10 interface xe-2/1/2", "is_correct": false}, {"id": "C", "text": "set interfaces xe-2/1/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set switch-port access VLAN 316", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '89b6cfe6cfeff180_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2562a80-1135-45e5-90cf-7bce8c71c2fa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 20).', '[{"id": "A", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "65002 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'd267d06feab7afce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00487665-6044-4ac6-be85-58bfe4f9ef55', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 20).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '398e3e0aa2785f9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3702f1ef-d07a-4b01-90db-91f2229b519c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 20).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "26 (011010)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "46 (101110)", "is_correct": true}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'd3d2d2a4c03e1d4d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6dfd8216-f2b5-458d-894f-0bdbc8e4ee59', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 20).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '8584bf2c9c21de8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5eccafc-e909-41c8-b6e2-e6a95d562e02', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 20).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Determines which packets are forwarded first", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '982f4b130d50049f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f788e624-b214-4871-8dc3-8b2f93c9d013', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 20).', '[{"id": "A", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set cos rewrite dscp 46 interface et-3/1/3", "is_correct": false}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '013b1e532ea7acf8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9152b8bb-d904-4f79-b4d3-27e601cf42c8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 20).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '85f336d5739a0240_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97caf7dd-b23b-49c3-9b6e-a4f39092d4fe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 20).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '901d8a5b3c893f11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a925e924-5c3c-4305-ab42-4fb3b9a4c061', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 20).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "8472", "is_correct": false}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '6d7f674617192b15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3489d153-eb0f-45ef-aa3d-25e71402aa75', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 20).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '6f96593a0892aa24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8142d23a-75e3-4851-8be8-8600c2a336d6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 20).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "D", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '9041f90e023b6068_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b33eb5c7-f59b-4dbf-b6e4-c7d552d506d2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 20).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'bb0645a422b920c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99768f1e-27bd-4634-ace2-0d8dcf33c61c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 20).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "C", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "D", "text": "Each host is configured with multiple default gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'b358f9b64c4dfea1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38335022-4e02-4cb1-bfba-ffcca9151238', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 20).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'c0d0f91ebf87144f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a541bca-d239-43c0-bdef-ff831259e007', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 20).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'a64a4d6cb0865af1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f44db7c-e162-491b-9b48-1f8d7b01f788', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 20).', '[{"id": "A", "text": "traceroute <destination>", "is_correct": true}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'fb18b5ed2597a1db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13382ae9-c753-431f-bb29-c9cce2591b3b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 20).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The BGP route table with all attributes", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '37f187efdf590c68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3b2587e-bb80-4986-87a7-1e127eec68a0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 20).', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "show route table inet.0 <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '7ffbe7bb4334edc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c033da36-3723-413b-8f36-0b3c608340d0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 20).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '491fb6d57ce45edf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1b86675-5a46-42f7-b264-e7e2d6f706e0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 20).', '[{"id": "A", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "B", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "C", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.74.163.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '388537c3685dd98b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('deb014d7-7815-482b-b99b-b17ec13b1bbd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 20).', '[{"id": "A", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "B", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Defines firewall rules for packet filtering", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'd7122b2f5597513a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e770818-3900-4510-ad04-f32023da237b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 20).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "deny", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '7e4063abe1849ffa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6938c608-93e3-49a6-bce1-55a37b07ce0c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 20).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'f9f6071fe06b123d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6ab2926-24b5-4ade-a459-84beeec05bf0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 20).', '[{"id": "A", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '2f68de28979e6375_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a2b00af-ecde-4862-aac9-ea5a8f9b4fcb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 20).', '[{"id": "A", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "B", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "C", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'b84b778b4924782e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3780594d-5650-4758-9b1a-7b4c63a78af4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 20).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "D", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'c6a9ea868f541c91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a5393f7-246a-4bb4-b573-1ea03fc70ab6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 21).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "ABR", "is_correct": false}, {"id": "C", "text": "Backbone Router", "is_correct": false}, {"id": "D", "text": "ASBR", "is_correct": true}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'cbb79e5bf67ab69d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a17fc40e-7a93-4082-b528-0acd3be8bfe9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 21).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "30 seconds", "is_correct": false}, {"id": "D", "text": "120 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'b188c0d9f8fc101e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c188c08-de58-4668-96f5-7a959d23b52d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 21).', '[{"id": "A", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '58c90279a82d3b64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2304d03b-e6eb-49d8-86d7-84c3b51ded10', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 21).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Advertises external IPv6 routes", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '763662fd3697a1a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('474e451e-7a4e-4ef1-b9fb-e083226e5252', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 21).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show ospf neighbor detail", "is_correct": true}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '78b4d9b20516e3b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e49fe1bb-970d-4275-9f1b-4915d6e69eec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 21).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '4c2d7ef3027643e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ebc911f-f6d9-4ea7-87ea-3401cd44ef14', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 21).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '8e34aae4170b6efb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4704a11f-1c53-49cc-8872-7ba5ad84aa65', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 21).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '8779caf720d55ea3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef753265-db80-4475-9460-f679356be467', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 21).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '56fdd749d5d1a129_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24b977e9-6932-4d31-8293-c2db7e1dc36b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 21).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'd1ceeea291511c1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b8ebfba-008f-4a7a-a270-66b5611ca3dc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 21).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '21cd152d970a13a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91ac400e-cc82-4850-b8bc-427b546a0ef3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 21).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'a0d85333bb548c9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('579bcde6-cf3c-4ab9-9978-5cdf4cbc6553', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 21).', '[{"id": "A", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '6077e8905489e97a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff592a1b-8d0e-4b6e-b72f-234dff863e12', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 21).', '[{"id": "A", "text": "COMMUNITY", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "ORIGIN", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'b6eba69f983712fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c2ef9e2-3de0-43f6-b035-d25f2f5730b6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 21).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '4a47d6c00286025f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74dc75ad-c68a-4c7f-ba6b-109084d92673', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 21).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Permanently deactivates BGP advertisement", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '94bba9fa0eb27cdc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec62fa54-3b73-4d3b-b1f4-4f7a2749faa6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 21).', '[{"id": "A", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show bgp summary", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'd904db36456cb452_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18a3a824-cdb9-4942-8856-e922f2ae850a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 21).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '465ea9bfd606d456_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70ecee85-482f-42b5-8418-b54ea85949dc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 21).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '171f0957a2bbc1c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26776f37-0552-4604-9365-ae4fd2f87634', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 21).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "D", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '88ca7090b65c4985_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88cb8160-6338-4171-9b33-db3ecf1e3ab1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 21).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "C", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '2937822903178e90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d970075-2897-459c-b9f5-43d4856d5a8d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 21).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'f279fed4eefa62e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d25989d4-9ced-4667-b4b0-5ae54ee51ea4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 21).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Edge port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '830907054742bcc8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cb6983b-e6e5-4594-a6a7-a291595ff752', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 21).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A physical link aggregation group", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '4d40260e87dedf00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0bf09c2-7ead-4a8a-b350-5caab3bdd76d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 21).', '[{"id": "A", "text": "show spanning-tree interface", "is_correct": true}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'd050dbdd03096dce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1d2fc65-b6db-48f6-b952-7ca6299d9e2a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 21).', '[{"id": "A", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '05efc17f7b77ee77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1d69ab4-f578-40a4-a56e-a1e67bc91adc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 21).', '[{"id": "A", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64514 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'c252243983d66a55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b197e17c-b316-4e1e-a6de-075619a107a3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 21).', '[{"id": "A", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "B", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Connects to the management network", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'f6aa8c4d3820199b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2baa28b3-31b7-42d8-b3a5-969dea8d4c47', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 21).', '[{"id": "A", "text": "set interfaces et-1/0/3 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set interfaces et-1/0/3 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set switch-port access VLAN 26", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface et-1/0/3", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '1839c685a0cdd556_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7d47eaa-d4c3-407a-ba98-505713296823', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 21).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "65100 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '6a31bdc054710e27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2879ff22-346e-45e1-9827-b5e662728107', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 21).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'cb602bb9315aacc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ffc5529-9bf2-4475-8b45-d62f872f15d5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 21).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "26 (011010)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'd0e936f5be34fd3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1094f63b-e561-44c3-af2a-c448b62d308a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 21).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'bc354b79f0aa83a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('450b90d1-526f-495f-b77e-836a7e5060b3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 21).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '4e83e7cac4e702cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('544a00ff-5b76-47db-b3d3-f29c50a31dfb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 21).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "D", "text": "set cos rewrite dscp 46 interface et-0/1/3", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '6ecf9cc3758c1a9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('948f9b5f-7150-4d9d-aae1-88eae587b402', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 21).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '750e3921e3858581_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d9b1f14-d337-409f-b543-aebbda79fb77', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 21).', '[{"id": "A", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "B", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "C", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'e8656fe308df3fd0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('386c967e-b3f0-4416-b858-93fd9fc59d40', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 21).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '4b2012b75a92afbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0318fb7-0ee5-4f60-b646-7b800fee70c4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 21).', '[{"id": "A", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '1fdb9c27877f259d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48214aa3-a047-4649-89bd-6d8547fc84d9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 21).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '1c4966c5a79707a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cc78666-f4ea-4771-bcdb-5799d23350df', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 21).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'c7a58fc9ef80ba15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5c44cbb-46df-4d22-88fe-9b31a6148158', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 21).', '[{"id": "A", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "B", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "C", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '752e47c4a4794f4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88c75352-6067-46f8-b84d-a58963d240fb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 21).', '[{"id": "A", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '5ef31fb12cc430b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a126346-6d0d-4476-9139-ebef6e4a5a34', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 21).', '[{"id": "A", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'dc5a14d7e1db1633_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8c6dcd2-31b1-44dc-87cc-8b4cf98248c9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 21).', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "traceroute <destination>", "is_correct": true}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '9359b957851fa20f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7622c24d-fa6f-44f8-9efa-2a77c54837a0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 21).', '[{"id": "A", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "The OSPF link-state database", "is_correct": false}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'd0ff1a36f649c8df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6232bbd-17f0-4073-9674-1225b9660ce4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 21).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '6f1d291400548e2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fb7df15-afbe-4abd-9ef5-a3e53d354a6f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 21).', '[{"id": "A", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "B", "text": "Replace the interface cables", "is_correct": false}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '5b178cf57771b604_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36a35c97-f901-40c4-9001-93b5024ccd75', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 21).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.243.93.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'ea91aec89a3f02a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9081ada3-9092-4404-989f-57ffc26c1d87', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 21).', '[{"id": "A", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "B", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Defines firewall rules for packet filtering", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'db59e7114e293f84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3ff00cd-bda3-4815-b06a-67cf87f8e919', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 21).', '[{"id": "A", "text": "reject", "is_correct": false}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "discard", "is_correct": true}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '8a6025ee68a60ee4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1783fe6-149c-4616-8be0-a941b2577908', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 21).', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '7790d28c32d62d5a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcf65f94-ab73-47dc-8754-7a793aef3356', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 21).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'f6f06e6403f0311c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4e7903d-5092-47b0-b448-2b1945e9d7ea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 21).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '1f03d63faf14cc57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('785a7e95-6712-4367-85af-f5739dcad942', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 21).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "D", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '267c2fdb7c2a747d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1034705-f22f-41e1-9b04-8c6f83d2233f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 22).', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "Internal Router", "is_correct": false}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '139d407d56983a35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df8bf43a-921f-41e7-99dd-1092d7760637', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 22).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '04059dfceb98284a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e96edda7-d8e3-4a40-b78a-5a94cfa326ff', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 22).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'f35dde4503e6c2c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('731e3e21-9732-48cd-b5fe-95a770deb5cd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 22).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Advertises external IPv6 routes", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'ab83cd188c4a8470_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d147de1-6bb7-4326-a17f-914d295c73d9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 22).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'facb510c416ef591_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('084f844d-f6b1-4acc-9311-015e1adfdfe4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 22).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "C", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "D", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '09baa90c61b7e467_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('345f2834-5e05-4809-a4fb-1409134bf96e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 22).', '[{"id": "A", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '970fa6cbf76776d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b5e0f69-1feb-4345-90e8-3a10bba70660', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 22).', '[{"id": "A", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'cd73a240644c7de9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba942c6d-7b1e-4c18-9941-b05a8189b100', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 22).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '5c80ba925de6338d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a97efc5-8762-406c-b7b1-fe955b33908b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 22).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'e2a6ad2e2a9b367a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd4c7536-1a2a-4da9-b520-0cd3dab31561', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 22).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '6a745fc3120b549d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b22307ce-c12b-4052-8a86-5edc72381728', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 22).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'b6800497e63a3c78_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0eeb9ec2-24e8-49b0-9623-f04c5ec507e4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 22).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '8eeace5946e31042_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c5c3f36-430b-45d9-95a8-ec2037e2f34f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 22).', '[{"id": "A", "text": "COMMUNITY", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "ORIGIN", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '7cd2cdfa556ac196_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d9fb17d-e9e5-4fa0-a564-bbd59f4db4c1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 22).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '7ee815fb4ba1500c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63429a55-974b-417f-9ba8-aa854017d4e4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 22).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'e4634456b9e76d3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6d18680-58b3-4212-85a2-f2468b9305df', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 22).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'bfe7f07728e32033_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a7e1387-47f3-4461-8c59-5d170950e60f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 22).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'c93186a0de6215b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d26f3ad2-b72e-4e90-b6b9-6b6bfcd2c0d7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 22).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "D", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'b98428d922c1046c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30d79b41-d2bc-4c08-9e61-8f2f603ae00d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 22).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '52630c88b8fd3371_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04129ee3-b25d-43bb-9847-e44f3bee0c1a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 22).', '[{"id": "A", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'ce931721436dbcf9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('605593d2-4a0d-49b4-8ef5-f5b349611753', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 22).', '[{"id": "A", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '95525bdb5c071a27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13e242e9-ac78-41ba-81ed-e93c3f1e675b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 22).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Designated port", "is_correct": false}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Alternate port", "is_correct": true}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'f28224c61300c333_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1439edfe-152f-46e5-a619-273ffd27310e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 22).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "D", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '0ffea24035e43c67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('501f9a32-8d7f-459e-979f-bb9f912b5014', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 22).', '[{"id": "A", "text": "show spanning-tree interface", "is_correct": true}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '5f40fa57a06ac507_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d3e60da-1448-47d4-9d99-1a8966524abf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 22).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '8db4969aba9594b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66c4e941-cf50-4d3a-9ed2-caeb9ac2fade', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 22).', '[{"id": "A", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64512 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '8d5104c2656d064d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a88948b-6601-4e74-bd67-730f7369061d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 22).', '[{"id": "A", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "C", "text": "Connects to the management network", "is_correct": false}, {"id": "D", "text": "Provides PoE power negotiation for access ports", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'e43f84566098669e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2323c2f6-e3c6-4b58-8945-99549d8dbc2f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 22).', '[{"id": "A", "text": "set interfaces ge-3/0/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set interfaces ge-3/0/2 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set switch-port access VLAN 80", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface ge-3/0/2", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '48e5db72cff05dfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ed2f976-0274-4e02-935f-b550e5ac2a57', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 22).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "65000 (16-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '653d2d546b345f6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dec19c08-d4b8-466c-b27b-9e059fa4d5b3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 22).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '606177522540f768_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85a97fed-76aa-4787-8b32-62e6d62a58bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 22).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "0 (000000)", "is_correct": false}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '9ebab95f31d9a6e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71ba16da-de85-4387-b2da-bfebf8cd88c9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 22).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '1ae6e47e5a65b543_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e9f916c-a86e-498e-936d-e77a3788f52a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 22).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '0e3ee50aba896985_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('553e15d0-91a1-46d6-9040-65825be69854', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 22).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "C", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "D", "text": "set cos rewrite dscp 46 interface ge-3/0/0", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '132ad99a0e21ddfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b388683f-5606-4620-b108-5a97ff449ff5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 22).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '8c2bc8f06a683985_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9d6a1c1-a96d-479f-a135-204293bf0ffb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 22).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '9f4321f48579f67d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6be83dde-67a9-447a-aedb-124121a77d25', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 22).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "1234", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'b933270d199f5f13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e072b79-57de-42d9-8c96-1aafda5e4b91', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 22).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '7107c24118d1b545_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8917ade-3089-4668-8d0a-8db256036db0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 22).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'cb7b6dbe2f3a3fd1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('caf17b38-8adf-49b8-95b9-9fe7df20f62e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 22).', '[{"id": "A", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'e7c5f701648d9348_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33c35bca-e8b4-45dc-9ac9-1251ae8f4bea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 22).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '1400dff78c1a2fe1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b03399bb-697f-4ce9-9b37-bb00237eb89f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 22).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '9aa9c52dde10409c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46322288-914c-42c1-89bc-be8b39438280', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 22).', '[{"id": "A", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "B", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "C", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "D", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '4e8334722f6d496d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4bcfdb4e-e124-4c08-bacf-7b0c9f809399', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 22).', '[{"id": "A", "text": "traceroute <destination>", "is_correct": true}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "monitor trace <destination>", "is_correct": false}, {"id": "D", "text": "ping trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '94b97e244bd791b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f725ccb-1e0a-41c2-8dc6-06d3085d9c24', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 22).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The multicast forwarding cache", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '0f952f2fdc26e597_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3b5f765-fdb4-4f2d-8484-86777d6d1339', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 22).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "show route <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '9a111990da9332ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('831a3e30-8c66-402f-99ca-692806c3deab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 22).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '47153ea89784985a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f72e049-b003-44c5-97fb-e62b41c5385a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 22).', '[{"id": "A", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "B", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.183.76.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'afd68fda0778c9f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e10d4efd-772f-4cce-b534-8445dd1e295c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 22).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '2dab56f8ac3676bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('971ae234-760f-45f4-a7cc-3b2d3f787beb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 22).', '[{"id": "A", "text": "silent-drop", "is_correct": false}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "deny", "is_correct": false}, {"id": "D", "text": "discard", "is_correct": true}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '0e8e785e5ce28e7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89ed19d7-aa8e-4546-9780-d48956203be4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 22).', '[{"id": "A", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'd0e9d3e3195af8a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ad6596a-885a-4ea1-883b-cd7e42039bab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 22).', '[{"id": "A", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "D", "text": "Single switch acting as both core and distribution", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'f324169554dd53aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('546e30ca-6a02-47ab-8f0f-cdd132490703', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 22).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '6745a2278b412100_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5ebe037-af83-4075-bf07-31ce64d32678', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 22).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '52fe91da60344d51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12a6e6fe-006c-4a67-861b-8aa5def945a0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 23).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "ABR", "is_correct": false}, {"id": "C", "text": "Internal Router", "is_correct": false}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'b7a0fcf2588638af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da413595-0a0f-43e1-9c84-450be5d9310e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 23).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'b05e878207cc1a92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88b61c11-18e2-4d11-9da1-fa1f78b87e64', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 23).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '92179ba4f6e980b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8141fb53-fec6-43ba-94d4-8482e2f11f26', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 23).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Advertises external IPv6 routes", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'de4e2ddf8506f2c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c49706ba-adb8-4206-9daa-d72418002b0c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 23).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'c1262411aa577a07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('042b9a3c-49fa-449e-8834-3fc17af169e7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 23).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'ee1a0eb94736af4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aac30137-5613-41b0-a5c8-28181800b648', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 23).', '[{"id": "A", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '7b4eb0efac95d3e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c1efaf2-2297-4799-8f91-758354d55b71', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 23).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Both narrow and wide are supported by default", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '5b1fed2af788f96f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecb1bc91-bb1c-47e3-91e6-051401e9ca06', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 23).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '3491d7fb50906120_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3aa6dd67-e9ec-4e39-ad96-40973aa7f749', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 23).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '2215829041e22dff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('763ca131-a279-43b5-863d-2df6afde9b98', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 23).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '9c9bb271e5cfa81e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a10ad16a-bb05-40e7-afae-733ac392be9c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 23).', '[{"id": "A", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "B", "text": "Configures the local preference value", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Sets the BGP router ID", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '9532ad33d1015f7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20f4bdff-c507-4f95-99f3-616775ae0c23', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 23).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'fca6f27155cd0c4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c00aefa-885d-4e40-98ac-3946c8783c4e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 23).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "ORIGIN", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '1ee69918c167f610_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3eec4e16-58ad-4624-87f7-8d348416d199', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 23).', '[{"id": "A", "text": "The AS of the route reflector", "is_correct": false}, {"id": "B", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "C", "text": "The group of route reflector clients", "is_correct": false}, {"id": "D", "text": "The IP address of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '1f256374dc1becb0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82c34a57-4dc5-45eb-87cf-b768c946e33f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 23).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'fef9580973629788_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e32a76be-cbfd-4731-ac38-8b725ad20345', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 23).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show route advertising-protocol bgp", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '1749e4dcf6f3f559_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37e25d29-f735-43f9-a5ee-6832001c52c8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 23).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '8882d11c8ef28351_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdcb38e4-549f-468d-8ad9-b7d2b27131b1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 23).', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '7b4a2ae2da2461cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea6f022a-4280-40ce-8720-4ccd49520e72', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 23).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '9546dc46403f7278_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de29a2c5-951a-46af-a569-bb904bb78e24', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 23).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'ed690faa816ef3b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8dbcd160-3a7f-4a3a-bbc9-a45125895cbe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 23).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'ad98c2b1e6d03021_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('720a5241-e507-494f-8823-65c0311cdfcd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 23).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Backup port", "is_correct": false}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Edge port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '41d6e850df112ba4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a39c3c05-626a-4411-aa72-3040f042feba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 23).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '85b50f2eae3d1044_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a90bd2d3-9337-4e0d-9641-ea9a3e6516f4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 23).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'dc9001702dfbde8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f141335-ccc8-4d49-ba87-5d866f6256e6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 23).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'c218b885d3b66378_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7851b73b-6359-4b57-82cd-20e060a3c701', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 23).', '[{"id": "A", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64512 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'fb1045ab865389f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87384c40-8d2a-47fa-b512-5d0c2fe800c8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 23).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "C", "text": "Connects to the management network", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '8df5f14c5d191428_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94b4285c-73d8-496b-b87d-cd884377c9b6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 23).', '[{"id": "A", "text": "set interfaces ge-1/0/2 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set interfaces ge-1/0/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set switch-port access VLAN 479", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface ge-1/0/2", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '22be8dc6303945c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('690f242d-0024-4584-9d37-f634d065cd58', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 23).', '[{"id": "A", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "65100 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '8c69b9202f623bd0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c2be527-7537-4e62-ae5f-cb3e14a4b886', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 23).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'ace0a9cfa5f7e49a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73f33a53-e7f3-4f14-aa2e-d9bcf7fb31af', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 23).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'c661b9fcfafb6512_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4329dbf-bd07-4bf5-87fb-72a0cf2b934d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 23).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '9193f8854bb34287_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2cc2954-69c7-42c0-8a0b-ceda19bf389f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 23).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '7b10279e209ec2e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fbe9abb-dec8-44aa-a551-f1a5b606eed4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 23).', '[{"id": "A", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "D", "text": "set cos rewrite dscp 46 interface ge-1/0/0", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'c91cace695c19594_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2a16a3b-c86c-4c00-bc99-93f75aa4840c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 23).', '[{"id": "A", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '0ba9ee06df485266_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecfddd8c-91e5-4e4e-9756-bb3f74063bea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 23).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'd89f112ad77e060b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aed1dc1e-d1be-4f68-a2e2-568073b29e2e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 23).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "6633", "is_correct": false}, {"id": "C", "text": "8472", "is_correct": false}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '228958d8b65fc244_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71c69425-b330-4a35-9a79-4e25f4ee7f8e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 23).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'd35e15f6a51a419f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('034273c1-5f26-49ef-a226-2b1bfeb33dea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 23).', '[{"id": "A", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "B", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "C", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "D", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '9bf50406363f792b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c495990-a45a-4a51-a878-bdff28978d54', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 23).', '[{"id": "A", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "B", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "C", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '92eac64b02f986e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df217753-3fbe-438a-ad76-bf653c4bb6c8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 23).', '[{"id": "A", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'c5153f52740fddc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e63da3b-dac1-4d04-941d-55ae66251dc5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 23).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'df1e02ba319c91a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91fd2712-079f-44cd-a133-0ed3da216a1a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 23).', '[{"id": "A", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'd6ebb19cd304185c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('918a214f-97ad-4952-8ada-0947629d7b1c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 23).', '[{"id": "A", "text": "traceroute <destination>", "is_correct": true}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "monitor trace <destination>", "is_correct": false}, {"id": "D", "text": "ping trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'ed41144ea468b23b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('070d96c8-bbf0-4220-9f76-0deba02691a9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 23).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '52c232cef3cb55d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2203912-1745-4fe2-b85d-6b77429234d5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 23).', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'c63e248c81b06025_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77792e46-8d0c-4317-855b-5066e0588356', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 23).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Replace the interface cables", "is_correct": false}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '05d609a8bd3db1e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40568194-2700-4efb-9321-df9705e446ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 23).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.132.120.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'dc70bd51460a140c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c8090f2-0e55-4554-9d68-c413c22d8022', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 23).', '[{"id": "A", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '6f27ab8603c631d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6628779-3361-4918-831b-a7f8f7bd4add', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 23).', '[{"id": "A", "text": "reject", "is_correct": false}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": true}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '1f2504171f87aca2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bee4a61f-13a1-441a-b74f-05ea118540fe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 23).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '47de442609da5b59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7befe3d-5880-45eb-a359-ddd5bb984736', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 23).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'ee44ae847a015274_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfd1b1e8-fbde-4310-8f7d-b56a853e7a21', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 23).', '[{"id": "A", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'bdea95df28a7fc7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d1e8b9e-f344-478a-805f-e1a16679b8ff', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 23).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '671dd2671b9e2521_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28675539-7c09-49ec-85e3-69bf2cb5be54', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 24).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "Internal Router", "is_correct": false}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '7afa48712e796454_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18f1f8ac-1d20-4d1d-9560-14f9ea6fc252', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 24).', '[{"id": "A", "text": "120 seconds", "is_correct": false}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'fe0fc22d98cc92f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfa81e97-7de2-43fe-b396-7a97a5e3a258', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 24).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '5f43e38c6c047b50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('341711c0-b733-4ef2-91d7-53ff939cb8bf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 24).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "C", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "D", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'b1bbae64e530d760_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2b809a0-22e7-49d9-a211-7372f4e502ac', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 24).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '07a758d8233d4b6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66d4bec3-b3c7-4c58-b72d-ebffe9b31ae6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 24).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '113eaa8c78c5569f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb7cafc0-b3d1-4fb8-8e53-a5f605dc7231', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 24).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'c1a84a7061ad5ab9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c80781af-9802-4dda-88c2-9d7dc85ca21e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 24).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Both narrow and wide are supported by default", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '0a4a541cd4e13135_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdf471a9-edc5-407a-aa9a-0ee272631d6d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 24).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'a096151270353977_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ba32b9f-c1bb-404d-bcb3-c1d9ecaba49b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 24).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'd8485157523a27bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22032a07-5e92-4bd6-af26-77901f059f87', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 24).', '[{"id": "A", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '9f8cd2ceec48b711_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a4091dc-37af-45b9-91f0-88cdbaa6bc13', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 24).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'b4c8d39092e12b96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec1de48f-57d7-4822-88c3-803118cb7d03', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 24).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'a0ef8d4ffae52cd9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43bf7fef-71bd-4fe5-8ca8-405980d8d488', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 24).', '[{"id": "A", "text": "COMMUNITY", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "ORIGIN", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '12400c9614ffb6f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17beae38-b452-4246-999a-8ce20cb0bba5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 24).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '91e379dcf564ec90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('459c7ed5-65e9-4cfe-8e28-9a8500d5c169', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 24).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '24cdafa05db8f146_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fbd5e9a-e7ed-4c6c-b431-9617b05c7360', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 24).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show bgp summary", "is_correct": false}, {"id": "C", "text": "show bgp neighbors", "is_correct": false}, {"id": "D", "text": "show route advertising-protocol bgp", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '895c68fd524933ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdc97d1a-c7fd-42a0-bca1-a02d159d21d8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 24).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '186c7d0d10682d89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d605ef2-a2ca-43b6-b02c-92721a17f9f0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 24).', '[{"id": "A", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '53a6d7b818cf4100_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ae5aa0b-6120-4c5d-b790-c69b27d05817', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 24).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '96cb022ab6dbc0ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65960443-f664-47b8-adf5-4f631ed7a484', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 24).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "C", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "D", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '2010230d133baeaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c4548ed-88f1-445e-a4e0-ff047d707213', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 24).', '[{"id": "A", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'a80823ed96488f45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c737743-f54b-4f6a-9ba4-dbc6d0f3bb22', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 24).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Designated port", "is_correct": false}, {"id": "C", "text": "Backup port", "is_correct": false}, {"id": "D", "text": "Edge port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '0cb565ec2beb8bb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('beb169a8-3054-40ce-9ddf-918790d7f0d1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 24).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'ee4d3d16d74a02d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0e08606-d680-4d19-a3d0-e462b2a1bec2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 24).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '350dd00a7d88f7ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54db991b-72e2-4282-af8b-4b5c2748c5ee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 24).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '34ce702aac5ccbe5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ccb6e0f-bb12-443d-8667-763900298fbb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 24).', '[{"id": "A", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64520 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '5a8ab31886a49401_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6c9d3c8-1620-46c2-9237-de1f8a45071e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 24).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '727fea33e6f7119e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54dde31c-f8c4-4f9e-8245-f47950301961', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 24).', '[{"id": "A", "text": "set interfaces xe-1/1/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set switch-port access VLAN 149", "is_correct": false}, {"id": "C", "text": "set interfaces xe-1/1/0 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface xe-1/1/0", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '3369a2a43696ef6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b399362-8e78-41f3-af6b-922b9e46438f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 24).', '[{"id": "A", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "65000 (16-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '249e58de8e407bdb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8be81834-b23a-4a3b-955a-d17d718301bf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 24).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'dc89c53fa3ce22bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc7dde14-b873-43d6-9cad-b7e6964d9f6c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 24).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "56 (111000)", "is_correct": false}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "46 (101110)", "is_correct": true}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '5b789ac3d8eefa45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56b86c32-8420-4200-b410-538c2c4b463f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 24).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'bed9acdaa8efe359_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39e404f8-ff44-4ff2-8ebb-4ea0d37177e1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 24).', '[{"id": "A", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "D", "text": "Determines which packets are forwarded first", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'e268d63bc75150a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2f816b4-ffed-444b-b527-cb7eaeffce98', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 24).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface et-1/0/3", "is_correct": false}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "D", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '91fd40a275e76ca5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b992581-b523-42b4-8df3-85ba065efa05', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 24).', '[{"id": "A", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "B", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '95e72069a50417e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f465607-a0f2-418a-9e14-2c51b85983d2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 24).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Carries multicast group membership information", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'a9947d7ec1eb9e67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('387fd9cf-b91f-46e1-b0fc-ab6406c4a476', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 24).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "6633", "is_correct": false}, {"id": "C", "text": "8472", "is_correct": false}, {"id": "D", "text": "4789", "is_correct": true}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '0426775a68bcfb52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b6e147f-2c2e-4056-b9ce-4df8d204f596', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 24).', '[{"id": "A", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'a6de61e09d128fd1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be0f3d85-45f2-492a-aa32-213000b14aa9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 24).', '[{"id": "A", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "B", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "C", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '5de197c9484be11b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebd5e5ee-a3ac-4540-a19c-956904564f51', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 24).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "C", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'd6e38f780f646a3b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6131e74-44fc-4c7b-9f78-3cd9c98bcf2b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 24).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'e94bf89c5da3da33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59392e4f-19db-4b1f-ac4d-d3212ab32cd3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 24).', '[{"id": "A", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '006373e759008741_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d008e38-5683-486c-a3a9-1a25ec3cc51b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 24).', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'f752562fbcc28ff7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f544bd87-72af-4f82-a7af-ed3d85dad335', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 24).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '9b1c9ddebe9163a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6eca49f1-69fe-4d6c-b505-18db341fbedd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 24).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'd7268aa876d13463_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0aeb083f-5e05-4a6f-a653-300bfb250a19', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 24).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '7ffdbe569a79aaaf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c322478-119d-41d9-8673-33ba72216007', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 24).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '93276e323d2baefd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3dbc9141-1cef-4b45-bf39-5322f7d7cabd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 24).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.38.144.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'c3494d2a2975f18b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a9ff1d3-5835-4dde-8683-8684a62a741f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 24).', '[{"id": "A", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "B", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Defines firewall rules for packet filtering", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'ca17ccfe9d89b9b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b8258cd-c27c-443c-bf3f-c32501c95763', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 24).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "deny", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '092414ff8031eca3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('253c5ea1-0bb4-4e2e-9ff0-2380e8f8d557', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 24).', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '24721900a61620c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbb5b966-67f3-465a-bbae-36c71ab8646c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 24).', '[{"id": "A", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "B", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "C", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'acfab8e96002841d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85b8e210-e7eb-4b40-bc43-fd61fe333df5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 24).', '[{"id": "A", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '92f202d3a171b574_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d5125d4-13b9-4d3a-be8c-f2c2c9406f13', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 24).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "D", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'f5c12b3f704d7d73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6664cf4-8f02-473a-8655-dca434a88055', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 25).', '[{"id": "A", "text": "Backbone Router", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "Internal Router", "is_correct": false}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'fca53b13b18b6a58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6522f0b-e146-4ffa-b76f-eb7e3f767ac4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 25).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '4a2587ecbf7f5b8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e99f9010-cc69-46f8-bd3a-091d88924a73', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 25).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Connects to external routing domains only", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '73142c45d318d6ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7cb01a6-3f4c-4cfd-9f57-5c64332c88f5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 25).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '59565c85b8fb6040_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f38c682d-89bb-4ddd-99e2-a23e4909d35a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 25).', '[{"id": "A", "text": "show ospf interface", "is_correct": false}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "D", "text": "show ospf neighbor detail", "is_correct": true}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '23857f7eedf97ef4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0af7f587-4d93-4902-b981-32b21b82e290', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 25).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '96f2d94958125141_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b6208f9-78a0-4875-89eb-96faa1d02e65', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 25).', '[{"id": "A", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '67c2ae504990b9f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('209e90ec-1b15-4319-8618-f772132ec37e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 25).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '5c7f8d27ddbb7be5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c534488b-21bb-4a42-935f-a00ca86e16df', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 25).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'a957683418be3080_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8b7ba96-d845-47af-b295-1aadf695b4ed', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 25).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '4ec4cb6cd940c08f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9beb846e-cb95-4793-b3b1-c251ce13f554', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 25).', '[{"id": "A", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'c46488640bda0d10_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('639a0579-743d-4394-be7a-036d8249bf95', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 25).', '[{"id": "A", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "B", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "C", "text": "Configures the local preference value", "is_correct": false}, {"id": "D", "text": "Sets the BGP router ID", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '8a5fc32b3411661b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55c98563-3d4f-4f5d-8a8d-dbdcf4969aef', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 25).', '[{"id": "A", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "B", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "C", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '331d36e827151921_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('744aa2c3-27ca-46a0-8b9c-1fcde6793415', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 25).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "B", "text": "COMMUNITY", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "ORIGIN", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '97a9955d257c7da0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b61ff576-7ffd-4cc7-99b1-b7763bf38177', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 25).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "C", "text": "The AS of the route reflector", "is_correct": false}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'a25d924919bd70a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d4fca0b-c7d5-43c4-a528-7e171e24be63', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 25).', '[{"id": "A", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "B", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '8375bfe74761feed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f65f1058-05dd-4a10-8fd1-c5136279db06', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 25).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show route advertising-protocol bgp", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '7c3d42dae7ce6b79_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7cbf39ab-c1f6-4edb-a7e9-564e89c16c6f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 25).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '3896f98b36059624_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a877829-28a8-4471-94e0-abb07363ec36', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 25).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "C", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '5d51a834abc2f6c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('054f4ad1-d834-4175-8ad7-4dfc85623a62', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 25).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'e0e8a1ffaff73008_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70cd4170-d913-4a09-8fc3-ba107134c6b7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 25).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'cee5bdddbc1bab8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c013b34e-e936-4da8-b65d-77890fca9a7d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 25).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'b2f83d8fceb1cdda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e8117a4-f135-4c9e-940b-08dbf3a2f6de', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 25).', '[{"id": "A", "text": "Edge port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '76a77dd94d16eccc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c96888f4-d33c-4b28-aa82-07fc09919683', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 25).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '261dd9674e308d24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf79d4dc-c28c-4971-ae98-fbf2035d6bb5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 25).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '133fdac67d2d1115_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f527cdf-c7f3-4d2f-b3b6-aea7fdf89e11', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 25).', '[{"id": "A", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "D", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '0a77d7b43cbc2fc8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('330b29e1-2de8-42cc-b890-c36e7aa90e8c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 25).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65300 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '04c8f6b53c7ef9ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c13468ac-e4aa-4cdc-bcbd-f7bcc16f0d15', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 25).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Connects to the management network", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '7aea6cab788099e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5c6408f-a50d-49d2-ab92-4314f408c425', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 25).', '[{"id": "A", "text": "set interfaces xe-2/1/2 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set interfaces xe-2/1/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set switch-port access VLAN 26", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface xe-2/1/2", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'b65d19974ae7a724_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f77af434-ad6a-457a-a36c-4801cb7c9648', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 25).', '[{"id": "A", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "C", "text": "65001 (16-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "256 (8-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '86e6321fc4539a3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f546bea-8a1a-4193-97a2-199556e92d2e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 25).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '9264ebbf20624413_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7488d9c5-fd72-4d79-b9ca-ebbef0771476', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 25).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "26 (011010)", "is_correct": false}, {"id": "C", "text": "46 (101110)", "is_correct": true}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'e8106c3e36b94660_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49fbe197-9c3c-4f7d-8ebb-da87a2c8d5b4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 25).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'a8d2a6e10781b2ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1757cd4-120a-46f3-9c3f-f65cba24adfa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 25).', '[{"id": "A", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "B", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '5c4e3af15c558c12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d323dbb7-11c1-44e3-a9d8-6b4804bb6727', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 25).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface xe-3/0/2", "is_correct": false}, {"id": "B", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "C", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "D", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'be0c2bc9c429400c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df730e96-1bf5-401e-bd35-989cc1a42042', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 25).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'b63fe51c353e8c15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8af920fb-aed5-469d-a5d3-ffa3f47da2d9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 25).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'e32ab7077f960482_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07992ab1-d0fc-4a90-9189-ff62b2a7dc87', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 25).', '[{"id": "A", "text": "8472", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '9b0095621aedb7c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6906dff-ca95-486f-b2cc-7392fb5941ee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 25).', '[{"id": "A", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '024c6bdb7ac3f159_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('105d29cd-8e97-4fc7-9040-17c98a9fdaab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 25).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '3a02e23b58d19905_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5c1b08e-8bbb-42a4-85e8-669d8a453af0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 25).', '[{"id": "A", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'f99ddbcbcbd783dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d2ffc97-4bcd-409c-976a-18a6410e10d5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 25).', '[{"id": "A", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "B", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "C", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "D", "text": "Each host is configured with multiple default gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '8b8d1afec90f6030_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d207326-48fa-4c62-92d8-8325ed8398b3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 25).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '2dcfcc6dafb6dd2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4bbb047c-629d-4a34-977a-0895f51c5b5f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 25).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "C", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '4c4d2a66a741f367_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2dee0119-7205-458c-b31f-5b8f24bb21b7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 25).', '[{"id": "A", "text": "show route <destination> trace", "is_correct": false}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "traceroute <destination>", "is_correct": true}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'f1e38fc578dc7e53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b327cd25-830f-4624-b442-b11419a0da6d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 25).', '[{"id": "A", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The OSPF link-state database", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '30661cb572f4a2f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e92b2f0-901c-4e6a-8ee1-7965b41acc05', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 25).', '[{"id": "A", "text": "All of the above can be used", "is_correct": true}, {"id": "B", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "C", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'b7d70df093af8400_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1fda322-0145-40a9-beb3-8dee0f58ae63', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 25).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '717cf811762326f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('318b18c4-2f53-46ed-90f8-8fe30ed8cc8f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 25).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.58.141.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '643b19e492bd620e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2649c8fd-918b-444a-a5a0-0552cfca75f9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 25).', '[{"id": "A", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "B", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "C", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'b59b2b868f982c75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63be04b8-efb4-4d71-9876-02445b4f206a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 25).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "silent-drop", "is_correct": false}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "discard", "is_correct": true}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '228c38807f69a142_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('308bae24-8648-42c3-975c-ef8d7e420711', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 25).', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '129bbaec732fdc3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92d3f404-f89c-4042-8ad8-8cb9a6bbca89', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 25).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '492c732c72b18bca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddcabef0-0221-4272-b9a4-1574113e28ad', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 25).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "C", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "D", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '61b0c1eff2f834a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11ad0a5d-7d1b-42bd-98da-cb601f25d572', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 25).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '9603956ccfbfdaa2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('691b3dac-64f9-4815-aae3-6a83cb000c9b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 26).', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'b3ddd9ede3c4ca36_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30fe59ce-1c66-4c1e-bf05-e94f4a06fd37', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 26).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "10 seconds", "is_correct": true}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "40 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '0bbcdc40babb7bea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1317e2d6-163d-4e93-92ac-b5233d84d598', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 26).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '56e4c3a443fa1c31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('426c9828-d3d2-45cb-8f35-d0528717f914', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 26).', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '7db818fb10fd94cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3d5b596-50a8-4dca-a51b-90571fe5271e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 26).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '6f58e5a0bc2d28aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5afa259-e605-452e-a65c-76e465ec2064', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 26).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '9f4034f8879dab6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9be93ff-2775-4327-88fc-d5484a0b6c90', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 26).', '[{"id": "A", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '89f98db16e67a886_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff42554c-786f-452a-a853-f011a2a1d7d2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 26).', '[{"id": "A", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '3e63a23e64e12b71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35fefb63-1b1e-4725-bba6-32fa76c75555', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 26).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'cc3a2eb90e15c27b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4910a40f-7a44-4d5f-a075-9865fec85c94', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 26).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'e86bfc07125e8126_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aaec0a2f-0a08-4ada-a581-dedee4d418bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 26).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '1a69964b813ef95d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8be71c00-0350-4b8b-8885-b80ce97a7953', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 26).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Configures the local preference value", "is_correct": false}, {"id": "D", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'f5372460ce6c11b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef200296-741c-4bd1-ace1-8d1599c72951', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 26).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'b55e598f67d5418b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69547799-dfe1-4067-9f89-3d7e64843388', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 26).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "COMMUNITY", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "D", "text": "ORIGIN", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '2bc64bb81f191245_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('745a6c7a-c731-4d15-a2ec-d7dded56e8ef', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 26).', '[{"id": "A", "text": "The AS of the route reflector", "is_correct": false}, {"id": "B", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '8fbaa58758d2aad8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da5aad39-8a91-4492-af68-fc3845143c7a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 26).', '[{"id": "A", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "B", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "C", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "D", "text": "Permanently deactivates BGP advertisement", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '97a0a10ac0026684_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b51e8b33-e93e-497a-8c8a-3785100a0097', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 26).', '[{"id": "A", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show bgp summary", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'da275f991edf7f6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ddb70f6-42bc-475a-8a87-47fa68ff82d4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 26).', '[{"id": "A", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "B", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '0aea20e8748133ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec155112-6308-4ac7-994e-538f7a55fd40', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 26).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "C", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'bee7d3e14de70ac2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1b5033e-a611-45dd-ac97-2584262171ff', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 26).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'f23a65f0a9d03165_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0c4a174-8965-4022-a03d-bb108f927cb0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 26).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '22800b9f16e37e8d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bb5c473-c9ee-4d9f-981a-a11d06d6c23f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 26).', '[{"id": "A", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '645dadf43e36b0d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12070c11-2637-4e04-8a9d-8d161233b96c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 26).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Designated port", "is_correct": false}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'a6637040723c0735_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6fdc5e4-5173-4d08-b826-0d9b64e3e8a4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 26).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'b4fe8f036f9a6418_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87ac921b-18a4-43a3-9cbc-4b3cc286d804', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 26).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show bridge stp", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '1ba5d1c115da2d25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43c841a6-909e-466f-a1b3-2b46b6bbe844', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 26).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '6d62075b9ec5bb35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('702d813c-15ab-451e-9f18-29726c8f1059', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 26).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64520 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '057043293e888f7a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94fad8e8-443a-49f7-ab30-b1f8b3b0b2cf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 26).', '[{"id": "A", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Connects to the management network", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '9d4de45b8bf6ff58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9da94c47-f867-4492-af70-0af12d005ac2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 26).', '[{"id": "A", "text": "set switch-port access VLAN 482", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/0/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set interfaces ge-2/0/1 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface ge-2/0/1", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'e2f2e207413aa4a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d16ea986-6515-4ec8-9380-0251ef5a1129', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 26).', '[{"id": "A", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "65100 (16-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "256 (8-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'c35739fc18152096_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('037e9f28-88ce-4b15-aac0-e06c73b3d4e7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 26).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '15f95c8b4842dd99_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('846fc1b3-f316-4ae5-b6ba-1304777fdbcc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 26).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "56 (111000)", "is_correct": false}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "46 (101110)", "is_correct": true}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '674b262b9df4e0e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cc8855a-eeb4-40f4-a889-62d321736e54', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 26).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '3f290711cbd027a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a7e3884-5f26-453c-8efb-cae6e29dcfe7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 26).', '[{"id": "A", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'cc3ae4f3eb828322_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c53c136-4227-464e-afac-949b6e05eaa5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 26).', '[{"id": "A", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "B", "text": "set cos rewrite dscp 46 interface et-2/0/1", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'bfc65a5e94e2b20b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ce049a5-d73f-4c86-8def-27483a85f284', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 26).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '868d87b0ba2903b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee3e9910-10cd-4ab9-8bb8-bde6e00491bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 26).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'bc5edf175cd86dc1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6529264-37f8-44b3-95a2-4910d0eb8812', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 26).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'aca7e6ed97bb7dea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d5a9b0c-6fca-4c71-bb26-de954f36235c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 26).', '[{"id": "A", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '956733facd383e0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cfbd1b1-c0e6-4464-b0b5-f56b6e00904b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 26).', '[{"id": "A", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "B", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "C", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "D", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'e0bea9be49842dda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f54cffa-5658-4e56-b851-c7ae10744aab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 26).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "C", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '7a0c273359889449_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6820799-4be2-4fa4-947a-1fdc79443ba7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 26).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '81749fe796784f0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5293fa84-60b2-4da0-94e2-f39c3c30cd35', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 26).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '144ac09b8efe774f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b4a48db-8803-43fc-8419-c468d879aa3f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 26).', '[{"id": "A", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '4e85da4071417c26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a4d10b1-4a69-4365-8e1b-7383b0f49675', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 26).', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "ping trace <destination>", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '11147ab95a03b242_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd8527cd-bdbd-44ff-b68d-4a3e999af102', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 26).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '33a0e7385e9537c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4e7898a-041b-43df-817b-8946582ce71f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 26).', '[{"id": "A", "text": "All of the above can be used", "is_correct": true}, {"id": "B", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '051a13f4b1a27c96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36f83f20-c8f3-4238-8f1c-41ccffad7c7d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 26).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '5963a6e4389a4574_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('490ad5a4-920f-40bb-b2c1-ebb0b0375851', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 26).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.87.240.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '378e10a69c050188_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f76bb081-1700-40fb-af13-5464e8d4fd96', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 26).', '[{"id": "A", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "B", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "C", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'e481dd431e4530d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63e4c843-c1f3-4a47-add9-58eba8df8c94', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 26).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '97da92f086355ca2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2ad4c8e-43ec-49c1-9def-197bfbfe7aea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 26).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'b1bfdfbb028d7cf7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62cef3bd-d75b-42f4-a06a-61795181cde0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 26).', '[{"id": "A", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "B", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "C", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "D", "text": "Single switch acting as both core and distribution", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'a85bcf3d6b9adfeb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c1a40f3-7363-4f39-bbb4-d499a7945ab1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 26).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '43e313da680d5eb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b427f63d-42c4-4744-b1bf-cce853f1db0b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 26).', '[{"id": "A", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '9744cddd53f6d772_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b897f41-3400-4c0a-82ac-7d0e4d62ebd8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 27).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "Backbone Router", "is_correct": false}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'e04333f4b2a1fe7a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5c3cf58-7d63-4b61-ae6a-e0898bd2ea1d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 27).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '59d47ce0165d84bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8df98ebe-31a2-4395-953e-229ef0e2981e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 27).', '[{"id": "A", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "B", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '2199835bcd06f9f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c974f69-043e-4df3-a66b-18b2ca1d92b4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 27).', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'eb283d349204fea3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4deefe15-f625-4e43-b83f-37ecca0c3e25', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 27).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show ospf interface", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '594e36953f6b0b8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32899f55-067c-4233-a6ba-7fc4396e8b81', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 27).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '0f3d6fb2fdb231d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da7c1922-85b6-49f3-95b5-ff9c1fc51179', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 27).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '2d88022de5a0522c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14653f79-df1b-415f-a877-896e5240f9bf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 27).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "Both narrow and wide are supported by default", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '233b577ec5232358_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fff32e4c-ce74-499b-ba2a-01529fd21481', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 27).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Hello PDU (IIH)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'e86c279ba4290bfd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d844f08-3d1f-418b-9ad9-4069ad92f9cb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 27).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '5b288b70d1021c66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e8e1bb2-8e1d-404d-915b-4dfe6702dd73', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 27).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '689dab58a175c0b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cbfc2e4-a356-494f-a018-a49351d982b6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 27).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Configures the local preference value", "is_correct": false}, {"id": "C", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "D", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '2d08dadc9cdea4bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57eb5904-615b-49f7-9b15-a20ed6ab866b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 27).', '[{"id": "A", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'bbb7d410c91ce7a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a4636a7-7d7a-46ea-a55a-dab85315c192', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 27).', '[{"id": "A", "text": "COMMUNITY", "is_correct": false}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '30b90d92f2a6d85f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a840a49-d2b8-4aef-a272-a27132e83ed2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 27).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "C", "text": "The AS of the route reflector", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'f9d5a58411f08f23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bb7a440-3727-4517-ac96-868b6d6c5a5c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 27).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Permanently deactivates BGP advertisement", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '212c019508bc8f3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87e3802c-c5bb-4033-b45a-60afe693a92f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 27).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show bgp neighbors", "is_correct": false}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '4bbe4c8471280c2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6e431d8-79c4-4a59-81f2-6150c8e77fd4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 27).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '6c9043774dd46d35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e869782c-5cc3-47d8-a6c7-34e86ea2224f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 27).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "C", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '090f36082e306aff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('071f8809-c107-4ebd-8e2d-0e2da73dd8fe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 27).', '[{"id": "A", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '695f4e6fc8e07b64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('977e53f6-92f9-4465-95ea-6b55cbc5c5d7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 27).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '39c054d16ca89e68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76499194-66e5-43bf-a4f3-a7737b34dbfa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 27).', '[{"id": "A", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'f7455d660df9f943_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2526adf5-4737-4729-8a75-6d1618f3115b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 27).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Backup port", "is_correct": false}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Designated port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '9b7f9b4e84ecb541_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21e013da-e567-4987-91a6-a10b9978eef9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 27).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '968ee8fd558cc7b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a20b1b59-8c5d-4ec0-b359-ca7d923da960', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 27).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show spanning-tree interface", "is_correct": true}, {"id": "C", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "D", "text": "show bridge stp", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '926cfcffd33c5e55_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22de90a0-0391-4ad1-8fc7-6fbbf1aff300', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 27).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'c07f3d78425e826d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22448856-fd6e-4d85-9793-410c08f3aba0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 27).', '[{"id": "A", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64700 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '14d08751d9deef00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0ff6fbe-0a5b-42ad-aee1-062519af6393', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 27).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'bb792ad0f7de4d45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1437d93a-36aa-449a-b5ae-a309c3e3f4bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 27).', '[{"id": "A", "text": "set switch-port access VLAN 427", "is_correct": false}, {"id": "B", "text": "set interfaces ge-1/1/2 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/1/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set vlans VLAN10 interface ge-1/1/2", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '58fb2bee7995d77c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc8ca6c2-bb7c-4641-9d51-4688f486841d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 27).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "65100 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'd9f2cc0e82f7935c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b259dfa-a619-4b7c-962a-72721e893bc2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 27).', '[{"id": "A", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'ec175238d55c0e7a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16786ce3-7281-4355-a348-a49bb19b61f9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 27).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "26 (011010)", "is_correct": false}, {"id": "C", "text": "46 (101110)", "is_correct": true}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '58c7833038c421c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7f7aed0-d619-476e-a899-4182188d28c5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 27).', '[{"id": "A", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "B", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "C", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '31d7a6345505c6d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a7adcd7-1b7e-4173-9414-4112c359706b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 27).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '517fa58b13d7f3a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4bd24dc-6abe-4810-a151-afd0e04f6f56', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 27).', '[{"id": "A", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "B", "text": "set cos rewrite dscp 46 interface ge-3/0/3", "is_correct": false}, {"id": "C", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "D", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '49ae52fbceaafd85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('064ef311-9182-443f-9e2e-fa6f97c9454a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 27).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'c5aa984083f2385a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5b7ce06-1eb9-41c5-bfdf-67fe62e4d594', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 27).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "D", "text": "Carries multicast group membership information", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'ade125336d294cdc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63292927-c3b6-4e60-8938-27f46b356119', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 27).', '[{"id": "A", "text": "8472", "is_correct": false}, {"id": "B", "text": "6633", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '7b5663aea1bc28a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5c23dcf-8c2d-4f78-b06d-fa045a604455', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 27).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'ac12e5802b55e3b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('069b6347-c09c-43c5-878a-2e8a6044d96d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 27).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "D", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'd4fe60c04642fc2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b46b1c23-7b85-4a0d-985e-b32a38894c2c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 27).', '[{"id": "A", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'b2c155960ea24a9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a13ae24e-a0e5-4666-b81f-85fbc77387ee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 27).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '2c038d816701e550_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98c9899a-ddd7-43e6-8fd4-3bc2b0c868ea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 27).', '[{"id": "A", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'c8214b13cb8083fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25c113a7-42c4-4f5e-8811-6e553e74d103', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 27).', '[{"id": "A", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '2dc33d0484e252fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9deb030c-a9d2-4bef-b2a6-cc17a90e837c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 27).', '[{"id": "A", "text": "traceroute <destination>", "is_correct": true}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "monitor trace <destination>", "is_correct": false}, {"id": "D", "text": "ping trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '53f87badf63ca8cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bdbc80c-ed03-4192-86b3-b51126a700a4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 27).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The BGP route table with all attributes", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'fa6808f35655def0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5eb159e-5d34-4f2c-9846-0ff05a0c811d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 27).', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'f825646632024bd8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9be8b03b-df01-46d6-91fa-191c9e58ed9d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 27).', '[{"id": "A", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Replace the interface cables", "is_correct": false}, {"id": "D", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'd16811a32cbdc915_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('977c5d71-7fa6-41c5-ae5e-d5d49a87c414', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 27).', '[{"id": "A", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "D", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.42.141.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'd9237bce0146919e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e8524c2-a412-4a59-b12a-c7e0dec6eb17', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 27).', '[{"id": "A", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "B", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Defines firewall rules for packet filtering", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '280805d185fcb05a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26067212-087e-4902-9677-79c65ef23077', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 27).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '592aa9776ff0b2e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb4317f6-5517-4633-8e8b-696163d02a1c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 27).', '[{"id": "A", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "B", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'b69e731b2cf914b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c1efcdb-76e7-4356-afb8-8f4d84293bc9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 27).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '1ab2ac58a6d6dffc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1f8cb95-ff82-4b71-a0ba-bef270529d8c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 27).', '[{"id": "A", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "B", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '53d6fba86a7ae2ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c6a4be3-76d7-4a25-b862-48a42de8c77d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 27).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "BGP on loopback interfaces between the switches", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '24b15a9d171ebaf9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2d73580-c434-4884-97ac-67198cffb6b8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 28).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "Internal Router", "is_correct": false}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'b390efad72cbbcaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd901e0c-c161-48ff-b5eb-267593a3f321', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 28).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'eafc0ceb762bde54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08e166ec-e1fa-4ce3-8714-a3829ccafdfc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 28).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'd259b3f87809558c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb1d9d7b-027d-4cbb-8085-8b4bf3349b0f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 28).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "C", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "D", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '92d9196be5aa330c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8da00b03-e0d2-4ee0-829a-b26b03d5ff61', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 28).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '2f226ec5838e9ac7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be8e4315-9555-4b85-af7c-40b0cbb79931', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 28).', '[{"id": "A", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "B", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "C", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '10c9873853210238_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d840eb8-9f06-4b92-b1cc-32f65aaba98b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 28).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'eea3b0cb44e509ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e533d7d-7b51-40a0-b2f2-a7fe9a14f366', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 28).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '83c1982977be5d89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93d1f98a-b9a7-449c-acd7-b4d2b52f1814', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 28).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '697213b504ffe0fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44cbd4ac-dfbd-4085-954e-39e3181b68d5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 28).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '7a9e30bc4375c068_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa43702a-7001-4bab-9d19-f2f414879b69', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 28).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'e118afe13360f616_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54c4d3ee-f45f-4a89-9998-d02527499045', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 28).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '4bbb1a502e85322d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c2b88f4-2369-413a-a3e5-bcbb6dd3d7e4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 28).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "D", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'dbd8630d6804e67c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da232d44-c5ca-4a16-934b-a5a736ab9011', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 28).', '[{"id": "A", "text": "COMMUNITY", "is_correct": false}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'a4b55e654217a823_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fbb06e0-634a-4d53-9234-1fb340ed23bd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 28).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The AS of the route reflector", "is_correct": false}, {"id": "D", "text": "The IP address of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '684d0641d2263130_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36fb352e-3c91-4e7c-9a58-da927c47fee7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 28).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '5fdce6c90159ea39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6b44663-68a8-4f33-af62-5687052d7041', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 28).', '[{"id": "A", "text": "show bgp neighbors", "is_correct": false}, {"id": "B", "text": "show bgp summary", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show route advertising-protocol bgp", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '7be3c775adf257ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d7df732-851a-4674-befe-49f1d2c163db', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 28).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '84014c4641a2eaf0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27975406-25f5-45f2-9d13-f1368d7c1372', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 28).', '[{"id": "A", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '9acc507a319a1080_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b137b1da-32ef-4dcf-b48e-2a48f1ac9068', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 28).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '96b2cf04b77382bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71311f68-d8c1-48ef-a90c-a3e098d6ae41', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 28).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'be3043967a3c3705_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0c76bde-9f47-4c81-b4ed-231cd4a78d72', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 28).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '67b99983de461412_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('405471c1-04d5-4b61-aad8-a46752e04f53', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 28).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Alternate port", "is_correct": true}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '681757816c9d370d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e83c6415-5bc1-4c2e-8538-0331c4e520f2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 28).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "C", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "D", "text": "A physical link aggregation group", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '7bd7d0da639c8db8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14ec8cd1-9036-441d-8608-8c00af024b40', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 28).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show stp status", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '24e39189f4886d67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acbdb9aa-2b25-4c3c-88fb-000fdb1e0a85', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 28).', '[{"id": "A", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '7f28032932c017a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a257931c-e4cd-494e-ba44-695079303f0d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 28).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64513 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '99e23fd91799c1c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b1be5ba-792a-44d2-bad2-fe95fe48f2cf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 28).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '348c2e5e703d58ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3f3555a-f802-4c20-b0f9-30c7b83d2e1f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 28).', '[{"id": "A", "text": "set interfaces ge-2/1/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set switch-port access VLAN 269", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/1/2 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface ge-2/1/2", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '2d4064ce304c06e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10173840-c93c-4828-9449-abedc128aa26', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 28).', '[{"id": "A", "text": "64700 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "256 (8-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '0c224b896d1df50b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28825648-44e6-4b8c-9367-514d62592ff8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 28).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '259680f1ed90327b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96abd848-d8c2-4b59-aa91-9166efed3b83', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 28).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'c600db2c88ac49ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08d41dac-97db-4e1e-a56c-b4af74ea0040', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 28).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "C", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "D", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'c28f9eb30d9eeb2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5946ce7f-f0c2-4454-937d-948f54290f37', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 28).', '[{"id": "A", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "D", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'd7a71a3642fa6b6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51553e76-02f4-4ff9-b5ad-969b188eee0b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 28).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "C", "text": "set cos rewrite dscp 46 interface xe-3/1/0", "is_correct": false}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '19cf9bfdde1f5985_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d02a6f10-3f21-46bb-aca9-8d4198e17484', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 28).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '9d759624beeb433f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c37674a-8018-452e-a7cb-b1fc8d7e1070', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 28).', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '971cd50b2bc1def6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f5df957-b146-4647-9193-86a2e6b420b4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 28).', '[{"id": "A", "text": "8472", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '7ae488b0661178c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e739fc46-29ef-4f32-9d86-9244fbb66038', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 28).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '2b9105e4babb2521_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8ba3359-2a1c-40f1-bbb9-76f4b3940cad', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 28).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '3468c4fbe3f41a50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('504e8073-d458-4b0a-a847-37e1ea7ebeec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 28).', '[{"id": "A", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'b568ac657201e6e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59d1d20c-af88-4e28-a6ed-15572e45112f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 28).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "D", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'a018ca6575b2b614_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccd8093b-7a26-4163-9eea-0446759346b5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 28).', '[{"id": "A", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "B", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '82a668f257aeafe1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4fac126-9fa3-4484-84be-f3ba036e8fa1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 28).', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '8f917d11112a5742_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62b5b324-9310-4cb2-b93f-5696089efc68', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 28).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "monitor trace <destination>", "is_correct": false}, {"id": "D", "text": "traceroute <destination>", "is_correct": true}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '40c9b68bc2f4ac12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('caad6ed4-9f2b-45aa-bf99-b0b5c605a862', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 28).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The OSPF link-state database", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The BGP route table with all attributes", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'b07fda50d74b6444_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf3c7ffe-17f9-470a-aee4-24e5c93a95a7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 28).', '[{"id": "A", "text": "All of the above can be used", "is_correct": true}, {"id": "B", "text": "show route <prefix>", "is_correct": false}, {"id": "C", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '340ce2af200e6df7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b48c041d-9c3c-4f4b-8c46-b7bc48c25dbb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 28).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'bb643b1fef817839_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0c9c12d-6287-48eb-a795-17388dffbf3b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 28).', '[{"id": "A", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.129.52.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '7b52143299688c35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd806bf5-f4f8-4a03-b0fe-92e3a2fd55f7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 28).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "C", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '5b67cdd7a9ef77cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0327a08-e5ad-4e51-9cd3-bdff2c4cde57', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 28).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'c8729aae28b2a6f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('304346c9-a2c8-42d2-9c98-c95bfd212acf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 28).', '[{"id": "A", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "B", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'afdeeb012a11d4c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ed6eced-2c27-4061-a18e-931337f81279', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 28).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Single switch acting as both core and distribution", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '9eadff0157fbfe68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9a3b645-b90f-44d4-8bad-58a4616c4a02', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 28).', '[{"id": "A", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'ea699817d5465ed1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('289b7d15-659e-464b-8dc6-bf2489fb8a6f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 28).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'f05d4becf570d7a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb61552f-d28c-46c3-8393-6d90bea3f43a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 29).', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '6edb243a34e43b2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('374bb712-1ba8-4e35-aa26-4969bc549e22', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 29).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "10 seconds", "is_correct": true}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '4afecea0738b4847_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6652f6ce-2594-4b88-b89d-5649291ce959', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 29).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '3f7845df9f9ed5bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2eba44f6-976b-4a60-bbef-d6f78bbfb03c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 29).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "C", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'ff52f5fd36118acb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fa7563b-320d-4aee-9125-99617e9d7549', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 29).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'a3d6001df2425739_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9cfbbd0-f9f8-43fd-87fc-73fcbda0bed9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 29).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '2fd1a52cfae53ca2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a94b93e-8d92-4040-a059-bdeabb07177c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 29).', '[{"id": "A", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '2d55c0a0f4bcd2fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68dd3fe9-a523-49a1-9bf1-72a1dd36620a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 29).', '[{"id": "A", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'cc9204203ae434b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e636af1-16f8-47be-bfdb-0db54150f1c6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 29).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '950a4fe717e12315_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f27bbd55-331f-4bc6-9acf-160a87e1c3b1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 29).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '0ab8e00f697c10eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f57d5a87-47a6-4f29-be05-8081a468532f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 29).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'ce4fc9540eb6fe33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cc9dc05-fb8a-426d-a9ed-db000853d271', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 29).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Configures the local preference value", "is_correct": false}, {"id": "C", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "D", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '2d2f5f1dc490e368_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ad92727-1c32-415b-8a23-0baf3a94493b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 29).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '32d7e77035a0bd0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e25cf6a5-38d4-4192-a8e9-54c677fabef1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 29).', '[{"id": "A", "text": "COMMUNITY", "is_correct": false}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'b0ef5cd09770b495_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e07dab8-078d-4545-b30d-de91c4ce010e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 29).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The AS of the route reflector", "is_correct": false}, {"id": "D", "text": "The IP address of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '79e28dccf10a33ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('979c3ab1-c07f-4196-9057-f6b56631abab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 29).', '[{"id": "A", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "B", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '8db2a98db0ebcdce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0682a4b0-b4ec-433b-942e-cbe83b0bf8c5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 29).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '11cf445e0cd7631d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de71b454-b059-4f43-af39-166221e485bb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 29).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '8e5a836d6c27c0ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a289d462-9fbf-47ae-8cc8-11c65d45bd6a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 29).', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '802ad8aea04adf90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edcb0571-5cfe-4dc2-a4ff-193cc8a74918', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 29).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'bd129e54e08716dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63e35fcb-b62a-4b22-b29b-098e214f275b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 29).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "C", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '15e8897315e11d31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6c95e10-cd01-4430-9786-fbf04e8106ab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 29).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '5b77dad3b8fafb41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a5dddbd-3f88-47d4-b53f-bdc10ed2fda0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 29).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '216b31dd20c492fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7599dbaf-1fa8-4f48-b056-eaadbd4e9e2c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 29).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '267d6a4590c3ba79_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee44bf54-5f9f-4f6f-9a0a-516c7d51ff39', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 29).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show spanning-tree interface", "is_correct": true}, {"id": "C", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "D", "text": "show stp status", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '1d602bde8b165936_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f44d269-2dc5-460d-ad60-7c98ec18e22f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 29).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'c484859e6fb6f8a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be8db6ba-4841-45f7-b5bb-6fd43f56219a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 29).', '[{"id": "A", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "B", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65300 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '0efca1e8cb75d859_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81fac3e8-5820-43e4-a1fc-818f835e2ba1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 29).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'c02d8b5c44a7d5ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('977ec8c1-c51a-4c9a-8c93-693e9a0680b1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 29).', '[{"id": "A", "text": "set vlans VLAN10 interface xe-3/1/0", "is_correct": false}, {"id": "B", "text": "set interfaces xe-3/1/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set switch-port access VLAN 69", "is_correct": false}, {"id": "D", "text": "set interfaces xe-3/1/0 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '9ced359d99fdf3c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbe16194-3182-4f29-857b-f67f57a1a78e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 29).', '[{"id": "A", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "64514 (16-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "1024 (10-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '9af4243681e6fad5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5673f402-7bd7-4358-bd99-5bff3be9d6b8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 29).', '[{"id": "A", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '4f550b46f88b3a2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61d25a7c-a8ad-4c9e-9161-27585eb445e3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 29).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "26 (011010)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '5d0e4ef8c9ab94cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c55a70e9-6819-42a8-b0ad-d9c486847f02', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 29).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'c2a7aebbb9b36407_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48ddafe0-60ad-4d8a-b153-4a60138bdf72', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 29).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '214936a3c9bb384d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9990aeb0-1bf1-4cd4-9947-f190adc4277f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 29).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "C", "text": "set cos rewrite dscp 46 interface xe-1/0/0", "is_correct": false}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '869596bc2f9a6019_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59aec1c9-f0b9-49bc-86ce-bdbe29ac9cbe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 29).', '[{"id": "A", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '234c945dc8e12886_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c54889a9-dc68-4b98-9c9f-49e9903632f7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 29).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '7bf07538633befd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4a4c028-8d10-455f-a6be-0b112e328d55', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 29).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "1234", "is_correct": false}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '5b6fd59e238db479_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e486700-2b28-4f1e-8300-76afd81dccee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 29).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'cfa16cc4321ba1bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d3e75ab-7b62-4825-804e-68303b4caed8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 29).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "C", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "D", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'f01459a2ef33cb32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('037e40b3-3fb8-425c-96d7-83af3325c9c1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 29).', '[{"id": "A", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "B", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "C", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '4677401ab5aac93c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ef0efbf-a081-4cfd-b1f6-d6588d04ffcd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 29).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "C", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '8bf6f1ed6e0549ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0cd763b-e9b4-431d-8fb0-0d2629a8ed8d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 29).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '8b26893824d8f7ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3daa0bd1-5723-403c-93a9-8335d00861ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 29).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'b84368e9127423ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6434bf75-6c85-4269-b138-76c53fb19dc3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 29).', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "traceroute <destination>", "is_correct": true}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'd501b908d1594ba2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f1b8f28-7d1c-4bc8-8311-d738e73f0517', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 29).', '[{"id": "A", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "The OSPF link-state database", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The BGP route table with all attributes", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '02f1589613a45986_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42016d9f-df9a-495d-ae7e-0f2c0b72ca20', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 29).', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'b6d1a18ffe93a44a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c928624-6e94-4ba9-a9fc-b70eb59d71d1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 29).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '3f8b42d191454233_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca26a4c5-6cb3-4cf0-a384-90ae1acb2667', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 29).', '[{"id": "A", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.54.163.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '3fc75adb48e3c2fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de3d03ea-83ef-4437-a8fb-2d615aad2ee1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 29).', '[{"id": "A", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '65df0b9748730d1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69fad381-9bef-4d61-9793-35f4e164419c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 29).', '[{"id": "A", "text": "silent-drop", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "deny", "is_correct": false}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'cac813d732ecc32d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18d80b7b-98af-47c2-aa48-921aedc8bd49', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 29).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '43afd2e64c8afcc1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7df5e025-d8f3-4085-81f4-828a67c4bd45', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 29).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "D", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'd46107d7ae054651_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59fe4f95-b8ad-4ddd-8b33-562268eff8d6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 29).', '[{"id": "A", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "D", "text": "No BGP configuration is needed in the fabric", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '520d994327239b6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('658f419e-0942-420f-9894-81f519d2855b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 29).', '[{"id": "A", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "BGP on loopback interfaces between the switches", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '0a794287032eadde_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94279dee-f101-4579-a612-7822daab7c0a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 30).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "Backbone Router", "is_correct": false}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '5fe41b61d99f7195_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('120dc864-67ca-4ef0-8539-11edfbe134a8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 30).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '1d91ffe94f096513_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed41ec8a-b4f9-44be-ba99-373968464ddd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 30).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'bfc4cd1d65c441c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edaef336-7882-460f-973d-ad7bcfb44a23', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 30).', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'adaff0bc4cc736da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9391aeb-a5f7-41cd-b8cc-5fe6f3f86f69', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 30).', '[{"id": "A", "text": "show ospf interface", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '62c50311ecd1746e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef521be7-9c5a-4ccd-a93b-69075463d7d0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 30).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'd212c6ed419edf2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b6971d5-b88b-4118-bc9e-9e336e42da8a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 30).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "C", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '053d152541ec77be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c614f7b-0f30-4668-bbe2-e4b3ed325f57', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 30).', '[{"id": "A", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '80101d8eaa017ddf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35c9f2a2-7ec5-4c10-8139-ac86c7557cdf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 30).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'cf49f3421823ccdc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4702254c-8c32-4006-ba15-2b3e994dea8c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 30).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '912a23042e42b1de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7dcc3cb-8827-469d-91b9-d99bc90485e8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 30).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "64", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '40710033aeb972ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a54b03c-76ae-429f-b6e1-f4ed8e6d9e31', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 30).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'd17db9f40c93568a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dd5e75c-7848-4049-9d4e-3b981fc7e5e3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 30).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '7c50cc308867eab7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5baa9051-0934-4c23-8a57-2ba921722427', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 30).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "COMMUNITY", "is_correct": false}, {"id": "C", "text": "ORIGIN", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '8d2738b3beb2c225_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7d5bd6e-b100-4453-b054-3b50f720cf27', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 30).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The AS of the route reflector", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'a998b852527ad231_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f98edbd5-dd98-4b04-bc64-232bf1367a74', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 30).', '[{"id": "A", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '10438343dde0c01c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e5db5a9-f647-4d9f-80f0-f86f8651580d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 30).', '[{"id": "A", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'dc08af34e548827e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd7c8a9e-38dd-4286-b7a2-89e163575b1c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 30).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '6fa364654d09f505_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('931851fb-a2cc-4ade-867f-f026f7697bd6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 30).', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '2f6c598f813daf40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b56d21a8-b8f5-453e-b47d-e29cc23644d7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 30).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '6af217ad06f8bfe3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cef25cee-b4fb-4c29-a327-b92df439720f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 30).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '928ddb6a9291baa4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39c45558-0407-4b33-818b-d5669941831a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 30).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'be4786a3e8793f23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e96177d0-4abd-4e62-b1ea-e68d9cb2b2cb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 30).', '[{"id": "A", "text": "Edge port", "is_correct": false}, {"id": "B", "text": "Backup port", "is_correct": false}, {"id": "C", "text": "Alternate port", "is_correct": true}, {"id": "D", "text": "Designated port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '9a917744ad884f30_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('453eb265-49f6-4886-a7d2-2a0c140527c8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 30).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '709bdc510c88169e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8315e16-a710-439c-959b-a646d9c32de0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 30).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show spanning-tree interface", "is_correct": true}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'fb98572400ccccb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc875a32-0dea-43c9-9361-8a8af790525c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 30).', '[{"id": "A", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'c30c2d57e728e759_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06bf0495-c5c0-4111-91a0-c09a2c70e39c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 30).', '[{"id": "A", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64600 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '2c5ed3a7a1ad400c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63160da3-9ed3-4600-8d55-f911186a31e1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 30).', '[{"id": "A", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Connects to the management network", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'c9da7a7852279feb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('224d9ad6-e014-49e3-967c-657d58242046', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 30).', '[{"id": "A", "text": "set vlans VLAN10 interface ge-3/0/1", "is_correct": false}, {"id": "B", "text": "set switch-port access VLAN 165", "is_correct": false}, {"id": "C", "text": "set interfaces ge-3/0/1 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set interfaces ge-3/0/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '3c13b7000d40924a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f968662-4d86-491f-a691-dd2b95d763e8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 30).', '[{"id": "A", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "65100 (16-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "256 (8-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '39f635e7a72fe69a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7818a10c-7022-46d0-81b9-ef1b790aaa77', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 30).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'faee091b25caf58b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66a107b5-5e6e-4085-9f5b-9f60e753fd9b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 30).', '[{"id": "A", "text": "56 (111000)", "is_correct": false}, {"id": "B", "text": "26 (011010)", "is_correct": false}, {"id": "C", "text": "0 (000000)", "is_correct": false}, {"id": "D", "text": "46 (101110)", "is_correct": true}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'd78dd39f0b076f61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34ae1b5a-e1e7-4b00-bfd1-e63687ed0e29', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 30).', '[{"id": "A", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "B", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'b66e94dfa873ca2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25c4dd2c-b6a1-4f4d-84b2-ad22504345e9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 30).', '[{"id": "A", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'e09399a14550b1e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e346fad-e2dc-4e0a-94d2-7aeeb88c76d2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 30).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface ge-0/0/1", "is_correct": false}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '34c70600ebd95b64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c76a2e6-985b-4b4f-a6a1-18439e4d58c1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 30).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'cf7ce9593067d373_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc466cf7-1170-4bf2-81de-0919668d4ee0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 30).', '[{"id": "A", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '23a1be8b2ec83fc8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0fe6b8d-fcf5-40f0-8a78-2801f9f8d92b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 30).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "8472", "is_correct": false}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '046973897cc0f35d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82f04066-c43a-44ee-a4d5-0e733dfdef1b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 30).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '3c614ae114c9b467_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48da4578-5f88-4b4b-9a79-b37eec9604c7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 30).', '[{"id": "A", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'f2677eefdd7d2097_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('679c746d-3abd-4811-9576-fb8f0aaa14b5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 30).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '877b79a43ae774ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d2377e3-56e8-4c60-8ee5-f8f94436e05f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 30).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "D", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '29d5a61c82a2433a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3cd2474-1f85-4e0c-847b-c818f5b45884', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 30).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '15dd0b8994cb92f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b955f4c-2018-454f-b81a-5607c0b81578', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 30).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '5f0ff30d75531c8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d64926a-484b-49f9-bf96-04d45f1eff12', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 30).', '[{"id": "A", "text": "show route <destination> trace", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '37cd2fad6ca3cfb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('284ee0ad-a65b-45ea-b298-b6403aad18a6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 30).', '[{"id": "A", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '77e20adf720115e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a22f5d21-e0da-436f-83b3-314444f1def6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 30).', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "show route table inet.0 <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '39ff65cd781755c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('adc795a7-402b-4c20-a2a7-2c7af6d3b7ea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 30).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '1b1f555a67e831a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('546c7105-c5a7-4516-93d7-772ec8ab91cc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 30).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.145.167.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '9534179b07a6d56e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c945481-e157-4c89-b9e6-18d7ae5fe133', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 30).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines user engineer permissions to the device", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'bfda394b7cf8d37f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4f89a31-c4cd-419e-8f0d-af317f3d7ea7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 30).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "deny", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '642810755c692961_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00cfb366-a6b8-4eca-ac3e-003f11c2ba30', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 30).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "C", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '1d40bb387558ba85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('535ef11d-9f19-47bf-bebc-cbc039389fd8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 30).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '29d3ad1244cb56e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9de6e8f6-fd5b-4801-bee6-c8bf7e648486', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 30).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'a83b896f288e1348_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a185a6e9-1559-4a34-9ad1-9c4f90085c76', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 30).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'ddbdd6ef2dface5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('45ea16ca-f573-4f77-a30f-1b940c0fd08c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 31).', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "Backbone Router", "is_correct": false}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '7de56c305779b4b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97d3be6c-e484-4390-a6da-cee66076c949', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 31).', '[{"id": "A", "text": "120 seconds", "is_correct": false}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "40 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'f939be68d989be1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98d43f9c-8866-4060-81fc-28951965ce63', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 31).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'df8007a93d1c4033_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dee61475-0f4b-4319-bb9f-58ca8d4d8379', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 31).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '55b9f51a07ddebfc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f07af60-0871-4fe8-ae85-1588a90f7866', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 31).', '[{"id": "A", "text": "show ospf interface", "is_correct": false}, {"id": "B", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'c32bde136067f98c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bb73e16-a8ac-4a46-9010-ed178f84c5bf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 31).', '[{"id": "A", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "D", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '3799e17b7ecaa636_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acd64cdc-53ae-409d-a089-26ee34d38d41', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 31).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '14171d7d3e7f0bb2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b959451-c1c8-4ebb-be30-f4fbc99cc3f0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 31).', '[{"id": "A", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '26d248b4acc3d5cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71e8c1d8-80d0-445e-b1c4-cea8f5bbdf3c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 31).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'b4742fb17d3918ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87941326-d8e5-45ab-a56b-bb80ceaa7be4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 31).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "B", "text": "AS_PATH", "is_correct": false}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'd66c8d7c866850b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4010cda-8558-434a-bd77-c280359a3f43', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 31).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "C", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '9416eb631da9bced_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('667b0eb9-e70b-4b8b-97ce-c21cff5534ed', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 31).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Configures the local preference value", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '54487a8a0c71e6e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d432601-b1b4-49d5-af19-2cf5224b16bf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 31).', '[{"id": "A", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "B", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "C", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '70799c732f8b7df0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99e8db25-2104-4196-bcb7-3b890fe0c44d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 31).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'b013c177d15a383f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a51c5e0-7652-4d7a-acce-3aa13017161f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 31).', '[{"id": "A", "text": "The AS of the route reflector", "is_correct": false}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'ed55c13064ab8560_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9057d45-bb0d-48f6-a577-b853eb8d308b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 31).', '[{"id": "A", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '46b16da2f49bd1ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('125a9613-8816-4170-84c9-80bf3bef16ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 31).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '8ab8d62104920a03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b6a67cc-898f-41c6-96c8-09b2df25f7f5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 31).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '4241f678421b777b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('599c603d-8afc-49be-bc94-6d1b80b859e2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 31).', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'e6610b6ccc455fa8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0587f448-840c-46b2-a1b7-78ab9f5c7d8a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 31).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'b161a29a1a5491fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('304179d6-525f-408b-84cc-67643417e997', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 31).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'cb506a852f17c117_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d590752-a849-4a3b-9f0e-8a2169b94ca4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 31).', '[{"id": "A", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '2ad3fadb0920cfa6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48bfd4a5-0397-4963-b6c1-4b0fcc2e7cb6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 31).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Edge port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '954e4206110923fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ea08a8d-0097-4cbe-8f1a-561ff0b6f048', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 31).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'cfbc4d1ec27892a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0835c135-601c-4f47-8e26-5c062a61f3a4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 31).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show stp status", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '361a476c2462cdc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7495bf3f-28f9-4885-8dae-b800369357a6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 31).', '[{"id": "A", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "B", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "C", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "D", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '9e3f281218c5ceeb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('341cbf01-5dda-4806-b992-726d2b0a00a1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 31).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64514 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'ca0988fec05a9312_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c4fcfe9-f092-46db-8a41-63ac28562629', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 31).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '8e81edbb3a7c38f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1c9dc03-d169-4de4-98bc-da6c1a0df715', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 31).', '[{"id": "A", "text": "set interfaces ge-3/1/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set switch-port access VLAN 240", "is_correct": false}, {"id": "C", "text": "set interfaces ge-3/1/1 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface ge-3/1/1", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '5bfcf29039754443_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35640c4f-6518-416c-b9cf-741dc6c6a43b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 31).', '[{"id": "A", "text": "65000 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '34fdd3f393c6b7b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7d5d8b7-7627-4d33-96ac-3c3994739221', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 31).', '[{"id": "A", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '884e685e348c06e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b3247ce-da83-4b7f-bcf9-df76bd16cf94', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 31).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'da1e3c458dfe3f7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43018f02-77d2-406f-a94c-52a16c73bcd9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 31).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'c8ad2102ff5bfce6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7f52c9b-4128-435f-9897-a98152ea90cd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 31).', '[{"id": "A", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "D", "text": "Determines which packets are forwarded first", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '13ad499365c381dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9878668a-b7ba-44c2-8edf-ea3fcdba76de', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 31).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set cos rewrite dscp 46 interface et-0/1/0", "is_correct": false}, {"id": "C", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'aec4438d924e7f68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9da640d1-3d1b-4ddf-88f5-1c8b4c811da0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 31).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '4aa56af67309e58e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b836964-e42f-48bb-a3f1-5f8392fff3fa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 31).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'fc329fdea730a9e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5541fe11-94d9-4105-a665-9fb7dcfaa4af', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 31).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'f6219b67d99ddfc7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0476af7-57f5-4eaf-bcb3-d840d2df47d7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 31).', '[{"id": "A", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '298198b42d3a887f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32e5b9c4-28de-4b7c-a77a-6770e82c00d7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 31).', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '13710e84a650c74f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96acbe5c-37e0-4c7c-a8cd-96458ee397ae', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 31).', '[{"id": "A", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '527a8a2ce234cfda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69a0a7c0-138c-4a46-b396-75ad2e2c72d3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 31).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "C", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "D", "text": "Each host is configured with multiple default gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '859257361e39045c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58b3ba19-5685-4321-a404-672386b75e23', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 31).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '9ece3ddd0c633b8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4fdc18c3-b694-4edc-91fe-9f614846e069', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 31).', '[{"id": "A", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '39d398a0f503ab35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22dc32c2-7d3f-48c4-b8eb-9b9ad8f94917', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 31).', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "show route <destination> trace", "is_correct": false}, {"id": "D", "text": "ping trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '87f61b3d4f5d41a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43ba74a7-cec5-4037-bc9b-eab8f01f0d65', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 31).', '[{"id": "A", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "B", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '8c4d51198c412ff0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43f09d07-a43d-4663-965c-7d151932b11a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 31).', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "show route <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route table inet.0 <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '9e013e7f6ddf409c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9ec7b35-d315-48c0-aa6c-9d7bbe312845', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 31).', '[{"id": "A", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Replace the interface cables", "is_correct": false}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '46aeb16e2b10abe2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce470ffb-62d9-481b-8974-65e2136915a9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 31).', '[{"id": "A", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.225.23.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '7d3ec4ae74507c6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b1099d6-168f-4fbc-821d-d0080927e47d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 31).', '[{"id": "A", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "B", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "C", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'c8a737e39685b47d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63b0f78f-9991-49a4-acf5-b1956ea24da5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 31).', '[{"id": "A", "text": "reject", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "deny", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '4a04814e612ca844_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8060556f-f619-403c-9f31-3ddbb455735e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 31).', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '969a4c1a73a4b6d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0010f4c4-e3a6-4607-8092-c9bcbea2242a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 31).', '[{"id": "A", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "D", "text": "Single switch acting as both core and distribution", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '03f0afd2732ba791_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cacc543-7b27-4991-9d4d-33ef7b7c6ba9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 31).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "D", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'dbe45f7aa2b0c66c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d897b465-8a34-4408-adea-c32ee7420798', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 31).', '[{"id": "A", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'd32d3c2255fad411_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ab8d225-eb07-4729-9e6e-88431c9e99ce', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 32).', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'daf59c1a505c9dbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9507c26b-0d93-4e8c-bb67-86c76da3738a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 32).', '[{"id": "A", "text": "120 seconds", "is_correct": false}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '521a9f713a6c896d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b604a6b-59fb-4112-a2ae-1e2941ae0628', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 32).', '[{"id": "A", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "B", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "D", "text": "Connects to external routing domains only", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'd598f25aa727910e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8884e0d2-57a5-4f0d-9c80-ced40e1f4956', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 32).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Advertises external IPv6 routes", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '4ff5b9408901f1ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9db488a0-0523-4704-870d-2e38b2a51d7c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 32).', '[{"id": "A", "text": "show ospf interface", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'b059608e800a0912_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de9f3975-0650-499a-a136-4cb4435b34fe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 32).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '533210cb53d798fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f435d90d-da50-486e-8479-eba21672c4b5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 32).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '06ebcbf5039177d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e11b46ed-eb7a-4709-95fd-c4809e8769a5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 32).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '8427a1a22ba21b15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8bb88f51-0507-46f3-b98d-c4bda28a981b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 32).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '73d4027c2fbb99fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c84fe998-1d76-4a74-9cda-12594eefc909', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 32).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '3383098939e490e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7feadce-72ce-41f8-b0dd-5520b233652d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 32).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '1c2d3b79ebb3e58e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8b66636-73a5-4845-a62a-5f754ad94eea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 32).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Configures the local preference value", "is_correct": false}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Sets the BGP router ID", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'f432208ec820fa0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('344ef3d2-735e-4795-aabc-bd4045cc6809', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 32).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'f61183585c4934af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af0bb15e-c7db-4022-8597-be79bd8e9e47', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 32).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "COMMUNITY", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'ec352240deb21a30_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('643f14ac-8b5d-409b-9134-25c9d25bcd80', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 32).', '[{"id": "A", "text": "The AS of the route reflector", "is_correct": false}, {"id": "B", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'dc291cb2de2f140a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1039ef6d-02d2-4614-b6f3-001319f48f87', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 32).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'f42b5e62d5df8dc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6215b56-a9c0-49d0-add3-63768fc63877', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 32).', '[{"id": "A", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "B", "text": "show bgp summary", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'a84c068ffc59dd1d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40c8d3c3-9dc2-4781-9464-ec8ebc4e5e73', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 32).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '0aca9372aa22ef07_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05ba4976-b7ea-473b-bd4d-e429b182d2c0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 32).', '[{"id": "A", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '6c440de76db84d4d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('245c2f3e-72b7-4872-8fac-75af77f58781', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 32).', '[{"id": "A", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "B", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'b1af7c05a0db3d72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e805d7f0-8886-4e60-ba1d-56f0e244c154', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 32).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'a13e5f4a0dabeaf3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('046f465d-6eb8-49e7-87bb-7232bfd01816', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 32).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '1430f603cc0bd66d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ce711f4-a64a-46d0-b187-1bd87260b8b1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 32).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Backup port", "is_correct": false}, {"id": "D", "text": "Edge port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '856eb0a57f76efe2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18f7bcb6-2bfa-4796-b2ec-e0bebbd89cd5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 32).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '2e2b914b9abd379e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('812f742a-c2da-4ebd-927d-a3d916d8644c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 32).', '[{"id": "A", "text": "show spanning-tree interface", "is_correct": true}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show bridge stp", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '338918c2feb65740_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78fbd751-66cb-4d33-b6ff-d52bc96b5d60', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 32).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'df8d5a2821d1f8f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b66f06d1-0541-482a-9782-db083a80bfe2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 32).', '[{"id": "A", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "B", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64800 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'bbb954b09dc043d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16ba283e-f485-460b-b464-fcea6298f1ad', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 32).', '[{"id": "A", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'a2fb5b65deb99cdc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2ea650e-ee92-4669-b919-3b4c4acfa45b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 32).', '[{"id": "A", "text": "set interfaces ge-2/1/2 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set switch-port access VLAN 188", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/1/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set vlans VLAN10 interface ge-2/1/2", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '709aeacd9edc5c0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed5d6fb6-8788-4ad3-9cb9-047cbbe69cba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 32).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "65002 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '72190b1ee70f9c7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('979ae624-e03b-45ba-8740-c7f4cdc31c6f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 32).', '[{"id": "A", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'ffee95a95c3a4c10_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19d6645f-4db0-4793-b948-219482bbe3fd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 32).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "46 (101110)", "is_correct": true}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'c85c04f9da121675_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c57dc0d6-3b5b-4af9-8604-c0a7fa5b13c3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 32).', '[{"id": "A", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "B", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'c05f17e4b5519a6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ca557f3-d47f-4433-9e91-fd5b0eeb4318', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 32).', '[{"id": "A", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '5bcb0e16aa4719d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('223a788b-b8ae-4f9b-b79e-21c8d5c995b8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 32).', '[{"id": "A", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set cos rewrite dscp 46 interface xe-1/0/0", "is_correct": false}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '807bf6f9fb779810_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ce2cc56-f1da-48f5-916b-38aeac523971', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 32).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'f7fe82e96d6cae10_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b2b6119-266a-4d67-8e2b-f19dd58e95d9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 32).', '[{"id": "A", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'd751a6aaf35062e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('451b8526-752b-41da-a281-61b3f6bb96e8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 32).', '[{"id": "A", "text": "8472", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '5cfa9a7a685aa681_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9f89b8f-217a-4756-8e3e-02d6844b4fdc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 32).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '37c2986cf937da8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('672bc4d9-9065-4fbe-8ae4-9bbb3ec65bad', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 32).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '1d01ad3a44d2d4eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('caf89e79-78cd-421d-a84e-1b5f47bd659a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 32).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '1c688781e76d7637_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60d11da3-4bd5-49df-b3e5-d2e686a81c89', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 32).', '[{"id": "A", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'f812e40709dcc10e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1110cb35-2f5b-4b9c-8e0a-77efa9a9109f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 32).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '150babbacc45d91a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bc75115-561f-447d-9533-115bf244d342', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 32).', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '929793eac0f6b88e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0788c1d1-ff4c-42fd-8502-06f35bf615b9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 32).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "show route <destination> trace", "is_correct": false}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '1cff9af1c258b14b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba140b16-eca0-4b95-afe0-7edf0ddf563e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 32).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The OSPF link-state database", "is_correct": false}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The multicast forwarding cache", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '4e193cbbd4ad81d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b964eff6-dba2-4937-b1a1-e28439cd7815', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 32).', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "show route <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route table inet.0 <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '589ba2e1c1bd80af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59d2a4d2-5c0c-49d7-bdfd-e3f99eeef8c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 32).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "C", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'adb96b66a99e7fb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70677962-a2fb-4658-8a04-06b48fdf7477', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 32).', '[{"id": "A", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.133.129.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '6fb445b6f63ad315_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9c5ee3b-0b11-4032-8147-268f531eaf5a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 32).', '[{"id": "A", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'b84bf9fe87423274_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c0d8cd3-a6dc-4123-afec-c6611a3a588e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 32).', '[{"id": "A", "text": "silent-drop", "is_correct": false}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "discard", "is_correct": true}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '1e4cb13c0c7ca3e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f7d3f9f-b0f1-4450-a07b-764ea88ef1c8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 32).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '59171cce7f37f293_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a431104-5bdc-4cb0-b158-1b5f7902dff0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 32).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'b42c992026091ff6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4c6113b-8e2e-4b01-870b-d1c6cee30e33', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 32).', '[{"id": "A", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '248ec56d16b8ef94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a2cf205-a1ea-44fc-83db-cb2b7090fbd1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 32).', '[{"id": "A", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '0520f87ffbf97312_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f3a3e49-f267-4e80-b065-c1aaffea8d8f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 33).', '[{"id": "A", "text": "Backbone Router", "is_correct": false}, {"id": "B", "text": "ABR", "is_correct": false}, {"id": "C", "text": "Internal Router", "is_correct": false}, {"id": "D", "text": "ASBR", "is_correct": true}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '04c10ab0547179c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c66b29a-2c55-42d5-862d-bd2ff073c66c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 33).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '2e94eed6d0fd7ade_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('416e2e7a-1cdb-46a7-8519-8737023b9084', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 33).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '2b6aa280252b288c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('422291c2-b265-46e6-bf5d-7fdbb3fe039b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 33).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'f4583535daa2aa04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a5d9f96-78a6-4a5f-97bc-3b09a1c4a802', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 33).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '49905b22a9ae45e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c990b5dc-a655-48da-a1d5-f93953cd3005', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 33).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '9527496f355f0921_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05fbd55a-164d-4ed3-9997-15101cf100e3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 33).', '[{"id": "A", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '529a3d6985d50607_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3b0fe18-66c2-4456-ac24-3303e966e696', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 33).', '[{"id": "A", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '7cdaa2adc1cfb9e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9649c34c-f7cf-4ecd-9051-53d9efacf6f9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 33).', '[{"id": "A", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '22e276d435f60695_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2226ce5f-4d4f-4d0d-a08e-57c02c9859bf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 33).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '3003478b3ae60418_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc5b6255-247c-4f8f-83bc-cad7369f0c9e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 33).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '1daacfd86f1846cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72ad0812-ecea-4554-af13-9062ad5650de', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 33).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Configures the local preference value", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '583165141bcb5738_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a7ab4e9-2ed4-4340-91e0-13c18e64ac34', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 33).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "D", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'd5a2cf03cb3abc9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4771703e-b940-4b66-9ecf-5cde5c951ab5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 33).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '071c95644c34b35c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('580d1170-190f-4335-b141-e52dbdd06e2a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 33).', '[{"id": "A", "text": "The AS of the route reflector", "is_correct": false}, {"id": "B", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "C", "text": "The group of route reflector clients", "is_correct": false}, {"id": "D", "text": "The IP address of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '2118d42a20d68009_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50133187-2e5d-431c-aced-a5279cdf1d47', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 33).', '[{"id": "A", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "B", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '1f88c2ed76452f7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b48004f-4fa4-4c15-b3e8-27394948638d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 33).', '[{"id": "A", "text": "show bgp neighbors", "is_correct": false}, {"id": "B", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'a5183c98d1cf3b4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ab556df-5437-4217-9973-c64c8cc68a92', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 33).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'a8f462e172931940_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f708e16-404b-4d64-a4f2-4caeafda78f8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 33).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "C", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'b0b5a0153bca7114_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fb612ed-0203-47f5-89eb-9bfd2537e0df', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 33).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'e0f7ca6235a5c158_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aeed944f-1a40-4b47-b618-0c9af1d2d3e0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 33).', '[{"id": "A", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "B", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "C", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "D", "text": "RPF is not used in PIM-SM", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '1dfb50451e7c5ac6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66de80a9-87ff-42e2-9cbc-597dbcae5ef3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 33).', '[{"id": "A", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "D", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '6630891d666e62c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9d47e7b-2fad-44e2-af6b-e69341bdd7e6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 33).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Alternate port", "is_correct": true}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'd3740c123979b447_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c940893f-b3af-4e27-a1ba-dc6c5eefad1a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 33).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '6692a504a795bab2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('136acdbd-b83d-4c58-b8e1-a138607f2102', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 33).', '[{"id": "A", "text": "show spanning-tree interface", "is_correct": true}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '7c4ce45edc89f378_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0efc16dd-8152-40c2-a7b0-40b9f38dab84', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 33).', '[{"id": "A", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'f918f0035e1c7677_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e7897d3-d548-4851-9061-ddfae9971ed0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 33).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65001 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '1af73f526a8b4787_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e4a3618-0bc8-40dd-b738-fc6c84ff580f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 33).', '[{"id": "A", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '35adc3eb4117ff6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ded2ac1b-8e58-419f-8b52-15192c17e937', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 33).', '[{"id": "A", "text": "set interfaces xe-1/1/2 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set switch-port access VLAN 49", "is_correct": false}, {"id": "C", "text": "set interfaces xe-1/1/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set vlans VLAN10 interface xe-1/1/2", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '6781d094038a8ace_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dad2d61-c5a1-4a8f-a3de-b583f6a8c2a3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 33).', '[{"id": "A", "text": "65200 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '81c080c95883238a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e22f85b3-b9af-4447-b3c9-7ed0ac7e21a6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 33).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'd4a9214a9512fc12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26b5350e-c807-4096-b662-85c89777b0ad', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 33).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "56 (111000)", "is_correct": false}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '93832bd682d001dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5d12648-b3e7-4d39-9ece-eed29df4ee2b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 33).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'ba684b14c3545dd8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7af3115-4223-4a9d-93bd-5c501a63b076', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 33).', '[{"id": "A", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '85a00ade4bf4e8d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71ea771d-31f9-41a8-9e62-5d3aeab32c6a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 33).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface et-0/0/2", "is_correct": false}, {"id": "B", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '91e8d71630839726_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4dcf593-58fe-45d2-8bb2-dd86f647a8dc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 33).', '[{"id": "A", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '50fd9b6db09ec777_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fc7e3c1-4009-45d9-b81c-0f4892b169d1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 33).', '[{"id": "A", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "B", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '3c2c43e53ce2fa5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('210ccc8f-de5f-4583-9018-4ea5c6d87eb8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 33).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "6633", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '0a769db5b4b37d9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07b8530f-f8cd-4823-98d4-e613632c48aa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 33).', '[{"id": "A", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "D", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'f3299ea912be2daf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d652057-a382-48b4-a02a-acce15d89746', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 33).', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "C", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '609a475ad1780652_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11414f42-69f6-4572-8675-16207b0f0032', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 33).', '[{"id": "A", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "B", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "C", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'ed9d34a19d5d4ac5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6447a95a-8a2b-41c3-bffc-8affdc73da6b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 33).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "C", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "D", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'c7f0e17d778a12e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6aa0104c-e7ff-48d1-a81c-c63e9c9f9298', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 33).', '[{"id": "A", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "B", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "C", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'fddbb49b39bac8d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0302d8a-63bd-42f4-b9fc-7f162f880a77', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 33).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'e3a280418507385f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c6f5b19-ef1f-496c-bf97-0391dc055bc5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 33).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '74af5b5778c8483d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a05eb5f9-5045-4558-9363-53e240015d11', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 33).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The OSPF link-state database", "is_correct": false}, {"id": "D", "text": "The BGP route table with all attributes", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '352bfe40d1ce0b06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ccca918-df8b-4ee9-9ad8-2c145a800279', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 33).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "show route <prefix>", "is_correct": false}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "All of the above can be used", "is_correct": true}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '74ef93c4f51d713b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2d802ad-05f9-43fa-9cc1-ae0b95f26bba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 33).', '[{"id": "A", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Replace the interface cables", "is_correct": false}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '01da565bc1d6ecc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('912941c6-e4ac-460d-acd4-58915175bf53', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 33).', '[{"id": "A", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "B", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "C", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.140.91.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '08c1cb61643e42a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e734c498-9b75-4b8f-a4df-347b891728d3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 33).', '[{"id": "A", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "B", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Defines firewall rules for packet filtering", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '8ca31178fe2d96cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a135466c-5aba-479c-a25a-049a7c8b759e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 33).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "deny", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '81d4cdafbb4c6194_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0db3382d-ab01-4fa5-93fd-3fcf00b10864', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 33).', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '6ed728541a6086fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea957ae0-5e83-4762-9d31-dfab48bc2114', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 33).', '[{"id": "A", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "B", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "C", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "D", "text": "Single switch acting as both core and distribution", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '02cba3631df66c62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe5320ef-b528-4384-a922-5f97bfb16eef', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 33).', '[{"id": "A", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "B", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'd0ac75901c258bd7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f75d145b-15cf-4c17-990e-98e4e6731514', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 33).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '5cb7bc0f5c6a6f53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('803761af-ba15-4633-905c-fbec833e3b69', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 34).', '[{"id": "A", "text": "Backbone Router", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "Internal Router", "is_correct": false}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '0e266b9b7e15f594_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5010489-9ff2-416d-bef5-f2cf9a3f0b33', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 34).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "120 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'da780c223c9dd2cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a890ad73-d339-43d0-a4ca-5c6854e237a1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 34).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Connects to external routing domains only", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '04e1c0e76a5d2560_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e85ea2f-f173-4032-8b2d-8d1674ee286d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 34).', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '766d5669efcfadc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9e65071-ab2a-4632-bc95-5112c4e876ea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 34).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'cf12851022e8e681_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1e2a9e6-dcc8-4594-b04a-a95e06abf215', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 34).', '[{"id": "A", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '6c942e0adeced8b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('250b4bf8-29b9-49e5-997a-0d556b6c1e3f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 34).', '[{"id": "A", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'e3056d102fdb2fca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b03b1e0-deef-4ebd-87ff-7cac0da76046', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 34).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'e1e36612cb107928_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b52b488-f9fe-4c45-99df-53496c1c8eaa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 34).', '[{"id": "A", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '20a4e1830bafa418_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e14c602c-10ee-466d-a49a-8ddda670e1ab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 34).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '599a681f1f5258f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bcba59e-0eb4-4338-a8bd-b4d77fda25a5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 34).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '9f54ee46a15732ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5716705-a985-4efa-9f8a-4a1ea53603da', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 34).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'accc286c5bd122a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6da13dbb-d682-4077-aaa8-e80330caf552', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 34).', '[{"id": "A", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "B", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '00da772e6ca3dbc1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('778cc86b-687e-43d3-85ce-983133559cc5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 34).', '[{"id": "A", "text": "COMMUNITY", "is_correct": false}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '301fe86f632c8394_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb282d3c-84a0-456e-adb0-b0bfbfbc54cc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 34).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'a79b1952aeeac479_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3723852-4a41-454b-9121-94afd3d8bc04', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 34).', '[{"id": "A", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "B", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Permanently deactivates BGP advertisement", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'dfc40e01552d8024_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c272a4e6-4ba0-48bb-be62-1a2cc8b859be', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 34).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show route advertising-protocol bgp", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'cb164a7d210b817f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d1a3568-d9b9-4a17-acb0-8b28ac84d821', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 34).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'f389f32da413fb1d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f04fa136-3310-4521-8cd9-c1573c0c5dc8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 34).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '4fb55676e3d0ae75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7477a32b-7e54-4b5d-a682-ac3b2a50156b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 34).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "C", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "D", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'feb29795ca8dd820_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c453da9-e39d-4883-84ff-9d85e2480d88', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 34).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "D", "text": "RPF is not used in PIM-SM", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '88ba62d0a9563c0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa494ce3-a7b8-4bce-9539-697fe4c7eff0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 34).', '[{"id": "A", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '028791059b26b127_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1e5250f-28e9-4896-be46-aa9077b8aa31', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 34).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Designated port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '2b99e277387366e3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e102ce6a-1d80-4bc9-a005-ffa49a08a494', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 34).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '5ad00937c6253a05_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ff37f70-020a-42b1-8869-1b4a4a256da8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 34).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show stp status", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'f315dcd7f5ae0485_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3157e096-6a0a-4c82-a462-505c1f8605dc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 34).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '0199ea60f9a78045_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32e9ccf2-232c-4425-acae-84f024233df3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 34).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65300 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '1bed7b3da184487c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc504656-38e3-43d1-8b51-2660fa0d64af', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 34).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Connects to the management network", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '398e86426694126a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b6e6962-b0d3-455a-879c-d2d5a4346be0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 34).', '[{"id": "A", "text": "set interfaces ge-2/1/3 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set interfaces ge-2/1/3 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set vlans VLAN10 interface ge-2/1/3", "is_correct": false}, {"id": "D", "text": "set switch-port access VLAN 89", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '53a5f744def2b52a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9846e90-3da3-463f-8f9c-09b0c19b0612', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 34).', '[{"id": "A", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "64600 (16-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '5678ca2eb10865ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e5bab91-8e4e-4f5d-873a-e7b3678d1f41', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 34).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'cd14f6cfb31b8743_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af5873e4-d529-4a06-a810-7ad432249558', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 34).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "26 (011010)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "46 (101110)", "is_correct": true}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '69cdf2fa50478352_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52245dd3-531a-42ca-b3d5-448bcbe34e81', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 34).', '[{"id": "A", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '4743605f27d58753_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b78b6aa-605d-436a-9381-798525cac7d6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 34).', '[{"id": "A", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "B", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '80adc37cf8d19c67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de798b98-32b5-4c9b-b57d-e341b6fae6e5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 34).', '[{"id": "A", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set cos rewrite dscp 46 interface ge-3/1/2", "is_correct": false}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '31747b52b75f77a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0654439-1992-41b9-a3a9-2e8274d9094b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 34).', '[{"id": "A", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '6b7d07c71ee514c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed90b41c-cada-46fd-8cf4-d263c2a6233c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 34).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Carries multicast group membership information", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'e1025b8b65ba2811_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25c1bbeb-cac2-4d65-aa3a-e20f821c3ed8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 34).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "4789", "is_correct": true}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '3a8da538cfeebe3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed6e5482-9ccb-48d2-820d-4ce3bdbdb5a3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 34).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "C", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '788789c80a5aa724_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c7605ff-81c0-477d-80f0-5cb2e15a6536', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 34).', '[{"id": "A", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "B", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "C", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '1895aecc9ae0d266_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3644b654-fd25-4e4d-ba22-3637adeb83d5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 34).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'b49bd5d48a0f4003_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5545546b-3af6-4520-9837-598842bf3a97', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 34).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "C", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "D", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '431f3b1918b839ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6b86eaa-4c34-4860-ac42-e562da56fb74', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 34).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '47abae505c5b72bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce225d97-94b1-4e14-8771-5ed8265c151c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 34).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "D", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '3dfaf2a0177c61f8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('734c9bfc-8cec-4a29-92cc-84715b49065b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 34).', '[{"id": "A", "text": "traceroute <destination>", "is_correct": true}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "show route <destination> trace", "is_correct": false}, {"id": "D", "text": "ping trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '13be1a74c089a41a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f032280-c4c3-4033-b775-6a6faa2d5ae6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 34).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The BGP route table with all attributes", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '9dfe1ee668dc4550_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f2309f7-841a-4296-a5d2-08d4ab2cb8b0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 34).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '7fe1b42457f76a24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ef4c04c-87d6-46cc-be5a-204bcd80d252', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 34).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Replace the interface cables", "is_correct": false}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'ed514ce22b9fec4d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90e99d65-87f1-4ab3-959f-63ff9328e9ee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 34).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.28.3.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '25ba5c55565d95e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b2b166e-2e74-48df-850b-2298add8d829', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 34).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'be84c0f9e079a0c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d192a91-be99-46e0-8f70-123a7dc16d46', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 34).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'dfbfb5645df65a9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a9d5263-d318-4c2f-9cb7-92d3b5ca3656', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 34).', '[{"id": "A", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '8d96c1f560a36703_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cda3a2e-079d-4b53-a094-be8f7eef40f5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 34).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "C", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "D", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '1a6ac65a2858942d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91539ffc-839c-4a71-b9f6-1326f766ca0c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 34).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "D", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'f3d33e7840b4f17c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f0451e0-6a68-44e6-bbe5-c2ea5953e909', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 34).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '2ed89cdfac3d5e56_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77311413-a0a2-420e-bd4b-b0694a0b871e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 35).', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "Internal Router", "is_correct": false}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '5c44674f16c531db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc38dfdb-a7ac-42c4-94f3-edbc4b877b3f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 35).', '[{"id": "A", "text": "120 seconds", "is_correct": false}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "40 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '53d67c8ff7165b72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96286d22-7c08-48ee-9444-0f5cbbc7b8fa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 35).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Connects to external routing domains only", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '128a66ca169d7dc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95c35af6-a43e-43a8-9853-d91ec7e0caa1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 35).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '79307b1f6c7b32b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cec53d0-1509-4bdf-bef6-e8aaae619188', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 35).', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '822b4e08d7faf97a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1b66a56-a838-4e5b-94b5-0078b3fd2830', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 35).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'a6bbb7a6276a675b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f43ecbed-7f70-4226-9215-4ba2800a0e25', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 35).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'a3c3c22736b6914e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b044377d-9a5c-48ee-8298-f75ba8ff8e75', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 35).', '[{"id": "A", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'eae422ef904fba8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5fd39d3-4aa5-48f3-b589-c2c3112e1757', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 35).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'c23564d7b4be620f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec29ba69-97dd-4c6f-9c00-98a8fec8cb19', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 35).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'ec2d43b74b69e1a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7983b27a-0b10-4454-9a0d-39f5bc28b610', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 35).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "64", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'c10e1b8c281e13d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eec701d1-654c-44fe-97a7-8c525ae9f320', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 35).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '7149351317cd19e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('095ea639-2b22-46ac-9fa1-cda1df51910d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 35).', '[{"id": "A", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "B", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "C", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '578c57fd69955144_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2eb9c05c-8e4e-4ac6-aa9d-375181aa07b2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 35).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '824fbd84d92b4b08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59550ca4-0ba4-40d1-8482-1ba48ae086a3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 35).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "C", "text": "The group of route reflector clients", "is_correct": false}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '32cf04c960b8465f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c7d19f8-3087-43a3-9f04-364785dcc060', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 35).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'bbc8f6047ac6c370_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7efe1914-76b3-4ba1-8df4-aa94e2ecadbb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 35).', '[{"id": "A", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show bgp summary", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '16fdf11fe577a595_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d18a2c7b-7d36-473f-8182-01c5315e8e39', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 35).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'a50eeac380d02628_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a52c86e9-c43b-4c44-a885-8bbbd37213f6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 35).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'f46857b0fc6c3d4a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a785274a-6cd4-46e0-af94-b231776c2ffb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 35).', '[{"id": "A", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'f9bfe5da46a218fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('204fd76f-3245-4b7c-9748-678ab7333b14', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 35).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "C", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '4edf4dd923fd5e8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5d20dd0-c2a7-4eff-80d1-4d13a46cc667', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 35).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '14a8d5ed5ad6d937_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e61e99e-db44-4b3d-a01e-2af16011b9e6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 35).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '32c7de581666d2bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c55f9f3-6945-491d-8bf4-869a9463a757', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 35).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "C", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "D", "text": "A physical link aggregation group", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '9a5a4c438eeadebb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82deae06-4a93-49b4-9518-939ef2731b42', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 35).', '[{"id": "A", "text": "show spanning-tree interface", "is_correct": true}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show bridge stp", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '0dd8a2e59ad3694f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c676a66-2780-4c80-94a1-fcf0f5612df7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 35).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '3d893c8abf9ac659_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d6e4c8f-f365-4a97-9abb-2dc236900570', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 35).', '[{"id": "A", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "B", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65001 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'e136c4c683b13037_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55be36ee-55aa-4471-93a5-42c7d25fa1e8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 35).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "C", "text": "Connects to the management network", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'efde275a586a20d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b22a8ffb-aa28-49ba-9374-813bfad93c03', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 35).', '[{"id": "A", "text": "set interfaces xe-0/0/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set vlans VLAN10 interface xe-0/0/2", "is_correct": false}, {"id": "C", "text": "set switch-port access VLAN 199", "is_correct": false}, {"id": "D", "text": "set interfaces xe-0/0/2 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '65d96dfd5cd3202a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d76fcb05-070a-43c6-a0c7-4516e0062a55', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 35).', '[{"id": "A", "text": "64515 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "1024 (10-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '2fe1685d101e3d73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06bd0f9c-3e90-40c7-bcaf-6b4688708ea4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 35).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '8381414399cc5d48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06b8e8d3-1a48-416c-9c33-85a4a8e2e09c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 35).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '33ad6637201281a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6a58c0d-e554-4903-8b31-0b64a9b04886', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 35).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'a6e866d66dabe932_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3b8fe04-f90f-4d16-b57d-6ab3afe4ea6f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 35).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "C", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "D", "text": "Determines which packets are forwarded first", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '66c6490236402178_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67226e4f-ce0f-488e-8d60-c996c4220c7e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 35).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "C", "text": "set cos rewrite dscp 46 interface et-3/0/3", "is_correct": false}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '202fb7aaaa11ba76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5377ed9-5ada-4927-a6dc-c0c12741234d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 35).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'be417792ce1a3db4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('625b9581-99c0-4398-a71f-d1686aa8d752', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 35).', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'a69041e6b548ccba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af7f9e69-bda7-4632-a368-031e1dbcd946', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 35).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "1234", "is_correct": false}, {"id": "C", "text": "8472", "is_correct": false}, {"id": "D", "text": "4789", "is_correct": true}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '2fc68521bf018a85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d29d3e1-84e3-4d12-bbac-16134845af1c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 35).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '917742e75edaa53b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dac664e-59be-4022-8488-38a2b88a8b3a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 35).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '9d9952ba5bd7eadd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b88b2797-194d-419d-89c4-0db3ebf97513', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 35).', '[{"id": "A", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'd2e4076fcbd26b91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d238279e-da20-4f69-9e9b-2e7a1b286665', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 35).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'a44742cae2cd2cf8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09f09258-f7a2-4226-bb42-c633d865bbf6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 35).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '35934365c5515855_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb341c72-bb9b-4a76-999e-49d76d59b47f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 35).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'bff3a634c944e075_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f929a75-0647-413f-a0ee-752aabf53504', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 35).', '[{"id": "A", "text": "traceroute <destination>", "is_correct": true}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '4bb4fc11656f8eac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('403a9e58-38ed-49b9-a927-d0c81657c152', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 35).', '[{"id": "A", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "B", "text": "The OSPF link-state database", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '6a4adff7c3a5e7d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e1cc8d4-c29d-4cc7-892b-2b344c72f20b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 35).', '[{"id": "A", "text": "All of the above can be used", "is_correct": true}, {"id": "B", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '63da6cdb17e52d6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b57540d-37f1-4ac2-a1bf-ff3f40182bfe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 35).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "C", "text": "Replace the interface cables", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '714bf6fd4c85fcb7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ecc4415-dfbd-4c32-aed3-040c591fa9f5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 35).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.177.93.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '82e3e97738c5dbf2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99f5cf42-e9fb-45e4-b3de-33366b2c9dd3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 35).', '[{"id": "A", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '4a78221e5f305865_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a25b43a-19c1-4414-a823-1e14e93a43d8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 35).', '[{"id": "A", "text": "silent-drop", "is_correct": false}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": true}, {"id": "D", "text": "deny", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '9ec0f18b0af06b4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b440cd8-eecb-4412-b847-7fad31809d86', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 35).', '[{"id": "A", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'e58ddcfd46b43ecc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('baeb63d7-c748-479d-ac3f-21e8a11e15bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 35).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '4ba34cc5da3bd870_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('715c394b-4794-49a8-8441-af1b8f628305', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 35).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "D", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '2828346dfe659751_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21d7c67e-571d-477e-8434-297dbbf2401d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 35).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '3b97b1e8c69ba83d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d1db93b-aef0-421c-96ed-d481a457da9f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 36).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "ABR", "is_correct": false}, {"id": "C", "text": "Backbone Router", "is_correct": false}, {"id": "D", "text": "ASBR", "is_correct": true}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '9f34907084880dfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dcd7c60-0ce6-4aca-9c5d-a9cfcc05791d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 36).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "30 seconds", "is_correct": false}, {"id": "D", "text": "120 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '6b3a685923b11ce4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02338e4a-f17e-4691-bc1a-342e4fb0396d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 36).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "D", "text": "Connects to external routing domains only", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '70a64b5be6a4062f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c01804f7-13ae-4bc0-b939-4ee8648739b3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 36).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'a0432d520a166859_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1fdc724-813d-4362-824d-10666afdbc5b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 36).', '[{"id": "A", "text": "show ospf interface", "is_correct": false}, {"id": "B", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '796eaee4726027b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95cb63ca-9ed9-461b-bfc3-057cab83fd7e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 36).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "C", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "D", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '8e6cfeb94d16f511_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e71ef49-3a32-4e6d-a834-5103c38ddeb4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 36).', '[{"id": "A", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '1714b1840131a047_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('564b888f-2044-4893-b7b1-4d05fb0c3b45', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 36).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Both narrow and wide are supported by default", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'c27c73f4291e1f52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1189d60d-dd42-4a78-b0af-9f4cf8b52ad8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 36).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "C", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "D", "text": "Hello PDU (IIH)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'b0673b557602f7a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35f6fec5-6c91-4cd9-864a-f170a21a1cf6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 36).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '2c679faf0dba083c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98cae810-c945-4807-ba65-826eb78749ee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 36).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'a82baf9527c8e593_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad9b4d58-59b2-409c-b52e-3b0f0311967c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 36).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '374719f2f446c318_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc57e6cb-52f1-4364-8518-ef7505547d08', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 36).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'a515adae61f29639_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44e063ec-c56e-4dd0-945b-1b9464f5595c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 36).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '7523c683fd8fa50f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62ac8f56-f767-4972-8f51-0f3f67596671', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 36).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "C", "text": "The AS of the route reflector", "is_correct": false}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '47ef352fdf81b1cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eefc73dd-8023-473f-bbf9-9003d6226f2f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 36).', '[{"id": "A", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "B", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "C", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "D", "text": "Permanently deactivates BGP advertisement", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'c79464eaf60f5a1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cf27fcf-084f-432c-872e-0f7c804ec90b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 36).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show bgp summary", "is_correct": false}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '313c17e1023d7822_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2a650c1-f8cd-4693-81a2-66bc1dbf25d9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 36).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '01ceafe98a20f90d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3740aa47-d955-46c2-8237-181dea24d2ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 36).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "D", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '539025a38bab6599_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3585879-d95a-4378-8d2c-ecb06fa72e88', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 36).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '4a282852f786efe4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e881ab91-5a8a-4f86-ba89-4f1a3dc56c6a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 36).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "RPF is not used in PIM-SM", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '71e1c18b1e2cbd34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d21a0850-4a85-45da-a09f-aed0a01fbca9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 36).', '[{"id": "A", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '054d0f61dbda3671_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('afb7ae4d-650d-4ed8-b2cd-fae6a8479355', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 36).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Alternate port", "is_correct": true}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '83d5611a793e26d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bacc369-6963-4057-8adb-596ff24a0fd0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 36).', '[{"id": "A", "text": "A physical link aggregation group", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '51f6a31a046176a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('549ade74-436b-41f9-bf57-dada7902433a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 36).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'eb8fe5c540f1d2e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35a21088-67cc-4d86-b29d-324f7fe1db3e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 36).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "C", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'bc7652db4025deb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8361a10f-fd04-44dd-aa2f-27b04e3d3e70', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 36).', '[{"id": "A", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "B", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64514 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '11e672c5731f1d99_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1f62d80-d47a-4345-8e3f-9de747185924', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 36).', '[{"id": "A", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Connects to the management network", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'db4f2be99a8b983c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eda90a28-fd18-4a6a-96b9-9c2e67d2beb9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 36).', '[{"id": "A", "text": "set switch-port access VLAN 491", "is_correct": false}, {"id": "B", "text": "set vlans VLAN10 interface ge-3/1/0", "is_correct": false}, {"id": "C", "text": "set interfaces ge-3/1/0 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set interfaces ge-3/1/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '8655f36edb96e675_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9986b9e5-3edc-4337-8109-40ee1afc2b82', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 36).', '[{"id": "A", "text": "64513 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "256 (8-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '3da61bdca04711a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03b4905c-36df-42d3-9cb9-8dcea4e0f530', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 36).', '[{"id": "A", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '8bd0bc744085535d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11f250c8-114a-4390-b504-db5c1b51357c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 36).', '[{"id": "A", "text": "56 (111000)", "is_correct": false}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "46 (101110)", "is_correct": true}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'debf0c8252fc6cff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e610cf3b-97e9-4b75-86b0-5d8b9f6b7259', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 36).', '[{"id": "A", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "B", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "C", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'cd1491b963c68641_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e4e5405-338a-4521-9b9a-767145527b0c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 36).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '3d1b1ccd52b0ed1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d9e214b-e57b-4c76-b474-141ce128df9b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 36).', '[{"id": "A", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "B", "text": "set cos rewrite dscp 46 interface ge-2/0/1", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '7729430478b46675_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('220d359f-7fe4-4b29-8ead-01d054274795', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 36).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'a0887ac1ac3fa98e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85ffb605-5530-4bee-baf3-d092d17c3e9a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 36).', '[{"id": "A", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "B", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "C", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '580fc503fb247de5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b75bf4f7-1b49-4901-ae89-93c798bd286f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 36).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '943483771884241f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29a5a544-fdf8-4747-96fb-3b466c41dfae', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 36).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '18726a2b07291509_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6886b68-ada1-4840-aa15-71e819b005d1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 36).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '257c49a9017d67fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4dab830-f54c-43be-a2c6-4b133032e6bd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 36).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '2a8c0e80cfcbd565_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf3a9e81-378a-4db8-b4c8-a89be5d61ca8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 36).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "C", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "D", "text": "Each host is configured with multiple default gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'e930711babc0e7b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('249f5697-c5c4-4772-8849-7e64f0a1e72f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 36).', '[{"id": "A", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "B", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "C", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '956be1dce92a94f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3316042e-2472-4c45-af91-bad8620a2ccf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 36).', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '5fad3d0bc2de6554_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7834a972-edd7-4ef0-93a8-13bc10cc0bbc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 36).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "monitor trace <destination>", "is_correct": false}, {"id": "D", "text": "traceroute <destination>", "is_correct": true}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '0a915d0ed728d675_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b339b49-e47c-4f74-801b-a4c44a351aed', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 36).', '[{"id": "A", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "B", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '8806948fce533718_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb5980eb-913f-4438-9949-61f2b500f22e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 36).', '[{"id": "A", "text": "All of the above can be used", "is_correct": true}, {"id": "B", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "C", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '1ca89fa9e98fb4c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c75247a-99b0-440f-97e3-47cac4d31e68', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 36).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '972bf59de32c755a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0884dea-3464-4dcb-9246-dc57eb1d7819', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 36).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.2.139.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'e4ea44698dd70498_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('362d814d-c1ff-439a-96f3-7306443ca84c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 36).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "C", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'df9d860b95adeb8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f9b5ec4-a84c-474e-9285-3c5437b1b6db', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 36).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "discard", "is_correct": true}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '1143ec3597d82ca4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca1f2f53-b159-4e60-b467-644959cf4052', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 36).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '0e27530398431dde_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6adb087-a9a8-4625-b476-9b485b196735', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 36).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'c89e7cf7fc50838f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf39da14-8f28-4f8e-8a3c-8d5668a409cb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 36).', '[{"id": "A", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "B", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '6fabed837285d6ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8609767-2159-4798-b5e5-f04ab5d23137', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 36).', '[{"id": "A", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '8e8d1210c8b27fa5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98fc39aa-d632-424c-8fa9-c63d937b3940', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 37).', '[{"id": "A", "text": "Backbone Router", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'f41013f4bd5c6bcf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('099ea94c-fcad-4e6a-834f-29cffb0e5e08', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 37).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "120 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '334de0b38f4f9d19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a9bf08d-2b80-4a27-82cd-1a17cd901581', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 37).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '950a91f5faa6a0a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d8ffb40-121b-4dbb-adc6-1be265715649', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 37).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "C", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '3de9c5a4ce33ae96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab503bcc-dd77-4af8-a704-a867a5f08c20', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 37).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show ospf interface", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'c101cdf0b4b55628_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2d747d2-9ed1-4697-84af-616a0ae2d045', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 37).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '2b31e9d2d5fcb1c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef927a41-660c-4120-a8b8-9d1a907f582f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 37).', '[{"id": "A", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "B", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'ef8a4a777f66945b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86f7acda-faae-43a1-863e-63a2964d09a6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 37).', '[{"id": "A", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '634346e0de8d9078_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ab83e2f-a341-4477-9871-f2455ce86fa2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 37).', '[{"id": "A", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'f3733282f45b0986_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('341ad70a-1671-4e3e-9ddb-abf7fbabdc02', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 37).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '1c75bb43f9070443_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d53f7ffb-00d1-415f-8f04-53d27e1c3214', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 37).', '[{"id": "A", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '7954be1a9e36b6b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2979de72-3709-4509-b9ab-148c55dcdc75', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 37).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Configures the local preference value", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '7a601f57a53b8750_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e2383f8-c888-455c-ade5-19e5fffe9591', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 37).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '7b49cfa9687c5e25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('912386be-21f8-4293-8073-3f5779978153', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 37).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "COMMUNITY", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'c16afd2a3b6f4097_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3a5fb6f-7fdc-406f-b6a3-a45a00169df0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 37).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '45349ab272ab4a33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26471ef9-9049-43c9-a490-cdb0cb40e710', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 37).', '[{"id": "A", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "B", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Permanently deactivates BGP advertisement", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '622b9e4e5fdb4b0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f668ff7-7ad6-49dc-b5bf-58bb2e4494bf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 37).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '8cebb8ab7a1d932b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bcc2c27-7b35-4e9f-9093-81e56bbc5650', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 37).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '012a40fb671e0b6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50099f16-03fd-45f8-b34c-eb5a1e4cc56b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 37).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "C", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'a5b1cc7620ff2b72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c76f2d5-f092-4a4b-bd14-172d70463c2e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 37).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '76ada3afc38b86f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cc9e4ea-1935-4bbe-9fe2-0d2e2818e221', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 37).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'ded947608b5977f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('348f3b54-e41e-41a2-9a29-d61749019b34', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 37).', '[{"id": "A", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '5c3695dad349e0f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('664381bc-8f1f-412e-bb6b-be977b9fad8b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 37).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '6f8370460994594e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea22a84e-9caf-4816-b1b4-39268b5dc991', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 37).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'a238bac1ddf00f9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb349de8-4d1f-460c-91b8-a9fa1fc4f794', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 37).', '[{"id": "A", "text": "show spanning-tree interface", "is_correct": true}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '25c98f31860165b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f998146a-1d02-4b5a-996b-897a8324a130', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 37).', '[{"id": "A", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'a13815c7b4ef5386_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78642970-d9d6-49d3-90ae-46487066e9a5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 37).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65002 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'c4bf35b5c17c816a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a70f2a40-27c5-4685-9d47-77965fcc9324', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 37).', '[{"id": "A", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Connects to the management network", "is_correct": false}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '22b8f4f7b4859336_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0096725a-6d39-42b2-9aab-16ec20f65d92', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 37).', '[{"id": "A", "text": "set vlans VLAN10 interface ge-3/1/1", "is_correct": false}, {"id": "B", "text": "set switch-port access VLAN 21", "is_correct": false}, {"id": "C", "text": "set interfaces ge-3/1/1 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set interfaces ge-3/1/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '03a0bd3a40514f1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdaa94ec-8e95-4247-bf54-c3667a827e5b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 37).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "65002 (16-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '09aa7f5936c1f0e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbfabf3d-fe75-4313-9504-c50b540e625a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 37).', '[{"id": "A", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'cfd49432bfa03c45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c89af346-7adb-4e6c-a3eb-bcb15b5519ab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 37).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "26 (011010)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "46 (101110)", "is_correct": true}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '680e9cbb9679a900_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0430a314-1a0c-4397-b567-24a89066edd4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 37).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'b1cd29769ed74db0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09f86ca1-22e8-4328-a120-6a2d3aa808c9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 37).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "D", "text": "Determines which packets are forwarded first", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '80b93a2c800524a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('850e5d54-d94b-4eef-8025-a3fdfb8ff8c7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 37).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface et-3/1/0", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '43d1ce6376eb5173_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94bf0f76-3c78-44eb-b74d-b268b2cf7204', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 37).', '[{"id": "A", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '451c21d2c64301eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7276a4ab-6bd8-43df-ad12-65ef7e3efcaf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 37).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Carries multicast group membership information", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'b1c7398430a2724d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9694ae5-4c67-4dec-b50c-4c576a26d6f7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 37).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'ca2a61b234b03d6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43d2390e-692c-4c21-a636-6c7394c4e6f1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 37).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'f70167887b9e4c5e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d418c361-74eb-449b-84f8-99c28240999f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 37).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'd56f4e2c199c90e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89bbc4a3-fcc5-4ea8-a45a-3a6c3416df3a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 37).', '[{"id": "A", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "B", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "C", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '0d8d911cc4aef9ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a68f0b9-dbf3-4a73-981d-0429abaed08b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 37).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '912f29e5baede111_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3dc70023-b456-422a-9e6e-1d6ea1ee0af2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 37).', '[{"id": "A", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '4fbcf6f77e76263a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2db2506d-3e79-445e-b9e0-ffae87d410c0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 37).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '19ec50b5492568be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4a8c46d-f6cf-4e16-a0be-b1d98d8431d8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 37).', '[{"id": "A", "text": "show route <destination> trace", "is_correct": false}, {"id": "B", "text": "ping trace <destination>", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '9aae5d06a6e91e1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f1e143b-8740-4689-ab5c-bd09773fb2e3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 37).', '[{"id": "A", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "B", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "C", "text": "The OSPF link-state database", "is_correct": false}, {"id": "D", "text": "The multicast forwarding cache", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '1befcd106f5c0d1b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0cdfe4be-9b7c-4146-b5d2-1bdb45741935', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 37).', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'a30764cf879c31cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c0a3662-e7f1-4bc9-bd87-e2c7c48eabf5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 37).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '4a9b0ae5be1166a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04bcc1df-70fb-4524-8e0d-2039dd63a61d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 37).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.57.203.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'cf2cc0e4e6f50a19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8dcf2181-90fd-43ae-bab5-e0fd0dfeb2b5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 37).', '[{"id": "A", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "B", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines firewall rules for packet filtering", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '12ccf8776bd9f20f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54ffe7c6-990b-4aa8-b009-cd6ecf3e328f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 37).', '[{"id": "A", "text": "reject", "is_correct": false}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "discard", "is_correct": true}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'ff988ed6e6948ddf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79d2edf4-dad2-42e8-b5a6-324d606b43dc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 37).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '76309161fc5dc89d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bf00312-334a-47af-9069-313f54c1c7e0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 37).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '9b5f12b4030e5ffd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9742e7b-2abb-4073-9ea6-d7b8dfd935ae', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 37).', '[{"id": "A", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '8a9018306d0d4056_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b8f05c3-f28a-4e95-803f-ab78833e97ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 37).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'de764fb70326f7ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd90cb90-6cc5-4547-860d-ce43155cf657', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 38).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'dc838e348c14bed9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d72ddb4-df8a-4e5a-9bbb-3b8432641cdf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 38).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '4851b9fa7886c7fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fe04230-1875-4172-8ffd-0d5d651a3b49', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 38).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'f78aa08f45af5387_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e2fb6e0-537a-4760-8a52-28754fba71a4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 38).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Advertises external IPv6 routes", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '02feb623e16748c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5651fb7-45d3-41c5-a68c-ca5364aef995', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 38).', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '5545e8d1eb5eaced_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51a0d699-7dcd-4fa5-a177-ef4ca3f7db81', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 38).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'a9873d7910978772_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8adac131-70db-4654-aba9-6d612e793e64', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 38).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '627ebac944af6a65_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c88ee34d-692e-4f68-bc4b-db3297d00ad0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 38).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '1bd4e253dda387e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e95f1ed-56c0-4b7c-8d4e-6286bddbb25d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 38).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'f27aa8b46abe9fb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b491cd5-e612-42a1-a3e7-6c95ad1ac556', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 38).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '8b50ba57fb6c4148_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa6a2cc7-a559-4f6a-9729-ec031a18d98d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 38).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '625ee9b87e2d6730_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97c0a90f-dfe5-4df1-875f-0bc011b9c000', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 38).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'e8453424b3215a62_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bffd30a-0a16-41e6-aabf-823bc57195c0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 38).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '728d2c9915000127_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b15c8009-c9d4-4b4c-8df4-3104e2cf2338', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 38).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "ORIGIN", "is_correct": false}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '42b63b461e83af14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e5820c7-fec8-40d8-b141-342cdc43f9ee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 38).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The group of route reflector clients", "is_correct": false}, {"id": "D", "text": "The IP address of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'a583a186b7af9232_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0656763d-a981-4b8a-a062-b56a7e04dfb6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 38).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '5df8e10744a42299_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6cab06f-b3ca-440d-bc03-c83bf4a2255b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 38).', '[{"id": "A", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "B", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "C", "text": "show bgp summary", "is_correct": false}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '5b81b0c557f687a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b191d6c3-04ad-4b05-9019-d666cecf3a40', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 38).', '[{"id": "A", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '760ee9933189109c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e50957b7-6fa1-4857-97af-a91869c4560e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 38).', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'ee73c09559094d88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d7ced29-3a8b-4146-8057-dab7b129a83a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 38).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '659de3fcf44653a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd046c3b-3360-4921-972f-0ddca71946df', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 38).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '624fc7f8e6810ba1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a29e2ac5-d63e-4245-8cf7-30c0d8575873', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 38).', '[{"id": "A", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'f97ad6ccbe90e8eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0670e0c-6c21-4189-b6d5-5295bc4bf704', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 38).', '[{"id": "A", "text": "Edge port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Backup port", "is_correct": false}, {"id": "D", "text": "Designated port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '90a320279f24ff59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72cf91e7-71c4-4375-920c-6b5d4d708ba1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 38).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '557fbf85184ee6ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4744363-8c32-4d50-9491-6270740b75d9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 38).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '488d77d4f93c36b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95bffcc9-fa15-49b5-ad85-d11d62388db5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 38).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '21243f1f9465578d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78a7e85c-8e8d-4a66-88a4-225155501207', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 38).', '[{"id": "A", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64515 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'ee1089aac4cb9a49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('599b2d08-6fb2-4ac2-8ffb-cff671cfaae4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 38).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "C", "text": "Connects to the management network", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '20a56ab11264b0cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('038a93a4-c9b2-4fdc-a200-e7cd40114b2d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 38).', '[{"id": "A", "text": "set interfaces ge-0/1/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set interfaces ge-0/1/0 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set switch-port access VLAN 29", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface ge-0/1/0", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '1626862afb023c71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d165320-f114-4f9e-a631-3cccd9152d3c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 38).', '[{"id": "A", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "C", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "65000 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '152645dc07165eb3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1075a83-ac2c-499e-bc4d-b09abd3d12fd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 38).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'ae129df7fb8a5153_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58c485b2-4784-48af-8194-9d2cf7b33f79', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 38).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "0 (000000)", "is_correct": false}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '928088173d8e0ee4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15269221-41a4-464b-9c99-cba8f8e110ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 38).', '[{"id": "A", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'e8920a4e19f67259_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d405fcf9-6a4f-45ae-913c-8f427a4eed6d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 38).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '1125b47b582beaac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62b75c17-8e60-410d-9a90-4d2a80a011f6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 38).', '[{"id": "A", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "D", "text": "set cos rewrite dscp 46 interface xe-1/0/0", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'c0c1bcf0ee0d0049_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('143991d4-9baa-4328-9a2f-d472afec3198', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 38).', '[{"id": "A", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '48d55346a08b9cd7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5b941f9-6880-4120-9573-d43e50e7ad29', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 38).', '[{"id": "A", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "B", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "C", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '6aa3ecb22b207454_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ddad708-32af-479c-86b8-fe08f178d80f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 38).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "1234", "is_correct": false}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '1465e6ce83be2da7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab5e6e3e-1096-482f-a2b7-6d2b3f9d615b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 38).', '[{"id": "A", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'ecd4c35a99242cc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8774cc07-d1ba-4f74-8f5a-14fa074d023b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 38).', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '5be208e6f9ee96c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ad700f6-15ad-47fb-a717-900bbdb08b2f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 38).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'd62e3393caf58873_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6992dfe1-8a05-412b-a318-11d38d9004f8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 38).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '3bd5daebc373d909_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80f31d68-34b1-4c15-819e-ac3ac1e727aa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 38).', '[{"id": "A", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "B", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'ffb8b7859bcae53c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3a497fe-d02e-4a74-8cb1-8af68c648687', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 38).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "D", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'bccdc4a8c20490e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe12f4b4-2c32-4d0e-8311-665b5b373b06', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 38).', '[{"id": "A", "text": "show route <destination> trace", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '2d36939130af703f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e84ba8d5-880a-4bea-bd8a-b0236fa7a369', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 38).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '22f474ad5580d0cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4277f243-0173-4e0e-aa53-9162f950de52', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 38).', '[{"id": "A", "text": "All of the above can be used", "is_correct": true}, {"id": "B", "text": "show route <prefix>", "is_correct": false}, {"id": "C", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'ce8a69fdfd55223a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c33fe29-9baf-4c54-85d9-bc623f30614f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 38).', '[{"id": "A", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "B", "text": "Replace the interface cables", "is_correct": false}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'c716f8b6147a76ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f6776a9-857a-43ca-b066-75722b2b8eba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 38).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.3.208.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '93dc259b65dcf621_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d2367db-9b06-42b1-829f-6cf6f40e487a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 38).', '[{"id": "A", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "B", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "C", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "D", "text": "Defines firewall rules for packet filtering", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'd869d5a52bd897a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd972d79-8c3b-4357-8f94-09858d74b1c3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 38).', '[{"id": "A", "text": "silent-drop", "is_correct": false}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": true}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '1f5e59502009c4d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c24e3d7-e451-41fe-b579-daaefa6409d2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 38).', '[{"id": "A", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "B", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '99d6bc96fd03fb6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b64101a4-971b-4f74-872d-0142b769ef22', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 38).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '586b5612b1fad08d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c921d049-d74b-4225-8425-8d46fa3fb384', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 38).', '[{"id": "A", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "B", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "No BGP configuration is needed in the fabric", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'a76d0049a051ed26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4110bf7e-c965-402e-8ab8-b3aeb93e0b2d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 38).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '6a0ebfa1df255a2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1f0eb87-a08f-4602-9ae3-fb6ff0387ba4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 39).', '[{"id": "A", "text": "Backbone Router", "is_correct": false}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "ASBR", "is_correct": true}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'a64d117cad09e09d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f41459d0-11e4-43fa-a3db-417a76b5b468', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 39).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "40 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '97c9820f98eac6a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42e3b35b-9d7a-4250-81fc-b809c6bba60c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 39).', '[{"id": "A", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '9d34b16983e6a2de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6409b436-b412-4678-8bd1-a6c6e5e5d67b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 39).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'c11b0c7ac2292111_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('163df9db-a9c0-485a-8820-7db95c21030f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 39).', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "D", "text": "show ospf neighbor detail", "is_correct": true}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '1d02cb8b8657d5df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5633737-e231-4849-829f-7179b3976dfb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 39).', '[{"id": "A", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "B", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "C", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'd3ddfdb8f036c965_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4e9ff5b-61c7-4fd6-8512-16bf4d4f9847', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 39).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '7c68d3bfbc6b46dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b63737aa-443f-49b6-8a29-87e0ab6e6130', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 39).', '[{"id": "A", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '219e96df0ed3a7f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d06f89f-8ea5-4511-89c3-681c7b113a5e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 39).', '[{"id": "A", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '321a3a565f5bdb99_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7df18cab-5b0d-463b-bc84-86ac3caeaa7a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 39).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'd8652f8a6734c563_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4fc51efe-3860-4769-a1e3-677a762f79c8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 39).', '[{"id": "A", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "B", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '7cd9006d812437d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48bc059f-ddcc-4cae-82b0-ef053d7a35bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 39).', '[{"id": "A", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'f50cfe856efdf935_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d844bd65-c464-49b9-97c4-4be84efe7ac1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 39).', '[{"id": "A", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'a211539f52d38207_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b027b75-fe53-4601-a942-e609ba9959bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 39).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '40f788a79ad9451a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99084591-e22c-4e47-aea7-9ed7a4e81d79', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 39).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "C", "text": "The AS of the route reflector", "is_correct": false}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'd08fd9f6d6438c48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e524bf5-86ff-40cb-b262-e481180543b6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 39).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'ec0d2a437d3b9093_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68d89ef7-6c30-4853-a00a-6fb5ef97a0ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 39).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show bgp neighbors", "is_correct": false}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'b5f05345149c8191_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d691136d-e7fd-46ab-9a7c-f8afbcf36477', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 39).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'b9f95ec2de6b1fe9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ec7837f-ca0c-44f1-a25d-66a530e92a6d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 39).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'c8393cc2c3e25b9a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7081c9b-75e2-4571-a596-87d0641802b4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 39).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '05477badc5374d41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d011d95a-34be-45d0-9dcf-ecb6672b78f7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 39).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '4598dd0f55d14607_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d003df9-fdb3-466f-9de7-065060b903cc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 39).', '[{"id": "A", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '3d9c1fe9d88406a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c29a0d0e-b3de-40d1-b4db-e7cb42b6f56e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 39).', '[{"id": "A", "text": "Edge port", "is_correct": false}, {"id": "B", "text": "Backup port", "is_correct": false}, {"id": "C", "text": "Alternate port", "is_correct": true}, {"id": "D", "text": "Designated port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '49c855fa7722b4ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3f62469-6a1d-42a3-9a2c-f1e8e5cf090a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 39).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '0a969e4b3ba0d93f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b382eb9e-9600-4559-9360-a337ba435809', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 39).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show spanning-tree interface", "is_correct": true}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show bridge stp", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '1cc854c96245240f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf493e9d-3e80-44b7-9ec4-bd63f41dbeec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 39).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '6eeebbd2f7a50e6c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04817fd8-c658-49c9-904c-d3806a43aab9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 39).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65100 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '9a3b68f88ed354d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2056994-a4d8-47d7-a0fe-6afd55607086', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 39).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'c9ec0e39d0eaa929_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('823a701a-cc66-45b3-9e2c-71fa3b0c0724', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 39).', '[{"id": "A", "text": "set interfaces xe-0/1/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set interfaces xe-0/1/2 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set switch-port access VLAN 470", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface xe-0/1/2", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '22edf58ca005bba5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9d94e85-1dd8-4078-8da2-966248d44ef8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 39).', '[{"id": "A", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "64700 (16-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '60ba9965853b7960_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2aba9e6c-fde6-430d-aafd-587365c7aed3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 39).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '6371d267b1b50ed6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('217a5807-aa70-4609-9f6e-a0e6bc452cac', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 39).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "0 (000000)", "is_correct": false}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'c2afca30d95ea334_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97f06665-c846-4a74-814b-fb9285abe1e3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 39).', '[{"id": "A", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'ccf8616f0de3248a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae661aa7-c81e-4fe6-abe4-622dd13da374', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 39).', '[{"id": "A", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'cc305c4f7695dc19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('904b2bc1-3d00-4a62-b302-7cd5f2a30b7d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 39).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface ge-3/0/2", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '8e3765010a15cccc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ec4d881-8914-42fa-9a5a-8b092e4a0ef9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 39).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'e6f9b9aee6055e44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a29e404-5141-4c3f-bb21-c184d1c531fe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 39).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "C", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "D", "text": "Carries multicast group membership information", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '15095c5ec8fe0922_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc3d1954-6e27-4afa-8ce6-7ae6b407fb31', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 39).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'cb3d2a8c1696ed8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c566e5d-95c1-4a18-9346-2c76d739f3fa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 39).', '[{"id": "A", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "D", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'f333b7e9b245213f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffddb287-e866-4100-b45e-1a23def3a6c0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 39).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '753a1c8990afeea7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfc2bd22-e321-4738-9f30-dd274bb9402a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 39).', '[{"id": "A", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "B", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "C", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'ddef3781310f2e97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3185f9fa-814d-4080-86ff-d0533942276c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 39).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "D", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '1f4c0befa887c60f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73506371-013d-4dfa-8906-ab7845d2a032', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 39).', '[{"id": "A", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '3374be4b99aa053b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c029d50-b689-4313-bc51-1f48d3f03daf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 39).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '8bccc233da17071b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be97943d-9bcf-4a51-aefb-4a8965f5518a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 39).', '[{"id": "A", "text": "traceroute <destination>", "is_correct": true}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'e3f9694bcf0cfd0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('887c5435-6d2c-4670-8426-01a5724da6a6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 39).', '[{"id": "A", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "B", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '014a57612509df04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa3f801c-a28e-435a-b2ff-1f661037e2c7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 39).', '[{"id": "A", "text": "show route <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '2bd28084d666f582_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49190639-33c2-4c2f-aedf-0a51ddc12642', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 39).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'd05c06d818a908f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cccadb10-5de4-4006-8a10-d67625ea9f2c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 39).', '[{"id": "A", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "D", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.37.186.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '2dd718b3dbec3f2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53a6d8a7-1b60-48ee-9dfe-7960f18970de', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 39).', '[{"id": "A", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '3e9ce9ced4b40b39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5b69932-e742-421a-ac22-93ad7603647f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 39).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "silent-drop", "is_correct": false}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "deny", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '93cf8b60e00468d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e298dbff-fcb3-40db-a7d9-9c59c3dc2500', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 39).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '9b3e959bd607ed11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('957a361f-dda1-471a-9fb9-044f910c5e4d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 39).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '3a5dd49ccf8fe8e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a028a25-82d2-43ff-89aa-bc6a66041b11', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 39).', '[{"id": "A", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "B", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'e51a95a1c94f170e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37660fd5-daf1-4a12-a363-d1056a4ad069', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 39).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "D", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'd37d5c651a447698_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc3ce3f6-7aaf-42ea-8e54-c0ddfb7ed241', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 40).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'f41c4d4151ef0479_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c9d0c6e-aa06-456e-b913-fc049e3fd1c1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 40).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "10 seconds", "is_correct": true}, {"id": "C", "text": "30 seconds", "is_correct": false}, {"id": "D", "text": "120 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '5f6aa17908b81b67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad7863dc-a473-45ac-b162-dc6590a67265', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 40).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '3c1acdacd0c8f509_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18f31b7a-7e55-486a-8150-363692ee4ea3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 40).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '62f3f94589548d53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58cbe24c-4f1d-449a-a9c3-f6de6fe86870', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 40).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "C", "text": "show ospf interface", "is_correct": false}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'bd24a26cd425140d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f36946c9-bbaa-484e-b340-c835e96a689c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 40).', '[{"id": "A", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "D", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '47188455c56f7643_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b737f3a8-870b-4ebd-aa4b-4a398566c881', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 40).', '[{"id": "A", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '4c31394f2337ec53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('647023a9-a3ab-4686-936c-daaa9d0d489a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 40).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '97733c4f12d7c5b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c00e7f46-4e3e-4f10-ad14-5c1857f33b98', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 40).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "C", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '9f3a2b97d0a13eb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27cc1427-f9ff-43b6-85a8-aede4e5af078', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 40).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "B", "text": "AS_PATH", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '25ea2497efc80d43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('609b9598-e153-475a-8534-7153bd38612c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 40).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'd9f55885449d4158_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84477476-dde2-49c4-8990-de1e038dbe40', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 40).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '0ee45fa2e263c245_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('132dac40-23d2-4f33-8c74-c1c3022a89b8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 40).', '[{"id": "A", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "D", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '43dda412ee44f0b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3dd56209-a0e6-474c-8e42-f13bb6cca97e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 40).', '[{"id": "A", "text": "COMMUNITY", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "ORIGIN", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'b876dab7c828b0a0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a46527e-63d3-410b-b092-6827c9c0aa20', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 40).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The IP address of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'e6e9cb10d4ca875a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aef2e1e6-85ae-4fe0-bbe6-595899d8fcfd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 40).', '[{"id": "A", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "B", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'ce668d4988f63f7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('520f75fc-8061-4abd-81e1-9cf760f00f05', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 40).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '454bc7bef30bef29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6c30554-08a4-4ff7-b0e3-751a5125ed01', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 40).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '02f3512ca270c2d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9342e14-7d74-433b-a0e6-ed8c89abe7d4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 40).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'af91eb1f1634bd42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2113bfb9-c6b6-45c2-9324-2bd1b19eff2c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 40).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '96ac9b30368c5f8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a7953f1-5228-4eb2-8b73-f4d4462b6e11', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 40).', '[{"id": "A", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "D", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'a256067a0a846291_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c5b7762-bf81-41be-8196-d6cda53d7eb9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 40).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "D", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'e53b30c170e5acd1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e931aca-06f1-4c4e-83c8-35f022e123cd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 40).', '[{"id": "A", "text": "Edge port", "is_correct": false}, {"id": "B", "text": "Backup port", "is_correct": false}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Alternate port", "is_correct": true}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'caa97640262ebf06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c08a4a74-3195-4e55-90ee-e7c6ce152286', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 40).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'd5bd50e33d61a8d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50164056-125c-4df0-8424-d3834176e35c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 40).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '799f099dff4a18e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39ff7f7a-0875-4502-a90c-aa5883107552', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 40).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '84ecc77894c3cbbc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6871a935-5123-4f59-a01e-380b833bcbf0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 40).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65500 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '8d3fb728f7283df9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a05a14a1-a972-4b19-a0bb-3d83918c00fd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 40).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Connects to the management network", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'a4a1f8fa08e3a615_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35ac1f20-fc96-43a2-a8f1-6788a2351b96', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 40).', '[{"id": "A", "text": "set switch-port access VLAN 293", "is_correct": false}, {"id": "B", "text": "set interfaces ge-3/1/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set vlans VLAN10 interface ge-3/1/0", "is_correct": false}, {"id": "D", "text": "set interfaces ge-3/1/0 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '2c0f73ec1b29d0b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9dc9937-0967-4c55-ad92-35dcd14fc23e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 40).', '[{"id": "A", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "B", "text": "65001 (16-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "1024 (10-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '7ce77e88fbc8fdbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91d2300e-6224-4895-ac5b-471b14adbb13', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 40).', '[{"id": "A", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '0a0fdb72c709c10d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('330a4d66-2bb9-4dcc-84f5-ad23d86369c4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 40).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '984883f951aa62af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52193fb4-caa2-491c-9a52-5af2c4d7bd42', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 40).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '672487276c274a22_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('806d1bc4-c273-46ed-acdc-c11c00db46ce', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 40).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "D", "text": "Determines which packets are forwarded first", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'c770524c4be9ce30_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c491864-a84d-48e3-8695-8f13936308c0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 40).', '[{"id": "A", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "D", "text": "set cos rewrite dscp 46 interface xe-3/1/2", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '205f306fb4afa7dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e1b2745-9983-4c60-a9a7-460685dc2e3a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 40).', '[{"id": "A", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'a9968df3d1213c23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a405fcf-36e0-4834-8155-030bab377d47', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 40).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'b6e9032554e1f724_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('572aaa73-8517-4772-ab36-e019d70a4d65', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 40).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "6633", "is_correct": false}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'a2d9be41e26b0a8d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5d678c5-0461-486a-895b-da4954c05665', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 40).', '[{"id": "A", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '2d530c8c926831d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5a9cbae-bf1f-422c-81c0-0590d13fe31d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 40).', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '37548b935cc63cf1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fe2c9e0-1ac3-41d5-b9f0-81f2d7db31c4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 40).', '[{"id": "A", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '41ad5fed441799cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30cce013-dd69-4357-9b89-8e001e737c5b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 40).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "Each host is configured with multiple default gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'aca556d18d3bafc4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14f82499-106b-4408-a76a-a43c07e7b148', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 40).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'f60727aba4540b31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34b138de-0283-4ddc-ba69-1591603a2484', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 40).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '59836a78fe69e1f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('489d0d3e-b2ef-4cb4-9ee0-2ad7a7f4fdcb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 40).', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "ping trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'f4cd271c6d71b2f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b39f50c-c81a-45bf-88ec-3055ed425dd5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 40).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '1797f93ae018cf0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3598bf8d-8b81-4074-8365-7639812a2696', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 40).', '[{"id": "A", "text": "All of the above can be used", "is_correct": true}, {"id": "B", "text": "show route <prefix>", "is_correct": false}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "show route table inet.0 <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'd4d03059558b05a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23cbed08-01c7-4f76-aeb4-5b0ace597c57', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 40).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '15cd8cd2dab3668c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0abf453-9b28-46e0-8b51-b0c46e55c6ab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 40).', '[{"id": "A", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.104.33.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '09230001306d285b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed1a274d-798f-4b4a-8057-80e1bcc7f7df', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 40).', '[{"id": "A", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '9c9fc4f0e141036d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1ed2852-c131-4a45-9cab-92551b687678', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 40).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '48516db410ae8019_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('036c2ca2-8cca-4503-bdef-124da3d03890', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 40).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'ed6dc6656323db4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe6e0980-93ed-42a8-814c-03101a68893c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 40).', '[{"id": "A", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "B", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '282171ebae0252a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bac3b517-5cad-469c-a0be-c2b22e4400ae', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 40).', '[{"id": "A", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "D", "text": "No BGP configuration is needed in the fabric", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '4e4ae05469e0e4c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c6241ff-c35c-4ff7-b382-53dbec9badc0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 40).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'f86023eea7467280_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fad4b74-39b5-4901-9117-806af99d5cd1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 41).', '[{"id": "A", "text": "Backbone Router", "is_correct": false}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "ASBR", "is_correct": true}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '6eb9478d5a865403_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86fb5bbc-1901-473e-a572-12dccf1bdf77', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 41).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "10 seconds", "is_correct": true}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "120 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'a65e4c9f0439909d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c273cf89-8391-4524-a991-2f599d7cf678', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 41).', '[{"id": "A", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "B", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '1b20edfaac830d20_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bb25443-0bbe-482e-a5cb-256059640baf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 41).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '4ecf02f383ad24ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('717aff36-8154-4134-965b-940774d7a015', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 41).', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "D", "text": "show ospf neighbor detail", "is_correct": true}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '1760d701ec854549_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3401057-7a05-4bd8-9ff0-87d8980ad1e8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 41).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'bbdd78fd13dfdaaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8393d9d6-682b-400f-b8c5-31d869e9314b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 41).', '[{"id": "A", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'd825afe369fe6ebf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7de77bd-65a1-4d30-a716-d6c7e458b200', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 41).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'a39181fc2a596ed2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be3c4455-5fa1-45e7-888d-e8f98532526e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 41).', '[{"id": "A", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'fb520b68d19c91b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('560a9508-35d1-48bb-a7ce-16c1bbf18f4b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 41).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '1f7b6f1f5e928613_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5a48b26-7d22-4458-804c-4f5bccbb6755', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 41).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'fb5a28dc4c36f05e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7e9a837-bd01-4303-bb14-62c8e9725b53', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 41).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '7464becbb7976d08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51d53917-ce1d-48bf-8d03-95ff597e2c49', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 41).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '3ac12e6c60fd05c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e5edb81-31a6-4cf1-9d3c-13edc25e6c38', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 41).', '[{"id": "A", "text": "COMMUNITY", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "ORIGIN", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'fef1d5baaaab502b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b38faeda-ce0f-4ce9-ad7e-48d769cc967a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 41).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '71c8f6b02573c747_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c3b90c0-56c0-4685-97d9-a6c77ddc4f67', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 41).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'a5ec01708f6b9237_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc4aabdf-574b-42b1-bab8-b0f5af4e2a17', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 41).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'f0c50931a209a72e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5a2b315-1c30-4365-b50c-4260433aef6d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 41).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '7e134decfe581e41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('910e1dca-327c-4e41-ad5a-108914554df3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 41).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '5c2ccaf7be6c1d01_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e885dad-bcc2-4518-b5e4-543a9a1539ea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 41).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'c0765dda536517f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b41e456d-3f76-4f53-ae53-008e07c173e4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 41).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "RPF is not used in PIM-SM", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'e1947758b9b7d3fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2e4a8fa-6410-4d88-8696-7564e28bbb13', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 41).', '[{"id": "A", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "D", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '5aadfc07dfc4aa7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('632dc8c5-dc8b-4420-bbaa-46f9142c6085', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 41).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Backup port", "is_correct": false}, {"id": "D", "text": "Edge port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '0c1f679c436ec719_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14fd6404-7862-4274-81c1-cd77fc5265c6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 41).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A physical link aggregation group", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '8da76972b3fdf58b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c2c651e-dc4d-468c-96d0-29569efaa0d4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 41).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show spanning-tree interface", "is_correct": true}, {"id": "C", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "D", "text": "show bridge stp", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '0e8568c81e46d1f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad533f79-1e7d-4173-b56f-3ffc43f67f76', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 41).', '[{"id": "A", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '2a5a52d307ce4f8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cbcabf4-853c-4636-adf5-f6b7902557e9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 41).', '[{"id": "A", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64600 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '1743b288fd840ef9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84a9ace4-e3c0-456e-af91-151bc8eb1ce3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 41).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '2831a7067f56e68b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83571e81-156a-4c64-affb-7542e1c82edd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 41).', '[{"id": "A", "text": "set interfaces ge-1/1/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set interfaces ge-1/1/0 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set switch-port access VLAN 67", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface ge-1/1/0", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'c5206cec44cb3d73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3baf6b7f-acfc-4c9a-9873-6b9880d10805', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 41).', '[{"id": "A", "text": "64800 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "256 (8-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '7468d1c008aaaaa5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17e3b935-9510-478c-92b9-e8571d4fb33c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 41).', '[{"id": "A", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '457d99d21983a0aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a56e4457-4e0c-4268-8075-62a7c07fd2ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 41).', '[{"id": "A", "text": "56 (111000)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "0 (000000)", "is_correct": false}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '8cb888bef786a717_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3894e6d-8533-46f6-8556-7d18a439665a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 41).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "C", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "D", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '61f79cc00ae247c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41d329c0-1a96-451f-9489-56213f527fb5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 41).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'cf3a54e2bbf53ce2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('006434bd-bae9-4916-a0e4-56691ca5307c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 41).', '[{"id": "A", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "B", "text": "set cos rewrite dscp 46 interface et-2/0/2", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '3f51108db5e300e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('594a90c2-628e-4465-adad-eec5d898f9bd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 41).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'cb8b3ca3a9d1eaea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12fcfdea-faf2-4f68-aa4d-b924801dc464', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 41).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'bf954332528892b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acfa73d9-5d53-469b-8ddd-dae5b7640cac', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 41).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '3d4f9e648c643f93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62ce9a23-459a-420d-bef7-effab7ac8df4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 41).', '[{"id": "A", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '713be0d927a16fda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b2fdf3b-4dc7-4f53-af8b-637b40fe2488', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 41).', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'f8b4550ef9209747_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e97f4676-42d7-4c54-be22-aa288766b508', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 41).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'abc6b756798dddd0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('518b0e5d-ef44-4bcc-8ca7-a3fcb8b45f52', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 41).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "C", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "D", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '8913480597b167cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8c95644-64bd-4efa-b442-cf7994fbdeda', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 41).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'd44aec869fe20770_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d50125dc-70dc-4ae1-91eb-8ff6ced4b700', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 41).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '20017378509d0bf8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b541e94-6dd7-4ac9-97d1-6f496da3da5b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 41).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '4d8ee012396627ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50bbae56-6076-4f7b-a3ff-20dc762614ef', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 41).', '[{"id": "A", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "B", "text": "The OSPF link-state database", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '3e5eb7e047a1a73b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74cc986b-4d94-4566-9a38-59d504b465c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 41).', '[{"id": "A", "text": "show route <prefix>", "is_correct": false}, {"id": "B", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "C", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "D", "text": "All of the above can be used", "is_correct": true}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '722dff4b5b35990c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f720779e-14a8-4787-9d1a-ba99587d44d3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 41).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '314092852e3b4a7b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70f0913a-55b2-480d-9f33-28cbc298ab84', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 41).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.186.171.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'eec9ea36bfaf4923_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f6afdbb-7e39-454d-acd9-4cd59811e897', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 41).', '[{"id": "A", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "B", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines firewall rules for packet filtering", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '7ac30091f8313ec3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fb7946c-8a9e-443c-93d0-9f86d81733bd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 41).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "discard", "is_correct": true}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'cc30280d4108ecd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a19d4ae1-8856-4ccc-8480-5ad52cf4088d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 41).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '9e0d46a76ce355c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90b628a3-8da9-4cb7-bb43-e0f3c2a2ee81', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 41).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "D", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'c058a3ea2e1e062c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ca42c3f-eb44-40b3-9515-9e4aaae2c9fd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 41).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '64dab57e4003b168_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0263dbf2-de44-465b-a991-38747aa8d790', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 41).', '[{"id": "A", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'e564887053f16882_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c91f35a5-3040-4d47-9e32-808ad1a1e6ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 42).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '31a1cfe3c5449d8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('448f8eaa-d1fe-423a-83e3-778a6f43cdde', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 42).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "30 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'e5217426d56c3ce2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd314862-be73-4caf-ade2-c37be4059337', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 42).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'd98f16031eeeadd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5916832-6491-499f-b4f1-393d0d18642c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 42).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '161dda9e0dfb6f06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('039cf3d1-9f4f-44fb-98c9-c5ca5a53e6b7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 42).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '5d604876df3ad8cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a916516-fbb9-43db-bd05-67f9708085c3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 42).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'cb5f7f91ea0da4bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a745aaab-5160-42ff-b640-2588f1e2c564', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 42).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '6817ee828746ff2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08cdf964-f009-4a61-a9ce-481e217030d7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 42).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'eada3a50f5d5e0c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36a6e1c6-4422-4d40-8e07-fc66e0c07bef', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 42).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '39e8df0faab861a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bbf5e41-ab3c-4aff-8d29-31ca6c4268ce', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 42).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '997697ea2b57878c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71cac416-1d73-4be0-9bf5-e7f06f91f743', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 42).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '5dc86c0631560f51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce7f074c-3e4e-4a76-8218-b721cfb83d54', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 42).', '[{"id": "A", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "B", "text": "Configures the local preference value", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Sets the BGP router ID", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '07a1b59339450d4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e467edf-8596-44a5-b9d7-c5ff2252e5f9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 42).', '[{"id": "A", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '010194b450e18f0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('071d1d46-45a3-47ae-9a21-3cdb1da8ddc4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 42).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "COMMUNITY", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '9d3c4046bc577890_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8df8d3d7-57de-45e2-b8fe-73236a58ad44', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 42).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'e8137e83a7749cd8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b4cbb1a-45e2-492e-bad6-f4d55dbd4c5a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 42).', '[{"id": "A", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "B", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'acf8f1e261ac5846_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('531238bc-4611-4e25-9349-c9dda0bdc9ef', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 42).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show bgp summary", "is_correct": false}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '33bfabd4f5d2f624_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d677663-4785-4d16-844a-76d970683b3f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 42).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '18f2a7de600bfb6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29e163e2-04f2-4293-b125-1bb489e120bb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 42).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'e897bd05bb174cfc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73c022c4-4672-445e-907c-4c292afa4309', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 42).', '[{"id": "A", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'b7534c67cf4afbc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ee78cf2-0411-4b1a-9d49-3d96bee878a3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 42).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '6ee6017a403ccafe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08e972cf-0df9-4588-9798-c1b1e98e2e6f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 42).', '[{"id": "A", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'bc2743e79f716d11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5edca2e0-a2b0-404c-9f41-74438ac0ff56', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 42).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '131cac17cfd169e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('123536cf-0d3d-43de-a6fd-f805a53430d8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 42).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '58c1000c45ddf692_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfe3665d-765e-475c-8c1b-8b25ef89dac7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 42).', '[{"id": "A", "text": "show spanning-tree interface", "is_correct": true}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "D", "text": "show stp status", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '1ff9cb52c144f168_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9efa8860-030b-4d30-a4c1-be743731cf58', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 42).', '[{"id": "A", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '436d1968d4c1ec77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('503de010-70c1-47bb-9fa9-563641842c47', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 42).', '[{"id": "A", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65500 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '88aacbd8a56243cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3faad48-f3d3-4e26-9fd8-612a2eb0de7e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 42).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "C", "text": "Connects to the management network", "is_correct": false}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '0309829831425c92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e195cb7-6922-4e57-9f73-80b8faa701f7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 42).', '[{"id": "A", "text": "set vlans VLAN10 interface ge-1/0/0", "is_correct": false}, {"id": "B", "text": "set switch-port access VLAN 331", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/0/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set interfaces ge-1/0/0 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'cb9db07d7f81ae3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4aa5251-0065-48d6-8782-1fd4e26dfc88', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 42).', '[{"id": "A", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "C", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "64512 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '39c9028935b40704_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22339d39-828b-45a1-bf5b-7ea0109e3b44', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 42).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'a3d359dbd5e871aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59603bb4-2a69-4412-867c-ef62019761b1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 42).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "56 (111000)", "is_correct": false}, {"id": "C", "text": "46 (101110)", "is_correct": true}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '9167f6150203dfca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99b2deda-e90c-4c22-944c-8db202b9a0b9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 42).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '4c49f503c589052e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81cbdb44-c2b0-4079-a466-35c2d7d21064', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 42).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '7ab92c29a17d3548_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('327362c9-5e69-45f7-83db-a032f6452349', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 42).', '[{"id": "A", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "B", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set cos rewrite dscp 46 interface ge-0/0/3", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'bfa6a8f2f3ab637f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5b2b0e9-e09d-4df7-952d-9eb80c2ede27', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 42).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'b2d87a56c51df721_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39554f44-417f-4d53-bc65-8eccd145bbb6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 42).', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Carries multicast group membership information", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '7bbd1e3a631a94da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f487ed3b-0692-4851-bca8-0431a6573625', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 42).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "4789", "is_correct": true}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '6b09cbfcde721771_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c7db460-e7fd-4cb4-a58d-14b2b5aa1bd3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 42).', '[{"id": "A", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '69b9db012825ad1d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c95201b4-4e54-402e-acbe-bf4443d10b05', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 42).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '80c34ff3320b843f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b48ebfd9-7cdd-438f-ba3a-b0536efa463f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 42).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '5fbc78bd76be7abc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71d591b7-f479-45da-95c4-5bf8e9b97052', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 42).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "C", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "D", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '0c4e3e66650059e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55583125-dc1a-4d6a-9f02-489e320c8708', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 42).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '58c1602f28554d70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca2a58e2-8d98-4bad-88c2-bbd32e402fd3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 42).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '80e5e8bc189db2c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7e263cf-bc3a-446a-af45-1de27d3ea0e7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 42).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "show route <destination> trace", "is_correct": false}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'a09ccafc8fa4d32c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f7d1b7d-f12a-4cdf-984e-fe90b150c8bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 42).', '[{"id": "A", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '992031566f2030b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e104b9c0-0e0b-47d4-92bb-341ed175daab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 42).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '1898dc7e27f52944_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e65181bf-09d5-4157-ae14-fa4b2f8ca1a9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 42).', '[{"id": "A", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "B", "text": "Replace the interface cables", "is_correct": false}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'ffa5d2047d4742ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4544c7c9-201a-4d6c-bb77-c6d82320370d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 42).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.6.173.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'f62cebb76b9e1ee3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9003bba7-515a-4abd-be6e-80ea04b6bb6c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 42).', '[{"id": "A", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "B", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "C", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'fa3fb97e955c097c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30c95555-16f7-4071-aa2f-4d13a16d0af5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 42).', '[{"id": "A", "text": "reject", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "deny", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'c2f2eb0cf3166d18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87ae7096-e864-47ed-8a04-cf9e3b807c69', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 42).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'df2b34286a62ef82_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e91c5aa-6d94-415e-b17f-daf0ff3984ad', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 42).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Single switch acting as both core and distribution", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '048510597c295b12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('684f3140-dd13-406b-841c-2cc033caa95e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 42).', '[{"id": "A", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "B", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "C", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "D", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'fe8eab7b8c2293dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f66098c0-4896-4a65-9ea9-49f9b4170a19', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 42).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '5fc5675b41354dbc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d9938b0-0f33-42ce-a081-ff6d7c6e39f2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 43).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "ABR", "is_correct": false}, {"id": "C", "text": "Backbone Router", "is_correct": false}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'bf7be578442763ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a005ec60-7137-4c06-8a96-8fd604f11838', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 43).', '[{"id": "A", "text": "120 seconds", "is_correct": false}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '5ceb5ef67759a517_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ea5ba58-5c08-423c-8f47-5500a2fd61ef', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 43).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '716fde58d12930a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80072cc3-7772-408d-8ca2-9970e336abed', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 43).', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'fea5152c348d2431_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('572ceb28-d4b4-4637-8e60-e137a7f9d19e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 43).', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'cea781b60c931d2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ce54521-8e27-45ec-af72-8301ad0a28ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 43).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'd03bc7b8d64e6086_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cd9f36d-c17f-4745-8a5c-66dfedb61180', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 43).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '8f11d7403028e197_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('514df38f-87d4-44fc-a8c7-89a1ef2c6603', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 43).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "C", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'ba5a5e1b3b8c3533_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b6251e5-4e3d-4a33-a3fe-f5f8ef765dbd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 43).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "C", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '1cbc8a1fdf87787e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22433ed6-ac72-4d4c-9d16-b101fb1b5c80', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 43).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "B", "text": "AS_PATH", "is_correct": false}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '347bd7ad6b869179_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f6c9663-25d7-458d-9388-29168f720c94', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 43).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '72473320dd85512b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92278aea-db7d-4aa5-96c2-e77e857f30f7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 43).', '[{"id": "A", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "B", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "C", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'a71959912bd4f6f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6155d1fb-90fd-45fa-bce6-1409e7301460', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 43).', '[{"id": "A", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "B", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'bc3f88c2c32183a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6041b644-bbf6-42f6-9328-2b88ee601a35', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 43).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '957571a1d2712068_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04975525-01cc-411c-bb45-4c42ef2f434b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 43).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The IP address of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '422822196f4fa704_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1cbf022-0cfd-4d76-8be3-cd7000ac2e81', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 43).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '7fc08f2dc4d72dd5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be440389-58c3-4f96-ad60-582443841ecf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 43).', '[{"id": "A", "text": "show bgp neighbors", "is_correct": false}, {"id": "B", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '3e243afde0f15b38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88f9e2f1-552a-4199-abf1-a6dc3b6d8964', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 43).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '5c3f6a1aabcff906_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cae1b597-98d2-49f5-9123-08920c09a8fd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 43).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "D", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'cef977e9e567207d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('789aeb7c-521c-46ad-8577-d3cf114070a5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 43).', '[{"id": "A", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'f45e6d9ee898da03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07303cf4-fd9d-43d8-820b-2242483efbdb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 43).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "RPF is not used in PIM-SM", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '047bcb2fd5baeff5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5a4357c-46a9-44e5-8a6b-4b9a1d044665', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 43).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'a7a4a343a9fc4d71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57108128-6321-4639-9fbc-b86d509db02d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 43).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '35966a254097bb38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f80bfa3b-0768-4461-89f3-34742df86e5c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 43).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '12caa1b2402804be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63d3beb9-dcd4-4eb9-878e-ea6b88317885', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 43).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'cdf33fa93b888d75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdcc29ab-d9ad-43c1-b783-505b9cbe5308', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 43).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '63dbe9fca3777e80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83953ccb-7fd2-48ec-a8e3-ca753601f22a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 43).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64514 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '1e87fc2f21a617aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e7cf0e4-cff1-490f-b76c-eb9ac26d2a6f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 43).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '88653b2325515968_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a049ad3-417d-42d6-b4f3-362ba268b2ea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 43).', '[{"id": "A", "text": "set switch-port access VLAN 67", "is_correct": false}, {"id": "B", "text": "set vlans VLAN10 interface et-2/0/1", "is_correct": false}, {"id": "C", "text": "set interfaces et-2/0/1 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set interfaces et-2/0/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '404546a388b2c329_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b0136d8-703c-44a9-9d81-989b5353f484', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 43).', '[{"id": "A", "text": "65200 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '1a87c0948519a249_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62c69b52-9534-4a23-a7cd-c8c57282681a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 43).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'c7277a3de6d40d0b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('068e7de3-77ad-44b5-abea-a6ea3b245440', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 43).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "0 (000000)", "is_correct": false}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '10546623aab4bd95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3bb3f2a-f182-48d4-bb79-8182f2f50899', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 43).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "D", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'ad1871328253f407_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b77282c-17b7-4037-9757-53c1d9d53567', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 43).', '[{"id": "A", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "B", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Determines which packets are forwarded first", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'cf67bfe5e4036e87_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e9c8442-2dbf-4fd9-8773-3a41447fee83', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 43).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface xe-0/0/1", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'eb5e8e07e3c83a72_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea640076-6d32-4072-a89e-ba0896b9e262', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 43).', '[{"id": "A", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "B", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '14adc35e92d38063_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('837da7c1-348d-426f-ae3d-a360386cf650', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 43).', '[{"id": "A", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "B", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "C", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '230c7e9399e0eda1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcf06ba4-782e-4d76-ac65-0bb216d43967', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 43).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "6633", "is_correct": false}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '42321f1d1e110d17_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70d9fbda-12bb-466b-8ae3-4098db23761a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 43).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'aa2c856f26cafbda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('635680b8-77fe-4be5-bbdc-85cb42120c61', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 43).', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'bedc44c1258bda81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b40831c2-dac8-4b2d-9d30-437450f16b16', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 43).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '7c8311e4e76b3857_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f00cde6-e42a-4254-9e08-3f79408654f9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 43).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '61048ba9c0ad00de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db687354-8362-4b52-8248-e4abc2be5d5b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 43).', '[{"id": "A", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "B", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'd9e645d096e98b51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('372da5aa-1cd7-41af-8f59-a5c5b287e37b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 43).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "C", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '1d7bb2910160397c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5e4699d-8efc-4972-872a-c7e6a52d39de', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 43).', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "show route <destination> trace", "is_correct": false}, {"id": "D", "text": "ping trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '4f3734c37f13871e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1df92a83-d83a-4ea5-98d7-8d3c35677b40', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 43).', '[{"id": "A", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '0d8f90f8b815a069_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e42c729-62c5-4a59-b030-260c4097f1b1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 43).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '6f97c10436a46aa8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8204c9e1-5841-4833-817b-ac0ffe6258d0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 43).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '6a99871cee83d3d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27d5ded7-5c0f-4a59-a0ca-0d10bc771214', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 43).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.44.155.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '1d4bf74433027973_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3439c0d5-9f4f-487b-b828-c64585fe8ec0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 43).', '[{"id": "A", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "B", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "C", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "D", "text": "Defines user netadmin permissions to the device", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '746529f89be8d645_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19bc569d-b8cc-4407-af3a-548ef3c90793', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 43).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "silent-drop", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": true}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '961e392cbee4b75b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f2cb068-9642-411c-858a-2677bd1a9a17', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 43).', '[{"id": "A", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'aeb41ffb754ab6d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('514c2779-d370-4f0b-ab0b-6f761ad38745', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 43).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Single switch acting as both core and distribution", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '4d3a39ee5a15d4bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbfc9e5c-35da-421a-a81f-05f8d5fa478c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 43).', '[{"id": "A", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '1b398224909b3643_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5a167ac-fd0b-4ab6-b636-9f42679eceff', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 43).', '[{"id": "A", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '33394a5e80ba5a49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('566b7b74-85af-460e-a960-64a2cbb6dc36', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 44).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "ASBR", "is_correct": true}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '2c07b7bc9fe0dc6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab19bfb8-8226-4cb6-9e88-f101dfcf6f49', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 44).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '748e3ab78a4bb1e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc97427f-759d-4105-9824-3a13b590183c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 44).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'f1655be0396163d5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('797b7f36-10a1-4b7a-be60-e5bb3afb35f6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 44).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Advertises external IPv6 routes", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '289e5d63cdd1cd11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea83b824-1786-4655-a24d-d0453f2945d9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 44).', '[{"id": "A", "text": "show ospf interface", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'cf0a9ca694f19d09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a16eade-86df-4364-ac35-ac9de7310b83', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 44).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "D", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'a64e4dabaff83c85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e29afa76-c0b9-4e3a-a17b-c6d17fc70bc6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 44).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'f78927de4389ac8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09e3c458-a93b-441a-ad75-af1bf9ee4636', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 44).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '6e479601efe25814_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3218bc0-9f70-4d44-b674-fa41a4660fd5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 44).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'adf311e9447ebd31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfb3023f-3df6-42c5-acb2-07740ac0ea97', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 44).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'ddb968caf4098856_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77f00114-c212-40a9-9692-584a5ea5d68b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 44).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'e4d7b2a693700f2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21a596eb-ea32-45fa-9aed-ba985fd0a523', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 44).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '70ba7545a4a0da06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9889006-825a-45e8-b0ab-b354b0ff28f2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 44).', '[{"id": "A", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'a929f252373e10b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76cbb1a9-0463-400d-bf2e-12667642f43f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 44).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "ORIGIN", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '9a26a398c8baecd4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('616ae040-00f8-4da0-948d-867d6d0b94bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 44).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '2eb29d08037ae9a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0612297-827d-4d2f-997c-2221556da173', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 44).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '4b868cb9a10e04ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('891caf14-69f7-4416-baf1-8dc322be44dc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 44).', '[{"id": "A", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show bgp summary", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '31e44f098b9a54e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdd56950-0350-4182-bc79-51afef235c67', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 44).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'b9ba96e1c58c5485_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3dc0e61e-c81d-4188-aded-fda8595803e3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 44).', '[{"id": "A", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '51f31abadab8d3ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9833c88a-e57c-41d1-a009-4a4d5ffe125c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 44).', '[{"id": "A", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'facf494f73361bb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3869f04d-3141-4a4d-af01-e5aa135c981e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 44).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'ee58f56773721fc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5aeedcbe-d218-49fc-8da6-417add1037c5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 44).', '[{"id": "A", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'db04cf3f61265763_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89108a82-627a-4912-b0d0-eb2b96dc2e58', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 44).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Backup port", "is_correct": false}, {"id": "D", "text": "Designated port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '9d25e7bd3bc540ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fcd425a-6460-48ad-9197-5848c561a22a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 44).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'e5d0d4469e0746de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46ea67a0-1edf-41fc-bc60-231c37b20a79', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 44).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '0b9814bb19ad3256_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('217b1b6b-adea-426f-9433-ba7dc739861e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 44).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '742d5b9e6126eb13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74da4148-16ae-4a7b-9a7e-f3e951695905', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 44).', '[{"id": "A", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64515 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '5c80d2e41a4e42ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a939a4bd-53f6-472b-ad84-41b68cbf90e1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 44).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '909f0f2527c67b84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2beb0274-0fe6-43e9-9795-a0b424cfefea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 44).', '[{"id": "A", "text": "set vlans VLAN10 interface ge-1/1/1", "is_correct": false}, {"id": "B", "text": "set interfaces ge-1/1/1 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/1/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set switch-port access VLAN 19", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '8ce410c72de6bb49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e762ef3b-2702-4e0e-8583-971d686467fe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 44).', '[{"id": "A", "text": "64520 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "C", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "1024 (10-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'fbda798842bed46f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4147481-6dd2-442a-8aa8-f5f0c49cb1ab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 44).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '672884aa1a2dfc7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20d26662-6393-4ccb-a1e3-b610de8267ed', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 44).', '[{"id": "A", "text": "56 (111000)", "is_correct": false}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "46 (101110)", "is_correct": true}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '6a4fe0ddc2b88113_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('821dc67e-a1d2-4f62-97ed-16dc824f1f27', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 44).', '[{"id": "A", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "B", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'ea7de98140f6a1ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9081f59c-d881-413e-9524-8e6ea0f73d2d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 44).', '[{"id": "A", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "D", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'aeef18c2e22f6fb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('672dcecb-9698-46c3-ad0e-10a5e85ee3a6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 44).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "C", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "D", "text": "set cos rewrite dscp 46 interface et-0/0/3", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '9e849ce33d05603e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15b3ebe1-91ba-4350-9c01-babc4518ee9a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 44).', '[{"id": "A", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'e66ee1ccfe937471_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('042a1d54-a7d3-4133-97f7-98ed50c03201', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 44).', '[{"id": "A", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'bae628804b938726_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dcfc2ed-1293-404d-8068-ef572f677ae9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 44).', '[{"id": "A", "text": "8472", "is_correct": false}, {"id": "B", "text": "1234", "is_correct": false}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "4789", "is_correct": true}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'cdd65a985faac96a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('031f7418-0dd8-4fb6-8ff2-3d028ed09667', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 44).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'bb8ded546129bcb8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ccc7658-fbb5-4940-9852-fe37d0a6752d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 44).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '9461751609d1cc33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5830b99c-1c4f-40c3-8bb0-eef426288145', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 44).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'ec7dde07c7dbb2ff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d928b3d-bc25-4f5f-b650-c55e0789c90a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 44).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '77f7eab7a4675237_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fb31544-6086-4c5f-a4ea-ed7c41aa8aac', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 44).', '[{"id": "A", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '325f80f4fb3fbff7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb36c56c-e636-4de5-9f35-9cf50b9d1c30', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 44).', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '2f24c410ad946321_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88953b1a-d2e9-4bd2-b37d-f074e729dad4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 44).', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "ping trace <destination>", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'c0354c09816619da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9c12eb8-f12b-4ae4-9a46-2dfb43912c81', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 44).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The BGP route table with all attributes", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'be1582181b33139a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e523d4f5-d92a-42a3-a3c6-f083ab1b0e73', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 44).', '[{"id": "A", "text": "All of the above can be used", "is_correct": true}, {"id": "B", "text": "show route <prefix>", "is_correct": false}, {"id": "C", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '8bb7b1a10cf52841_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb02f1cc-40ad-4281-b748-0ba99d166e0d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 44).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'ff98d96e70567938_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21453cb5-4faa-4115-ab87-52e639dcb8f6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 44).', '[{"id": "A", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "B", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.109.236.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '523c324811ba884d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e110942-3801-4322-ad56-563a379df2d8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 44).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "C", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '6c9bfe77ff0f4964_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18379146-f4b6-4857-98d8-696fcc17af00', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 44).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'ab06ee9b08130e43_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7f0b5ae-ce9a-4dd2-bca6-7abfd55432b6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 44).', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "C", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "D", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '67f96b8c96dfbfec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f42d539-e3ae-4ae4-a30a-bea48758f351', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 44).', '[{"id": "A", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "B", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "C", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'e8363087c7abe2e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0687992d-49de-42de-beb3-1855f4491a76', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 44).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '6ca8e809b88a7d81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('caf25852-52a7-446c-a000-343a075e1cae', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 44).', '[{"id": "A", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "B", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "BGP on loopback interfaces between the switches", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '640dc179829a6079_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28d99184-84a5-470b-ac9d-70c85d6888f4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 45).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "Backbone Router", "is_correct": false}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '3253ad1d61b160cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82788f76-6faa-49a3-98f5-d6807fd81827', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 45).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'dd3214f7fb75fd8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d0d425b-b4c0-4efc-8361-c848ffad0ee2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 45).', '[{"id": "A", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "D", "text": "Connects to external routing domains only", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'abe518042dcb5351_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('038f95c9-8960-42bd-b30a-b8322f03edac', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 45).', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '01a021f8a79c285d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d029c5ff-d340-41e4-8312-b0c241cad990', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 45).', '[{"id": "A", "text": "show ospf interface", "is_correct": false}, {"id": "B", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '4f7502dfffeb4b3d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73979266-5297-4c12-a78d-4dac4c8b7d01', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 45).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'cb44386d555261c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42b5a9e8-dd4e-44e2-af63-194684d421a4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 45).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'ff7bb09f3e3ccec1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d39cd58-530a-4bbc-84ae-797f0eeff4f1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 45).', '[{"id": "A", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "Both narrow and wide are supported by default", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '671478c062c36249_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38bdc614-01d6-4fa3-ba62-952b296e6294', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 45).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '6abf15d9626ed00a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef490a0a-bb6a-441d-9209-94aad7f5725f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 45).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '4f5e5ac690381bed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81f461af-9338-4f29-a026-8fb0aff4c4c7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 45).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "64", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '6413d569d730d42d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('248f4935-58d9-431f-a1b1-37b16acb8166', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 45).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Configures the local preference value", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '04f888c902de27b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('825c44ce-132b-4567-9679-b995668dffdd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 45).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '23dbe81872a5f21f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfd42475-c3ed-4695-a048-99436fe388d4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 45).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "ORIGIN", "is_correct": false}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'cf3f9d4d08079705_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c55b735c-77ee-41db-9b1a-3b99ec1c4d90', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 45).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'f38e374741a06365_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('666a3060-4c1d-44db-a186-f370da214478', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 45).', '[{"id": "A", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "B", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'ef473cf278131c44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f3ff1fb-57f6-4fd5-b66c-5bb4d1ffece7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 45).', '[{"id": "A", "text": "show bgp neighbors", "is_correct": false}, {"id": "B", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'c869ffbfd94c2dbf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d36ebb87-1470-41ce-aa97-6ec6938c29fa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 45).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'd1b2112c0a39eb27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3392a496-2e88-4cff-817c-714affff86f6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 45).', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '0d08079ffaad467b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c636ec8c-aa18-4919-96cd-4ad7a7c947fc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 45).', '[{"id": "A", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '497adc288fbab69b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e39511a-1b9a-44a3-aec9-b9b520f2ed59', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 45).', '[{"id": "A", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "B", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "C", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "D", "text": "RPF is not used in PIM-SM", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '33d1898b61cd2d8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b26ca559-fbb8-4f3a-9721-3e30435ff95b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 45).', '[{"id": "A", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "D", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'fda9c81753182a45_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bff9da0e-6ecb-4b3b-bdae-9ad21ddcb510', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 45).', '[{"id": "A", "text": "Edge port", "is_correct": false}, {"id": "B", "text": "Designated port", "is_correct": false}, {"id": "C", "text": "Alternate port", "is_correct": true}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'def804f73fe6ef8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('688d6ffc-f4d8-40d9-b862-01e4b11b68bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 45).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '5926f36425c33f1c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7803e3d9-6369-4c18-b3ff-ddae53aab0b6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 45).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show spanning-tree interface", "is_correct": true}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show bridge stp", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '88c1afd1490ca17b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16924f19-83e6-4f7d-ac58-d0947fe4db9f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 45).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '1f03de67d196a49b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5388bce8-3fe9-47dd-a8f4-dd1ed4478383', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 45).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64512 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'ed1535d371e50808_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef02108d-7a28-43a1-958e-36c6593800c1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 45).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '0a57373b5b4bfb6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4ace73d-e364-4c8f-8920-3d0c24436a8b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 45).', '[{"id": "A", "text": "set interfaces ge-2/0/3 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set switch-port access VLAN 339", "is_correct": false}, {"id": "C", "text": "set vlans VLAN10 interface ge-2/0/3", "is_correct": false}, {"id": "D", "text": "set interfaces ge-2/0/3 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '62f1f8e3787ce478_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48aa2c71-5724-45c5-b45d-09d804624a8f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 45).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "C", "text": "65300 (16-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "1024 (10-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '16a36c1fdc123868_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c261377-406c-4146-9aa0-95fbd75e28f7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 45).', '[{"id": "A", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "D", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '690bae9158d7c217_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db5fe71e-7ae2-483a-b329-cc684f3b9ca8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 45).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '43f3c8b8629b80f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab6c33a6-c792-4078-888e-b2e6a7f9c336', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 45).', '[{"id": "A", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '1e88c4ee01bdfaf6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca5f156d-2f97-4793-b775-fba35d962a6c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 45).', '[{"id": "A", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "B", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '6d313cfde4cc3eeb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12fa055b-4388-4936-b386-d0375d9ce8ea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 45).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface ge-2/0/3", "is_correct": false}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '96d0b28acd6c4413_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('415b49f4-e673-4877-8563-4ec753a1b4ac', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 45).', '[{"id": "A", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "B", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'c9cd9a3575310726_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e146df1-2ba4-4cc7-a156-67e254ff958f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 45).', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '91f8004a49c21ee5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0549f0d-aa9b-4535-b7ec-14901a744bb7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 45).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '3a443fecec175dbe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12af847e-0d58-4163-a626-445e1309ba4a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 45).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'e526821c9872c241_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13179f7f-9275-4159-a58b-4df21ffcf0db', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 45).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "C", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'f67e42507b3f5c8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3993cdec-9598-4330-a08a-15be5bdd1b52', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 45).', '[{"id": "A", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "B", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "C", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '659a6642d18f97e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d41f4397-ef19-406b-bf93-b8b253615643', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 45).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "C", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "D", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '8afdc3dbdb5a04bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef0eb2a5-409f-45ac-8e77-815c4813bcf4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 45).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'f17d1d59243dfaa3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d75b6f9-b8fe-4606-b2f4-9560fabfb958', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 45).', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'cf50aa7373927591_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('734b0caa-6c06-46b4-b707-8d194b1199da', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 45).', '[{"id": "A", "text": "show route <destination> trace", "is_correct": false}, {"id": "B", "text": "ping trace <destination>", "is_correct": false}, {"id": "C", "text": "monitor trace <destination>", "is_correct": false}, {"id": "D", "text": "traceroute <destination>", "is_correct": true}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'e9e584107fdce654_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ac582d8-1b0e-4a03-b9f1-705ca9e3d219', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 45).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The OSPF link-state database", "is_correct": false}, {"id": "D", "text": "The multicast forwarding cache", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'a53ebb1b2bf8469c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('344541e6-d67d-494d-a7a2-a17ac54e11b2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 45).', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'ca31c1a72c6b98e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff59f9ea-ea52-4953-8889-6a7590720486', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 45).', '[{"id": "A", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Replace the interface cables", "is_correct": false}, {"id": "D", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '5cca7d4fabeb80c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('838fba92-6e5c-4159-a92c-20e457471e4e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 45).', '[{"id": "A", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.0.141.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'cf6bf02d7c93d4f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d05434b7-0976-4cbd-a2e0-3b1b9e0ea2e1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 45).', '[{"id": "A", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "B", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Defines firewall rules for packet filtering", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'eb3fd7cee1ae02c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('720df300-e45f-4649-af31-a3fe39fca149', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 45).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '7b5533a4d863b379_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e41c07e4-a55d-442f-9b18-d8797c2dc734', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 45).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'ac58885c80354dcd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12a0a634-4f44-4474-80e2-a40a91e79021', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 45).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '070ca0ac1ed9241f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8b0e7f5-0edb-4419-adb7-fdb2e793bde3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 45).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '9a8ffc1b9bad3d18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('398c2375-47ab-4300-bc6b-ea9be6577fd9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 45).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '3131357eb80e07dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5ad72ac-a41c-42a4-871f-fb9d26da1bfb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 46).', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "Backbone Router", "is_correct": false}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'cb59019707d8c07e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66a46d6c-1f1c-4f20-88db-39e8330f8e67', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 46).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '9e4d4ab472d5add3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('363a14f0-9c7c-4ba1-bdd8-7b171f049d12', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 46).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '6ecc030effa5baec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('222c2766-6e1c-4c30-ba28-d99d8149da09', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 46).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Advertises external IPv6 routes", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '2425236e67487015_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fd5aefe-6cd6-4e39-bfb2-b17dbed3f4e4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 46).', '[{"id": "A", "text": "show ospf interface", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '332b3f71f1f4253f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95a0659d-1d94-4680-903e-3b38b51f8f4b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 46).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'd8d1f0eb6c15c6f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d827c11-2ae1-4886-9d33-43036a8d3615', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 46).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'f21194d2b3806762_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9075848f-7717-4011-9b5a-00bb5ae44bcd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 46).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '8bb3a87a441e5fea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc62bf16-2e98-4d4c-93be-6cea7a57eb71', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 46).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'cd1098358a264379_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f25e669-f5e7-4920-8459-f303fbfdc1b9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 46).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '6f3c6b18c3904670_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85b0bee8-d814-4145-873f-f557d7a8f650', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 46).', '[{"id": "A", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "B", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "C", "text": "64", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '9b777d83b262e3fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6be5ce5-e852-43ae-b16c-53b1162ba939', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 46).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '690272969c69df09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6287164-c5dc-4f77-8dd5-f28a36c1c90e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 46).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '5fb34cdb6c5258c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a86454fa-3538-4771-8d44-ec7142f878f0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 46).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'c4185f903022fa27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93527a80-45cb-4c33-bc19-a85020134d03', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 46).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The group of route reflector clients", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'acbb68482e2eafb9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26cc3d90-3333-4964-9d29-9193fedd782f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 46).', '[{"id": "A", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "D", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '713e418e92c8e17d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4691fa36-4c1a-4242-aff3-7ed7d237c74e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 46).', '[{"id": "A", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '0de0fadc4fa9cd86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('425991ae-4422-4fad-ab9b-87d237b38ef6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 46).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '8ef1f7c19f41821f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('405ece6d-2dad-4a92-b914-5c835f8e7bf3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 46).', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '7f5abe179d038e61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('005af489-f693-4278-8614-bff4a37a4fc4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 46).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'dfdf9d10d1e119b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f8be517-f21c-46b8-ab79-97d81d2b0559', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 46).', '[{"id": "A", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "B", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '2e154042c3aff252_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('650c3a1e-c324-405c-8772-b5fcf0ce82cc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 46).', '[{"id": "A", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '2e9ab7c87cdaaf95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('503c7b0a-805c-4831-b84c-876e944c7377', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 46).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Backup port", "is_correct": false}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Edge port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'd747c41ca79954ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf9f60be-2353-4c4c-b40a-ac4ba6efa82b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 46).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "C", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "D", "text": "A physical link aggregation group", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '3ca05474be64919a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06541a37-ca31-4e87-96de-f70b4b4e4564', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 46).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '328ea4268182e696_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09a86034-88ae-4d62-b9a4-6f82327f9c42', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 46).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '6bc894e0d50f0f63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d53f387-c92c-4a02-997e-313872d7cc94', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 46).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64513 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '398ef316a1f7ce2a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc9339c8-f8d6-4748-8f06-7fecc15822a7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 46).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '916566ba3fd7dc98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d43bede-0d08-4a80-96a0-075ff682aeef', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 46).', '[{"id": "A", "text": "set vlans VLAN10 interface ge-0/1/1", "is_correct": false}, {"id": "B", "text": "set interfaces ge-0/1/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set interfaces ge-0/1/1 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set switch-port access VLAN 415", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '3d78b71cb2cdbbba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d96f90b-a501-40b1-b1d7-2130d0c839f5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 46).', '[{"id": "A", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "B", "text": "64520 (16-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "256 (8-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'c25717deca17fcf1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86c89886-d1c6-4027-aa65-aa557679a866', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 46).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'd4ec32de0a7a9b2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd71a939-be83-4b76-b5e2-401c3a1730e9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 46).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '25f3119ad0ede7cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40caf4c1-d18a-427b-a2ac-ddfc9a4679db', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 46).', '[{"id": "A", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "B", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '48e9971812b78511_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('616393f4-55ac-409f-a257-71f5f42f5035', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 46).', '[{"id": "A", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "D", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '19a6313fd96690d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93744047-3cd5-441f-aa71-1c3bb49adff1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 46).', '[{"id": "A", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "D", "text": "set cos rewrite dscp 46 interface xe-3/1/1", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'edb8e92a23a04b4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53f8263f-de5b-4838-b50b-4fe0213fe85a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 46).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'e320d9c47c27e44e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3784202f-8103-4b35-8a45-ff2b757a3064', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 46).', '[{"id": "A", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "B", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "C", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '51ca1f08028317fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8ed2ed6-1038-4ffc-80f3-4853d484a574', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 46).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '0e98973ea4c3d0a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b23dc1f7-1bda-496e-b4ff-6b4c81c2613f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 46).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '08607f3a5bbe467d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a91b6dc8-910f-4373-82ee-a3ff1b8e0bd9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 46).', '[{"id": "A", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "B", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "C", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "D", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'dc3b590ea1e1f325_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fd02172-72c4-4dc0-a67d-84bcdbf18781', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 46).', '[{"id": "A", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '51880f5a6856e63c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6844374-b75d-402e-b8d5-1408ffb0fb98', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 46).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "C", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '853379aa634bb07e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d524e582-d4fb-4f6e-bd5a-b21b8be83cb6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 46).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '26df203276c6b863_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf38672c-7be0-4fc8-8552-9f1fb9a1a502', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 46).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '6b6f3ba78838b667_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0adc5a5-24da-4efc-b3dc-0796fca551c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 46).', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "traceroute <destination>", "is_correct": true}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '360629a78797ad59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05d138eb-afc7-474c-a0dc-72858d698478', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 46).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The OSPF link-state database", "is_correct": false}, {"id": "D", "text": "The BGP route table with all attributes", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '9e83176b7bf8da9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8077901f-0082-4472-8023-e69bcf9c8163', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 46).', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "All of the above can be used", "is_correct": true}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'e682daad8804563f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ea1b51f-8f85-440b-8946-868680ccdb72', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 46).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'd192d4880ca6efb0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6005abc5-66e2-4f80-8c4f-35ffc04cf3c5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 46).', '[{"id": "A", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "B", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "C", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.35.133.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'c9c6444f3675c4d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c32d2314-26b8-4ee8-bb3b-99ec572aafe1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 46).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'e1e8c16f8fa73e58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ad00826-5a5e-497b-b311-f8bd507f90ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 46).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "deny", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'ac4c5db74f1601d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd5b0304-6e41-421e-b820-2b55ebb8116c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 46).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '8fb2da61e8cea9a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b1c9d50-5a9a-4755-9b87-6e4a89f1fbab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 46).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '540d5f3e033166ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d1b41e1-f4e6-46fb-9043-60e5dfe4a646', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 46).', '[{"id": "A", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "No BGP configuration is needed in the fabric", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'f6427967a2058296_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ef503b5-fbe5-465a-a11d-f5ce8109af05', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 46).', '[{"id": "A", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "BGP on loopback interfaces between the switches", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '8883c81bbd41841a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('553247cb-fc30-4f2c-a1ea-85f3b2141263', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 47).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '4c6e0a7e4113d39e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df9d3ff3-ea66-49c5-a516-d2d891da577a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 47).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '5c3d70d89293a166_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('501ea40a-3400-4a97-8622-23689844e305', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 47).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '77ead8c8ba935fa4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ff23af3-c8d6-4694-abf8-f7b202a44f27', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 47).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'dcb751aa7e8a3ef3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e61addbe-dc4f-4a01-9e58-2519b4921916', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 47).', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '283853532495fbaa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c04b1983-b8c8-487c-8caf-1d1e780acc39', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 47).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '747f8a5384bd43ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d4c79ca-d782-41ac-b7c8-eeaff7ae8663', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 47).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '611f980f9782c90b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf553974-967b-4180-a0d3-90eeaf1e2026', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 47).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Both narrow and wide are supported by default", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '19638fc41ce94896_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30d5197a-f721-439c-aef8-2bc0f28578eb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 47).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'bc11515d7459f0dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08159569-83b2-48ca-926b-ecef69ed0d78', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 47).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '36f7ba1483df810e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a68e63b4-6e7c-4a69-9e42-eab915a5fb7b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 47).', '[{"id": "A", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "B", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '58e442b6f62c33fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a7d833c-56a1-4d11-8a72-4616b39c22db', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 47).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '212bd38bc4f6ef4a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91e29d6c-eb55-4a30-a00a-837e8e91057e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 47).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'f605f0cbbf8f52fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c86df28-0801-4efb-9d89-01d9a3e9bf7c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 47).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "B", "text": "COMMUNITY", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "ORIGIN", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '86daac3b08c85bab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53c7d826-0e90-4585-8e40-55c73ce000b9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 47).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'ed95d4e8c015d3cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69b20d23-7323-4565-9ea1-7da3134d42f3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 47).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '35c9da3546980b06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b152a51-5e41-4493-9b20-c954fac59893', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 47).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '2b2eda48a9dd1187_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a324b04-1175-4c02-a2b7-0ebb5088dc93', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 47).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '2313518beec438d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d8176bf-4ca1-4f7a-a9a6-2b4ba22eb5f9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 47).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '2e9a5309777efd5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e033cd21-06a5-4ccb-8903-e1e4a2ae5700', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 47).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '7761cd8071f2c9a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91f4b69d-9ff2-4afb-be2d-0405a5f369f4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 47).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '7e1b8b97e6231dc3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0ee5952-b7aa-4bd8-8cfc-ba7786c86026', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 47).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'e93d6a3c623e2959_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41847296-e37b-493a-9fd2-e1b03572b22f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 47).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Edge port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '5ca253f936054777_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e5f500f-ad25-4b53-877f-69c1f9533ecc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 47).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'f9ca43d9a0b2d707_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a5233ad-00d1-488b-9915-2868d4806a52', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 47).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show bridge stp", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '2ae257f6247df0ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a63a691-c3a2-47b7-8411-9c8a4766ba3a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 47).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'c0a792b7246d4ccb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e56426f7-3c97-4f4b-87f0-725691eb4dde', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 47).', '[{"id": "A", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64513 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '708f1417320bf8ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01656a6f-8e47-4a58-aafb-d13353c7af26', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 47).', '[{"id": "A", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Connects to the management network", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '710a82c20f618929_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('375f5b0e-47df-46bd-92b6-2f2f498cf86f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 47).', '[{"id": "A", "text": "set switch-port access VLAN 290", "is_correct": false}, {"id": "B", "text": "set interfaces ge-0/1/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set vlans VLAN10 interface ge-0/1/2", "is_correct": false}, {"id": "D", "text": "set interfaces ge-0/1/2 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '9ee3b8ba7b3c0cc1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d44e4593-68c2-40f2-9cce-fd59dcc7702c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 47).', '[{"id": "A", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "64515 (16-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "256 (8-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '1142d06010336593_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('536b5e35-73bc-4671-81c9-04076bfe59d4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 47).', '[{"id": "A", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '8829c4a5e77b7fd5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28c27189-24af-4440-9a55-1993ee6918c8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 47).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "46 (101110)", "is_correct": true}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '79e4c97fda974cd5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7eea3c8e-4942-40d3-96c0-91dbc40b4f90', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 47).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "D", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '77db60a78db5d671_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('054c87ef-b8b8-46e0-a750-a4d0f5f81ffc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 47).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '4a4747b86e796753_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81b85982-deb0-4a46-b7e2-3a75b4db3304', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 47).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface ge-2/1/2", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '4c7e624b5c5015b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7dd8604b-7315-4c75-b687-90fbca1ed510', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 47).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'cb2aa38b732f8a54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c5487c48-0ba1-421b-9aa9-4bd6f950afe7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 47).', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'dba8be57a7c748dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6b63c46-8114-4b2e-882f-b66b3ef07866', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 47).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '62fc3a29594aad19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0316dd0c-73bd-4856-875c-48125b8225f7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 47).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'ec6b85b497fe9675_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cad287e9-1647-4cd9-94be-f5aa711bada4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 47).', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "C", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'db7d0f952f09dd96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a8a8502-f8f6-496c-8833-4a43055bc5d0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 47).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'f59be48d8bd7c7f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('520df0cc-420d-4ff2-84ad-9d58b9b0c1a4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 47).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "D", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '11a3e412bed2600b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('356dc5e8-09de-4c96-b324-dc87bb37a28d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 47).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '385e4733e2cc33b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67597907-fe50-4f0a-a940-081e4313ac49', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 47).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '1a2cae5c08a2ff6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01f48b22-5173-4874-a05e-af8592875276', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 47).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "show route <destination> trace", "is_correct": false}, {"id": "D", "text": "traceroute <destination>", "is_correct": true}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '138394ca1f8745bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbcfa922-39a9-47bd-aa51-947bfa69ae30', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 47).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'caf12473aae33135_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b688042-3cc4-48a8-a963-d163fd4d9299', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 47).', '[{"id": "A", "text": "show route <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "show route table inet.0 <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '461e05733c9b77d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2468ccfe-a5ae-43da-8e66-7fc77c0a074e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 47).', '[{"id": "A", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "B", "text": "Replace the interface cables", "is_correct": false}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '316a71b8b3a565da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c550464-21b4-48cc-aae3-8d6037d24ec9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 47).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "D", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.204.235.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'b41e0e79a30f91c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1304154e-2429-478b-95c4-fa8fd4cb024f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 47).', '[{"id": "A", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "B", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "C", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'ed39f022d753097e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('295bcd66-bdb1-452b-8234-54de3eb3ff39', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 47).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'ec3f58dd0c6173ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d496411-cac8-4df2-9b4e-b7bbd71bdd07', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 47).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '0dd8d0fbaed5e134_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ff573c1-e50d-4bd4-b273-379efa591200', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 47).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "D", "text": "Single switch acting as both core and distribution", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '0df5e195aecbb64e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a8745e8-f9f4-490a-aca9-893260e698a3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 47).', '[{"id": "A", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "B", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '9f124741ae53ccd9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26d3a454-2106-4ac7-9d8a-c6606251b806', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 47).', '[{"id": "A", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "B", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "C", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'e81b4c6f7af5640d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('996fc3a9-3bf4-47c2-b4eb-43e352bb2e54', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 48).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'cc298b96fb17f01d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b861a53-c75d-4c11-b9fa-8cd0fa8e7bf6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 48).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "30 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'c298438eec5c8538_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99a4af54-ef48-4290-af12-f190a230289d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 48).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '7e7a88a67ff64f44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc39671e-5b48-42a1-806b-63b03f8e4c90', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 48).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'af8c0e3900f82111_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8df1d8fe-ec97-4bc0-abb7-06ee4fe76dba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 48).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show ospf neighbor detail", "is_correct": true}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '4dbb1087f246a5e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e12166b-3258-4757-bef9-e904cc0977b0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 48).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '9c601372a593e79b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22c6bef6-cbf4-4c35-a8f6-58f07107cda2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 48).', '[{"id": "A", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '1953d9f2ecce59ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de4f6b0e-ab68-48b9-a092-14b0eb83592b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 48).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "C", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'd45854df6c076c0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d3f334f-b330-456d-9913-6fb0d315c359', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 48).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '371bfd76888cb480_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('342bd3fa-01b9-40b0-b629-270952b109ab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 48).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'fde2b272a7d9efca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ba1eae5-5ec0-469d-bc07-b3e95a0fd6e5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 48).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "64", "is_correct": false}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '7c93c5e895a105d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57143e98-f8ee-4459-800d-2a80d1ee500e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 48).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'b9193889306745a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5027a4a9-f349-4d12-8162-ef813d803557', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 48).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'f50abf30ae20a4a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0543094a-97ba-4f8a-8c1d-1089d378c6d2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 48).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '7db0c9ad91950c42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c05a9a9-a575-4bea-881b-a16c2c35eb2e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 48).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '58a829d933dcec5a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ba1206e-1992-4a83-923d-dffa6e57b17c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 48).', '[{"id": "A", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'bda4c611a29ba702_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80e78792-8d45-4e11-b757-59af1c645527', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 48).', '[{"id": "A", "text": "show bgp neighbors", "is_correct": false}, {"id": "B", "text": "show bgp summary", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '173bf7b66f8c5d6e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2de4c78d-75b4-4b92-81cc-6095d9b470f8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 48).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "D", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'eda5977048bbcb27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33ee89ea-10cd-4e41-a985-1a69eca28160', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 48).', '[{"id": "A", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'a71433a018d12fe3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f8dcd19-3818-413e-9806-3f2e86990154', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 48).', '[{"id": "A", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'd74b0e08d78e66d3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8136048-faa7-4ab0-9e33-f5e5e5b57680', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 48).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'f376a24e5a567bff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02eaff1e-0213-4a44-98ce-2ced2370355f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 48).', '[{"id": "A", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '2616cf6b77dec61b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5a823d3-dfc7-498d-afd2-e3e29cabf12a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 48).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Alternate port", "is_correct": true}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'aac9f3bea1c8ac5e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d869423c-0679-48a8-b03c-4c596fe29231', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 48).', '[{"id": "A", "text": "A physical link aggregation group", "is_correct": false}, {"id": "B", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "C", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '4eb103cd93da6c90_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c506ce1-9b28-4eeb-acea-b62629addddf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 48).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'bff060e9b8a389a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f809925-fd37-4e95-baa8-6ec5a99b5e01', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 48).', '[{"id": "A", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'ecd5c9b0a5ba34d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ec04821-1a2c-491b-97ad-cd4758510c08', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 48).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65002 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '603d3303931760a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d1bd9b3-b0de-443e-b1e5-7c29dcc67c6e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 48).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '07fff1e73bf9eddc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c6db831-dcd7-43b5-a0b3-fd91734123c6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 48).', '[{"id": "A", "text": "set interfaces ge-2/0/1 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set switch-port access VLAN 134", "is_correct": false}, {"id": "C", "text": "set vlans VLAN10 interface ge-2/0/1", "is_correct": false}, {"id": "D", "text": "set interfaces ge-2/0/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'c22fdc431897ee0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('499316b0-2bc5-40c5-bb46-ee0e9f73b7b0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 48).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "65000 (16-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '07571046eb96cd67_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2de735e2-2f38-4aa7-80da-59262c385f92', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 48).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'f65b38aa14cfc666_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('298cb4bd-d9e0-419e-9fb9-352329e55278', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 48).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '41b73a1d007d37c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a96739e-562b-4e25-be39-f14df9cf496a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 48).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '2e9a732dc3d4cbdc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c93d5e9c-54ee-4d08-a68c-d13ac8acb4a2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 48).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "C", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "D", "text": "Determines which packets are forwarded first", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '1d05083ce2d0a974_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8030895a-f642-45ea-b56b-8d8cdfee74e3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 48).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface et-1/0/1", "is_correct": false}, {"id": "B", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '07c301c85c2b710c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('931bf52c-cbbd-464a-a6c2-8fc9a5fce631', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 48).', '[{"id": "A", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "B", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'c6ccb8185c40055d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9a4d0f9-9458-4585-b34f-78514e775045', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 48).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'c1c834037270e159_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf18c637-62c6-4d98-8594-257cccbf37e2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 48).', '[{"id": "A", "text": "8472", "is_correct": false}, {"id": "B", "text": "1234", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '2452be14f864ccdc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('547833f8-5160-40a4-ac6a-0686411594f1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 48).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'b56e108c8526c15e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73fb99be-3101-4466-9bcf-d67f9c2a2bdf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 48).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'a529d1c31ce2bbd5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c2ca5e98-cb24-4d0d-b854-0ab161daaf47', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 48).', '[{"id": "A", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "B", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '3bd6889acd6d8fac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9159df26-5c24-4498-be0b-5b73fe206b03', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 48).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '8bc716da417ca58d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcd69153-6ab8-47b8-b4ba-fb3992afa742', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 48).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '8e5aaa400ce925be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8f44745-ffcd-4174-b0b7-ea90a42644e5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 48).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '3c11ebb222fd40c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd52fe9a-df07-4ce5-a4fe-55a42918ac05', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 48).', '[{"id": "A", "text": "show route <destination> trace", "is_correct": false}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "traceroute <destination>", "is_correct": true}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'c22cc9526c18dfda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3659edf3-16da-49ff-b768-cd83f3d9d6cf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 48).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The BGP route table with all attributes", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'cfddf32390ae0847_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b85c154-439e-447e-bb8f-3f3031559cf7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 48).', '[{"id": "A", "text": "All of the above can be used", "is_correct": true}, {"id": "B", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'a6a32b581a6d233d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bcaafcd-9300-4b61-ae4c-afec4828d9e0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 48).', '[{"id": "A", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '33395c9612e9ebd0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d925681-f4a2-41e2-9198-cb5cb421afe0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 48).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.245.59.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '41d6e6fc328dceab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3603723-32d1-47ab-b3c1-0b6d78f48f76', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 48).', '[{"id": "A", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "B", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines firewall rules for packet filtering", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'd2a892b80e4ba2ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f489e910-b9e4-4003-8710-0af1cc0ea1c3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 48).', '[{"id": "A", "text": "silent-drop", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "deny", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'c2fbf14801b82c05_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7dcf9174-9863-4094-81db-183d64ab118d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 48).', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "D", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'cd9d0a87a9e48418_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fd21840-0361-4cda-b678-1cde74992325', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 48).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "D", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'fdb9abbb48dfa2fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e3de736-41a0-4bd1-8bde-c44d0e8c14ff', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 48).', '[{"id": "A", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "D", "text": "No BGP configuration is needed in the fabric", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'b50b759053ab49c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fbc0d99-c3f5-48b2-8a4b-81ba5a1b447e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 48).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '5fe6edbb9e73ba44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b56e1a4e-0c5e-468d-bc0e-d9a0d53fdc61', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 49).', '[{"id": "A", "text": "Backbone Router", "is_correct": false}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "ASBR", "is_correct": true}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '84143141fa86c8bc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07766b82-67d8-49ec-a417-b1d90da71efe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 49).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "10 seconds", "is_correct": true}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "120 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '128d1740119f7e3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95915c94-6049-4702-ba19-54339836f9c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 49).', '[{"id": "A", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '1cfce79a09c3c028_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4792548d-c6e7-4c08-bea7-ed711de5ef18', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 49).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'f3b6ae20e601c956_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4597b58a-6714-48da-8111-917e09e64cc0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 49).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show ospf interface", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '1ece15be0eb55015_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82979ba0-8749-4c32-b12a-eae034e9c6dc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 49).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "C", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "D", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '8f03afd1983192ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0162d72-f414-4c06-a65a-1d656ce967df', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 49).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '94539fe9e625d488_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4f90c4a-3302-40b8-912b-19068cd8dcda', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 49).', '[{"id": "A", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "B", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "C", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "D", "text": "Both narrow and wide are supported by default", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '5d3e1ae488108434_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aab7cef7-9fbc-43b0-8e86-ed64d0d29e69', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 49).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '2b610baeec73de14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a470b03c-b100-43a0-a04e-479fdf3ff0f8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 49).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '26ff7742a35e8fb0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b999d4c3-e570-49ee-b83d-0bfbc30290e0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 49).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'ab2806c3ebc04899_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f901e158-88fe-40a1-b5dc-5ce542f9e302', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 49).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Configures the local preference value", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '1acd37b8327808b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2282aae9-6061-4d05-b68a-f4c97b1bf375', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 49).', '[{"id": "A", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "B", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '42f5f570e7e2e6ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b387c6d-41ed-456c-8f70-32f42326ed69', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 49).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '82049fae4949b10b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35897e38-21a4-40b2-a3d3-0e8456b2a859', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 49).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '1ec90543378e4d51_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4009ba87-8fd3-40d9-aea0-9b3dd4d24301', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 49).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '03d975465965acc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa517f9a-46e0-44ec-9289-96372d8f7db7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 49).', '[{"id": "A", "text": "show bgp neighbors", "is_correct": false}, {"id": "B", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'a480006ccd627a64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d74fe7b-6a9a-4777-ba02-1c80d49aea8e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 49).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'a3bfc98639259248_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('442863ae-383a-453a-8d4e-28376e6c2eab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 49).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "D", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '63342c6426ce8693_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dfa2173-4cab-4311-aba5-e377bca324ea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 49).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '58c4daa31d990f49_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e27cb4ca-fe4d-4f07-b660-3e4bdb0e2335', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 49).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '898c7708bd117def_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5ced25d-11f4-449e-b3ee-701919718033', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 49).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '7519268e74d8b8a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b04e9d7-c810-451e-8d76-1d0d25a4833b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 49).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Designated port", "is_correct": false}, {"id": "C", "text": "Backup port", "is_correct": false}, {"id": "D", "text": "Edge port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '9ddecd0d9bf4fc39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bbc122c-d916-496d-87e3-8bb1ab3124b8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 49).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'f2b3831a694a7711_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be086a95-13fb-4ade-aee5-1cd7fd28d3f5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 49).', '[{"id": "A", "text": "show spanning-tree interface", "is_correct": true}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "D", "text": "show bridge stp", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '1c4c2eca68082fd1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74f81192-9c07-47a5-b782-c566ceb464f0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 49).', '[{"id": "A", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'fb2afea470a8be13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c87b9359-a977-4717-ae36-3935677dc24c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 49).', '[{"id": "A", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65100 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '0f33ae0f96cd280c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b62b212-cfc8-460d-aa53-73e2ab8928ea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 49).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '6257f0349ee41d25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24390345-0f30-4474-a481-939367c94dfb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 49).', '[{"id": "A", "text": "set interfaces ge-0/1/1 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set interfaces ge-0/1/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set switch-port access VLAN 85", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface ge-0/1/1", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '2b339b720c4c19dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a79f561c-2c18-4427-b719-a33ea952a4c1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 49).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "64512 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'b779cb175b05a287_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d26196e9-5d00-40d7-b561-240785e7eb50', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 49).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'fd374b869b7106cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98b9f052-e6b7-4b02-8338-2db03ed16ae4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 49).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '5c34623553210633_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7993664-f1a5-46a9-89d0-baa313ec06ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 49).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '464cceca66583402_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdbaea4f-dca8-4c96-aa69-00de8c4d66ab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 49).', '[{"id": "A", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "B", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '20465070a3f44076_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a069eeb-b765-4996-9be0-c3a480c3baa4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 49).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set cos rewrite dscp 46 interface xe-0/1/3", "is_correct": false}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'e51c43bafa274e86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcfa97f3-6abc-4eda-881b-4256ad8dd9f9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 49).', '[{"id": "A", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "B", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "C", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'b7d56658f6130503_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78e39f83-3168-4c49-875b-50583c65fa03', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 49).', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Carries multicast group membership information", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'e0efb9330a687b11_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1da6135f-8ab6-40b9-9d3a-86281dc70ef2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 49).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '08024706ad351d5a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cacadc1-bca8-4b9b-87c5-09dab99ac616', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 49).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "C", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'd503b119bbc9ed04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12e1270e-f74a-46c2-ab0f-c93b2b62ce04', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 49).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "D", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '4ed6ab4b86020ac3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa06df4e-c4ce-4c0b-b0fa-73ffcc682330', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 49).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '4384ffaabdc0d18c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('420abc12-2ae3-441c-b764-485e76a169ee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 49).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "C", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "D", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'f45478aed82a90ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc6eaf63-0711-4853-8a85-3b3c98ed6351', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 49).', '[{"id": "A", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'dd99063aa7289559_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14cf62b8-ba7d-480d-b48b-fb1f523d5bac', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 49).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "D", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '3b57cbaa7bfda173_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07801d56-95d8-47eb-b8f7-b3d1b74d063f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 49).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "monitor trace <destination>", "is_correct": false}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '94ff8cba0a6ac1c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0f52851-5aa7-4f92-a766-7be889a03c6a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 49).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The OSPF link-state database", "is_correct": false}, {"id": "D", "text": "The BGP route table with all attributes", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '32e287151bed1fb2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b99d5d8-56f0-49d2-8346-48147da59352', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 49).', '[{"id": "A", "text": "All of the above can be used", "is_correct": true}, {"id": "B", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '376b8135667efd5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('768ca9d2-7a05-448c-95fb-9cf5af62fd91', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 49).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '1ed909b60852e475_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9cc6a05-59ad-41cb-9693-022cce46958b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 49).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.252.47.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'a86ff6f7dd548d5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4419819e-1a71-45f8-8f4a-d078b62b8b5d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 49).', '[{"id": "A", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "B", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "C", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '18c8aca6afcaedb2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('194ab31d-f0d9-4832-ba06-15aa68f03aa7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 49).', '[{"id": "A", "text": "silent-drop", "is_correct": false}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": true}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'c8b096772e6783dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b93269b6-6d7f-4dc4-900f-a4004fe9b66d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 49).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'afa9288cc57c6c82_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc8df110-cffc-4bbe-9e97-be257bcda90f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 49).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "D", "text": "Single switch acting as both core and distribution", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '071456fdebf96e41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91386594-4f33-455d-8c97-8c5ef03d27c8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 49).', '[{"id": "A", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "No BGP configuration is needed in the fabric", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '002272cb1d9b01a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('972791ba-dbde-4883-9698-71a2108f66a2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 49).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "BGP on loopback interfaces between the switches", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '0424c35c7f5bbc37_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca5ae942-01a0-4192-8099-2dbbc3006f0f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 50).', '[{"id": "A", "text": "Backbone Router", "is_correct": false}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "ASBR", "is_correct": true}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '2e6d771ddea0dc0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a52cccc8-537c-42e9-96f8-d6ff75e64fcf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 50).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "10 seconds", "is_correct": true}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "120 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '0f7bd5e7fd3a0832_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6eab12c-0b55-4210-8723-5c8f8225dd6d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 50).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'c0f12df4ce3e6791_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25a3b837-71ea-4811-949f-43ed2836f89a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 50).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '9509094d4f4c433a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c0d034e-61e9-4cca-a7a7-4e5b6a088b7c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 50).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '19321432893c86b4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e67115b-87db-4676-a528-ad011fa6bde4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 50).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '44faf85ac2c16582_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eedda854-1896-43ac-ac24-2f1c633d9f9f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 50).', '[{"id": "A", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "B", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '314ed1adbeadca8d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5484da72-48de-49cb-a72d-1dabb258dcba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 50).', '[{"id": "A", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '70ae943350895039_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec7a3708-a5d7-4938-b3fc-c7f4e9265c72', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 50).', '[{"id": "A", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '719fd05db252b41e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('868223a4-599e-4039-86fb-1c0719314777', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 50).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'af986e5bcedae159_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c0bd75a-9b65-4e45-b17d-895dcd928238', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 50).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'd79afb8eca7d47a6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('04ce2d67-4471-4b3e-8408-f5330072db9a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 50).', '[{"id": "A", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Configures the local preference value", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '0cdc9265da59427e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88a2e1d9-777c-41bf-b459-360bb6805bfc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 50).', '[{"id": "A", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '5613af5983c9ad83_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f9546d3-3f3a-413b-8cc2-c800f7044167', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 50).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '850010c0168569fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('89b9586f-d796-476b-8e3e-380aed0eca91', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 50).', '[{"id": "A", "text": "The AS of the route reflector", "is_correct": false}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'e30b435de7175134_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9e57204-d875-4f41-8d46-9b653887c93d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 50).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'ac341875fe434fa9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17bfe94a-3b57-4cb1-a92c-e6f94b6efc38', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 50).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show bgp neighbors", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'f647c9332fd94f9a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f051d399-4aa1-4850-9e79-8d77e898e55b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 50).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '9d1df7b1a051ab33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b5c841e-e906-4d8f-9a89-81dc0b3628b8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 50).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '2a9b637011fc8ae0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03165e63-ce98-4d3b-8a47-3cdd6e3fafe4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 50).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '8e46006ba24d7a50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('122f3bb3-d532-47af-a8d6-c5ccb4086f2a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 50).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'a904aed3be17de89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ef08e0c-e330-4731-901f-481786fda7ab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 50).', '[{"id": "A", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '7e57392c1ef14e5e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1406bb3a-59dd-4926-b925-4231c11d8a9b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 50).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'd7bb0c589e08388c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3481f3e2-04d6-4e25-bd80-8c2d6d9e0a3a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 50).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A physical link aggregation group", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '466fecce219c1338_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad1aa54b-6773-46a5-8434-6c246a6f74dc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 50).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show stp status", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '4a4af307798fe4e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9360af8-e0c9-42c3-b4f1-480d87585fff', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 50).', '[{"id": "A", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '380599133ca715a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('381aa6ad-b222-4b60-b55c-736de4a6dd2d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 50).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65200 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '2e947d909ad33f8a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4cf2601d-eb2c-43e7-ab3e-7349a6dcc3eb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 50).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "C", "text": "Connects to the management network", "is_correct": false}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '48e0fb9bea0ef1f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3353f09c-dd62-49ca-8340-9cc762cd5930', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 50).', '[{"id": "A", "text": "set vlans VLAN10 interface ge-3/0/1", "is_correct": false}, {"id": "B", "text": "set switch-port access VLAN 41", "is_correct": false}, {"id": "C", "text": "set interfaces ge-3/0/1 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set interfaces ge-3/0/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '83a9c454a618ddd5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ad7f339-7c1d-4228-83ba-15f807a35d84', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 50).', '[{"id": "A", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "65001 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'c75c0574ddfb87d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8a7ca29-2289-4af9-9018-52be913835aa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 50).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'f6b455ab9ba2ed1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d937a1f4-15d6-4e88-847e-cb99a74e951c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 50).', '[{"id": "A", "text": "56 (111000)", "is_correct": false}, {"id": "B", "text": "26 (011010)", "is_correct": false}, {"id": "C", "text": "46 (101110)", "is_correct": true}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '3250903476bbfe74_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5810cb1-00e4-4499-84cf-0d7e05be0347', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 50).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '593490330b6e3145_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22fe62e0-8c17-472c-b6bf-b6eb9aff8afa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 50).', '[{"id": "A", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '16fdb20abb8d74de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('188cf338-6483-4a6c-9b43-d6b6a6fa50d2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 50).', '[{"id": "A", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set cos rewrite dscp 46 interface et-3/1/2", "is_correct": false}, {"id": "D", "text": "set qos rewrite DSCP EF", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '27e5804df79efa9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('529f0ab1-dcfe-4e69-991b-a8dfdc8c9957', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 50).', '[{"id": "A", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "B", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "C", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'ef38e907733f6723_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17f862d8-835b-412f-af1b-ee3dc4079559', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 50).', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '66c308fdd1c4ce82_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac460b0f-91e5-4f1a-b725-b8a059cf35ba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 50).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "1234", "is_correct": false}, {"id": "C", "text": "8472", "is_correct": false}, {"id": "D", "text": "4789", "is_correct": true}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '1e3d40f3f41628ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('326d587e-d63c-4d6d-9a63-daa6c2246b65', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 50).', '[{"id": "A", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "B", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'fcdcc936feb26cf0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a55226ed-417c-432d-9b06-a67a9fbf9c9b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 50).', '[{"id": "A", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "B", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "C", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '04b570fec0d06432_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0634ba1f-6a69-4232-b14c-e553eb8f9b36', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 50).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '0e8362d771d83d0c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2c61d06-dde9-40d9-a07c-3e7e0e6328ed', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 50).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "Each host is configured with multiple default gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '9dcb0d0aa05e2c81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('547d23db-55d2-4099-b02d-9fd99c666ec0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 50).', '[{"id": "A", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'f971eebe90388a24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3578c6a5-13b1-4f2e-babf-00f8b6cb1793', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 50).', '[{"id": "A", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '4880e95eed5ac63c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('774d71e9-c5ed-44aa-bc54-19769623a36f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 50).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "monitor trace <destination>", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'd93ab645c316aa5b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bb0e8fd-4252-4e26-bb87-68ee6a2d3018', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 50).', '[{"id": "A", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'ad4f626bf0c028ae_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('593e8319-3dc4-468d-9aee-63f6e0d27147', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 50).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "All of the above can be used", "is_correct": true}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'c032583a579bddd6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d0217ea-e700-4ddf-9331-5263c00e2d9d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 50).', '[{"id": "A", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '85dcb5a092257abf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c09c84b7-b5f9-4e17-8c5b-f40c7e57bfa1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 50).', '[{"id": "A", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "D", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.189.176.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '751d5a49c15a840c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f051916-915b-4f77-856d-35faed491a9b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 50).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "C", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '4d17a9b3921389bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1969e2a4-9a01-463a-8511-ba0a471b35d0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 50).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '10b61b49e6672ebd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72c9c4de-ea18-460e-b8ac-ac8e9f72d6ea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 50).', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'fcf6d943f43b75e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6048b576-4cf7-4ad5-a41e-be33276dbb59', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 50).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '6e2ef03da2a1c13e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a12ff0f-cda4-4aca-80c2-0e868f5d196d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 50).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "D", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '8a179aff50dee11c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d94479b-08b6-40d0-80f8-051a288c4201', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 50).', '[{"id": "A", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '2fa443f8f137d257_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e6ca728-7bd7-407e-86b6-f3e5a6303765', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 51).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "Backbone Router", "is_correct": false}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'c0886bb08f650483_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21905981-4bfd-45b3-87ea-17960c3d77b1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 51).', '[{"id": "A", "text": "120 seconds", "is_correct": false}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'b6920042cc9bba9b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3342e3dc-0bdd-441d-b99b-72d31d78d837', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 51).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Connects to external routing domains only", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'da14c37775140f52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d39c0711-69b7-4066-b058-7ac76813e39c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 51).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '1e7783b464cb0345_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('879b2b1d-cf54-4da9-aa31-3d3707db2f61', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 51).', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'bfc17c2ffffcbd79_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da802f0d-2c87-47ee-8648-8fb83cbd0709', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 51).', '[{"id": "A", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "B", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "C", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '656f4d6b75a3d4d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8cc61bf-425d-4318-adb7-b187608f6e22', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 51).', '[{"id": "A", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "D", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '883aabf95e2b3b3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b03a6eee-42c9-4d15-83c1-57269f3fadbe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 51).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '4278f43587d101f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d58a128e-5bf9-43f2-a03e-894bbb15d9a7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 51).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '270b8075ddc04bda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d644ef7-1146-487a-ae88-58bb8923088b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 51).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "AS_PATH", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'cf52f167906b2d6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6984e790-022e-4961-8017-88cc4e62fed8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 51).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '6748d0fe31a70703_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f3260b1-4b84-4687-beed-a1e06248ea7c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 51).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '8b8ffe123b6dc474_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70b1ecd6-39a8-491f-a097-59215e9d435e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 51).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '17e4310d295241a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f40efce-f5db-4bf5-8e54-41248089b5ee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 51).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '2aa6932d98540095_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('809ccb72-811a-4f26-92f9-a1411dc0673f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 51).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The group of route reflector clients", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'a99610c8d9091024_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c15036e-1446-4e99-b241-b2ccadf71b98', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 51).', '[{"id": "A", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "B", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "C", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "D", "text": "Permanently deactivates BGP advertisement", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'b9727f1671d96b80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05dc256a-5755-437c-b795-3c339fd9985b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 51).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show bgp summary", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '5915c4b6765eda5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6182ed6-3eea-49e3-b599-b983af5249f4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 51).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "D", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'b2142fce32820cca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47c10e61-0eb1-4f7f-b9e0-6fc95265ecdb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 51).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "C", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '25d22df590e12196_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57e16904-a841-4226-9bac-faade4b06df5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 51).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'c6be5620a0d0555e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6066be0-159b-44e9-ad43-bdaccd65a6d5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 51).', '[{"id": "A", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "B", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'e905a8505769830b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5edfa0ac-533f-4f2c-9da4-2fc25a81da48', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 51).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "D", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '708c37446689c7a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae267f2e-98e1-4063-a21c-30bf39afad87', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 51).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Backup port", "is_correct": false}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Alternate port", "is_correct": true}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'd3cdd2fcab8dd7b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e1a0617-3a3d-4a3d-9345-30f573e9d499', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 51).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '9d88260857f8b991_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52696058-9760-4265-a115-6db03e2bcf77', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 51).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show stp status", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '29c5ec2a808ec9f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0aece7c-a1b6-4095-b663-2ef2a35ebe90', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 51).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '1369f90e3c413de1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d4358cd-df4d-47ad-b2be-ecd98d131168', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 51).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64515 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '34b1fee48544a472_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab468909-ec12-441e-a929-aa50a123dadc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 51).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'a28c77ed192e01ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47f0edeb-e968-4e07-b917-ddd6ae6e871c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 51).', '[{"id": "A", "text": "set interfaces ge-1/0/3 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set switch-port access VLAN 106", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/0/3 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set vlans VLAN10 interface ge-1/0/3", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '17ae89c1417abf1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c46ccd66-f4e2-4bd0-aa10-6faa1783730b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 51).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "65400 (16-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '6484ea6cee71589e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('097c36c3-bd27-4843-a730-5a16a0b99cc8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 51).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'a7b6595d43a56a41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('360491b9-5c44-4f91-a189-bf0aecb705a9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 51).', '[{"id": "A", "text": "56 (111000)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'b1013a276b26aecb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0ea0ac5-0019-458f-8823-3c9fc23b1085', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 51).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "C", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "D", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '399615e80cf7df79_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32600445-eb11-4f46-84e4-5f2cc98ec055', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 51).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '4d5cbdb37daa1205_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fdc312e-5a96-4bc1-a8db-761cbdbcf9b7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 51).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "C", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "D", "text": "set cos rewrite dscp 46 interface xe-3/1/0", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'b569777672e43d13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0600d14d-f080-406c-a540-f4ec37f152fb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 51).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '85c180dd2d675d64_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9e1effb-93d6-4886-8e56-5f2638e1379f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 51).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '026c96753d00fd4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5af21cc1-cd2a-4bfd-85bc-7c3641b54c74', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 51).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '535dd07cd0cef3e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8541c6d6-8475-4af7-97b5-05bd674df690', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 51).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'c650952d2898b4a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('625ac38e-295c-461d-9b2e-297f6c15d3dc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 51).', '[{"id": "A", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "B", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "C", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'd1d1cf374cf9c8d2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21ceef50-1eec-43a3-8cbd-594e7128bd8b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 51).', '[{"id": "A", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "B", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "C", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '309c8a4e23c6c04f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a5a1bac-2e55-41b1-b052-b36f39f04628', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 51).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '83f1122a979dec20_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d61c40d-d890-4c37-afc8-2f10702f3f82', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 51).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '0f7324e109b097ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6c8689a-3ccc-420a-9de9-b52a21176379', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 51).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "D", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'f312cff27e3aa471_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9dc8492e-adec-4c20-aecb-36d84e673fe4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 51).', '[{"id": "A", "text": "traceroute <destination>", "is_correct": true}, {"id": "B", "text": "ping trace <destination>", "is_correct": false}, {"id": "C", "text": "monitor trace <destination>", "is_correct": false}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '8cb8aa34dff2c28f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b284dfeb-ceff-4080-8536-6deacc24cda3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 51).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The OSPF link-state database", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The BGP route table with all attributes", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'f95b9ca6420b8703_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f535242a-770c-461d-a2c1-632f94ed8c09', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 51).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '114784721a1ea3ed_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ded2986e-371f-48fe-bf8e-f856f901126c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 51).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'b5a40881ef3a2f12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15bc435d-4bec-43a4-81fa-8a6ce9f6b4f0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 51).', '[{"id": "A", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.69.69.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'a0eb7e53912fca52_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a968fa20-baf2-40a3-8a3f-f5a1ddf4810f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 51).', '[{"id": "A", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '3c34fc0fa165f3a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f4ead0e-e675-42d6-ad28-99145b7b5fb3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 51).', '[{"id": "A", "text": "reject", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "deny", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '09e3d9362deda9db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b522dfbd-13ad-48bd-87c8-2d7af115abcc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 51).', '[{"id": "A", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "B", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '104607968e4b2130_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('340b0a4e-bfac-4011-ab26-352e58d2ea1c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 51).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "D", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '17c9dc2aa888006a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee8297ac-486f-4140-9d0c-4a29af9a8357', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 51).', '[{"id": "A", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "B", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '6a4de701776a802c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ae720b9-7f97-4664-bcbf-0b364106c7b7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 51).', '[{"id": "A", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "B", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "BGP on loopback interfaces between the switches", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'a26d77ac38b63ef4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44360b8a-6766-4d88-9a3c-f39074558a3e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 52).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "ABR", "is_correct": false}, {"id": "C", "text": "Backbone Router", "is_correct": false}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'ae57059a9e3d0b5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16585c3a-e68a-4630-8925-da0b709a12c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 52).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "40 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '0dee8772801ea619_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0943dc9-3a0d-4bab-af4d-0602162b4532', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 52).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '594c2f87fa9f2657_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c979d3b0-9311-4ae9-91a9-5dafaf05c917', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 52).', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '8321e68b4e45bff3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94e2623a-cd5b-4f32-b5af-c6297ffeebb2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 52).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show ospf interface", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'af4a24652ae2356b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28e2e256-2b3e-44ce-a983-4d9df3b7b1d2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 52).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '121abf3d72eefabf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b830cc0d-508b-49a9-afd6-9d49a91fda42', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 52).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'd7a22c1dea6e3dc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb64a3cc-dfc5-49eb-9a82-f5769f9fed79', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 52).', '[{"id": "A", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '8beee1368b0d66b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('812a2ff7-d330-4077-a329-b6ac1785536c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 52).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '0e9dfe1c0a9ca519_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8c75ad8-cdb6-4c79-96cf-3c4ee5acb766', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 52).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'a23bfea4f7b394a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99539844-1813-4e40-9ffc-9e6a36fe92a6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 52).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "64", "is_correct": false}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '8240a12e23a6078d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5793e1a2-afd8-46b9-ae67-5e95f830671a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 52).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'c9ea6d036f476250_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c67e71b-7f67-41f3-a1b5-d4afd2b1c8f9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 52).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'bc49a9c19de4090e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d090f0f-b206-47ed-a1aa-35e2fa0d28dd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 52).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "COMMUNITY", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '6e25af4585e1e7c4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26a066b1-6685-4408-bca4-52d3761713b1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 52).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '062b6c41b0a71ef7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25fe252c-b8e6-4f92-b0e8-bfdec8943651', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 52).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'afb723995f503512_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8522e30-647f-4794-af9b-8096674b9988', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 52).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '60d92f2b900330f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39b986cc-c2a7-409f-9f8c-a8fd7c049ea7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 52).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '0f01755bf40a7157_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8b8aaa9-d0cd-4cd4-8f1d-aab26a5e03ae', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 52).', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '648c927c4a2c1a93_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c938ba8-4137-4083-9f7a-06292c441410', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 52).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "D", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'a785c9ec1e67bf21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bfcc5b7-c6b2-418d-bda2-0670d56d8e1d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 52).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '68ecd1435c5f6760_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5256302c-e69f-4f6e-b047-6f38c6f8136f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 52).', '[{"id": "A", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "D", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '69d31ad832863513_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41f3579a-4530-47e9-8e37-d1947f722907', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 52).', '[{"id": "A", "text": "Edge port", "is_correct": false}, {"id": "B", "text": "Designated port", "is_correct": false}, {"id": "C", "text": "Alternate port", "is_correct": true}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'e7a735c1abb77798_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da42ca05-b10f-45c5-8d5b-54c5168e1e00', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 52).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A physical link aggregation group", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'b85715350b121814_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca2919f0-a4e2-460a-924a-28a6853187b7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 52).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show spanning-tree interface", "is_correct": true}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show stp status", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '5aa7e668c83c059e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64c700c5-0619-40f4-9122-68c5123254ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 52).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "D", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '9ff79b8972a95e94_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63205b4c-3a4c-49d1-8b8e-5682b9eabb71', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 52).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64600 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'e7035ec2a0e2fa35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a58a68c-8673-4361-844f-76cf4b11ee5d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 52).', '[{"id": "A", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'f4213a0ccee8348c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('012cf9fb-29af-4bd5-bbaa-fa0b06c5fd4d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 52).', '[{"id": "A", "text": "set vlans VLAN10 interface ge-2/0/2", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/0/2 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/0/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set switch-port access VLAN 251", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'c4111eeb2c3af496_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de70d4fd-938b-44ed-9758-04d1c1611216', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 52).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "65500 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'db0623cfa6c6dc9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcc4fc89-9318-46a9-9d0f-01798ecafab5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 52).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'fe73cc5a56e27ac5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cf52ebe-1777-4a23-a299-f376382e89e5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 52).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "46 (101110)", "is_correct": true}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '2b64d52ef26605a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bd9e1dd-0a27-4801-b200-82313ec28819', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 52).', '[{"id": "A", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "B", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'ebaac5a24f156515_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1af1c1e-36e6-4669-bd86-9208e97353f3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 52).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "D", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'ade3bc6b1f00620b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d610160-a100-4b3d-8a5c-1ca2b7244dba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 52).', '[{"id": "A", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "D", "text": "set cos rewrite dscp 46 interface et-0/1/1", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'a650a178bafa1130_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cae18556-4dc5-4f76-9564-dd27ba83ac4c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 52).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'b85fd5f6d78a3c2d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57fff3d8-0e26-4948-9a6d-0fae00246197', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 52).', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '930c5a0120908fa7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f5850ff-5c80-447e-800b-e172012a9a65', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 52).', '[{"id": "A", "text": "4789", "is_correct": true}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '14c564ac265dd934_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('935048ce-7d2f-4328-8e2b-bbb6b1c6c61d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 52).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'fe9017962e7d53c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('037cc4b2-ae67-4035-b9f2-d7fff0c80ca0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 52).', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '5559a95570588870_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2df66a39-1d44-4981-b199-671df9870e26', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 52).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '553af5ed67e03cc5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8377d805-a274-4baa-a4dc-9a7f074c8f62', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 52).', '[{"id": "A", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "B", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "C", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '94b12f8fba346c19_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64637691-0a9f-45c8-a6e0-429d89ee691c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 52).', '[{"id": "A", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'ea769cf544affdf6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54ee49aa-4238-400a-a523-d093f9c3fc65', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 52).', '[{"id": "A", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '427d16e37aa5b17d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5487b691-6fe9-4515-941d-11a8f86366be', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 52).', '[{"id": "A", "text": "show route <destination> trace", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '469e2dc9ce3e2e24_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07e30309-3f1f-47f7-b0ce-3a3c440f1d8e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 52).', '[{"id": "A", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "The OSPF link-state database", "is_correct": false}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '9dcaff4491027fba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('094447e3-c957-4ed5-be2c-c2ba15eb2e5d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 52).', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "show route <prefix>", "is_correct": false}, {"id": "C", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "D", "text": "All of the above can be used", "is_correct": true}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'cee7904523d6b3b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f76a4512-f209-4290-acf3-9bce1fa73435', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 52).', '[{"id": "A", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "B", "text": "Replace the interface cables", "is_correct": false}, {"id": "C", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "D", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '0623947d5ac5a7f4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e80c4b6-9c5c-49e5-bcca-d4ec96e237f1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 52).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.214.6.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '9764dc96b24d5d38_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eea53fae-d6f7-48c3-83f0-3a77582e532e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 52).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "C", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '7c1c7a2cc2ad7e37_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4718d2e1-3479-4f5a-b040-e2928a86422a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 52).', '[{"id": "A", "text": "silent-drop", "is_correct": false}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": true}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '2701cf44c7282ffc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d57f07af-e8f4-4ab2-8597-b70b5b1d40d9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 52).', '[{"id": "A", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '66a40cad361b3d77_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('885cc763-951f-4104-989b-293e99b1002d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 52).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '3f09ba631bce624e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('204fb072-a15f-412d-93bf-923e1b508b50', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 52).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'd6499cc8485a825f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37955049-8917-40d8-ba42-a9b9b66e1f70', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 52).', '[{"id": "A", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "BGP on loopback interfaces between the switches", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '003fef5bef79dd53_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('685030e5-6266-459f-9334-d0ace0ca1cbb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 53).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "ABR", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'e879a8152d31d73e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c7fdea1-3b1a-4fde-aa26-43ac7ead4967', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 53).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "30 seconds", "is_correct": false}, {"id": "D", "text": "40 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'eb7d4f7fd920eb89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85e7a029-df86-45ec-bd35-e0b26c2cedd4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 53).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'f5b124113224a584_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d342f54-baa1-4845-9be2-457c976f71a4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 53).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Advertises external IPv6 routes", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'ce80befbbbffdf68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cccddb6f-e656-4126-94b1-85396df9817d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 53).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '2a8e409a10a99018_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ecbc72b-a008-4dcc-a0d5-0424dae89efd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 53).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "D", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '4ef2fae6d248f1ca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb82caa8-1e93-4311-82fe-70e35f978077', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 53).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '99267e96d57ceb34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f150b83-cdc1-4de7-a148-0273a2c7a86a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 53).', '[{"id": "A", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '28f57d5bd5f3dc85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05f2c4c6-abb4-47e6-ba42-0bba7d842d09', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 53).', '[{"id": "A", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'ac33f74c70de4f58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b35d190-c8e8-448d-a31e-5a12e97e2e63', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 53).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "B", "text": "AS_PATH", "is_correct": false}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '9643c00301470bf5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29f0cbff-a798-47e7-b7fd-3053225b512a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 53).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "C", "text": "64", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '3041c01149b049c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31432c5c-a84d-4532-8f85-0bc54af429d2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 53).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Configures the local preference value", "is_correct": false}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Sets the BGP router ID", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'e9ce9f4571862919_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('becff757-e413-4979-aad5-5ace162f1e84', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 53).', '[{"id": "A", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '0701cf189802052a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2066abc-4880-4896-9fc5-93ec72b028ea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 53).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'f0bc155bbbee570b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('484934d3-fae0-4f19-9052-c6020dc500c8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 53).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "C", "text": "The AS of the route reflector", "is_correct": false}, {"id": "D", "text": "The IP address of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '4d94cea1e4a081bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7b0a060-4d6f-45fc-80c8-045e9bb2677d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 53).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'aa6a93cd67948cc1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a271d8b-4421-4747-963b-57300cc10fae', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 53).', '[{"id": "A", "text": "show bgp neighbors", "is_correct": false}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '5f46dc84896be71b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ace05133-e1ef-45e5-a27a-b540db3d8fb6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 53).', '[{"id": "A", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "B", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '7243e222a43b8106_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b89bc506-44ea-4bae-90ed-af5d535c0f46', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 53).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '69f1b92f9aa1080c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad86435c-dd8c-4e6e-9f1c-49f3b71b1852', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 53).', '[{"id": "A", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '63c692a16ce036b0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c158b9bb-3b6f-4576-8d9f-4ca7efe87d47', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 53).', '[{"id": "A", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "B", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "RPF is not used in PIM-SM", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'baccd303db6d62e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11dcb0c5-0e49-4d3d-aeba-6dd605ce76c1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 53).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '601365a3eed4b80b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5cef8045-9b6b-49d2-a6ef-2abba0366d09', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 53).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Backup port", "is_correct": false}, {"id": "D", "text": "Alternate port", "is_correct": true}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'e6b287f3f2aaedd8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca001a3c-e773-4348-8952-55126ccb48a1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 53).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '9277e656197a26b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6776b0a3-47c7-4a7c-9684-3769fbe4f8e8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 53).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '5864fb51daeaff73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fba9b51-05a9-4085-b898-2bde9a799882', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 53).', '[{"id": "A", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '847db892be253f61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6260cb0-5b1b-4553-91d8-0a8dd7548008', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 53).', '[{"id": "A", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65500 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '499138e9fc82c4d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60fdcb40-bad1-43c6-b804-8d1482523b71', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 53).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '1a0e8fdbecdb52b3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53ee902d-f58f-489c-aad7-bc9e36621daa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 53).', '[{"id": "A", "text": "set vlans VLAN10 interface ge-2/1/2", "is_correct": false}, {"id": "B", "text": "set interfaces ge-2/1/2 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/1/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set switch-port access VLAN 158", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'e19890ec37d100aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5561a980-9eff-4bae-9c71-fadb7ace5750', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 53).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "64513 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'c6b6f20b039d3502_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05dfcd2e-566c-47c1-b959-d78d8c49a65a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 53).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '73d161b4a509d47e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48823a7d-1ba5-4832-b62b-8c92d132e151', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 53).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "56 (111000)", "is_correct": false}, {"id": "C", "text": "46 (101110)", "is_correct": true}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'eeb3047535e4ae5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37842c15-7774-443d-ac52-2dfad9d70645', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 53).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '16896954d9cd574f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4bace25-c11e-4b20-b03c-42bf40c32b4d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 53).', '[{"id": "A", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '5624aa432b649378_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4278e1bc-8ee3-4333-aaf3-0ea1f96aef51', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 53).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set cos rewrite dscp 46 interface et-0/0/2", "is_correct": false}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '22bacf85aeb7bbd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbb78e17-dd94-474f-9ebb-eb5ede330768', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 53).', '[{"id": "A", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '8f16590c0ce4654a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e1310a8-f316-465d-8121-8ab28ad8e3d6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 53).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'cee4f45da7e36c88_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be9db8a8-277d-40fc-856c-46eb0970f472', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 53).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "1234", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '59d00db6e173b1a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d1b9fa8-8536-4724-9106-19ec802a9a16', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 53).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '4d4fd35ffedc4e40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d97ba84d-57ac-4f5d-a39a-1bc8fcad450c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 53).', '[{"id": "A", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "B", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '6f0af7248230929f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8889ab7c-df0e-4823-a35e-e3df8a619e0a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 53).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '7ca11dfa1566099d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f092a67-786c-42a1-a427-e4f56ec5aa8e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 53).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "C", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "D", "text": "Each host is configured with multiple default gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '57fe22700fdaf3ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f5c2086-b75c-451a-b03c-4e0b29b19f0c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 53).', '[{"id": "A", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'e0d55d03adaece3c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('592b6a44-0df4-48c1-8bbf-9e6696c91134', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 53).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "C", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'bac78ea170cb80ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31884aec-7b1f-4063-8724-1398c7347450', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 53).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "show route <destination> trace", "is_correct": false}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '81bbef4893809723_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd199b5e-3304-4702-a25d-1a49e1d48c6e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 53).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The BGP route table with all attributes", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '997e735afaab6194_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c28c86a4-60a9-41e4-be15-bbe909934fc8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 53).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '65915b9b2b264ca5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6889de5-e7f0-4f59-a6bd-7be6ea20f473', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 53).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "C", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '917db7aa4bc4921e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b598409a-6dd0-46fa-a9fd-166856e85530', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 53).', '[{"id": "A", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.61.235.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'becaf60e7de80520_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f55ea542-45f3-4bcf-a11e-f243ab755f6f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 53).', '[{"id": "A", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '5da97f0f6e473209_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b612e8f-1454-4301-8e3d-cabcd00c170c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 53).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'c2e74ebda441081d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35dfee4d-4726-4954-bdad-c7b676a1ce26', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 53).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "C", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'ce183f1ad37d785c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05d293e9-6a32-42b4-b5e7-da8162f8efda', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 53).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '9b6a9b0e2a151c82_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('216fe95a-c5f9-4a15-96b0-326354f95299', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 53).', '[{"id": "A", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "B", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '684e2b3c9a8cac30_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a24e69a1-a90f-42d9-8e19-f464daa637a4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 53).', '[{"id": "A", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "B", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "C", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '58b0c7e2e83170c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54031e32-ea90-43e6-befe-48146cc46252', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 54).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "ABR", "is_correct": false}, {"id": "C", "text": "Internal Router", "is_correct": false}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '7ad2226c64a01869_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('255c794a-5900-462d-b4a7-ed8f3119bc52', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 54).', '[{"id": "A", "text": "120 seconds", "is_correct": false}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "40 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '22bc2c6e1f52460e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc165139-2954-4175-9d7f-b44094ddb29f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 54).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "D", "text": "Connects to external routing domains only", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'cd925c77a1bdab13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65bb1b18-9372-43f3-8da8-6bd2b9b94ddb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 54).', '[{"id": "A", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'fd6f6ff5bc3b6cb3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea4d1ce5-21e7-4170-b88e-22807d8cd21d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 54).', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show ospf interface", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'b770a9f41c98748c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('728c8185-47e1-484f-abee-237f870a0e65', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 54).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'f3d6ef301841f0db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1d0b7ac-e67a-4215-81b8-1456b85e021a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 54).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '2f426b4d3b202c4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96586fbc-bedb-4a95-ab42-623df5c6549c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 54).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'f3723d1971b1fe04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f7a3706-baea-4caf-baf7-d7607a189c8d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 54).', '[{"id": "A", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "D", "text": "Hello PDU (IIH)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'c74876f617cac198_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b326dd52-a5e1-4df0-8f45-9bfe11617959', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 54).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '22dbf4a8459ddb2b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92ac1ac9-1b35-4c90-8583-7549f18ab700', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 54).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "64", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '24f2fe6d1abb5b6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bb2300d-2432-451a-9b82-00c13328c517', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 54).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '4e2c05e9df32aed7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ea8a9f7-f903-4a59-a8ba-89df0cbf6910', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 54).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '5fdf296bd6c59189_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('116203db-c741-4dd2-a986-11a286c0add8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 54).', '[{"id": "A", "text": "COMMUNITY", "is_correct": false}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '3ac7b749254f05aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d9810ea-8965-408d-a71b-0377e3960dfc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 54).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '69e469a5a7b781b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99e416ab-ce10-4732-838c-02dc51405814', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 54).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '0f8be07b81e9d463_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5863bb16-9d8d-4ea7-9cac-51e4d17e7ec0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 54).', '[{"id": "A", "text": "show bgp neighbors", "is_correct": false}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '2fdf90522ca2efdb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a50b0695-a58d-4c8f-b490-310fe1aaaead', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 54).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'b83687fbe188b852_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c2d82c5-3d49-43b7-b0f5-eb3dba6269ef', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 54).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'a804d24ec8ac5306_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcebec10-b558-4c7b-a7df-f17e02bd9f25', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 54).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'b4b49bea088b1a32_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ba1bea4-d8b8-4859-b072-03e882aaa5d6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 54).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "C", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "D", "text": "RPF is not used in PIM-SM", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '31183b48ae3678ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7149ccad-11d2-417c-82dd-b70e74747481', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 54).', '[{"id": "A", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'c978839c661040da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bc1b9aa-f058-4fa5-8efe-84cb58d6ab87', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 54).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Designated port", "is_correct": false}, {"id": "D", "text": "Edge port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'e981e6180e7f582f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a302a950-1bd4-4a5f-8354-ce27481721e2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 54).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '8ebbaa09c28922dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6abb26f7-b79f-437a-a9fe-f3577b11b3cb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 54).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show spanning-tree interface", "is_correct": true}, {"id": "C", "text": "show stp status", "is_correct": false}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '4f2d28fa74ac7cd6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7042dfe-4d5a-49f2-bc0a-cc4c75ee2e94', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 54).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '99cf037725a23478_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0cc742a2-6dc4-4ff0-9a4b-1b1bb676f0a0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 54).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65001 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '49f18bfa8f7d9ebd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3235ec11-aea7-4183-879d-9d31ed517329', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 54).', '[{"id": "A", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '0181ba877607a429_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77ce0133-a085-444e-9ece-197103738e5d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 54).', '[{"id": "A", "text": "set switch-port access VLAN 150", "is_correct": false}, {"id": "B", "text": "set vlans VLAN10 interface ge-0/1/0", "is_correct": false}, {"id": "C", "text": "set interfaces ge-0/1/0 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set interfaces ge-0/1/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'd62c5b388bba786c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa32f067-c372-4fe3-be25-231f5998c761', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 54).', '[{"id": "A", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "B", "text": "65300 (16-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "1024 (10-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '8a47f573dca8e2a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc63c14b-0d92-4032-9049-ccadbcb4f448', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 54).', '[{"id": "A", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'b1d2aa7a0f971a9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f0116f0-e08a-4d6d-856d-5a0cb61b36a4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 54).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "56 (111000)", "is_correct": false}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "46 (101110)", "is_correct": true}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '63a5a3e862ee9e0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e5a1840-c71b-4671-ba2d-06035cf65744', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 54).', '[{"id": "A", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '9ab684300ca15f61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f655608-6ce3-48ef-b59c-e2dbf5a12f84', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 54).', '[{"id": "A", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'd3747e7e8471c252_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5c92e9d-9e48-422f-89fb-7639df0fc02c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 54).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set cos rewrite dscp 46 interface ge-3/1/2", "is_correct": false}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '76b745bcc96e1772_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71c1695d-6c84-4433-b31a-795e4ef70e1f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 54).', '[{"id": "A", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "B", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "C", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '845aa24ff5a6506c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65eb0ebc-7c33-4bf4-b826-b86f029b0004', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 54).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '6c1760cc16751bdf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f84725af-bcd7-4f18-94e3-a138e60eb119', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 54).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "1234", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '62bd6e40414bbd68_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('782e1dfd-2dda-4591-b557-67bdc33888b1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 54).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '0f77b12bdace64fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c999c1c-2542-447f-ad21-df974b6660c7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 54).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '98d7e09d058c3775_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21eb27eb-3c28-4e9b-befd-edb9460361b0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 54).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '0fdcc5c6229c675a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54b96d65-7cae-4ba1-8c17-a6f0f0bb653c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 54).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "C", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "D", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '82606cbdc6b960ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39377006-8b1a-411e-b08b-2286e4657ea5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 54).', '[{"id": "A", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "B", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'd7f4bdb0983ebd71_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad8e325c-7b91-4c3e-b27f-c7f6ed0f7217', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 54).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'c9ae67ff59fae60d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b27989b-1b01-4a40-b6d5-499ed70c32c9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 54).', '[{"id": "A", "text": "show route <destination> trace", "is_correct": false}, {"id": "B", "text": "ping trace <destination>", "is_correct": false}, {"id": "C", "text": "monitor trace <destination>", "is_correct": false}, {"id": "D", "text": "traceroute <destination>", "is_correct": true}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '7515d5d2cf5a3ab2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee894155-83c6-42a5-be37-85d10798bc3c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 54).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The OSPF link-state database", "is_correct": false}, {"id": "D", "text": "The BGP route table with all attributes", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '55cea6dcd3c12bfe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09798550-0be5-4deb-858c-ca262f2481cb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 54).', '[{"id": "A", "text": "show route <prefix>", "is_correct": false}, {"id": "B", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '2dfd1558e582bab8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3eb10311-bcb2-4441-93bd-1889f3c3de70', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 54).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'd2815b80bd0b7ae1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2071a734-7f4c-4144-9465-396f2bc0470e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 54).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.35.107.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '16a13f30aa4c921a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79c81847-2e52-42df-b399-a0dc5e608114', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 54).', '[{"id": "A", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "B", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Defines firewall rules for packet filtering", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'cec98db88e198f5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67136e60-0760-4c03-9e53-2b52fc5c6b74', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 54).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "silent-drop", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": true}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '3d5771a296fcb1cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('569c219b-469d-4471-9a1e-6c87fa8cdd26', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 54).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '6dffb5efa30e1cca_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97d7637e-4346-404c-9181-6c605170245e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 54).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Single switch acting as both core and distribution", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '1c7c695158da34f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c5c7f46-655d-4f1d-be2e-1609f67bd82d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 54).', '[{"id": "A", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'bdc3e13221da6a0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44512e4d-7826-4275-b003-14d6eda1c598', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 54).', '[{"id": "A", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "B", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "C", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "D", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '2f3abcd78a443bf5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2d4bb63-bcc3-4d28-9eae-dc8ebaecc04c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 55).', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "Internal Router", "is_correct": false}, {"id": "D", "text": "ASBR", "is_correct": true}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'acd311b291c5adef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c6b8d5c-7724-4cea-9aaa-68601bee0d31', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 55).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '3f131758080b3ea8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('828068f8-d5a1-45c1-b5c6-c7191f607782', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 55).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Connects to external routing domains only", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'd7eb543237542950_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86d41462-2c28-4331-8064-a41b33716a83', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 55).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Advertises external IPv6 routes", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'eba0147f9a6fcc84_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90717338-be09-4fff-97b8-68c10e89039e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 55).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'ad36c0c8082f960e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10b344f3-7b5f-4ab6-a22e-4cafa85ad6fc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 55).', '[{"id": "A", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '3207f005116d437f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cfbf1e4-d610-4e32-a12a-4bf971bd9e9b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 55).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '0ccdf4e0a4a4ecc6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76c2c4ab-81eb-4534-be12-03a39d92189b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 55).', '[{"id": "A", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '38f6461d60d3e1f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5786264-3cc7-4319-8cc9-a8e4e781ddb1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 55).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '621504e45da2a243_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbe557b0-9f4f-4b2e-b354-69c88fb191d1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 55).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '645f457e011b2603_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e24134ef-9711-4c2e-be14-c3696432c472', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 55).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'dd6a8dbd5f78a245_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52e71d33-f208-457c-9264-c3cab5d1029b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 55).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Sets the BGP router ID", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '318ecb84828f567d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b910014b-b390-4e86-90d4-6761da5d54d1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 55).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '058012c8da41272c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a002635-70af-4d08-a5fc-b6d729a67d7f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 55).', '[{"id": "A", "text": "COMMUNITY", "is_correct": false}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'efc2fed6720b0d8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b86ddf87-41ff-4c77-90b6-c3d23b20b38f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 55).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "C", "text": "The AS of the route reflector", "is_correct": false}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '8435ae373eb34eb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf0001e9-24ab-4429-a308-1de861bc2141', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 55).', '[{"id": "A", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '495d5f03e4706b33_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c2d05d7-69a2-4cbb-ba37-bbc27929814d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 55).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show bgp summary", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '594675b4ef90649a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a38d584-f32a-4d8f-a6ff-6a018a346ead', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 55).', '[{"id": "A", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "B", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '2765348f5cfec0b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e8efaf2-b692-4168-aed5-d7a30f1b2c04', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 55).', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '581853a269ac83c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08663cd7-96cd-4cbe-a85e-36b5da72c412', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 55).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '36abc4e2215321a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f387d83-1cfb-4c73-a994-1301f32abddc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 55).', '[{"id": "A", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "D", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '017b1a502094d648_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2638c410-74fb-463e-a009-8116e29fb4e6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 55).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '3fc863834637aca2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6de7efbc-ec87-472d-8f78-8698af4df520', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 55).', '[{"id": "A", "text": "Edge port", "is_correct": false}, {"id": "B", "text": "Designated port", "is_correct": false}, {"id": "C", "text": "Alternate port", "is_correct": true}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '0b60644c23c7f920_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('deb85298-3b8a-4b74-99a5-c61ba2210925', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 55).', '[{"id": "A", "text": "A physical link aggregation group", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'f0e239dd74014876_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ff2ee4e-b0da-43bf-be0c-e9dcc886c066', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 55).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '16b131c7836690e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b04470cd-bf35-4533-a89f-4ab71238148d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 55).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "C", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'fac5e00b7bf2fee2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cc84e9b-28e9-4d59-8e83-81607e4358aa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 55).', '[{"id": "A", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65200 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '2069f233d5958154_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80ff7692-bc63-46d9-94bf-f2b0565f57b7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 55).', '[{"id": "A", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "B", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Connects to the management network", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '437d4c659ae4ae9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ca9e96c-5e72-46d7-be65-a83ceeca2187', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 55).', '[{"id": "A", "text": "set interfaces et-1/1/2 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set interfaces et-1/1/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set vlans VLAN10 interface et-1/1/2", "is_correct": false}, {"id": "D", "text": "set switch-port access VLAN 451", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '0c1420312daf5b0d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecf98b33-71e0-45f8-bddf-540f7363503b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 55).', '[{"id": "A", "text": "65002 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '2103bcc7fe823e5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f244e6b-9977-4612-a149-0fd17e719499', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 55).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '9a477e58454a343b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('995d740b-9ae8-4f9f-b37b-7f1b421acba7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 55).', '[{"id": "A", "text": "56 (111000)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "0 (000000)", "is_correct": false}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'ccb1ccbe5d28c366_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f52eca2-7fce-4204-85ad-239a9daef6e7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 55).', '[{"id": "A", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '69adb70a00d09b10_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf4cbc0f-4727-491b-b142-0075c4893e3f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 55).', '[{"id": "A", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "B", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '244da5bd85b05d1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23ea2e98-4e4f-4500-9aa0-1286ff56ef66', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 55).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface ge-0/0/3", "is_correct": false}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '91e9ca0513053942_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e088e08-9863-40f8-9e68-79cd5c9c42be', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 55).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '3913167a86e769e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b1954af-cd81-486b-b941-679532f4c207', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 55).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'c3cc906dbc97e552_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9607f470-f14c-4587-8233-179a52a9197d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 55).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "8472", "is_correct": false}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '2ec3f08c252e12d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dec98e02-13fe-4ad7-8859-309167669461', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 55).', '[{"id": "A", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '960d75a93e34450f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ef39bbc-5a75-4f16-806e-4ea889639a70', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 55).', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '8f32fe538ab4d345_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5abeac41-6ef2-48c7-9345-189e59ff8a8b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 55).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'ac3d27531c23cdfd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94a1eff0-8d62-4acc-abc7-1f3c7e116a8c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 55).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'e2fd3c7ac03c8be2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecfc1d77-3d13-4687-baf8-4965523a17a5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 55).', '[{"id": "A", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '07b842743ca0cdda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f535375-05e0-4a87-b4ad-df44b24aba34', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 55).', '[{"id": "A", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "D", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '9b74ec0f15b6fdf9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2084ab5e-1c36-48f0-87de-078eb638be64', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 55).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "monitor trace <destination>", "is_correct": false}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'a1bbf697a327d31e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('968cfdbd-96be-4e50-8f1b-1accd9380221', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 55).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'a3d579a19c7b5600_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2eb67734-5031-43d3-82f4-55c6ed3b4e4f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 55).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "show route <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '93c7a433bccf16d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e70e54b-aa76-4cd0-ab6f-f2d9bd87a8f3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 55).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Replace the interface cables", "is_correct": false}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'db084b7c9cd852ba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd75cf67-abef-49ee-aa30-c8d12c96ecf6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 55).', '[{"id": "A", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "B", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "C", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.194.162.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '19ef3b237715c0d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22ddb9dc-b1f1-4fb3-828c-917f5e1b4b8a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 55).', '[{"id": "A", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "B", "text": "Defines user tech permissions to the device", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Defines firewall rules for packet filtering", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '375f2500bf75594c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddfeee19-c31c-46cc-a1c6-4587adc5c707', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 55).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "silent-drop", "is_correct": false}, {"id": "C", "text": "deny", "is_correct": false}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'd5a4a4ca10aeb3dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cefe5de9-44f7-4b45-8571-d8228ef877a9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 55).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '45d09e48fa8fd02e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58848736-3b1b-443f-b7d9-e2f0aecd0d08', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 55).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'c9ff60ce842b1a7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21938544-1d6e-40da-9816-3a440cfb773d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 55).', '[{"id": "A", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "D", "text": "No BGP configuration is needed in the fabric", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '3f61cbe3c4112ef3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebcfbeb7-b46a-4c40-8f25-aa7a14238b7e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 55).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'f934558677571898_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc72d2ce-df92-49c5-b83d-c65330814af5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 56).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '0b6159e517076a60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d369dd1-aa75-4d77-8208-fe28030c0914', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 56).', '[{"id": "A", "text": "120 seconds", "is_correct": false}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "30 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '362ae1bf4935c423_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69162e2a-6030-4138-8934-031289dbdd8d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 56).', '[{"id": "A", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'b25df4a2fbf0cd61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68bda837-5a93-42c7-8197-04eaa2b16cad', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 56).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Advertises external IPv6 routes", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '634c375324a7bf95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2d043ab-022d-468c-abac-77cba76d6eec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 56).', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "D", "text": "show ospf neighbor detail", "is_correct": true}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '5f458fea8179738d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fa72888-c0ad-4d3c-b592-841726d3a328', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 56).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'c3dcb3018a9b64f7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3cc2cc4f-9293-4d75-8ec8-3f1c4d36e5c9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 56).', '[{"id": "A", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '6be2647967b75824_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d6b7f60-de9a-4e3d-ad80-aa1105c07f97', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 56).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'fe1e0c20b86b6b50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e8fa541-9561-4e75-b9a7-c8758b275d65', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 56).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '2d12aa63d2d4fcff_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d20bee9e-d442-4d8b-8579-1d297650712a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 56).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '2a8d87bf48511f08_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee2fe963-8e24-4af9-b24c-8775d56dc854', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 56).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'f3b56282cfe1a751_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7724f9a6-b5f0-4058-86a4-7dd855461abd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 56).', '[{"id": "A", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'f7c38f7d2a12e7ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2d81a20-d50c-4d49-ad69-ceab4f0464eb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 56).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '5d49f6eba43d9e80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99fa4829-a783-4710-b221-3f3e0e0ecd1d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 56).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "B", "text": "COMMUNITY", "is_correct": false}, {"id": "C", "text": "ORIGIN", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'c1dedb08c1d72052_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8017ac3b-da7d-482b-8933-2ca611824b3d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 56).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '6605dfe1f0306a54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('715e86c3-4a71-4eaa-a513-103175e4e92d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 56).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '23bf14b87af87461_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c5756cc-ceb9-4a1d-8e2a-3ef92bd4d080', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 56).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show bgp summary", "is_correct": false}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '259fa2057ad629e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43d4494b-cc70-4743-b76c-c6791c865647', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 56).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '61b1629aef8f66ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f83354ed-154b-46fe-ae0f-22b54ef43066', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 56).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '96c99ca203097f3e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc3f0ba6-6570-4366-a6f8-7d7f689df081', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 56).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "C", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "D", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '9ac396b1fb6c746c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08dc6655-7aa0-4ac2-a502-1224c2584b10', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 56).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '4b7c8eb04f2576f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20548e01-f6a1-4bb4-8702-109dada5ebfc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 56).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '63459ee5a44dbaa0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('287e81d4-6ff4-4b14-99b1-53098da47217', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 56).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Backup port", "is_correct": false}, {"id": "D", "text": "Edge port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'd11cccc92addd835_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ba40cbc-d04b-43be-95f2-4ccd61730ed3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 56).', '[{"id": "A", "text": "A physical link aggregation group", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'bca55403b6fc45b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfd1d87d-1b97-488a-a6e5-93fd24bac097', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 56).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show bridge stp", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '8bc655ab00a9251f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('251383ec-2c3c-4b27-8627-70822a526c2a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 56).', '[{"id": "A", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "D", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '4a58d2f71b63f1df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c0a9a08-383e-4101-b8fa-343fc3f5ffab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 56).', '[{"id": "A", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "D", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64600 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '9e07b245ba5dc8de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4326edbf-034f-400b-b73c-b821cfbafc3b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 56).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Provides PoE power negotiation for access ports", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'aca9eca800f9b50e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71cf67a1-2511-4923-a11a-5d731d1562a7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 56).', '[{"id": "A", "text": "set interfaces ge-2/1/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set switch-port access VLAN 335", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/1/1 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface ge-2/1/1", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'cecec562fca20b57_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa91a1f0-f2a0-4b98-9557-171c77dd3ec1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 56).', '[{"id": "A", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "64515 (16-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "256 (8-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '72bebe65da0f99e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d773fbdb-e8ca-4b65-bed5-b3a5e4dd91f7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 56).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '508dfba0975b3e26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('badd1692-2af4-478a-9578-2a5ebc514a8a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 56).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '68b86f341d918ff4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d012de58-179f-418b-bcbc-884cda54c154', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 56).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '80582e583995f25e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b2985b6-ac3e-47f7-8d2d-a371a04368ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 56).', '[{"id": "A", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "D", "text": "Determines which packets are forwarded first", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '9904c2d64f4199dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97f3efdf-f015-454e-8eb3-e4e95e091ce6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 56).', '[{"id": "A", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "D", "text": "set cos rewrite dscp 46 interface xe-3/1/2", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '97833103451b5bc9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33abd142-a663-4553-9d61-83afae59a94e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 56).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '2b54b0946c88dd5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a1a6bd3-0bd6-4657-869b-30088b468c3b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 56).', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'a246dcf37171dc97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('677e395d-f3c2-4034-a1da-06b7baf7213c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 56).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "1234", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'f6af30083c8064b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fdd8e6f-3afb-4c1e-97e2-5671f17eba04', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 56).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'ae652e29a7a52c02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9627e5f7-fbbb-4769-9c65-02ee9e7c6c19', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 56).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "C", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '04162a3ed912e709_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('761772a7-afc1-4d33-910d-208c76a50350', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 56).', '[{"id": "A", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Uses STP to detect the topology change", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'b3576553c080344a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92cb93dd-921e-4f92-a52f-2e571669065e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 56).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "Each host is configured with multiple default gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '5e1394779f94b6ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99d0e0fb-db62-49ba-9ec9-0c1c86f5ea07', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 56).', '[{"id": "A", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "B", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '5a8b586171e6f2aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed524625-b406-41d4-8243-bc47f1262371', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 56).', '[{"id": "A", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'a2cebb983ce66c95_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0063abca-a233-4615-88ae-ac8b014f4748', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 56).', '[{"id": "A", "text": "show route <destination> trace", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "monitor trace <destination>", "is_correct": false}, {"id": "D", "text": "ping trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'c8b4d8ee59aa3f70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('def1b682-3da9-4547-badf-60ec3d37307c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 56).', '[{"id": "A", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "The OSPF link-state database", "is_correct": false}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '2d5aeb7db02b3b8f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c6477e25-5cf4-4dee-83a1-213e9780be06', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 56).', '[{"id": "A", "text": "All of the above can be used", "is_correct": true}, {"id": "B", "text": "show route <prefix>", "is_correct": false}, {"id": "C", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'bb0d0bdc8529ce73_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42832187-19d0-4c5b-a9c1-fc71ff2878bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 56).', '[{"id": "A", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "B", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '9233fb8ac755a23e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b777a88-dcf1-4711-8f81-99204ab0c398', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 56).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.168.132.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '67d25ee0859e22cd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d104831-780f-4c8e-bb77-7232cb27227b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 56).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "C", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "D", "text": "Defines user engineer permissions to the device", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'cf2a0f25b0a843fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61f1cda1-57e9-49d2-aaa7-473b4f4abadd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 56).', '[{"id": "A", "text": "discard", "is_correct": true}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "deny", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'c9f0b4d0d53ac4f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9073db80-0a37-45a5-b424-85d854d931b5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 56).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "C", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "D", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'afba14cef930e987_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa87e7b8-c29d-45d5-bad5-74c83c96cff1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 56).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '35550e2c2276bfd3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a1ac54b-3954-48fb-9036-ed42266ca35b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 56).', '[{"id": "A", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "D", "text": "No BGP configuration is needed in the fabric", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'fa7d0ecc69856b8e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90b5a362-f435-4641-a007-4b36298d3fe5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 56).', '[{"id": "A", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "BGP on loopback interfaces between the switches", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '02b097a3cee3431f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b98b64df-17d1-456b-9217-5b9497a1a417', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 57).', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "Internal Router", "is_correct": false}, {"id": "D", "text": "ASBR", "is_correct": true}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'dfd4113152de8dba_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18d33270-bdf4-411e-a848-00f2503e352b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 57).', '[{"id": "A", "text": "30 seconds", "is_correct": false}, {"id": "B", "text": "10 seconds", "is_correct": true}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "120 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'fca37897d80ee6a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a654ac1d-24c2-4fcd-818d-cf156f3f6a51', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 57).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '12cb3feb753d13a9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0dab48b-7b20-456d-a12f-418fdd5174f8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 57).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "C", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'e9ad2fa4317d3aad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e0c4c50-d608-44ad-9956-6f1c3061894d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 57).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '51e6c5016db16132_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94873bc3-2a5e-4385-a5be-e497a0221ba3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 57).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "C", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "D", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '0d8780287a81c81d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d370a8f8-4e2e-43e2-9e50-042ac89a71f2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 57).', '[{"id": "A", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '52a69dc7695f4be4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08157f1f-a91d-44fa-9ea8-c62bacb8ede9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 57).', '[{"id": "A", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '430473a83aa045a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2490a19-6f35-45e4-ba7d-9287c30f48fc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 57).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'bdeb5f33bc69cb26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a3ababc-4245-475f-b144-5db7d266c6d7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 57).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '503a83cdb16fafbe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9609109-5cfb-4865-84a9-704c2b561835', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 57).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "255", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '785b6604478cb07f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02924f07-9f18-4efe-ab53-955c837fb77d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 57).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Configures the local preference value", "is_correct": false}, {"id": "C", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'd15972f722ff0e50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb4592b6-c03e-436f-8e95-c390fa9471d5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 57).', '[{"id": "A", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'c5e29bba0eddb628_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33474107-91f1-42ca-bf12-930278318cda', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 57).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'f56c4363852827bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e725957-4422-411f-8ab7-c72ca681c145', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 57).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "C", "text": "The AS of the route reflector", "is_correct": false}, {"id": "D", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '7db0263155870bb0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9829c79-b77c-4a8e-a8fc-971dc3751d31', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 57).', '[{"id": "A", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "B", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "C", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "D", "text": "Permanently deactivates BGP advertisement", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'f7dbdad5c4e711ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0f5c361-5d90-49ee-9384-aead12cd4e2e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 57).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show bgp neighbors", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '5d389675ddedaa92_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77a9b86e-1729-401f-b94a-9305540856b7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 57).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "D", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'a80f1b2b54fba638_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2498aaf3-9082-4deb-a17f-0b70a6b6aa3e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 57).', '[{"id": "A", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "D", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '0db8f0d9ce06f420_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b598685a-bcd8-44ef-a7d0-4d78c728691f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 57).', '[{"id": "A", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "B", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "C", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "D", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '7b8a7ab00d5568ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ac71914-517c-4124-a3a0-3824ec85b3ce', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 57).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "D", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '37f675c348ba4a9e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7e79c33-ba10-443c-af6b-d2f309daa20e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 57).', '[{"id": "A", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '309ae0ad33565fea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e735d5d-5194-401a-af30-36287efc7755', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 57).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Designated port", "is_correct": false}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '44f2797ff3394fa2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6098dea0-3ecd-43c4-ab1e-4fd57a1000f7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 57).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A physical link aggregation group", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '5fae10d672fd71fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0befd1ab-187a-467b-8106-627c6faa782c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 57).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '565452f43f7010d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('016965ef-3d26-4093-b1c0-8a626ae00f55', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 57).', '[{"id": "A", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "B", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'afcd516591bd44d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1c07c8b-312f-48e2-8317-a7be50fd3067', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 57).', '[{"id": "A", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65001 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '89783ed6863c05f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55fcf3b5-179c-42ac-8a09-d22037126d0a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 57).', '[{"id": "A", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'ba5b1de3d9bb7b76_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca2f0b07-0a97-460c-be7a-96a928f13f93', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 57).', '[{"id": "A", "text": "set switch-port access VLAN 78", "is_correct": false}, {"id": "B", "text": "set interfaces et-1/1/3 vlan-id 10", "is_correct": false}, {"id": "C", "text": "set vlans VLAN10 interface et-1/1/3", "is_correct": false}, {"id": "D", "text": "set interfaces et-1/1/3 unit 0 family ethernet-switching vlan members 10", "is_correct": true}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '4382062e7e636f89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5584e05-83ea-494c-aa6e-6b268dd4006f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 57).', '[{"id": "A", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "64800 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '02ed2393d059f3af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a00c7a9-444f-47eb-a5c5-3a6d044b961e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 57).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '8efea9db0d50360e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0750355e-1795-4d4a-b821-0bac4a1ad544', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 57).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '0cdca49d120618f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90745b71-e18f-4974-adef-2caf448638d8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 57).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '3de47561f9b23265_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f0fa0ca-e7f4-4db4-96d0-a23740f1f59a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 57).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '0cdf7f5117e40dbd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf7d69c1-4095-44ca-8acd-f30a96cf417b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 57).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface xe-3/1/2", "is_correct": false}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "D", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '2d1eb597fc39c0a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f045fb47-6b9d-403f-bb03-2a7d56fdae9f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 57).', '[{"id": "A", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'eb2cc1773bd723ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87e4ac30-340a-4a93-b6a1-d775b8738597', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 57).', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '237fddbb3da39ceb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e35fb30-7b02-4cff-b1d0-1e025f52a725', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 57).', '[{"id": "A", "text": "6633", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "1234", "is_correct": false}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '1a8dbabdf140b31c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29912c67-c78a-46e7-83e9-fbba2c42bb36', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 57).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '63905ec0592aeb31_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8275945-2657-4a4f-98f8-1e043133418e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 57).', '[{"id": "A", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'f686dc5e5fbc2cfd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ebffcf4-e1f2-4f79-90f7-10b1edd1f2af', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 57).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '22e0f1cfdb65b0fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77406df5-313c-4684-922e-0153c607b0c6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 57).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "D", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '8456253ac6a256c8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba3be731-512f-4280-a0f3-fc9296d664f5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 57).', '[{"id": "A", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "B", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "C", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'c62d8d770e187bd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb0a4b89-acda-40d7-be8a-b194fb86d3a7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 57).', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '78b7243927b40729_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d814f5a3-59ad-4dde-b0f8-701f564f63c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 57).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "show route <destination> trace", "is_correct": false}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'b55d380d3e139f9d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7aa9766f-06e1-4a1d-8c78-981be657f0af', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 57).', '[{"id": "A", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '697eb4f914ee1a2c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b454ce92-6138-48ab-85db-4ad4d5b40765', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 57).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '6499f24bb650653d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d0991b5-9faf-45c9-b481-2b3f4fba0837', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 57).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'd169ecd3f58176d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('268243ea-6299-4104-9d7e-4867c1ad3a64', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 57).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.82.34.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '19b620b02d31692f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1a0f7b7-08f0-49dc-8a4b-d24302b33009', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 57).', '[{"id": "A", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "B", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "C", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '17936eb4c00a80e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc86e459-5076-4bbe-82a1-ce838d4eed7f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 57).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '71320a88194b55a5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca65c886-c652-45b7-8ade-c7954d001104', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 57).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '0846e07af3676a23_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a774a4a-f836-40e5-a1eb-afa0b2c12b3d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 57).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '8ab076bd7785912a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3080b555-dda0-463e-b1cf-01e9809b7e61', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 57).', '[{"id": "A", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '099e03553bbe4fd4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4eea9d9c-2975-4297-ab9b-e1a43b6ed949', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 57).', '[{"id": "A", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "B", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "C", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'd7aaa53330467c75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86bae05a-986a-4d4e-b465-da923730ba3f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 58).', '[{"id": "A", "text": "Backbone Router", "is_correct": false}, {"id": "B", "text": "ABR", "is_correct": false}, {"id": "C", "text": "Internal Router", "is_correct": false}, {"id": "D", "text": "ASBR", "is_correct": true}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'd00a45bd1f819260_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25c1c3f6-1e6d-44d6-8669-232d02c992f0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 58).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "10 seconds", "is_correct": true}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '1c1fc3e7ebc34128_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5038f304-7abc-4fc4-8808-dfb488dc653b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 58).', '[{"id": "A", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "D", "text": "Connects to external routing domains only", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '1b24c42f5add55fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd815801-78f4-4520-aed0-0f3fb7d57ab1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 58).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'b7d3294b93f694db_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1c1c7ad-28ed-4441-8316-10c902485eb7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 58).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show ospf interface", "is_correct": false}, {"id": "D", "text": "show ospf neighbor detail", "is_correct": true}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'c3adef5608e990e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('609cb640-f7e5-4b26-835e-40badb572bf3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 58).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '098821d004a64e27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12b38b3f-ddc3-442d-867c-dcb9877d3480', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 58).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '2bd9f18f82b722fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2aa4dbf-203a-48bf-ab74-37786c63a922', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 58).', '[{"id": "A", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "B", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'e660b93187097008_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13cd50d6-6b02-450d-b94b-7fb18e76c5af', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 58).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '5edcfb0473557e4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b3112e0-d6f9-4aa6-94cc-f8098926a8e4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 58).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '307b32bb6e54acb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f332eabd-5dfb-4d89-825a-a0658c10aaa5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 58).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '4fe9adcbd387f921_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c033da40-7470-490f-98aa-7f0cc7ecfe0b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 58).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'c347ee348da17cb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f72850f0-c545-4407-8ba8-d7d3fdc72bd6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 58).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'f131cc0e2284b2eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcd98393-2ae5-498f-adeb-faea7d939077', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 58).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "COMMUNITY", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "D", "text": "ORIGIN", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '441f33071e1ab57a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd6909cd-bd61-4989-a186-b1a63383c8fe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 58).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '41b80e49d50bad96_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67d1b264-9018-4953-be51-9cdd78fe5564', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 58).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '4b3fdc01f245e80d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85fc80e3-df05-427d-a2c2-b672ed14f07c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 58).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'b4febe9c1fe60195_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb5d571a-15b7-4c74-8710-2dcb677dd24d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 58).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '2b6aa1bb4a9a15a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0554918d-2351-4a05-8917-4d71a17ecac4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 58).', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '9e373889dd582118_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b117fe24-3074-4cd2-8760-4112499a8630', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 58).', '[{"id": "A", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '362cca5aee236a27_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff2fbdc9-e8d2-4a8b-8d0c-11fe5d425ee4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 58).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "D", "text": "The unicast route table is used by default for RPF check", "is_correct": true}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'b0b5609fdc946536_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9c98fe3-cbf9-4d7a-b661-91be67df8db3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 58).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'ea0c02432917a081_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e8100b7-2ed7-4de3-b094-abe38ae5fc4e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 58).', '[{"id": "A", "text": "Backup port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Designated port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '9c0c382425dacbbe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c9d882c-5650-406d-aa20-dfec54b05e45', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 58).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A physical link aggregation group", "is_correct": false}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '43232b288841cdb1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbb4ccc9-8fdc-414b-8484-0e108626c1b1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 58).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '8cf5752a94de7a37_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09a78a23-25ba-42cf-9084-74d26023a93a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 58).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "C", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '6ee02e28301e477d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d534c00d-66b4-4574-a25a-0f134ea7782d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 58).', '[{"id": "A", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65300 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'c6118a867dfa9cbe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b38c345-e89f-4776-be7a-6a6bbe2ff6b0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 58).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '6a14f38836c33f9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3893727-08e1-4e54-9729-9450683d4020', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 58).', '[{"id": "A", "text": "set switch-port access VLAN 14", "is_correct": false}, {"id": "B", "text": "set vlans VLAN10 interface ge-3/0/0", "is_correct": false}, {"id": "C", "text": "set interfaces ge-3/0/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set interfaces ge-3/0/0 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '352b7dedc146cf70_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97ea4b7b-d2e9-4e28-b615-630b7ad0efe6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 58).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "D", "text": "64800 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'b3e982b50e23f74d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07962727-ec3e-4889-83fb-f17b8c76a846', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 58).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '9e11b7a126a98ea5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e09d092-14f6-4c0a-a7fa-671c3e4cf6e2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 58).', '[{"id": "A", "text": "0 (000000)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '10c0bd4f888b7ae6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c218234-f6b5-454b-b819-d29a42f11604', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 58).', '[{"id": "A", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "B", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "C", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'a7b6a226f333ddcc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08c55c0f-4b4f-4ec2-91e9-b9b467f1c3e2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 58).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '71eb09ad34dbe0a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d6b9240-cd00-4087-9f8d-bbeb7fd465d9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 58).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface xe-0/0/2", "is_correct": false}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "D", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '2d541783b43c4896_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34d4ff19-1c49-4e49-b9f7-d208a77c07ad', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 58).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'affb673a942e2ae9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('976a659c-3715-4676-87a1-e7e6a7ae8d44', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 58).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '3e4b47038fb4f9ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9fdc237a-51c2-4265-9775-c163fee19598', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 58).', '[{"id": "A", "text": "8472", "is_correct": false}, {"id": "B", "text": "1234", "is_correct": false}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "4789", "is_correct": true}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '052bdaec8453d73a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea3228e7-7bfe-4fdb-a94a-93ef78e96e10', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 58).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "C", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "D", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '56a9eef723d96aef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c66d3ef-789c-43a7-aef9-58d0c36aea0b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 58).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '795de42c1d29c9cb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f0d5a12-1271-4e00-a1e6-744a977e331b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 58).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '4c8b36917af72a1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b794061b-2902-40e7-89d8-a4c6c234967d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 58).', '[{"id": "A", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "B", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "C", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'dfa81732e64cea0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cceccb84-4f06-4400-9802-9842bfcb5be0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 58).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '6102990a483c582f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f6765a3-6910-4345-ba17-57d8858b61f0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 58).', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'd7a6471639c80cf0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3df7b805-e035-4d5d-8e63-40e94e497a5b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 58).', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "traceroute <destination>", "is_correct": true}, {"id": "D", "text": "ping trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '8437da227df15731_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbeb72a9-a401-4f72-a403-dc321529dd2e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 58).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '9caa5a3bd819c107_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8dfd12e-643c-46fe-bac5-61c4c7da5a52', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 58).', '[{"id": "A", "text": "All of the above can be used", "is_correct": true}, {"id": "B", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '11c53f069472c982_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5581bdc1-d7bc-4cb5-b65e-316efd42109c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 58).', '[{"id": "A", "text": "Replace the interface cables", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '787ebef4d9c27e7a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2f68777-0363-4587-89e9-49f773525977', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 58).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.141.244.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '497777ed8cd11f41_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa237a59-6bdd-468a-af59-f28e82f52eb8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 58).', '[{"id": "A", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "B", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "C", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "D", "text": "Configures NAT translation rules", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '79412c4fe7bc4f29_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72fd3b64-6243-4257-a202-679bed1f3f6d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 58).', '[{"id": "A", "text": "reject", "is_correct": false}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "discard", "is_correct": true}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'ad9b5d1d248d5654_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34833ff0-2967-49b3-8971-a7ccd2736aa7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 58).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'f591f64c5f8c71f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab978132-305a-450b-881a-bb194250fe3b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 58).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'dda5a40c6e7a60bd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ce77fe7-e9af-4c51-b854-05d7f9062521', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 58).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'acb1edbb17500cb6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6f06842-f1ee-43f8-a9c2-5b2b452524fc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 58).', '[{"id": "A", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "B", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "C", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "D", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'bc439ae134cffe7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f56e9285-97e0-4a2c-a06f-bd695dc634f8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 59).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "Backbone Router", "is_correct": false}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '857f8ed918fe940f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4fe06c3-1a9f-4a9b-bc77-77c45b4fe404', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 59).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "30 seconds", "is_correct": false}, {"id": "D", "text": "40 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'd5b886d3ee96d821_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('270f3570-0866-4d55-855b-43021ec224d4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 59).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '6efb4a00603cf73b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d11aa811-6b95-4a55-b594-f90554bcddeb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 59).', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '39a7bee2585e358c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60c42223-fca0-42f1-80e0-eab912784471', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 59).', '[{"id": "A", "text": "show ospf adjacency", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '7d9e6d16c2f43f5a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4a6aff1-c990-4b13-a3b2-f1f5ae0dbf59', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 59).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '1b96789875442088_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e15422f-79b5-483e-8fbb-96cb41ce2918', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 59).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "C", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "D", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '821b4febd23fe897_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('772fdf6e-831b-4c32-8be5-fde336e75749', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 59).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "Both narrow and wide are supported by default", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '4f483dd1ab32bcd4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f35e4043-0b08-4af2-98f4-bf8a998fc912', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 59).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "C", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '9ec122ec36b331b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c90882f7-0876-4f3b-abb3-43e5c5e8ec8c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 59).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '442d99490e52e2f1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9570dde8-ae1e-4d8c-b7e8-9c1a8bf1d7e9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 59).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'a136cefde2098daf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13fbef5f-8b17-4aa6-a9ee-576be0f4124e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 59).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Configures the local preference value", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '055ce8149565d52e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b69d9991-f188-4e4f-96c1-9e43bb527be7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 59).', '[{"id": "A", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'f09de30ceac126e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69949509-5f88-4bb7-92c4-28fd8398a174', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 59).', '[{"id": "A", "text": "COMMUNITY", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "ORIGIN", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '306f0d469a20a1ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9cb71c0-e32a-4236-a898-23a23d8386c4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 59).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '5aa7f1d094642a5c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('073fe880-e880-4828-be97-c530da63ae1b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 59).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "D", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'fb38f90c83ab68e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a1eb4c4-9df3-4c5b-9d02-fc0940df2d3c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 59).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'cae63e62fb2cf1eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a69e9f9a-ea63-4f52-bcf1-db35c439ad1b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 59).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '7e08ba4eea4b12d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12201fe0-6b8e-4438-a129-3968932544c9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 59).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '683e32a59b08a0a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a935d1c4-7d7f-4007-8561-5a17d2ec1e1e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 59).', '[{"id": "A", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '1f5c3ecd4af1ae74_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0166cbf1-908c-4e49-ac2d-fe759eb285b2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 59).', '[{"id": "A", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'a655ace51fea20c0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6397dcd9-7f17-40df-a345-338d90092d21', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 59).', '[{"id": "A", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '76da0fe702df6578_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ba181c4-39e4-4d8e-9808-98c2666e90a8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 59).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '7960345f2d3c85d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a93c800-29b0-4fed-a889-e9e3119c1ad1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 59).', '[{"id": "A", "text": "A physical link aggregation group", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'eb606b77a7bf0235_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('127687c7-1e25-489b-a1f9-1be9a53c8bdf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 59).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '63227a1c6e2d905f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e79a0e0-c466-4f84-af8f-d056ea67c49e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 59).', '[{"id": "A", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'f699c62d39b957f5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('168c991b-f473-4034-90b3-0a4d725d410f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 59).', '[{"id": "A", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-64700 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'cb622188b964f748_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4740c318-abd7-47e1-a173-92558521e23c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 59).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'da9bd46fbc552d8d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('765e1d7a-3daf-42ca-a2d6-94d0092af37f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 59).', '[{"id": "A", "text": "set switch-port access VLAN 258", "is_correct": false}, {"id": "B", "text": "set vlans VLAN10 interface ge-2/1/1", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/1/1 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set interfaces ge-2/1/1 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'd7082a3b41c7760b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b90e83a5-be39-4c72-ac4a-e035591b5ad3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 59).', '[{"id": "A", "text": "65001 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'b9403af00e442898_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad2bbcc8-0119-4684-84c6-96c015dfd5c1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 59).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "C", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, 'e97e829744fed053_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e36678c7-5280-460a-a520-1762d2a1434d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 59).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "26 (011010)", "is_correct": false}, {"id": "C", "text": "0 (000000)", "is_correct": false}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '9dbfc83cd145e1b7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2ea450f-ea72-449d-bd51-93ad03a4960c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 59).', '[{"id": "A", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "B", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'ca4b1109d3f5b1c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16c5e960-8cbc-4437-b50c-c4b1b35015f5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 59).', '[{"id": "A", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '0fa058ed72a9d4b2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08f652bd-4a43-493d-9a60-de904c03d189', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 59).', '[{"id": "A", "text": "set cos rewrite dscp 46 interface ge-2/1/0", "is_correct": false}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "D", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '391d4cb1aeb14320_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1aa6b731-8813-4783-9cfb-eae938b91f07', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 59).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '3244e2cff49b2e04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('853f3e5d-2200-4330-a080-db366fede494', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 59).', '[{"id": "A", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'b55905ee6bb0b623_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f22c2c05-891a-4cf3-95b7-cd00c2f8bd3b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 59).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "8472", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'f8855c4207ea8163_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef6d7e42-40c1-4b38-ad7b-ef60c1422e3e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 59).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '4a2d70b8c17fe0f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b894f01e-b3f8-4bec-9606-95383a725ba1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 59).', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '8ac2bf44bf25d082_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad73b570-a8df-4a5b-a7e3-62aaff15a848', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 59).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '81bc9043ce05156b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e478826-12c6-4caf-b7d8-f7da02c0b3ae', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 59).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, 'f29dbd6104e0bec7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d49415fb-b409-4ede-9567-502093f73aa1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 59).', '[{"id": "A", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "B", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '4122148dd84f8365_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('319c4a49-03bd-4745-b3e5-13aa08cf09d1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 59).', '[{"id": "A", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "B", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "C", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '6080d6a61ae1579d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccd5f913-fb31-483c-a295-c0dc0d3e5f04', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 59).', '[{"id": "A", "text": "ping trace <destination>", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "show route <destination> trace", "is_correct": false}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '3ec23924dad8a6dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b1498e1-d98f-4272-a7d0-b8fba7c17864', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 59).', '[{"id": "A", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '416e15b2eaa17d66_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4fcb5076-b7e4-4160-bbb9-9671c26bd882', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 59).', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "show route table inet.0 <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'ad8ac78cbfda0b97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57caa1e8-0bf0-40fe-b0ca-5c9338baab02', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 59).', '[{"id": "A", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "B", "text": "Replace the interface cables", "is_correct": false}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '0e4b38304e8300a3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d4ba1e8-0c6d-4e98-929b-88aa7c0e562d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 59).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "D", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.86.186.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'ef7e378811a056fd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b48fa4ee-b818-45e3-ad1b-90c75b1b72c0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 59).', '[{"id": "A", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "B", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '7d0bb477e8c322c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf103b25-97a2-490a-a39e-48ea3f08494a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 59).', '[{"id": "A", "text": "silent-drop", "is_correct": false}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "deny", "is_correct": false}, {"id": "D", "text": "discard", "is_correct": true}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '572635dd97189f69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a68a77c-53c2-4a92-b4bf-5e2af745e657', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 59).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '7eae59a5b3150da3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e3137f4-e0f8-4509-90df-cc4698c942a1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 59).', '[{"id": "A", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "D", "text": "Single switch acting as both core and distribution", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'cd8d4d11becdbdfb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6eb515aa-3d0a-4957-92f9-921ad58fb6cb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 59).', '[{"id": "A", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'ab508db62019b08a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c885243-3cc9-4a30-9e56-3642596ec04b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 59).', '[{"id": "A", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '1e2ed1c2e6ad6a3a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ab03f73-c774-4017-b1c9-07a6ea5b008c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 60).', '[{"id": "A", "text": "ASBR", "is_correct": true}, {"id": "B", "text": "Backbone Router", "is_correct": false}, {"id": "C", "text": "ABR", "is_correct": false}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'f2f7331e96b888ad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07bc6ec1-89d3-4a12-82ed-a3ffe26653df', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 60).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '061544539a9d82ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b2c12fc-d04e-47f8-9afe-69852d828fcc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 60).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '210b5a20f7c0679b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b40ce69e-fd72-4c43-96c4-bc06e53e6fbd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 60).', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '3913ec3c7e36e941_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c19f065c-8b30-4d6b-bdd7-2433a5c94d4e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 60).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show ospf interface", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '7f779907bffe3a75_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a867aaa1-8542-41ce-8b8f-65cd8aff7ae5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 60).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '61b133cfe2acce85_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00b0947c-d0f8-491e-8b34-838b9b9efc70', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 60).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '769a53b0a1df168c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9be04524-fab4-478b-83df-d67208930855', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 60).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "C", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '68e862d4fdd3336a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd5571b9-be5e-402c-b406-8a95a184cfb0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 60).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '69670ee4e853c928_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22f702e6-677c-4eeb-96f8-502ce2c89936', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 60).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": true}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '8e69326441822efb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f0f0160-53d0-4116-87f2-67aed17a7ec1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 60).', '[{"id": "A", "text": "64", "is_correct": false}, {"id": "B", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "1 (directly connected required by default)", "is_correct": true}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '5bc5c0f1dcb4eb79_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8ccd968-6f89-4431-9274-bd27c197144d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 60).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'f264114c13610f97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d75871b0-96e9-48b0-87b8-23852bcb54e2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 60).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'bc089d9434c8d75d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65340206-6804-49dc-9554-c4da20f0d9a0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 60).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'cf0063da48f2b880_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3d99f53-81a5-4d75-b63a-867dfa635fe3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 60).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The IP address of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '0b7ba0f62089c215_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb508708-aa82-417c-b92a-0d0bac04a0d7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 60).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'f03cafd7f56a188f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e12126e-7a3d-4b72-b782-d92ca5046de2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 60).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show bgp neighbors", "is_correct": false}, {"id": "D", "text": "show bgp summary", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'b344c050a40e0ab4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acc9b117-ee4d-4402-8d60-02dc138e5d15', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 60).', '[{"id": "A", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "B", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '61761c5b30dcb576_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c26ba7bc-8aa9-482f-8bdf-ecf5d411a845', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 60).', '[{"id": "A", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '37b5e2202ad993e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('496a2e49-8d90-48b8-91aa-e939b8608f12', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 60).', '[{"id": "A", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "B", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '319f707590e9ddeb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('233f50ed-ffa8-4afb-bb9a-0a6eb7e98457', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 60).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'b086d7ff97af4a97_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69c4de31-a397-484e-8cb8-e094d885d75a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 60).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '1b04f64e12e77e06_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79796b6f-4ed1-4931-a1e3-62213456f603', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 60).', '[{"id": "A", "text": "Alternate port", "is_correct": true}, {"id": "B", "text": "Designated port", "is_correct": false}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '19edbd768bc202d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83b6c364-a03a-440c-8844-318893877e92', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 60).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '8297dd2b4e9d58fc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97f0cfc8-1fa3-4d19-b62d-a63418729af5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 60).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '5e96a021c7b2e780_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a0d2a4b-fb52-4a6b-9ae3-8594a309f3ee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 60).', '[{"id": "A", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "B", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'a4e5c8d1d561f964_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('016f83e3-dd67-445e-9f4c-52d596e4b77c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 60).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65400 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'd73ed457cbb91937_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f4b192e-7188-486b-9b78-0fd241bfcbd0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 60).', '[{"id": "A", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "C", "text": "Connects to the management network", "is_correct": false}, {"id": "D", "text": "Provides PoE power negotiation for access ports", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '5b3e4c3f9d2cb5d8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae0b7ae9-13d5-4fea-b5a1-855b0d527445', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 60).', '[{"id": "A", "text": "set interfaces et-3/1/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set switch-port access VLAN 167", "is_correct": false}, {"id": "C", "text": "set interfaces et-3/1/0 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface et-3/1/0", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '01b75794b51d5db3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8df976d-7d38-4052-9e32-8461aef74c08', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 60).', '[{"id": "A", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "65002 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'd18f051c56b7870e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bebecc49-326a-4ef9-bd09-397b961e7649', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 60).', '[{"id": "A", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '690c384ddfb22b13_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5681af3b-24ed-48fc-8d8a-dcb09160cf1f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 60).', '[{"id": "A", "text": "56 (111000)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "0 (000000)", "is_correct": false}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'f662f8bd19e9db09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26d30608-e92c-47c0-93e2-4c196626e1aa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 60).', '[{"id": "A", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "D", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '80e29a0fbe69824f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2635cee8-b298-426c-a310-95f2d779418d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 60).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "D", "text": "Determines which packets are forwarded first", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'ffdf70bc2eca532e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3688e551-e7d9-454e-ae8f-69b2417547ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 60).', '[{"id": "A", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "B", "text": "set cos rewrite dscp 46 interface ge-2/0/3", "is_correct": false}, {"id": "C", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "D", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'cd8bfba741db06e4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7a9742c-d41d-4152-bf84-926468a4ba03', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 60).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '95b8316674094848_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80d3630b-bd94-45df-84ed-d8e0f0f4c220', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 60).', '[{"id": "A", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "B", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "C", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '1417a30f3edac13f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88fac110-7aec-4798-b8ea-15e66c1c5bcf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 60).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'a850a1147110c21a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56a24fb0-64ee-43e6-a890-44de57c34439', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 60).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "C", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'ff622ef4de2d1adb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b57910c-e17c-4eba-bddf-2df1ffac43e6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 60).', '[{"id": "A", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '59cb02311378e760_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd9ac22e-be71-43e3-9f97-fe1ac3343bf1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 60).', '[{"id": "A", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '490e5a208687a68b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b263695d-d49c-4684-8a2e-42a0d3a81868', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 60).', '[{"id": "A", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "B", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "C", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '5fe1b385e4ba5564_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ba8eb7a-8ad2-4855-862f-a49180ae66f6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 60).', '[{"id": "A", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '0eb9b87ff4c66724_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('807497b0-a410-462c-8917-d64eee0aabec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 60).', '[{"id": "A", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "B", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'c0dccdff5a4ed708_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac54b3ba-fae3-4fb9-82ac-a336a879e7e4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 60).', '[{"id": "A", "text": "show route <destination> trace", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'ec80de41fe9e3084_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c61f78fa-85c0-4cd9-a601-2d3ecbbd71fd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 60).', '[{"id": "A", "text": "The OSPF link-state database", "is_correct": false}, {"id": "B", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The BGP route table with all attributes", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '41a4167787ee5a34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40c779c8-630c-499e-8361-6816f4b2fdb9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 60).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "show route <prefix>", "is_correct": false}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "All of the above can be used", "is_correct": true}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'c96cf5edb9ae3913_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44957a99-8b0f-43d3-aed8-a093a7fbd287', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 60).', '[{"id": "A", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "B", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "C", "text": "Replace the interface cables", "is_correct": false}, {"id": "D", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '425d017cb6f3a3cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('085d43b3-5300-4b49-9448-09ff406ae501', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 60).', '[{"id": "A", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "B", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.227.247.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '2e02bdfd40599159_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('714d320d-d049-4365-8c2f-107bb50c2234', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 60).', '[{"id": "A", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "B", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "C", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "D", "text": "Defines firewall rules for packet filtering", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'f67d8dc22af01981_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a670f69-2fed-4c74-ad79-01d20b12a6f5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 60).', '[{"id": "A", "text": "silent-drop", "is_correct": false}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": true}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'ac6457e6c291f3a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61f860cc-4c02-4644-a8e5-f3de9559d5c1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 60).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '7bf8248a7b12d61e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc34b3f7-36d1-4b9f-84c1-73b4eb9deea7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 60).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '7bb71f406a3232ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd99b31c-838f-47ca-a050-f894fe0d3dba', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 60).', '[{"id": "A", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "B", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "C", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "D", "text": "No BGP configuration is needed in the fabric", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '6dd9036a3386fb9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a006af50-f1bf-49c7-b0cf-dc098a21642b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 60).', '[{"id": "A", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "BGP on loopback interfaces between the switches", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'f954b87c508dad79_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f408a71-9c22-45da-9029-3b32f2210a54', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 61).', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '0f2110ff8af9580f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2cf26f3-1b16-48ad-8d90-9553413e7be6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 61).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "120 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '0cf7c11bba179862_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a9a835b-d2cf-48f7-a7c5-cb58d4699c57', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 61).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '263ee6aa2c867fda_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9b9b3bc-5428-4dba-bbcf-ee7f3d5fe45e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 61).', '[{"id": "A", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "D", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '11770b34e265b3d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('400a6af7-fe6c-4ce8-9a6f-db5450dd73d0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 61).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '8ee18021366a891f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e79a0cfc-4eff-4952-9055-4a0c7f9fdeca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 61).', '[{"id": "A", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '91fda7346e017723_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('319a1ca0-d104-4a62-a734-2f1b17d5b795', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 61).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '58d327153d7aacac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ab81ec8-39d1-40c5-a352-a1116139cf92', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 61).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "D", "text": "IS-IS uses hop count as its metric", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '9ce487b5cb9ded10_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa656102-d51c-4e38-81d8-be950fd966e6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 61).', '[{"id": "A", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "B", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '5c58bd4c1e3f5978_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34996e50-d1fb-4517-8a40-963a86b2a50a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 61).', '[{"id": "A", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '65c491b146691b89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5999b9a4-2016-4140-9d7d-ea130f3f3c9b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 61).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "C", "text": "255", "is_correct": false}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '6393e6f1fe2a6997_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a32b40ab-e58f-4c34-9206-47bc9e62df6f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 61).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Sets the BGP router ID", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'ff72ed857b273566_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9102fc4d-c81d-4b69-846c-cdf828a227f7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 61).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '3866b836e05eae20_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6940e53b-b85f-4d74-a2cd-8a7afb9aa49e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 61).', '[{"id": "A", "text": "COMMUNITY", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "D", "text": "ORIGIN", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '7de7a878067c4b0a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d320bab-fadf-4c3c-862c-04afc0d5be13', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 61).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The AS of the route reflector", "is_correct": false}, {"id": "D", "text": "The IP address of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'ce49d015d6ccb72c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34c94d47-207f-4b5e-b9cb-a29909934f93', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 61).', '[{"id": "A", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "B", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "C", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "D", "text": "Permanently deactivates BGP advertisement", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'bee0d1c2e406ac6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27b31d89-512c-4452-afe3-0101480d8edf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 61).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "C", "text": "show bgp neighbors", "is_correct": false}, {"id": "D", "text": "show route advertising-protocol bgp", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'ccd71c5d7ec27f15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a33dba2-fe9e-41d4-be3f-4b5d4b9acfa1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 61).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "C", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "D", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '5c7de727e10af35d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcc2bddd-e0b0-41c6-8a3a-e6b8622c6348', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 61).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "D", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '190a00127f68cedc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd64f13b-f888-4e55-82a8-0c17436ebdcc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 61).', '[{"id": "A", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "D", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'eba57573360c72e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9b0e75a-2b33-4372-85d5-85585a60caf0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 61).', '[{"id": "A", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "D", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '4438fcf3b6afd37c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f630af1e-839e-4779-b782-cbe357a1611d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 61).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Assigns MAC addresses to switch ports", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '8551ef606d014fa3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c00887af-ce30-4c1c-bd96-19412bd0997f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 61).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Backup port", "is_correct": false}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Alternate port", "is_correct": true}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'd87da0b0527375de_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca75cdbc-386c-43a0-82ae-46194cb334dc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 61).', '[{"id": "A", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "B", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A physical link aggregation group", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '563ab1b674105c61_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66410462-dce0-4dc7-9724-246fa97a3fa1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 61).', '[{"id": "A", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "B", "text": "show bridge stp", "is_correct": false}, {"id": "C", "text": "show spanning-tree interface", "is_correct": true}, {"id": "D", "text": "show stp status", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '578ee85040e5bb81_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('796c0767-27be-4248-b5e0-af99591cc6be', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 61).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "C", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "D", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '91de448aab659969_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9048f7af-2cbc-4146-be26-c9b61327efbb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 61).', '[{"id": "A", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65000 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '0e0614bc09bc5ef3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a77eda3d-cd79-499c-ab4f-31976b6d1760', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 61).', '[{"id": "A", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Provides PoE power negotiation for access ports", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '2fdff3436dab67b9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f1cd1d9-1b65-4e16-a45f-ff2eb6b0d647', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 61).', '[{"id": "A", "text": "set interfaces ge-2/0/3 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "B", "text": "set switch-port access VLAN 447", "is_correct": false}, {"id": "C", "text": "set interfaces ge-2/0/3 vlan-id 10", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface ge-2/0/3", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'a657158ab6f090e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ab939f9-bf53-4e09-9a3b-83af18ae2f4e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 61).', '[{"id": "A", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "C", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "64514 (16-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'ca9f9ab437ffc478_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f835435-4d33-47c6-b0c5-297340657706', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 61).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '2f9ce39bd52544c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('275aa9ea-b00e-4961-8f97-3bbc5618cebe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 61).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "26 (011010)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '8852b20dee7955a2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84cd6b1d-a1ff-47f1-8e04-7b94b5d0ce40', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 61).', '[{"id": "A", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "B", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '905206fc02f39099_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f3ce27dc-2f96-49ac-8bc6-f71a007901c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 61).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, 'acb199e39d4ea090_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19f0da0e-6f65-47c9-a005-023ac36b1a14', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 61).', '[{"id": "A", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "B", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "C", "text": "set cos rewrite dscp 46 interface et-0/1/2", "is_correct": false}, {"id": "D", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'be1081d56685e4e0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d316bd6e-1ce3-4c67-95d7-af20901147ae', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 61).', '[{"id": "A", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "B", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "C", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '442e246c529ced7e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42f620a5-dce4-4895-b8e6-71bb8ee0f4b6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 61).', '[{"id": "A", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'cbb41e6fca9b33cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cb18197-e3ef-4a29-b130-6e69f75c56f1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 61).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "4789", "is_correct": true}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '988e47dc45cb6513_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf19ef03-7171-4baf-a73b-9f8deac2537e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 61).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '9201f84f8ebbc4d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2c74add-c9ac-4cff-869d-5ec6a65e3a9d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 61).', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '021c0cd1a4042210_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17c5c572-a07b-4cbd-965c-20a1b550288a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 61).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'c75137aa0da3c02b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cb35774-e3a1-4d34-86b5-dd4776b43f2b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 61).', '[{"id": "A", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "B", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "C", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '6a115735b57ac9d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c82d673-4c60-4d4f-98ec-c767ff56cf73', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 61).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'f02f4b7cd221b353_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1b11513-11b8-4ef4-af43-6e0fe6df60b5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 61).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'a3f55ae8ede1968b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5980b48e-ea9b-4353-898e-21e56ef46fa3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 61).', '[{"id": "A", "text": "show route <destination> trace", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '7a113396798101c2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e13e2940-3fe5-441c-92c2-49d467a41171', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 61).', '[{"id": "A", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "B", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "C", "text": "The OSPF link-state database", "is_correct": false}, {"id": "D", "text": "The multicast forwarding cache", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '022bd65bc9fbf899_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40cec851-59ca-4b90-ad97-7bd1433e219a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 61).', '[{"id": "A", "text": "All of the above can be used", "is_correct": true}, {"id": "B", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "show route table inet.0 <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, '6ab02487416d07dd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cbc17607-cf39-4b25-99a8-bf0025129ce8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 61).', '[{"id": "A", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, '97f586d167110c03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de6491c9-5e09-4916-a16e-7f88cf6c63f0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 61).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.19.30.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '51b7734aaf641443_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69bc4537-dd30-4c0f-bc76-8300a210ea7c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 61).', '[{"id": "A", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'a5c94f8a643c83b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc11779e-fd90-4bf0-b7b4-e2fbc3741a90', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 61).', '[{"id": "A", "text": "silent-drop", "is_correct": false}, {"id": "B", "text": "reject", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": true}, {"id": "D", "text": "deny", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '644b9114d55105b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbff1261-1bf2-4f97-acfb-7f9b0182ce0b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 61).', '[{"id": "A", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "B", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '86bac170a87fe9f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad61d4d1-e8b7-46c2-997a-54866d2210e2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 61).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "C", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '18c54905052ca402_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05fcd77e-01a5-4c88-acc6-57f2f8202754', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 61).', '[{"id": "A", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "B", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "C", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "D", "text": "No BGP configuration is needed in the fabric", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '8819c84d41a8ac21_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8937954-dbed-4799-bd58-97c9a98b651f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 61).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '1394a3400fa2b12f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('490c6727-1ec3-46d3-8827-8816d378ff05', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 62).', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "Internal Router", "is_correct": false}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '6b79c48d07d5ea47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('141dec2b-9e49-47e1-8ad0-1a8bdffecea5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 62).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "120 seconds", "is_correct": false}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '3781ba7405d2baa1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b98e3b30-655b-481e-b92c-5ce72c51cdea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 62).', '[{"id": "A", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "B", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, 'acc23c0f8c99fa18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0edae03-5ce2-4ecb-ba35-6d0dbdf0d5f7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 62).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'c2d3a72273cab3a7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ae9c46e-1a24-4f18-906e-7e462e4338dd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 62).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'e8bf80eea93e1d98_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e62ed6dd-4c6b-4050-8151-96b19fc368ee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 62).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'ad580c26d71b50dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a91c25ea-5b66-47c0-ab8c-ec8ca210a66d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 62).', '[{"id": "A", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "D", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '7f1ca718214b121a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edb3cf01-e6ea-41fe-9f8c-ece3acdd06d0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 62).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '5a46dedc20ee74bf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d3b466c-b85b-4bed-92ba-d708d6a603b2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 62).', '[{"id": "A", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '35d008ba88fdaea2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca787c21-b1ba-4753-a495-b6917119b502', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 62).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'a7ae9764d4b36c80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3635846f-3b8a-43c6-97e8-1173994a3c7c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 62).', '[{"id": "A", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '8d95e705a6715726_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad03124a-2f69-4f86-9820-ccf04c479d5c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 62).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Configures the local preference value", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'b4f8fa48adcebb6d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9587877-59d5-45cb-b97c-e379f78d8060', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 62).', '[{"id": "A", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "B", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'dff005e99d7382b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b43f897c-aa8a-4a22-ba1d-27f2410bb8fb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 62).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'd926616980ae4b0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49d55f6c-8dcd-470d-b825-57e9b7eacad8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 62).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '5f97178263b810f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d594309-ed68-4907-9e68-cb8baa36c9bb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 62).', '[{"id": "A", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Forces BGP to advertise only active routes", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'a5fc8d96f05e5a4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c750a762-8624-4cd0-a4d4-96ac66ea2211', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 62).', '[{"id": "A", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "B", "text": "show bgp neighbors", "is_correct": false}, {"id": "C", "text": "show bgp summary", "is_correct": false}, {"id": "D", "text": "show route advertising-protocol bgp", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '04db859227ce464c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e1095db-f087-4d4c-9c31-499a3e682257', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 62).', '[{"id": "A", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "B", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'daf5fa525af80e4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73e97adb-372a-4536-86f9-51bd58e14a94', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 62).', '[{"id": "A", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '6f9ac891881fdd63_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('129ed3e6-5e17-4a0d-9f76-0a56ada91eb1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 62).', '[{"id": "A", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "B", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "C", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'ba7c5bfa19f68b7d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2577d327-53d5-4874-b341-f64bf7bacc44', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 62).', '[{"id": "A", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "B", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "RPF is not used in PIM-SM", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'c2082122944adf5f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6dfee2b-5c5c-4013-9990-9ccfab125063', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 62).', '[{"id": "A", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "B", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "C", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '4c327bd174490805_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7b97e71-6438-4aed-acd4-582513adcf2b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 62).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Backup port", "is_correct": false}, {"id": "D", "text": "Alternate port", "is_correct": true}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'a85041ef13744bfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('263eecd1-8a0a-4d7b-85c2-f6062ccc2e79', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 62).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '163cdd19c418fecc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fdde79f-fef4-4efb-bfdc-2bedd4945a58', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 62).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show spanning-tree interface", "is_correct": true}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '7f45210c072af339_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31a8532a-dcbe-4bed-bd3a-52d936d86448', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 62).', '[{"id": "A", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '2f80d34a106caf15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a984338e-331c-4e1b-8967-5902e0866d86', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 62).', '[{"id": "A", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "B", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65001 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '5b4a8cbdf947c944_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec4b33f7-ac71-4e84-b08f-0efd0a099660', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 62).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "C", "text": "Provides PoE power negotiation for access ports", "is_correct": false}, {"id": "D", "text": "Trunks multiple VLANs between switches", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '713249a5810b8f40_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c91ec40-fb8b-4857-88cf-1daf8ecf681c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 62).', '[{"id": "A", "text": "set interfaces et-3/1/0 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set vlans VLAN10 interface et-3/1/0", "is_correct": false}, {"id": "C", "text": "set switch-port access VLAN 266", "is_correct": false}, {"id": "D", "text": "set interfaces et-3/1/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '8b7893dba4d7e1ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc2b90a2-82ee-47d1-afd4-bd946a7a94aa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 62).', '[{"id": "A", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "64700 (16-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, '7586c502118b70da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f0fd16c-b93a-471a-b9c0-55c4b52bc125', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 62).', '[{"id": "A", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "B", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '142f7e3ce3d40876_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05cbe03b-34f7-4e58-952e-357c7a3c6d2a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 62).', '[{"id": "A", "text": "46 (101110)", "is_correct": true}, {"id": "B", "text": "26 (011010)", "is_correct": false}, {"id": "C", "text": "56 (111000)", "is_correct": false}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '17ac76f88ff21b1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae64128c-d276-41d1-ab26-32f8656b710a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 62).', '[{"id": "A", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "B", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '758f564490875075_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2f8dce0-1b93-4f8f-9fc6-5c2442a08e86', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 62).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "C", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '68e0415b83a3ce69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82eb2194-9a3b-4019-9cc2-306e1973d6d5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 62).', '[{"id": "A", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "B", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "C", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "D", "text": "set cos rewrite dscp 46 interface ge-2/0/0", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '2dd317aa6d82db2e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5307c1a4-d67c-4675-bd00-07f0c3cce53a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 62).', '[{"id": "A", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '39c51a8a091350c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7529f814-3685-4438-b39a-45116bbee1cc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 62).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "D", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '96efb653a2f06290_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75554897-037f-41e7-93f5-5db76de8a4e8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 62).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "8472", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '9c832658e0ac2c4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4f02de6-eed6-4e11-8bf5-d488114748d8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 62).', '[{"id": "A", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "D", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '9b0749713e6bbe1a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad908a87-239d-4a3b-ab3b-a09e077a1759', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 62).', '[{"id": "A", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "B", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "C", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "D", "text": "The EVPN route reflector configuration", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '119936660bf63a25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a490cf5e-e4a3-4d26-a752-7df14c68a7bc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 62).', '[{"id": "A", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "D", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, 'cf9673088bdc4687_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2fa30a3-aefe-4b99-989d-dc96f06f38cb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 62).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "C", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "D", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '13fe68422849e973_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7518bca1-bfaa-4ecf-ab0c-f18b456bf9a2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 62).', '[{"id": "A", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '90477f1cd4384e4e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5339878-25f6-4b53-afbf-9e63eb57822c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 62).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'bde4432173f8999d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a137d57-2a2c-4df3-8311-0d9cbe773702', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 62).', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "traceroute <destination>", "is_correct": true}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'abe2020ae884663b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30c6d1d2-bf3a-48fa-96be-e12b1d3d5211', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 62).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, 'ca92f09e423fd42b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ceae26c6-ceb4-48c9-85ca-860c9be62385', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 62).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "C", "text": "All of the above can be used", "is_correct": true}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'ff4ef2d58f22c753_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8320b0c6-760f-427d-9c45-938a672b8439', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 62).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "C", "text": "Replace the interface cables", "is_correct": false}, {"id": "D", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'a057147897a7dbea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9da1c395-cf76-4c87-ae61-c2ffd18695ab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 62).', '[{"id": "A", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.223.167.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'fe1731af05675707_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43040a17-7dba-4fe9-9162-e7a12b769d77', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 62).', '[{"id": "A", "text": "Defines user netadmin permissions to the device", "is_correct": false}, {"id": "B", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "C", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '4a2159b47b67a314_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c99467e-e02c-4fcd-a196-8bc25e31ea23', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 62).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "silent-drop", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": true}, {"id": "D", "text": "reject", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '71cd533e8cae3b25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64ac6532-cade-44a8-9cf5-94f3d439add7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 62).', '[{"id": "A", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "B", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches all routes except those in the prefix-list", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '2a8bca5e45cccaf0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8f954de-f743-4e56-b8d5-20c20f5bc2b0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 62).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '9abc0b4d529fa817_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b454b2c2-caeb-4969-aed5-1e921765aa9f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 62).', '[{"id": "A", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "B", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "C", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "D", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '1a1fccb703f2aa58_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('321019f5-fc89-46d1-a940-9f9fc46b93e4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 62).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '13201a11124ce5fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6932e88a-bf83-431b-b0c9-24613de27964', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 63).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "ABR", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "Backbone Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '9b7c6d34ca11998c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f13a6a2-7669-46be-a05d-e4cc0d69ad91', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 63).', '[{"id": "A", "text": "40 seconds", "is_correct": false}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "10 seconds", "is_correct": true}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'f00d06cbf899e1b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5994804d-3115-45f4-b4db-445fd6faf2ea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 63).', '[{"id": "A", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "B", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Connects to external routing domains only", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '0f724efb130c2169_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('660c6882-37bf-457a-983c-54818c14d9f2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 63).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Advertises external IPv6 routes", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'd8c91617240a58d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bab3300c-3a03-4166-8a0c-3e1a7e0dfb1c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 63).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show ospf neighbor detail", "is_correct": true}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'd79735df5ce2e845_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2409d84e-1783-44bf-a7da-fcee2b4166e5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 63).', '[{"id": "A", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, 'd637d023cd73f08e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7af9c348-79fd-49ce-83de-536709d7cd37', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 63).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "C", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "D", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'e5b31e41989684d6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfffa8eb-5eed-4690-b55c-5c0fd73ee544', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 63).', '[{"id": "A", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '3d00cd57f5bd429f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('593fa9f2-017e-4824-b737-426a38e91a5d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 63).', '[{"id": "A", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "B", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "C", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "D", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, 'd636126769c8d1c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('024b5311-ac3b-4789-be48-90b675157877', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 63).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "AS_PATH", "is_correct": false}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '13cc2623f5dcaaad_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1be5cb5-fcb5-49f1-bf69-357dcc8a5e7c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 63).', '[{"id": "A", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '7b07a61916d8e1e7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad468c9d-5d89-4c08-816a-0bdd0eacd52f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 63).', '[{"id": "A", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Configures the local preference value", "is_correct": false}, {"id": "D", "text": "Sets the BGP router ID", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '877ce6659cb0ed09_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b53d7b2f-f862-4a57-8d06-4a8164fc3749', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 63).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "C", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '262d181bfb696e69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24d761cd-7f71-4080-a072-a42727f2dbbf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 63).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "ORIGIN", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '1d7045f2bc23c570_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d625adf6-44fa-4b6f-ae62-5088b4321c1a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 63).', '[{"id": "A", "text": "The group of route reflector clients", "is_correct": false}, {"id": "B", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "C", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, 'c4eac8e250a070f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4948e06f-8367-41ab-be9c-f9b6bd484eb9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 63).', '[{"id": "A", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "D", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'fb586a4892452868_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6af6b44d-7127-4773-90c9-eee3b2f2f97e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 63).', '[{"id": "A", "text": "show bgp neighbors", "is_correct": false}, {"id": "B", "text": "show bgp summary", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show route advertising-protocol bgp", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '49cdd40b187cfb6b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66a0fe60-a5f4-4b03-ba23-47a61fc5591b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 63).', '[{"id": "A", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "D", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '20de97f2e04d4063_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9a28393-2e95-4876-9b3a-2f0296207659', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 63).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '8de7eece51405f5d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1f044bc-ba72-468f-956b-465084fde20d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 63).', '[{"id": "A", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "B", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "C", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "D", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, 'a967d6ae1b526456_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24147b2e-7a78-4891-b14f-6d0aab3d336e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 63).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'e0b1ea2b8da2a585_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3444f16-68cb-42a7-9b60-0761ec466345', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 63).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '316a630c22d0286e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b7b7f53-8476-4e80-88bb-eadc1b984eb8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 63).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Alternate port", "is_correct": true}, {"id": "C", "text": "Edge port", "is_correct": false}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'ffd277f4e2a76539_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e754920-5027-45e9-b790-3549c269d491', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 63).', '[{"id": "A", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "B", "text": "A physical link aggregation group", "is_correct": false}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '08dc03dc415be092_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('092ad4ec-0a1b-482d-a17f-a92cfb382c6d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 63).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show spanning-tree interface", "is_correct": true}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '31404b9f79a28d6f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffa76c4b-e9e4-4c2b-b026-9ecff32b5c88', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 63).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "C", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '3525a2e821e871d7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e9b6933-dc5a-4358-a098-642d681f9b64', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 63).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65001 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'ebbf09baefd8e64a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bda712f7-fb73-44c6-893a-259efe4475f5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 63).', '[{"id": "A", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Provides PoE power negotiation for access ports", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, 'ecbc1a0c6e1d739a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d95523f-6df6-4298-bb0e-acd4744a2d12', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 63).', '[{"id": "A", "text": "set switch-port access VLAN 400", "is_correct": false}, {"id": "B", "text": "set interfaces et-2/0/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set vlans VLAN10 interface et-2/0/0", "is_correct": false}, {"id": "D", "text": "set interfaces et-2/0/0 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'c4c237fa524bd36b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66208410-d5f8-4e1e-b4b2-896638f418f9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 63).', '[{"id": "A", "text": "65002 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "C", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "1024 (10-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'ea010f9b2fdc69e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0350167e-1141-4d12-9a4d-90ab4601aa7d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 63).', '[{"id": "A", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}, {"id": "B", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "D", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '679edd6ae34cb727_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bb2f8d5-b66c-4fd2-ae38-de0db43adafd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 63).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "56 (111000)", "is_correct": false}, {"id": "C", "text": "46 (101110)", "is_correct": true}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '0ef157dd418f5d4a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cfcaeaf-7f34-4157-bbe7-a656f1b254b2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 63).', '[{"id": "A", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "B", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "C", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '58026ff254c3b208_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d92f3a6b-5257-4bc4-827d-470a424cfdaf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 63).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "D", "text": "Determines which packets are forwarded first", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '1db634dce8baca44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75a31385-67d3-4f68-b0fc-993fbba7cbc9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 63).', '[{"id": "A", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "B", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}, {"id": "C", "text": "set cos rewrite dscp 46 interface xe-3/1/0", "is_correct": false}, {"id": "D", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '226b67c99aacfcce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('83a92f89-97d2-4a2a-a7e1-911865596c9a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 63).', '[{"id": "A", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "B", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}, {"id": "C", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "D", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '26e9769ec32be99e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('641ddf08-a962-4b5e-9f52-bb5fdba0f8d8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 63).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '271a3b77cde914e1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7ad066d-cea8-4df3-a42a-0b26cdda6ecb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 63).', '[{"id": "A", "text": "1234", "is_correct": false}, {"id": "B", "text": "4789", "is_correct": true}, {"id": "C", "text": "8472", "is_correct": false}, {"id": "D", "text": "6633", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '829a2345b23ea8c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a02a4e3-50ea-4ac5-8985-22f2e7162857', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 63).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "C", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "D", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, '716b58b697e103ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3a80a01-d447-4a75-8727-b65b80925a83', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 63).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, '6f1aa2c4bd56647e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9103e9cd-d5e6-4945-a17e-823743a58445', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 63).', '[{"id": "A", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}, {"id": "B", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '6329e31cf2cee3a4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bc5e987-6aa9-433f-800a-578ee2bf007a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 63).', '[{"id": "A", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "B", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "C", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "D", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '0997261208c0b254_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0c8f6b0-58b5-4df2-9746-8024f78d97ee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 63).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "C", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "D", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '4a49098b8be3bb0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d88f3ba4-22a3-4bec-a070-c83dad3d95e8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 63).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '4ca65cab5478864e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('874b8f8f-77fa-4b1c-8b1a-3c596fc46795', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 63).', '[{"id": "A", "text": "show route <destination> trace", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "monitor trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, 'e8bf6be49db15009_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4556975-c343-4aca-b384-4c360000efc7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 63).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '1e3b360663fe082d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80412ed5-4154-428f-8001-9273d7a9aec9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 63).', '[{"id": "A", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "B", "text": "show route <prefix>", "is_correct": false}, {"id": "C", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "D", "text": "All of the above can be used", "is_correct": true}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'f9b4e308a0805ecb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1409f8ea-630a-4786-a82a-c133ce1614ed', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 63).', '[{"id": "A", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'b769c440ac6169ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8bdac6b-b6c1-4f91-85c6-98d5498133e1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 63).', '[{"id": "A", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}, {"id": "B", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.191.222.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, 'f5d5cdbede7ac7d0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a66923e-99e5-44ea-9111-280cd03116cc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 63).', '[{"id": "A", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "D", "text": "Defines user engineer permissions to the device", "is_correct": false}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, '88f2a28303f6efd2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ccca8d48-8b8f-465e-b86f-9eb6382abeb5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 63).', '[{"id": "A", "text": "reject", "is_correct": false}, {"id": "B", "text": "discard", "is_correct": true}, {"id": "C", "text": "silent-drop", "is_correct": false}, {"id": "D", "text": "deny", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'e1e9708aa2881e48_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1dc1ba5-f6ab-4a24-b57c-03d361020d2c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 63).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "C", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}, {"id": "D", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '885f2b6dad16d21e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4782a330-21e5-4b62-8b9b-6ba6355b3e65', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 63).', '[{"id": "A", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "B", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "C", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}, {"id": "D", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '48d08c5d76de3a39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6191df33-174f-4396-a664-797b9521d7d1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 63).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '2140e0715b95d87e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1924de23-aa27-4392-b252-b5652098dd91', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 63).', '[{"id": "A", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "B", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '68aedbccf1656cdc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e026a6e7-d65b-44f7-beca-a1583bdc0fe2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 64).', '[{"id": "A", "text": "Internal Router", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "Backbone Router", "is_correct": false}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'b745a67dd95cb6e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e69a49b-a4fe-4565-bbea-36923bb01b5c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 64).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "40 seconds", "is_correct": false}, {"id": "C", "text": "30 seconds", "is_correct": false}, {"id": "D", "text": "120 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '0438564980250580_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c693d062-060a-4fac-9061-62653268b254', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 64).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Forwards all traffic between routers in the same area", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '1e5b777fddac9d8b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfe51ded-8c5e-4bb1-9934-9368ee97d3e6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 64).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "C", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, 'b957c61324a841c5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f8aef6e-d9b4-4928-a47b-d4aa5f2664f2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 64).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show ospf adjacency", "is_correct": false}, {"id": "D", "text": "show ospf interface", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '65d372eab9f86019_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54cdb98f-52c8-419a-840c-d0026b137a01', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 64).', '[{"id": "A", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "B", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '0fbc9476299aba54_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f03176bd-c8ea-4921-9285-404a70f9c74f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 64).', '[{"id": "A", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "B", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '967a1d650f37773c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87ae1d31-c755-4b9c-aa5f-82dae595023d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 64).', '[{"id": "A", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "D", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '35789293cc11b295_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05a5295d-fc05-480d-8c4d-9e3b7da2f29e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 64).', '[{"id": "A", "text": "Link State PDU (LSP)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Hello PDU (IIH)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '46f6efeb1971b918_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebb33d47-197d-43ca-a7dd-f31d45c59950', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 64).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '9f427026b552cf04_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0194e9aa-b743-4fae-812c-a18c12a9ea6c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 64).', '[{"id": "A", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}, {"id": "D", "text": "64", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'aa2f2bd33af40c02_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('833690ab-1413-44c7-ac37-45b91689c8e5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 64).', '[{"id": "A", "text": "Configures the local preference value", "is_correct": false}, {"id": "B", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "C", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "D", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '01e6d7e2cea976bb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a8c3b2b-3fb2-45c2-aac1-6c936357c525', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 64).', '[{"id": "A", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '2e65c56db8a2091e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af3e7b37-a4c8-4a09-bc2d-de067287f2c7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 64).', '[{"id": "A", "text": "ORIGIN", "is_correct": false}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "D", "text": "COMMUNITY", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '44e5deb2e1dc1ae4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('588b8009-18c8-4d56-b836-6e8b6263b534', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 64).', '[{"id": "A", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The group of route reflector clients", "is_correct": false}, {"id": "D", "text": "The IP address of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '5f4141547ae4493b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7425eee7-6470-4d13-9769-32c285e8d8ee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 64).', '[{"id": "A", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "B", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "C", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, 'eb55e20b4630a4c3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c5b802b-b5ff-47d3-95c7-0d9755e097af', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 64).', '[{"id": "A", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "B", "text": "show bgp summary", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '2f938aaed0ffd170_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9c8f437d-8a54-406e-bd70-91219d2827cd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 64).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, 'cf4a69cfae79fc4c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8db2c892-31df-4c41-9df5-eec7f1522452', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 64).', '[{"id": "A", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "B", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "C", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '1f1f70ab875df3a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54a1bd73-3bdb-4542-908e-5cb67046760d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 64).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '63468f8aad3c3bc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('018b2cc3-62cb-4bb8-add6-bd796e9d4605', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 64).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '43e4d4b3b2a9dbf0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1aa5812-0c5b-4665-9738-f32b0db0b3d0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 64).', '[{"id": "A", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '93a07ccb59bd5cfa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08f41f9a-77b7-471c-afb1-3debe540a2fe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 64).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Alternate port", "is_correct": true}, {"id": "D", "text": "Backup port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, 'dae797c261426993_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0c535a4-4f09-449b-81c8-e2c3e3d2d617', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 64).', '[{"id": "A", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A single VLAN with its own STP instance", "is_correct": false}, {"id": "D", "text": "A physical link aggregation group", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'c84708ca8c637df8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53252882-6309-45ee-8a6b-f2bae89475a7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 64).', '[{"id": "A", "text": "show spanning-tree interface", "is_correct": true}, {"id": "B", "text": "show stp status", "is_correct": false}, {"id": "C", "text": "show bridge stp", "is_correct": false}, {"id": "D", "text": "show ethernet-switching spanning-tree", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, '7dfdf4252b7456e5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8f8248c-eac6-4673-962a-ecd4d06ba54d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 64).', '[{"id": "A", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "B", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "C", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}, {"id": "D", "text": "Accelerates STP convergence on access ports", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, '642417b0c7859edd_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97615e89-54c0-4380-aea2-3a3c70f81ac6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 64).', '[{"id": "A", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}, {"id": "C", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "D", "text": "The switch with the most ports becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65400 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, '73510851696e2328_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eee65c2b-b186-404f-b028-72f30e599df9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 64).', '[{"id": "A", "text": "Connects to the management network", "is_correct": false}, {"id": "B", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "C", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "D", "text": "Provides PoE power negotiation for access ports", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '74aa2a7ccff91818_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4796a4aa-19e0-48aa-8f78-88de8ce4d9c6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 64).', '[{"id": "A", "text": "set interfaces et-1/0/2 vlan-id 10", "is_correct": false}, {"id": "B", "text": "set interfaces et-1/0/2 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "C", "text": "set switch-port access VLAN 492", "is_correct": false}, {"id": "D", "text": "set vlans VLAN10 interface et-1/0/2", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, '48d2419cbc74ed60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffd34d49-d403-414b-9368-5cc6c53280c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 64).', '[{"id": "A", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}, {"id": "B", "text": "64700 (16-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "1024 (10-bit VLAN ID)", "is_correct": false}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'd2f07a178bd9fffb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c805bb1f-e2d5-4436-88bc-f41f21081471', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 64).', '[{"id": "A", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '0a53aba76c3f2b60_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77afef1e-82f9-407a-b145-99f82c2ee2fa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 64).', '[{"id": "A", "text": "26 (011010)", "is_correct": false}, {"id": "B", "text": "0 (000000)", "is_correct": false}, {"id": "C", "text": "46 (101110)", "is_correct": true}, {"id": "D", "text": "56 (111000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, '879cc91dce7b0eac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f09a99b3-c397-4d20-bebe-6a3f522468c9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 64).', '[{"id": "A", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}, {"id": "D", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, 'c3ca68a521564065_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa095ed9-a310-4ff2-a15b-639cda53359c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 64).', '[{"id": "A", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "B", "text": "Controls which packets are logged during congestion", "is_correct": false}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '0d15ed91245a3492_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c1d5d69-a569-49ae-a7d8-5f176e1a3b86', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 64).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set cos rewrite dscp 46 interface et-3/0/0", "is_correct": false}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, '42d8e1f653c7048f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f18747e-e92d-4c3c-9c81-6a3c6b6cb137', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 64).', '[{"id": "A", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "B", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "C", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "D", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, '7a6323a625086bf4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b605d859-6730-4c10-8429-2fb10886eb06', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 64).', '[{"id": "A", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}, {"id": "B", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "C", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "D", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'ea5836aa8b034178_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f36aa37f-9caa-4a76-9804-74ab5ceee9ef', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 64).', '[{"id": "A", "text": "8472", "is_correct": false}, {"id": "B", "text": "1234", "is_correct": false}, {"id": "C", "text": "6633", "is_correct": false}, {"id": "D", "text": "4789", "is_correct": true}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, 'bc397edb7c8e039a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26aed2c0-752d-47c0-bda6-b9f6b65ba712', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 64).', '[{"id": "A", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "B", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "C", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}, {"id": "D", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'b4452a4e0710a9a1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7b34952b-e85f-408a-949d-f7115b4c535e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 64).', '[{"id": "A", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "B", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "C", "text": "The EVPN routing table with BGP path selection", "is_correct": false}, {"id": "D", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'b9f39166a645034d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0248147-6181-4b67-b03f-ebeea27b4eb6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 64).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "C", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '70458cfd7184e2df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1eadeb8-8ed5-478d-ad56-69fbe4146063', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 64).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}, {"id": "C", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "D", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '11d8242625fd8201_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26f54a4f-18f3-436d-a757-4780c42b7d7d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 64).', '[{"id": "A", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "B", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "C", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}, {"id": "D", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, '240796b1b5186387_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5973d4dc-2435-468d-879d-b827c97500a5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 64).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}, {"id": "D", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, '0ccd33b6d26d49df_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b61693da-3640-4c94-88b0-728e1e04c667', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 64).', '[{"id": "A", "text": "monitor trace <destination>", "is_correct": false}, {"id": "B", "text": "traceroute <destination>", "is_correct": true}, {"id": "C", "text": "ping trace <destination>", "is_correct": false}, {"id": "D", "text": "show route <destination> trace", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '2d484cc04ed84068_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a368ff3-a56f-45d1-af48-8c4390608439', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 64).', '[{"id": "A", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "B", "text": "The OSPF link-state database", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '695348d6f72a7e4f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c9aa5ae-b245-4602-96a6-9664663d8046', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 64).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route protocol bgp <prefix>", "is_correct": false}, {"id": "D", "text": "show route <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'c4d4c6e1ef323867_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c5e1029-d3ff-4c94-bb58-9c1a2e22f50d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 64).', '[{"id": "A", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "B", "text": "Replace the interface cables", "is_correct": false}, {"id": "C", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "D", "text": "Disable and re-enable OSPF globally", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'c4b9291816a1392f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44a22952-5fce-4ea5-8b65-9e1a3d98fce5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 64).', '[{"id": "A", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "B", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "C", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.217.50.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '6a69b7238b782d42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a854716-b416-415b-b226-dc2975c2cf7f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 64).', '[{"id": "A", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "B", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "C", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'b682a12ab04fb6e6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e5922cf-34eb-476a-8150-f75ce1f7fadb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 64).', '[{"id": "A", "text": "reject", "is_correct": false}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": true}, {"id": "D", "text": "silent-drop", "is_correct": false}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, 'b4793d1f79d5558e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e1f1a52-5b82-4e95-a69d-8bf1d7abca6b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 64).', '[{"id": "A", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "B", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "C", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, 'f4cd6d1656536bef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('638de08f-121d-48c6-ab57-53427bee2e03', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 64).', '[{"id": "A", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "B", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "C", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, '47649e59ae24c621_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('692d3a1d-08ab-449b-9bd4-016ac9d32711', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 64).', '[{"id": "A", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "B", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}, {"id": "C", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "D", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, 'a1ee21c359c5ddee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26c4a9c9-ada7-4a4b-b1ce-890bc2f3c484', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 64).', '[{"id": "A", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}, {"id": "D", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, 'e02e6deffaa041ec_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d8763cc-3d64-4a6c-81f9-49f4bad261a2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 65).', '[{"id": "A", "text": "ABR", "is_correct": false}, {"id": "B", "text": "ASBR", "is_correct": true}, {"id": "C", "text": "Backbone Router", "is_correct": false}, {"id": "D", "text": "Internal Router", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '70a3be543063921d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('084cc0a5-ba85-4338-bea1-96df5ca6961b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 65).', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "120 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, 'd7cbc231523a918f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5dadeeb3-699e-4c5e-bd20-774f06d39f14', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 65).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "C", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '46dbecc2bbf6fe44_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca048c68-253c-469d-9de8-25298a86df4f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 65).', '[{"id": "A", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "B", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}, {"id": "C", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "D", "text": "Advertises external IPv6 routes", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '4baf8fad4edd7ac7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31750279-5fa0-4217-9288-00df921ee3dd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 65).', '[{"id": "A", "text": "show protocols ospf neighbors", "is_correct": false}, {"id": "B", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "C", "text": "show ospf interface", "is_correct": false}, {"id": "D", "text": "show ospf adjacency", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, 'ef1c65dcefec95d4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8518a94-b442-4118-b7e0-f42fc408bd84', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 65).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '452ac8544a560342_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b0d5408-37fc-4f48-9371-bc5b1245f78f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 65).', '[{"id": "A", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "B", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, '60f9a4d140067a4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a8233eb-1c06-41ac-957c-28de1c50dcb5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 65).', '[{"id": "A", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "B", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Both narrow and wide are supported by default", "is_correct": false}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, 'e5cb8306749d03c7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be0f78ff-2785-4dbe-9ead-8a6f82a2abdf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 65).', '[{"id": "A", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '17dc2af9e639ae2f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('804786c7-8ac2-45de-a7a4-b0a48b2a58fa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 65).', '[{"id": "A", "text": "AS_PATH", "is_correct": false}, {"id": "B", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'b402835151f4f3c6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e0f0952-a34c-472a-84a7-5e4ac289c46b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 65).', '[{"id": "A", "text": "255", "is_correct": false}, {"id": "B", "text": "64", "is_correct": false}, {"id": "C", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, '974b03231cbc7d59_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f29e9a54-e5d7-4ff4-825e-5524a6cb571a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 65).', '[{"id": "A", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}, {"id": "B", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Configures the local preference value", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'dc2cc4e93dbbbc0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c48f85c-65ee-4db9-bb8c-d705148f6bc8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 65).', '[{"id": "A", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}, {"id": "D", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'e476aee92f8f275e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5111ec42-191d-426a-a56c-5892d92a15af', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 65).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "COMMUNITY", "is_correct": false}, {"id": "C", "text": "ORIGIN", "is_correct": false}, {"id": "D", "text": "LOCAL_PREFERENCE", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, '10eefc58999ada03_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ecd8c5aa-f658-4a8b-a042-bab7df273bc2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 65).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The group of route reflector clients", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The AS of the route reflector", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '8dd57ced9a01ac30_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b9c4e71-ced1-48fa-95c0-177915dec858', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 65).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}, {"id": "C", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "D", "text": "Permanently deactivates BGP advertisement", "is_correct": false}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '7645c655e74f09fe_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('109115ec-568b-4f8d-9fc1-b0b5057a518d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 65).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show bgp neighbors", "is_correct": false}, {"id": "D", "text": "show route protocol bgp detail", "is_correct": true}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, '67afd50b7231bd1f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61ade551-67d9-4591-88fb-b7903fba6166', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 65).', '[{"id": "A", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "B", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "C", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}, {"id": "D", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '53524e0a9004f666_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('227a936b-8a21-48f2-8aff-6c8f2ef87068', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 65).', '[{"id": "A", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}, {"id": "B", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "C", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "D", "text": "Maintains the multicast forwarding cache", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, '84288a5d1379fdac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8ebe6b3-1443-4ace-9e71-bb40b43cc7f9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 65).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}, {"id": "C", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "D", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '2a900b471df8586e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e4d1bc55-78b6-46f2-b4c6-423829c0ab8c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 65).', '[{"id": "A", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "B", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "C", "text": "RPF is not used in PIM-SM", "is_correct": false}, {"id": "D", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, '1eb2c0dc830ff614_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bc8b4cd-f669-455d-bedd-4ef11e444b1b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 65).', '[{"id": "A", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "B", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "C", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}, {"id": "D", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, '21c1c346e15a7fb4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('459af722-8116-4a35-a55a-833ea20c0e00', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 65).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Edge port", "is_correct": false}, {"id": "C", "text": "Backup port", "is_correct": false}, {"id": "D", "text": "Alternate port", "is_correct": true}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '41f2c50bb0832127_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37f93660-79bb-4792-93c9-4da83fb5a0b2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 65).', '[{"id": "A", "text": "A physical link aggregation group", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, 'e29e9dd50b08789e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('026dc534-cb36-405c-8608-893958895808', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 65).', '[{"id": "A", "text": "show stp status", "is_correct": false}, {"id": "B", "text": "show spanning-tree interface", "is_correct": true}, {"id": "C", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "D", "text": "show bridge stp", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'b1557aa21b4fa8d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c73556e3-a0ed-43c3-8fe3-81293f2c9a83', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of BPDU guard on an access port (variant 65).', '[{"id": "A", "text": "Disables the port if a BPDU is received, protecting against rogue switch connections", "is_correct": true}, {"id": "B", "text": "Filters BPDUs from being sent out of the port", "is_correct": false}, {"id": "C", "text": "Accelerates STP convergence on access ports", "is_correct": false}, {"id": "D", "text": "Prioritizes BPDUs for faster failover", "is_correct": false}]', 'BPDU guard errdisables the port when a BPDU is received on an access port, preventing unauthorized switches from being connected and affecting the STP topology.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Protection', 12.0, 'ea6739d88b8aecc2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1d31100-7fe4-4db9-8dfe-a1512167c53e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the root bridge election process in STP (variant 65).', '[{"id": "A", "text": "The switch with the most ports becomes root", "is_correct": false}, {"id": "B", "text": "The switch with the lowest bridge priority (and lowest MAC address as tiebreaker) becomes root", "is_correct": true}, {"id": "C", "text": "The switch with the highest CPU clock speed becomes root", "is_correct": false}, {"id": "D", "text": "The switch with the highest bridge priority becomes root", "is_correct": false}]', 'The root bridge is elected based on lowest bridge ID (priority + MAC address). The bridge priority range is 0-65100 in increments of 4096.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Root Bridge', 12.0, 'aba4b60347ad97ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ce28c4b-e3b6-4005-8739-cc93f71cd0c2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos, what is the function of a VLAN interface (vlan.0) on an EX switch (variant 65).', '[{"id": "A", "text": "Trunks multiple VLANs between switches", "is_correct": false}, {"id": "B", "text": "Connects to the management network", "is_correct": false}, {"id": "C", "text": "Provides Layer 3 routing for the VLAN as an SVI (Switch Virtual Interface)", "is_correct": true}, {"id": "D", "text": "Provides PoE power negotiation for access ports", "is_correct": false}]', 'A VLAN interface (vlan.<unit>) is a Layer 3 logical interface (SVI) used for inter-VLAN routing. The switch must have at least one port in the VLAN for the interface to be up.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Routing', 12.0, '1e33675ab5ab50ab_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13ae35a3-fdd0-4b34-b548-254807eadaf6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'How do you configure an access port on a Juniper EX switch to belong to a specific VLAN (variant 65).', '[{"id": "A", "text": "set vlans VLAN10 interface ge-1/0/0", "is_correct": false}, {"id": "B", "text": "set switch-port access VLAN 392", "is_correct": false}, {"id": "C", "text": "set interfaces ge-1/0/0 unit 0 family ethernet-switching vlan members 10", "is_correct": true}, {"id": "D", "text": "set interfaces ge-1/0/0 vlan-id 10", "is_correct": false}]', 'Access ports use ''family ethernet-switching'' with ''vlan members'' to assign the port to a VLAN. Trunk ports use ''vlan members all'' or a list of VLAN IDs.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Configuration', 12.0, 'a214ffc4f640d1ef_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40380d1e-571b-4e17-985a-3a08abb6f576', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the maximum number of VLANs supported by 802.1Q tagging (variant 65).', '[{"id": "A", "text": "64520 (16-bit VLAN ID)", "is_correct": false}, {"id": "B", "text": "256 (8-bit VLAN ID)", "is_correct": false}, {"id": "C", "text": "1024 (10-bit VLAN ID)", "is_correct": false}, {"id": "D", "text": "4094 (12-bit VLAN ID, values 1-4094 usable)", "is_correct": true}]', '802.1Q uses a 12-bit VLAN ID field, allowing VLANs 0-4095. VLAN 0 and 4095 are reserved, leaving 1-4094 (4094 usable VLANs).', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'VLAN Fundamentals', 10.0, 'cc2851a6f451823d_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56558617-b282-4ab6-b963-fdb772fdc5b7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is a native VLAN on a trunk port and how does it differ from tagged VLANs (variant 65).', '[{"id": "A", "text": "Native VLAN is used exclusively for voice traffic", "is_correct": false}, {"id": "B", "text": "Native VLAN traffic is double-tagged for additional security", "is_correct": false}, {"id": "C", "text": "Native VLAN traffic is sent untagged on the trunk; all other VLANs are 802.1Q tagged", "is_correct": true}, {"id": "D", "text": "Native VLAN cannot be changed from the default VLAN 1", "is_correct": false}]', 'The native VLAN frames are transmitted without an 802.1Q tag on the trunk. Both ends of the trunk must agree on the native VLAN to avoid VLAN mismatch issues.', '{"https://www.juniper.net/documentation/us/en/software/junos/vlans/"}', 'Trunk Ports', 12.0, '465cc3e480f2bd8c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4561f975-2e75-4b24-ac4e-5e8191b4d530', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'Which DiffServ Code Point (DSCP) value is recommended for voice traffic (EF - Expedited Forwarding) (variant 65).', '[{"id": "A", "text": "56 (111000)", "is_correct": false}, {"id": "B", "text": "46 (101110)", "is_correct": true}, {"id": "C", "text": "26 (011010)", "is_correct": false}, {"id": "D", "text": "0 (000000)", "is_correct": false}]', 'EF (Expedited Forwarding) uses DSCP 46 (binary 101110). AF classes use DSCP values 10, 12, 14 (AF1), 18, 20, 22 (AF2), etc. Voice typically uses EF.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'QoS Classification', 12.0, 'ef32af2e384fcb46_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5998c33-ab69-4378-9ac7-39ba0d08d22c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does CoS (Class of Service) work on a Juniper EX switch to prioritize delay-sensitive traffic (variant 65).', '[{"id": "A", "text": "Applies priority only at Layer 3 using DSCP marking without queuing", "is_correct": false}, {"id": "B", "text": "Classifies traffic at the ingress, assigns a forwarding class, and applies scheduling/queuing at the egress", "is_correct": true}, {"id": "C", "text": "Prioritizes all traffic equally across all ports", "is_correct": false}, {"id": "D", "text": "Uses MPLS EXP bits exclusively for QoS marking", "is_correct": false}]', 'Junos CoS performs classification at ingress (based on DSCP/IP/interface), assigns forwarding classes (best-effort, assured-forwarding, expedited-forwarding), and applies schedulers/shapers at egress.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Architecture', 12.0, '7c06242c1b31d2fb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d7ad3c0-dc8a-4125-9cc1-5df637a58d39', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a ''loss-priority'' in Junos CoS configuration (variant 65).', '[{"id": "A", "text": "Marks packets for higher bandwidth allocation", "is_correct": false}, {"id": "B", "text": "Determines drop probability within a forwarding class during congestion (high/low loss priority)", "is_correct": true}, {"id": "C", "text": "Determines which packets are forwarded first", "is_correct": false}, {"id": "D", "text": "Controls which packets are logged during congestion", "is_correct": false}]', 'Loss priority (high/low) within a forwarding class determines which packets are dropped first during congestion via RED/WRED drop profiles.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Queuing', 10.0, '439c0dd1a1bc7113_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9609408-c3fb-4c13-a998-263c688bafaa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'apply', 'Which command configures a DSCP rewrite rule on a Junos interface to mark outgoing packets with a specific forwarding class (variant 65).', '[{"id": "A", "text": "set class-of-service rewrite-rules dscp RULE-NAME forwarding-class expedited-forwarding loss-priority low code-point 101110", "is_correct": true}, {"id": "B", "text": "set qos rewrite DSCP EF", "is_correct": false}, {"id": "C", "text": "set cos rewrite dscp 46 interface et-3/1/1", "is_correct": false}, {"id": "D", "text": "set class-of-service classifiers dscp EF rewrite", "is_correct": false}]', 'Rewrite rules are configured under ''class-of-service rewrite-rules'' and assign a specific code-point value to packets based on their forwarding class and loss priority.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Rewrite Rules', 12.0, 'e57246896d53328c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c5781b6-2163-406e-abe8-8219482f80aa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of ''shaping-rate'' in Junos CoS (variant 65).', '[{"id": "A", "text": "Limits the transmission rate on an interface to a specified bandwidth, buffering excess traffic", "is_correct": true}, {"id": "B", "text": "Configures the maximum packet size allowed on an interface", "is_correct": false}, {"id": "C", "text": "Limits the rate of incoming traffic before classification", "is_correct": false}, {"id": "D", "text": "Determines the scheduling order of forwarding classes", "is_correct": false}]', 'Shaping-rate limits the egress bandwidth to a specified rate. Excess traffic is buffered (not dropped) and transmitted when capacity becomes available.', '{"https://www.juniper.net/documentation/us/en/software/junos/cos/"}', 'CoS Traffic Shaping', 12.0, 'b172019f430a8703_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d001669-b0c7-434c-b036-36aa718fbf8d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In EVPN-VXLAN, what is the purpose of Route Type 2 (MAC/IP Advertisement Route) (variant 65).', '[{"id": "A", "text": "Advertises MAC addresses and optionally associated IP addresses for host reachability", "is_correct": true}, {"id": "B", "text": "Advertises Ethernet segment information for multi-homing", "is_correct": false}, {"id": "C", "text": "Carries multicast group membership information", "is_correct": false}, {"id": "D", "text": "Advertises IP prefixes for inter-subnet routing", "is_correct": false}]', 'Route Type 2 carries MAC address (mandatory) and IP address (optional) information. It enables MAC learning and ARP suppression across the EVPN fabric.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '4817f8bb5dc1eae0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66b87c3f-4f54-4533-ace5-203d61105f94', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default VXLAN UDP destination port number (variant 65).', '[{"id": "A", "text": "8472", "is_correct": false}, {"id": "B", "text": "6633", "is_correct": false}, {"id": "C", "text": "4789", "is_correct": true}, {"id": "D", "text": "1234", "is_correct": false}]', 'VXLAN uses UDP destination port 4789 (IANA-assigned). Some early implementations used 8472 (Linux VXLAN). The IETF standard is port 4789.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'VXLAN Fundamentals', 10.0, '381249370f8ed3f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3bc51c34-376d-4f45-8577-7f59882dd870', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'In EVPN-VXLAN with an anycast IRB gateway model, what is the benefit of using a consistent virtual MAC (VMAC) across all VTEPs (variant 65).', '[{"id": "A", "text": "Provides encryption for VXLAN traffic between VTEPs", "is_correct": false}, {"id": "B", "text": "Enables seamless host mobility without ARP/ND flapping when the host moves between VTEPs", "is_correct": true}, {"id": "C", "text": "Increases the MAC address table capacity of the switch", "is_correct": false}, {"id": "D", "text": "Reduces the number of BGP routes needed for EVPN", "is_correct": false}]', 'All VTEPs in an anycast IRB model share the same virtual MAC address. When a host moves, the new VTEP sends a gratuitous ARP/NA with the same VMAC, so the host sees no gateway MAC change.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Anycast Gateway', 14.0, 'a7a38bfca09accf0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('760a951f-7bd4-4c10-a9b1-0b551ecc5ce5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does ''show evpn database extensive'' display on a Junos switch (variant 65).', '[{"id": "A", "text": "The EVPN route reflector configuration", "is_correct": false}, {"id": "B", "text": "Detailed EVPN learned MAC and IP information per VLAN for all remote VTEPs", "is_correct": true}, {"id": "C", "text": "VXLAN tunnel endpoint statistics only", "is_correct": false}, {"id": "D", "text": "The EVPN routing table with BGP path selection", "is_correct": false}]', '''show evpn database extensive'' shows the local and remote MAC+IP entries learned via EVPN, including the next-hop VTEP, VLAN, and sequence numbers.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Operations', 10.0, 'bd4106bfc60cc0f9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42eae45b-9884-468f-af11-8e3f66bdfbc1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'How does EVPN prevent MAC flapping when a host moves between different leaf switches (variant 65).', '[{"id": "A", "text": "All leaf switches must be configured with static MAC entries for the host", "is_correct": false}, {"id": "B", "text": "Requires manual reconfiguration of the host''s MAC address on the new leaf", "is_correct": false}, {"id": "C", "text": "Uses STP to detect the topology change", "is_correct": false}, {"id": "D", "text": "Uses a sequence number in the MAC/IP Advertisement Route - higher sequence wins, and old entries are withdrawn", "is_correct": true}]', 'EVPN uses a sequence number in Route Type 2 for MAC mobility. The PE with the higher sequence number for the same MAC wins, and the old PE withdraws its route.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Mobility', 12.0, '02f9fe9f03eaf1c9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a2016ff-a36a-4e43-9944-d24d58c2ca33', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is VRRP and how does it provide first-hop redundancy (variant 65).', '[{"id": "A", "text": "VRRP elects a DR to handle all routing protocol updates", "is_correct": false}, {"id": "B", "text": "Each host is configured with multiple default gateways", "is_correct": false}, {"id": "C", "text": "Multiple routers share a virtual IP address; one master forwards traffic, a backup takes over if the master fails", "is_correct": true}, {"id": "D", "text": "Routers load balance traffic across multiple gateways", "is_correct": false}]', 'VRRP (Virtual Router Redundancy Protocol) groups routers into a virtual router with a shared virtual IP and MAC. The master router handles forwarding; standby routers take over upon failure.', '{"https://www.juniper.net/documentation/us/en/software/junos/vrrp/"}', 'VRRP', 12.0, '3a6cd6c56134f859_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef849992-cfe0-4aca-8435-13c26e0b9b97', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of Graceful Routing Engine Switchover (GRES) on a dual-RE Juniper device (variant 65).', '[{"id": "A", "text": "Enables the backup RE to take over forwarding without interruption if the primary RE fails", "is_correct": false}, {"id": "B", "text": "Both A and C - GRES preserves PFE forwarding and keeps routing protocol sessions up", "is_correct": true}, {"id": "C", "text": "Allows the PFE to continue forwarding during RE switchover", "is_correct": false}, {"id": "D", "text": "Keeps BGP sessions up after a RE switchover without re-establishment", "is_correct": false}]', 'GRES preserves the PFE forwarding table during RE switchover and keeps kernel connections intact. Combined with NSR (Nonstop Routing), BGP/OSPF sessions also survive without re-establishment.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'GRES', 12.0, 'ca70df14be2ffa7f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05ee23eb-775b-4ae5-813f-81748ab8ca96', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 5, 'understand', 'What is Nonstop Active Routing (NSR) in Junos (variant 65).', '[{"id": "A", "text": "Routing updates are queued during RE switchover and processed after the switchover completes", "is_correct": false}, {"id": "B", "text": "BGP sessions are re-established after a RE switchover using graceful restart capability", "is_correct": false}, {"id": "C", "text": "A router runs multiple routing protocols simultaneously without conflicts", "is_correct": false}, {"id": "D", "text": "Routing protocol state is synchronized from the primary RE to the backup RE, so sessions survive switchover without peer detection", "is_correct": true}]', 'NSR synchronizes protocol state (BGP FSM, OSPF adjacency, LDP sessions) from the active to the standby RE. When switchover occurs, the standby RE continues protocol operations transparently.', '{"https://www.juniper.net/documentation/us/en/software/junos/ha/"}', 'Nonstop Routing', 12.0, 'dab79b7dd90b6c35_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7c9bbad-f956-41b0-9851-80ea1617277a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which Junos operational command performs a real-time trace route from the device to a specified destination (variant 65).', '[{"id": "A", "text": "traceroute <destination>", "is_correct": true}, {"id": "B", "text": "show route <destination> trace", "is_correct": false}, {"id": "C", "text": "monitor trace <destination>", "is_correct": false}, {"id": "D", "text": "ping trace <destination>", "is_correct": false}]', '''traceroute'' sends UDP probes with incrementing TTL values to identify the path a packet takes. The response shows each hop along the path.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Connectivity Verification', 10.0, '8248ee88807ff984_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8ca1c78-ba0d-44bd-8347-0270fdf41c2f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What does the command ''show route forwarding-table'' display (variant 65).', '[{"id": "A", "text": "The forwarding table (kernel routing table) that the PFE uses for packet forwarding", "is_correct": true}, {"id": "B", "text": "The BGP route table with all attributes", "is_correct": false}, {"id": "C", "text": "The multicast forwarding cache", "is_correct": false}, {"id": "D", "text": "The OSPF link-state database", "is_correct": false}]', '''show route forwarding-table'' displays the kernel forwarding table, which is the subset of active best routes actually used by the PFE for packet forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Forwarding Table', 10.0, '4ddca922c57da3ea_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b7f3edb-6d8b-4775-b480-a0f63cfa5135', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'apply', 'Which command verifies that a specific route is present in the routing table, showing the exact next-hop and protocol (variant 65).', '[{"id": "A", "text": "show route table inet.0 <prefix>", "is_correct": false}, {"id": "B", "text": "All of the above can be used", "is_correct": true}, {"id": "C", "text": "show route <prefix>", "is_correct": false}, {"id": "D", "text": "show route protocol bgp <prefix>", "is_correct": false}]', '''show route <prefix>'' displays all routes matching the prefix. Options like ''protocol bgp'' filter by source. ''table inet.0'' specifies the routing table to query.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Route Verification', 10.0, 'dbe1e57f7a2ef269_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b94f2685-b44e-4535-ab3c-215dcbd3a1f0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'What is the first troubleshooting step when interfaces are up but OSPF neighbors are not forming (variant 65).', '[{"id": "A", "text": "Reboot the router to reset OSPF adjacencies", "is_correct": false}, {"id": "B", "text": "Verify OSPF configuration (area, network type, authentication) and check that interfaces are included in the OSPF area", "is_correct": true}, {"id": "C", "text": "Disable and re-enable OSPF globally", "is_correct": false}, {"id": "D", "text": "Replace the interface cables", "is_correct": false}]', 'First check ''show ospf neighbor'' to see current adjacency states. Then verify OSPF configuration - interfaces must be included in the OSPF area, network types must match, and authentication must be consistent.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 12.0, 'e2782d70bb8f6f86_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55683f07-0c32-4d21-8240-a7f5dfc3846b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In Junos routing policy, what is the difference between ''from protocol'' and ''from route-filter'' (variant 65).', '[{"id": "A", "text": "''from protocol'' filters by IP protocol; ''from route-filter'' filters by route type", "is_correct": false}, {"id": "B", "text": "They are functionally identical and can be used interchangeably", "is_correct": false}, {"id": "C", "text": "''from protocol'' matches routes from a specific protocol source; ''from route-filter'' matches specific prefixes within those routes", "is_correct": true}, {"id": "D", "text": "''from protocol'' is for inbound policies; ''from route-filter'' is for outbound policies", "is_correct": false}]', '''from protocol bgp'' matches all routes learned via BGP. ''from route-filter 10.142.147.0/8 orlonger'' further limits to a specific prefix range. They are often used together.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '2d36e1559a668472_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ba9146d-b8fb-4181-a041-17bb4c6049fd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of ''policy-statement'' in Junos (variant 65).', '[{"id": "A", "text": "Configures NAT translation rules", "is_correct": false}, {"id": "B", "text": "Defines firewall rules for packet filtering", "is_correct": false}, {"id": "C", "text": "Defines user engineer permissions to the device", "is_correct": false}, {"id": "D", "text": "Defines a named set of match conditions and actions used to control route acceptance, advertisement, and modification", "is_correct": true}]', 'A policy-statement consists of terms with ''from'' (match) and ''then'' (action) conditions. They can accept, reject, or modify routes, and can be applied as import or export policies.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Policy Fundamentals', 12.0, 'f7311d863b8e3ee4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a379598a-98d2-4d4e-9509-0a59b989700f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In a firewall filter, which action should be used to silently drop traffic without sending an ICMP response (variant 65).', '[{"id": "A", "text": "deny", "is_correct": false}, {"id": "B", "text": "silent-drop", "is_correct": false}, {"id": "C", "text": "reject", "is_correct": false}, {"id": "D", "text": "discard", "is_correct": true}]', '''discard'' silently drops the packet without sending any notification. ''reject'' sends an ICMP unreachable message back to the source. ''accept'' permits the traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/firewall-filters/"}', 'Firewall Filter Actions', 10.0, '1edfd02b8526c7fa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ad7c9cf-6215-4e0a-9f68-acad504162ce', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the effect of ''prefix-list'' in a routing policy when used as ''from prefix-list BLOCK-RFC1918'' (variant 65).', '[{"id": "A", "text": "Matches routes with the specified prefix length exactly", "is_correct": false}, {"id": "B", "text": "Matches routes based on next-hop address, not destination prefix", "is_correct": false}, {"id": "C", "text": "Matches all routes except those in the prefix-list", "is_correct": false}, {"id": "D", "text": "Matches routes whose destination prefix is in the prefix-list; routes outside the list are not matched", "is_correct": true}]', '''from prefix-list <name>'' matches routes whose destination prefix matches an entry in the referenced prefix-list. The prefix-list can include exact, longer, or orlonger matches.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Prefix Lists', 10.0, '6df883596834341c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75baa46e-0c98-4a91-aaf7-a54eddb4c9d3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the recommended campus network architecture using Juniper EX and QFX switches (variant 65).', '[{"id": "A", "text": "Traditional 3-tier (Core-Access-Distribution) with STP-based loop prevention", "is_correct": false}, {"id": "B", "text": "Spine-leaf (Clos) architecture with QFX as spines and EX as leafs, using EVPN-VXLAN for overlay", "is_correct": true}, {"id": "C", "text": "Single switch acting as both core and distribution", "is_correct": false}, {"id": "D", "text": "Full mesh of all switches with no hierarchy", "is_correct": false}]', 'Modern Juniper campus designs use a spine-leaf IP fabric (EVPN-VXLAN) with QFX as spine and EX/QFX as leaf. This provides active-active uplinks and eliminates STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/campus/"}', 'Campus Fabric Design', 12.0, 'c0361c6baea86710_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0c5778e-99f2-44d3-b2e0-54d8b4fd9bb7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'What is the benefit of an EVPN-VXLAN fabric over a traditional spanning-tree based campus network (variant 65).', '[{"id": "A", "text": "No BGP configuration is needed in the fabric", "is_correct": false}, {"id": "B", "text": "Fabric only requires Layer 2 connectivity between switches", "is_correct": false}, {"id": "C", "text": "All uplinks are active and can forward traffic simultaneously, with sub-second convergence and no blocked ports", "is_correct": true}, {"id": "D", "text": "Lower cost per port due to simpler hardware requirements", "is_correct": false}]', 'EVPN-VXLAN fabrics enable all active uplinks using ECMP, eliminating STP''s blocked ports. Convergence times drop from STP''s 30-50s to sub-second via BGP/L3 routing.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Benefits', 12.0, '404e044830bf3da8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2015321b-d00e-466d-9e78-6fb2f3faeb41', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which protocol is used by EX and QFX switches to form a Virtual Chunder Fabric (VCF) for simplified management (variant 65).', '[{"id": "A", "text": "Virtual Chassis Protocol (VCP) over dedicated VCP ports or configured network ports", "is_correct": true}, {"id": "B", "text": "BGP on loopback interfaces between the switches", "is_correct": false}, {"id": "C", "text": "OSPF with a specific area for VCF connectivity", "is_correct": false}, {"id": "D", "text": "EVPN route type 6 for fabric discovery", "is_correct": false}]', 'VCP (Virtual Chassis Port) allows switches to interconnect and form a single logical device. VCP ports can be dedicated SFP+ ports or configured on any network port.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis Fabric', 10.0, '8971e416e355d3e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ac7b2e6-c433-4c94-b379-86aca031a402', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which OSPF router type generates Type 5 LSAs to advertise external routes into the OSPF domain (variant 66).', '[{"id": "A", "text": "Backbone Router", "is_correct": false}, {"id": "B", "text": "Internal Router", "is_correct": false}, {"id": "C", "text": "ASBR", "is_correct": true}, {"id": "D", "text": "ABR", "is_correct": false}]', 'ASBR (Autonomous System Boundary Router) injects external routes into OSPF and generates Type 5 LSAs. ABRs generate Type 3/4 LSAs for inter-area routes.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '1a675f0376fe17cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9ea6307-c8aa-4013-a953-4397f21d50a0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast multi-access network (variant 66).', '[{"id": "A", "text": "120 seconds", "is_correct": false}, {"id": "B", "text": "10 seconds", "is_correct": true}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "30 seconds", "is_correct": false}]', 'On broadcast and point-to-point networks, the default hello interval is 10 seconds. On NBMA networks, it is 30 seconds. Dead interval is 4x hello by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Operation', 12.0, '70d686ccafda5a69_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bed3f635-3c07-4df9-8c23-1654ae1cf70f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In OSPF multi-area design, what is the function of an Area Border Router (ABR) (variant 66).', '[{"id": "A", "text": "Connects the backbone area (Area 0) to other areas and summarizes routes", "is_correct": true}, {"id": "B", "text": "Forwards all traffic between routers in the same area", "is_correct": false}, {"id": "C", "text": "Connects to external routing domains only", "is_correct": false}, {"id": "D", "text": "Elected by OSPF neighbors to distribute Type 7 LSAs", "is_correct": false}]', 'ABRs have interfaces in Area 0 and at least one other area. They generate Type 3 summary LSAs and can perform route summarization between areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 14.0, '25afb85e6ca6ab91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24d3bf52-670a-4f77-bc50-6a7bdf8b1c83', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of OSPFv3 Type 8 LSA (variant 66).', '[{"id": "A", "text": "Contains the OSPFv3 routing table checksum", "is_correct": false}, {"id": "B", "text": "Advertises external IPv6 routes", "is_correct": false}, {"id": "C", "text": "Links an IPv6 prefix to a link-local interface on a non-broadcast segment", "is_correct": true}, {"id": "D", "text": "Describes the router''s IPv6 link-local addresses", "is_correct": false}]', 'OSPFv3 uses Type 8 LSA (Link LSA) to advertise IPv6 prefix information associated with a link-local interface to other routers on the same link.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospfv3/"}', 'OSPFv3', 12.0, '13fb4d2bcf712fe4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee45f8ac-b65f-4134-9974-11b80b3412ec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which Junos command displays OSPF neighbor adjacency details including DR/BDR election status (variant 66).', '[{"id": "A", "text": "show ospf neighbor detail", "is_correct": true}, {"id": "B", "text": "show ospf adjacency", "is_correct": false}, {"id": "C", "text": "show ospf interface", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbors", "is_correct": false}]', '''show ospf neighbor detail'' shows neighbor IP, state (Full/2-Way/ExStart), DR/BDR status, and adjacent interface. ''show ospf interface'' shows per-interface OSPF settings.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Troubleshooting', 10.0, '649dc3ddcac28d14_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a357c74a-9bda-44f1-8741-031ad19e921a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does OSPF prevent routing loops in multi-area designs (variant 66).', '[{"id": "A", "text": "Each area runs a separate SPF calculation and OSPF uses split-horizon", "is_correct": false}, {"id": "B", "text": "All non-backbone areas must connect directly to Area 0 (backbone) and traffic cannot traverse between non-backbone areas directly", "is_correct": true}, {"id": "C", "text": "All OSPF routers maintain full topology of every area", "is_correct": false}, {"id": "D", "text": "Type 7 LSAs are never flooded beyond the NSSA", "is_correct": false}]', 'OSPF mandates a 2-level hierarchy. All areas must connect to Area 0. Inter-area traffic always passes through Area 0, preventing loops in multi-area designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF Design', 12.0, '9bd7b392ad300303_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ef4d360-6c7f-4b02-af08-11626792588f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'In IS-IS, what is the difference between Level 1 and Level 2 routers (variant 66).', '[{"id": "A", "text": "L1 routers use SPF; L2 routers use distance-vector", "is_correct": false}, {"id": "B", "text": "L1 routers are for IPv4 only; L2 routers are for IPv6 only", "is_correct": false}, {"id": "C", "text": "L1 routers are access switches; L2 routers are core switches", "is_correct": false}, {"id": "D", "text": "L1 knows only intra-area topology; L2 knows inter-area topology. L1/L2 routers attach to both", "is_correct": true}]', 'IS-IS hierarchy: Level 1 routers operate within an area (intra-area), Level 2 routers connect areas (inter-area). L1/L2 routers participate in both levels.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Fundamentals', 12.0, 'a5f83dc40aacc09b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e9d69af-967f-4ea0-a9ef-5eb7663be5e7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the default IS-IS metric style in Junos (variant 66).', '[{"id": "A", "text": "Both narrow and wide are supported by default", "is_correct": false}, {"id": "B", "text": "Wide metrics (max 2^24-1 per link)", "is_correct": false}, {"id": "C", "text": "IS-IS uses hop count as its metric", "is_correct": false}, {"id": "D", "text": "Narrow metrics (max 63 per link, 1023 total path)", "is_correct": true}]', 'Junos defaults to narrow metrics (6-bit link metric, max 63). Wide metrics (24-bit, max 16,777,215) must be explicitly configured with ''wide-metrics-only''.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Configuration', 10.0, '20bd4f2f31a9f08e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f09b4ff-ccbd-4d56-a659-b21157454673', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which IS-IS PDU type is used for link-state database synchronization between adjacent routers (variant 66).', '[{"id": "A", "text": "Partial Sequence Numbers PDU (PSNP)", "is_correct": false}, {"id": "B", "text": "Complete Sequence Numbers PDU (CSNP)", "is_correct": true}, {"id": "C", "text": "Hello PDU (IIH)", "is_correct": false}, {"id": "D", "text": "Link State PDU (LSP)", "is_correct": false}]', 'CSNPs are sent periodically by the DIS to provide a complete summary of the LSP database on broadcast networks. PSNPs are used for partial synchronization and acknowledgments.', '{"https://www.juniper.net/documentation/us/en/software/junos/isis/"}', 'IS-IS Operations', 12.0, '265e3b9e5a0c0015_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af126de6-2113-499e-bf65-e465ca055b23', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is primarily used for outbound traffic engineering from an AS (variant 66).', '[{"id": "A", "text": "WEIGHT (Cisco proprietary)", "is_correct": false}, {"id": "B", "text": "MED (MULTI_EXIT_DISC)", "is_correct": false}, {"id": "C", "text": "LOCAL_PREFERENCE", "is_correct": true}, {"id": "D", "text": "AS_PATH", "is_correct": false}]', 'LOCAL_PREFERENCE influences outbound traffic by affecting which path is chosen for routes leaving the AS. Higher LOCAL_PREF is preferred. It is exchanged within iBGP only.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'aa0aa864367e2912_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ebf1f9e8-c9d6-40a4-aea0-a38f3c496b6a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default eBGP multihop TTL value when configuring an EBGP multihop session (variant 66).', '[{"id": "A", "text": "1 (directly connected required by default)", "is_correct": true}, {"id": "B", "text": "255", "is_correct": false}, {"id": "C", "text": "64", "is_correct": false}, {"id": "D", "text": "0 (TTL decremented to 0 by default)", "is_correct": false}]', 'eBGP defaults to TTL=1, requiring directly connected peers. ''multihop'' must be configured for non-directly connected eBGP sessions, specifying the number of hops allowed.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'eBGP Configuration', 10.0, 'f49fd401dd429cb0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52c04336-2694-4ce5-a3bc-2972a404757e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Junos BGP configuration, what does ''local-as'' under a BGP group do (variant 66).', '[{"id": "A", "text": "Sets the BGP router ID", "is_correct": false}, {"id": "B", "text": "Configures the local preference value", "is_correct": false}, {"id": "C", "text": "Overrides the global AS number for a specific BGP group, enabling AS number hiding", "is_correct": true}, {"id": "D", "text": "Defines the local AS for the BGP group''s routing instance", "is_correct": false}]', '''local-as'' allows a BGP group to use a different AS than the one configured under ''routing-options autonomous-system''. It can also prepend the real AS using ''private'' option.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '0ea20e83c1b9b0e9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61d9c643-cec1-4e70-82fe-65307d8c61c1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the correct order of BGP path selection criteria (variant 66).', '[{"id": "A", "text": "Highest LOCAL_PREF → Shortest AS_PATH → Lowest MED → eBGP over iBGP → Lowest IGP metric to next-hop", "is_correct": true}, {"id": "B", "text": "Lowest MED → Highest LOCAL_PREF → eBGP over iBGP → Shortest AS_PATH", "is_correct": false}, {"id": "C", "text": "eBGP over iBGP → Lowest MED → Shortest AS_PATH → Lowest IGP metric", "is_correct": false}, {"id": "D", "text": "Shortest AS_PATH → Highest LOCAL_PREF → Lowest MED → eBGP over iBGP", "is_correct": false}]', 'The complete BGP decision process: 1) Highest LOCAL_PREF, 2) Shortest AS_PATH, 3) Lowest origin (IGP<EGP<incomplete), 4) Lowest MED, 5) eBGP over iBGP, 6) Lowest IGP metric to next-hop.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, 'ede8d49d5dd47c9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dda90c4d-bc81-4c3c-a9ee-c7b26a99e53c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP attribute is used for inbound traffic engineering by influencing the path selection of neighboring ASes (variant 66).', '[{"id": "A", "text": "MED (MULTI_EXIT_DISC)", "is_correct": true}, {"id": "B", "text": "LOCAL_PREFERENCE", "is_correct": false}, {"id": "C", "text": "COMMUNITY", "is_correct": false}, {"id": "D", "text": "ORIGIN", "is_correct": false}]', 'MED is sent to eBGP neighbors to influence their inbound path selection. Lower MED is preferred. MED is only compared between paths from the same neighboring AS.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Traffic Engineering', 12.0, 'c819278783813bf5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8367fcf4-e2d1-41b3-b347-032a36dccd93', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector cluster, what does the ''cluster'' configuration option specify (variant 66).', '[{"id": "A", "text": "The IP address of the route reflector", "is_correct": false}, {"id": "B", "text": "The AS of the route reflector", "is_correct": false}, {"id": "C", "text": "The cluster ID used in the CLUSTER_LIST attribute for loop prevention", "is_correct": true}, {"id": "D", "text": "The group of route reflector clients", "is_correct": false}]', 'The cluster ID is included in the CLUSTER_LIST attribute when the RR reflects routes. If a RR sees its own cluster ID in the CLUSTER_LIST, the route is ignored to prevent loops.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '46fbf8c90a2ef2cf_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78cc9e48-a4a4-45c5-9583-27d638876c38', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the purpose of ''advertise-inactive'' in Junos BGP configuration (variant 66).', '[{"id": "A", "text": "Advertises BGP routes to the forwarding table only", "is_correct": false}, {"id": "B", "text": "Permanently deactivates BGP advertisement", "is_correct": false}, {"id": "C", "text": "Forces BGP to advertise only active routes", "is_correct": false}, {"id": "D", "text": "Allows BGP to advertise routes that are installed in the routing table but not active (not the best route)", "is_correct": true}]', 'By default, BGP only advertises the active best route. ''advertise-inactive'' allows BGP to advertise routes that exist in the routing table but are not the selected active route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Policy', 10.0, '4307216eb9c6f079_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4bf98937-1794-4c45-a358-5ac7027eb3b4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command shows the BGP table including all path attributes for each prefix (variant 66).', '[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show route advertising-protocol bgp", "is_correct": false}, {"id": "C", "text": "show route protocol bgp detail", "is_correct": true}, {"id": "D", "text": "show bgp neighbors", "is_correct": false}]', '''show route protocol bgp detail'' displays all BGP routes with full attributes (AS_PATH, LOCAL_PREF, MED, communities) and BGP-specific information.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Troubleshooting', 10.0, 'fab124bb2916ab0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8a998e8-da40-46ce-81ac-e6b0e8610eda', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which PIM mode uses explicit join messages from receivers to build shared trees rooted at the RP (variant 66).', '[{"id": "A", "text": "PIM Source-Specific Multicast (PIM-SSM)", "is_correct": false}, {"id": "B", "text": "PIM Sparse Mode (PIM-SM)", "is_correct": true}, {"id": "C", "text": "PIM Dense Mode (PIM-DM)", "is_correct": false}, {"id": "D", "text": "PIM Bidirectional (Bidir-PIM)", "is_correct": false}]', 'PIM-SM uses explicit join messages toward the RP, building a shared tree (RP-tree/*-tree). Receivers join only when they want the multicast traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM Sparse Mode', 14.0, '737c56989242cee2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd908c20-50bb-4a90-88f5-5f3b54de1377', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the function of a PIM Bootstrap Router (BSR) (variant 66).', '[{"id": "A", "text": "Elected as the first-hop router for all multicast sources", "is_correct": false}, {"id": "B", "text": "Maintains the multicast forwarding cache", "is_correct": false}, {"id": "C", "text": "Distributes RP-set information throughout the PIM domain using periodic bootstrap messages", "is_correct": true}, {"id": "D", "text": "Converts IGMP joins to PIM joins toward the source", "is_correct": false}]', 'The BSR collects candidate-RP advertisements and distributes the RP-set to all PIM routers. Routers hash the multicast group to determine the active RP.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'PIM RP Discovery', 12.0, 'bf272d5547b3ed39_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('232c9f87-3c1f-4fb6-bacd-14d457d86494', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'How does IGMP snooping help manage multicast traffic on a switch (variant 66).', '[{"id": "A", "text": "By listening to IGMP messages between hosts and routers to constrain multicast forwarding to only interested ports", "is_correct": true}, {"id": "B", "text": "By converting IGMP to PIM at the switch level", "is_correct": false}, {"id": "C", "text": "By broadcasting all multicast traffic to all ports for reliability", "is_correct": false}, {"id": "D", "text": "By blocking all multicast traffic by default on access ports", "is_correct": false}]', 'IGMP snooping allows a Layer 2 switch to inspect IGMP membership reports and leave messages, building a forwarding table of which ports want which multicast groups.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'IGMP Snooping', 12.0, '2999fd6169ee9882_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('382274aa-c732-4b04-893a-cca53cf57625', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the default administrative distance of multicast routes in Junos when using RPF for reverse path forwarding (variant 66).', '[{"id": "A", "text": "The unicast route table is used by default for RPF check", "is_correct": true}, {"id": "B", "text": "A separate multicast RIB is maintained with its own AD", "is_correct": false}, {"id": "C", "text": "Multicast routes have an AD of 0 by default", "is_correct": false}, {"id": "D", "text": "RPF is not used in PIM-SM", "is_correct": false}]', 'PIM uses the unicast routing table for RPF checks by default. The ''multicast-routing-options'' can be configured to use a separate multicast RIB with routing-instance.', '{"https://www.juniper.net/documentation/us/en/software/junos/multicast/"}', 'Multicast RPF', 10.0, 'b3e8fed5c872cc0e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1b8f878-ecc5-4999-b296-757f681d1665', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'What is the purpose of the Spanning Tree Protocol (STP) in an Ethernet network (variant 66).', '[{"id": "A", "text": "Prevents Layer 2 loops by placing redundant links in a blocking state", "is_correct": true}, {"id": "B", "text": "Provides Layer 3 routing between VLANs", "is_correct": false}, {"id": "C", "text": "Assigns MAC addresses to switch ports", "is_correct": false}, {"id": "D", "text": "Increases the bandwidth of Ethernet links", "is_correct": false}]', 'STP creates a loop-free logical topology by placing redundant ports in blocking state. It uses BPDUs to determine the root bridge and port roles.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Fundamentals', 12.0, 'c8953ea99eceaf6a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f4681df-4a07-4df8-8ed1-f867e5234542', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which port role in Rapid Spanning Tree Protocol (RSTP) provides an alternate path to the root bridge, different from the root port (variant 66).', '[{"id": "A", "text": "Designated port", "is_correct": false}, {"id": "B", "text": "Backup port", "is_correct": false}, {"id": "C", "text": "Alternate port", "is_correct": true}, {"id": "D", "text": "Edge port", "is_correct": false}]', 'The Alternate port in RSTP provides an alternate path to the root bridge. It transitions to forwarding immediately when the root port fails, providing faster convergence than classic STP.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'RSTP', 12.0, '3f1768b5d8aa1156_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c576e68-05e3-4255-91bd-321139c0e5c9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In Multiple Spanning Tree Protocol (MSTP), what is an MST instance (MSTI) (variant 66).', '[{"id": "A", "text": "A physical link aggregation group", "is_correct": false}, {"id": "B", "text": "A logical spanning tree instance that maps to one or more VLANs, each with its own root bridge", "is_correct": true}, {"id": "C", "text": "A logical interface bundle in an IRB configuration", "is_correct": false}, {"id": "D", "text": "A single VLAN with its own STP instance", "is_correct": false}]', 'MSTP groups VLANs into MST instances. Each MSTI has its own independent spanning tree topology, root bridge, and port roles, enabling per-instance load balancing.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'MSTP', 12.0, '99621baf0104d2be_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2730dd95-4302-4156-9fb7-6f3fcae9c360', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'apply', 'Which command on a Juniper EX switch displays the STP interface status including port role and state (variant 66).', '[{"id": "A", "text": "show bridge stp", "is_correct": false}, {"id": "B", "text": "show spanning-tree interface", "is_correct": true}, {"id": "C", "text": "show ethernet-switching spanning-tree", "is_correct": false}, {"id": "D", "text": "show stp status", "is_correct": false}]', '''show spanning-tree interface'' displays each interface''s STP role (Root/Designated/Alternate/Backup), state (Forwarding/Blocking), and cost.', '{"https://www.juniper.net/documentation/us/en/software/junos/spanning-tree/"}', 'STP Operations', 10.0, 'f0df9068029b808a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edd5ae53-e762-4bdc-abfa-59d572e16c95', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is inter-AS VPN option B?', '[{"id": "A", "text": "VRF-to-VRF connections at the ASBR", "is_correct": false}, {"id": "B", "text": "A full mesh of IBGP sessions between all PEs", "is_correct": false}, {"id": "C", "text": "ASBRs exchange labeled VPN-IPv4 routes via MP-eBGP without running IGP between ASes", "is_correct": true}, {"id": "D", "text": "MPLS LDP between ASBRs", "is_correct": false}]', 'In Option B, ASBRs peer via MP-eBGP exchanging labeled VPN-IPv4 routes. The ASBR must swap both the transport and service labels.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, 'a865e203674dffd4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab70d044-6079-4b67-89e5-93cb7db0dc85', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'Which Junos feature enables seamless MPLS handoff between domains in inter-AS Option C?', '[{"id": "A", "text": "BGP labeled unicast (inet-labeled-unicast)", "is_correct": true}, {"id": "B", "text": "RSVP-TE across AS boundaries", "is_correct": false}, {"id": "C", "text": "LDP between ASBRs", "is_correct": false}, {"id": "D", "text": "Static MPLS labels", "is_correct": false}]', 'Option C uses BGP labeled unicast (family inet-labeled-unicast) to distribute loopback reachability with MPLS labels across AS boundaries.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, 'd413db85ab407134_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc1548bc-e90e-40db-bb90-ae2c039db484', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the function of ''autonomous-system lo0'' in Junos BGP configurations?', '[{"id": "A", "text": "Configures the loopback IP address for the AS", "is_correct": false}, {"id": "B", "text": "Enables BGP on the loopback interface", "is_correct": false}, {"id": "C", "text": "Allows a router to appear in a different AS for BGP purposes on the loopback interface", "is_correct": true}, {"id": "D", "text": "Sets the BGP AS number globally", "is_correct": false}]', '''autonomous-system lo0'' allows a router to use a different AS number for BGP peering. Used in AS migration scenarios and inter-AS designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'ae017af1f9c62aa7_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4380563-bbce-4e1e-8dbf-c1825b485a46', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 5, 'understand', 'Which two statements about MVPN (Multicast VPN) are correct? (Select TWO)', '[{"id": "A", "text": "PIM-SM must run in the core for all MVPN types", "is_correct": false}, {"id": "B", "text": "MVPN uses a Default-MDT and Data-MDT model", "is_correct": true}, {"id": "C", "text": "NG-MVPN uses BGP for auto-discovery", "is_correct": true}, {"id": "D", "text": "MVPN is not supported in Junos", "is_correct": false}]', 'MVPN uses Default-MDT for control traffic and Data-MDT for data traffic. NG-MVPN (RFC 6513/6514) uses BGP for auto-discovery.', '{"https://www.juniper.net/documentation/us/en/software/junos/mvpn/"}', 'MVPN', 14.0, 'b4efba4a08b03dc0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79461311-1486-41d7-9b0d-6a1153f64a65', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'In Segment Routing, what is the function of the ''adjacency SID''?', '[{"id": "A", "text": "Identifies the node itself", "is_correct": false}, {"id": "B", "text": "Represents a prefix in the IGP", "is_correct": false}, {"id": "C", "text": "Identifies a specific adjacency on a node, forcing traffic through that link", "is_correct": true}, {"id": "D", "text": "Carries MPLS EXP bits", "is_correct": false}]', 'Adjacency SID identifies a specific link/adjacency. Traffic steered through an adjacency SID must traverse that specific link, enabling strict path control.', '{"https://www.juniper.net/documentation/us/en/software/junos/segment-routing/"}', 'Segment Routing', 14.0, '699e4ec9868cbae1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5775aec1-fd0c-4b6b-8bac-a453758f90ea', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is inter-AS VPN option A?', '[{"id": "A", "text": "MP-eBGP between ASBRs with labeled VPNv4 routes", "is_correct": false}, {"id": "B", "text": "VRF-to-VRF connections at the ASBR using separate physical/logical interfaces", "is_correct": true}, {"id": "C", "text": "BGP labeled unicast across ASes", "is_correct": false}, {"id": "D", "text": "LDP session between ASBRs", "is_correct": false}]', 'Option A (VRF-to-VRF) uses an ASBR as a VRF-to-VRF gateway. Each ASBR is a PE for its VPN, connected via sub-interfaces. This approach does not scale well.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, 'b4830ed79bbfb330_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b193827-ce28-445e-9c5e-1e2fa7074c21', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the purpose of BGP add-path feature in Junos?', '[{"id": "A", "text": "Enables BGP multipath for load balancing", "is_correct": false}, {"id": "B", "text": "Adds a new BGP path to the routing table", "is_correct": false}, {"id": "C", "text": "Allows advertising multiple paths for the same prefix to BGP peers", "is_correct": true}, {"id": "D", "text": "Increases the maximum number of BGP prefixes", "is_correct": false}]', 'BGP add-path enables a router to advertise multiple paths for the same prefix, providing fast convergence and better load balancing in redundant topologies.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 14.0, '9bc563e4d1403487_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df1c91a5-8e08-4e9a-8b6d-07e93100c77b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is inter-AS VPN option B (variant 2).', '[{"id": "A", "text": "VRF-to-VRF connections at the ASBR", "is_correct": false}, {"id": "B", "text": "A full mesh of IBGP sessions between all PEs", "is_correct": false}, {"id": "C", "text": "ASBRs exchange labeled VPN-IPv4 routes via MP-eBGP without running IGP between ASes", "is_correct": true}, {"id": "D", "text": "MPLS LDP between ASBRs", "is_correct": false}]', 'In Option B, ASBRs peer via MP-eBGP exchanging labeled VPN-IPv4 routes. The ASBR must swap both the transport and service labels.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, 'be59745d691ad25a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb971310-99aa-473e-8ccb-620e103f28d2', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'Which Junos feature enables seamless MPLS handoff between domains in inter-AS Option C (variant 2).', '[{"id": "A", "text": "BGP labeled unicast (inet-labeled-unicast)", "is_correct": true}, {"id": "B", "text": "Static MPLS labels", "is_correct": false}, {"id": "C", "text": "LDP between ASBRs", "is_correct": false}, {"id": "D", "text": "RSVP-TE across AS boundaries", "is_correct": false}]', 'Option C uses BGP labeled unicast (family inet-labeled-unicast) to distribute loopback reachability with MPLS labels across AS boundaries.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, '9d2cb2460698f5f6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0046bdac-2735-4075-9dbd-ad4d11887707', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the function of ''autonomous-system lo0'' in Junos BGP configurations (variant 2).', '[{"id": "A", "text": "Enables BGP on the loopback interface", "is_correct": false}, {"id": "B", "text": "Allows a router to appear in a different AS for BGP purposes on the loopback interface", "is_correct": true}, {"id": "C", "text": "Sets the BGP AS number globally", "is_correct": false}, {"id": "D", "text": "Configures the loopback IP address for the AS", "is_correct": false}]', '''autonomous-system lo0'' allows a router to use a different AS number for BGP peering. Used in AS migration scenarios and inter-AS designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '512d75f9f72e650e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
