INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4942aec4-6d6a-43d8-8e07-caad07a8f69e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 5, 'understand', 'Which two statements about MVPN (Multicast VPN) are correct? (Select TWO) (variant 6).', '[{"id": "A", "text": "NG-MVPN uses BGP for auto-discovery", "is_correct": true}, {"id": "B", "text": "MVPN uses a Default-MDT and Data-MDT model", "is_correct": true}, {"id": "C", "text": "PIM-SM must run in the core for all MVPN types", "is_correct": false}, {"id": "D", "text": "MVPN is not supported in Junos", "is_correct": false}]', 'MVPN uses Default-MDT for control traffic and Data-MDT for data traffic. NG-MVPN (RFC 6513/6514) uses BGP for auto-discovery.', '{"https://www.juniper.net/documentation/us/en/software/junos/mvpn/"}', 'MVPN', 14.0, 'dfbeea46c3602ca2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fcd90a3-ddbf-4ae4-94db-a42dfc1ccf1d', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'In Segment Routing, what is the function of the ''adjacency SID'' (variant 6).', '[{"id": "A", "text": "Identifies the node itself", "is_correct": false}, {"id": "B", "text": "Identifies a specific adjacency on a node, forcing traffic through that link", "is_correct": true}, {"id": "C", "text": "Carries MPLS EXP bits", "is_correct": false}, {"id": "D", "text": "Represents a prefix in the IGP", "is_correct": false}]', 'Adjacency SID identifies a specific link/adjacency. Traffic steered through an adjacency SID must traverse that specific link, enabling strict path control.', '{"https://www.juniper.net/documentation/us/en/software/junos/segment-routing/"}', 'Segment Routing', 14.0, 'f3e8c9b0552979aa_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0993224e-325c-40cc-b959-1dcb7a7c0f4f', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is inter-AS VPN option A (variant 6).', '[{"id": "A", "text": "VRF-to-VRF connections at the ASBR using separate physical/logical interfaces", "is_correct": true}, {"id": "B", "text": "BGP labeled unicast across ASes", "is_correct": false}, {"id": "C", "text": "LDP session between ASBRs", "is_correct": false}, {"id": "D", "text": "MP-eBGP between ASBRs with labeled VPNv4 routes", "is_correct": false}]', 'Option A (VRF-to-VRF) uses an ASBR as a VRF-to-VRF gateway. Each ASBR is a PE for its VPN, connected via sub-interfaces. This approach does not scale well.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, 'efbde4bf888a5a42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d26f67cc-fa5d-407c-944c-3eec08a1b15b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the purpose of BGP add-path feature in Junos (variant 6).', '[{"id": "A", "text": "Allows advertising multiple paths for the same prefix to BGP peers", "is_correct": true}, {"id": "B", "text": "Increases the maximum number of BGP prefixes", "is_correct": false}, {"id": "C", "text": "Enables BGP multipath for load balancing", "is_correct": false}, {"id": "D", "text": "Adds a new BGP path to the routing table", "is_correct": false}]', 'BGP add-path enables a router to advertise multiple paths for the same prefix, providing fast convergence and better load balancing in redundant topologies.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 14.0, '6c8456ea0e9e8e15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db59d96c-87d4-46b7-b6fc-fc16fbaea1a3', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is inter-AS VPN option B (variant 7).', '[{"id": "A", "text": "A full mesh of IBGP sessions between all PEs", "is_correct": false}, {"id": "B", "text": "MPLS LDP between ASBRs", "is_correct": false}, {"id": "C", "text": "ASBRs exchange labeled VPN-IPv4 routes via MP-eBGP without running IGP between ASes", "is_correct": true}, {"id": "D", "text": "VRF-to-VRF connections at the ASBR", "is_correct": false}]', 'In Option B, ASBRs peer via MP-eBGP exchanging labeled VPN-IPv4 routes. The ASBR must swap both the transport and service labels.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, '3eb7b6b6d484e2d9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('156b0c68-e4a6-49c4-8dec-ed893b6f11e4', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'Which Junos feature enables seamless MPLS handoff between domains in inter-AS Option C (variant 7).', '[{"id": "A", "text": "LDP between ASBRs", "is_correct": false}, {"id": "B", "text": "Static MPLS labels", "is_correct": false}, {"id": "C", "text": "RSVP-TE across AS boundaries", "is_correct": false}, {"id": "D", "text": "BGP labeled unicast (inet-labeled-unicast)", "is_correct": true}]', 'Option C uses BGP labeled unicast (family inet-labeled-unicast) to distribute loopback reachability with MPLS labels across AS boundaries.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, '70af7f9000fbf56e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97293e26-be8d-4cbd-8c8d-6cc44023d81f', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the function of ''autonomous-system lo0'' in Junos BGP configurations (variant 7).', '[{"id": "A", "text": "Enables BGP on the loopback interface", "is_correct": false}, {"id": "B", "text": "Sets the BGP AS number globally", "is_correct": false}, {"id": "C", "text": "Configures the loopback IP address for the AS", "is_correct": false}, {"id": "D", "text": "Allows a router to appear in a different AS for BGP purposes on the loopback interface", "is_correct": true}]', '''autonomous-system lo0'' allows a router to use a different AS number for BGP peering. Used in AS migration scenarios and inter-AS designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '50bacb1469a095b8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
