INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9cc26bf0-3521-4a50-9973-fca8a84a0a65', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is inter-AS VPN option B (variant 15).', '[{"id": "A", "text": "MPLS LDP between ASBRs", "is_correct": false}, {"id": "B", "text": "VRF-to-VRF connections at the ASBR", "is_correct": false}, {"id": "C", "text": "ASBRs exchange labeled VPN-IPv4 routes via MP-eBGP without running IGP between ASes", "is_correct": true}, {"id": "D", "text": "A full mesh of IBGP sessions between all PEs", "is_correct": false}]', 'In Option B, ASBRs peer via MP-eBGP exchanging labeled VPN-IPv4 routes. The ASBR must swap both the transport and service labels.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, 'bb5002f6dbf4db42_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9179c766-dcc1-4a77-8d51-0f02c6b5b644', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'Which Junos feature enables seamless MPLS handoff between domains in inter-AS Option C (variant 15).', '[{"id": "A", "text": "RSVP-TE across AS boundaries", "is_correct": false}, {"id": "B", "text": "Static MPLS labels", "is_correct": false}, {"id": "C", "text": "LDP between ASBRs", "is_correct": false}, {"id": "D", "text": "BGP labeled unicast (inet-labeled-unicast)", "is_correct": true}]', 'Option C uses BGP labeled unicast (family inet-labeled-unicast) to distribute loopback reachability with MPLS labels across AS boundaries.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, 'b5c9809ade41cef1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c15b9797-f9da-40eb-9285-021e66e701b5', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the function of ''autonomous-system lo0'' in Junos BGP configurations (variant 15).', '[{"id": "A", "text": "Allows a router to appear in a different AS for BGP purposes on the loopback interface", "is_correct": true}, {"id": "B", "text": "Configures the loopback IP address for the AS", "is_correct": false}, {"id": "C", "text": "Sets the BGP AS number globally", "is_correct": false}, {"id": "D", "text": "Enables BGP on the loopback interface", "is_correct": false}]', '''autonomous-system lo0'' allows a router to use a different AS number for BGP peering. Used in AS migration scenarios and inter-AS designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '0c6c1fad5c372c80_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d16ef3da-f73c-493c-969a-650a11a4c4ac', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 5, 'understand', 'Which two statements about MVPN (Multicast VPN) are correct? (Select TWO) (variant 15).', '[{"id": "A", "text": "MVPN uses a Default-MDT and Data-MDT model", "is_correct": true}, {"id": "B", "text": "PIM-SM must run in the core for all MVPN types", "is_correct": false}, {"id": "C", "text": "MVPN is not supported in Junos", "is_correct": false}, {"id": "D", "text": "NG-MVPN uses BGP for auto-discovery", "is_correct": true}]', 'MVPN uses Default-MDT for control traffic and Data-MDT for data traffic. NG-MVPN (RFC 6513/6514) uses BGP for auto-discovery.', '{"https://www.juniper.net/documentation/us/en/software/junos/mvpn/"}', 'MVPN', 14.0, 'e598b618ad0b48f2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11f90c08-1ae1-40c7-980e-c1e8d11e850b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'In Segment Routing, what is the function of the ''adjacency SID'' (variant 15).', '[{"id": "A", "text": "Represents a prefix in the IGP", "is_correct": false}, {"id": "B", "text": "Carries MPLS EXP bits", "is_correct": false}, {"id": "C", "text": "Identifies a specific adjacency on a node, forcing traffic through that link", "is_correct": true}, {"id": "D", "text": "Identifies the node itself", "is_correct": false}]', 'Adjacency SID identifies a specific link/adjacency. Traffic steered through an adjacency SID must traverse that specific link, enabling strict path control.', '{"https://www.juniper.net/documentation/us/en/software/junos/segment-routing/"}', 'Segment Routing', 14.0, '0c23b61dcb6d4ff9_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('812058c5-307e-4089-b492-83e16a1046ca', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is inter-AS VPN option A (variant 15).', '[{"id": "A", "text": "VRF-to-VRF connections at the ASBR using separate physical/logical interfaces", "is_correct": true}, {"id": "B", "text": "LDP session between ASBRs", "is_correct": false}, {"id": "C", "text": "BGP labeled unicast across ASes", "is_correct": false}, {"id": "D", "text": "MP-eBGP between ASBRs with labeled VPNv4 routes", "is_correct": false}]', 'Option A (VRF-to-VRF) uses an ASBR as a VRF-to-VRF gateway. Each ASBR is a PE for its VPN, connected via sub-interfaces. This approach does not scale well.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, '813480480c4d3322_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('edb0db26-08e9-4c84-abfe-3aaa8d2d5cf5', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the purpose of BGP add-path feature in Junos (variant 15).', '[{"id": "A", "text": "Adds a new BGP path to the routing table", "is_correct": false}, {"id": "B", "text": "Enables BGP multipath for load balancing", "is_correct": false}, {"id": "C", "text": "Allows advertising multiple paths for the same prefix to BGP peers", "is_correct": true}, {"id": "D", "text": "Increases the maximum number of BGP prefixes", "is_correct": false}]', 'BGP add-path enables a router to advertise multiple paths for the same prefix, providing fast convergence and better load balancing in redundant topologies.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 14.0, 'f7e6643d1390b652_gen_v4', true) ON CONFLICT (id) DO NOTHING;
