INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d406aa10-0726-40cd-bcb3-932ccf87183a', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the function of ''autonomous-system lo0'' in Junos BGP configurations (variant 32).', '[{"id": "A", "text": "Configures the loopback IP address for the AS", "is_correct": false}, {"id": "B", "text": "Enables BGP on the loopback interface", "is_correct": false}, {"id": "C", "text": "Allows a router to appear in a different AS for BGP purposes on the loopback interface", "is_correct": true}, {"id": "D", "text": "Sets the BGP AS number globally", "is_correct": false}]', '''autonomous-system lo0'' allows a router to use a different AS number for BGP peering. Used in AS migration scenarios and inter-AS designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '1efe35c9d99d5426_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('424a716b-45c9-4fbc-8b69-ba6c7c672e16', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 5, 'understand', 'Which two statements about MVPN (Multicast VPN) are correct? (Select TWO) (variant 32).', '[{"id": "A", "text": "MVPN is not supported in Junos", "is_correct": false}, {"id": "B", "text": "MVPN uses a Default-MDT and Data-MDT model", "is_correct": true}, {"id": "C", "text": "NG-MVPN uses BGP for auto-discovery", "is_correct": true}, {"id": "D", "text": "PIM-SM must run in the core for all MVPN types", "is_correct": false}]', 'MVPN uses Default-MDT for control traffic and Data-MDT for data traffic. NG-MVPN (RFC 6513/6514) uses BGP for auto-discovery.', '{"https://www.juniper.net/documentation/us/en/software/junos/mvpn/"}', 'MVPN', 14.0, '2cb235925ae618cc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('532daccf-b4bc-457d-bea2-af77f89a2c3c', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'In Segment Routing, what is the function of the ''adjacency SID'' (variant 32).', '[{"id": "A", "text": "Carries MPLS EXP bits", "is_correct": false}, {"id": "B", "text": "Identifies a specific adjacency on a node, forcing traffic through that link", "is_correct": true}, {"id": "C", "text": "Identifies the node itself", "is_correct": false}, {"id": "D", "text": "Represents a prefix in the IGP", "is_correct": false}]', 'Adjacency SID identifies a specific link/adjacency. Traffic steered through an adjacency SID must traverse that specific link, enabling strict path control.', '{"https://www.juniper.net/documentation/us/en/software/junos/segment-routing/"}', 'Segment Routing', 14.0, 'a9248b7415235751_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('137b9640-436b-4a20-9140-c1a3a71595fe', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is inter-AS VPN option A (variant 32).', '[{"id": "A", "text": "VRF-to-VRF connections at the ASBR using separate physical/logical interfaces", "is_correct": true}, {"id": "B", "text": "MP-eBGP between ASBRs with labeled VPNv4 routes", "is_correct": false}, {"id": "C", "text": "BGP labeled unicast across ASes", "is_correct": false}, {"id": "D", "text": "LDP session between ASBRs", "is_correct": false}]', 'Option A (VRF-to-VRF) uses an ASBR as a VRF-to-VRF gateway. Each ASBR is a PE for its VPN, connected via sub-interfaces. This approach does not scale well.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, '7ce76a6e1993ca47_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95983c32-14e7-454a-84c5-fbda5d0f6ebf', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the purpose of BGP add-path feature in Junos (variant 32).', '[{"id": "A", "text": "Adds a new BGP path to the routing table", "is_correct": false}, {"id": "B", "text": "Allows advertising multiple paths for the same prefix to BGP peers", "is_correct": true}, {"id": "C", "text": "Enables BGP multipath for load balancing", "is_correct": false}, {"id": "D", "text": "Increases the maximum number of BGP prefixes", "is_correct": false}]', 'BGP add-path enables a router to advertise multiple paths for the same prefix, providing fast convergence and better load balancing in redundant topologies.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 14.0, '6133a9a283973f91_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6aa117b2-7be5-4fc5-a2d8-6535e5fed8ba', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is inter-AS VPN option B (variant 33).', '[{"id": "A", "text": "A full mesh of IBGP sessions between all PEs", "is_correct": false}, {"id": "B", "text": "VRF-to-VRF connections at the ASBR", "is_correct": false}, {"id": "C", "text": "MPLS LDP between ASBRs", "is_correct": false}, {"id": "D", "text": "ASBRs exchange labeled VPN-IPv4 routes via MP-eBGP without running IGP between ASes", "is_correct": true}]', 'In Option B, ASBRs peer via MP-eBGP exchanging labeled VPN-IPv4 routes. The ASBR must swap both the transport and service labels.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, '1cb832654d70be26_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8e30d3e4-560f-43c8-96d0-237a5f4d0d11', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'Which Junos feature enables seamless MPLS handoff between domains in inter-AS Option C (variant 33).', '[{"id": "A", "text": "BGP labeled unicast (inet-labeled-unicast)", "is_correct": true}, {"id": "B", "text": "RSVP-TE across AS boundaries", "is_correct": false}, {"id": "C", "text": "Static MPLS labels", "is_correct": false}, {"id": "D", "text": "LDP between ASBRs", "is_correct": false}]', 'Option C uses BGP labeled unicast (family inet-labeled-unicast) to distribute loopback reachability with MPLS labels across AS boundaries.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, '5c8390cf8242a55e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('599bea40-8d5d-412b-959b-53c72917a9ed', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the function of ''autonomous-system lo0'' in Junos BGP configurations (variant 33).', '[{"id": "A", "text": "Enables BGP on the loopback interface", "is_correct": false}, {"id": "B", "text": "Sets the BGP AS number globally", "is_correct": false}, {"id": "C", "text": "Allows a router to appear in a different AS for BGP purposes on the loopback interface", "is_correct": true}, {"id": "D", "text": "Configures the loopback IP address for the AS", "is_correct": false}]', '''autonomous-system lo0'' allows a router to use a different AS number for BGP peering. Used in AS migration scenarios and inter-AS designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, 'b768e7aada359938_gen_v4', true) ON CONFLICT (id) DO NOTHING;
