INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f196770e-ce3f-4834-95c5-022095966c9c', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'Which Junos feature enables seamless MPLS handoff between domains in inter-AS Option C (variant 72).', '[{"id": "A", "text": "LDP between ASBRs", "is_correct": false}, {"id": "B", "text": "BGP labeled unicast (inet-labeled-unicast)", "is_correct": true}, {"id": "C", "text": "Static MPLS labels", "is_correct": false}, {"id": "D", "text": "RSVP-TE across AS boundaries", "is_correct": false}]', 'Option C uses BGP labeled unicast (family inet-labeled-unicast) to distribute loopback reachability with MPLS labels across AS boundaries.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, 'ce03f57bf7e25b50_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30ec3b56-b0fd-410f-9398-915e13f28654', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the function of ''autonomous-system lo0'' in Junos BGP configurations (variant 72).', '[{"id": "A", "text": "Sets the BGP AS number globally", "is_correct": false}, {"id": "B", "text": "Allows a router to appear in a different AS for BGP purposes on the loopback interface", "is_correct": true}, {"id": "C", "text": "Configures the loopback IP address for the AS", "is_correct": false}, {"id": "D", "text": "Enables BGP on the loopback interface", "is_correct": false}]', '''autonomous-system lo0'' allows a router to use a different AS number for BGP peering. Used in AS migration scenarios and inter-AS designs.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 12.0, '8a4525b38e1161ce_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a78086e-977a-4225-a97b-a8a59aab9b38', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 5, 'understand', 'Which two statements about MVPN (Multicast VPN) are correct? (Select TWO) (variant 72).', '[{"id": "A", "text": "NG-MVPN uses BGP for auto-discovery", "is_correct": true}, {"id": "B", "text": "PIM-SM must run in the core for all MVPN types", "is_correct": false}, {"id": "C", "text": "MVPN is not supported in Junos", "is_correct": false}, {"id": "D", "text": "MVPN uses a Default-MDT and Data-MDT model", "is_correct": true}]', 'MVPN uses Default-MDT for control traffic and Data-MDT for data traffic. NG-MVPN (RFC 6513/6514) uses BGP for auto-discovery.', '{"https://www.juniper.net/documentation/us/en/software/junos/mvpn/"}', 'MVPN', 14.0, 'ea8ef3f19e82db25_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca074b7d-7913-49e7-9e61-48d2c454ec02', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'In Segment Routing, what is the function of the ''adjacency SID'' (variant 72).', '[{"id": "A", "text": "Identifies the node itself", "is_correct": false}, {"id": "B", "text": "Identifies a specific adjacency on a node, forcing traffic through that link", "is_correct": true}, {"id": "C", "text": "Represents a prefix in the IGP", "is_correct": false}, {"id": "D", "text": "Carries MPLS EXP bits", "is_correct": false}]', 'Adjacency SID identifies a specific link/adjacency. Traffic steered through an adjacency SID must traverse that specific link, enabling strict path control.', '{"https://www.juniper.net/documentation/us/en/software/junos/segment-routing/"}', 'Segment Routing', 14.0, 'a777e229eb39c3e8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07e68db9-dfea-4583-8973-1cbc76cf66a8', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is inter-AS VPN option A (variant 72).', '[{"id": "A", "text": "BGP labeled unicast across ASes", "is_correct": false}, {"id": "B", "text": "MP-eBGP between ASBRs with labeled VPNv4 routes", "is_correct": false}, {"id": "C", "text": "VRF-to-VRF connections at the ASBR using separate physical/logical interfaces", "is_correct": true}, {"id": "D", "text": "LDP session between ASBRs", "is_correct": false}]', 'Option A (VRF-to-VRF) uses an ASBR as a VRF-to-VRF gateway. Each ASBR is a PE for its VPN, connected via sub-interfaces. This approach does not scale well.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, '59fe0d4f65a892b6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1dba16de-500f-4df4-855b-deacfa0b270e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is the purpose of BGP add-path feature in Junos (variant 72).', '[{"id": "A", "text": "Enables BGP multipath for load balancing", "is_correct": false}, {"id": "B", "text": "Allows advertising multiple paths for the same prefix to BGP peers", "is_correct": true}, {"id": "C", "text": "Increases the maximum number of BGP prefixes", "is_correct": false}, {"id": "D", "text": "Adds a new BGP path to the routing table", "is_correct": false}]', 'BGP add-path enables a router to advertise multiple paths for the same prefix, providing fast convergence and better load balancing in redundant topologies.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Advanced', 14.0, 'a9b519cce40107dc_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d51339bc-3535-4c98-b33b-768c3aaa1d79', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 5, 'understand', 'What is inter-AS VPN option B (variant 73).', '[{"id": "A", "text": "MPLS LDP between ASBRs", "is_correct": false}, {"id": "B", "text": "A full mesh of IBGP sessions between all PEs", "is_correct": false}, {"id": "C", "text": "VRF-to-VRF connections at the ASBR", "is_correct": false}, {"id": "D", "text": "ASBRs exchange labeled VPN-IPv4 routes via MP-eBGP without running IGP between ASes", "is_correct": true}]', 'In Option B, ASBRs peer via MP-eBGP exchanging labeled VPN-IPv4 routes. The ASBR must swap both the transport and service labels.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Inter-AS VPN', 14.0, '59f5ef07f75ce920_gen_v4', true) ON CONFLICT (id) DO NOTHING;
