INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e04f94e6-3791-49e6-8397-5cb7e9278952', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of SRX chassis clustering (variant 31).', '[{"id": "A", "text": "Multiple virtual SRX instances on one chassis", "is_correct": false}, {"id": "B", "text": "Two SRX devices operate as a single cluster for high availability", "is_correct": true}, {"id": "C", "text": "Load balancing between two independent firewalls", "is_correct": false}, {"id": "D", "text": "Aggregation of physical interfaces", "is_correct": false}]', 'Chassis clustering enables two physical SRX devices to act as one HA pair with synchronized sessions, configurations, and stateful failover.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, 'ec12a9a75c65b172_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b88a452a-0a68-4ab0-a619-a26c49846e8b', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'multiple-choice', 4, 'understand', 'Which two interfaces are required for SRX chassis cluster operation? (Select TWO) (variant 31).', '[{"id": "A", "text": "A dedicated spanning-tree interface", "is_correct": false}, {"id": "B", "text": "Fabric link for session replication", "is_correct": true}, {"id": "C", "text": "Control link (fab0/fab1) for IPC", "is_correct": true}, {"id": "D", "text": "Out-of-band management interface", "is_correct": false}]', 'The control link (fab0) handles control plane IPC. The fabric link (fab1) handles session replication and data plane state synchronization.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, 'c1eafaea2c4abd34_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee8585ae-71de-420c-bd31-7dd3d0704e05', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'What is ''logical systems'' on SRX (variant 31).', '[{"id": "A", "text": "Logical grouping of security policies", "is_correct": false}, {"id": "B", "text": "Partitioning a single SRX into multiple virtual firewalls", "is_correct": true}, {"id": "C", "text": "A logging subsystem on SRX", "is_correct": false}, {"id": "D", "text": "VLAN segmentation for management traffic", "is_correct": false}]', 'Logical Systems (LSYS) partition a single physical SRX into multiple virtual security devices, each with its own routing table, security policies, and administration.', '{"https://www.juniper.net/documentation/us/en/software/junos/logical-systems/"}', 'Logical Systems', 14.0, '7964e57c29d6ac4b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ab7ed9c-4734-4832-abec-fef6e7d24722', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the function of ''Security Intelligence'' (SecIntel) on SRX (variant 31).', '[{"id": "A", "text": "Feeds threat intelligence data from Juniper ATP Cloud to block malicious IPs/URLs", "is_correct": true}, {"id": "B", "text": "A local database of known malware signatures", "is_correct": false}, {"id": "C", "text": "Geo-IP based blocking", "is_correct": false}, {"id": "D", "text": "Encrypted traffic analysis using machine learning", "is_correct": false}]', 'SecIntel feeds real-time threat intelligence from Juniper ATP Cloud. It can block connections to known malicious IPs, URLs, and domains.', '{"https://www.juniper.net/documentation/us/en/software/junos/secintel/"}', 'Advanced Threat Prevention', 14.0, 'c9d41edb1725e096_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e685168-5641-4ee0-b53b-29b8de1ba702', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'Which routing mode is NOT supported on SRX devices (variant 31).', '[{"id": "A", "text": "All of the above are supported", "is_correct": true}, {"id": "B", "text": "NPB (Network Packet Broker) mode", "is_correct": false}, {"id": "C", "text": "Transparent mode (Layer 2)", "is_correct": false}, {"id": "D", "text": "Route mode (Layer 3)", "is_correct": false}]', 'SRX supports route mode (L3), transparent mode (L2), and NPB mode. Each mode determines how the SRX processes and forwards traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-modes/"}', 'SRX Modes', 12.0, 'c202230e884a9d9f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
