INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a85ebdee-01fe-43b0-83b4-c851cc9abf6f', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of SRX chassis clustering (variant 40).', '[{"id": "A", "text": "Aggregation of physical interfaces", "is_correct": false}, {"id": "B", "text": "Load balancing between two independent firewalls", "is_correct": false}, {"id": "C", "text": "Two SRX devices operate as a single cluster for high availability", "is_correct": true}, {"id": "D", "text": "Multiple virtual SRX instances on one chassis", "is_correct": false}]', 'Chassis clustering enables two physical SRX devices to act as one HA pair with synchronized sessions, configurations, and stateful failover.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, '8dc7b6ef61f97ca2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e81d29d4-510b-405d-ae10-1035fb85bb98', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'multiple-choice', 4, 'understand', 'Which two interfaces are required for SRX chassis cluster operation? (Select TWO) (variant 40).', '[{"id": "A", "text": "Out-of-band management interface", "is_correct": false}, {"id": "B", "text": "Control link (fab0/fab1) for IPC", "is_correct": true}, {"id": "C", "text": "Fabric link for session replication", "is_correct": true}, {"id": "D", "text": "A dedicated spanning-tree interface", "is_correct": false}]', 'The control link (fab0) handles control plane IPC. The fabric link (fab1) handles session replication and data plane state synchronization.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, '0874449b5aa2eb89_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('918c94a1-78ca-421a-af52-e61338d06a9c', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'What is ''logical systems'' on SRX (variant 40).', '[{"id": "A", "text": "Partitioning a single SRX into multiple virtual firewalls", "is_correct": true}, {"id": "B", "text": "A logging subsystem on SRX", "is_correct": false}, {"id": "C", "text": "Logical grouping of security policies", "is_correct": false}, {"id": "D", "text": "VLAN segmentation for management traffic", "is_correct": false}]', 'Logical Systems (LSYS) partition a single physical SRX into multiple virtual security devices, each with its own routing table, security policies, and administration.', '{"https://www.juniper.net/documentation/us/en/software/junos/logical-systems/"}', 'Logical Systems', 14.0, 'da2f8229e1cdc3da_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9f7e34d-2c27-4e9f-b1fe-cb5f5e065293', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the function of ''Security Intelligence'' (SecIntel) on SRX (variant 40).', '[{"id": "A", "text": "Encrypted traffic analysis using machine learning", "is_correct": false}, {"id": "B", "text": "Geo-IP based blocking", "is_correct": false}, {"id": "C", "text": "A local database of known malware signatures", "is_correct": false}, {"id": "D", "text": "Feeds threat intelligence data from Juniper ATP Cloud to block malicious IPs/URLs", "is_correct": true}]', 'SecIntel feeds real-time threat intelligence from Juniper ATP Cloud. It can block connections to known malicious IPs, URLs, and domains.', '{"https://www.juniper.net/documentation/us/en/software/junos/secintel/"}', 'Advanced Threat Prevention', 14.0, '052078759a2b7179_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8485b5fe-17a1-4520-8f48-85cdce38f5cc', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'Which routing mode is NOT supported on SRX devices (variant 40).', '[{"id": "A", "text": "Transparent mode (Layer 2)", "is_correct": false}, {"id": "B", "text": "NPB (Network Packet Broker) mode", "is_correct": false}, {"id": "C", "text": "All of the above are supported", "is_correct": true}, {"id": "D", "text": "Route mode (Layer 3)", "is_correct": false}]', 'SRX supports route mode (L3), transparent mode (L2), and NPB mode. Each mode determines how the SRX processes and forwards traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-modes/"}', 'SRX Modes', 12.0, 'fb5fc51897444746_gen_v4', true) ON CONFLICT (id) DO NOTHING;
