INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b69ce698-3f82-442a-8ff9-a0b48c89a507', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of SRX chassis clustering (variant 67).', '[{"id": "A", "text": "Load balancing between two independent firewalls", "is_correct": false}, {"id": "B", "text": "Two SRX devices operate as a single cluster for high availability", "is_correct": true}, {"id": "C", "text": "Multiple virtual SRX instances on one chassis", "is_correct": false}, {"id": "D", "text": "Aggregation of physical interfaces", "is_correct": false}]', 'Chassis clustering enables two physical SRX devices to act as one HA pair with synchronized sessions, configurations, and stateful failover.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, '7a8be120e683e6eb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ea9b540-d1d4-42e7-9c26-bc34e09f4c56', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'multiple-choice', 4, 'understand', 'Which two interfaces are required for SRX chassis cluster operation? (Select TWO) (variant 67).', '[{"id": "A", "text": "Fabric link for session replication", "is_correct": true}, {"id": "B", "text": "A dedicated spanning-tree interface", "is_correct": false}, {"id": "C", "text": "Out-of-band management interface", "is_correct": false}, {"id": "D", "text": "Control link (fab0/fab1) for IPC", "is_correct": true}]', 'The control link (fab0) handles control plane IPC. The fabric link (fab1) handles session replication and data plane state synchronization.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, 'c2d868b8aa9e2ef4_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93101a05-88a7-4bd1-b98c-58c468573113', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'What is ''logical systems'' on SRX (variant 67).', '[{"id": "A", "text": "A logging subsystem on SRX", "is_correct": false}, {"id": "B", "text": "Partitioning a single SRX into multiple virtual firewalls", "is_correct": true}, {"id": "C", "text": "VLAN segmentation for management traffic", "is_correct": false}, {"id": "D", "text": "Logical grouping of security policies", "is_correct": false}]', 'Logical Systems (LSYS) partition a single physical SRX into multiple virtual security devices, each with its own routing table, security policies, and administration.', '{"https://www.juniper.net/documentation/us/en/software/junos/logical-systems/"}', 'Logical Systems', 14.0, '2ab3d7e46996ae7c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('179f9387-01d3-4961-8559-7e1566a4a8b2', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the function of ''Security Intelligence'' (SecIntel) on SRX (variant 67).', '[{"id": "A", "text": "Geo-IP based blocking", "is_correct": false}, {"id": "B", "text": "Encrypted traffic analysis using machine learning", "is_correct": false}, {"id": "C", "text": "Feeds threat intelligence data from Juniper ATP Cloud to block malicious IPs/URLs", "is_correct": true}, {"id": "D", "text": "A local database of known malware signatures", "is_correct": false}]', 'SecIntel feeds real-time threat intelligence from Juniper ATP Cloud. It can block connections to known malicious IPs, URLs, and domains.', '{"https://www.juniper.net/documentation/us/en/software/junos/secintel/"}', 'Advanced Threat Prevention', 14.0, 'bbc0491f883ae018_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d1189aa-3d8b-4561-9584-4c2f7201ace4', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'Which routing mode is NOT supported on SRX devices (variant 67).', '[{"id": "A", "text": "Transparent mode (Layer 2)", "is_correct": false}, {"id": "B", "text": "All of the above are supported", "is_correct": true}, {"id": "C", "text": "Route mode (Layer 3)", "is_correct": false}, {"id": "D", "text": "NPB (Network Packet Broker) mode", "is_correct": false}]', 'SRX supports route mode (L3), transparent mode (L2), and NPB mode. Each mode determines how the SRX processes and forwards traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-modes/"}', 'SRX Modes', 12.0, 'e3d2ae4b62a8e330_gen_v4', true) ON CONFLICT (id) DO NOTHING;
