INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60fdd581-24bf-4257-be8b-3bfaf08cf999', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of SRX chassis clustering (variant 73).', '[{"id": "A", "text": "Aggregation of physical interfaces", "is_correct": false}, {"id": "B", "text": "Load balancing between two independent firewalls", "is_correct": false}, {"id": "C", "text": "Multiple virtual SRX instances on one chassis", "is_correct": false}, {"id": "D", "text": "Two SRX devices operate as a single cluster for high availability", "is_correct": true}]', 'Chassis clustering enables two physical SRX devices to act as one HA pair with synchronized sessions, configurations, and stateful failover.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, '654da895e3d72353_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d74cf50-34a8-4ed5-82a5-038f565f9ef7', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'multiple-choice', 4, 'understand', 'Which two interfaces are required for SRX chassis cluster operation? (Select TWO) (variant 73).', '[{"id": "A", "text": "Control link (fab0/fab1) for IPC", "is_correct": true}, {"id": "B", "text": "Fabric link for session replication", "is_correct": true}, {"id": "C", "text": "A dedicated spanning-tree interface", "is_correct": false}, {"id": "D", "text": "Out-of-band management interface", "is_correct": false}]', 'The control link (fab0) handles control plane IPC. The fabric link (fab1) handles session replication and data plane state synchronization.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, 'ba1599bafb61ed0f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdabecb6-2896-412a-86eb-a1e7ffe02198', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'What is ''logical systems'' on SRX (variant 73).', '[{"id": "A", "text": "Logical grouping of security policies", "is_correct": false}, {"id": "B", "text": "A logging subsystem on SRX", "is_correct": false}, {"id": "C", "text": "Partitioning a single SRX into multiple virtual firewalls", "is_correct": true}, {"id": "D", "text": "VLAN segmentation for management traffic", "is_correct": false}]', 'Logical Systems (LSYS) partition a single physical SRX into multiple virtual security devices, each with its own routing table, security policies, and administration.', '{"https://www.juniper.net/documentation/us/en/software/junos/logical-systems/"}', 'Logical Systems', 14.0, 'f2a2001f668c7686_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec097c7c-85c3-42e8-b346-1c3265ad14a5', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the function of ''Security Intelligence'' (SecIntel) on SRX (variant 73).', '[{"id": "A", "text": "Encrypted traffic analysis using machine learning", "is_correct": false}, {"id": "B", "text": "A local database of known malware signatures", "is_correct": false}, {"id": "C", "text": "Feeds threat intelligence data from Juniper ATP Cloud to block malicious IPs/URLs", "is_correct": true}, {"id": "D", "text": "Geo-IP based blocking", "is_correct": false}]', 'SecIntel feeds real-time threat intelligence from Juniper ATP Cloud. It can block connections to known malicious IPs, URLs, and domains.', '{"https://www.juniper.net/documentation/us/en/software/junos/secintel/"}', 'Advanced Threat Prevention', 14.0, 'eb71cd3f5690e75c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('062ad897-af42-4c42-86a3-2fde6679188a', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'Which routing mode is NOT supported on SRX devices (variant 73).', '[{"id": "A", "text": "All of the above are supported", "is_correct": true}, {"id": "B", "text": "Route mode (Layer 3)", "is_correct": false}, {"id": "C", "text": "Transparent mode (Layer 2)", "is_correct": false}, {"id": "D", "text": "NPB (Network Packet Broker) mode", "is_correct": false}]', 'SRX supports route mode (L3), transparent mode (L2), and NPB mode. Each mode determines how the SRX processes and forwards traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-modes/"}', 'SRX Modes', 12.0, '70f88801764116f3_gen_v4', true) ON CONFLICT (id) DO NOTHING;
