INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6938d8e5-38f3-4362-adfe-1fcfb26dc994', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'In a VXLAN-EVPN fabric, what is a ''symmetric'' IRB model (variant 6).', '[{"id": "A", "text": "Both ingress and egress VTEPs perform L3 routing with VNI translation", "is_correct": true}, {"id": "B", "text": "Only the ingress VTEP performs routing", "is_correct": false}, {"id": "C", "text": "Routing is done on a central gateway", "is_correct": false}, {"id": "D", "text": "ARP is used for inter-subnet forwarding", "is_correct": false}]', 'In symmetric IRB, both ingress and egress VTEPs route the traffic. The ingress translates L2 VNI to L3 VNI; egress translates back. Both VTEPs have the anycast gateway.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Design', 14.0, '2ab4b50d06803ce6_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f13f51d9-1a9a-4f37-bd3b-5136f49fbf1f', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN multi-homing ''all-active'' mode (variant 6).', '[{"id": "A", "text": "All traffic is duplicated to all PEs", "is_correct": false}, {"id": "B", "text": "CE is multi-homed to multiple PEs with all links active; load balancing occurs per flow", "is_correct": true}, {"id": "C", "text": "Only one PE is active; others are standby", "is_correct": false}, {"id": "D", "text": "CE connects to a single PE with redundant links", "is_correct": false}]', 'In all-active multi-homing, the CE connects to multiple PEs with all links forwarding traffic. Load balancing is per-flow based on hash of MAC/IP.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Multi-homing', 14.0, '209b63860463660e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cdaeb952-9dae-416f-8154-4c5c460d722c', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'Which Junos feature enables data center interconnect (DCI) over EVPN (variant 6).', '[{"id": "A", "text": "Static VXLAN tunnels between data centers", "is_correct": false}, {"id": "B", "text": "EVPN interconnect using Route Type 5 with VNI mapping", "is_correct": true}, {"id": "C", "text": "LDP-based MPLS between DC gateways", "is_correct": false}, {"id": "D", "text": "VPLS over GRE between DCs", "is_correct": false}]', 'DCI with EVPN uses Type 5 routes to exchange IP prefixes between data centers with different VNI mappings per site, enabling Layer 3 DCI with optimal forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'DCI', 14.0, '44bf2b7e7e2a5887_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37b4e82b-5592-449f-92ce-219c47a01209', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN Route Type 4 (Ethernet Segment Route) (variant 7).', '[{"id": "A", "text": "Signals IP prefix routes", "is_correct": false}, {"id": "B", "text": "Carries VXLAN tunnel information", "is_correct": false}, {"id": "C", "text": "Used for designated forwarder (DF) election for multi-homed segments", "is_correct": true}, {"id": "D", "text": "Advertises MAC addresses only", "is_correct": false}]', 'Route Type 4 is used for DF election in multi-homed segments. PEs advertise the same ESI; the PE with the highest IP is elected DF for each VLAN.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Advanced', 14.0, '5e1920225cb5023b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
