INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e40e8021-3778-4585-8cb9-28486dd20e06', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'In a VXLAN-EVPN fabric, what is a ''symmetric'' IRB model (variant 18).', '[{"id": "A", "text": "Only the ingress VTEP performs routing", "is_correct": false}, {"id": "B", "text": "Routing is done on a central gateway", "is_correct": false}, {"id": "C", "text": "ARP is used for inter-subnet forwarding", "is_correct": false}, {"id": "D", "text": "Both ingress and egress VTEPs perform L3 routing with VNI translation", "is_correct": true}]', 'In symmetric IRB, both ingress and egress VTEPs route the traffic. The ingress translates L2 VNI to L3 VNI; egress translates back. Both VTEPs have the anycast gateway.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Design', 14.0, '0e609911e3242755_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a734c9d-cc37-4011-a900-c72ee67bc604', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN multi-homing ''all-active'' mode (variant 18).', '[{"id": "A", "text": "Only one PE is active; others are standby", "is_correct": false}, {"id": "B", "text": "CE connects to a single PE with redundant links", "is_correct": false}, {"id": "C", "text": "CE is multi-homed to multiple PEs with all links active; load balancing occurs per flow", "is_correct": true}, {"id": "D", "text": "All traffic is duplicated to all PEs", "is_correct": false}]', 'In all-active multi-homing, the CE connects to multiple PEs with all links forwarding traffic. Load balancing is per-flow based on hash of MAC/IP.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Multi-homing', 14.0, 'a076491105847f00_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c1a085b-827b-46cb-ba10-0f52ae4a8175', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'Which Junos feature enables data center interconnect (DCI) over EVPN (variant 18).', '[{"id": "A", "text": "VPLS over GRE between DCs", "is_correct": false}, {"id": "B", "text": "EVPN interconnect using Route Type 5 with VNI mapping", "is_correct": true}, {"id": "C", "text": "Static VXLAN tunnels between data centers", "is_correct": false}, {"id": "D", "text": "LDP-based MPLS between DC gateways", "is_correct": false}]', 'DCI with EVPN uses Type 5 routes to exchange IP prefixes between data centers with different VNI mappings per site, enabling Layer 3 DCI with optimal forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'DCI', 14.0, '2d11f7aa0ac4d402_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fda259ce-ab3f-4f67-879b-c3bed65bac97', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN Route Type 4 (Ethernet Segment Route) (variant 19).', '[{"id": "A", "text": "Carries VXLAN tunnel information", "is_correct": false}, {"id": "B", "text": "Signals IP prefix routes", "is_correct": false}, {"id": "C", "text": "Used for designated forwarder (DF) election for multi-homed segments", "is_correct": true}, {"id": "D", "text": "Advertises MAC addresses only", "is_correct": false}]', 'Route Type 4 is used for DF election in multi-homed segments. PEs advertise the same ESI; the PE with the highest IP is elected DF for each VLAN.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Advanced', 14.0, 'fdc1d2c7bdb62c82_gen_v4', true) ON CONFLICT (id) DO NOTHING;
