INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c187380b-e9f1-40f8-9af9-07dddae43760', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN Route Type 4 (Ethernet Segment Route) (variant 22).', '[{"id": "A", "text": "Advertises MAC addresses only", "is_correct": false}, {"id": "B", "text": "Used for designated forwarder (DF) election for multi-homed segments", "is_correct": true}, {"id": "C", "text": "Carries VXLAN tunnel information", "is_correct": false}, {"id": "D", "text": "Signals IP prefix routes", "is_correct": false}]', 'Route Type 4 is used for DF election in multi-homed segments. PEs advertise the same ESI; the PE with the highest IP is elected DF for each VLAN.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Advanced', 14.0, '4430ed37970dcd18_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee6d257e-b482-443b-9018-0611ce2bf313', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'multiple-choice', 5, 'understand', 'Which two features are supported by EVPN Type 5 (IP Prefix Route)? (Select TWO) (variant 22).', '[{"id": "A", "text": "Inter-subnet forwarding (IP prefix advertisement across VNIs)", "is_correct": true}, {"id": "B", "text": "MAC learning", "is_correct": false}, {"id": "C", "text": "DF election", "is_correct": false}, {"id": "D", "text": "External network connectivity", "is_correct": true}]', 'Type 5 carries IP prefixes across VNIs, enabling inter-subnet forwarding without an L3 gateway per VNI. It also provides external connectivity (e.g., to WAN router).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Type 5', 14.0, 'a8afeaf3befd871a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7411cd53-bfbf-4fd4-921b-e9d7bbf792b7', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'In a VXLAN-EVPN fabric, what is a ''symmetric'' IRB model (variant 22).', '[{"id": "A", "text": "ARP is used for inter-subnet forwarding", "is_correct": false}, {"id": "B", "text": "Routing is done on a central gateway", "is_correct": false}, {"id": "C", "text": "Only the ingress VTEP performs routing", "is_correct": false}, {"id": "D", "text": "Both ingress and egress VTEPs perform L3 routing with VNI translation", "is_correct": true}]', 'In symmetric IRB, both ingress and egress VTEPs route the traffic. The ingress translates L2 VNI to L3 VNI; egress translates back. Both VTEPs have the anycast gateway.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Design', 14.0, 'ce026dbf58a0043b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3ce2c64-3d6d-489a-8e3d-143ab947bc89', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN multi-homing ''all-active'' mode (variant 22).', '[{"id": "A", "text": "All traffic is duplicated to all PEs", "is_correct": false}, {"id": "B", "text": "CE connects to a single PE with redundant links", "is_correct": false}, {"id": "C", "text": "CE is multi-homed to multiple PEs with all links active; load balancing occurs per flow", "is_correct": true}, {"id": "D", "text": "Only one PE is active; others are standby", "is_correct": false}]', 'In all-active multi-homing, the CE connects to multiple PEs with all links forwarding traffic. Load balancing is per-flow based on hash of MAC/IP.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Multi-homing', 14.0, 'ece7dbc665e0bfd8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3d521e3-820f-4fd3-84b8-726093b84787', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'Which Junos feature enables data center interconnect (DCI) over EVPN (variant 22).', '[{"id": "A", "text": "VPLS over GRE between DCs", "is_correct": false}, {"id": "B", "text": "Static VXLAN tunnels between data centers", "is_correct": false}, {"id": "C", "text": "EVPN interconnect using Route Type 5 with VNI mapping", "is_correct": true}, {"id": "D", "text": "LDP-based MPLS between DC gateways", "is_correct": false}]', 'DCI with EVPN uses Type 5 routes to exchange IP prefixes between data centers with different VNI mappings per site, enabling Layer 3 DCI with optimal forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'DCI', 14.0, 'b7aa7fb550b770d1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
