INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91a452de-eb72-429a-8605-a42d2c6bd86c', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'In a VXLAN-EVPN fabric, what is a ''symmetric'' IRB model (variant 62).', '[{"id": "A", "text": "Only the ingress VTEP performs routing", "is_correct": false}, {"id": "B", "text": "ARP is used for inter-subnet forwarding", "is_correct": false}, {"id": "C", "text": "Both ingress and egress VTEPs perform L3 routing with VNI translation", "is_correct": true}, {"id": "D", "text": "Routing is done on a central gateway", "is_correct": false}]', 'In symmetric IRB, both ingress and egress VTEPs route the traffic. The ingress translates L2 VNI to L3 VNI; egress translates back. Both VTEPs have the anycast gateway.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN Design', 14.0, '7c35e6b597f444b1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a33e92a5-d1cf-4e99-abda-934580635909', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN multi-homing ''all-active'' mode (variant 62).', '[{"id": "A", "text": "CE is multi-homed to multiple PEs with all links active; load balancing occurs per flow", "is_correct": true}, {"id": "B", "text": "Only one PE is active; others are standby", "is_correct": false}, {"id": "C", "text": "CE connects to a single PE with redundant links", "is_correct": false}, {"id": "D", "text": "All traffic is duplicated to all PEs", "is_correct": false}]', 'In all-active multi-homing, the CE connects to multiple PEs with all links forwarding traffic. Load balancing is per-flow based on hash of MAC/IP.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Multi-homing', 14.0, 'fa15b0d959bbb6ee_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6049ca8-98f9-4476-a78c-65774cabf74c', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'Which Junos feature enables data center interconnect (DCI) over EVPN (variant 62).', '[{"id": "A", "text": "EVPN interconnect using Route Type 5 with VNI mapping", "is_correct": true}, {"id": "B", "text": "LDP-based MPLS between DC gateways", "is_correct": false}, {"id": "C", "text": "Static VXLAN tunnels between data centers", "is_correct": false}, {"id": "D", "text": "VPLS over GRE between DCs", "is_correct": false}]', 'DCI with EVPN uses Type 5 routes to exchange IP prefixes between data centers with different VNI mappings per site, enabling Layer 3 DCI with optimal forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'DCI', 14.0, 'e1d23f771c2c4944_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da3248d9-6258-452b-862b-83d0399564bb', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 5, 'understand', 'What is the purpose of EVPN Route Type 4 (Ethernet Segment Route) (variant 63).', '[{"id": "A", "text": "Carries VXLAN tunnel information", "is_correct": false}, {"id": "B", "text": "Advertises MAC addresses only", "is_correct": false}, {"id": "C", "text": "Used for designated forwarder (DF) election for multi-homed segments", "is_correct": true}, {"id": "D", "text": "Signals IP prefix routes", "is_correct": false}]', 'Route Type 4 is used for DF election in multi-homed segments. PEs advertise the same ESI; the PE with the highest IP is elected DF for each VLAN.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Advanced', 14.0, 'f9b6864496aaae9c_gen_v4', true) ON CONFLICT (id) DO NOTHING;
