INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a31f5e6e-cd0f-4630-90ad-64cb3d29b349', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 5, 'apply', 'What is the recommended approach for implementing a CI/CD pipeline for Junos configuration changes (variant 7).', '[{"id": "A", "text": "Use only SNMP for configuration", "is_correct": false}, {"id": "B", "text": "Use only manual CLI changes", "is_correct": false}, {"id": "C", "text": "Validate configuration in a staging environment before production deployment", "is_correct": true}, {"id": "D", "text": "Directly push configuration to production", "is_correct": false}]', 'Best practice: validate config in staging using tools like Ansible+PyEZ, run commit-check and commit-confirm, then promote to production.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation/"}', 'Automation Pipelines', 16.0, '5052b84bc17931b5_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a578cbc8-ac42-445d-84fe-685afa26bcf5', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'In Junos telemetry (JTI), what is a ''sensor'' (variant 7).', '[{"id": "A", "text": "A physical temperature sensor on the device", "is_correct": false}, {"id": "B", "text": "A syslog collector", "is_correct": false}, {"id": "C", "text": "A SNMP trap receiver", "is_correct": false}, {"id": "D", "text": "A configuration that defines which operational data to stream and how often", "is_correct": true}]', 'A JTI sensor defines the data collection parameters: which operational data (e.g., interface statistics, routing table entries) to stream and the reporting interval.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Junos Telemetry', 14.0, '7b15d4f068da72e2_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e296507-ea37-4c70-89a7-a32203cbb689', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which tool is commonly used with gRPC for Junos telemetry collection (variant 7).', '[{"id": "A", "text": "Syslog-ng", "is_correct": false}, {"id": "B", "text": "OpenConfig telemetry", "is_correct": false}, {"id": "C", "text": "SNMP MIB walker", "is_correct": false}, {"id": "D", "text": "JTI (Junos Telemetry Interface) collector", "is_correct": true}]', 'JTI collector (or Junos Telemetry collector) receives streaming telemetry data via gRPC from Junos devices. OpenConfig also defines telemetry models.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Telemetry', 14.0, '310de1f67f8dcafb_gen_v4', true) ON CONFLICT (id) DO NOTHING;
