INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0378b3e4-aeec-4537-9a33-00ba9acc2a91', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which tool is commonly used with gRPC for Junos telemetry collection (variant 11).', '[{"id": "A", "text": "JTI (Junos Telemetry Interface) collector", "is_correct": true}, {"id": "B", "text": "OpenConfig telemetry", "is_correct": false}, {"id": "C", "text": "SNMP MIB walker", "is_correct": false}, {"id": "D", "text": "Syslog-ng", "is_correct": false}]', 'JTI collector (or Junos Telemetry collector) receives streaming telemetry data via gRPC from Junos devices. OpenConfig also defines telemetry models.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Telemetry', 14.0, 'f9f78e2b09c065ac_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54a7505a-c00c-4043-b3b8-da7f7e9d5fb7', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which Junos automation feature enables event-driven responses to system events (variant 11).', '[{"id": "A", "text": "Manual CLI monitoring", "is_correct": false}, {"id": "B", "text": "SNMP traps", "is_correct": false}, {"id": "C", "text": "CRON scheduler", "is_correct": false}, {"id": "D", "text": "Event scripts (commit/op scripts triggered by system events)", "is_correct": true}]', 'Junos event scripts are triggered by system events (interface down, BGP down, etc.) and can execute predefined automation actions to respond automatically.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation-scripts/"}', 'Event Automation', 14.0, '5bb84961a48e96f0_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77ab18b7-1c77-4a48-8107-184eb89f0097', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the purpose of ''commit confirmed'' in Junos (variant 11).', '[{"id": "A", "text": "Checks configuration syntax only", "is_correct": false}, {"id": "B", "text": "Displays the commit history", "is_correct": false}, {"id": "C", "text": "Commits the configuration permanently", "is_correct": false}, {"id": "D", "text": "Applies configuration temporarily; automatically rolls back if not confirmed within the timeout", "is_correct": true}]', '''commit confirmed <minutes>'' applies the candidate config for a test period. If not confirmed with another ''commit'' within the timeout, automatic rollback occurs.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Management', 12.0, 'c67804e0c098f080_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58c7d21f-50b1-4269-a1ab-57cf39d21f67', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 5, 'apply', 'What is the recommended approach for implementing a CI/CD pipeline for Junos configuration changes (variant 12).', '[{"id": "A", "text": "Validate configuration in a staging environment before production deployment", "is_correct": true}, {"id": "B", "text": "Use only SNMP for configuration", "is_correct": false}, {"id": "C", "text": "Use only manual CLI changes", "is_correct": false}, {"id": "D", "text": "Directly push configuration to production", "is_correct": false}]', 'Best practice: validate config in staging using tools like Ansible+PyEZ, run commit-check and commit-confirm, then promote to production.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation/"}', 'Automation Pipelines', 16.0, '81963f4776b4c6a8_gen_v4', true) ON CONFLICT (id) DO NOTHING;
