INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('635b8aef-26f4-4f51-9dc4-10c25bcf98be', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the purpose of ''commit confirmed'' in Junos (variant 15).', '[{"id": "A", "text": "Displays the commit history", "is_correct": false}, {"id": "B", "text": "Checks configuration syntax only", "is_correct": false}, {"id": "C", "text": "Applies configuration temporarily; automatically rolls back if not confirmed within the timeout", "is_correct": true}, {"id": "D", "text": "Commits the configuration permanently", "is_correct": false}]', '''commit confirmed <minutes>'' applies the candidate config for a test period. If not confirmed with another ''commit'' within the timeout, automatic rollback occurs.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Management', 12.0, 'b2c5547b240446af_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c5587e4-4266-450b-9e25-cc615177eb15', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 5, 'apply', 'What is the recommended approach for implementing a CI/CD pipeline for Junos configuration changes (variant 16).', '[{"id": "A", "text": "Use only manual CLI changes", "is_correct": false}, {"id": "B", "text": "Use only SNMP for configuration", "is_correct": false}, {"id": "C", "text": "Validate configuration in a staging environment before production deployment", "is_correct": true}, {"id": "D", "text": "Directly push configuration to production", "is_correct": false}]', 'Best practice: validate config in staging using tools like Ansible+PyEZ, run commit-check and commit-confirm, then promote to production.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation/"}', 'Automation Pipelines', 16.0, '40027a46f5d8747a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14820507-3058-4297-9bf9-c3a0b7403f51', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'In Junos telemetry (JTI), what is a ''sensor'' (variant 16).', '[{"id": "A", "text": "A physical temperature sensor on the device", "is_correct": false}, {"id": "B", "text": "A syslog collector", "is_correct": false}, {"id": "C", "text": "A configuration that defines which operational data to stream and how often", "is_correct": true}, {"id": "D", "text": "A SNMP trap receiver", "is_correct": false}]', 'A JTI sensor defines the data collection parameters: which operational data (e.g., interface statistics, routing table entries) to stream and the reporting interval.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Junos Telemetry', 14.0, '0a36dea1a6088624_gen_v4', true) ON CONFLICT (id) DO NOTHING;
