INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65b70994-1a69-44d4-acf2-6ca01bc2ddaa', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which Junos automation feature enables event-driven responses to system events (variant 24).', '[{"id": "A", "text": "Event scripts (commit/op scripts triggered by system events)", "is_correct": true}, {"id": "B", "text": "SNMP traps", "is_correct": false}, {"id": "C", "text": "CRON scheduler", "is_correct": false}, {"id": "D", "text": "Manual CLI monitoring", "is_correct": false}]', 'Junos event scripts are triggered by system events (interface down, BGP down, etc.) and can execute predefined automation actions to respond automatically.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation-scripts/"}', 'Event Automation', 14.0, '1901237d7b42640e_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('897ca54c-d0eb-4dfa-b446-6b2052b8cf4c', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the purpose of ''commit confirmed'' in Junos (variant 24).', '[{"id": "A", "text": "Applies configuration temporarily; automatically rolls back if not confirmed within the timeout", "is_correct": true}, {"id": "B", "text": "Displays the commit history", "is_correct": false}, {"id": "C", "text": "Commits the configuration permanently", "is_correct": false}, {"id": "D", "text": "Checks configuration syntax only", "is_correct": false}]', '''commit confirmed <minutes>'' applies the candidate config for a test period. If not confirmed with another ''commit'' within the timeout, automatic rollback occurs.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Management', 12.0, '95671ffaf280e878_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15fc438b-5609-46d4-831b-78d2cdb53f12', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 5, 'apply', 'What is the recommended approach for implementing a CI/CD pipeline for Junos configuration changes (variant 25).', '[{"id": "A", "text": "Use only SNMP for configuration", "is_correct": false}, {"id": "B", "text": "Validate configuration in a staging environment before production deployment", "is_correct": true}, {"id": "C", "text": "Use only manual CLI changes", "is_correct": false}, {"id": "D", "text": "Directly push configuration to production", "is_correct": false}]', 'Best practice: validate config in staging using tools like Ansible+PyEZ, run commit-check and commit-confirm, then promote to production.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation/"}', 'Automation Pipelines', 16.0, '1c39599214245e15_gen_v4', true) ON CONFLICT (id) DO NOTHING;
