INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e52abc4-80a8-4ff2-b5a2-03b3957ec209', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'In Junos telemetry (JTI), what is a ''sensor'' (variant 64).', '[{"id": "A", "text": "A configuration that defines which operational data to stream and how often", "is_correct": true}, {"id": "B", "text": "A SNMP trap receiver", "is_correct": false}, {"id": "C", "text": "A physical temperature sensor on the device", "is_correct": false}, {"id": "D", "text": "A syslog collector", "is_correct": false}]', 'A JTI sensor defines the data collection parameters: which operational data (e.g., interface statistics, routing table entries) to stream and the reporting interval.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Junos Telemetry', 14.0, '62fdc5049550396a_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6454d13-70ec-4ed0-aaa8-320013d25c46', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which tool is commonly used with gRPC for Junos telemetry collection (variant 64).', '[{"id": "A", "text": "JTI (Junos Telemetry Interface) collector", "is_correct": true}, {"id": "B", "text": "Syslog-ng", "is_correct": false}, {"id": "C", "text": "OpenConfig telemetry", "is_correct": false}, {"id": "D", "text": "SNMP MIB walker", "is_correct": false}]', 'JTI collector (or Junos Telemetry collector) receives streaming telemetry data via gRPC from Junos devices. OpenConfig also defines telemetry models.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Telemetry', 14.0, 'd1fa49ba288e51c1_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9d4dfa4-9181-45c0-82d5-013ee4233c22', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which Junos automation feature enables event-driven responses to system events (variant 64).', '[{"id": "A", "text": "Event scripts (commit/op scripts triggered by system events)", "is_correct": true}, {"id": "B", "text": "Manual CLI monitoring", "is_correct": false}, {"id": "C", "text": "CRON scheduler", "is_correct": false}, {"id": "D", "text": "SNMP traps", "is_correct": false}]', 'Junos event scripts are triggered by system events (interface down, BGP down, etc.) and can execute predefined automation actions to respond automatically.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation-scripts/"}', 'Event Automation', 14.0, 'ac1a12e90d6df784_gen_v4', true) ON CONFLICT (id) DO NOTHING;
