INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9209183d-14e8-485d-a544-1a84269a5789', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which tool is commonly used with gRPC for Junos telemetry collection (variant 77).', '[{"id": "A", "text": "SNMP MIB walker", "is_correct": false}, {"id": "B", "text": "Syslog-ng", "is_correct": false}, {"id": "C", "text": "OpenConfig telemetry", "is_correct": false}, {"id": "D", "text": "JTI (Junos Telemetry Interface) collector", "is_correct": true}]', 'JTI collector (or Junos Telemetry collector) receives streaming telemetry data via gRPC from Junos devices. OpenConfig also defines telemetry models.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Telemetry', 14.0, 'd6a067f2a176ca3f_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dceb2313-c4f7-4335-bf9b-7ffa2c8742d7', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which Junos automation feature enables event-driven responses to system events (variant 77).', '[{"id": "A", "text": "CRON scheduler", "is_correct": false}, {"id": "B", "text": "Event scripts (commit/op scripts triggered by system events)", "is_correct": true}, {"id": "C", "text": "Manual CLI monitoring", "is_correct": false}, {"id": "D", "text": "SNMP traps", "is_correct": false}]', 'Junos event scripts are triggered by system events (interface down, BGP down, etc.) and can execute predefined automation actions to respond automatically.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation-scripts/"}', 'Event Automation', 14.0, 'feb308354e1c886b_gen_v4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acc7d316-dcc3-406a-8aef-4caff4eeeefa', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the purpose of ''commit confirmed'' in Junos (variant 77).', '[{"id": "A", "text": "Commits the configuration permanently", "is_correct": false}, {"id": "B", "text": "Checks configuration syntax only", "is_correct": false}, {"id": "C", "text": "Applies configuration temporarily; automatically rolls back if not confirmed within the timeout", "is_correct": true}, {"id": "D", "text": "Displays the commit history", "is_correct": false}]', '''commit confirmed <minutes>'' applies the candidate config for a test period. If not confirmed with another ''commit'' within the timeout, automatic rollback occurs.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Management', 12.0, 'b455b9ae93415e12_gen_v4', true) ON CONFLICT (id) DO NOTHING;
